def get_runtime_material_order() -> List[str]:
    order = globals().get("RUNTIME_OUTPUT_MATERIAL_ORDER", None)
    if order:
        return [str(m) for m in order]
    return list(MATERIAL_ORDER)

def _normalise_material_token(value: object) -> str:
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="strict")
    return str(value)


def _positive_material_counts(
    stack_grid: Optional[np.ndarray],
    dose_grid: Optional[np.ndarray],
    *,
    source_name: str,
) -> Dict[str, int]:
    """Count positive-dose material cells in one resolved final emission grid."""
    if stack_grid is None:
        return {}
    stack = np.asarray(stack_grid)
    if stack.ndim != 3:
        raise RuntimeError(f"{source_name} stack grid must be HxWxL, got {stack.shape}")
    if dose_grid is None:
        positive = stack != "."
    else:
        dose = np.asarray(dose_grid)
        if dose.shape != stack.shape:
            raise RuntimeError(
                f"{source_name} dose grid shape {dose.shape} does not match stack grid {stack.shape}"
            )
        positive = (stack != ".") & (dose > 1e-12)
    counts: Dict[str, int] = {}
    for raw in np.unique(stack[positive]):
        material = _normalise_material_token(raw)
        counts[material] = int(np.count_nonzero(positive & (stack == raw)))
    return counts


def discover_job_material_demand(
    normal_stack_grid: np.ndarray,
    normal_dose_grid: Optional[np.ndarray],
    filter_stack_grid: Optional[np.ndarray],
    filter_dose_grid: Optional[np.ndarray],
) -> Dict[str, object]:
    """Resolve the one authoritative job-active material set before G-code emission.

    The optical tower has canonical W,F,R,Y,G,C,B slots, but material demand
    and executable lifecycle demand are separate. W is always active because the
    print has a mandatory 0.20 mm structural foundation even when no optical W
    cell is present. Every other material must occur at positive final dose in a
    resolved normal or filter grid.
    """
    canonical = list(RUNTIME_CANONICAL_TOWER_SLOT_ORDER)
    source_counts = {
        "normal": _positive_material_counts(
            normal_stack_grid, normal_dose_grid, source_name="normal"
        ),
        "filter": _positive_material_counts(
            filter_stack_grid, filter_dose_grid, source_name="filter"
        ),
    }
    demanded = {"W"}
    for counts in source_counts.values():
        demanded.update(counts)
    unknown = sorted(demanded - set(canonical))
    if unknown:
        raise RuntimeError(
            "Final planned stack names materials outside the active FC3D W/F/R/Y/G/C/B contract: "
            + ",".join(unknown)
        )
    active = [material for material in canonical if material in demanded]
    excluded = [material for material in canonical if material not in demanded]
    if not active or active[0] != "W":
        raise RuntimeError(f"Job material discovery lost mandatory structural W: active={active}")
    combined_counts = {
        material: int(sum(counts.get(material, 0) for counts in source_counts.values()))
        for material in canonical
    }
    return {
        "policy": "positive_final_dose_plus_mandatory_structural_W",
        "canonical_material_order": canonical,
        "active_materials": active,
        "excluded_materials": excluded,
        "positive_cell_counts": combined_counts,
        "source_positive_cell_counts": source_counts,
        "tower_policy": "fixed_59x44_canonical_slots_previous_active_material_filler",
    }

