def derive_pixel_head_width(rp_pitch_mm: float, print_width_mm: float) -> int:
    """Derive integer RP pixels occupied by one printed road/head width."""
    rp = float(rp_pitch_mm)
    pw = float(print_width_mm)
    if rp <= 0.0:
        raise ValueError("rp_pitch_mm must be greater than zero")
    if pw <= 0.0:
        raise ValueError("print_width_mm must be greater than zero")
    ratio = pw / rp
    n = int(round(ratio))
    if n < 1 or abs(ratio - n) > 1e-6:
        raise ValueError(
            f"print_width_mm / rp_pitch_mm must be a whole number; got {pw} / {rp} = {ratio}"
        )
    return n

# Raw H2C tool IDs are zero-based; the positions shown in Bambu Studio are
# one-based.  Current FC3D PETG production positions:
#   W=2, F(clear)=7, R=8, Y=13, G=14, C=15, B=16
# F and every chromatic material use distinct filament slots. W is assigned to
# the left physical hotend; F/R/Y/G/C/B are assigned to the right hotend.
DEFAULT_TOOL_MAP = {"W":1, "F":6, "R":7, "Y":12, "G":13, "C":14, "B":15}

# Physical installed-spool registry. Values are raw/zero-based tool IDs.
# This is deliberately separate from logical FC3D material letters so a test
# card can, for example, use logical B while physically printing PLA cyan.
INSTALLED_FILAMENT_TOOL_MAP = {
    "petg": {"W":1, "F":6, "R":7, "Y":12, "G":13, "C":14, "B":15},
    "pla":  {"W":0, "C":9, "Y":10, "M":11},
}
# Material positions encoded by the canonical reference G-code package.  These
# are identities in the *reference*, not current defaults.  Any fragment copied
# from that package must be translated by material name before it is retained.
