def _inherited_command_classification() -> Dict[str, Dict[str, str]]:
    out: Dict[str, Dict[str, str]] = {}
    for category, group in _INHERITED_COMMAND_GROUPS.items():
        for command in group["commands"]:
            if command in out:
                raise RuntimeError(f"Inherited command {command} is classified more than once")
            out[str(command)] = {
                "category": str(category),
                "purpose": str(group["purpose"]),
                "state_effect": str(group["state_effect"]),
            }
    return out


INHERITED_COMMAND_CLASSIFICATION = _inherited_command_classification()


def _embedded_template_lines(text: str) -> List[str]:
    lines = str(text).splitlines()
    if lines and lines[0] == "":
        lines = lines[1:]
    return lines


def audit_inherited_template(lines: Sequence[str], region: str) -> Dict[str, object]:
    """Require every retained executable record, form, parameter, and label to be classified."""
    if region not in EMBEDDED_INHERITED_FORM_COUNTS:
        raise RuntimeError(f"Unknown inherited template region {region!r}")
    parsed_lines = parse_gcode_lines(lines, strict=True)
    actual_forms: Dict[str, int] = {}
    classifications: Dict[str, int] = {}
    parameter_classes: Dict[str, int] = {}
    classified_parameter_count = 0
    labels: List[Dict[str, object]] = []
    for parsed in parsed_lines:
        if parsed.command is None:
            continue
        form = _parsed_form_signature(parsed)
        actual_forms[form] = int(actual_forms.get(form, 0)) + 1
        if parsed.command == "@RECORD":
            classifications["firmware_data_record_delimiter"] = int(classifications.get("firmware_data_record_delimiter", 0)) + 1
        else:
            semantic = INHERITED_COMMAND_CLASSIFICATION.get(parsed.command)
            if semantic is None:
                raise RuntimeError(
                    f"{region} line {parsed.line_number} retains unclassified command {parsed.command}: {parsed.original.strip()}"
                )
            category = semantic["category"]
            classifications[category] = int(classifications.get(category, 0)) + 1
        if parsed.payload is not None:
            # M1002 action text is an exact, hash-provenanced firmware action
            # payload.  It is never searched, edited, or passed through as an
            # opaque unknown record.
            parameter_classes["validated_firmware_action_payload_invariant"] = int(
                parameter_classes.get("validated_firmware_action_payload_invariant", 0)
            ) + 1
            classified_parameter_count += 1
        for word in parsed.words:
            label = word.placeholder
            if label is not None:
                family = str(label).split(":", 1)[0]
                parameter_class = f"typed_dynamic_{family.lower()}"
                labels.append({
                    "region": region,
                    "line": int(parsed.line_number),
                    "command": str(parsed.command),
                    "field": str(word.letter),
                    "label": str(label),
                })
            elif word.value_text is None:
                parameter_class = "validated_flag_invariant"
            elif word.numeric is not None:
                parameter_class = "validated_numeric_invariant"
            else:
                raise RuntimeError(
                    f"{region} line {parsed.line_number} has an unclassified parameter token: "
                    f"{word.original_token!r}"
                )
            parameter_classes[parameter_class] = int(parameter_classes.get(parameter_class, 0)) + 1
            classified_parameter_count += 1

    expected_forms = {str(k): int(v) for k, v in EMBEDDED_INHERITED_FORM_COUNTS[region].items()}
    if actual_forms != expected_forms:
        missing = {k: v for k, v in expected_forms.items() if actual_forms.get(k) != v}
        extra = {k: v for k, v in actual_forms.items() if expected_forms.get(k) != v}
        raise RuntimeError(f"{region} inherited command/form inventory changed; expected mismatches={missing}, actual mismatches={extra}")

    expected_labels = [
        {k: row[k] for k in ("region", "line", "command", "field", "label")}
        for row in EMBEDDED_DYNAMIC_FIELD_MANIFEST
        if row["region"] == region
    ]
    label_key = lambda row: (str(row["region"]), int(row["line"]), str(row["command"]), str(row["field"]), str(row["label"]))
    if sorted(labels, key=label_key) != sorted(expected_labels, key=label_key):
        raise RuntimeError(f"{region} typed-label manifest changed; expected={expected_labels}, actual={labels}")

    return {
        "region": str(region),
        "line_count": int(len(lines)),
        "executable_record_count": int(sum(actual_forms.values())),
        "unique_forms": int(len(actual_forms)),
        "typed_field_count": int(len(labels)),
        "form_counts": dict(sorted(actual_forms.items())),
        "classification_counts": dict(sorted(classifications.items())),
        "classified_parameter_count": int(classified_parameter_count),
        "parameter_class_counts": dict(sorted(parameter_classes.items())),
        "unclassified_command_count": 0,
        "unclassified_parameter_count": 0,
        "typed_fields": labels,
        "result": "PASS",
    }


def _format_typed_template_value(label: str, value: object) -> str:
    family = str(label).split(":", 1)[0]
    if family in ("FILAMENT_RAW", "THERMAL_HEAD", "TEMP"):
        numeric = float(value)
        if abs(numeric - round(numeric)) > 1e-9:
            raise RuntimeError(f"Typed label {label} requires an integer value, got {value!r}")
        integer = int(round(numeric))
        if family == "FILAMENT_RAW" and integer < 0:
            raise RuntimeError(f"Typed filament label {label} cannot resolve to {integer}")
        if family == "THERMAL_HEAD" and integer not in (0, 1):
            raise RuntimeError(f"Typed thermal-head label {label} must resolve to 0 or 1, got {integer}")
        return str(integer)
    numeric = float(value)
    if family == "NOZZLE":
        if numeric <= 0.0:
            raise RuntimeError(f"Typed nozzle label {label} must be positive, got {numeric}")
        return f"{numeric:.3f}".rstrip("0").rstrip(".")
    if family == "G29":
        return f"{numeric:.3f}"
    if family in ("STARTUP_PURGE", "END_Z"):
        return f"{numeric:.3f}".rstrip("0").rstrip(".")
    raise RuntimeError(f"No typed formatter is registered for template label {label}")


def render_inherited_template(
    lines: Sequence[str],
    region: str,
    typed_values: Dict[str, object],
) -> Tuple[List[str], Dict[str, object]]:
    source_audit = audit_inherited_template(lines, region)
    rendered: List[str] = []
    resolved_counts: Dict[str, int] = {}
    for parsed in parse_gcode_lines(lines, strict=True):
        replacements: Dict[int, str] = {}
        for idx, word in enumerate(parsed.words):
            label = word.placeholder
            if label is None:
                continue
            if label not in typed_values:
                raise RuntimeError(f"{region} line {parsed.line_number} has unresolved typed label {label}")
            replacements[idx] = _format_typed_template_value(label, typed_values[label])
            resolved_counts[label] = int(resolved_counts.get(label, 0)) + 1
        rendered.append(parsed.render_word_values(replacements))

    reparsed = parse_gcode_lines(rendered, strict=True)
    unresolved = [
        (p.line_number, w.placeholder)
        for p in reparsed
        for w in p.words
        if w.placeholder is not None
    ]
    if unresolved:
        raise RuntimeError(f"{region} rendered template still contains typed labels: {unresolved[:12]}")
    rendered_forms: Dict[str, int] = {}
    for parsed in reparsed:
        if parsed.command is not None:
            form = _parsed_form_signature(parsed)
            rendered_forms[form] = int(rendered_forms.get(form, 0)) + 1
    expected_forms = {str(k): int(v) for k, v in EMBEDDED_INHERITED_FORM_COUNTS[region].items()}
    if rendered_forms != expected_forms:
        raise RuntimeError(f"{region} rendering changed executable command/parameter forms")
    expected_counts: Dict[str, int] = {}
    for row in EMBEDDED_DYNAMIC_FIELD_MANIFEST:
        if row["region"] == region:
            label = str(row["label"])
            expected_counts[label] = int(expected_counts.get(label, 0)) + 1
    if resolved_counts != expected_counts:
        raise RuntimeError(f"{region} typed-label resolution counts changed: expected={expected_counts}, actual={resolved_counts}")
    audit = dict(source_audit)
    audit.update({
        "resolved_label_counts": dict(sorted(resolved_counts.items())),
        "unresolved_labels": 0,
        "rendered_reparse": "PASS",
    })
    return rendered, audit


def audit_final_parsed_gcode(lines: Sequence[str]) -> Dict[str, object]:
    """Strictly parse every final line and reject unresolved structured data."""
    command_counts: Dict[str, int] = {}
    executable = 0
    numeric_fields = 0
    flag_fields = 0
    for parsed in parse_gcode_lines(lines, strict=True):
        if parsed.command is None:
            continue
        executable += 1
        command_counts[parsed.command] = int(command_counts.get(parsed.command, 0)) + 1
        for word in parsed.words:
            if word.placeholder is not None:
                raise RuntimeError(
                    f"Final G-code line {parsed.line_number} contains unresolved label {word.placeholder}"
                )
            if word.value_text is None:
                flag_fields += 1
            elif word.numeric is None:
                raise RuntimeError(
                    f"Final G-code line {parsed.line_number} contains a non-numeric field outside a typed template"
                )
            else:
                numeric_fields += 1
    return {
        "line_count": int(len(lines)),
        "executable_record_count": int(executable),
        "numeric_field_count": int(numeric_fields),
        "flag_field_count": int(flag_fields),
        "unique_commands": int(len(command_counts)),
        "command_counts": dict(sorted(command_counts.items())),
        "unparsed_lines": 0,
        "unresolved_labels": 0,
        "result": "PASS",
    }


def audit_embedded_template_provenance() -> Dict[str, object]:
    """Reconstruct the canonical retained bytes through parsed fields and hash them."""
    results: Dict[str, object] = {}
    for region, text, count_key, hash_key in (
        ("startup", EMBEDDED_H2C_STARTUP_TEMPLATE, "startup_source_line_count", "startup_source_sha256"),
        ("shutdown", EMBEDDED_H2C_SHUTDOWN_TEMPLATE, "shutdown_source_line_count", "shutdown_source_sha256"),
    ):
        lines = _embedded_template_lines(text)
        if len(lines) != int(EMBEDDED_TEMPLATE_PROVENANCE[count_key]):
            raise RuntimeError(
                f"Embedded {region} line count changed: expected {EMBEDDED_TEMPLATE_PROVENANCE[count_key]}, got {len(lines)}"
            )
        manifest_by_key = {
            (int(row["line"]), str(row["command"]), str(row["field"]), str(row["label"])): str(row["reference_value"])
            for row in EMBEDDED_DYNAMIC_FIELD_MANIFEST
            if row["region"] == region
        }
        restored: List[str] = []
        used_keys = set()
        for parsed in parse_gcode_lines(lines, strict=True):
            replacements: Dict[int, str] = {}
            for idx, word in enumerate(parsed.words):
                label = word.placeholder
                if label is None:
                    continue
                key = (int(parsed.line_number), str(parsed.command), str(word.letter), str(label))
                if key not in manifest_by_key:
                    raise RuntimeError(f"{region} provenance has no source value for typed field {key}")
                replacements[idx] = manifest_by_key[key]
                used_keys.add(key)
            restored.append(parsed.render_word_values(replacements))
        if used_keys != set(manifest_by_key):
            missing = sorted(set(manifest_by_key) - used_keys)
            raise RuntimeError(f"{region} provenance manifest contains unused fields: {missing}")
        payload = ("\n".join(restored) + "\n").encode("utf-8")
        actual_hash = hashlib.sha256(payload).hexdigest()
        expected_hash = str(EMBEDDED_TEMPLATE_PROVENANCE[hash_key])
        if actual_hash != expected_hash:
            raise RuntimeError(f"Embedded {region} provenance hash mismatch: expected {expected_hash}, got {actual_hash}")
        results[region] = {
            "line_count": int(len(lines)),
            "sha256": actual_hash,
            "restored_typed_fields": int(len(used_keys)),
            "result": "PASS",
        }
    embedded_h2c_package_bytes()
    results["package_skeleton"] = {
        "bytes": int(EMBEDDED_TEMPLATE_PROVENANCE["embedded_package_skeleton_bytes"]),
        "sha256": str(EMBEDDED_TEMPLATE_PROVENANCE["embedded_package_skeleton_sha256"]),
        "reference_model_gcode_embedded": False,
        "result": "PASS",
    }
    results["result"] = "PASS"
    return results


def embedded_h2c_package_bytes() -> bytes:
    data = base64.b85decode(EMBEDDED_H2C_PACKAGE_B85.encode("ascii"))
    expected = str(EMBEDDED_TEMPLATE_PROVENANCE["embedded_package_skeleton_sha256"])
    actual = hashlib.sha256(data).hexdigest()
    if actual != expected:
        raise RuntimeError(f"Embedded H2C package skeleton hash mismatch: expected {expected}, got {actual}")
    with zipfile.ZipFile(io.BytesIO(data), "r") as zf:
        names = {name.lower() for name in zf.namelist()}
        if "metadata/plate_1.gcode" in names or "metadata/plate_1.gcode.md5" in names:
            raise RuntimeError("Embedded package skeleton unexpectedly contains the discarded reference model G-code")
        required = {
            "[content_types].xml",
            "3d/3dmodel.model",
            "metadata/project_settings.config",
            "metadata/model_settings.config",
            "metadata/slice_info.config",
            "metadata/plate_1.json",
            "metadata/filament_sequence.json",
        }
        missing = sorted(required - names)
        if missing:
            raise RuntimeError(f"Embedded H2C package skeleton is missing required entries: {missing}")
    return data


def validate_and_report_tool_map(tool_map: Dict[str, int], w_hotend_index: int) -> None:
    """Fail early on an unsafe map and print the human-facing slot/head audit."""
    active = ["W", "F", "R", "Y", "G", "C", "B"]
    missing = [m for m in active if m not in tool_map]
    if missing:
        raise ValueError(f"tool map is missing active FC3D materials: {','.join(missing)}")

    resolved = {m: int(tool_map[m]) for m in active}
    if any(v < 0 for v in resolved.values()):
        raise ValueError(f"tool-map raw IDs must be non-negative: {resolved}")
    if len(set(resolved.values())) != len(resolved):
        raise ValueError(f"active FC3D materials must use distinct filament positions: {resolved}")

    w_thermal = 1 if int(w_hotend_index) == 1 else 0
    colour_thermal = 1 - w_thermal
    positions = " ".join(f"{m}={resolved[m] + 1}" for m in active)
    raw_ids = " ".join(f"{m}={resolved[m]}" for m in active)
    heads = f"W=left/M104-T{w_thermal}; FRGBCY=right/M104-T{colour_thermal}"
    print(f"FC3D material positions (one-based): {positions}", flush=True)
    print(f"FC3D raw tool IDs (zero-based): {raw_ids}", flush=True)
    print(f"FC3D physical-head assignment: {heads}", flush=True)

