def polymer_profile_for_material(material):
    key = str(RUNTIME_MATERIAL_POLYMER.get(str(material).upper(), "petg")).lower()
    if key not in POLYMER_PROFILES:
        raise RuntimeError(f"Unsupported FC3D polymer profile {key!r} for material {material!r}")
    return POLYMER_PROFILES[key]


def parse_filament_assignment(value):
    """Resolve a friendly installed-filament token such as PLA:C or PETG:W.

    Returns (polymer_key, physical_colour, raw_tool_id).  The physical colour
    is intentionally independent of the logical FC3D material letter.
    """
    text = str(value).strip().replace("/", ":")
    if ":" not in text:
        raise ValueError(f"expected POLYMER:COLOUR (for example PLA:C), got {value!r}")
    polymer, colour = (x.strip() for x in text.split(":", 1))
    polymer = polymer.lower(); colour = colour.upper()
    if polymer not in INSTALLED_FILAMENT_TOOL_MAP:
        raise ValueError(f"unknown installed polymer {polymer!r}; choose PETG or PLA")
    if colour not in INSTALLED_FILAMENT_TOOL_MAP[polymer]:
        known = ",".join(INSTALLED_FILAMENT_TOOL_MAP[polymer])
        raise ValueError(f"no installed {polymer.upper()} {colour} assignment; known colours: {known}")
    return polymer, colour, int(INSTALLED_FILAMENT_TOOL_MAP[polymer][colour])

def report_installed_filament_assignments():
    for polymer in ("petg", "pla"):
        items = " ".join(f"{c}={raw+1}" for c,raw in INSTALLED_FILAMENT_TOOL_MAP[polymer].items())
        print(f"FC3D installed {polymer.upper()} positions (one-based): {items}", flush=True)

def optical_e_per_mm_for_material(material=None):
    return float(OPTICAL_LAYER_E_PER_MM if material is None else polymer_profile_for_material(material)["optical_e_per_mm"])

def polymer_cooling_commands(material):
    p = polymer_profile_for_material(material)
    out = [f"; FC3D_V1_119_POLYMER_COOLING material={str(material).upper()} polymer={RUNTIME_MATERIAL_POLYMER.get(str(material).upper(),'petg')}"]
    if p.get("part_fan_pwm") is not None:
        out.append(f"M106 S{int(p['part_fan_pwm'])} ; FC3D_V1_119_PART_FAN")
    if p.get("aux_fan_pwm") is not None:
        out.append(f"M106 P2 S{int(p['aux_fan_pwm'])} ; FC3D_V1_119_AUX_FAN")
    return out
