def print_acceleration_for_layer_height(layer_h: float) -> int:
    """Return the validated print acceleration for a generated physical layer."""
    if float(layer_h) >= BASE_H_MM - 1e-6:
        return int(FIRST_LAYER_PRINT_ACCEL_MM_S2)
    return int(NORMAL_PRINT_ACCEL_MM_S2)

def _srgb_to_lab_array(rgb: np.ndarray) -> np.ndarray:
    """Convert uint8/float sRGB array (...,3) to CIE RGB (D65)."""
    rgb = np.asarray(rgb, dtype=np.float32) / 255.0
    lin = np.where(rgb <= 0.04045, rgb / 12.92, ((rgb + 0.055) / 1.055) ** 2.4)
    M = np.array([[0.4124564, 0.3575761, 0.1804375],
                  [0.2126729, 0.7151522, 0.0721750],
                  [0.0193339, 0.1191920, 0.9503041]], dtype=np.float32)
    xyz = lin @ M.T
    xyz = xyz / np.array([0.95047, 1.00000, 1.08883], dtype=np.float32)
    eps = 216/24389
    kappa = 24389/27
    f = np.where(xyz > eps, np.cbrt(xyz), (kappa * xyz + 16) / 116)
    L = 116*f[...,1] - 16
    a = 500*(f[...,0] - f[...,1])
    b = 200*(f[...,1] - f[...,2])
    return np.stack([L,a,b], axis=-1).astype(np.float32)

class _ProgressReporter:
    """Small stderr progress helper for long PP loops.

    It avoids optional dependencies such as tqdm and keeps progress output out of
    generated files/manifests. In auto mode it prints when stderr is a TTY; in
    on mode it always prints. The caller supplies total work where known so ETA
    can be estimated.
    """
    def __init__(self, label: str, total: int | None = None, enabled: Optional[bool] = None, interval_sec: Optional[float] = None):
        if enabled is None:
            mode = str(globals().get("RUNTIME_PROGRESS", "auto")).lower()
            enabled = (mode == "on") or (mode == "auto" and bool(getattr(sys.stderr, "isatty", lambda: False)()))
        self.label = label
        self.total = int(total) if total is not None else None
        self.enabled = bool(enabled)
        self.interval_sec = float(interval_sec if interval_sec is not None else globals().get("RUNTIME_PROGRESS_INTERVAL_SEC", 2.0))
        self.start = time.time()
        self.last = 0.0
        self.last_count = 0
        if self.enabled:
            self._print(0, final=False, force=True)

    def _print(self, count: int, final: bool = False, force: bool = False):
        if not self.enabled:
            return
        now = time.time()
        if not force and not final and (now - self.last) < self.interval_sec:
            return
        elapsed = max(1e-9, now - self.start)
        rate = count / elapsed
        if self.total and self.total > 0:
            pct = 100.0 * min(count, self.total) / self.total
            remaining = max(0, self.total - count)
            eta = remaining / rate if rate > 1e-9 else 0.0
            msg = f"[{self.label}] {count:,}/{self.total:,} ({pct:5.1f}%) elapsed {elapsed:,.1f}s rate {rate:,.1f}/s ETA {eta:,.1f}s"
        else:
            msg = f"[{self.label}] {count:,} elapsed {elapsed:,.1f}s rate {rate:,.1f}/s"
        if final:
            msg += " done"
        print(msg, file=sys.stderr, flush=True)
        self.last = now
        self.last_count = count

    def update(self, count: int):
        self._print(int(count), final=False)

    def done(self, count: Optional[int] = None):
        if count is None:
            count = self.total if self.total is not None else self.last_count
        self._print(int(count), final=True, force=True)


class RecipeLookup:
    """Nearest-recipe lookup built from an offline .npz codebook.

    The .npz must contain:
      recipes: Unicode array of literal recipe strings
      lab:     Nx3 predicted Lab values (diagnostic only in ppv32)
      rgb:     Nx3 predicted RGB values
    At compile time we build a KD-tree once and query target image cells in RGB.
    """
    def __init__(self, path: Optional[Path] = None, data_bytes: Optional[bytes] = None, label: Optional[str] = None):
        if data_bytes is not None:
            self.path = Path(label or "<embedded_lut>")
            data = np.load(io.BytesIO(data_bytes), allow_pickle=True)
        else:
            if path is None:
                raise ValueError("RecipeLookup requires either path or data_bytes")
            self.path = Path(path)
            data = np.load(self.path, allow_pickle=True)
        self.metadata_json = str(data["metadata_json"]) if "metadata_json" in data else "{}"
        try:
            self.metadata = json.loads(self.metadata_json)
        except Exception:
            self.metadata = {}

        # v1.20: source-policy metadata embedded by lutmakerv3.10+.
        # These sets let strict reverse-lookup validation distinguish deliberate
        # LUT policy exclusions from unexpected missing reverse keys.
        def _npz_str_set(key: str) -> set:
            try:
                if key in data.files:
                    return {str(x) for x in np.asarray(data[key]).astype(str).reshape(-1).tolist() if str(x).strip()}
            except Exception:
                pass
            return set()
        self.source_accepted_print_keys = _npz_str_set("source_accepted_print_keys")
        self.source_rejected_print_keys = _npz_str_set("source_rejected_print_keys")
        self.source_rejected_reasons_by_key = {}
        try:
            if "source_rejected_print_keys" in data.files and "source_rejected_reasons" in data.files:
                _rk = np.asarray(data["source_rejected_print_keys"]).astype(str).reshape(-1).tolist()
                _rr = np.asarray(data["source_rejected_reasons"]).astype(str).reshape(-1).tolist()
                self.source_rejected_reasons_by_key = {str(k): str(r) for k, r in zip(_rk, _rr) if str(k).strip()}
        except Exception:
            self.source_rejected_reasons_by_key = {}

        # 3dprintv1.2: lutmakerv1.3 dose-aware cloud/grid LUTs.
        # Format contract:
        #   target_rgb[N,3] / grid_size describe the dense RGB grid.
        #   grid_top_candidate_indices[N,K] indexes into the full deployable cloud.
        #   cloud_recipe_material_codes[C,8] and cloud_recipe_doses_pct[C,8] are bottom->top.
        #   cloud_predicted_rgb[C,3] is the expected printed RGB for preview.
        # Default uses candidate rank 0 exactly as selected by lutmaker. Optional v1.3 RGB-best mode can choose the best actual predicted-RGB match from the stored top-K bucket contents.
        # lutmaker cloud/grid LUTs, including lutmakerv1.3+ and lutmakerv2.1.
        # Required contract:
        #   target_rgb[N,3]
        #   grid_top_candidate_indices[N,K]  (or compatibility alias candidate_indices)
        #   cloud_recipe_material_codes[C,8]
        #   cloud_recipe_doses_pct[C,8]
        #   cloud_predicted_rgb[C,3]
        has_grid_top = ("grid_top_candidate_indices" in data.files) or ("candidate_indices" in data.files)
        self.is_lutmaker_v13_lut = (
            "target_rgb" in data.files
            and has_grid_top
            and "cloud_recipe_material_codes" in data.files
            and "cloud_recipe_doses_pct" in data.files
            and "cloud_predicted_rgb" in data.files
        )
        if self.is_lutmaker_v13_lut:
            self.is_lutmaker_lut = True
            self.is_stack_lut = True
            self.is_demand_lut = False
            self.lutmaker_candidate_rank = int(globals().get("RUNTIME_LUT_CANDIDATE_RANK", 0))
            self.query_rgb = np.asarray(data["target_rgb"], dtype=np.float32).reshape(-1, 3)
            self.stack_lut_grid_rows = int(self.query_rgb.shape[0])
            self.stack_lut_levels = int(np.asarray(data["grid_size"]).item()) if "grid_size" in data.files else int(round(float(self.stack_lut_grid_rows) ** (1.0/3.0)))
            self.stack_lut_direct_indexable = bool(self.stack_lut_levels ** 3 == self.stack_lut_grid_rows)
            grid_top_key = "grid_top_candidate_indices" if "grid_top_candidate_indices" in data.files else "candidate_indices"
            top_idx = np.asarray(data[grid_top_key], dtype=np.int64)
            if top_idx.ndim != 2 or top_idx.shape[0] != self.stack_lut_grid_rows:
                raise RuntimeError(f"lutmaker cloud-grid {grid_top_key} must be [N,K], got {top_idx.shape}")
            if self.lutmaker_candidate_rank >= top_idx.shape[1]:
                raise RuntimeError(f"lutmakerv1.3 candidate rank {self.lutmaker_candidate_rank} unavailable; top_k={top_idx.shape[1]}")
            self.selected_recipe_index = top_idx[:, self.lutmaker_candidate_rank].astype(np.uint32, copy=False)
            self.recipe_stack_values = None
            self.recipes = np.array([], dtype=str)
            self.rgb = None if self.stack_lut_direct_indexable else self.query_rgb
            self.lab = np.zeros((0,3), dtype=np.float32)
            material_order = str(np.asarray(data["material_order"]).item()) if "material_order" in data.files else "RGBCYW"
            self.recipe_materials = list(material_order)
            self.recipe_material_id_table = list(self.recipe_materials)
            self.stack_materials = list(self.recipe_materials)
            mat_cloud = np.asarray(data["cloud_recipe_material_codes"], dtype=np.uint8)
            dose_pct_cloud = np.asarray(data["cloud_recipe_doses_pct"], dtype=np.float32)
            pred_cloud = np.asarray(data["cloud_predicted_rgb"], dtype=np.float32)
            if mat_cloud.ndim != 2 or mat_cloud.shape[1] != MIX_LAYERS:
                raise RuntimeError(f"lutmaker cloud_recipe_material_codes must be [C,{MIX_LAYERS}], got {mat_cloud.shape}")
            if dose_pct_cloud.shape != mat_cloud.shape:
                raise RuntimeError(f"lutmaker cloud_recipe_doses_pct shape {dose_pct_cloud.shape} does not match material codes {mat_cloud.shape}")
            if pred_cloud.ndim != 2 or pred_cloud.shape[0] != mat_cloud.shape[0] or pred_cloud.shape[1] != 3:
                raise RuntimeError(f"lutmaker cloud_predicted_rgb must be [C,3], got {pred_cloud.shape}")
            if len(self.selected_recipe_index) and int(np.max(self.selected_recipe_index)) >= mat_cloud.shape[0]:
                raise RuntimeError(f"lutmaker {grid_top_key} references outside cloud_recipe_material_codes")
            self.recipe_stack_material_id = mat_cloud.astype(np.uint8, copy=False)
            # Continuous variable extrusion dose.  No low-dose halftone conversion here.
            self.recipe_stack_dose = (dose_pct_cloud.astype(np.float32, copy=False) / 100.0).astype(np.float32, copy=False)
            self.recipe_pred_rgb = pred_cloud.astype(np.float32, copy=False)
            # 3dprintv1.27: Lab selector support.  The LUT stores print-space RGB
            # predictions; convert those RGB triplets to CIE Lab once and use the
            # same conversion for source/target RGB during selection.
            self.recipe_pred_lab = (
                np.asarray(data["cloud_predicted_lab"], dtype=np.float32)
                if "cloud_predicted_lab" in data.files
                else _srgb_to_lab_array(self.recipe_pred_rgb)
            )
            self.multi_recipe_index = top_idx.astype(np.int64, copy=False)
            self.cloud_is_exact_measured = (
                np.asarray(data["cloud_is_exact_measured"], dtype=np.uint8)
                if "cloud_is_exact_measured" in data.files
                else np.zeros(mat_cloud.shape[0], dtype=np.uint8)
            )
            if self.cloud_is_exact_measured.shape != (mat_cloud.shape[0],):
                raise RuntimeError("cloud_is_exact_measured must have one row per cloud recipe")
            self.cloud_exact_measured_index = (
                np.asarray(data["cloud_exact_measured_index"], dtype=np.int64)
                if "cloud_exact_measured_index" in data.files
                else np.full(mat_cloud.shape[0], -1, dtype=np.int64)
            )
            self.existing_history_bonus_de = float(
                np.asarray(data["existing_history_bonus_de"]).item()
            ) if "existing_history_bonus_de" in data.files else 0.0
            self.existing_history_bonus_scale_de = float(
                np.asarray(data["existing_history_bonus_scale_de"]).item()
            ) if "existing_history_bonus_scale_de" in data.files else 3.0
            self.generated_ve_penalty_de = float(
                np.asarray(data["generated_ve_penalty_de"]).item()
            ) if "generated_ve_penalty_de" in data.files else 0.0
            self.generated_ve_penalty_scale = float(
                np.asarray(data["generated_ve_penalty_scale"]).item()
            ) if "generated_ve_penalty_scale" in data.files else 30.0
            self.multi_recipe_total_ve_movement = None
            if "grid_top_total_ve_movement" in data.files:
                _gtv = np.asarray(data["grid_top_total_ve_movement"], dtype=np.float32)
                self.multi_recipe_total_ve_movement = _gtv if _gtv.shape == top_idx.shape else None
            self.multi_recipe_parent_history_index = None
            if "grid_top_parent_history_index" in data.files:
                _gpi = np.asarray(data["grid_top_parent_history_index"], dtype=np.int64)
                self.multi_recipe_parent_history_index = _gpi if _gpi.shape == top_idx.shape else None
            delta_key = "grid_top_delta_e76" if "grid_top_delta_e76" in data.files else ("candidate_delta_e76" if "candidate_delta_e76" in data.files else None)
            score_key = "grid_top_score" if "grid_top_score" in data.files else ("candidate_score" if "candidate_score" in data.files else None)
            self.multi_recipe_error_lab = np.asarray(data[delta_key], dtype=np.float32) if delta_key else None
            self.multi_recipe_score = np.asarray(data[score_key], dtype=np.float32) if score_key else None
            # 3dprintv1.37: optional recipe-space support-distance2 arrays.
            # lutmakerv4.6 writes cloud_support_distance and the already-weighted
            # cloud_support_distance2_penalty used by the LUT scorer.  Older test
            # builds may contain unweighted cloud_support_d2/grid_top_support_d2.
            self.cloud_support_distance = np.asarray(data["cloud_support_distance"], dtype=np.float32) if "cloud_support_distance" in data.files else None
            self.cloud_support_distance2_penalty = np.asarray(data["cloud_support_distance2_penalty"], dtype=np.float32) if "cloud_support_distance2_penalty" in data.files else None
            self.cloud_support_d2 = np.asarray(data["cloud_support_d2"], dtype=np.float32) if "cloud_support_d2" in data.files else None
            self.support_distance2_mode = str(np.asarray(data["support_distance2_mode"]).item()) if "support_distance2_mode" in data.files else ""
            self.support_distance2_weight = float(np.asarray(data["support_distance2_weight"]).item()) if "support_distance2_weight" in data.files else 0.0
            self.support_distance2_scale_used = float(np.asarray(data["support_distance2_scale_used"]).item()) if "support_distance2_scale_used" in data.files else 0.0
            # 3dprintv1.38: lutmakerv4.7 can declare the active colour-distance
            # metric used to rank LUT buckets.  For Lab LUTs, print-time bucket
            # re-selection must also use CIE Lab DeltaE76, not RGB distance.
            self.colour_distance_mode = str(np.asarray(data["colour_distance_mode"]).item()) if "colour_distance_mode" in data.files else "rgb2"
            self.colour_distance_metric = str(np.asarray(data["colour_distance_metric"]).item()) if "colour_distance_metric" in data.files else ("lab_deltae76" if self.colour_distance_mode.lower().strip() in ("lab", "deltae", "deltae76", "lab_deltae76") else "rgb_squared")
            if "grid_top_support_distance2_penalty" in data.files:
                _gsp = np.asarray(data["grid_top_support_distance2_penalty"], dtype=np.float32)
                self.multi_recipe_support_distance2_penalty = _gsp if _gsp.shape == top_idx.shape else None
            else:
                self.multi_recipe_support_distance2_penalty = None
            if "grid_top_support_d2" in data.files:
                _gsd2 = np.asarray(data["grid_top_support_d2"], dtype=np.float32)
                self.multi_recipe_support_d2 = _gsd2 if _gsd2.shape == top_idx.shape else None
            else:
                self.multi_recipe_support_d2 = None
            self.multi_recipe_count = int(top_idx.shape[1])
            self.selected_demand_units = None
            self.selected_stack_values = None
            self.selected_candidate_index = self.selected_recipe_index
            self.candidate_packed_stack_json = None
            self.candidate_demand_units = None
            self.candidate_pred_rgb = None
            self.candidate_pred_lab = None
            self.multi_candidate_index = self.multi_recipe_index
            self.multi_candidate_error_lab = self.multi_recipe_error_lab
            self.multi_candidate_score = self.multi_recipe_score
            self.multi_candidate_count = int(top_idx.shape[1])
            self.demand_materials = []
            lutmaker_script_version = str(np.asarray(data["script_version"]).item()) if "script_version" in data.files else "lutmaker_cloud_grid"
            lutmaker_model_name = str(np.asarray(data["model_name"]).item()) if "model_name" in data.files else "doseaware_cloud_grid"
            self.lut_kind = "lutmaker_doseaware_cloud_grid"
            self.modern_exact_stack_lut = True
            self.recipe_policy_filter = {}
            dose_vals = dose_pct_cloud[np.isfinite(dose_pct_cloud)]
            self.metadata.update({
                "lut_kind": self.lut_kind,
                "script_version": lutmaker_script_version,
                "model_name": lutmaker_model_name,
                "grid_top_key": grid_top_key,
                "grid_delta_key": delta_key or "",
                "grid_score_key": score_key or "",
                "grid_size": int(self.stack_lut_levels),
                "top_k": int(top_idx.shape[1]),
                "cloud_recipe_count": int(mat_cloud.shape[0]),
                "material_order": material_order,
                "layer_order": str(np.asarray(data["layer_order"]).item()) if "layer_order" in data.files else "bottom_to_top",
                "hierarchical_parent_grid": int(np.asarray(data["hierarchical_parent_grid"]).item()) if "hierarchical_parent_grid" in data.files else 0,
                "hierarchical_parent_top_k": int(np.asarray(data["hierarchical_parent_top_k"]).item()) if "hierarchical_parent_top_k" in data.files else 0,
                "hierarchical_parent_lut": str(np.asarray(data["hierarchical_parent_lut"]).item()) if "hierarchical_parent_lut" in data.files else "",
                "dose_mode": "continuous_extrusion_multiplier_from_cloud_recipe_doses_pct",
                "dose_pct_min": float(np.min(dose_vals)) if dose_vals.size else 0.0,
                "dose_pct_max": float(np.max(dose_vals)) if dose_vals.size else 0.0,
                "low_dose_halftone": "disabled_for_lutmakerv1.3_path",
                "hybrid_speed_ve": "disabled",
            })
            self.metadata_json = json.dumps(self.metadata, sort_keys=True)
            self.forward_predictor = None
            self.forward_predictor_report = {"available": False, "reason": "not_checked"}
            try:
                import importlib
                requested_predictor_module = str(np.asarray(data["predictor_module"]).item()) if "predictor_module" in data.files else "fc3d_predictorv1"
                if requested_predictor_module not in ("fc3d_predictorv1", "fc3d_predictorv2"):
                    requested_predictor_module = "fc3d_predictorv1"
                _fc3d_pred = importlib.import_module(requested_predictor_module)
                if _fc3d_pred.npz_has_predictor(data):
                    self.forward_predictor = _fc3d_pred.load_predictor_bundle(data)
                    self.forward_predictor_report = {
                        "available": True,
                        "module": requested_predictor_module,
                        "feature_encoding_version": str(self.forward_predictor.feature_encoding_version),
                        "model_name": str(self.forward_predictor.model_name),
                    }
                    self.metadata["forward_predictor"] = self.forward_predictor_report
                else:
                    self.forward_predictor_report = {"available": False, "reason": "lut_has_no_predictor_bundle"}
            except Exception as e:
                self.forward_predictor = None
                self.forward_predictor_report = {"available": False, "reason": f"load_failed: {e}"}

            if self.stack_lut_direct_indexable:
                self.tree = None
                self.rgb_tree = None
                self._mode = f"direct-rgb-cube lutmaker cloud-grid levels={self.stack_lut_levels} candidate_rank={self.lutmaker_candidate_rank} cloud={mat_cloud.shape[0]} script={lutmaker_script_version}"
            else:
                try:
                    from scipy.spatial import cKDTree
                    self.tree = cKDTree(self.query_rgb)
                    self.rgb_tree = self.tree
                    self._mode = f"scipy.cKDTree lutmaker cloud-grid script={lutmaker_script_version}"
                except Exception:
                    self.tree = None
                    self.rgb_tree = None
                    self._mode = f"chunked-bruteforce lutmaker cloud-grid script={lutmaker_script_version}"
            return

        # 3dprintv1.0: lutmakerv1.0 hybrid LUTs.
        # Format contract:
        #   target_rgb[N,3] -> candidate_recipe_codes[N,K,8] bottom->top
        #   candidate_predicted_rgb[N,K,3] is the expected printed RGB for preview.
        # Default uses candidate rank 0 exactly as selected by lutmaker. Optional v1.3 RGB-best mode can choose the best actual predicted-RGB match from the stored top-K bucket contents.
        self.is_lutmaker_lut = (
            "target_rgb" in data.files
            and "candidate_recipe_codes" in data.files
            and "candidate_predicted_rgb" in data.files
        )
        if self.is_lutmaker_lut:
            self.is_stack_lut = True
            self.is_demand_lut = False
            self.lutmaker_candidate_rank = 0
            self.query_rgb = np.asarray(data["target_rgb"], dtype=np.float32).reshape(-1, 3)
            self.stack_lut_grid_rows = int(self.query_rgb.shape[0])
            self.stack_lut_levels = int(np.asarray(data["grid_size"]).item()) if "grid_size" in data.files else int(round(float(self.stack_lut_grid_rows) ** (1.0/3.0)))
            self.stack_lut_direct_indexable = bool(self.stack_lut_levels ** 3 == self.stack_lut_grid_rows)
            self.selected_recipe_index = np.arange(self.stack_lut_grid_rows, dtype=np.uint32)
            self.recipe_stack_values = None
            self.recipes = np.array([], dtype=str)
            self.rgb = None if self.stack_lut_direct_indexable else self.query_rgb
            self.lab = np.zeros((0,3), dtype=np.float32)
            material_order = str(np.asarray(data["material_order"]).item()) if "material_order" in data.files else "RGBCYW"
            self.recipe_materials = list(material_order)
            self.recipe_material_id_table = ["."] + list(self.recipe_materials)
            self.stack_materials = list(self.recipe_materials)
            codes_all = np.asarray(data["candidate_recipe_codes"], dtype=np.uint8)
            pred_all = np.asarray(data["candidate_predicted_rgb"], dtype=np.float32)
            if codes_all.ndim != 3 or codes_all.shape[0] != self.stack_lut_grid_rows or codes_all.shape[2] != MIX_LAYERS:
                raise RuntimeError(f"lutmakerv1.0 candidate_recipe_codes must be [N,K,{MIX_LAYERS}], got {codes_all.shape}")
            if pred_all.ndim != 3 or pred_all.shape[0] != self.stack_lut_grid_rows or pred_all.shape[2] != 3:
                raise RuntimeError(f"lutmakerv1.0 candidate_predicted_rgb must be [N,K,3], got {pred_all.shape}")
            if self.lutmaker_candidate_rank >= codes_all.shape[1]:
                raise RuntimeError(f"lutmakerv1.0 candidate rank {self.lutmaker_candidate_rank} unavailable; top_k={codes_all.shape[1]}")
            self.recipe_stack_material_id = codes_all[:, self.lutmaker_candidate_rank, :].astype(np.uint8, copy=False)
            self.recipe_stack_dose = np.ones_like(self.recipe_stack_material_id, dtype=np.float32)
            self.recipe_pred_rgb = pred_all[:, self.lutmaker_candidate_rank, :].astype(np.float32, copy=False)
            self.recipe_pred_lab = None
            self.multi_recipe_index = None
            self.multi_recipe_error_lab = None
            self.multi_recipe_score = None
            self.multi_recipe_count = int(codes_all.shape[1])
            self.selected_demand_units = None
            self.selected_stack_values = None
            self.selected_candidate_index = None
            self.candidate_packed_stack_json = None
            self.candidate_demand_units = None
            self.candidate_pred_rgb = pred_all
            self.candidate_pred_lab = None
            self.multi_candidate_index = None
            self.multi_candidate_error_lab = np.asarray(data["candidate_delta_e76"], dtype=np.float32) if "candidate_delta_e76" in data.files else None
            self.multi_candidate_score = np.asarray(data["candidate_score"], dtype=np.float32) if "candidate_score" in data.files else None
            self.multi_candidate_count = int(codes_all.shape[1])
            self.demand_materials = []
            self.lut_kind = "lutmakerv1.0_hybrid_rgb_to_recipe_stack"
            self.modern_exact_stack_lut = True
            self.recipe_policy_filter = {}
            self.metadata.update({
                "lut_kind": self.lut_kind,
                "script_version": str(np.asarray(data["script_version"]).item()) if "script_version" in data.files else "lutmakerv1.0",
                "model_name": str(np.asarray(data["model_name"]).item()) if "model_name" in data.files else "hybrid",
                "grid_size": int(self.stack_lut_levels),
                "top_k": int(codes_all.shape[1]),
                "material_order": material_order,
                "layer_order": str(np.asarray(data["layer_order"]).item()) if "layer_order" in data.files else "bottom_to_top",
            })
            self.metadata_json = json.dumps(self.metadata, sort_keys=True)
            if self.stack_lut_direct_indexable:
                self.tree = None
                self.rgb_tree = None
                self._mode = f"direct-rgb-cube lutmakerv1.0 hybrid levels={self.stack_lut_levels} candidate_rank={self.lutmaker_candidate_rank}"
            else:
                try:
                    from scipy.spatial import cKDTree
                    self.tree = cKDTree(self.query_rgb)
                    self.rgb_tree = self.tree
                    self._mode = "scipy.cKDTree lutmakerv1.0 hybrid"
                except Exception:
                    self.tree = None
                    self.rgb_tree = None
                    self._mode = "chunked-bruteforce lutmakerv1.0 hybrid"
            return

        # PPSPV34: recipegenv64 stack LUTs are the only supported active path.
        # They store RGB query grid -> selected_recipe_index -> exact printable recipe_stack_values.
        self.is_stack_lut = ("selected_recipe_index" in data.files and "recipe_stack_values" in data.files)
        self.is_demand_lut = False
        if not self.is_stack_lut:
            raise RuntimeError("PPSPV34 requires a recipegenv64 stack LUT with selected_recipe_index and recipe_stack_values; legacy literal/demand LUTs were removed from the PSP branch.")

        self.recipes = np.array([], dtype=str)
        self.selected_recipe_index = np.asarray(data["selected_recipe_index"], dtype=np.uint32)
        self.recipe_stack_values = np.asarray(data["recipe_stack_values"], dtype=np.uint16)
        self.stack_lut_grid_rows = int(self.selected_recipe_index.shape[0])
        inferred_levels = int(round(float(self.stack_lut_grid_rows) ** (1.0/3.0)))
        self.stack_lut_levels = inferred_levels if inferred_levels ** 3 == self.stack_lut_grid_rows else None
        self.stack_lut_direct_indexable = self.stack_lut_levels is not None
        self.query_rgb = None if self.stack_lut_direct_indexable else (np.asarray(data["grid_rgb"], dtype=np.float32) if "grid_rgb" in data.files else None)
        self.rgb = None if self.stack_lut_direct_indexable else (np.asarray(data["selected_pred_rgb"], dtype=np.float32) if "selected_pred_rgb" in data.files else self.query_rgb)
        self.lab = np.asarray(data["recipe_pred_lab"], dtype=np.float32) if "recipe_pred_lab" in data.files else np.zeros((0,3), dtype=np.float32)
        self.recipe_stack_material_id = np.asarray(data["recipe_stack_material_id"], dtype=np.uint8) if "recipe_stack_material_id" in data.files else None
        self.recipe_stack_dose = np.asarray(data["recipe_stack_dose"], dtype=np.float32) if "recipe_stack_dose" in data.files else None
        self.recipe_materials = [str(x) for x in np.asarray(data["recipe_materials"]).tolist()] if "recipe_materials" in data.files else ["R","G","B","C","Y","W","F"]
        self.recipe_material_id_table = [str(x) for x in np.asarray(data["recipe_material_id_table"]).tolist()] if "recipe_material_id_table" in data.files else ["."] + list(self.recipe_materials)
        self.recipe_pred_rgb = np.asarray(data["recipe_pred_rgb"], dtype=np.float32) if "recipe_pred_rgb" in data.files else None
        self.recipe_pred_lab = np.asarray(data["recipe_pred_lab"], dtype=np.float32) if "recipe_pred_lab" in data.files else None
        self.multi_recipe_index = None
        self.multi_recipe_error_lab = None
        self.multi_recipe_score = None
        self.multi_recipe_count = 1
        self.selected_demand_units = None
        self.selected_stack_values = None
        self.selected_candidate_index = None
        self.candidate_packed_stack_json = None
        self.candidate_demand_units = None
        self.candidate_pred_rgb = None
        self.candidate_pred_lab = None
        self.multi_candidate_index = None
        self.multi_candidate_error_lab = None
        self.multi_candidate_score = None
        self.multi_candidate_count = 1
        self.demand_materials = []
        self.stack_materials = list(self.recipe_materials)
        self.lut_kind = str(self.metadata.get("lut_kind", "fc3d_rgb_to_printable_recipe_stack_v1"))
        self.modern_exact_stack_lut = True
        _cg = self.metadata.get("candidate_generation", {}) if isinstance(self.metadata, dict) else {}
        self.recipe_policy_filter = _cg.get("recipe_policy_filter", {}) if isinstance(_cg, dict) else {}
        if not self.stack_lut_direct_indexable:
            if self.query_rgb is None:
                raise RuntimeError("Stack LUT is not a dense RGB cube and does not contain grid_rgb for fallback lookup")
            if self.selected_recipe_index.shape[0] != self.query_rgb.shape[0]:
                raise RuntimeError(f"Stack LUT selected_recipe_index length {self.selected_recipe_index.shape[0]} does not match grid_rgb rows {self.query_rgb.shape[0]}")

        if getattr(self, "is_stack_lut", False) and getattr(self, "stack_lut_direct_indexable", False):
            self.tree = None
            self.rgb_tree = None
            self._mode = f"direct-rgb-cube stack levels={self.stack_lut_levels}"
        else:
            try:
                from scipy.spatial import cKDTree
                self.tree = cKDTree(self.query_rgb) if self.query_rgb is not None else None
                self.rgb_tree = self.tree
                self._mode = "scipy.cKDTree stack"
            except Exception:
                self.tree = None
                self.rgb_tree = None
                self._mode = "chunked-bruteforce stack"

    def _lookup_space(self) -> str:
        # ppv41: RGB-only lookup. Lab arrays may still exist in old LUTs for
        # diagnostics, but pp no longer uses them for recipe choice.
        if self.rgb is None:
            raise RuntimeError("RGB-only lookup requires LUT rgb array")
        return "rgb"

    def _nearest_indices_rgb_batch(self, rgbs: np.ndarray) -> np.ndarray:
        """Return nearest LUT indices by stored RGB Euclidean distance."""
        if self.rgb is None:
            raise RuntimeError("Recipe LUT does not contain predicted rgb array")
        rgbs = np.asarray(rgbs, dtype=np.float32).reshape(-1, 3)
        if getattr(self, "rgb_tree", None) is not None:
            _dist, idx = self.rgb_tree.query(rgbs, k=1)
            return np.asarray(idx, dtype=np.int64)
        out = np.empty((len(rgbs),), dtype=np.int64)
        for row, target in enumerate(rgbs):
            best_i = 0; best_d = float("inf")
            for start in range(0, len(self.rgb), 65536):
                block = self.rgb[start:start+65536]
                d = np.sum((block - target) ** 2, axis=1)
                j = int(np.argmin(d))
                if float(d[j]) < best_d:
                    best_d = float(d[j]); best_i = start + j
            out[row] = best_i
        return out

    def _candidate_indices_rgb_batch(self, rgbs: np.ndarray, k: int = 1) -> Tuple[np.ndarray, np.ndarray]:
        """Return (RGB distances, LUT indices) for k nearest candidates by stored RGB."""
        if self.rgb is None:
            raise RuntimeError("Recipe LUT does not contain predicted rgb array")
        k = max(1, int(k))
        rgbs = np.asarray(rgbs, dtype=np.float32).reshape(-1, 3)
        if getattr(self, "rgb_tree", None) is not None:
            d, idx = self.rgb_tree.query(rgbs, k=min(k, len(self.rgb)))
            d = np.asarray(d, dtype=np.float32)
            idx = np.asarray(idx, dtype=np.int64)
            if d.ndim == 1:
                d = d[:, None]; idx = idx[:, None]
            return d, idx
        all_d = np.empty((len(rgbs), k), dtype=np.float32)
        all_i = np.empty((len(rgbs), k), dtype=np.int64)
        for row, target in enumerate(rgbs):
            best_d2 = np.full((k,), np.inf, dtype=np.float32)
            best_i = np.full((k,), 0, dtype=np.int64)
            for start in range(0, len(self.rgb), 65536):
                block = self.rgb[start:start+65536]
                d2 = np.sum((block - target) ** 2, axis=1)
                take = min(k, len(d2))
                cand = np.argpartition(d2, take-1)[:take]
                cat_d2 = np.concatenate([best_d2, d2[cand]])
                cat_i = np.concatenate([best_i, start + cand])
                keep = np.argsort(cat_d2)[:k]
                best_d2 = cat_d2[keep].astype(np.float32)
                best_i = cat_i[keep].astype(np.int64)
            all_d[row] = np.sqrt(best_d2).astype(np.float32)
            all_i[row] = best_i
        return all_d, all_i

    def nearest_index_for_rgb(self, rgb: Tuple[int,int,int]) -> int:
        return int(self._nearest_indices_rgb_batch(np.array([[rgb[0], rgb[1], rgb[2]]], dtype=np.float32))[0])


    def nearest_indices_batch(self, rgbs: np.ndarray) -> np.ndarray:
        """Return LUT row indices by stored RGB/direct stack lookup."""
        rgbs = np.asarray(rgbs, dtype=np.float32).reshape(-1, 3)
        if getattr(self, "is_stack_lut", False):
            return self.nearest_stack_indices_batch(rgbs)
        return self._nearest_indices_rgb_batch(np.clip(rgbs, 0, 255))

    def nearest_rgb_batch(self, rgbs: np.ndarray) -> np.ndarray:
        """Return predicted print RGB for an array of target RGBs using the same lookup as printing."""
        if getattr(self, "is_stack_lut", False):
            idx = self.nearest_stack_indices_batch(rgbs)
            return self.predicted_rgb_for_indices(idx)
        if self.rgb is None:
            raise RuntimeError("Recipe LUT does not contain predicted rgb array; cannot render preview image")
        idx = self.nearest_indices_batch(rgbs)
        return np.asarray(self.rgb[idx], dtype=np.float32)

    def _direct_stack_indices_from_rgb(self, rgbs: np.ndarray) -> np.ndarray:
        """Direct dense-cube RGB -> LUT row index for recipegenv64 stack LUTs.

        v64 writes grid_rgb in r-major order:
          index = r_level * levels^2 + g_level * levels + b_level
        For 8-bit LUTs this is exact round-to-byte direct lookup, avoiding the
        old grid_rgb/selected_pred_rgb staging tables and all brute-force search.
        """
        if not getattr(self, "stack_lut_direct_indexable", False):
            raise RuntimeError("direct stack LUT indexing requested for a non-dense LUT")
        levels = int(self.stack_lut_levels)
        q = np.asarray(rgbs, dtype=np.float32).reshape(-1, 3)
        q = np.clip(q, 0.0, 255.0)
        if levels == 256:
            lvl = np.rint(q).astype(np.int64)
        else:
            lvl = np.rint(q * float(levels - 1) / 255.0).astype(np.int64)
        lvl = np.clip(lvl, 0, levels - 1)
        return (lvl[:, 0] * (levels * levels) + lvl[:, 1] * levels + lvl[:, 2]).astype(np.int64)

    def nearest_stack_indices_batch(self, rgbs: np.ndarray) -> np.ndarray:
        """Return nearest grid-row indices for a recipegenv64 stack LUT."""
        if not getattr(self, "is_stack_lut", False):
            raise RuntimeError("nearest_stack_indices_batch requires a recipegenv64 stack LUT")
        rgbs = np.asarray(rgbs, dtype=np.float32).reshape(-1, 3)
        if getattr(self, "stack_lut_direct_indexable", False):
            return self._direct_stack_indices_from_rgb(rgbs)
        q = np.clip(rgbs, 0, 255)
        if getattr(self, "rgb_tree", None) is not None:
            _dist, idx = self.rgb_tree.query(q, k=1)
            return np.asarray(idx, dtype=np.int64)
        out = np.empty((len(q),), dtype=np.int64)
        for row, target in enumerate(q):
            best_i = 0; best_d = float("inf")
            for start in range(0, len(self.query_rgb), 65536):
                block = self.query_rgb[start:start+65536]
                d = np.sum((block - target) ** 2, axis=1)
                j = int(np.argmin(d))
                if float(d[j]) < best_d:
                    best_d = float(d[j]); best_i = start + j
            out[row] = best_i
        return out

    def recipe_index_for_grid_index(self, idx: int) -> int:
        if not getattr(self, "is_stack_lut", False):
            raise RuntimeError("recipe_index_for_grid_index requires a stack LUT")
        return int(np.asarray(self.selected_recipe_index)[int(idx)])

    def recipe_stack_for_recipe_index(self, recipe_idx: int) -> tuple[np.ndarray, np.ndarray]:
        """Return (material_chars, dose) for a unique recipe index."""
        if not getattr(self, "is_stack_lut", False):
            raise RuntimeError("recipe_stack_for_recipe_index requires a stack LUT")
        recipe_idx = int(recipe_idx)
        if getattr(self, "is_lutmaker_lut", False):
            codes = np.asarray(self.recipe_stack_material_id[recipe_idx], dtype=np.int64)
            mats = np.asarray([self.recipe_materials[int(c)] if 0 <= int(c) < len(self.recipe_materials) else EMPTY_MAT for c in codes], dtype='<U1')
            if self.recipe_stack_dose is not None:
                dose = np.asarray(self.recipe_stack_dose[recipe_idx], dtype=np.float32)
            else:
                dose = np.ones((len(mats),), dtype=np.float32)
            mats = np.where(dose > 0, mats, EMPTY_MAT).astype('<U1')
            return mats, dose.astype(np.float32)
        if self.recipe_stack_material_id is not None and self.recipe_stack_dose is not None:
            ids = np.asarray(self.recipe_stack_material_id[recipe_idx], dtype=np.int64)
            dose = np.asarray(self.recipe_stack_dose[recipe_idx], dtype=np.float32)
            mats = np.asarray([self.recipe_material_id_table[int(i)] if 0 <= int(i) < len(self.recipe_material_id_table) else EMPTY_MAT for i in ids], dtype='<U1')
            mats = np.where(dose > 0, mats, EMPTY_MAT).astype('<U1')
            return mats, dose.astype(np.float32)
        vals = np.asarray(self.recipe_stack_values[recipe_idx], dtype=np.uint16)
        max_units = np.max(vals, axis=1).astype(np.float32)
        arg = np.argmax(vals, axis=1)
        mats = np.asarray([self.recipe_materials[int(i)] if max_units[row] > 0 else EMPTY_MAT for row, i in enumerate(arg)], dtype='<U1')
        dose = (max_units / 1024.0).astype(np.float32)
        return mats, dose

    def predicted_rgb_for_recipe_indices(self, recipe_idx: np.ndarray) -> np.ndarray:
        if self.recipe_pred_rgb is None:
            raise RuntimeError("predicted_rgb_for_recipe_indices requires recipe_pred_rgb")
        return np.asarray(self.recipe_pred_rgb[np.asarray(recipe_idx, dtype=np.int64)], dtype=np.float32)

    def calibrated_predict_rgb_for_material_dose(self, material_codes: np.ndarray, doses_pct: np.ndarray) -> np.ndarray:
        """Predict RGB for exact bottom-to-top stacks using the shared lutmaker forward model."""
        pred = getattr(self, "forward_predictor", None)
        if pred is None:
            raise RuntimeError(f"LUT {self.path} has no shared forward predictor bundle; rebuild with lutmakerv2.6+")
        return pred.predict_material_dose(material_codes, doses_pct)

    def select_recipe_indices_for_grid_targets(self, grid_idx: np.ndarray, target_rgb: np.ndarray, mode: str = "prime", candidate_count: int = 32) -> Tuple[np.ndarray, np.ndarray, Dict[str, object]]:
        """Select cloud recipe indices for already-quantised RGB grid rows.

        For lutmakerv1.3/v1.4 cloud-grid LUTs, each grid bucket stores top-K
        candidate recipe indices.  prime/rank mode returns the configured rank.
        rgb-best mode checks the stored bucket contents against the actual
        averaged source RGB and chooses the candidate with the smallest predicted
        RGB distance.  This does not invent new recipes or doses; it only chooses
        among lutmaker-approved bucket candidates.
        """
        grid_idx = np.asarray(grid_idx, dtype=np.int64).reshape(-1)
        target_rgb = np.asarray(target_rgb, dtype=np.float32).reshape(-1, 3)
        mode_l = str(mode or "prime").lower().strip()
        if grid_idx.shape[0] != target_rgb.shape[0]:
            raise ValueError("grid_idx and target_rgb row counts differ")
        # Legacy stack LUTs or explicit prime mode: return existing rank.
        if not getattr(self, "is_lutmaker_v13_lut", False) or mode_l in ("prime", "rank", "off", "0", "false", "none"):
            recipe_idx = np.asarray(self.selected_recipe_index[grid_idx], dtype=np.int64)
            pred = self.predicted_rgb_for_recipe_indices(recipe_idx)
            report = {
                "enabled": False,
                "mode": mode_l,
                "candidate_rank": int(getattr(self, "lutmaker_candidate_rank", 0)),
                "candidate_count_requested": int(candidate_count),
                "candidate_count_used": 1,
                "reason": "prime/rank mode or non-cloud-grid LUT",
            }
            return recipe_idx, pred, report
        if mode_l in ("direct-cloud-rgb", "direct_cloud_rgb", "cloud-rgb", "cloud_rgb", "direct-rgb", "direct_rgb", "direct-cloud-lab", "direct_cloud_lab", "cloud-lab", "cloud_lab", "direct-lab", "direct_lab"):
            use_lab = mode_l in ("direct-cloud-lab", "direct_cloud_lab", "cloud-lab", "cloud_lab", "direct-lab", "direct_lab")
            if self.recipe_pred_rgb is None:
                raise RuntimeError("direct-cloud-rgb/lab requires cloud recipe_pred_rgb / cloud_predicted_rgb")
            cloud_rgb = np.asarray(self.recipe_pred_rgb, dtype=np.float32).reshape(-1, 3)
            if cloud_rgb.shape[0] <= 0:
                raise RuntimeError("direct-cloud-rgb/lab found an empty recipe cloud")
            if use_lab:
                cloud_metric = np.asarray(getattr(self, "recipe_pred_lab", None), dtype=np.float32).reshape(-1, 3)
                if cloud_metric.shape[0] != cloud_rgb.shape[0]:
                    cloud_metric = _srgb_to_lab_array(cloud_rgb)
                target_metric = _srgb_to_lab_array(target_rgb)
                metric_name = "CIE_Lab_D65_Euclidean_deltaE76"
            else:
                cloud_metric = cloud_rgb
                target_metric = target_rgb
                metric_name = "RGB_Euclidean"
            n = int(target_rgb.shape[0])
            best_i = np.zeros((n,), dtype=np.int64)
            best_d2 = np.full((n,), np.inf, dtype=np.float32)
            # Keep memory bounded: 2048 x 3366 x 3 float32 is about 83 MB for the diff array.
            row_chunk = int(globals().get("RUNTIME_DIRECT_CLOUD_RGB_ROW_CHUNK", 2048))
            row_chunk = max(128, row_chunk)
            for start in range(0, n, row_chunk):
                end = min(n, start + row_chunk)
                diff = cloud_metric[None, :, :] - target_metric[start:end, None, :]
                d2 = np.sum(diff * diff, axis=2)
                j = np.argmin(d2, axis=1).astype(np.int64)
                best_i[start:end] = j
                best_d2[start:end] = d2[np.arange(end - start), j].astype(np.float32)
            recipe_idx = best_i.astype(np.int64)
            pred_best = cloud_rgb[recipe_idx].astype(np.float32)
            best_d = np.sqrt(best_d2).astype(np.float32)
            # Compare against the grid prime/bucket row for diagnostics only.
            try:
                prime_idx = np.asarray(self.selected_recipe_index[grid_idx], dtype=np.int64)
                prime_pred = self.predicted_rgb_for_recipe_indices(prime_idx)
                prime_d = np.sqrt(np.sum((prime_pred - target_rgb) ** 2, axis=1)).astype(np.float32)
                changed = recipe_idx != prime_idx
                mean_prime = float(np.mean(prime_d)) if prime_d.size else 0.0
                mean_improve = float(np.mean(prime_d - best_d)) if best_d.size else 0.0
                max_improve = float(np.max(prime_d - best_d)) if best_d.size else 0.0
                changed_cells = int(np.count_nonzero(changed))
            except Exception:
                mean_prime = 0.0; mean_improve = 0.0; max_improve = 0.0; changed_cells = 0
            in_bucket_pct = None
            try:
                if getattr(self, "multi_recipe_index", None) is not None:
                    _top = np.asarray(self.multi_recipe_index[grid_idx], dtype=np.int64)
                    if _top.ndim == 1:
                        _top = _top[:, None]
                    _in = np.any(_top == recipe_idx[:, None], axis=1)
                    in_bucket_pct = float(100.0 * np.count_nonzero(_in) / max(1, _in.shape[0]))
            except Exception:
                in_bucket_pct = None
            report = {
                "enabled": True,
                "mode": "direct-cloud-lab" if use_lab else "direct-cloud-rgb",
                "algorithm": "brute_force_nearest_predicted_lab_over_full_measured_cloud" if use_lab else "brute_force_nearest_predicted_rgb_over_full_measured_cloud",
                "metric": metric_name,
                "candidate_count_requested": int(candidate_count),
                "candidate_count_used": int(cloud_rgb.shape[0]),
                "bucket_top_k_available": int(getattr(self, "multi_recipe_count", 0) or 0),
                "cloud_recipe_count": int(cloud_rgb.shape[0]),
                "cells": int(n),
                "changed_from_prime_cells": changed_cells,
                "changed_from_prime_pct": float(100.0 * changed_cells / max(1, n)),
                "mean_prime_rgb_distance": mean_prime,
                "mean_selected_rgb_distance": float(np.mean(best_d)) if best_d.size else 0.0,
                "mean_rgb_distance_improvement": mean_improve,
                "max_rgb_distance_improvement": max_improve,
            }
            if in_bucket_pct is not None:
                report["direct_best_in_original_bucket_pct"] = in_bucket_pct
            return recipe_idx, pred_best, report

        if mode_l not in ("rgb-best", "rgb_best", "bucket-rgb", "bucket_rgb", "lab-best", "lab_best", "bucket-lab", "bucket_lab", "rgb-best-ve", "rgb_best_ve", "bucket-rgb-ve", "bucket_rgb_ve", "lab-best-ve", "lab_best_ve", "bucket-lab-ve", "bucket_lab_ve"):
            raise RuntimeError(f"Unsupported --lut-bucket-choice {mode!r}; use prime, rgb-best, lab-best, rgb-best-ve, lab-best-ve, direct-cloud-rgb, or direct-cloud-lab")
        if getattr(self, "multi_recipe_index", None) is None:
            recipe_idx = np.asarray(self.selected_recipe_index[grid_idx], dtype=np.int64)
            pred = self.predicted_rgb_for_recipe_indices(recipe_idx)
            return recipe_idx, pred, {"enabled": False, "mode": mode_l, "reason": "no bucket multi_recipe_index available"}
        top = np.asarray(self.multi_recipe_index[grid_idx], dtype=np.int64)
        if top.ndim == 1:
            top = top[:, None]
        k_avail = int(top.shape[1])
        k = max(1, min(int(candidate_count), k_avail))
        top = top[:, :k]
        pred = np.asarray(self.recipe_pred_rgb[top], dtype=np.float32)  # [N,k,3]
        # 3dprintv1.38 active print-time bucket colour metric.
        # auto = follow explicit choice first, then LUT colour_distance_mode for *-best-ve,
        # else preserve old RGB behaviour.  Lab mode uses CIE Lab DeltaE76; RGB mode
        # uses squared RGB distance, matching lutmakerv4.7 conventions.
        requested_metric = str(globals().get("RUNTIME_LUT_BUCKET_COLOUR_DISTANCE_MODE", "auto") or "auto").lower().strip().replace("_", "-")
        lut_metric_raw = str(getattr(self, "colour_distance_mode", "rgb2") or "rgb2").lower().strip().replace("_", "-")
        if lut_metric_raw in ("lab-deltae76", "deltae76", "deltae", "de76"):
            lut_metric_raw = "lab"
        elif lut_metric_raw in ("rgb-squared", "rgb-square", "rgb-sq", "rgb"):
            lut_metric_raw = "rgb2"
        if requested_metric in ("lab", "deltae", "deltae76", "lab-deltae76", "de76"):
            active_colour_metric = "lab"
        elif requested_metric in ("rgb", "rgb2", "rgb-squared", "rgb-square", "rgb-sq"):
            active_colour_metric = "rgb2"
        elif mode_l in ("lab-best", "lab_best", "bucket-lab", "bucket_lab", "lab-best-ve", "lab_best_ve", "bucket-lab-ve", "bucket_lab_ve"):
            active_colour_metric = "lab"
        elif mode_l in ("rgb-best-ve", "rgb_best_ve", "bucket-rgb-ve", "bucket_rgb_ve") and lut_metric_raw == "lab":
            active_colour_metric = "lab"
        else:
            active_colour_metric = "rgb2"
        use_lab_bucket = active_colour_metric == "lab"
        if use_lab_bucket:
            if getattr(self, "recipe_pred_lab", None) is not None:
                pred_metric_all = np.asarray(self.recipe_pred_lab[top], dtype=np.float32)
            else:
                pred_metric_all = _srgb_to_lab_array(pred.reshape(-1, 3)).reshape(pred.shape)
            target_metric = _srgb_to_lab_array(target_rgb)
            diff = pred_metric_all - target_metric[:, None, :]
        else:
            diff = pred - target_rgb[:, None, :]
        metric_d2 = np.sum(diff * diff, axis=2).astype(np.float32)
        colour_error = np.sqrt(np.maximum(metric_d2, 0.0)).astype(np.float32) if use_lab_bucket else metric_d2.astype(np.float32)
        d2 = metric_d2  # kept for compatibility below; RGB mode d2 is RGB², Lab mode d2 is Lab².
        rgb_d2_actual = np.sum((pred - target_rgb[:, None, :]) ** 2, axis=2).astype(np.float32)
        rgb_distance_actual = np.sqrt(np.maximum(rgb_d2_actual, 0.0)).astype(np.float32)
        rows = np.arange(top.shape[0], dtype=np.int64)
        prime_idx = top[:, 0].astype(np.int64)
        prime_pred = pred[:, 0, :].astype(np.float32)
        prime_d = rgb_distance_actual[:, 0]

        # v1.40 soft settling prior. The LUT embeds the production defaults;
        # optional runtime overrides exist for audit sweeps. This is deliberately
        # a score adjustment, not a hard DeltaE threshold or candidate filter.
        _bonus_override = globals().get("RUNTIME_LUT_EXISTING_HISTORY_BONUS_DE", None)
        history_bonus_de = float(self.existing_history_bonus_de if _bonus_override is None else _bonus_override)
        _history_scale_override = globals().get("RUNTIME_LUT_EXISTING_HISTORY_BONUS_SCALE_DE", None)
        history_bonus_scale = max(1e-6, float(self.existing_history_bonus_scale_de if _history_scale_override is None else _history_scale_override))
        _ve_penalty_override = globals().get("RUNTIME_LUT_GENERATED_VE_PENALTY_DE", None)
        generated_ve_penalty_de = float(self.generated_ve_penalty_de if _ve_penalty_override is None else _ve_penalty_override)
        _ve_scale_override = globals().get("RUNTIME_LUT_GENERATED_VE_PENALTY_SCALE", None)
        generated_ve_penalty_scale = max(1e-6, float(self.generated_ve_penalty_scale if _ve_scale_override is None else _ve_scale_override))
        exact_top = np.asarray(self.cloud_is_exact_measured[top], dtype=np.float32)
        history_adjustment = np.zeros_like(colour_error, dtype=np.float32)
        if use_lab_bucket and (history_bonus_de > 0.0 or generated_ve_penalty_de > 0.0):
            exact_bonus = (
                max(0.0, history_bonus_de)
                * np.exp(-np.square(colour_error / history_bonus_scale))
                * exact_top
            ).astype(np.float32)
            movement = None
            if getattr(self, "multi_recipe_total_ve_movement", None) is not None:
                movement = np.asarray(self.multi_recipe_total_ve_movement[grid_idx], dtype=np.float32)[:, :k]
            if movement is None or movement.shape != colour_error.shape:
                movement = np.zeros_like(colour_error, dtype=np.float32)
            calm = np.exp(-np.square(np.min(colour_error, axis=1) / history_bonus_scale))[:, None]
            movement_penalty = (
                max(0.0, generated_ve_penalty_de)
                * calm
                * (1.0 - np.exp(-movement / generated_ve_penalty_scale))
                * (1.0 - exact_top)
            ).astype(np.float32)
            history_adjustment = -exact_bonus + movement_penalty

        if mode_l in ("rgb-best", "rgb_best", "bucket-rgb", "bucket_rgb"):
            score_without_history = colour_error.astype(np.float32)
            score = score_without_history + history_adjustment
            best_without_history = np.argmin(score_without_history, axis=1).astype(np.int64)
            best_pos = np.argmin(score, axis=1).astype(np.int64)
            algorithm = "choose_nearest_predicted_lab_deltae76_within_lut_bucket_top_k" if use_lab_bucket else "choose_nearest_predicted_rgb2_within_lut_bucket_top_k"
        elif mode_l in ("lab-best", "lab_best", "bucket-lab", "bucket_lab"):
            score_without_history = colour_error.astype(np.float32)
            score = score_without_history + history_adjustment
            best_without_history = np.argmin(score_without_history, axis=1).astype(np.int64)
            best_pos = np.argmin(score, axis=1).astype(np.int64)
            algorithm = "choose_nearest_predicted_CIE_Lab_deltaE76_with_soft_measured_history_prior"
        else:
            # *-best-ve: first find the best active colour match, then allow a small
            # active-colour-error guard and prefer candidates that keep chromatic
            # depth/VE while avoiding unnecessary W.  In Lab mode this guard is
            # DeltaE76; in RGB mode it remains linear RGB distance for continuity.
            _guard_override = globals().get("RUNTIME_LUT_BUCKET_BEST_VE_MAX_EXTRA_COLOUR_ERROR", None)
            rgb_guard = float(_guard_override) if _guard_override is not None else float(globals().get("RUNTIME_LUT_BUCKET_RGB_BEST_VE_MAX_EXTRA_RGB", 4.0))
            w_weight = float(globals().get("RUNTIME_LUT_BUCKET_RGB_BEST_VE_W_WEIGHT", 0.35))
            chroma_bonus = float(globals().get("RUNTIME_LUT_BUCKET_RGB_BEST_VE_CHROMA_BONUS", 0.45))
            ve_bonus = float(globals().get("RUNTIME_LUT_BUCKET_RGB_BEST_VE_VE_BONUS", 0.35))
            active_d = colour_error.astype(np.float32)
            best_active = np.min(active_d, axis=1, keepdims=True)
            allowed = active_d <= (best_active + rgb_guard)
            mats_top = np.asarray(self.recipe_stack_material_id[top], dtype=np.uint8)  # [N,k,8]
            dose_top = np.asarray(self.recipe_stack_dose[top], dtype=np.float32) * 100.0
            try:
                w_code = int(self.recipe_materials.index("W"))
            except ValueError:
                w_code = 5
            is_w = mats_top == w_code
            is_chroma = ~is_w
            w_count = np.sum(is_w, axis=2).astype(np.float32)
            chroma_count = np.sum(is_chroma, axis=2).astype(np.float32)
            ve_count = np.sum(is_chroma & (dose_top < 100.0), axis=2).astype(np.float32)
            # 3dprintv1.38: match the LUT's active colour distance model.
            # RGB2 LUTs use squared RGB distance.  Lab LUTs use CIE Lab DeltaE76.
            # Recipe terms and support-distance2 only break near-ties inside the
            # active colour-error guard.
            score = colour_error.astype(np.float32) + w_weight * w_count - chroma_bonus * chroma_count - ve_bonus * ve_count
            # Optional support-distance2 penalty inside the same RGB guard.
            # For lutmakerv4.6, cloud_support_distance2_penalty is already the
            # weighted recipe-space penalty used by the LUT.  The runtime weight
            # is therefore a multiplier on the stored penalty; default 1.0 means
            # "use the LUT penalty as written", 0 disables it.
            support2_weight = float(globals().get("RUNTIME_LUT_BUCKET_SUPPORT2_WEIGHT", 1.0) or 0.0)
            support2_penalty = None
            support2_distance = None
            support2_source = "none"
            if support2_weight > 0.0:
                if getattr(self, "multi_recipe_support_distance2_penalty", None) is not None:
                    try:
                        support2_penalty = np.asarray(self.multi_recipe_support_distance2_penalty[grid_idx], dtype=np.float32)[:, :k]
                        support2_source = "grid_top_support_distance2_penalty"
                    except Exception:
                        support2_penalty = None
                if support2_penalty is None and getattr(self, "cloud_support_distance2_penalty", None) is not None:
                    try:
                        support2_penalty = np.asarray(self.cloud_support_distance2_penalty[top], dtype=np.float32)
                        support2_source = "cloud_support_distance2_penalty"
                    except Exception:
                        support2_penalty = None
                if getattr(self, "cloud_support_distance", None) is not None:
                    try:
                        support2_distance = np.asarray(self.cloud_support_distance[top], dtype=np.float32)
                    except Exception:
                        support2_distance = None
                # Backward-compatible fallback for older unweighted d2 arrays.
                if support2_penalty is None:
                    support2_d2 = None
                    if getattr(self, "multi_recipe_support_d2", None) is not None:
                        try:
                            support2_d2 = np.asarray(self.multi_recipe_support_d2[grid_idx], dtype=np.float32)[:, :k]
                            support2_source = "grid_top_support_d2_unweighted"
                        except Exception:
                            support2_d2 = None
                    if support2_d2 is None and getattr(self, "cloud_support_d2", None) is not None:
                        try:
                            support2_d2 = np.asarray(self.cloud_support_d2[top], dtype=np.float32)
                            support2_source = "cloud_support_d2_unweighted"
                        except Exception:
                            support2_d2 = None
                    if support2_d2 is not None:
                        support2_penalty = support2_weight * support2_d2
                        support2_distance = np.sqrt(np.maximum(support2_d2, 0.0)).astype(np.float32)
                elif support2_penalty.shape == score.shape:
                    support2_penalty = support2_weight * support2_penalty
                if support2_penalty is not None and support2_penalty.shape == score.shape:
                    score = score + support2_penalty
                else:
                    support2_source = "missing_or_bad_shape"
            score_without_history = np.where(allowed, score, np.inf)
            score = np.where(allowed, score + history_adjustment, np.inf)
            best_without_history = np.argmin(score_without_history, axis=1).astype(np.int64)
            best_pos = np.argmin(score, axis=1).astype(np.int64)
            # Fallback should be unnecessary, but protects against all-inf rows.
            bad = ~np.isfinite(score[rows, best_pos])
            if np.any(bad):
                best_pos[bad] = np.argmin(colour_error[bad], axis=1).astype(np.int64)
            algorithm = "lab_deltae76_best_with_ve_chromatic_depth_and_recipe_support2_tiebreak_inside_lab_guard" if use_lab_bucket else "rgb_squared_best_with_ve_chromatic_depth_and_recipe_support2_tiebreak_inside_rgb_guard"

        recipe_idx = top[rows, best_pos].astype(np.int64)
        pred_best = pred[rows, best_pos, :].astype(np.float32)
        best_d = rgb_distance_actual[rows, best_pos]
        selected_colour_error = colour_error[rows, best_pos]
        changed = recipe_idx != prime_idx
        selected_exact = exact_top[rows, best_pos] > 0
        without_history_idx = top[rows, best_without_history].astype(np.int64)
        changed_by_history = recipe_idx != without_history_idx
        selected_exact_without_history = exact_top[rows, best_without_history] > 0
        report = {
            "enabled": True,
            "mode": ("lab-best-ve" if mode_l in ("lab-best-ve", "lab_best_ve", "bucket-lab-ve", "bucket_lab_ve") or (mode_l in ("rgb-best-ve", "rgb_best_ve", "bucket-rgb-ve", "bucket_rgb_ve") and use_lab_bucket) else ("rgb-best-ve" if mode_l in ("rgb-best-ve", "rgb_best_ve", "bucket-rgb-ve", "bucket_rgb_ve") else ("lab-best" if mode_l in ("lab-best", "lab_best", "bucket-lab", "bucket_lab") or use_lab_bucket else "rgb-best"))),
            "algorithm": algorithm,
            "metric": "CIE_Lab_D65_DeltaE76" if use_lab_bucket else "RGB_squared_distance",
            "lut_colour_distance_mode": str(getattr(self, "colour_distance_mode", "")),
            "active_colour_distance_mode": "lab" if use_lab_bucket else "rgb2",
            "candidate_count_requested": int(candidate_count),
            "candidate_count_used": int(k),
            "bucket_top_k_available": int(k_avail),
            "cells": int(top.shape[0]),
            "changed_from_prime_cells": int(np.count_nonzero(changed)),
            "changed_from_prime_pct": float(100.0 * np.count_nonzero(changed) / max(1, top.shape[0])),
            "mean_prime_rgb_distance": float(np.mean(prime_d)) if prime_d.size else 0.0,
            "mean_selected_rgb_distance": float(np.mean(best_d)) if best_d.size else 0.0,
            "mean_selected_rgb2_distance": float(np.mean(rgb_d2_actual[rows, best_pos])) if best_d.size else 0.0,
            "mean_prime_rgb2_distance": float(np.mean(rgb_d2_actual[:, 0])) if prime_d.size else 0.0,
            "mean_rgb_distance_improvement": float(np.mean(prime_d - best_d)) if best_d.size else 0.0,
            "mean_rgb2_distance_improvement": float(np.mean(rgb_d2_actual[:, 0] - rgb_d2_actual[rows, best_pos])) if best_d.size else 0.0,
            "max_rgb_distance_improvement": float(np.max(prime_d - best_d)) if best_d.size else 0.0,
            "mean_prime_colour_error": float(np.mean(colour_error[:, 0])) if colour_error.size else 0.0,
            "existing_history_bonus_de": float(history_bonus_de),
            "existing_history_bonus_scale_de": float(history_bonus_scale),
            "generated_ve_penalty_de": float(generated_ve_penalty_de),
            "generated_ve_penalty_scale": float(generated_ve_penalty_scale),
            "selected_exact_history_cells": int(np.count_nonzero(selected_exact)),
            "selected_exact_history_pct": float(100.0 * np.mean(selected_exact)),
            "selected_exact_history_without_preference_cells": int(np.count_nonzero(selected_exact_without_history)),
            "selected_exact_history_without_preference_pct": float(100.0 * np.mean(selected_exact_without_history)),
            "changed_by_history_preference_cells": int(np.count_nonzero(changed_by_history)),
            "changed_by_history_preference_pct": float(100.0 * np.mean(changed_by_history)),
            "history_preference_raw_colour_cost_mean": float(np.mean(selected_colour_error - colour_error[rows, best_without_history])),
            "history_preference_raw_colour_cost_p95": float(np.percentile(selected_colour_error - colour_error[rows, best_without_history], 95)),
            "mean_selected_colour_error": float(np.mean(selected_colour_error)) if colour_error.size else 0.0,
            "mean_colour_error_improvement": float(np.mean(colour_error[:, 0] - selected_colour_error)) if colour_error.size else 0.0,
            "p95_selected_colour_error": float(np.percentile(selected_colour_error, 95)) if colour_error.size else 0.0,
        }
        if mode_l in ("rgb-best-ve", "rgb_best_ve", "bucket-rgb-ve", "bucket_rgb_ve", "lab-best-ve", "lab_best_ve", "bucket-lab-ve", "bucket_lab_ve"):
            report.update({
                "active_colour_guard_extra": float(locals().get("rgb_guard", globals().get("RUNTIME_LUT_BUCKET_RGB_BEST_VE_MAX_EXTRA_RGB", 4.0))),
                "active_colour_guard_metric": "DeltaE76" if locals().get("use_lab_bucket", False) else "linear_RGB_distance",
                "rgb_guard_extra": float(globals().get("RUNTIME_LUT_BUCKET_RGB_BEST_VE_MAX_EXTRA_RGB", 4.0)),
                "w_weight": float(globals().get("RUNTIME_LUT_BUCKET_RGB_BEST_VE_W_WEIGHT", 0.35)),
                "chroma_bonus": float(globals().get("RUNTIME_LUT_BUCKET_RGB_BEST_VE_CHROMA_BONUS", 0.45)),
                "ve_bonus": float(globals().get("RUNTIME_LUT_BUCKET_RGB_BEST_VE_VE_BONUS", 0.35)),
                "low_dose_special_case": "removed_in_3dprintv1.57",
                "support2_runtime_multiplier": float(globals().get("RUNTIME_LUT_BUCKET_SUPPORT2_WEIGHT", 1.0) or 0.0),
                "support2_source": locals().get("support2_source", "none"),
                "support2_lut_mode": str(getattr(self, "support_distance2_mode", "")),
                "support2_lut_weight": float(getattr(self, "support_distance2_weight", 0.0) or 0.0),
                "support2_lut_scale_used": float(getattr(self, "support_distance2_scale_used", 0.0) or 0.0),
            })
            try:
                if locals().get("support2_penalty", None) is not None:
                    _sp = np.asarray(support2_penalty[rows, best_pos], dtype=np.float32)
                    report["mean_selected_support2_penalty"] = float(np.mean(_sp)) if _sp.size else 0.0
                    report["p95_selected_support2_penalty"] = float(np.percentile(_sp, 95)) if _sp.size else 0.0
                if locals().get("support2_distance", None) is not None:
                    _sd = np.asarray(support2_distance[rows, best_pos], dtype=np.float32)
                    report["mean_selected_support_distance"] = float(np.mean(_sd)) if _sd.size else 0.0
                    report["p95_selected_support_distance"] = float(np.percentile(_sd, 95)) if _sd.size else 0.0
            except Exception:
                pass
        return recipe_idx, pred_best, report

    def has_multi_candidates(self) -> bool:
        # PPSPV13: staged multi-candidate tables are deliberately removed from this branch.
        # Dense stack-LUT emission is the active path for now.
        return False

    def predicted_rgb_for_indices(self, idx: np.ndarray) -> np.ndarray:
        idx = np.asarray(idx, dtype=np.int64)
        if getattr(self, "is_stack_lut", False) and self.rgb is None:
            if self.recipe_pred_rgb is None:
                raise RuntimeError("stack LUT predicted_rgb_for_indices requires recipe_pred_rgb when selected_pred_rgb is not loaded")
            recipe_idx = np.asarray(self.selected_recipe_index[idx], dtype=np.int64)
            return np.asarray(self.recipe_pred_rgb[recipe_idx], dtype=np.float32)
        return np.asarray(self.rgb[idx], dtype=np.float32)

    def rgb_for_recipe_string(self, recipe: str) -> Optional[np.ndarray]:
        """Return stored LUT RGB for an exact 8-symbol recipe string.

        ppv41: all RGB preview/reconstruction/AA scoring must use the LUT's
        stored predicted RGB, not an old built-in optical model.  Current full
        7^8 LUTs are generated in MATERIALS order, so their row index can be
        calculated directly without building a 5.7M-entry dict.
        """
        if self.rgb is None:
            return None
        s = str(recipe).strip().upper().replace("S", "F")
        if len(s) != MIX_LAYERS:
            return None
        try:
            idx = 0
            base = len(MATERIAL_ORDER)
            for ch in s:
                idx = idx * base + MATERIAL_ORDER.index(ch)
            if 0 <= idx < len(self.recipes) and str(self.recipes[idx]) == s:
                return np.asarray(self.rgb[idx], dtype=np.float32)
        except Exception:
            pass
        # Fallback for non-full-universe/reordered LUTs; only used for the small
        # number of unique stacks encountered during debugging/AA scoring.
        hits = np.nonzero(self.recipes == s)[0]
        if len(hits):
            return np.asarray(self.rgb[int(hits[0])], dtype=np.float32)
        return None

    def candidate_indices_for_rgb(self, rgb: Tuple[float,float,float], k: int = 1) -> Tuple[np.ndarray, np.ndarray]:
        """Return (RGB distances, LUT indices) for the k nearest candidate recipes."""
        k = max(1, int(k))
        return self._candidate_indices_rgb_batch(np.array([[rgb[0], rgb[1], rgb[2]]], dtype=np.float32), k=k)
        rgb = _srgb_to_lab_array(np.array([[rgb[0], rgb[1], rgb[2]]], dtype=np.float32))[0]
        if self.tree is not None:
            d, idx = self.tree.query(rgb, k=min(k, len(self.rgb)))
            return np.atleast_1d(d).astype(np.float32), np.atleast_1d(idx).astype(np.int64)
        # Fallback for environments without scipy.  Keep a small top-k heap by
        # doing a full vector pass in chunks.
        best_d = np.full((k,), np.inf, dtype=np.float32)
        best_i = np.full((k,), 0, dtype=np.int64)
        for start in range(0, len(self.rgb), 65536):
            block = self.rgb[start:start+65536]
            d2 = np.sum((block - rgb) ** 2, axis=1)
            take = min(k, len(d2))
            cand = np.argpartition(d2, take-1)[:take]
            all_d = np.concatenate([best_d ** 2, d2[cand]])
            all_i = np.concatenate([best_i, start + cand])
            keep = np.argsort(all_d)[:k]
            best_d = np.sqrt(all_d[keep]).astype(np.float32)
            best_i = all_i[keep].astype(np.int64)
        order = np.argsort(best_d)
        return best_d[order], best_i[order]

    def candidate_indices_batch(self, rgbs: np.ndarray, k: int = 1) -> Tuple[np.ndarray, np.ndarray]:
        """Return (RGB distances, LUT indices) for k nearest candidates for each RGB row."""
        k = max(1, int(k))
        rgbs = np.asarray(rgbs, dtype=np.float32).reshape(-1, 3)
        return self._candidate_indices_rgb_batch(np.clip(rgbs, 0, 255), k=k)
        rgbs = _srgb_to_lab_array(np.clip(rgbs, 0, 255))
        if self.tree is not None:
            d, idx = self.tree.query(rgbs, k=min(k, len(self.rgb)))
            d = np.asarray(d, dtype=np.float32)
            idx = np.asarray(idx, dtype=np.int64)
            if d.ndim == 1:
                d = d[:, None]; idx = idx[:, None]
            return d, idx
        # Simpler fallback: query each row.
        all_d = np.empty((len(rgbs), k), dtype=np.float32)
        all_i = np.empty((len(rgbs), k), dtype=np.int64)
        for row, rgb in enumerate(rgbs):
            best_d = np.full((k,), np.inf, dtype=np.float32)
            best_i = np.full((k,), 0, dtype=np.int64)
            for start in range(0, len(self.rgb), 65536):
                block = self.rgb[start:start+65536]
                d2 = np.sum((block - rgb) ** 2, axis=1)
                take = min(k, len(d2))
                cand = np.argpartition(d2, take-1)[:take]
                cat_d = np.concatenate([best_d ** 2, d2[cand]])
                cat_i = np.concatenate([best_i, start + cand])
                keep = np.argsort(cat_d)[:k]
                best_d = np.sqrt(cat_d[keep]).astype(np.float32)
                best_i = cat_i[keep].astype(np.int64)
            all_d[row] = best_d; all_i[row] = best_i
        return all_d, all_i


