def avg_rgb(vals: Sequence[Tuple[int,int,int]]) -> Tuple[int,int,int]:
    if not vals: return (255,255,255)
    return tuple(int(round(sum(v[i] for v in vals)/len(vals))) for i in range(3))

def orientation(mix_layer: int) -> str:
    # Corrected 3.x parity: odd mixing layers Y/front-back, even X/left-right.
    return "Y" if mix_layer % 2 == 1 else "X"


def direct_variable_height_operation(pass_role: str, material: str, logical_layer: Optional[int] = None) -> str:
    """Classify one direct-card road from pass/material plus optional card overrides.

    v1.125 adds two narrowly scoped repeating-layer controls:
      * selected paired/filter logical layers can use the normal Z-offset height
        profile against FILTER dose, making the paired pass a true same-Z valley
        deposit;
      * selected chromatic materials can be declared ordinary carriers on
        specific logical layers (e.g. B as the layer-2 valley-forming carrier).

    Cards that do not request these controls retain v1.124 behaviour.
    """
    role = str(pass_role).strip().lower()
    mat = str(material).strip().upper()
    logical = None if logical_layer is None else int(logical_layer)

    spec = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
    if isinstance(spec, dict) and logical is not None:
        if role == "normal" and bool(spec.get("normal_pass_all_carriers", False)):
            return "carrier"
        carrier_overrides = spec.get("carrier_material_overrides_by_logical_layer", {})
        mats = carrier_overrides.get(str(logical), []) if isinstance(carrier_overrides, dict) else []
        if role == "normal" and mat in {str(v).strip().upper() for v in mats}:
            return "carrier"

        filter_zoffset_layers = {int(v) for v in spec.get("filter_zoffset_logical_layers", [])}
        if role == "filter" and logical in filter_zoffset_layers:
            return "filter_zoffset"

    if role == "normal" and mat in DIRECT_ZOFFSET_TEST_MATERIALS:
        return "zoffset"
    if role == "normal" and mat in ("W", "F"):
        return "carrier"
    if role == "filter":
        return "filter"
    return "ordinary"


def direct_zoffset_underlayer_orientation(logical_layer: int) -> str:
    """Return the raster direction of the physical layer below a Z-offset pass.

    The mandatory 0.20 mm foundation uses X roads. Above the first optical
    layer, ordinary optical directions alternate, so the immediately lower
    optical layer is ``orientation(logical_layer - 1)``.
    """
    logical = int(logical_layer)
    if logical < 1:
        raise ValueError(f"Z-offset test requires logical layer >= 1, got {logical_layer!r}")
    return "X" if logical == 1 else orientation(logical - 1)


def direct_zoffset_phase_shift_mm() -> float:
    """Return the half-road perpendicular phase used by the upper test."""
    shift = float(RUNTIME_PRINT_WIDTH_MM) * DIRECT_ZOFFSET_PHASE_FRACTION
    if not math.isfinite(shift) or shift <= 0.0:
        raise ValueError(f"invalid Z-offset half-road phase {shift!r}")
    return shift


def _normalise_direct_scanline_print_mode(raw: object, profile_id: str) -> Dict[str, object]:
    """Validate one card-selected physical start/end transition profile.

    The values describe filament motion, not nozzle XYZ motion. They are
    intentionally small and fail closed. Profiles are balanced by default.
    A card may explicitly select ``allow_under_recovery`` to test a smaller
    pre-line filament push than the following pullback; over-recovery remains
    prohibited and the exact intended deficit is audited.
    """
    mode = dict(DEFAULT_DIRECT_SCANLINE_PRINT_MODE)
    mode["id"] = str(profile_id)
    if raw is None:
        return mode
    if not isinstance(raw, dict):
        raise RuntimeError(f"print profile {profile_id!r} scanline_mode must be an object")
    mode["label"] = str(raw.get("label", mode.get("label", profile_id)))
    balance_policy = str(raw.get("cycle_balance_policy", mode.get("cycle_balance_policy", "strict"))).strip().lower()
    if balance_policy not in {"strict", "allow_under_recovery", "allow_over_recovery"}:
        raise RuntimeError(
            f"print profile {profile_id!r} cycle_balance_policy must be strict, allow_under_recovery, or allow_over_recovery"
        )
    mode["cycle_balance_policy"] = balance_policy
    recovery_rule_raw = raw.get("stationary_recovery_rule")
    if recovery_rule_raw is not None:
        if not isinstance(recovery_rule_raw, dict):
            raise RuntimeError(f"print profile {profile_id!r} stationary_recovery_rule must be an object")
        rule_type = str(recovery_rule_raw.get("type", "")).strip().lower()
        if rule_type != "linear_alpha_fraction":
            raise RuntimeError(
                f"print profile {profile_id!r} stationary_recovery_rule type must be linear_alpha_fraction"
            )
        base_mm = float(recovery_rule_raw.get("base_mm"))
        span_mm = float(recovery_rule_raw.get("span_mm"))
        if not math.isfinite(base_mm) or not math.isfinite(span_mm):
            raise RuntimeError(f"print profile {profile_id!r} has non-finite dynamic recovery coefficients")
        lo_mm = min(base_mm, base_mm + span_mm)
        hi_mm = max(base_mm, base_mm + span_mm)
        if lo_mm < 0.20 - 1e-12 or hi_mm > 0.60 + 1e-12:
            raise RuntimeError(
                f"print profile {profile_id!r} dynamic stationary recovery range {lo_mm:.5f}..{hi_mm:.5f} is outside 0.20..0.60 mm"
            )
        mode["stationary_recovery_rule"] = {
            "type": "linear_alpha_fraction",
            "base_mm": base_mm,
            "span_mm": span_mm,
            "formula": "base_mm + span_mm*(alpha/128)",
        }
        # Store the 100% endpoint as the nominal profile value. It is replaced
        # by the exact group-specific value before emission and auditing.
        mode["stationary_recovery_mm"] = base_mm + span_mm
    retract_before_wipe_raw = raw.get("retract_before_wipe", mode.get("retract_before_wipe", False))
    if not isinstance(retract_before_wipe_raw, bool):
        raise RuntimeError(
            f"print profile {profile_id!r} retract_before_wipe must be true or false"
        )
    mode["retract_before_wipe"] = bool(retract_before_wipe_raw)
    retract_before_end_coast_raw = raw.get("retract_before_end_coast", mode.get("retract_before_end_coast", False))
    if not isinstance(retract_before_end_coast_raw, bool):
        raise RuntimeError(
            f"print profile {profile_id!r} retract_before_end_coast must be true or false"
        )
    mode["retract_before_end_coast"] = bool(retract_before_end_coast_raw)
    stationary_components_raw = raw.get("stationary_retract_components_mm", mode.get("stationary_retract_components_mm", []))
    if stationary_components_raw is None:
        stationary_components_raw = []
    if not isinstance(stationary_components_raw, list):
        raise RuntimeError(f"print profile {profile_id!r} stationary_retract_components_mm must be a list")
    stationary_components = [float(v) for v in stationary_components_raw]
    if any((not math.isfinite(v) or v < 0.0 or v > 0.60) for v in stationary_components):
        raise RuntimeError(f"print profile {profile_id!r} has invalid stationary retract component")
    if stationary_components and (float(raw.get("wipe_distance_mm", mode.get("wipe_distance_mm", 0.0))) > 1e-12 or float(raw.get("moving_retract_mm", mode.get("moving_retract_mm", 0.0))) > 1e-12 or float(raw.get("final_retract_mm", mode.get("final_retract_mm", 0.0))) > 1e-12):
        raise RuntimeError(f"print profile {profile_id!r} stationary_retract_components_mm is mutually exclusive with wipe/moving/final retract")
    mode["stationary_retract_components_mm"] = stationary_components

    recovery_components_raw = raw.get("stationary_recovery_components", mode.get("stationary_recovery_components", []))
    if recovery_components_raw is None:
        recovery_components_raw = []
    if not isinstance(recovery_components_raw, list):
        raise RuntimeError(f"print profile {profile_id!r} stationary_recovery_components must be a list")
    recovery_components = []
    for item in recovery_components_raw:
        if not isinstance(item, dict):
            raise RuntimeError(f"print profile {profile_id!r} stationary_recovery_components entries must be objects")
        mm = float(item.get("mm", 0.0))
        feed_mm_min = float(item.get("feed_mm_min", DIRECT_REFERENCE_RETRACT_FEED_MM_MIN))
        if not math.isfinite(mm) or mm <= 0.0 or mm > 0.60:
            raise RuntimeError(f"print profile {profile_id!r} invalid recovery component mm={mm!r}")
        if not math.isfinite(feed_mm_min) or feed_mm_min < 60.0 or feed_mm_min > 6000.0:
            raise RuntimeError(f"print profile {profile_id!r} invalid recovery component feed={feed_mm_min!r}")
        recovery_components.append({"mm": mm, "feed_mm_min": feed_mm_min})
    if recovery_components and ("stationary_recovery_mm" in raw or raw.get("stationary_recovery_rule") is not None):
        # Components are the complete stationary recovery definition.
        mode["stationary_recovery_mm"] = sum(float(x["mm"]) for x in recovery_components)
        mode.pop("stationary_recovery_rule", None)
    mode["stationary_recovery_components"] = recovery_components

    recovery_feed = float(raw.get("stationary_recovery_feed_mm_min", mode.get("stationary_recovery_feed_mm_min", DIRECT_REFERENCE_RETRACT_FEED_MM_MIN)))
    if not math.isfinite(recovery_feed) or recovery_feed < 60.0 or recovery_feed > 6000.0:
        raise RuntimeError(f"print profile {profile_id!r} invalid stationary_recovery_feed_mm_min={recovery_feed!r}")
    mode["stationary_recovery_feed_mm_min"] = recovery_feed
    recovery_dwell_ms = int(raw.get("stationary_recovery_dwell_ms", mode.get("stationary_recovery_dwell_ms", 0)))
    if recovery_dwell_ms < 0 or recovery_dwell_ms > 1000:
        raise RuntimeError(f"print profile {profile_id!r} stationary_recovery_dwell_ms must be 0..1000")
    mode["stationary_recovery_dwell_ms"] = recovery_dwell_ms

    numeric_fields = (
        "stationary_recovery_mm",
        "moving_recovery_mm",
        "moving_recovery_distance_mm",
        "end_coast_distance_mm",
        "start_underfeed_length_mm",
        "end_underfeed_length_mm",
        "start_flow_ramp_distance_mm",
        "end_flow_ramp_distance_mm",
        "end_z_relief_distance_mm",
        "end_z_relief_mm",
        "wipe_distance_mm",
        "moving_retract_mm",
        "final_retract_mm",
    )
    for field in numeric_fields:
        if field in raw:
            mode[field] = float(raw[field])
        value = float(mode[field])
        if not math.isfinite(value) or value < 0.0:
            raise RuntimeError(f"print profile {profile_id!r} has invalid {field}={value!r}")
    if float(mode["stationary_recovery_mm"]) > 0.60:
        raise RuntimeError(f"print profile {profile_id!r} stationary recovery exceeds 0.60 mm")
    if float(mode["moving_recovery_mm"]) > 0.10:
        raise RuntimeError(f"print profile {profile_id!r} moving recovery exceeds 0.10 mm")
    if float(mode["moving_recovery_distance_mm"]) > 1.00:
        raise RuntimeError(f"print profile {profile_id!r} moving recovery distance exceeds 1.00 mm")
    if float(mode["end_coast_distance_mm"]) > 1.00:
        raise RuntimeError(f"print profile {profile_id!r} end coast exceeds 1.00 mm")
    for _fk, _max in (("start_underfeed_factor", 2.0), ("end_underfeed_factor", 1.0)):
        if _fk in raw:
            mode[_fk] = float(raw[_fk])
        _fv = float(mode.get(_fk, 1.0))
        if not math.isfinite(_fv) or _fv < 0.0 or _fv > _max:
            raise RuntimeError(f"print profile {profile_id!r} invalid {_fk}={_fv!r}")
    if float(mode.get("start_flow_ramp_distance_mm", 0.0)) > 0.50 or float(mode.get("end_flow_ramp_distance_mm", 0.0)) > 0.50:
        raise RuntimeError(f"print profile {profile_id!r} flow ramp distance exceeds 0.50 mm")
    if float(mode.get("end_z_relief_distance_mm", 0.0)) > 0.20:
        raise RuntimeError(f"print profile {profile_id!r} end Z relief distance exceeds 0.20 mm")
    if float(mode.get("end_z_relief_mm", 0.0)) > 0.05:
        raise RuntimeError(f"print profile {profile_id!r} end Z relief exceeds 0.05 mm")
    end_ramp_final = float(raw.get("end_flow_ramp_final_factor", mode.get("end_flow_ramp_final_factor", 0.0)))
    if not math.isfinite(end_ramp_final) or end_ramp_final < 0.0 or end_ramp_final > 1.0:
        raise RuntimeError(f"print profile {profile_id!r} invalid end_flow_ramp_final_factor={end_ramp_final!r}")
    mode["end_flow_ramp_final_factor"] = end_ramp_final
    ramp_steps = int(raw.get("flow_ramp_steps", mode.get("flow_ramp_steps", 4)))
    if ramp_steps < 2 or ramp_steps > 16:
        raise RuntimeError(f"print profile {profile_id!r} flow_ramp_steps must be 2..16")
    mode["flow_ramp_steps"] = ramp_steps
    if float(mode["wipe_distance_mm"]) > 2.00:
        raise RuntimeError(f"print profile {profile_id!r} wipe distance exceeds 2.00 mm")
    if float(mode["moving_retract_mm"]) > 0.60 or float(mode["final_retract_mm"]) > 0.60:
        raise RuntimeError(f"print profile {profile_id!r} retract values are outside the experimental safety envelope")
    steps = int(raw.get("moving_recovery_steps", mode.get("moving_recovery_steps", 0)))
    if steps < 0 or steps > 16:
        raise RuntimeError(f"print profile {profile_id!r} moving_recovery_steps must be 0..16")
    mode["moving_recovery_steps"] = steps
    moving_recovery = float(mode["moving_recovery_mm"])
    moving_distance = float(mode["moving_recovery_distance_mm"])
    if moving_recovery > 0.0:
        if moving_distance <= 0.02:
            raise RuntimeError(f"print profile {profile_id!r} moving recovery requires distance >0.02 mm")
        if steps < 1:
            raise RuntimeError(f"print profile {profile_id!r} moving recovery requires at least one step")
    else:
        mode["moving_recovery_distance_mm"] = 0.0
        mode["moving_recovery_steps"] = 0
    if bool(mode.get("retract_before_end_coast", False)):
        if float(mode.get("end_coast_distance_mm", 0.0)) <= 0.0:
            raise RuntimeError(
                f"print profile {profile_id!r} retract_before_end_coast requires positive end_coast_distance_mm"
            )
        if not list(mode.get("stationary_retract_components_mm", [])):
            raise RuntimeError(
                f"print profile {profile_id!r} retract_before_end_coast requires stationary_retract_components_mm"
            )
        if float(mode.get("wipe_distance_mm", 0.0)) > 1e-12 or float(mode.get("moving_retract_mm", 0.0)) > 1e-12 or float(mode.get("final_retract_mm", 0.0)) > 1e-12:
            raise RuntimeError(
                f"print profile {profile_id!r} retract_before_end_coast is mutually exclusive with wipe/moving/final retract"
            )
    if bool(mode.get("retract_before_wipe", False)):
        if float(mode["wipe_distance_mm"]) <= 0.0:
            raise RuntimeError(
                f"print profile {profile_id!r} retract_before_wipe requires a positive wipe distance"
            )
        if float(mode["moving_retract_mm"]) > 1e-12:
            raise RuntimeError(
                f"print profile {profile_id!r} retract_before_wipe requires moving_retract_mm=0"
            )
        if float(mode["final_retract_mm"]) <= 0.0:
            raise RuntimeError(
                f"print profile {profile_id!r} retract_before_wipe requires a positive stationary retract"
            )
    total_recovery = float(mode["stationary_recovery_mm"]) + float(mode["moving_recovery_mm"])
    stationary_components = list(mode.get("stationary_retract_components_mm", []))
    total_retract = sum(float(v) for v in stationary_components) if stationary_components else (float(mode["moving_retract_mm"]) + float(mode["final_retract_mm"]))
    deficit = total_retract - total_recovery
    dynamic_rule = mode.get("stationary_recovery_rule")
    dynamic_min_recovery = total_recovery
    dynamic_max_recovery = total_recovery
    if isinstance(dynamic_rule, dict):
        base_mm = float(dynamic_rule["base_mm"])
        span_mm = float(dynamic_rule["span_mm"])
        end0 = base_mm + float(mode["moving_recovery_mm"])
        end1 = base_mm + span_mm + float(mode["moving_recovery_mm"])
        dynamic_min_recovery = min(end0, end1)
        dynamic_max_recovery = max(end0, end1)
        if balance_policy == "strict" and (
            abs(dynamic_min_recovery - total_retract) > 1e-9
            or abs(dynamic_max_recovery - total_retract) > 1e-9
        ):
            raise RuntimeError(
                f"print profile {profile_id!r} strict dynamic recovery is not balanced across alpha: "
                f"range={dynamic_min_recovery:.5f}..{dynamic_max_recovery:.5f} retract={total_retract:.5f}"
            )
        if balance_policy == "allow_under_recovery":
            if dynamic_max_recovery > total_retract + 1e-9:
                raise RuntimeError(
                    f"print profile {profile_id!r} dynamic rule over-recovers at some alpha: "
                    f"max={dynamic_max_recovery:.5f} retract={total_retract:.5f}"
                )
            if total_retract - dynamic_min_recovery > 0.10 + 1e-9:
                raise RuntimeError(
                    f"print profile {profile_id!r} dynamic under-recovery exceeds 0.10 mm"
                )
        # The stored totals describe alpha=128 only; exact per-group values are
        # resolved by resolve_direct_scanline_print_mode_for_fraction().
        deficit = total_retract - total_recovery
    if balance_policy == "strict":
        if abs(deficit) > 1e-9:
            raise RuntimeError(
                f"print profile {profile_id!r} is not filament-balanced: "
                f"recovery={total_recovery:.5f} retract={total_retract:.5f}"
            )
        deficit = 0.0
    elif balance_policy == "allow_under_recovery":
        if deficit < -1e-9:
            raise RuntimeError(
                f"print profile {profile_id!r} allow_under_recovery may not over-recover: "
                f"recovery={total_recovery:.5f} retract={total_retract:.5f}"
            )
        if deficit > 0.10 + 1e-9:
            raise RuntimeError(
                f"print profile {profile_id!r} intentional under-recovery exceeds 0.10 mm: {deficit:.5f}"
            )
    else:  # allow_over_recovery
        if deficit > 1e-9:
            raise RuntimeError(
                f"print profile {profile_id!r} allow_over_recovery may not under-recover: "
                f"recovery={total_recovery:.5f} retract={total_retract:.5f}"
            )
        if -deficit > 0.15 + 1e-9:
            raise RuntimeError(
                f"print profile {profile_id!r} intentional over-recovery exceeds 0.15 mm: {-deficit:.5f}"
            )
    if total_recovery < 0.20 or total_recovery > 0.60:
        raise RuntimeError(f"print profile {profile_id!r} total recovery must be 0.20..0.60 mm")
    if total_retract < 0.20 or total_retract > 0.60:
        raise RuntimeError(f"print profile {profile_id!r} total retract must be 0.20..0.60 mm")
    mode["total_recovery_mm"] = total_recovery
    mode["total_retract_mm"] = total_retract
    mode["intentional_under_recovery_mm"] = max(0.0, float(deficit))
    mode["intentional_over_recovery_mm"] = max(0.0, float(-deficit))
    return mode


def resolve_direct_scanline_print_mode_for_fraction(mode_raw: Dict[str, object], fraction: float) -> Dict[str, object]:
    """Resolve a card scanline mode at one alpha/128 carrier fraction."""
    mode = dict(mode_raw)
    rule = mode.get("stationary_recovery_rule")
    if not isinstance(rule, dict):
        return mode
    f = min(1.0, max(0.0, float(fraction)))
    stationary = float(rule["base_mm"]) + float(rule["span_mm"]) * f
    moving = float(mode.get("moving_recovery_mm", 0.0))
    stationary_components = list(mode.get("stationary_retract_components_mm", []))
    total_retract = sum(float(v) for v in stationary_components) if stationary_components else (float(mode.get("moving_retract_mm", 0.38)) + float(mode.get("final_retract_mm", 0.02)))
    total_recovery = stationary + moving
    deficit = total_retract - total_recovery
    policy = str(mode.get("cycle_balance_policy", "strict"))
    if policy == "strict" and abs(deficit) > 1e-9:
        raise RuntimeError(
            f"dynamic scanline mode {mode.get('id')!r} is not balanced at fraction={f:.8f}: "
            f"recovery={total_recovery:.5f} retract={total_retract:.5f}"
        )
    if policy == "allow_under_recovery" and (deficit < -1e-9 or deficit > 0.10 + 1e-9):
        raise RuntimeError(
            f"dynamic scanline mode {mode.get('id')!r} invalid at fraction={f:.8f}: deficit={deficit:.5f}"
        )
    if policy == "allow_over_recovery" and (deficit > 1e-9 or -deficit > 0.10 + 1e-9):
        raise RuntimeError(
            f"dynamic scanline mode {mode.get('id')!r} invalid over-recovery at fraction={f:.8f}: deficit={deficit:.5f}"
        )
    mode["stationary_recovery_mm"] = float(stationary)
    mode["total_recovery_mm"] = float(total_recovery)
    mode["total_retract_mm"] = float(total_retract)
    mode["intentional_under_recovery_mm"] = max(0.0, float(deficit))
    mode["intentional_over_recovery_mm"] = max(0.0, float(-deficit))
    mode["resolved_alpha_fraction"] = float(f)
    mode["resolved_alpha"] = int(round(f * 128.0))
    return mode


def _normalise_direct_zoffset_height_adjustment(raw: object, panel_height_px: int, panel_width_px: Optional[int] = None) -> Optional[Dict[str, object]]:
    """Validate card-encoded row print profiles.

    v1.75's fc3d_zoffset_height_adjustment_v1 schema remains accepted. v1.76+
    fc3d_zoffset_print_profiles_v1 schema adds a per-profile scanline_mode while
    retaining the same height coefficients and row mapping.
    """
    if raw is None:
        return None
    if not isinstance(raw, dict):
        raise RuntimeError("direct_print Z-offset profile table must be an object")
    schema = str(raw.get("schema_version", ""))
    if schema not in {"fc3d_zoffset_height_adjustment_v1", "fc3d_zoffset_print_profiles_v1", "fc3d_zoffset_print_profiles_v2"}:
        raise RuntimeError(
            "unsupported Z-offset profile schema; expected "
            "fc3d_zoffset_height_adjustment_v1, fc3d_zoffset_print_profiles_v1, or fc3d_zoffset_print_profiles_v2"
        )
    logical_layers_raw = raw.get("logical_layers")
    if logical_layers_raw is None:
        logical_layers = [int(raw.get("logical_layer", 0))]
    else:
        if not isinstance(logical_layers_raw, list) or not logical_layers_raw:
            raise RuntimeError("logical_layers must be a non-empty list when supplied")
        logical_layers = [int(v) for v in logical_layers_raw]
    if any(v < 1 or v > MIX_LAYERS for v in logical_layers):
        raise RuntimeError(
            f"card-encoded Z-offset profiles require logical layers in 1..{MIX_LAYERS}, got {logical_layers}"
        )
    if len(set(logical_layers)) != len(logical_layers):
        raise RuntimeError(f"logical_layers contains duplicates: {logical_layers}")
    logical_layer = int(logical_layers[0])

    filter_zoffset_raw = raw.get("filter_zoffset_logical_layers", [])
    if not isinstance(filter_zoffset_raw, list):
        raise RuntimeError("filter_zoffset_logical_layers must be a list")
    filter_zoffset_logical_layers = [int(v) for v in filter_zoffset_raw]
    if any(v not in logical_layers for v in filter_zoffset_logical_layers):
        raise RuntimeError(
            "filter_zoffset_logical_layers must be a subset of logical_layers: "
            f"{filter_zoffset_logical_layers} vs {logical_layers}"
        )

    carrier_overrides_raw = raw.get("carrier_material_overrides_by_logical_layer", {})
    if not isinstance(carrier_overrides_raw, dict):
        raise RuntimeError("carrier_material_overrides_by_logical_layer must be an object")
    carrier_material_overrides_by_logical_layer = {}
    for key, values in carrier_overrides_raw.items():
        li = int(key)
        if li < 1 or li > MIX_LAYERS:
            raise RuntimeError(f"carrier override logical layer is outside 1..{MIX_LAYERS}: {li}")
        if not isinstance(values, list):
            raise RuntimeError(f"carrier override for logical layer {li} must be a list")
        mats = []
        for value in values:
            mat = str(value).strip().upper()
            if mat not in DIRECT_ZOFFSET_TEST_MATERIALS and mat not in ("W", "F"):
                raise RuntimeError(f"unsupported carrier override material {mat!r} on logical layer {li}")
            if mat not in mats:
                mats.append(mat)
        carrier_material_overrides_by_logical_layer[str(li)] = mats

    normal_pass_all_carriers = bool(raw.get("normal_pass_all_carriers", False))
    require_complete_carrier_layer = bool(raw.get("require_complete_carrier_layer", False))
    allow_sparse_normal_layers_without_filter = bool(
        raw.get("allow_sparse_normal_layers_without_filter", False)
    )
    normal_carrier_height_mode = str(
        raw.get("normal_carrier_height_mode", "dose_scaled")
    ).strip().lower()
    if normal_carrier_height_mode not in ("dose_scaled", "fixed_nominal"):
        raise RuntimeError(
            "normal_carrier_height_mode must be 'dose_scaled' or 'fixed_nominal'"
        )
    bounded_valleys_only = bool(raw.get("bounded_valleys_only", False))
    same_layer_infill_scheduler = str(raw.get("same_layer_infill_scheduler", "legacy")).strip().lower()
    if same_layer_infill_scheduler not in {"legacy", "all_or_defer"}:
        raise RuntimeError("same_layer_infill_scheduler must be legacy or all_or_defer")
    if same_layer_infill_scheduler == "all_or_defer":
        if not normal_pass_all_carriers:
            raise RuntimeError("all_or_defer same-layer infill scheduling requires normal_pass_all_carriers=true")
        if not require_complete_carrier_layer:
            raise RuntimeError("all_or_defer same-layer infill scheduling requires require_complete_carrier_layer=true")
        if not bounded_valleys_only:
            raise RuntimeError("all_or_defer same-layer infill scheduling requires bounded_valleys_only=true")
    carrier_dose_min = float(raw.get("carrier_dose_min", 1.0 if require_complete_carrier_layer else 0.0))
    if not math.isfinite(carrier_dose_min) or carrier_dose_min < 0.0 or carrier_dose_min > 1.0:
        raise RuntimeError("carrier_dose_min must be finite in 0..1")
    tile_size_px = int(raw.get("tile_size_px", 0))
    grid_rows = int(raw.get("grid_rows", 0))
    profile_grid_top_offset_px = int(raw.get("profile_grid_top_offset_px", 0) or 0)
    profile_grid_left_offset_px = int(raw.get("profile_grid_left_offset_px", 0) or 0)
    profile_grid_bottom_offset_px = int(raw.get("profile_grid_bottom_offset_px", profile_grid_top_offset_px) or 0)
    profile_grid_right_offset_px = int(raw.get("profile_grid_right_offset_px", profile_grid_left_offset_px) or 0)
    if min(profile_grid_top_offset_px, profile_grid_left_offset_px, profile_grid_bottom_offset_px, profile_grid_right_offset_px) < 0:
        raise RuntimeError("Z-offset profile grid offsets must be non-negative")
    expected_profile_h = profile_grid_top_offset_px + tile_size_px * grid_rows + profile_grid_bottom_offset_px
    if tile_size_px <= 0 or grid_rows <= 0 or expected_profile_h != int(panel_height_px):
        raise RuntimeError(
            f"Z-offset profile row geometry mismatch: tile_size_px={tile_size_px}, "
            f"grid_rows={grid_rows}, offsets=({profile_grid_top_offset_px},{profile_grid_bottom_offset_px}), "
            f"panel_height_px={panel_height_px}"
        )
    profiles_raw = raw.get("profiles")
    row_ids = raw.get("row_profile_ids_top_to_bottom")
    profile_id_grid = raw.get("profile_id_grid_top_to_bottom")
    grid_cols = int(raw.get("grid_cols", 0) or 0)
    if not isinstance(profiles_raw, dict) or not profiles_raw:
        raise RuntimeError("Z-offset profiles must be a non-empty object")
    if schema == "fc3d_zoffset_print_profiles_v2":
        if panel_width_px is None or int(panel_width_px) <= 0:
            raise RuntimeError("fc3d_zoffset_print_profiles_v2 requires panel_width_px")
        expected_profile_w = profile_grid_left_offset_px + tile_size_px * grid_cols + profile_grid_right_offset_px
        if grid_cols <= 0 or expected_profile_w != int(panel_width_px):
            raise RuntimeError(
                f"Z-offset profile column geometry mismatch: tile_size_px={tile_size_px}, "
                f"grid_cols={grid_cols}, offsets=({profile_grid_left_offset_px},{profile_grid_right_offset_px}), "
                f"panel_width_px={panel_width_px}"
            )
        if not isinstance(profile_id_grid, list) or len(profile_id_grid) != grid_rows:
            raise RuntimeError("profile_id_grid_top_to_bottom must contain grid_rows rows")
        for r, grid_row in enumerate(profile_id_grid):
            if not isinstance(grid_row, list) or len(grid_row) != grid_cols:
                raise RuntimeError(f"profile_id_grid_top_to_bottom row {r} must contain grid_cols entries")
    else:
        if not isinstance(row_ids, list) or len(row_ids) != grid_rows:
            raise RuntimeError("row_profile_ids_top_to_bottom length must equal grid_rows")

    atomic_partition_raw = raw.get("atomic_partition_id_grids_top_to_bottom", {})
    if atomic_partition_raw is None:
        atomic_partition_raw = {}
    if not isinstance(atomic_partition_raw, dict):
        raise RuntimeError("atomic_partition_id_grids_top_to_bottom must be an object keyed by logical layer")
    atomic_partition_grids: Dict[str, List[List[int]]] = {}
    for layer_key, owner_grid in atomic_partition_raw.items():
        li = int(layer_key)
        if li not in logical_layers:
            raise RuntimeError(f"atomic partition grid logical layer {li} is not in logical_layers={logical_layers}")
        if not isinstance(owner_grid, list) or len(owner_grid) != grid_rows:
            raise RuntimeError(f"atomic partition grid for logical layer {li} must contain grid_rows={grid_rows} rows")
        norm_rows: List[List[int]] = []
        for r, owner_row in enumerate(owner_grid):
            if not isinstance(owner_row, list) or len(owner_row) != grid_cols:
                raise RuntimeError(f"atomic partition grid logical layer {li} row {r} must contain grid_cols={grid_cols} entries")
            vals = [int(v) for v in owner_row]
            if any(v < 0 for v in vals):
                raise RuntimeError(f"atomic partition IDs must be >=0; logical layer {li} row {r}")
            norm_rows.append(vals)
        atomic_partition_grids[str(li)] = norm_rows
    profiles: List[Dict[str, object]] = []
    profile_index: Dict[str, int] = {}
    for profile_id, profile_raw in profiles_raw.items():
        pid = str(profile_id).strip()
        if not pid or not isinstance(profile_raw, dict):
            raise RuntimeError(f"invalid Z-offset print profile {profile_id!r}")
        complement = float(profile_raw.get("complement_depth_mm", float("nan")))
        dose_scaled = float(profile_raw.get("dose_scaled_depth_mm", float("nan")))
        if not math.isfinite(complement) or not math.isfinite(dose_scaled):
            raise RuntimeError(f"non-finite depth coefficient in Z-offset profile {pid}")
        if complement < 0.0 or dose_scaled < 0.0 or complement > 0.20 or dose_scaled > 0.20:
            raise RuntimeError(f"unsafe depth coefficient in Z-offset profile {pid}: {complement}, {dose_scaled}")
        scanline_mode = _normalise_direct_scanline_print_mode(
            profile_raw.get("scanline_mode") if schema in {"fc3d_zoffset_print_profiles_v1", "fc3d_zoffset_print_profiles_v2"} else None,
            pid,
        )
        static_height_representation = str(profile_raw.get("static_height_representation", "g29")).strip().lower()
        if static_height_representation not in {"g29", "direct_g1z"}:
            raise RuntimeError(
                f"unsupported static_height_representation for profile {pid}: {static_height_representation!r}"
            )
        profile_index[pid] = len(profiles)
        profiles.append({
            "id": pid,
            "label": str(profile_raw.get("label", pid)),
            "complement_depth_mm": complement,
            "dose_scaled_depth_mm": dose_scaled,
            "height_curve_model": str(profile_raw.get("height_curve_model", "linear")).strip().lower(),
            "height_curve_low_alpha": int(profile_raw.get("height_curve_low_alpha", 38)),
            "height_curve_low_depth_mm": float(profile_raw.get("height_curve_low_depth_mm", complement)),
            "height_curve_high_alpha": int(profile_raw.get("height_curve_high_alpha", 128)),
            "height_curve_high_depth_mm": float(profile_raw.get("height_curve_high_depth_mm", dose_scaled)),
            "height_curve_road_width_mm": float(profile_raw.get("height_curve_road_width_mm", ROAD_W_MM)),
            "height_curve_width_model": str(profile_raw.get("height_curve_width_model", "fixed")).strip().lower(),
            "height_curve_width_low_alpha": int(profile_raw.get("height_curve_width_low_alpha", 38)),
            "height_curve_width_low_mm": float(profile_raw.get("height_curve_width_low_mm", ROAD_W_MM)),
            "height_curve_width_high_alpha": int(profile_raw.get("height_curve_width_high_alpha", 128)),
            "height_curve_width_high_mm": float(profile_raw.get("height_curve_width_high_mm", ROAD_W_MM)),
            "height_curve_filament_diameter_mm": float(profile_raw.get("height_curve_filament_diameter_mm", FILAMENT_DIAM_MM)),
            "height_curve_full_e_per_mm": float(profile_raw.get("height_curve_full_e_per_mm", OPTICAL_LAYER_E_PER_MM)),
            "height_curve_tilt_low_alpha": int(profile_raw.get("height_curve_tilt_low_alpha", 38)),
            "height_curve_tilt_high_alpha": int(profile_raw.get("height_curve_tilt_high_alpha", 128)),
            "height_curve_tilt_low_depth_mm": float(profile_raw.get("height_curve_tilt_low_depth_mm", 0.0)),
            "height_curve_tilt_high_depth_mm": float(profile_raw.get("height_curve_tilt_high_depth_mm", 0.0)),
            "scanline_mode": scanline_mode,
            "continuous_variable_dose_row": bool(profile_raw.get("continuous_variable_dose_row", False)),
            "continuous_transition_blend_mm": float(profile_raw.get("continuous_transition_blend_mm", 0.20)),
            "continuous_transition_overrides": list(profile_raw.get("continuous_transition_overrides", [])),
            "continuous_transition_z_delay_mm": float(profile_raw.get("continuous_transition_z_delay_mm", 0.0)),
            "continuous_transition_z_ramp_mm": float(profile_raw.get("continuous_transition_z_ramp_mm", 0.0)),
            "continuous_hard_g29_step": bool(profile_raw.get("continuous_hard_g29_step", False)),
            "continuous_live_g29_residual_z_span_mm": (
                float(profile_raw["continuous_live_g29_residual_z_span_mm"])
                if profile_raw.get("continuous_live_g29_residual_z_span_mm") is not None else None
            ),
            "continuous_live_g29_steps": int(profile_raw.get("continuous_live_g29_steps", 0)),
            "depth_adjustment_points_by_alpha": list(profile_raw.get("depth_adjustment_points_by_alpha", [])),
            "continuous_g29_anchor_alpha": (
                int(profile_raw["continuous_g29_anchor_alpha"])
                if profile_raw.get("continuous_g29_anchor_alpha") is not None else None
            ),
            "continuous_g29_representation_shift_mm": float(profile_raw.get("continuous_g29_representation_shift_mm", 0.0)),
            "continuous_scanline_direction": str(profile_raw.get("continuous_scanline_direction", "serpentine")).strip().lower(),
            # v1.120 low-VE kinematics research: card profiles may independently
            # control print speed and optical E/mm while preserving the established
            # VE->G29 height curve.  This lets us distinguish slower-motion stability
            # from deliberately increased/decreased deposited dose.
            "print_speed_mm_s": float(profile_raw.get("print_speed_mm_s", NORMAL_LAYER_FEED / 60.0)),
            "optical_e_multiplier": float(profile_raw.get("optical_e_multiplier", 1.0)),
            "static_height_representation": static_height_representation,
            # v1.99 stop-mode seam research: profile-level physical scanline endpoint
            # controls.  None preserves the global --endpoint-trim-mm total-shortening
            # path.  Explicit values exempt this profile from global pre-trim and
            # are applied at the actual emitted start/end after direction is known.
            "start_trim_mm": (float(profile_raw["start_trim_mm"]) if profile_raw.get("start_trim_mm") is not None else None),
            "end_trim_mm": (float(profile_raw["end_trim_mm"]) if profile_raw.get("end_trim_mm") is not None else None),
            "start_underfeed_length_mm": float(profile_raw.get("start_underfeed_length_mm", 0.0)),
            "start_underfeed_factor": float(profile_raw.get("start_underfeed_factor", 1.0)),
            "end_underfeed_length_mm": float(profile_raw.get("end_underfeed_length_mm", 0.0)),
            "end_underfeed_factor": float(profile_raw.get("end_underfeed_factor", 1.0)),
        })
    for p in profiles:
        _speed = float(p.get("print_speed_mm_s", NORMAL_LAYER_FEED / 60.0))
        _em = float(p.get("optical_e_multiplier", 1.0))
        if not math.isfinite(_speed) or _speed <= 0.0 or _speed > 1000.0:
            raise RuntimeError(f"invalid print_speed_mm_s in profile {p.get('id')!r}: {_speed!r}")
        if not math.isfinite(_em) or _em <= 0.0 or _em > 8.0:
            raise RuntimeError(f"invalid optical_e_multiplier in profile {p.get('id')!r}: {_em!r}")
        _curve_model = str(p.get("height_curve_model", "linear")).strip().lower()
        if _curve_model not in {"linear", "stadium_volume_anchored_v1", "volume_gap_power_width_anchored_v1", "volume_gap_power_width_anchored_v1_plus_tilt"}:
            raise RuntimeError(
                f"unsupported height_curve_model in profile {p.get('id')!r}: {_curve_model!r}"
            )
        if _curve_model in {"stadium_volume_anchored_v1", "volume_gap_power_width_anchored_v1", "volume_gap_power_width_anchored_v1_plus_tilt"}:
            _la = int(p.get("height_curve_low_alpha", 38))
            _ha = int(p.get("height_curve_high_alpha", 128))
            _ld = float(p.get("height_curve_low_depth_mm", float("nan")))
            _hd = float(p.get("height_curve_high_depth_mm", float("nan")))
            _rw = float(p.get("height_curve_road_width_mm", float("nan")))
            _wm = str(p.get("height_curve_width_model", "fixed")).strip().lower()
            _wla = int(p.get("height_curve_width_low_alpha", 38))
            _wlw = float(p.get("height_curve_width_low_mm", _rw))
            _wha = int(p.get("height_curve_width_high_alpha", 128))
            _whw = float(p.get("height_curve_width_high_mm", _rw))
            if _wm not in {"fixed", "linear_anchored_v1"}:
                raise RuntimeError(f"unsupported height_curve_width_model in profile {p.get('id')!r}: {_wm!r}")
            if _wm == "linear_anchored_v1":
                if not (0 <= _wla < _wha <= 128):
                    raise RuntimeError(f"invalid width anchors in profile {p.get('id')!r}: {_wla}, {_wha}")
                if not (0.10 <= _wlw <= 0.80 and 0.10 <= _whw <= 0.80):
                    raise RuntimeError(f"unsafe width anchors in profile {p.get('id')!r}: {_wlw}, {_whw}")
            _fd = float(p.get("height_curve_filament_diameter_mm", float("nan")))
            _epm = float(p.get("height_curve_full_e_per_mm", float("nan")))
            if not (0 <= _la < _ha <= 128):
                raise RuntimeError(
                    f"invalid stadium height anchors in profile {p.get('id')!r}: {_la}, {_ha}"
                )
            if not all(math.isfinite(v) for v in (_ld, _hd, _rw, _fd, _epm)):
                raise RuntimeError(f"non-finite stadium height parameter in profile {p.get('id')!r}")
            if not (0.0 <= _hd <= 0.20 and 0.0 <= _ld <= 0.20 and _rw > 0.0 and _fd > 0.0 and _epm > 0.0):
                raise RuntimeError(f"unsafe stadium height parameter in profile {p.get('id')!r}")
            _c = 1.0 - math.pi / 4.0
            _fil_area = math.pi * (_fd / 2.0) ** 2
            _a_full = _fil_area * _epm
            _disc_hi = _rw * _rw - 4.0 * _c * _a_full
            if _disc_hi <= 0.0:
                raise RuntimeError(
                    f"stadium model has impossible full-dose area for profile {p.get('id')!r}"
                )
        direction_mode = str(p.get("continuous_scanline_direction", "serpentine"))
        if direction_mode not in {"serpentine", "left_to_right"}:
            raise RuntimeError(
                f"unsupported continuous_scanline_direction {direction_mode!r}; "
                "expected serpentine or left_to_right"
            )
        for _z_key, _z_max in (("continuous_transition_z_delay_mm", 30.0), ("continuous_transition_z_ramp_mm", 10.0)):
            _zv = float(p.get(_z_key, 0.0))
            _z_min = -3.0 if _z_key == "continuous_transition_z_delay_mm" else 0.0
            if not math.isfinite(_zv) or _zv < _z_min or _zv > _z_max:
                raise RuntimeError(f"unsafe {_z_key} in profile {p.get('id')!r}: {_zv!r}")
        _hard_g29_step = bool(p.get("continuous_hard_g29_step", False))
        _live_span = p.get("continuous_live_g29_residual_z_span_mm")
        _live_steps = int(p.get("continuous_live_g29_steps", 0))
        if _live_span is not None:
            if not math.isfinite(float(_live_span)) or not (0.0 < float(_live_span) <= 0.045):
                raise RuntimeError(f"unsafe continuous_live_g29_residual_z_span_mm in profile {p.get('id')!r}: {_live_span!r}")
            if not (2 <= _live_steps <= 64):
                raise RuntimeError(f"unsafe continuous_live_g29_steps in profile {p.get('id')!r}: {_live_steps!r}")
            if float(p.get("continuous_transition_z_ramp_mm", 0.0)) <= 0.0:
                raise RuntimeError("live G29 hybrid transition requires a positive Z-ramp distance")
        _repr_shift = float(p.get("continuous_g29_representation_shift_mm", 0.0) or 0.0)
        if not math.isfinite(_repr_shift) or abs(_repr_shift) > 0.10:
            raise RuntimeError(f"unsafe continuous_g29_representation_shift_mm in profile {p.get('id')!r}: {_repr_shift!r}")
        if abs(_repr_shift) > 1e-12 and p.get("continuous_g29_anchor_alpha") is None:
            raise RuntimeError("continuous_g29_representation_shift_mm requires continuous_g29_anchor_alpha")
        if abs(_repr_shift) > 1e-12 and _live_span is not None:
            raise RuntimeError("continuous_g29_representation_shift_mm is mutually exclusive with live G29 hybrid mode")
        if _hard_g29_step:
            if abs(_repr_shift) > 1e-12:
                raise RuntimeError("continuous_hard_g29_step requires continuous_g29_representation_shift_mm=0")
            if p.get("continuous_g29_anchor_alpha") is None:
                raise RuntimeError("continuous_hard_g29_step requires continuous_g29_anchor_alpha")
            if _live_span is not None:
                raise RuntimeError("continuous_hard_g29_step is mutually exclusive with live G29 hybrid mode")
            if float(p.get("continuous_transition_z_ramp_mm", 0.0)) > 1e-12:
                raise RuntimeError("continuous_hard_g29_step requires continuous_transition_z_ramp_mm=0")
        for _trim_key in ("start_trim_mm", "end_trim_mm"):
            _v = p.get(_trim_key)
            if _v is not None and (not math.isfinite(float(_v)) or float(_v) < 0.0 or float(_v) > 1.0):
                raise RuntimeError(f"unsafe {_trim_key} in profile {p.get('id')!r}: {_v!r}")
        for _len_key in ("start_underfeed_length_mm", "end_underfeed_length_mm"):
            _v = float(p.get(_len_key, 0.0))
            if not math.isfinite(_v) or _v < 0.0 or _v > 1.0:
                raise RuntimeError(f"unsafe {_len_key} in profile {p.get('id')!r}: {_v!r}")
        _v = float(p.get("start_underfeed_factor", 1.0))
        if not math.isfinite(_v) or _v < 0.0 or _v > 2.0:
            raise RuntimeError(f"unsafe start_underfeed_factor in profile {p.get('id')!r}: {_v!r}")
        _v = float(p.get("end_underfeed_factor", 1.0))
        if not math.isfinite(_v) or _v < 0.0 or _v > 1.0:
            raise RuntimeError(f"unsafe end_underfeed_factor in profile {p.get('id')!r}: {_v!r}")

    row_indices: List[int] = []
    profile_index_grid: Optional[List[List[int]]] = None
    if schema == "fc3d_zoffset_print_profiles_v2":
        profile_index_grid = []
        for row, grid_row in enumerate(profile_id_grid):
            idx_row: List[int] = []
            for col, profile_id in enumerate(grid_row):
                pid = str(profile_id)
                if pid not in profile_index:
                    raise RuntimeError(f"Z-offset cell row={row} col={col} references unknown profile {pid!r}")
                idx_row.append(int(profile_index[pid]))
            profile_index_grid.append(idx_row)
        # Retain a row summary only when the complete row uses one profile.
        for idx_row in profile_index_grid:
            row_indices.append(idx_row[0] if len(set(idx_row)) == 1 else -1)
    else:
        for row, profile_id in enumerate(row_ids):
            pid = str(profile_id)
            if pid not in profile_index:
                raise RuntimeError(f"Z-offset row {row} references unknown profile {pid!r}")
            row_indices.append(int(profile_index[pid]))

    emission_order = str(raw.get("profile_emission_order", "dose_then_profile")).strip().lower()
    if emission_order not in {"dose_then_profile", "profile_then_height"}:
        raise RuntimeError(
            "profile_emission_order must be dose_then_profile or profile_then_height"
        )

    reset_raw = raw.get("inter_profile_reset")
    inter_profile_reset: Optional[Dict[str, object]] = None
    if reset_raw is not None:
        if schema not in {"fc3d_zoffset_print_profiles_v1", "fc3d_zoffset_print_profiles_v2"} or not isinstance(reset_raw, dict):
            raise RuntimeError("inter_profile_reset requires fc3d_zoffset_print_profiles_v1/v2 and an object value")
        enabled_raw = reset_raw.get("enabled", True)
        if not isinstance(enabled_raw, bool):
            raise RuntimeError("inter_profile_reset.enabled must be true or false")
        roads = int(reset_raw.get("purge_roads_per_boundary", 2))
        spacing = float(reset_raw.get("road_spacing_mm", 0.34))
        restore = reset_raw.get("restore_intentional_under_recovery", True)
        if not isinstance(restore, bool):
            raise RuntimeError("inter_profile_reset.restore_intentional_under_recovery must be true or false")
        if roads < 1 or roads > 4:
            raise RuntimeError("inter_profile_reset.purge_roads_per_boundary must be 1..4")
        if not math.isfinite(spacing) or spacing < 0.25 or spacing > 0.45:
            raise RuntimeError("inter_profile_reset.road_spacing_mm must be finite in 0.25..0.45")
        max_restore = float(reset_raw.get("max_restore_mm", 6.0))
        if not math.isfinite(max_restore) or max_restore <= 0.0 or max_restore > 10.0:
            raise RuntimeError("inter_profile_reset.max_restore_mm must be finite in 0..10")
        if bool(enabled_raw) and emission_order != "profile_then_height":
            raise RuntimeError("enabled inter_profile_reset requires profile_emission_order=profile_then_height")
        inter_profile_reset = {
            "enabled": bool(enabled_raw),
            "purge_roads_per_boundary": roads,
            "road_spacing_mm": spacing,
            "restore_intentional_under_recovery": bool(restore),
            "max_restore_mm": max_restore,
            "foundation_material": "W",
            "purge_material": "active_chromatic",
            "purge_dose_fraction": 1.0,
            "recovery_mm": 0.40,
            "moving_retract_mm": 0.38,
            "final_retract_mm": 0.02,
            "wipe_distance_mm": 1.00,
        }

    return {
        "schema_version": schema,
        "logical_layer": logical_layer,
        "logical_layers": logical_layers,
        "filter_zoffset_logical_layers": filter_zoffset_logical_layers,
        "carrier_material_overrides_by_logical_layer": carrier_material_overrides_by_logical_layer,
        "normal_pass_all_carriers": normal_pass_all_carriers,
        "require_complete_carrier_layer": require_complete_carrier_layer,
        "allow_sparse_normal_layers_without_filter": allow_sparse_normal_layers_without_filter,
        "normal_carrier_height_mode": normal_carrier_height_mode,
        "bounded_valleys_only": bounded_valleys_only,
        "same_layer_infill_scheduler": same_layer_infill_scheduler,
        "carrier_dose_min": carrier_dose_min,
        "tile_size_px": tile_size_px,
        "grid_rows": grid_rows,
        "profile_grid_top_offset_px": profile_grid_top_offset_px,
        "profile_grid_left_offset_px": profile_grid_left_offset_px,
        "profile_grid_bottom_offset_px": profile_grid_bottom_offset_px,
        "profile_grid_right_offset_px": profile_grid_right_offset_px,
        "grid_cols": grid_cols if schema == "fc3d_zoffset_print_profiles_v2" else 0,
        "profiles": profiles,
        "row_profile_indices_top_to_bottom": row_indices,
        "row_profile_ids_top_to_bottom": [str(v) for v in row_ids] if isinstance(row_ids, list) else [],
        "profile_index_grid_top_to_bottom": profile_index_grid,
        "profile_id_grid_top_to_bottom": profile_id_grid if schema == "fc3d_zoffset_print_profiles_v2" else None,
        "atomic_partition_id_grids_top_to_bottom": atomic_partition_grids,
        "profile_emission_order": emission_order,
        "inter_profile_reset": inter_profile_reset,
    }


def direct_zoffset_scanline_print_mode(profile_index: int = -1) -> Dict[str, object]:
    profile = direct_zoffset_height_profile(profile_index)
    mode = profile.get("scanline_mode") if isinstance(profile, dict) else None
    if isinstance(mode, dict):
        return dict(mode)
    return dict(DEFAULT_DIRECT_SCANLINE_PRINT_MODE)


def direct_zoffset_height_profile(profile_index: int = -1) -> Dict[str, object]:
    spec = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
    if isinstance(spec, dict):
        profiles = spec.get("profiles")
        if isinstance(profiles, list) and 0 <= int(profile_index) < len(profiles):
            profile = profiles[int(profile_index)]
            if isinstance(profile, dict):
                return profile
    return dict(DEFAULT_DIRECT_ZOFFSET_HEIGHT_PROFILE)


def _direct_height_curve_width_mm(fraction: float, profile: Dict[str, object]) -> float:
    """Provisional deposited-road width used only to shape the VE->height curve.

    v1.115 deliberately uses a VERY cautious width correction. The default
    linear_anchored_v1 model is anchored at measured/assumed widths and linearly
    extrapolates below the low anchor rather than allowing width to collapse
    with VE. This is intended for calibration, not as a claim of exact bead width.
    """
    f = min(1.0, max(0.0, float(fraction)))
    model = str(profile.get("height_curve_width_model", "fixed")).strip().lower()
    if model == "linear_anchored_v1":
        a0 = int(profile.get("height_curve_width_low_alpha", 38))
        w0 = float(profile.get("height_curve_width_low_mm", ROAD_W_MM))
        a1 = int(profile.get("height_curve_width_high_alpha", 128))
        w1 = float(profile.get("height_curve_width_high_mm", ROAD_W_MM))
        f0 = float(a0) / 128.0
        f1 = float(a1) / 128.0
        t = (f - f0) / (f1 - f0)
        return float(w0 + (w1 - w0) * t)
    return float(profile.get("height_curve_road_width_mm", ROAD_W_MM))


def _direct_stadium_bead_height_mm(
    fraction: float,
    road_width_mm: float,
    filament_diameter_mm: float,
    full_e_per_mm: float,
) -> float:
    """Mass-conserving capsule/stadium deposited-bead height for a fixed road width.

    Cross-sectional area:
        A = h*(w-h) + pi*h^2/4
          = w*h - (1-pi/4)*h^2

    The requested area per mm of path is the incoming filament area times
    E/mm, scaled by dose fraction. The smaller physical root is the deposited
    bead height for the fixed-width branch.
    """
    f = min(1.0, max(0.0, float(fraction)))
    w = float(road_width_mm)
    fd = float(filament_diameter_mm)
    epm = float(full_e_per_mm)
    c = 1.0 - math.pi / 4.0
    a_full = math.pi * (fd / 2.0) ** 2 * epm
    area = a_full * f
    disc = w * w - 4.0 * c * area
    if disc < -1e-12:
        raise ValueError(
            f"stadium bead model impossible: fraction={f:.6f} width={w:.6f} area={area:.9f}"
        )
    disc = max(0.0, disc)
    return float((w - math.sqrt(disc)) / (2.0 * c))


def direct_zoffset_total_depth_mm(height_fraction: float, profile_index: int = -1) -> float:
    """Return total descent below nominal model Z for one chromatic Z-offset road.

    v1.114 adds a physically shaped, mass-conserving stadium/capsule height model.
    It is anchored to measured depth targets but uses requested extrusion volume
    to set the curvature over the full 0..100% VE range, including below 30%.
    """
    fraction = float(height_fraction)
    if not math.isfinite(fraction) or fraction < 0.0 or fraction > 1.0 + 1e-9:
        raise ValueError(f"Z-offset dose fraction must be finite in 0..1, got {height_fraction!r}")
    f = min(1.0, max(0.0, fraction))
    profile = direct_zoffset_height_profile(profile_index)
    model = str(profile.get("height_curve_model", "linear")).strip().lower()

    if model in {"volume_gap_power_width_anchored_v1", "volume_gap_power_width_anchored_v1_plus_tilt"}:
        # v1.116: direct physical interpretation.
        # v1.123 optionally adds a bounded empirical Z-depth tilt AFTER the
        # baseline physical curve has been evaluated. This leaves the baseline
        # mass-conserving width/gap model untouched while allowing a different
        # valley geometry to require a VE-dependent nozzle-position correction.
        #
        # Requested E/mm sets deposited cross-sectional area A(f).
        # The deposited road is approximated as a stadium/capsule:
        #     A = w*g - (1-pi/4)*g^2
        # where g is nozzle-to-substrate gap / deposited road height.
        #
        # 100% width is the nominal road width. The measured 100% depth
        # fixes the absolute gap reference. The measured low-VE depth
        # then implies the low-VE road width required by mass conservation.
        # A smooth power law w(f)=w100*f^beta is fitted through those two
        # width anchors. This avoids guessing a 30% width independently.
        low_alpha = int(profile.get("height_curve_low_alpha", 38))
        high_alpha = int(profile.get("height_curve_high_alpha", 128))
        low_depth = float(profile.get("height_curve_low_depth_mm", 0.08025))
        high_depth = float(profile.get("height_curve_high_depth_mm", 0.02180))
        w_high = float(profile.get("height_curve_road_width_mm", ROAD_W_MM))
        filament_diameter = float(profile.get("height_curve_filament_diameter_mm", FILAMENT_DIAM_MM))
        full_e_per_mm = float(profile.get("height_curve_full_e_per_mm", OPTICAL_LAYER_E_PER_MM))

        f0 = float(low_alpha) / 128.0
        f1 = float(high_alpha) / 128.0
        if not (0.0 < f0 < f1 <= 1.0):
            raise ValueError("volume-gap model requires 0 < low anchor < high anchor <= 1")
        c = 1.0 - math.pi / 4.0
        a_full = math.pi * (filament_diameter / 2.0) ** 2 * full_e_per_mm

        # High anchor: solve the smaller physical stadium root for the gap.
        a1 = a_full * f1
        disc1 = w_high * w_high - 4.0 * c * a1
        if disc1 <= 0.0:
            raise ValueError("volume-gap model high anchor has impossible area/width")
        g1 = (w_high - math.sqrt(disc1)) / (2.0 * c)

        # Absolute depth reference: depth + gap is constant for this optical layer.
        depth_gap_reference = high_depth + g1

        # Low empirical depth implies low physical gap, hence an implied width.
        g0 = depth_gap_reference - low_depth
        if g0 <= 0.0:
            raise ValueError(
                f"volume-gap model low anchor implies non-positive gap {g0:.6f} mm"
            )
        a0 = a_full * f0
        w0 = (a0 + c * g0 * g0) / g0
        if not (0.05 <= w0 <= 1.0):
            raise ValueError(
                f"volume-gap model implied low width unsafe: {w0:.6f} mm"
            )

        beta = math.log(w0 / w_high) / math.log(f0 / f1)

        if f <= 1e-15:
            gap = 0.0
        else:
            width = w_high * (f / f1) ** beta
            area = a_full * f
            disc = width * width - 4.0 * c * area
            if disc < -1e-12:
                raise ValueError(
                    f"volume-gap model impossible at fraction={f:.6f}: "
                    f"width={width:.6f} area={area:.9f}"
                )
            gap = (width - math.sqrt(max(0.0, disc))) / (2.0 * c)
        depth = depth_gap_reference - gap

        if model == "volume_gap_power_width_anchored_v1_plus_tilt":
            tilt_low_alpha = int(profile.get("height_curve_tilt_low_alpha", low_alpha))
            tilt_high_alpha = int(profile.get("height_curve_tilt_high_alpha", high_alpha))
            tilt_low_mm = float(profile.get("height_curve_tilt_low_depth_mm", 0.0))
            tilt_high_mm = float(profile.get("height_curve_tilt_high_depth_mm", 0.0))
            if not (0 <= tilt_low_alpha < tilt_high_alpha <= 128):
                raise ValueError("tilted volume-gap model requires 0 <= tilt low alpha < tilt high alpha <= 128")
            if (not math.isfinite(tilt_low_mm) or not math.isfinite(tilt_high_mm)
                    or abs(tilt_low_mm) > 0.060 or abs(tilt_high_mm) > 0.060):
                raise ValueError("tilted volume-gap model requires finite tilt depths within +/-0.060 mm")
            a = f * 128.0
            if a <= tilt_low_alpha:
                tilt_mm = tilt_low_mm
            elif a >= tilt_high_alpha:
                tilt_mm = tilt_high_mm
            else:
                tt = (a - tilt_low_alpha) / float(tilt_high_alpha - tilt_low_alpha)
                tilt_mm = tilt_low_mm + tt * (tilt_high_mm - tilt_low_mm)
            depth += tilt_mm

    elif model == "stadium_volume_anchored_v1":
        low_alpha = int(profile.get("height_curve_low_alpha", 38))
        high_alpha = int(profile.get("height_curve_high_alpha", 128))
        low_depth = float(profile.get("height_curve_low_depth_mm", 0.08025))
        high_depth = float(profile.get("height_curve_high_depth_mm", 0.02180))
        filament_diameter = float(profile.get("height_curve_filament_diameter_mm", FILAMENT_DIAM_MM))
        full_e_per_mm = float(profile.get("height_curve_full_e_per_mm", OPTICAL_LAYER_E_PER_MM))

        f0 = float(low_alpha) / 128.0
        f1 = float(high_alpha) / 128.0
        w = _direct_height_curve_width_mm(f, profile)
        w0 = _direct_height_curve_width_mm(f0, profile)
        w1 = _direct_height_curve_width_mm(f1, profile)
        h = _direct_stadium_bead_height_mm(f, w, filament_diameter, full_e_per_mm)
        h0 = _direct_stadium_bead_height_mm(f0, w0, filament_diameter, full_e_per_mm)
        h1 = _direct_stadium_bead_height_mm(f1, w1, filament_diameter, full_e_per_mm)
        if abs(h1 - h0) < 1e-12:
            raise ValueError("stadium height anchors are degenerate")
        t = (h - h0) / (h1 - h0)
        depth = low_depth + (high_depth - low_depth) * t
    else:
        complement = float(profile["complement_depth_mm"])
        dose_scaled = float(profile["dose_scaled_depth_mm"])
        depth = (1.0 - f) * complement + f * dose_scaled

    if not math.isfinite(depth) or depth < -1e-9 or depth > 0.20 + 1e-9:
        raise ValueError(f"invalid card-encoded Z-offset total depth {depth!r}")
    return float(max(0.0, depth))


def direct_zoffset_extra_depth_mm(height_fraction: float) -> float:
    """Compatibility helper for the default v1.73 blended formula."""
    fraction = min(1.0, max(0.0, float(height_fraction)))
    return float(fraction * DIRECT_ZOFFSET_EXTRA_DEPTH_MM)


def direct_total_depth_print_z(physical_layer: int, total_depth_mm: float) -> float:
    physical_layer = int(physical_layer)
    if physical_layer < 1:
        raise ValueError("variable height requires an optical physical layer >= 1")
    depth = float(total_depth_mm)
    if not math.isfinite(depth) or depth < 0.0:
        raise ValueError(f"total depth must be finite and non-negative, got {total_depth_mm!r}")
    nominal_z = BASE_H_MM + physical_layer * MIX_H_MM
    return float(nominal_z - depth)


def direct_total_depth_z_trim(total_depth_mm: float, baseline_trim_mm: float = 0.0) -> float:
    depth = float(total_depth_mm)
    baseline = float(baseline_trim_mm)
    if not math.isfinite(depth) or depth < 0.0 or not math.isfinite(baseline):
        raise ValueError(f"invalid total depth/baseline: {total_depth_mm!r}, {baseline_trim_mm!r}")
    return float(baseline - depth)


def direct_same_layer_filter_representation_shift_mm(material_operation: str) -> float:
    """Return the G29-only representation shift for same-layer optical infill.

    TILT20/depth was physically calibrated from the NEXT 0.10-mm nominal plane.
    A filter_zoffset action is now deliberately represented inside the current
    Studio/logical layer. Raising absolute G29.1 by one MIX_H_MM preserves the
    original physical nozzle Z exactly while keeping nominal G1 Z unchanged.
    """
    return float(MIX_H_MM if str(material_operation) == "filter_zoffset" else 0.0)


def direct_filter_phase_shift_mm() -> float:
    """Return the half-road perpendicular phase used by the lower filter."""
    shift = float(RUNTIME_PRINT_WIDTH_MM) * DIRECT_FILTER_PHASE_FRACTION
    if not math.isfinite(shift) or shift <= 0.0:
        raise ValueError(f"invalid lower-filter half-road phase {shift!r}")
    return shift

def e_for_len(length: float, layer_h: float, line_w: float = RUNTIME_PRINT_WIDTH_MM, material=None) -> float:
    """Return relative E for a line length.

    Base layer remains standard volumetric extrusion.
    Optical 0.10 mm layers use Studio-observed E/mm ~= 0.0155 rather
    than the previous 0.40*0.10/filament_area ~= 0.01663.
    This avoids layer-2+ systematic overextrusion while keeping geometry unchanged.
    """
    if layer_h <= MIX_H_MM + 1e-6:
        return max(0.0, length * optical_e_per_mm_for_material(material))
    return max(0.0, length * line_w * layer_h / FILAMENT_AREA)

def parse_printable_area(gcode_3mf: Optional[Path] = None) -> Tuple[float, float, float, float]:
    """Read and validate printable_area from an explicit or embedded package.

    v1.54 fails closed: malformed/missing structured metadata is not silently
    replaced by a guessed H2C rectangle.
    """
    source: object = Path(gcode_3mf) if gcode_3mf is not None else io.BytesIO(embedded_h2c_package_bytes())
    try:
        with zipfile.ZipFile(source, "r") as z:
            cfg = json.loads(z.read("Metadata/project_settings.config").decode("utf-8"))
    except Exception as exc:
        raise RuntimeError(f"Could not parse H2C project printable-area metadata: {exc}") from exc
    pts = cfg.get("printable_area")
    if not isinstance(pts, list):
        raise RuntimeError("H2C project_settings.config has no list-valued printable_area")
    xy: List[Tuple[float, float]] = []
    for index, item in enumerate(pts):
        parts = str(item).lower().split("x", 1)
        if len(parts) != 2:
            raise RuntimeError(f"printable_area[{index}] has unexpected form {item!r}")
        try:
            xy.append((float(parts[0]), float(parts[1])))
        except Exception as exc:
            raise RuntimeError(f"printable_area[{index}] is non-numeric: {item!r}") from exc
    if len(xy) < 3:
        raise RuntimeError(f"printable_area requires at least three points; found {len(xy)}")
    xs = [v[0] for v in xy]
    ys = [v[1] for v in xy]
    result = (min(xs), min(ys), max(xs), max(ys))
    if result[2] <= result[0] or result[3] <= result[1]:
        raise RuntimeError(f"printable_area is degenerate: {result}")
    return result

def rects_overlap_or_touch(a, b, gap: float = 0.0) -> bool:
    ax0, ay0, ax1, ay1 = a; bx0, by0, bx1, by1 = b
    return not (ax1 + gap <= bx0 or bx1 + gap <= ax0 or ay1 + gap <= by0 or by1 + gap <= ay0)

def rect_inside(inner, outer) -> bool:
    ix0, iy0, ix1, iy1 = inner; ox0, oy0, ox1, oy1 = outer
    return ix0 >= ox0 and iy0 >= oy0 and ix1 <= ox1 and iy1 <= oy1

def union_bbox(*boxes: Tuple[float, float, float, float]) -> Tuple[float, float, float, float]:
    if not boxes:
        raise ValueError("union_bbox requires at least one rectangle")
    return (
        min(float(b[0]) for b in boxes),
        min(float(b[1]) for b in boxes),
        max(float(b[2]) for b in boxes),
        max(float(b[3]) for b in boxes),
    )


def audit_generated_first_layer_acceleration(lines: Sequence[str]) -> Dict[str, object]:
    """Parse the generated first layer and prove every XY extrusion uses S500."""
    in_first_layer = False
    layer_markers = 0
    current_accel: Optional[float] = None
    xy_extrusion_count = 0
    observed_accels = set()
    failures: List[str] = []

    for line_number, original in enumerate(lines, start=1):
        if original.strip() == "; CHANGE_LAYER":
            layer_markers += 1
            if layer_markers == 1:
                in_first_layer = True
                continue
            if layer_markers == 2:
                break
        if not in_first_layer:
            continue

        parsed = parse_gcode_line(original, line_number, strict=True)
        if parsed.command is None:
            continue
        command = str(parsed.command)
        if command == "M204":
            s_word = parsed.optional_word("S")
            if s_word is None:
                failures.append(f"line {line_number} M204 does not contain exactly one S field")
                continue
            if s_word[1].numeric is None:
                failures.append(f"line {line_number} M204 has non-numeric S field")
            else:
                current_accel = float(s_word[1].numeric)
            continue
        if command not in ("G0", "G1"):
            continue

        params = parsed.numeric_parameters()
        if params.get("E", 0.0) > 0.0 and ("X" in params or "Y" in params):
            xy_extrusion_count += 1
            observed_accels.add(current_accel)
            if current_accel is None or abs(current_accel - FIRST_LAYER_PRINT_ACCEL_MM_S2) > 1e-6:
                failures.append(
                    f"line {line_number} first-layer XY extrusion uses M204 S{current_accel}, "
                    f"expected S{FIRST_LAYER_PRINT_ACCEL_MM_S2}: {original.strip()}"
                )

    if layer_markers < 2:
        failures.append(f"expected at least two CHANGE_LAYER markers, found {layer_markers}")
    if xy_extrusion_count == 0:
        failures.append("first generated layer contains no positive XY extrusion moves")
    if failures:
        raise RuntimeError("Generated first-layer acceleration audit failed: " + "; ".join(failures[:20]))
    return {
        "result": "PASS",
        "parser": "strict_token_parser_no_semantic_regex",
        "expected_xy_extrusion_acceleration_mm_s2": int(FIRST_LAYER_PRINT_ACCEL_MM_S2),
        "xy_extrusion_count": int(xy_extrusion_count),
        "observed_xy_extrusion_accelerations_mm_s2": sorted(float(v) for v in observed_accels),
    }

def choose_tower_bbox(card_bbox, printable_bbox) -> Tuple[float, float, float, float]:
    """Place the tower out of the model way with a guaranteed 5 mm gap.

    Preference order is above, below, right, then left of the image. If no
    candidate fits fully inside the printable area, raise an error before any
    print file is created.
    """
    cx0, cy0, cx1, cy1 = card_bbox
    px0, py0, px1, py1 = printable_bbox
    card_cx = (cx0 + cx1) / 2.0
    card_cy = (cy0 + cy1) / 2.0

    def clamp(v, lo, hi):
        return max(lo, min(v, hi))

    def centred_x(y0):
        x0 = clamp(card_cx - TOWER_W_MM / 2.0, px0, px1 - TOWER_W_MM)
        return (x0, y0, x0 + TOWER_W_MM, y0 + TOWER_H_MM)

    def centred_y(x0):
        y0 = clamp(card_cy - TOWER_H_MM / 2.0, py0, py1 - TOWER_H_MM)
        return (x0, y0, x0 + TOWER_W_MM, y0 + TOWER_H_MM)

    candidates = [
        centred_x(cy1 + TOWER_GAP_MM),
        centred_x(cy0 - TOWER_GAP_MM - TOWER_H_MM),
        centred_y(cx1 + TOWER_GAP_MM),
        centred_y(cx0 - TOWER_GAP_MM - TOWER_W_MM),
    ]
    for cand in candidates:
        if rect_inside(cand, printable_bbox) and not rects_overlap_or_touch(card_bbox, cand, TOWER_GAP_MM - 1e-6):
            return cand
    raise RuntimeError(
        f"Cannot place prime tower: no {TOWER_W_MM:.2f} x {TOWER_H_MM:.2f} mm square tower position fits inside "
        f"printable area {printable_bbox} while maintaining a {TOWER_GAP_MM:.1f} mm gap from image bbox {card_bbox}."
    )

def _tower_outside_staging_x(tower_bbox: Tuple[float, float, float, float],
                             printable_bbox: Optional[Tuple[float, float, float, float]] = None) -> float:
    """Return a Bambu-style M620.14 staging X outside the tower entry edge.

    FC3D's visible tower prime/seed path enters from the left.  BambuStudio computes
    M620.14 from the tool-change start position and shifts it 2 mm farther outward
    from the wipe-tower bounding box.  We therefore prefer tx0-2 mm.  If that point
    would leave the printable region, use tx1+2 mm instead; fail closed if neither
    side can provide the requested staging offset.
    """
    tx0, _ty0, tx1, _ty1 = map(float, tower_bbox)
    off = float(M62014_TOWER_STAGE_OFFSET_MM)
    candidates = [tx0 - off, tx1 + off]
    if printable_bbox is None:
        return candidates[0]
    px0, _py0, px1, _py1 = map(float, printable_bbox)
    for x in candidates:
        if px0 <= x <= px1:
            return x
    raise RuntimeError(
        f"cannot place M620.14 staging {off:.3f} mm outside tower X{tx0:.3f}-{tx1:.3f} "
        f"inside printable X{px0:.3f}-{px1:.3f}"
    )


def tower_machine_prime_xy_for_slot(slot_index: int, slot_count: int,
                                    tower_bbox: Tuple[float, float, float, float],
                                    printable_bbox: Optional[Tuple[float, float, float, float]] = None) -> Tuple[float, float]:
    """Return reserved outside-tower M620.14 staging coordinate for one tower slot."""
    tx0, ty0, tx1, ty1 = map(float, tower_bbox)
    n = max(1, int(slot_count))
    idx = max(0, min(n - 1, int(slot_index)))
    band_h = (ty1 - ty0) / n
    y = ty0 + (idx + 0.5) * band_h
    x = _tower_outside_staging_x(tower_bbox, printable_bbox)
    return (x, y)


def tower_machine_prime_xy_for_material(mat: str, active: Sequence[str],
                                        tower_bbox: Tuple[float, float, float, float],
                                        printable_bbox: Optional[Tuple[float, float, float, float]] = None) -> Tuple[float, float]:
    """Return reserved outside-tower M620.14 staging coordinate for a material band."""
    tx0, ty0, tx1, ty1 = map(float, tower_bbox)
    act = [m for m in MATERIAL_ORDER if m in active]
    if mat not in act:
        return (_tower_outside_staging_x(tower_bbox, printable_bbox), (ty0 + ty1) / 2.0)
    return tower_machine_prime_xy_for_slot(act.index(mat), max(1, len(act)), tower_bbox, printable_bbox)


def point_in_tower(p: Optional[Tuple[float,float]], tower_bbox=None) -> bool:
    if p is None or tower_bbox is None: return False
    x,y=p; x0,y0,x1,y1=tower_bbox
    return x0-TOWER_MARGIN <= x <= x1+TOWER_MARGIN and y0-TOWER_MARGIN <= y <= y1+TOWER_MARGIN


def _point_in_tower_inflated(p: Optional[Tuple[float, float]], tower_bbox=None, inflate: float = 0.35) -> bool:
    if p is None or tower_bbox is None:
        return False
    x, y = float(p[0]), float(p[1])
    x0, y0, x1, y1 = tower_bbox
    return (x0 - inflate <= x <= x1 + inflate) and (y0 - inflate <= y <= y1 + inflate)


def _segment_intersects_tower_bbox(start: Optional[Tuple[float, float]], end: Optional[Tuple[float, float]], tower_bbox=None, inflate: float = 0.35) -> bool:
    """Return True when the XY segment touches/crosses the tower rectangle.

    PPSPV46 uses this for motion safety only.  It intentionally tests the
    tower body rectangle, not the per-road span collision index, because the
    observed damage is the nozzle scraping the prime-tower edge/body.
    """
    if start is None or end is None or tower_bbox is None:
        return False
    if _point_in_tower_inflated(start, tower_bbox, inflate) or _point_in_tower_inflated(end, tower_bbox, inflate):
        return True
    x0, y0 = float(start[0]), float(start[1])
    x1, y1 = float(end[0]), float(end[1])
    bx0, by0, bx1, by1 = tower_bbox
    xmin, ymin, xmax, ymax = bx0 - inflate, by0 - inflate, bx1 + inflate, by1 + inflate
    dx, dy = x1 - x0, y1 - y0
    t0, t1 = 0.0, 1.0
    for p, q in ((-dx, x0 - xmin), (dx, xmax - x0), (-dy, y0 - ymin), (dy, ymax - y0)):
        if abs(p) < 1e-12:
            if q < 0:
                return False
        else:
            t = q / p
            if p < 0:
                if t > t1:
                    return False
                if t > t0:
                    t0 = t
            else:
                if t < t0:
                    return False
                if t < t1:
                    t1 = t
    return True


def _append_vertical_checked_hop_xy(g: List[str], current_xy: Tuple[float, float], target_xy: Tuple[float, float],
                                      z: float, feed: int = 60000, reason: str = "TOWER_SAFE_TRAVEL",
                                      e_field: Optional[str] = None, restore_z: bool = True,
                                      hop_z_mm: Optional[float] = None,
                                      z_decimals: int = 3) -> None:
    """Studio-safe vertical checked travel: lift, XY at hop Z, optional lower.

    PPSPV50 keeps the physical vertical clearance behaviour of PPSPV48 but avoids
    the classic Bambu Studio layer-view poison pattern caused by huge numbers of
    bare Z-only commands such as ``G1 Z0.700`` / ``G1 Z0.300`` inside the model.

    To make the lift/drop explicit without Z-only G0/G1 moves, the lift and lower
    commands repeat the current/target XY while changing Z. The XY travel leg also
    carries the hop Z. This preserves parser state and keeps collision audits able
    to see the actual lifted Z, while avoiding the known bad Z-only command form.
    """
    x0, y0 = float(current_xy[0]), float(current_xy[1])
    x, y = float(target_xy[0]), float(target_xy[1])
    hop = HOP_Z_MM if hop_z_mm is None else float(hop_z_mm)
    zhop = z + hop
    zd = max(3, int(z_decimals))
    g.append(f"; FC3D_PPSPV62_STUDIO_SAFE_VERTICAL_CHECKED_HOP reason={reason} hop={hop:.3f}")
    g.append(f"G1 X{x0:.3f} Y{y0:.3f} Z{zhop:.{zd}f} F60000")
    g.append(f"G1 X{x:.3f} Y{y:.3f} Z{zhop:.{zd}f}" + (f" {e_field}" if e_field else "") + f" F{int(feed)}")
    if restore_z:
        g.append(f"G1 X{x:.3f} Y{y:.3f} Z{z:.{zd}f} F6000")

def dist_point_seg(px,py, ax,ay,bx,by):
    vx,vy=bx-ax,by-ay; wx,wy=px-ax,py-ay
    c1=vx*wx+vy*wy
    if c1<=0: return math.hypot(px-ax,py-ay)
    c2=vx*vx+vy*vy
    if c2<=1e-12: return math.hypot(px-ax,py-ay)
    if c1>=c2: return math.hypot(px-bx,py-by)
    t=c1/c2; qx=ax+t*vx; qy=ay+t*vy
    return math.hypot(px-qx,py-qy)

class SpanCollisionIndex:
    """Per-layer exact floating-point span index for selective Z-hop decisions.

    PPV69 deliberately matches the corrected audit model:
      - Python float/double precision coordinates are used directly.
      - No audit-grid/key quantisation is used; coordinates are the exact emitted %.3f G-code floats.
      - Lower layers are ignored; the index is per current physical layer only.
      - Printed roads are stored as exact generated centreline spans, not inflated.
      - Endpoint-only contacts are not considered collisions.
      - Proper crossings and colinear overlaps are considered collisions.

    This keeps the geometry conservative for real crossings without adding the
    PPV67 tile-entry false-positive hop explosion caused by treating exact
    endpoint touches as requiring a lift.
    """
    MIN_SEG_MM = 0.02

    @staticmethod
    def _gcode_coord(v: float) -> float:
        # Match the actual emitted G-code coordinate precision used everywhere
        # in PP: X/Y are written as %.3f.  Collision decisions must use the same
        # coordinates the printer will execute, otherwise an internal endpoint
        # touch can become a real crossing after formatting to G-code.
        return float(f"{float(v):.3f}")

    def __init__(self, printable_bbox=(0.0, 0.0, 330.0, 320.0)):
        self.printable_bbox = printable_bbox
        self.x_spans: Dict[float, List[Tuple[float, float]]] = {}  # key = exact y, spans are x0..x1
        self.y_spans: Dict[float, List[Tuple[float, float]]] = {}  # key = exact x, spans are y0..y1
        self.x_dirty: set[float] = set()
        self.y_dirty: set[float] = set()
        self._x_keys_dirty = False
        self._y_keys_dirty = False
        self._x_keys: List[float] = []
        self._y_keys: List[float] = []
        self.diag_segments: List[Tuple[float, float, float, float]] = []

    @staticmethod
    def _norm_span(a: float, b: float) -> Tuple[float, float]:
        return (a, b) if a <= b else (b, a)

    def _append_span(self, table: Dict[float, List[Tuple[float, float]]], dirty: set[float],
                     key: float, a: float, b: float):
        a, b = self._norm_span(a, b)
        if b - a <= self.MIN_SEG_MM:
            return
        spans = table.get(key)
        if spans is None:
            table[key] = [(a, b)]
            if table is self.x_spans:
                self._x_keys_dirty = True
            else:
                self._y_keys_dirty = True
            return

        last_a, last_b = spans[-1]
        if a >= last_a:
            # Merge only true overlap, not endpoint-only contact.
            if a < last_b:
                spans[-1] = (last_a, max(last_b, b))
            else:
                spans.append((a, b))
        else:
            spans.append((a, b))
            dirty.add(key)

    def add_segment(self, x0, y0, x1, y1, height_z=None, width=None):
        # Store the exact double-precision coordinates that will be emitted to
        # G-code, i.e. after PP's %.3f formatting. Width is intentionally ignored.
        x0 = self._gcode_coord(x0); y0 = self._gcode_coord(y0)
        x1 = self._gcode_coord(x1); y1 = self._gcode_coord(y1)
        if y1 == y0:
            self._append_span(self.x_spans, self.x_dirty, y0, x0, x1)
        elif x1 == x0:
            self._append_span(self.y_spans, self.y_dirty, x0, y0, y1)
        else:
            # Very rare defensive fallback for non-axis extrusion.
            if math.hypot(x1 - x0, y1 - y0) > self.MIN_SEG_MM:
                self.diag_segments.append((x0, y0, x1, y1))

    def _ensure_line_clean(self, table: Dict[float, List[Tuple[float, float]]],
                           dirty: set[float], key: float):
        if key not in dirty:
            return
        spans = sorted(table.get(key, []))
        merged: List[Tuple[float, float]] = []
        for a, b in spans:
            if not merged or a >= merged[-1][1]:
                merged.append((a, b))
            else:
                merged[-1] = (merged[-1][0], max(merged[-1][1], b))
        table[key] = merged
        dirty.discard(key)

    def _keys_for(self, axis: str) -> List[float]:
        if axis == "X":
            if self._x_keys_dirty:
                self._x_keys = sorted(self.x_spans)
                self._x_keys_dirty = False
            return self._x_keys
        if self._y_keys_dirty:
            self._y_keys = sorted(self.y_spans)
            self._y_keys_dirty = False
        return self._y_keys

    @staticmethod
    def _proper_interval_overlap(a0: float, a1: float, b0: float, b1: float) -> bool:
        a0, a1 = SpanCollisionIndex._norm_span(a0, a1)
        b0, b1 = SpanCollisionIndex._norm_span(b0, b1)
        # True positive-length overlap only; endpoint-only touching is ignored.
        return min(a1, b1) > max(a0, b0)

    def _span_contains_strict(self, spans: Sequence[Tuple[float, float]], p: float) -> bool:
        # Strict containment only. Endpoint touches are not collisions.
        for s0, s1 in spans:
            if p < s0:
                return False
            if s0 < p < s1:
                return True
            if p <= s1:
                return False
        return False

    def _line_overlap_hits(self, table, dirty, key: float, a: float, b: float) -> bool:
        spans = table.get(key)
        if not spans:
            return False
        self._ensure_line_clean(table, dirty, key)
        for s0, s1 in table[key]:
            if s1 <= min(a, b):
                continue
            if s0 >= max(a, b):
                return False
            if self._proper_interval_overlap(a, b, s0, s1):
                return True
        return False

    @staticmethod
    def _orient(ax, ay, bx, by, cx, cy):
        return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)

    def _diag_hit(self, x0, y0, x1, y1, sx0, sy0, sx1, sy1) -> bool:
        # Exact double-precision orientation. Proper crossing or colinear overlap only.
        o1 = self._orient(x0, y0, x1, y1, sx0, sy0)
        o2 = self._orient(x0, y0, x1, y1, sx1, sy1)
        o3 = self._orient(sx0, sy0, sx1, sy1, x0, y0)
        o4 = self._orient(sx0, sy0, sx1, sy1, x1, y1)

        if o1 == 0.0 and o2 == 0.0 and o3 == 0.0 and o4 == 0.0:
            if abs(x1 - x0) >= abs(y1 - y0):
                return self._proper_interval_overlap(x0, x1, sx0, sx1)
            return self._proper_interval_overlap(y0, y1, sy0, sy1)

        return ((o1 > 0.0 and o2 < 0.0) or (o1 < 0.0 and o2 > 0.0)) and \
               ((o3 > 0.0 and o4 < 0.0) or (o3 < 0.0 and o4 > 0.0))

    def swept_line_hits(self, x0, y0, x1, y1, current_z=None, sweep_w=TRAVEL_SWEEP_W_MM) -> bool:
        # PPV69 emitted-G-code exact-float query.  Coordinates are converted to
        # the actual %.3f X/Y values that the printer will execute, then compared
        # with double-precision float math. Endpoint-only contact is ignored;
        # proper crossings and colinear overlaps trigger a hop.
        x0 = self._gcode_coord(x0); y0 = self._gcode_coord(y0)
        x1 = self._gcode_coord(x1); y1 = self._gcode_coord(y1)
        length = math.hypot(x1 - x0, y1 - y0)
        if length <= 0.05:
            return False

        import bisect
        xmin, xmax = self._norm_span(x0, x1)
        ymin, ymax = self._norm_span(y0, y1)
        dx = x1 - x0
        dy = y1 - y0

        # Horizontal travel.
        if y0 == y1:
            # Colinear overlap with horizontal printed spans at exact same y.
            if self._line_overlap_hits(self.x_spans, self.x_dirty, y0, x0, x1):
                return True
            # Proper crossing with vertical spans.
            y_keys = self._keys_for("Y")
            i0 = bisect.bisect_left(y_keys, xmin)
            i1 = bisect.bisect_right(y_keys, xmax)
            for key in y_keys[i0:i1]:
                spans = self.y_spans.get(key)
                if not spans:
                    continue
                self._ensure_line_clean(self.y_spans, self.y_dirty, key)
                if self._span_contains_strict(self.y_spans[key], y0):
                    # endpoint-only in X is ignored by strict/interval rules; proper interior crossing only.
                    if xmin < key < xmax:
                        return True
            return False

        # Vertical travel.
        if x0 == x1:
            if self._line_overlap_hits(self.y_spans, self.y_dirty, x0, y0, y1):
                return True
            x_keys = self._keys_for("X")
            i0 = bisect.bisect_left(x_keys, ymin)
            i1 = bisect.bisect_right(x_keys, ymax)
            for key in x_keys[i0:i1]:
                spans = self.x_spans.get(key)
                if not spans:
                    continue
                self._ensure_line_clean(self.x_spans, self.x_dirty, key)
                if self._span_contains_strict(self.x_spans[key], x0):
                    if ymin < key < ymax:
                        return True
            return False

        # Diagonal/other travel vs horizontal printed roads.
        x_keys = self._keys_for("X")
        i0 = bisect.bisect_left(x_keys, ymin)
        i1 = bisect.bisect_right(x_keys, ymax)
        for key in x_keys[i0:i1]:
            # key is exact y of a horizontal printed road.
            t = (key - y0) / dy
            if not (0.0 < t < 1.0):
                continue
            x_cross = x0 + dx * t
            spans = self.x_spans.get(key)
            if spans:
                self._ensure_line_clean(self.x_spans, self.x_dirty, key)
                if self._span_contains_strict(self.x_spans[key], x_cross):
                    return True

        # Diagonal/other travel vs vertical printed roads.
        y_keys = self._keys_for("Y")
        i0 = bisect.bisect_left(y_keys, xmin)
        i1 = bisect.bisect_right(y_keys, xmax)
        for key in y_keys[i0:i1]:
            t = (key - x0) / dx
            if not (0.0 < t < 1.0):
                continue
            y_cross = y0 + dy * t
            spans = self.y_spans.get(key)
            if spans:
                self._ensure_line_clean(self.y_spans, self.y_dirty, key)
                if self._span_contains_strict(self.y_spans[key], y_cross):
                    return True

        # Defensive diagonal printed segments.
        for sx0, sy0, sx1, sy1 in self.diag_segments:
            if max(sx0, sx1) < xmin or min(sx0, sx1) > xmax or max(sy0, sy1) < ymin or min(sy0, sy1) > ymax:
                continue
            if self._diag_hit(x0, y0, x1, y1, sx0, sy0, sx1, sy1):
                return True
        return False


def travel_needs_hop(start, end, span_index: Optional[SpanCollisionIndex], z: float, tower_bbox=None) -> bool:
    if start is None:
        return False
    # Tower boundary crossings are mandatory safety hops.  This is independent
    # of the user z-hop setting because tower entry/exit scraping was a direct
    # observed failure mode.
    if _segment_intersects_tower_bbox(start, end, tower_bbox, inflate=0.35):
        return True
    if Z_HOP_MODE == "off":
        return False
    if span_index is None:
        return False
    return span_index.swept_line_hits(start[0], start[1], end[0], end[1], z, TRAVEL_SWEEP_W_MM)


def _append_ramped_checked_hop_xy(g: List[str], current_xy: Tuple[float, float], target_xy: Tuple[float, float],
                                  z: float, feed: int = 60000, reason: str = "CHECKED_TRAVEL",
                                  e_field: Optional[str] = None,
                                  z_decimals: int = 3) -> None:
    """Emit a checked travel hop by combining XY travel with Z lift/drop.

    This replaces the old conservative sequence:
        G1 Zhop; G1 X/Y; G1 Znormal
    with a Studio-like ramped travel.  For short moves it emits two diagonal
    moves via the midpoint.  For longer moves it ramps up over the first
    PSP_RAMPED_Z_HOP_RAMP_MM, travels at hop Z, then ramps down over the final
    ramp distance.

    Functional lifting remains; only the geometry of the hop changes.
    """
    x0, y0 = float(current_xy[0]), float(current_xy[1])
    x1, y1 = float(target_xy[0]), float(target_xy[1])
    dx, dy = x1 - x0, y1 - y0
    dist = math.hypot(dx, dy)
    zhop = z + HOP_Z_MM
    feed = int(feed)
    zd = max(3, int(z_decimals))
    if dist <= 0.02:
        g.append(f"G1 Z{zhop:.{zd}f} F60000")
        g.append(f"G1 Z{z:.{zd}f} F6000")
        return
    # Negative-E wipe travels are rare.  Keep the E field on the first XY leg so
    # total E command remains unchanged rather than duplicated over multiple legs.
    e_suffix_first = (f" {e_field}" if e_field else "")
    ramp = min(float(PSP_RAMPED_Z_HOP_RAMP_MM), dist / 2.0)
    ux, uy = dx / dist, dy / dist
    if dist <= 2.0 * float(PSP_RAMPED_Z_HOP_RAMP_MM) + 1e-9:
        mx, my = (x0 + x1) * 0.5, (y0 + y1) * 0.5
        g.append(f"G1 X{mx:.3f} Y{my:.3f} Z{zhop:.{zd}f}{e_suffix_first} F{feed}")
        g.append(f"G1 X{x1:.3f} Y{y1:.3f} Z{z:.{zd}f} F{feed}")
    else:
        x_up, y_up = x0 + ux * ramp, y0 + uy * ramp
        x_dn, y_dn = x1 - ux * ramp, y1 - uy * ramp
        g.append(f"G1 X{x_up:.3f} Y{y_up:.3f} Z{zhop:.{zd}f}{e_suffix_first} F{feed}")
        g.append(f"G1 X{x_dn:.3f} Y{y_dn:.3f} Z{zhop:.{zd}f} F{feed}")
        g.append(f"G1 X{x1:.3f} Y{y1:.3f} Z{z:.{zd}f} F{feed}")


def append_checked_travel_xy(g: List[str], current_xy: Optional[Tuple[float, float]], target_xy: Tuple[float, float],
                             z: float, span_index: Optional[SpanCollisionIndex], tower_bbox=None,
                             feed: int = 60000, reason: str = "CHECKED_TRAVEL",
                             force_hop: bool = False, restore_z: bool = False,
                             e_field: Optional[str] = None,
                             z_decimals: int = 3) -> Tuple[Tuple[float, float], bool]:
    """Central checked non-drawing XY movement emitter.

    PPSPV7 keeps the same collision decision as the old V4 checked-travel hop,
    but when a hop is required it uses ramped XY+Z travel instead of separate
    vertical lift / horizontal travel / vertical drop moves.  This is closer to
    the Studio motion style observed in the reference geometry file.
    """
    x, y = target_xy
    zd = max(3, int(z_decimals))
    if current_xy is None:
        # Unknown current XY: only forced hops, otherwise just position and optionally restore Z.
        if force_hop:
            if PSP_EMIT_ZHOP_COMMENTS:
                g.append(f"; V4_ZHOP_START ramped +{HOP_Z_MM:.2f} {reason}")
            # With unknown XY, the first positioning move cannot know a start XY.
            # Avoid a bare Z-only drop by carrying target XY on the lower command.
            g.append(f"G1 Z{z+HOP_Z_MM:.{zd}f} F60000")
            g.append(f"G1 X{x:.3f} Y{y:.3f} Z{z+HOP_Z_MM:.{zd}f}" + (f" {e_field}" if e_field else "") + f" F{int(feed)}")
            g.append(f"G1 X{x:.3f} Y{y:.3f} Z{z:.{zd}f} F6000")
            if PSP_EMIT_ZHOP_COMMENTS:
                g.append(f"; V4_ZHOP_END ramped {reason}")
            return (x, y), True
        # PPSPV51: no-hop travel is already at the current physical layer.
        # Do not emit a redundant X/Y/Z restore command; Bambu Studio can treat
        # huge numbers of non-drawing X/Y/Z moves as layer-view poison.
        g.append(f"G1 X{x:.3f} Y{y:.3f}" + (f" {e_field}" if e_field else "") + f" F{int(feed)}")
        return (x, y), False

    if math.hypot(x - current_xy[0], y - current_xy[1]) <= 0.02:
        # PPSPV51: avoid redundant nominal-layer restores at identical XY.
        # v1.57 exception: a forced variable-height transition must still make
        # the Z state explicit even when the next road begins at the same XY.
        if force_hop:
            _append_vertical_checked_hop_xy(
                g, current_xy, (x, y), z, feed=feed, reason=reason,
                e_field=e_field, restore_z=True, hop_z_mm=HOP_Z_MM,
                z_decimals=zd,
            )
            return (x, y), True
        return (x, y), False

    tower_intersecting_travel = _segment_intersects_tower_bbox(current_xy, (x, y), tower_bbox, inflate=0.35)
    collision_required_travel = False
    if not tower_intersecting_travel and Z_HOP_MODE != "off" and span_index is not None:
        collision_required_travel = span_index.swept_line_hits(
            current_xy[0], current_xy[1], x, y, z, TRAVEL_SWEEP_W_MM
        )
    need = bool(force_hop) or tower_intersecting_travel or collision_required_travel
    if need:
        if PSP_EMIT_ZHOP_COMMENTS:
            if tower_intersecting_travel:
                mode = "tower-vertical"
            elif collision_required_travel:
                mode = "collision-vertical"
            else:
                mode = "forced-vertical"
            g.append(f"; V4_ZHOP_START {mode} +{HOP_Z_MM:.2f} {reason}")
        # PPSPV50: every required checked hop is a Studio-safe vertical-clearance hop with no bare Z-only lift/drop commands.
        # Ramped hops remain available in the code for future experiments, but
        # are not used for any move that the current geometry says requires a hop.
        # PPSPV62: if a non-extruding XY path touches/crosses the tower bbox,
        # use tower clearance rather than the normal 0.40 mm hop.  This models
        # "tower already printed on this active layer" conservatively: any
        # tower-bbox crossing is lifted by TOWER_HOP_Z_MM (0.90 mm), giving
        # >=0.85 mm clearance over the fresh tower top.
        _append_vertical_checked_hop_xy(
            g, current_xy, (x, y), z, feed=feed, reason=reason,
            # PPSPV51: every actual checked hop must return to the real layer Z
            # before the next prime/extrusion.  The old ramped helper always
            # ended at z; restore_z=False was only safe for no-hop travels.
            e_field=e_field, restore_z=True,
            hop_z_mm=(max(HOP_Z_MM, TOWER_HOP_Z_MM) if tower_intersecting_travel else HOP_Z_MM),
            z_decimals=zd,
        )
        if PSP_EMIT_ZHOP_COMMENTS:
            g.append(f"; V4_ZHOP_END vertical {reason}")
        return (x, y), True

    # PPSPV51: no-hop travel is already at the current physical layer.  Avoid
    # redundant X/Y/Z current-layer restore commands; they were the remaining
    # high-volume Bambu Studio layer-view poison after PPSPV50.
    g.append(f"G1 X{x:.3f} Y{y:.3f}" + (f" {e_field}" if e_field else "") + f" F{int(feed)}")
    return (x, y), False

def seg_xy(seg):
    return tuple(seg[:4])

def seg_dose(seg) -> float:
    try:
        return float(seg[4])
    except Exception:
        return 1.0


def seg_height_fraction(seg) -> float:
    """Return a direct 4x4 carrier-height fraction carried by a segment.

    Ordinary/card/4x2 segments have no sixth field and therefore remain at the
    nominal physical-layer plane.  A 4x4 normal or filter segment carries the
    local normal-carrier fraction in field six.  The value is already limited
    to 0..1 when the direct input is decoded; no low-dose floor is applied.
    """
    try:
        return float(seg[5])
    except Exception:
        return 1.0


def seg_has_height_fraction(seg) -> bool:
    try:
        return len(seg) >= 6
    except Exception:
        return False


def seg_height_profile_index(seg) -> int:
    try:
        return int(seg[6])
    except Exception:
        return -1


def direct_carrier_print_z(
    physical_layer: int,
    height_fraction: float,
    extra_depth_mm: float = 0.0,
) -> float:
    """Return the literal-Z equivalent for one variable-height 4x4 group.

    ``physical_layer`` is the one-based optical layer number used by the main
    emission loop (1..8).  The lower nominal plane remains fixed even when an
    earlier carrier incurred a height debt; this revision deliberately exposes
    that inter-layer interaction for testing.
    """
    physical_layer = int(physical_layer)
    if physical_layer < 1:
        raise ValueError("variable carrier height requires an optical physical layer >= 1")
    fraction = float(height_fraction)
    extra_depth = float(extra_depth_mm)
    if not math.isfinite(fraction) or fraction < 0.0 or fraction > 1.0 + 1e-9:
        raise ValueError(f"carrier height fraction must be finite in 0..1, got {height_fraction!r}")
    if not math.isfinite(extra_depth) or extra_depth < 0.0:
        raise ValueError(f"extra depth must be finite and non-negative, got {extra_depth_mm!r}")
    lower_nominal_z = BASE_H_MM + (physical_layer - 1) * MIX_H_MM
    return float(
        lower_nominal_z
        + min(1.0, max(0.0, fraction)) * MIX_H_MM
        - extra_depth
    )


def direct_carrier_z_trim(
    height_fraction: float,
    baseline_trim_mm: float = 0.0,
    extra_depth_mm: float = 0.0,
) -> float:
    """Return the absolute H2C ``G29.1 Z`` value for one direct group.

    The G-code model remains at the nominal logical-layer Z.  A negative
    additional trim lowers the physical nozzle by the height deliberately
    omitted from a sub-100% carrier:

        absolute trim = inherited baseline - extra depth - (1 - fraction) * 0.10 mm

    This is geometrically equivalent to the v1.57-v1.59 literal-Z rule while
    keeping every model extrusion at one nominal Z for Bambu Studio's layer
    classifier.  ``G29.1`` is treated as an absolute setting, never accumulated.
    """
    fraction = float(height_fraction)
    baseline = float(baseline_trim_mm)
    extra_depth = float(extra_depth_mm)
    if not math.isfinite(fraction) or fraction < 0.0 or fraction > 1.0 + 1e-9:
        raise ValueError(f"carrier height fraction must be finite in 0..1, got {height_fraction!r}")
    if not math.isfinite(baseline):
        raise ValueError(f"baseline Z trim must be finite, got {baseline_trim_mm!r}")
    if not math.isfinite(extra_depth) or extra_depth < 0.0:
        raise ValueError(f"extra depth must be finite and non-negative, got {extra_depth_mm!r}")
    return float(
        baseline
        - extra_depth
        - (1.0 - min(1.0, max(0.0, fraction))) * MIX_H_MM
    )


def extract_active_h2c_z_trim(lines: Sequence[str]) -> float:
    """Return the last executable absolute G29.1 Z value in a startup stream."""
    values: List[float] = []
    for line_number, line in enumerate(lines, start=1):
        parsed = parse_gcode_line(str(line), line_number, strict=True)
        if parsed.command != "G29.1":
            continue
        z_word = parsed.optional_word("Z")
        if z_word is None or z_word[1].numeric is None:
            raise RuntimeError(f"H2C startup G29.1 at line {line_number} lacks one numeric Z value")
        values.append(float(z_word[1].numeric))
    if not values:
        raise RuntimeError("H2C startup contains no executable G29.1 Z baseline")
    return float(values[-1])


def get_build_plate_profile(build_plate: str) -> Dict[str, object]:
    key = str(build_plate).strip()
    profile = BUILD_PLATE_PROFILES.get(key)
    if profile is None:
        raise ValueError(
            f"Unknown build plate {build_plate!r}; expected one of {sorted(BUILD_PLATE_PROFILES)}"
        )
    return dict(profile)


def audit_build_plate_startup(lines: Sequence[str], build_plate: str) -> Dict[str, object]:
    """Fail closed unless one rendered H2C startup exactly matches the requested plate."""
    profile = get_build_plate_profile(build_plate)
    display_name = str(profile["display_name"])
    expected_m972 = str(profile["startup_m972"])
    expected_trim = float(profile["startup_z_trim"])
    all_m972 = {str(p["startup_m972"]) for p in BUILD_PLATE_PROFILES.values()}

    header = f"; curr_bed_type = {display_name}"
    header_count = sum(1 for line in lines if str(line).strip() == header)
    if header_count != 1:
        raise RuntimeError(
            f"H2C build-plate startup audit expected one {header!r}, found {header_count}"
        )

    expected_m972_count = sum(1 for line in lines if str(line).strip() == expected_m972)
    if expected_m972_count != 1:
        raise RuntimeError(
            f"H2C build-plate startup audit expected one {expected_m972!r}, found {expected_m972_count}"
        )
    stale_m972 = [
        command for command in sorted(all_m972 - {expected_m972})
        if any(str(line).strip() == command for line in lines)
    ]
    if stale_m972:
        raise RuntimeError(f"H2C build-plate startup audit found stale plate M972 commands: {stale_m972}")

    marker_indices = [
        i for i, line in enumerate(lines)
        if str(line).strip().startswith(";===== for Textured PEI Plate , lower the nozzle")
    ]
    if len(marker_indices) != 1:
        raise RuntimeError(
            f"H2C build-plate startup audit expected one textured-offset marker, found {len(marker_indices)}"
        )
    marker = marker_indices[0]
    try:
        region_end = next(
            i for i in range(marker + 1, len(lines))
            if str(lines[i]).strip() == "G150.1"
        )
    except StopIteration as exc:
        raise RuntimeError("H2C build-plate startup audit cannot find G150.1 after plate offset marker") from exc

    textured_offset_lines = [
        str(line).strip() for line in lines[marker + 1:region_end]
        if str(line).strip().startswith("G29.1 Z")
    ]
    if build_plate == "tex_plate":
        expected_offset_line = "G29.1 Z-0.02 ; for Textured PEI Plate"
        if textured_offset_lines != [expected_offset_line]:
            raise RuntimeError(
                "H2C textured build-plate startup audit expected exactly "
                f"{expected_offset_line!r}, got {textured_offset_lines!r}"
            )
    elif textured_offset_lines:
        raise RuntimeError(
            f"H2C engineering build-plate startup audit found unexpected plate offset: {textured_offset_lines}"
        )

    actual_trim = extract_active_h2c_z_trim(lines)
    if abs(actual_trim - expected_trim) > 5e-7:
        raise RuntimeError(
            f"H2C build-plate startup trim {actual_trim:.5f} != expected {expected_trim:.5f} for {build_plate}"
        )
    return {
        "build_plate": str(build_plate),
        "display_name": display_name,
        "plate_json_value": str(profile["plate_json_value"]),
        "m972": expected_m972,
        "z_trim": actual_trim,
        "result": "PASS",
    }


def apply_build_plate_profile_to_startup(
    lines: Sequence[str], build_plate: str
) -> Tuple[List[str], Dict[str, object]]:
    """Resolve the embedded Engineering-plate startup to one explicit H2C plate profile."""
    profile = get_build_plate_profile(build_plate)
    out = [str(line) for line in lines]
    display_name = str(profile["display_name"])
    expected_m972 = str(profile["startup_m972"])
    all_m972 = {str(p["startup_m972"]) for p in BUILD_PLATE_PROFILES.values()}

    header_indices = [i for i, line in enumerate(out) if str(line).startswith("; curr_bed_type = ")]
    if len(header_indices) != 1:
        raise RuntimeError(
            f"H2C build-plate patch expected one curr_bed_type header, found {len(header_indices)}"
        )
    out[header_indices[0]] = f"; curr_bed_type = {display_name}"

    m972_indices = [i for i, line in enumerate(out) if str(line).strip() in all_m972]
    if len(m972_indices) != 1:
        raise RuntimeError(
            f"H2C build-plate patch expected one resolved plate M972 command, found {len(m972_indices)}"
        )
    out[m972_indices[0]] = expected_m972

    marker_indices = [
        i for i, line in enumerate(out)
        if str(line).strip().startswith(";===== for Textured PEI Plate , lower the nozzle")
    ]
    if len(marker_indices) != 1:
        raise RuntimeError(
            f"H2C build-plate patch expected one textured-offset marker, found {len(marker_indices)}"
        )
    marker = marker_indices[0]
    try:
        region_end = next(
            i for i in range(marker + 1, len(out))
            if str(out[i]).strip() == "G150.1"
        )
    except StopIteration as exc:
        raise RuntimeError("H2C build-plate patch cannot find G150.1 after plate offset marker") from exc

    kept_region: List[str] = []
    removed_offsets = 0
    for line in out[marker + 1:region_end]:
        stripped = str(line).strip()
        if stripped.startswith("G29.1 Z") and "Textured PEI Plate" in stripped:
            removed_offsets += 1
            continue
        kept_region.append(str(line))
    if removed_offsets > 1:
        raise RuntimeError(
            f"H2C build-plate patch found {removed_offsets} pre-existing textured offset commands"
        )
    if build_plate == "tex_plate":
        kept_region.append("G29.1 Z-0.02 ; for Textured PEI Plate")
    out = out[:marker + 1] + kept_region + out[region_end:]
    audit = audit_build_plate_startup(out, build_plate)
    return out, audit


def quantize_direct_g29_trim_5dp(value: float) -> float:
    """Return the exact numeric value represented by an emitted G29.1 Z trim.

    Direct variable-height G29.1 commands are serialized with five decimal
    places.  All change/no-change decisions must therefore be made in that same
    representable space, not against the higher-precision intermediate float.
    """
    return float(f"{float(value):.5f}")


def append_direct_z_trim_begin(
    g: List[str],
    current_xy: Optional[Tuple[float, float]],
    nominal_z: float,
    target_trim_mm: float,
    baseline_trim_mm: float,
    context: str,
    *,
    allow_nonlowered: bool = False,
) -> None:
    """Enter a fixed direct-Z trim group from a safe, baseline-trimmed height.

    Normal FC3D carrier/filter groups remain fail-closed to lowered trims. The
    explicit continuous Studio-representation experiment may opt in to a trim
    at/above the plate baseline because its direct G1 Z is shifted equally and
    oppositely, preserving physical nozzle Z.
    """
    if current_xy is None:
        raise RuntimeError(f"Cannot enter direct Z-trim group with unknown XY state: {context}")
    if (not allow_nonlowered) and float(target_trim_mm) >= float(baseline_trim_mm) - 1e-9:
        raise RuntimeError(f"Direct Z-trim begin requires a lowered target: {context}")
    x, y = float(current_xy[0]), float(current_xy[1])
    safe_command_z = float(nominal_z) + HOP_Z_MM
    g.append(
        f"; FC3D_DIRECT_Z_TRIM_BEGIN {context} target={float(target_trim_mm):.5f} "
        f"baseline={float(baseline_trim_mm):.5f} safe_command_z={safe_command_z:.5f}"
    )
    g.append("G90 ; FC3D_DIRECT_Z_TRIM_ABSOLUTE_XYZ")
    # Lift using the inherited baseline before changing the coordinate trim.
    g.append(
        f"G1 X{x:.3f} Y{y:.3f} Z{safe_command_z:.5f} F1200 "
        "; FC3D_DIRECT_Z_TRIM_SAFE_LIFT_BASELINE"
    )
    g.append("M400 ; FC3D_DIRECT_Z_TRIM_DRAIN_BEFORE_SET")
    g.append(f"G29.1 Z{float(target_trim_mm):.5f} ; FC3D_DIRECT_Z_TRIM_SET_ABSOLUTE")
    g.append("M400 ; FC3D_DIRECT_Z_TRIM_DRAIN_AFTER_SET")
    # Re-command the same safe model coordinate so the new absolute trim is
    # physically realised before any lateral group movement.
    g.append(
        f"G1 X{x:.3f} Y{y:.3f} Z{safe_command_z:.5f} F1200 "
        "; FC3D_DIRECT_Z_TRIM_APPLY_AT_SAFE_Z"
    )
    g.append("M400 ; FC3D_DIRECT_Z_TRIM_APPLIED")


def append_direct_z_trim_restore(
    g: List[str],
    current_xy: Optional[Tuple[float, float]],
    nominal_z: float,
    active_trim_mm: float,
    baseline_trim_mm: float,
    context: str,
) -> None:
    """Leave a lowered 4x4 group safely and restore the inherited baseline."""
    if current_xy is None:
        raise RuntimeError(f"Cannot restore direct Z trim with unknown XY state: {context}")
    x, y = float(current_xy[0]), float(current_xy[1])
    safe_command_z = float(nominal_z) + HOP_Z_MM
    g.append(
        f"; FC3D_DIRECT_Z_TRIM_RESTORE {context} active={float(active_trim_mm):.5f} "
        f"baseline={float(baseline_trim_mm):.5f} safe_command_z={safe_command_z:.5f}"
    )
    g.append("G90 ; FC3D_DIRECT_Z_TRIM_ABSOLUTE_XYZ")
    # Lift while the lowered trim is still active, then restore at the safe
    # coordinate.  A final same-coordinate command realises the baseline before
    # any following tower, tool change, physical-layer header, or finish macro.
    g.append(
        f"G1 X{x:.3f} Y{y:.3f} Z{safe_command_z:.5f} F1200 "
        "; FC3D_DIRECT_Z_TRIM_SAFE_LIFT_ACTIVE"
    )
    g.append("M400 ; FC3D_DIRECT_Z_TRIM_DRAIN_BEFORE_RESTORE")
    g.append(f"G29.1 Z{float(baseline_trim_mm):.5f} ; FC3D_DIRECT_Z_TRIM_RESTORE_ABSOLUTE")
    g.append("M400 ; FC3D_DIRECT_Z_TRIM_DRAIN_AFTER_RESTORE")
    g.append(
        f"G1 X{x:.3f} Y{y:.3f} Z{safe_command_z:.5f} F1200 "
        "; FC3D_DIRECT_Z_TRIM_BASELINE_AT_SAFE_Z"
    )
    g.append("M400 ; FC3D_DIRECT_Z_TRIM_BASELINE_CONFIRMED")


def direct_inter_profile_reset_config() -> Optional[Dict[str, object]]:
    spec = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
    if not isinstance(spec, dict):
        return None
    cfg = spec.get("inter_profile_reset")
    if isinstance(cfg, dict) and bool(cfg.get("enabled", False)):
        return dict(cfg)
    return None


def append_direct_continuous_variable_dose_rows(
    g: List[str],
    segs: Sequence[tuple],
    physical_layer: int,
    nominal_z: float,
    layer_height: float,
    current_xy: Optional[Tuple[float, float]],
    span_index,
    tower_bbox,
    line_width: float,
    feed: int,
    endpoint_trim_mm: float = 0.0,
    baseline_trim_mm: float = 0.0,
    material=None,
) -> Tuple[Optional[Tuple[float, float]], Dict[str, object]]:
    """Emit marked continuous rows as one pressure-live road per scanline.

    Internal dose boundaries normally use one coordinated X/Z/E move centred
    on the boundary. Profiles may override selected alpha-pairs with a custom
    blend distance or a stationary Z step. Profiles may also apply a small
    alpha-keyed depth adjustment, linearly interpolated between supplied
    control points. This is intended for tightly-scoped low-dose diagnostics.
    """
    rows: Dict[float, List[tuple]] = {}
    for seg in segs:
        x0, y0, x1, y1 = (float(v) for v in seg_xy(seg))
        if abs(y1 - y0) > 1e-5:
            raise RuntimeError("continuous variable-dose rows currently require X-oriented roads")
        rows.setdefault(round((y0 + y1) * 0.5, 5), []).append(seg)
    stats = {
        "continuous_variable_dose_scanlines": 0,
        "continuous_variable_dose_blocks": 0,
        "continuous_variable_dose_z_boundaries": 0,
        "continuous_variable_dose_blend_moves": 0,
        "continuous_variable_dose_stationary_boundaries": 0,
        "continuous_variable_dose_boundary_snaps": 0,
        "continuous_variable_dose_delayed_z_transitions": 0,
        "continuous_variable_dose_delayed_z_mm": 0.0,
        "continuous_variable_dose_z_ramp_mm": 0.0,
        "continuous_variable_dose_stationary_recovery_mm": 0.0,
        "continuous_variable_dose_stationary_retract_mm": 0.0,
        "continuous_g29_anchored_scanlines": 0,
    }

    def _alpha_for_fraction(frac: float) -> int:
        return max(0, min(128, int(round(float(frac) * 128.0))))

    def _depth_adjustment(profile: Dict[str, object], alpha: int) -> float:
        raw = profile.get("depth_adjustment_points_by_alpha", [])
        if not raw:
            return 0.0
        pts = []
        for item in raw:
            if not isinstance(item, (list, tuple)) or len(item) != 2:
                raise RuntimeError("depth_adjustment_points_by_alpha entries must be [alpha, mm]")
            a = int(item[0]); mm = float(item[1])
            if a < 0 or a > 128 or not math.isfinite(mm) or abs(mm) > 0.02:
                raise RuntimeError(f"unsafe depth adjustment point {item!r}")
            pts.append((a, mm))
        pts.sort()
        if alpha <= pts[0][0]:
            return float(pts[0][1])
        if alpha >= pts[-1][0]:
            return float(pts[-1][1])
        for (a0, v0), (a1, v1) in zip(pts, pts[1:]):
            if a0 <= alpha <= a1:
                t = (alpha - a0) / float(a1 - a0)
                return v0 + t * (v1 - v0)
        return 0.0

    def _transition_spec(profile: Dict[str, object], a_alpha: int, b_alpha: int) -> Tuple[str, float]:
        default_blend = float(profile.get("continuous_transition_blend_mm", 0.20))
        mode = "blend"
        blend = default_blend
        key = tuple(sorted((int(a_alpha), int(b_alpha))))
        for item in profile.get("continuous_transition_overrides", []):
            if not isinstance(item, dict):
                raise RuntimeError("continuous_transition_overrides entries must be objects")
            if "alpha_pair" not in item:
                raise RuntimeError("continuous transition override missing alpha_pair")
            pair = item["alpha_pair"]
            if not isinstance(pair, (list, tuple)) or len(pair) != 2:
                raise RuntimeError("continuous transition alpha_pair must have two values")
            pkey = tuple(sorted((int(pair[0]), int(pair[1]))))
            if pkey != key:
                continue
            mode = str(item.get("mode", "blend")).strip().lower()
            if mode not in {"blend", "stationary"}:
                raise RuntimeError(f"unsupported continuous transition mode {mode!r}")
            if mode == "blend":
                blend = float(item.get("blend_mm", default_blend))
            else:
                blend = 0.0
            break
        if not math.isfinite(blend) or blend < 0.0 or blend > 1.0:
            raise RuntimeError(f"unsafe continuous transition blend {blend!r} mm")
        return mode, blend

    endpoint_trim_each_end_mm = 0.5 * max(0.0, float(endpoint_trim_mm))

    for road_i, fixed in enumerate(sorted(rows)):
        spans = sorted(rows[fixed], key=lambda seg: min(float(seg[0]), float(seg[2])))
        if not spans:
            continue
        preview_profile = direct_zoffset_height_profile(seg_height_profile_index(spans[0]))
        direction_mode = str(preview_profile.get("continuous_scanline_direction", "serpentine"))
        reverse = bool(road_i % 2) if direction_mode == "serpentine" else False
        if reverse:
            spans = list(reversed(spans))

        def oriented(seg):
            x0, y0, x1, y1 = (float(v) for v in seg_xy(seg))
            if reverse:
                return (max(x0, x1), fixed), (min(x0, x1), fixed)
            return (min(x0, x1), fixed), (max(x0, x1), fixed)

        blocks = []
        for seg in spans:
            p0, p1 = oriented(seg)
            # The raster compiler has already applied the global endpoint
            # inset to each compiled source span.  For a pressure-live
            # continuous row those per-block insets are artificial planner
            # boundaries, so first reconstruct the original contiguous block
            # geometry here.  v1.93 then trims only the two true physical road
            # endpoints once, after the complete road has been assembled.
            if endpoint_trim_each_end_mm > 0.0:
                if reverse:
                    p0 = (float(p0[0]) + endpoint_trim_each_end_mm, float(p0[1]))
                    p1 = (float(p1[0]) - endpoint_trim_each_end_mm, float(p1[1]))
                else:
                    p0 = (float(p0[0]) - endpoint_trim_each_end_mm, float(p0[1]))
                    p1 = (float(p1[0]) + endpoint_trim_each_end_mm, float(p1[1]))
            fraction = min(1.0, max(0.0, seg_height_fraction(seg)))
            alpha = _alpha_for_fraction(fraction)
            profile_index = seg_height_profile_index(seg)
            profile = direct_zoffset_height_profile(profile_index)
            depth = direct_zoffset_total_depth_mm(fraction, profile_index) + _depth_adjustment(profile, alpha)
            if depth < 0.0 or depth > 0.20:
                raise RuntimeError(f"adjusted continuous-row depth out of range: {depth:.6f} mm")
            target_z = direct_total_depth_print_z(int(physical_layer), depth)
            dose = float(seg_dose(seg))
            blocks.append({"seg": seg, "p0": p0, "p1": p1, "fraction": fraction,
                           "alpha": alpha, "profile_index": profile_index, "profile": profile,
                           "z": target_z, "depth": depth, "dose": dose})
        if not blocks:
            continue

        # v1.93 true-road-end semantics: apply endpoint trim exactly once to
        # the two physical ends of the complete pressure-live road.  Internal
        # dose/Z/E boundaries remain at their original coordinates.
        if endpoint_trim_each_end_mm > 0.0:
            road_direction = 1.0 if float(blocks[0]["p1"][0]) > float(blocks[0]["p0"][0]) else -1.0
            first = blocks[0]
            last = blocks[-1]
            first["p0"] = (float(first["p0"][0]) + road_direction * endpoint_trim_each_end_mm, float(first["p0"][1]))
            last["p1"] = (float(last["p1"][0]) - road_direction * endpoint_trim_each_end_mm, float(last["p1"][1]))
            if abs(float(first["p1"][0]) - float(first["p0"][0])) < float(MIN_TRIMMED_SEGMENT_MM):
                raise RuntimeError("continuous-row first block too short after true endpoint trim")
            if abs(float(last["p1"][0]) - float(last["p0"][0])) < float(MIN_TRIMMED_SEGMENT_MM):
                raise RuntimeError("continuous-row last block too short after true endpoint trim")
            g.append(
                f"; FC3D_CONTINUOUS_TRUE_ENDPOINT_TRIM total={float(endpoint_trim_mm):.4f} "
                f"each_end={endpoint_trim_each_end_mm:.4f} "
                f"start_x={float(first['p0'][0]):.3f} end_x={float(last['p1'][0]):.3f}"
            )

        # Every block in one row must use the same profile so transition policy is unambiguous.
        profile_ids = {int(b["profile_index"]) for b in blocks}
        if len(profile_ids) != 1:
            raise RuntimeError("one continuous row must use one print profile")
        profile = blocks[0]["profile"]
        transition_z_delay_mm = float(profile.get("continuous_transition_z_delay_mm", 0.0) or 0.0)
        transition_z_ramp_mm = float(profile.get("continuous_transition_z_ramp_mm", 0.0) or 0.0)
        hard_g29_step = bool(profile.get("continuous_hard_g29_step", False))
        delayed_z_transition = hard_g29_step or transition_z_delay_mm > 1e-9 or transition_z_ramp_mm > 1e-9

        # v1.104 lineage/isolation support: honour explicit profile-level physical
        # start/end trims on continuous rows too.  The legacy continuous path
        # reconstructs per-block compiler insets and then applies the global
        # endpoint trim.  With an in-card transparent margin the compiled source
        # span itself can begin/end 0.10 mm farther out than the old edge-of-card
        # v3.2 geometry.  Explicit profile trims are therefore applied here, once,
        # to the already chained true physical road endpoints.  None preserves the
        # established v1.103 behaviour exactly.
        _profile_start_trim = profile.get("start_trim_mm")
        _profile_end_trim = profile.get("end_trim_mm")
        if _profile_start_trim is not None or _profile_end_trim is not None:
            _st = 0.0 if _profile_start_trim is None else float(_profile_start_trim)
            _et = 0.0 if _profile_end_trim is None else float(_profile_end_trim)
            _rd = 1.0 if float(blocks[0]["p1"][0]) > float(blocks[0]["p0"][0]) else -1.0
            blocks[0]["p0"] = (float(blocks[0]["p0"][0]) + _rd * _st, float(blocks[0]["p0"][1]))
            blocks[-1]["p1"] = (float(blocks[-1]["p1"][0]) - _rd * _et, float(blocks[-1]["p1"][1]))
            if abs(float(blocks[0]["p1"][0]) - float(blocks[0]["p0"][0])) < float(MIN_TRIMMED_SEGMENT_MM):
                raise RuntimeError("continuous-row first block too short after explicit profile start trim")
            if abs(float(blocks[-1]["p1"][0]) - float(blocks[-1]["p0"][0])) < float(MIN_TRIMMED_SEGMENT_MM):
                raise RuntimeError("continuous-row last block too short after explicit profile end trim")
            g.append(
                f"; FC3D_CONTINUOUS_PROFILE_ENDPOINT_TRIM start_trim={_st:.3f} end_trim={_et:.3f} "
                f"start_x={float(blocks[0]['p0'][0]):.3f} end_x={float(blocks[-1]['p1'][0]):.3f}"
            )

        anchor_alpha_raw = profile.get("continuous_g29_anchor_alpha")
        anchor_alpha = None if anchor_alpha_raw is None else int(anchor_alpha_raw)
        live_g29_span = profile.get("continuous_live_g29_residual_z_span_mm")
        live_g29_steps = int(profile.get("continuous_live_g29_steps", 0))
        live_g29_mode = live_g29_span is not None
        anchor_trim = None
        anchor_command_shift = 0.0
        representation_shift_mm = float(profile.get("continuous_g29_representation_shift_mm", 0.0) or 0.0)
        if live_g29_mode:
            first_physical_z = float(blocks[0]["z"]) + float(baseline_trim_mm)
            anchor_trim = first_physical_z - float(nominal_z)
            anchor_command_shift = float(nominal_z) - float(blocks[0]["z"])
            if anchor_trim >= float(baseline_trim_mm) - 1e-9:
                raise RuntimeError("live G29 hybrid mode requires a lowered starting trim")
        elif anchor_alpha is not None:
            if anchor_alpha < 0 or anchor_alpha > 128:
                raise RuntimeError(f"continuous_g29_anchor_alpha out of range: {anchor_alpha}")
            anchor_fraction = float(anchor_alpha) / 128.0
            profile_index = int(blocks[0]["profile_index"])
            anchor_depth = direct_zoffset_total_depth_mm(anchor_fraction, profile_index) + _depth_adjustment(profile, anchor_alpha)
            anchor_trim = direct_total_depth_z_trim(anchor_depth, float(baseline_trim_mm))
            anchor_command_shift = float(baseline_trim_mm) - float(anchor_trim)
            if anchor_trim >= float(baseline_trim_mm) - 1e-9:
                raise RuntimeError("G29.1 anchored continuous mode requires a lowered anchor trim")
            # v1.107 Studio-representation-only translation. A positive shift raises
            # G29.1 by that amount and lowers every direct G1 Z by the same amount,
            # so (direct Z + G29.1) and therefore physical nozzle Z are unchanged.
            if abs(representation_shift_mm) > 1e-12:
                anchor_trim += representation_shift_mm
                anchor_command_shift -= representation_shift_mm
                # Diagnostic representation shifts are allowed to cross the
                # inherited plate baseline. Physical nozzle Z is unchanged
                # because anchor_command_shift moves by the equal/opposite amount.
                if not (-0.120 <= float(anchor_trim) <= 0.080):
                    raise RuntimeError(
                        f"continuous G29 representation shift produced unsafe absolute trim {anchor_trim:.5f} mm"
                    )
            if hard_g29_step:
                # Pure hard-G29 diagnostic: model/direct Z is exactly nominal for the
                # entire road. G29.1 alone carries both the source and destination
                # physical VE-dependent heights. This cleanly isolates Studio's
                # response to G29.1 from any intra-road G1 Z change.
                _source_physical_z = float(blocks[0]["z"]) + float(baseline_trim_mm)
                anchor_trim = _source_physical_z - float(nominal_z)
                anchor_command_shift = float(nominal_z) - float(blocks[0]["z"])
                if not (-0.120 <= float(anchor_trim) <= 0.080):
                    raise RuntimeError(
                        f"continuous hard G29 source trim outside diagnostic safety range {anchor_trim:.5f} mm"
                    )

        # Raster-vector compilation can represent two touching source blocks with
        # a tiny centreline overlap/gap (typically one RP pitch = 0.20 mm) when
        # the continuous strip sits inside transparent card margins.  The source
        # contract for this path is explicitly pressure-live and contiguous, so
        # normalise only these small internal boundary discrepancies to their
        # midpoint.  Larger gaps remain a hard error and cannot be silently joined.
        for a, b in zip(blocks, blocks[1:]):
            dx = float(b["p0"][0]) - float(a["p1"][0])
            dy = float(b["p0"][1]) - float(a["p1"][1])
            boundary_delta = math.hypot(dx, dy)
            if boundary_delta > 0.03:
                if boundary_delta > 0.25 or abs(dy) > 0.03:
                    raise RuntimeError("continuous variable-dose row contains a non-contiguous block gap")
                mid_x = 0.5 * (float(a["p1"][0]) + float(b["p0"][0]))
                mid_y = 0.5 * (float(a["p1"][1]) + float(b["p0"][1]))
                a["p1"] = (mid_x, mid_y)
                b["p0"] = (mid_x, mid_y)
                stats["continuous_variable_dose_boundary_snaps"] += 1
                g.append(
                    f"; FC3D_CONTINUOUS_BOUNDARY_SNAP delta={boundary_delta:.3f} "
                    f"x={mid_x:.3f} y={mid_y:.3f}"
                )

        transitions = []
        for a, b in zip(blocks, blocks[1:]):
            if math.hypot(float(a["p1"][0])-float(b["p0"][0]), float(a["p1"][1])-float(b["p0"][1])) > 0.03:
                raise RuntimeError("continuous variable-dose row contains a non-contiguous block gap after boundary normalisation")
            mode, blend = _transition_spec(profile, int(a["alpha"]), int(b["alpha"]))
            min_len = min(abs(float(a["p1"][0])-float(a["p0"][0])), abs(float(b["p1"][0])-float(b["p0"][0])))
            if mode == "blend" and blend >= min_len - 1e-6:
                raise RuntimeError("continuous transition blend must be shorter than neighbouring dose blocks")
            transitions.append({"mode": mode, "blend_mm": blend})

        if delayed_z_transition:
            for _tr in transitions:
                if str(_tr["mode"]) != "blend" or abs(float(_tr["blend_mm"])) > 1e-9:
                    raise RuntimeError(
                        "delayed-Z diagnostic requires continuous_transition_blend_mm=0 "
                        "and no stationary/positive-blend transition override"
                    )

        g.append(
            f"; FC3D_CONTINUOUS_SCANLINE_DIRECTION mode={direction_mode} road={road_i+1} reverse={int(reverse)}"
        )
        first_start = blocks[0]["p0"]
        current_xy, _ = append_checked_travel_xy(
            g, current_xy, first_start, nominal_z, span_index, tower_bbox,
            feed=60000, reason="CONTINUOUS_VARIABLE_DOSE_ROW_START", restore_z=True,
            force_hop=True, z_decimals=5,
        )
        if anchor_trim is not None:
            append_direct_z_trim_begin(
                g, current_xy, nominal_z, float(anchor_trim), float(baseline_trim_mm),
                context=(
                    f"continuous_profile={profile.get('id', 'unknown')} road={road_i+1} "
                    + (f"live_g29_span={float(live_g29_span):.5f} steps={live_g29_steps}" if live_g29_mode else f"anchor_alpha={anchor_alpha} representation_shift={representation_shift_mm:+.5f} hard_g29_step={int(hard_g29_step)}")
                ),
                allow_nonlowered=(not live_g29_mode and abs(representation_shift_mm) > 1e-12),
            )
            stats["continuous_g29_anchored_scanlines"] += 1
        scan_mode = dict(profile.get("scanline_mode", {}))
        stationary_recovery_mm = float(scan_mode.get("stationary_recovery_mm", 0.400))
        stationary_recovery_feed_mm_min = float(scan_mode.get("stationary_recovery_feed_mm_min", DIRECT_REFERENCE_RETRACT_FEED_MM_MIN))
        stationary_recovery_dwell_ms = int(scan_mode.get("stationary_recovery_dwell_ms", 0))
        stationary_recovery_components = list(scan_mode.get("stationary_recovery_components", []))
        start_shape_len = float(scan_mode.get("start_underfeed_length_mm", 0.0) or 0.0)
        start_shape_factor = float(scan_mode.get("start_underfeed_factor", 1.0))
        end_shape_len = float(scan_mode.get("end_underfeed_length_mm", 0.0) or 0.0)
        end_shape_factor = float(scan_mode.get("end_underfeed_factor", 1.0))
        end_flow_ramp_distance_mm = float(scan_mode.get("end_flow_ramp_distance_mm", 0.0) or 0.0)
        end_flow_ramp_final_factor = float(scan_mode.get("end_flow_ramp_final_factor", 0.0))
        flow_ramp_steps = int(scan_mode.get("flow_ramp_steps", 4))
        end_z_relief_distance_mm = float(scan_mode.get("end_z_relief_distance_mm", 0.0) or 0.0)
        end_z_relief_mm = float(scan_mode.get("end_z_relief_mm", 0.0) or 0.0)
        end_coast_distance_mm = float(scan_mode.get("end_coast_distance_mm", 0.0) or 0.0)
        moving_retract_mm = float(scan_mode.get("moving_retract_mm", 0.0))
        final_retract_mm = float(scan_mode.get("final_retract_mm", 0.400))
        wipe_distance_mm = float(scan_mode.get("wipe_distance_mm", 0.0))
        stationary_retract_components_mm = [float(v) for v in scan_mode.get("stationary_retract_components_mm", [])]
        total_retract_mm = sum(stationary_retract_components_mm) if stationary_retract_components_mm else (moving_retract_mm + final_retract_mm)
        first_z = float(blocks[0]["z"]) + float(anchor_command_shift)
        g.append(f"G1 Z{first_z:.5f} F1200 ; FC3D_CONTINUOUS_ROW_SET_Z block=1 alpha={int(blocks[0]['alpha'])} g29_anchor={anchor_alpha if anchor_alpha is not None else 'none'} representation_shift={representation_shift_mm:+.5f}")
        if stationary_recovery_components:
            for _ri, _comp in enumerate(stationary_recovery_components, 1):
                _mm = float(_comp["mm"]); _rf = int(round(float(_comp["feed_mm_min"])))
                g.append(f"G1 E{_mm:.5f} F{_rf} ; FC3D_CONTINUOUS_ROW_STATIONARY_RECOVERY_COMPONENT mode={profile.get('id','unknown')} part={_ri}/{len(stationary_recovery_components)}")
        else:
            g.append(
                f"G1 E{stationary_recovery_mm:.5f} F{int(round(stationary_recovery_feed_mm_min))} ; FC3D_CONTINUOUS_ROW_STATIONARY_RECOVERY "
                f"mode={profile.get('id','unknown')}"
            )
        if stationary_recovery_dwell_ms > 0:
            g.append(f"G4 P{stationary_recovery_dwell_ms} ; FC3D_CONTINUOUS_ROW_RECOVERY_DWELL mode={profile.get('id','unknown')}")
        stats["continuous_variable_dose_stationary_recovery_mm"] += float(stationary_recovery_mm)
        cursor = first_start
        direction = 1.0 if float(blocks[0]["p1"][0]) > float(blocks[0]["p0"][0]) else -1.0
        base_e_per_mm = e_for_len(1.0, layer_height, line_width, material=material)
        delayed_entry_consumed_mm = [0.0 for _ in blocks]

        for i, block in enumerate(blocks):
            prev_half = 0.0 if i == 0 else 0.5 * float(transitions[i-1]["blend_mm"])
            next_half = 0.0 if i == len(blocks)-1 else 0.5 * float(transitions[i]["blend_mm"])
            block_start_x = float(block["p0"][0]) + direction * (prev_half + float(delayed_entry_consumed_mm[i]))
            block_end_x = float(block["p1"][0]) - direction * next_half
            _negative_g29_lead_mm = (
                max(0.0, -float(transition_z_delay_mm))
                if (hard_g29_step and i < len(blocks)-1) else 0.0
            )
            if _negative_g29_lead_mm > 1e-12:
                block_end_x -= direction * _negative_g29_lead_mm
            # cursor should already be at block_start_x after previous transition.
            if abs(float(cursor[0]) - block_start_x) > 1e-4:
                raise RuntimeError(f"continuous-row cursor mismatch {cursor[0]:.5f} vs {block_start_x:.5f}")
            flat_len = abs(block_end_x - block_start_x)
            if flat_len > 1e-7:
                # v1.101 endpoint pressure-shaping for continuous-road diagnostics.
                # Start/end lengths are physical road-direction distances; factors scale
                # only normal dose E, while an optional final coast emits XY with no E.
                local_start = min(start_shape_len if i == 0 else 0.0, flat_len)
                local_coast = min(end_coast_distance_mm if i == len(blocks)-1 else 0.0, max(0.0, flat_len-local_start))
                local_ramp = min(end_flow_ramp_distance_mm if i == len(blocks)-1 else 0.0, max(0.0, flat_len-local_start-local_coast))
                local_end = min(end_shape_len if i == len(blocks)-1 else 0.0, max(0.0, flat_len-local_start-local_coast-local_ramp))
                if local_ramp > 1e-9 and local_end > 1e-9:
                    raise RuntimeError("continuous end underfeed and end flow ramp are mutually exclusive")
                if i == len(blocks)-1 and end_z_relief_distance_mm > 1e-9:
                    active_relief_len = local_ramp if local_ramp > 1e-9 else local_end
                    if abs(active_relief_len-end_z_relief_distance_mm) > 1e-6:
                        raise RuntimeError("continuous end Z relief distance must match end underfeed/ramp distance")
                middle_len = max(0.0, flat_len-local_start-local_end-local_ramp-local_coast)
                _x = block_start_x
                if local_start > 1e-9:
                    _x2 = _x + direction*local_start
                    g.append(f"G1 X{_x2:.3f} Y{fixed:.3f} E{base_e_per_mm*local_start*float(block['dose'])*start_shape_factor:.5f} F{int(feed)} ; FC3D_CONTINUOUS_START_FLOW_FACTOR distance={local_start:.3f} factor={start_shape_factor:.3f}")
                    _x = _x2
                if middle_len > 1e-9:
                    _x2 = _x + direction*middle_len
                    g.append(f"G1 X{_x2:.3f} Y{fixed:.3f} E{base_e_per_mm*middle_len*float(block['dose']):.5f} F{int(feed)} ; FC3D_CONTINUOUS_VARIABLE_DOSE_FLAT block={i+1} alpha={int(block['alpha'])} dose={float(block['dose']):.8f} z={float(block['z']):.5f}")
                    _x = _x2
                if local_end > 1e-9:
                    _x2 = _x + direction*local_end
                    z_suffix = ""
                    if end_z_relief_distance_mm > 1e-9:
                        z_suffix = f" Z{float(block['z']) + float(anchor_command_shift) + end_z_relief_mm:.5f}"
                    g.append(f"G1 X{_x2:.3f} Y{fixed:.3f}{z_suffix} E{base_e_per_mm*local_end*float(block['dose'])*end_shape_factor:.5f} F{int(feed)} ; FC3D_CONTINUOUS_END_FLOW_FACTOR distance={local_end:.3f} factor={end_shape_factor:.3f} z_relief={end_z_relief_mm:.5f}")
                    _x = _x2
                if local_ramp > 1e-9:
                    steps = max(2, int(flow_ramp_steps))
                    ramp_start_x = _x
                    previous_x = _x
                    for step_i in range(steps):
                        frac = float(step_i+1)/float(steps)
                        _x2 = ramp_start_x + direction*local_ramp*frac
                        step_len = abs(_x2-previous_x)
                        flow_fraction = 1.0 - (1.0-end_flow_ramp_final_factor)*(float(step_i)/float(steps-1))
                        z_suffix = ""
                        if end_z_relief_distance_mm > 1e-9:
                            z_suffix = f" Z{float(block['z']) + float(anchor_command_shift) + end_z_relief_mm*frac:.5f}"
                        e_amt = base_e_per_mm*step_len*float(block['dose'])*flow_fraction
                        g.append(f"G1 X{_x2:.3f} Y{fixed:.3f}{z_suffix} E{e_amt:.5f} F{int(feed)} ; FC3D_CONTINUOUS_END_FLOW_RAMP step={step_i+1}/{steps} flow={flow_fraction:.6f} final_factor={end_flow_ramp_final_factor:.3f} z_relief={end_z_relief_mm*frac:.5f}")
                        previous_x = _x2
                    _x = ramp_start_x + direction*local_ramp
                if local_coast > 1e-9:
                    _x2 = _x + direction*local_coast
                    g.append(f"G1 X{_x2:.3f} Y{fixed:.3f} F{int(feed)} ; FC3D_CONTINUOUS_END_COAST distance={local_coast:.3f} no_E")
                    _x = _x2
                if abs(_x-block_end_x) > 1e-4:
                    raise RuntimeError(f"continuous endpoint shaping cursor mismatch {_x:.5f} vs {block_end_x:.5f}")
                if span_index is not None and flat_len > 0.02:
                    span_index.add_segment(block_start_x, fixed, block_end_x, fixed, float(block["z"]), line_width)
                cursor = (block_end_x, fixed)
            stats["continuous_variable_dose_blocks"] += 1

            if i == len(blocks)-1:
                continue
            nxt = blocks[i+1]
            tr = transitions[i]
            boundary_x = float(block["p1"][0])
            if delayed_z_transition:
                _negative_lead_mm = max(0.0, -float(transition_z_delay_mm)) if hard_g29_step else 0.0
                _expected_cursor_x = boundary_x - direction * _negative_lead_mm
                if abs(float(cursor[0]) - _expected_cursor_x) > 1e-4:
                    raise RuntimeError(
                        "delayed-Z continuous transition cursor mismatch at E-boundary/lead point"
                    )
                next_block_len = abs(float(nxt["p1"][0]) - float(nxt["p0"][0]))
                consume = max(0.0, float(transition_z_delay_mm)) + float(transition_z_ramp_mm)
                if consume >= next_block_len - 0.25:
                    raise RuntimeError(
                        f"delayed-Z transition consumes {consume:.3f} mm but next VE block is only {next_block_len:.3f} mm"
                    )
                _cursor_x = float(cursor[0])
                if transition_z_delay_mm > 1e-9:
                    _x2 = _cursor_x + direction * float(transition_z_delay_mm)
                    _e = base_e_per_mm * float(transition_z_delay_mm) * float(nxt["dose"])
                    g.append(
                        f"G1 X{_x2:.3f} Y{fixed:.3f} E{_e:.5f} F{int(feed)} "
                        f"; FC3D_CONTINUOUS_BOUNDARY_Z_DELAY boundary={i+1} distance={float(transition_z_delay_mm):.3f} "
                        f"alpha_from={int(block['alpha'])} alpha_to={int(nxt['alpha'])} "
                        f"E_steps_at_x={boundary_x:.3f} old_z_held=1"
                    )
                    if span_index is not None and transition_z_delay_mm > 0.02:
                        span_index.add_segment(_cursor_x, fixed, _x2, fixed, float(block["z"]), line_width)
                    _cursor_x = _x2
                if hard_g29_step:
                    # v1.109 Studio-isolation diagnostic: hold direct model Z constant
                    # for the entire road and perform the VE-height change as one
                    # instantaneous G29.1 offset step. No G1 Z is emitted at the boundary.
                    _fixed_cmd_z = float(first_z)
                    _target_physical_z = float(nxt["z"]) + float(baseline_trim_mm)
                    _step_trim_z = _target_physical_z - _fixed_cmd_z
                    if not (-0.120 <= float(_step_trim_z) <= 0.080):
                        raise RuntimeError(
                            f"continuous hard G29 step produced unsafe absolute trim {_step_trim_z:.5f} mm"
                        )
                    g.append(
                        f"G29.1 Z{_step_trim_z:.5f} ; FC3D_CONTINUOUS_BOUNDARY_HARD_G29_STEP boundary={i+1} "
                        f"alpha_from={int(block['alpha'])} alpha_to={int(nxt['alpha'])} "
                        f"E_steps_at_x={boundary_x:.3f} z_delay_before_step={float(transition_z_delay_mm):.3f} "
                        f"direct_z_held={_fixed_cmd_z:.5f} physical_target_z={_target_physical_z:.5f}"
                    )
                    anchor_trim = float(_step_trim_z)
                    if _negative_lead_mm > 1e-9:
                        _x2 = boundary_x
                        _e = base_e_per_mm * float(_negative_lead_mm) * float(block["dose"])
                        g.append(
                            f"G1 X{_x2:.3f} Y{fixed:.3f} E{_e:.5f} F{int(feed)} "
                            f"; FC3D_CONTINUOUS_BOUNDARY_G29_LEAD_TO_E boundary={i+1} "
                            f"lead={float(_negative_lead_mm):.3f} old_alpha={int(block['alpha'])} "
                            f"E_steps_at_x={boundary_x:.3f}"
                        )
                        if span_index is not None and _negative_lead_mm > 0.02:
                            span_index.add_segment(_cursor_x, fixed, _x2, fixed, float(block["z"]), line_width)
                        _cursor_x = _x2
                elif transition_z_ramp_mm > 1e-9:
                    if live_g29_mode:
                        _steps = int(live_g29_steps)
                        _span = float(live_g29_span)
                        _physical0 = float(block["z"]) + float(baseline_trim_mm)
                        _physical1 = float(nxt["z"]) + float(baseline_trim_mm)
                        _ramp_start_x = _cursor_x
                        for _si in range(1, _steps + 1):
                            _tt = float(_si) / float(_steps)
                            _x2 = _ramp_start_x + direction * float(transition_z_ramp_mm) * _tt
                            _cmd_z = float(nominal_z) + _span * _tt
                            _physical_z = _physical0 + (_physical1 - _physical0) * _tt
                            _trim_z = _physical_z - _cmd_z
                            _actual_len = abs(_x2 - _cursor_x)
                            _e = base_e_per_mm * _actual_len * float(nxt["dose"])
                            g.append(
                                f"G1 X{_x2:.3f} Y{fixed:.3f} Z{_cmd_z:.5f} E{_e:.5f} F{int(feed)} "
                                f"; FC3D_CONTINUOUS_BOUNDARY_HYBRID_Z_RAMP boundary={i+1} step={_si}/{_steps} "
                                f"distance={_actual_len:.5f} alpha_from={int(block['alpha'])} alpha_to={int(nxt['alpha'])} "
                                f"z_delay_before_ramp={float(transition_z_delay_mm):.3f} E_steps_at_x={boundary_x:.3f}"
                            )
                            g.append(
                                f"G29.1 Z{_trim_z:.5f} ; FC3D_CONTINUOUS_BOUNDARY_LIVE_G29 boundary={i+1} "
                                f"step={_si}/{_steps} residual_cmd_z={_cmd_z:.5f} physical_target_z={_physical_z:.5f}"
                            )
                            _cursor_x = _x2
                        if span_index is not None and transition_z_ramp_mm > 0.02:
                            span_index.add_segment(_ramp_start_x, fixed, _cursor_x, fixed, max(float(block["z"]), float(nxt["z"])), line_width)
                    else:
                        _x2 = _cursor_x + direction * float(transition_z_ramp_mm)
                        _e = base_e_per_mm * float(transition_z_ramp_mm) * float(nxt["dose"])
                        g.append(
                            f"G1 X{_x2:.3f} Y{fixed:.3f} Z{float(nxt['z']) + float(anchor_command_shift):.5f} "
                            f"E{_e:.5f} F{int(feed)} "
                            f"; FC3D_CONTINUOUS_BOUNDARY_Z_RAMP boundary={i+1} distance={float(transition_z_ramp_mm):.3f} "
                            f"alpha_from={int(block['alpha'])} alpha_to={int(nxt['alpha'])} "
                            f"z_delay_before_ramp={float(transition_z_delay_mm):.3f} E_steps_at_x={boundary_x:.3f}"
                        )
                        if span_index is not None and transition_z_ramp_mm > 0.02:
                            span_index.add_segment(_cursor_x, fixed, _x2, fixed, max(float(block["z"]), float(nxt["z"])), line_width)
                        _cursor_x = _x2
                elif (not hard_g29_step) and abs(float(nxt["z"]) - float(block["z"])) > 1e-9:
                    g.append(
                        f"G1 Z{float(nxt['z']) + float(anchor_command_shift):.5f} F1200 "
                        f"; FC3D_CONTINUOUS_BOUNDARY_Z_AFTER_DELAY boundary={i+1}"
                    )
                cursor = (_cursor_x, fixed)
                delayed_entry_consumed_mm[i+1] = consume
                stats["continuous_variable_dose_z_boundaries"] += 1
                stats["continuous_variable_dose_delayed_z_transitions"] += 1
                stats["continuous_variable_dose_delayed_z_mm"] += float(transition_z_delay_mm)
                stats["continuous_variable_dose_z_ramp_mm"] += float(transition_z_ramp_mm)
            elif tr["mode"] == "stationary":
                # cursor is exactly at the boundary for a stationary transition.
                if abs(float(cursor[0]) - boundary_x) > 1e-4:
                    raise RuntimeError("stationary continuous transition did not end at boundary")
                g.append(
                    f"G1 Z{float(nxt['z']) + float(anchor_command_shift):.5f} F1200 ; FC3D_CONTINUOUS_BOUNDARY_STATIONARY "
                    f"boundary={i+1} alpha_from={int(block['alpha'])} alpha_to={int(nxt['alpha'])}"
                )
                stats["continuous_variable_dose_z_boundaries"] += 1
                stats["continuous_variable_dose_stationary_boundaries"] += 1
            else:
                ramp_len = float(tr["blend_mm"])
                ramp_end_x = boundary_x + direction * 0.5 * ramp_len
                actual_len = abs(ramp_end_x - float(cursor[0]))
                avg_dose = 0.5 * (float(block["dose"]) + float(nxt["dose"]))
                g.append(
                    f"G1 X{ramp_end_x:.3f} Y{fixed:.3f} Z{float(nxt['z']) + float(anchor_command_shift):.5f} "
                    f"E{base_e_per_mm*actual_len*avg_dose:.5f} F{int(feed)} "
                    f"; FC3D_CONTINUOUS_BOUNDARY_BLEND boundary={i+1} length={actual_len:.5f} "
                    f"alpha_from={int(block['alpha'])} alpha_to={int(nxt['alpha'])} "
                    f"dose_from={float(block['dose']):.8f} dose_to={float(nxt['dose']):.8f}"
                )
                if span_index is not None and actual_len > 0.02:
                    span_index.add_segment(float(cursor[0]), fixed, ramp_end_x, fixed, max(float(block["z"]), float(nxt["z"])), line_width)
                cursor = (ramp_end_x, fixed)
                stats["continuous_variable_dose_z_boundaries"] += 1
                stats["continuous_variable_dose_blend_moves"] += 1

        current_xy = cursor
        if stationary_retract_components_mm:
            if wipe_distance_mm > 1e-12 or moving_retract_mm > 1e-12 or final_retract_mm > 1e-12:
                raise RuntimeError("continuous stationary retract components are mutually exclusive with wipe/moving/final retract")
            for component_index, component_mm in enumerate(stationary_retract_components_mm, 1):
                if component_mm > 1e-9:
                    g.append(
                        f"G1 E-{component_mm:.5f} F1800 ; FC3D_CONTINUOUS_ROW_STATIONARY_RETRACT_COMPONENT "
                        f"mode={profile.get('id','unknown')} part={component_index}/{len(stationary_retract_components_mm)}"
                    )
        elif wipe_distance_mm > 1e-12:
            wipe_distance = min(float(wipe_distance_mm), abs(float(blocks[-1]["p1"][0]) - float(blocks[-1]["p0"][0])))
            wipe_x = float(cursor[0]) - direction * wipe_distance
            if moving_retract_mm > 1e-9:
                g.append(
                    f"G1 X{wipe_x:.3f} Y{fixed:.3f} E-{moving_retract_mm:.5f} F{int(DIRECT_REFERENCE_WIPE_FEED_MM_MIN)} "
                    f"; FC3D_CONTINUOUS_ROW_BACKTRACE_RETRACT mode={profile.get('id','unknown')} distance={wipe_distance:.3f}"
                )
            else:
                g.append(
                    f"G1 X{wipe_x:.3f} Y{fixed:.3f} F{int(DIRECT_REFERENCE_WIPE_FEED_MM_MIN)} "
                    f"; FC3D_CONTINUOUS_ROW_BACKTRACE_ONLY mode={profile.get('id','unknown')} distance={wipe_distance:.3f}"
                )
            current_xy = (wipe_x, fixed)
            if final_retract_mm > 1e-9:
                g.append(
                    f"G1 E-{final_retract_mm:.5f} F1800 ; FC3D_CONTINUOUS_ROW_FINAL_RETRACT mode={profile.get('id','unknown')}"
                )
        else:
            if moving_retract_mm > 1e-12:
                raise RuntimeError("continuous moving retract requires positive wipe distance")
            if final_retract_mm > 1e-9:
                g.append(
                    f"G1 E-{final_retract_mm:.5f} F1800 ; FC3D_CONTINUOUS_ROW_STATIONARY_RETRACT mode={profile.get('id','unknown')}"
                )
        stats["continuous_variable_dose_stationary_retract_mm"] += float(total_retract_mm)
        if anchor_trim is not None:
            _restore_active_trim = float(anchor_trim)
            if live_g29_mode and len(blocks) >= 2:
                _last_physical_z = float(blocks[-1]["z"]) + float(baseline_trim_mm)
                _restore_active_trim = _last_physical_z - (float(nominal_z) + float(live_g29_span))
            append_direct_z_trim_restore(
                g, current_xy, nominal_z, _restore_active_trim, float(baseline_trim_mm),
                context=(
                    f"continuous_profile={profile.get('id', 'unknown')} road={road_i+1} "
                    + (f"live_g29_span={float(live_g29_span):.5f} steps={live_g29_steps}" if live_g29_mode else f"anchor_alpha={anchor_alpha}")
                ),
            )
        else:
            g.append(f"G1 Z{nominal_z + HOP_Z_MM:.5f} F1200 ; FC3D_CONTINUOUS_ROW_SAFE_LIFT")
        stats["continuous_variable_dose_scanlines"] += 1
    return current_xy, stats

def group_segments_by_height_fraction(segs: Sequence[tuple]) -> List[Tuple[float, int, List[tuple]]]:
    """Group direct segments by decoded dose-height fraction and card profile.

    The historical order is dose first. Cards that need an independent reset
    between complete row-pair profiles may explicitly request profile first,
    which keeps every dose group for one profile contiguous.
    """
    grouped: Dict[Tuple[float, int], List[tuple]] = {}
    for seg in segs:
        key = (float(round(seg_height_fraction(seg), 8)), int(seg_height_profile_index(seg)))
        grouped.setdefault(key, []).append(seg)
    spec = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
    order = str(spec.get("profile_emission_order", "dose_then_profile")) if isinstance(spec, dict) else "dose_then_profile"
    if order == "profile_then_height":
        keys = sorted(grouped, key=lambda item: (item[1], -item[0]))
    else:
        keys = sorted(grouped, key=lambda item: (item[0], -item[1]), reverse=True)
    return [(fraction, profile_index, grouped[(fraction, profile_index)]) for fraction, profile_index in keys]


def direct_profile_reset_gutter_geometry(
    card_bbox: Tuple[float, float, float, float],
    tower_bbox: Tuple[float, float, float, float],
) -> Dict[str, object]:
    """Return unique sacrificial road positions in the card/tower gap."""
    cfg = direct_inter_profile_reset_config()
    spec = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
    if cfg is None or not isinstance(spec, dict):
        raise RuntimeError("direct profile reset gutter requested without an enabled card reset contract")
    profiles = [p for p in spec.get("profiles", []) if isinstance(p, dict)]
    boundary_count = max(0, len(profiles) - 1)
    roads_per_boundary = int(cfg["purge_roads_per_boundary"])
    total_roads = boundary_count * roads_per_boundary
    if total_roads <= 0:
        raise RuntimeError("direct profile reset requires at least two print profiles")

    cx0, cy0, cx1, cy1 = (float(v) for v in card_bbox)
    tx0, ty0, tx1, ty1 = (float(v) for v in tower_bbox)
    margin = float(ROAD_W_MM) / 2.0 + 0.05
    spacing = float(cfg["road_spacing_mm"])
    span_inset = max(0.50, float(ROAD_W_MM))
    roads: List[Tuple[float, float, float, float]] = []
    side = ""
    gap = 0.0

    if ty0 >= cy1 - 1e-9:
        side = "above"
        gap = ty0 - cy1
        fixed0 = cy1 + margin
        coords = [fixed0 + i * spacing for i in range(total_roads)]
        if coords[-1] + float(ROAD_W_MM) / 2.0 > ty0 - 0.05 + 1e-9:
            raise RuntimeError("inter-profile reset roads do not fit in the upper card/tower gap")
        xa, xb = cx0 + span_inset, cx1 - span_inset
        roads = [(xa, y, xb, y) if i % 2 == 0 else (xb, y, xa, y) for i, y in enumerate(coords)]
    elif ty1 <= cy0 + 1e-9:
        side = "below"
        gap = cy0 - ty1
        fixed0 = cy0 - margin
        coords = [fixed0 - i * spacing for i in range(total_roads)]
        if coords[-1] - float(ROAD_W_MM) / 2.0 < ty1 + 0.05 - 1e-9:
            raise RuntimeError("inter-profile reset roads do not fit in the lower card/tower gap")
        xa, xb = cx0 + span_inset, cx1 - span_inset
        roads = [(xa, y, xb, y) if i % 2 == 0 else (xb, y, xa, y) for i, y in enumerate(coords)]
    elif tx0 >= cx1 - 1e-9:
        side = "right"
        gap = tx0 - cx1
        fixed0 = cx1 + margin
        coords = [fixed0 + i * spacing for i in range(total_roads)]
        if coords[-1] + float(ROAD_W_MM) / 2.0 > tx0 - 0.05 + 1e-9:
            raise RuntimeError("inter-profile reset roads do not fit in the right card/tower gap")
        ya, yb = cy0 + span_inset, cy1 - span_inset
        roads = [(x, ya, x, yb) if i % 2 == 0 else (x, yb, x, ya) for i, x in enumerate(coords)]
    elif tx1 <= cx0 + 1e-9:
        side = "left"
        gap = cx0 - tx1
        fixed0 = cx0 - margin
        coords = [fixed0 - i * spacing for i in range(total_roads)]
        if coords[-1] - float(ROAD_W_MM) / 2.0 < tx1 + 0.05 - 1e-9:
            raise RuntimeError("inter-profile reset roads do not fit in the left card/tower gap")
        ya, yb = cy0 + span_inset, cy1 - span_inset
        roads = [(x, ya, x, yb) if i % 2 == 0 else (x, yb, x, ya) for i, x in enumerate(coords)]
    else:
        raise RuntimeError("prime tower is not separated from the card by an axis-aligned reset gutter")

    if gap < 4.9:
        raise RuntimeError(f"inter-profile reset requires the established 5 mm card/tower gap, got {gap:.3f} mm")
    return {
        "side": side,
        "gap_mm": float(gap),
        "boundary_count": int(boundary_count),
        "roads_per_boundary": int(roads_per_boundary),
        "roads": roads,
    }


def append_direct_profile_reset_foundation(
    g: List[str],
    current_xy: Optional[Tuple[float, float]],
    z: float,
    span_index: Optional[SpanCollisionIndex],
    tower_bbox: Tuple[float, float, float, float],
    card_bbox: Tuple[float, float, float, float],
) -> Tuple[Optional[Tuple[float, float]], Dict[str, object]]:
    """Print the W first-layer foundation below all later reset/purge roads."""
    geometry = direct_profile_reset_gutter_geometry(card_bbox, tower_bbox)
    roads = list(geometry["roads"])
    g.append(
        f"; FC3D_PROFILE_RESET_FOUNDATION_START side={geometry['side']} roads={len(roads)} "
        f"gap={float(geometry['gap_mm']):.3f}"
    )
    hops = 0
    for road_index, (x0, y0, x1, y1) in enumerate(roads):
        current_xy, did_hop = append_segment(
            g, x0, y0, x1, y1, z, BASE_H_MM, current_xy, span_index, tower_bbox,
            line_w=ROAD_W_MM, feed=FIRST_LAYER_FEED, e_multiplier=1.0,
            force_hop=True, z_decimals=3,
        )
        hops += int(bool(did_hop))
        g.append(f"; FC3D_PROFILE_RESET_FOUNDATION_ROAD index={road_index+1}/{len(roads)}")
    g.append("; FC3D_PROFILE_RESET_FOUNDATION_END")
    return current_xy, {
        "enabled": True,
        "side": str(geometry["side"]),
        "roads": int(len(roads)),
        "hops": int(hops),
    }


def append_direct_inter_profile_reset(
    g: List[str],
    current_xy: Optional[Tuple[float, float]],
    z: float,
    h: float,
    span_index: Optional[SpanCollisionIndex],
    tower_bbox: Tuple[float, float, float, float],
    card_bbox: Tuple[float, float, float, float],
    boundary_index: int,
    completed_profile_id: str,
    next_profile_id: str,
    intentional_under_recovery_mm: float,
) -> Tuple[Optional[Tuple[float, float]], Dict[str, object]]:
    """Restore one completed profile in a sacrificial, foundation-backed gutter.

    Each road uses the established +0.40 / -0.38 / -0.02 pressure cycle. The
    exact accumulated profile deficit is distributed as additional positive E
    over the sacrificial roads, so the following profile starts from the normal
    retracted baseline rather than inheriting the previous experiment.
    """
    cfg = direct_inter_profile_reset_config()
    if cfg is None:
        raise RuntimeError("inter-profile reset emission requested without an enabled contract")
    restore_mm = float(intentional_under_recovery_mm) if bool(cfg.get("restore_intentional_under_recovery", True)) else 0.0
    if not math.isfinite(restore_mm) or restore_mm < -1e-9:
        raise RuntimeError(f"invalid inter-profile restore amount {restore_mm!r}")
    restore_mm = max(0.0, restore_mm)
    if restore_mm > float(cfg["max_restore_mm"]) + 1e-9:
        raise RuntimeError(
            f"inter-profile restore {restore_mm:.5f} mm exceeds card limit {float(cfg['max_restore_mm']):.5f} mm"
        )
    geometry = direct_profile_reset_gutter_geometry(card_bbox, tower_bbox)
    roads_per_boundary = int(geometry["roads_per_boundary"])
    boundary_count = int(geometry["boundary_count"])
    if boundary_index < 0 or boundary_index >= boundary_count:
        raise RuntimeError(f"inter-profile boundary index {boundary_index} outside 0..{boundary_count-1}")
    start = boundary_index * roads_per_boundary
    roads = list(geometry["roads"])[start:start + roads_per_boundary]
    restore_per_road = restore_mm / max(1, len(roads))
    g.append(
        f"; FC3D_PROFILE_RESET_START boundary={boundary_index+1}/{boundary_count} "
        f"from={completed_profile_id} to={next_profile_id} roads={len(roads)} "
        f"restore_total={restore_mm:.5f} restore_per_road={restore_per_road:.5f}"
    )
    purge_e_total = 0.0
    normal_e_total = 0.0
    hops = 0
    for local_index, (x0, y0, x1, y1) in enumerate(roads):
        current_xy, did_hop = append_checked_travel_xy(
            g, current_xy, (x0, y0), z, span_index, tower_bbox,
            feed=60000, reason="PROFILE_RESET_PURGE_START", restore_z=True,
            force_hop=True, z_decimals=5,
        )
        hops += int(bool(did_hop))
        length = math.hypot(x1 - x0, y1 - y0)
        if length <= 2.0:
            raise RuntimeError("inter-profile reset purge road is unexpectedly short")
        normal_e = e_for_len(length, h, ROAD_W_MM)
        line_e = normal_e + restore_per_road
        normal_e_total += normal_e
        purge_e_total += line_e
        g.extend([
            f"; FC3D_PROFILE_RESET_ROAD index={local_index+1}/{len(roads)} length={length:.3f} normal_E={normal_e:.5f} restore_E={restore_per_road:.5f}",
            f"G1 E{float(cfg['recovery_mm']):.5f} F{int(DIRECT_REFERENCE_RETRACT_FEED_MM_MIN)} ; FC3D_PROFILE_RESET_RECOVERY",
            f"G1 F{int(NORMAL_LAYER_FEED)}",
            f"M204 S{print_acceleration_for_layer_height(h)}",
            f"G1 X{x1:.3f} Y{y1:.3f} E{line_e:.5f} ; FC3D_PROFILE_RESET_PURGE",
        ])
        if span_index is not None:
            span_index.add_segment(x0, y0, x1, y1, z, ROAD_W_MM)
        ux = (x1 - x0) / length
        uy = (y1 - y0) / length
        wipe_distance = min(float(cfg["wipe_distance_mm"]), length)
        wipe_xy = (x1 - ux * wipe_distance, y1 - uy * wipe_distance)
        g.extend([
            "; WIPE_START FC3D_PROFILE_RESET",
            f"G1 F{int(DIRECT_REFERENCE_WIPE_FEED_MM_MIN)}",
            f"G1 X{wipe_xy[0]:.3f} Y{wipe_xy[1]:.3f} E-{float(cfg['moving_retract_mm']):.5f} ; FC3D_PROFILE_RESET_MOVING_RETRACT",
            "; WIPE_END FC3D_PROFILE_RESET",
            f"G1 E-{float(cfg['final_retract_mm']):.5f} F{int(DIRECT_REFERENCE_RETRACT_FEED_MM_MIN)} ; FC3D_PROFILE_RESET_FINAL_RETRACT",
        ])
        current_xy = wipe_xy
    g.append(
        f"; FC3D_PROFILE_RESET_END boundary={boundary_index+1}/{boundary_count} "
        f"restore_total={restore_mm:.5f} purge_E_total={purge_e_total:.5f}"
    )
    return current_xy, {
        "boundary_index": int(boundary_index),
        "from_profile": str(completed_profile_id),
        "to_profile": str(next_profile_id),
        "roads": int(len(roads)),
        "restore_mm": float(restore_mm),
        "normal_purge_e_mm": float(normal_e_total),
        "commanded_purge_e_mm": float(purge_e_total),
        "hops": int(hops),
        "side": str(geometry["side"]),
    }


def parse_ironing_layer_set(spec: str, max_layers: int = MIX_LAYERS) -> set:
    """Parse optional no-flow ironing layer list as optical layer numbers 1..N."""
    text = (spec or "").strip().lower()
    if text in ("", "off", "none", "0", "false", "no"):
        return set()
    if text == "all":
        return set(range(1, max_layers + 1))
    if text == "even":
        return {i for i in range(1, max_layers + 1) if i % 2 == 0}
    if text == "odd":
        return {i for i in range(1, max_layers + 1) if i % 2 == 1}
    out = set()
    for part in text.split(','):
        part = part.strip()
        if not part:
            continue
        if '-' in part:
            a_s, b_s = part.split('-', 1)
            a, b = int(a_s), int(b_s)
            if a > b:
                a, b = b, a
            vals = range(a, b + 1)
        else:
            vals = [int(part)]
        for v in vals:
            if v < 1 or v > max_layers:
                raise ValueError(f"ironing layer {v} outside valid optical layer range 1..{max_layers}")
            out.add(v)
    return out


def _frange_inclusive(a: float, b: float, step: float) -> List[float]:
    if step <= 0:
        raise ValueError("step must be positive")
    vals = []
    x = float(a)
    # Use a small epsilon to include the far edge if it lands on grid.
    while x <= float(b) + 1e-9:
        vals.append(round(x, 6))
        x += step
    if not vals or abs(vals[-1] - float(b)) > min(0.001, step * 0.01):
        vals.append(round(float(b), 6))
    return vals


def append_no_flow_ironing_pass(g: List[str], current_xy: Optional[Tuple[float, float]], z: float,
                                logical_layer: int, card_bbox: Tuple[float, float, float, float],
                                span_index: Optional[SpanCollisionIndex], tower_bbox, args,
                                layer_orientation: str = "X",
                                force_first_hop: bool = False) -> Tuple[Optional[Tuple[float, float]], dict]:
    """Append an optional no-extrusion thermal ironing pass over the image bbox.

    This is deliberately recipe-neutral: no material is added, no T/F recipe slot
    is used, and no E is emitted on ironing strokes.  The pass is marked so the
    collision audit can later classify it separately from accidental travel.
    """
    selected = parse_ironing_layer_set(getattr(args, 'ironing_layers', ''), int(DIRECT_OPTICAL_LAYER_COUNT))
    if logical_layer <= 0 or logical_layer not in selected:
        return current_xy, {"enabled": False, "logical_layer": int(logical_layer), "lines": 0}

    spacing = float(getattr(args, 'ironing_line_spacing_mm', DEFAULT_IRONING_LINE_SPACING_MM))
    if spacing <= 0:
        raise ValueError("--ironing-line-spacing-mm must be > 0")
    speed_mm_s = float(getattr(args, 'ironing_speed_mm_s', DEFAULT_IRONING_SPEED_MM_S))
    if speed_mm_s <= 0:
        raise ValueError("--ironing-speed-mm-s must be > 0")
    feed = int(round(speed_mm_s * 60.0))
    margin = float(getattr(args, 'ironing_margin_mm', DEFAULT_IRONING_MARGIN_MM))
    z_offset = float(getattr(args, 'ironing_z_offset_mm', DEFAULT_IRONING_Z_OFFSET_MM))
    pattern = str(getattr(args, 'ironing_pattern', DEFAULT_IRONING_PATTERN)).lower()

    x0, y0, x1, y1 = map(float, card_bbox)
    x0 += margin; y0 += margin; x1 -= margin; y1 -= margin
    if x1 <= x0 or y1 <= y0:
        return current_xy, {"enabled": True, "logical_layer": int(logical_layer), "lines": 0, "skipped": "empty_bbox_after_margin"}

    if pattern == "layer":
        passes = [(layer_orientation or "X").upper()]
    elif pattern == "x":
        passes = ["X"]
    elif pattern == "y":
        passes = ["Y"]
    elif pattern == "xy":
        passes = ["X", "Y"]
    else:
        raise ValueError(f"Unsupported ironing pattern {pattern!r}")

    iron_z = z + z_offset
    g.append(f"; FC3D_IRONING_BEGIN logical_layer={int(logical_layer)} z={iron_z:.3f} pattern={pattern} speed_mm_s={speed_mm_s:.3f} spacing_mm={spacing:.3f} no_flow=true recipe_impact=none")
    if abs(z_offset) > 1e-9:
        g.append(f"G1 Z{iron_z:.3f} F1200 ; FC3D_IRONING_Z_OFFSET")

    total_lines = 0
    first_line = True
    for pass_i, orient in enumerate(passes):
        orient = orient.upper()
        g.append(f"; FC3D_IRONING_PASS pass={pass_i+1}/{len(passes)} orient={orient}")
        if orient == "X":
            coords = _frange_inclusive(y0, y1, spacing)
            reverse = False
            for yy in coords:
                p0 = (x1, yy) if reverse else (x0, yy)
                p1 = (x0, yy) if reverse else (x1, yy)
                current_xy, _ = append_checked_travel_xy(
                    g, current_xy, p0, iron_z, span_index, tower_bbox,
                    feed=60000, reason="IRONING_LINE_START", restore_z=True,
                    force_hop=bool(force_first_hop and first_line),
                    z_decimals=(5 if force_first_hop and first_line else 3),
                )
                first_line = False
                g.append(f"G1 X{p1[0]:.3f} Y{p1[1]:.3f} F{feed} ; FC3D_IRONING no_flow")
                current_xy = p1
                total_lines += 1
                reverse = not reverse
        elif orient == "Y":
            coords = _frange_inclusive(x0, x1, spacing)
            reverse = False
            for xx in coords:
                p0 = (xx, y1) if reverse else (xx, y0)
                p1 = (xx, y0) if reverse else (xx, y1)
                current_xy, _ = append_checked_travel_xy(
                    g, current_xy, p0, iron_z, span_index, tower_bbox,
                    feed=60000, reason="IRONING_LINE_START", restore_z=True,
                    force_hop=bool(force_first_hop and first_line),
                    z_decimals=(5 if force_first_hop and first_line else 3),
                )
                first_line = False
                g.append(f"G1 X{p1[0]:.3f} Y{p1[1]:.3f} F{feed} ; FC3D_IRONING no_flow")
                current_xy = p1
                total_lines += 1
                reverse = not reverse
        else:
            raise ValueError(f"Unsupported ironing orientation {orient!r}")

    if abs(z_offset) > 1e-9:
        g.append(f"G1 Z{z:.3f} F1200 ; FC3D_IRONING_RESTORE_Z")
    g.append(f"; FC3D_IRONING_END logical_layer={int(logical_layer)} lines={total_lines}")
    return current_xy, {
        "enabled": True,
        "logical_layer": int(logical_layer),
        "lines": int(total_lines),
        "pattern": pattern,
        "passes": passes,
        "speed_mm_s": speed_mm_s,
        "spacing_mm": spacing,
        "z_offset_mm": z_offset,
    }


def seg_with_xy(seg, xy):
    base = (xy[0], xy[1], xy[2], xy[3], seg_dose(seg))
    if seg_has_height_fraction(seg):
        base = base + (seg_height_fraction(seg),)
    if len(seg) >= 7:
        base = base + (seg_height_profile_index(seg),)
    return base

def append_segment(g, x0,y0,x1,y1,z,h, current_xy, span_index: Optional[SpanCollisionIndex], tower_bbox=None, line_w=RUNTIME_PRINT_WIDTH_MM, feed=15000, e_multiplier: float = 1.0, force_hop: bool = False, z_decimals: int = 3):
    length=math.hypot(x1-x0,y1-y0)
    if length<=0.02: return current_xy, False
    g.append("M204 S10000")
    current_xy, need = append_checked_travel_xy(
        g, current_xy, (x0, y0), z, span_index, tower_bbox,
        feed=60000, reason="SEGMENT_START", restore_z=True,
        force_hop=bool(force_hop), z_decimals=int(z_decimals),
    )
    line_e = e_for_len(length, h, line_w) * float(e_multiplier)
    print_accel = print_acceleration_for_layer_height(h)
    g += ["G1 E0.4 F1800", f"G1 F{feed}", f"M204 S{print_accel}", f"G1 X{x1:.3f} Y{y1:.3f} E{line_e:.5f}", "G1 E-0.4 F1800"]
    if span_index is not None:
        span_index.add_segment(x0,y0,x1,y1,z,line_w)
    return (x1,y1), need


def _group_axis_aligned_segments_for_sweep(segs: Sequence[Tuple[float,float,float,float]]):
    """Group axis-aligned same-material+dose spans by scanline for continuous sweep emission."""
    groups = {}
    passthrough = []
    for s in segs:
        x0, y0, x1, y1 = seg_xy(s)
        dose = round(seg_dose(s), 6)
        if abs(y0 - y1) < 1e-6:
            key = ("X", round(y0, 5), dose)
            a, b = sorted((x0, x1))
            groups.setdefault(key, []).append((a, b))
        elif abs(x0 - x1) < 1e-6:
            key = ("Y", round(x0, 5), dose)
            a, b = sorted((y0, y1))
            groups.setdefault(key, []).append((a, b))
        else:
            passthrough.append(s)

    ordered_groups = []
    for (axis, fixed, dose), spans in groups.items():
        spans.sort(key=lambda p: (p[0], p[1]))
        merged = []
        for a, b in spans:
            if not merged or a > merged[-1][1] + 1e-9:
                merged.append([a, b])
            else:
                merged[-1][1] = max(merged[-1][1], b)
        ordered_groups.append((axis, fixed, float(dose), [(a, b) for a, b in merged]))

    ordered_groups.sort(key=lambda item: (0 if item[0] == "X" else 1, item[1], item[2]))
    return ordered_groups, passthrough



def append_material_studio_raster_segments(g, segs, z, h, current_xy, span_index: Optional[SpanCollisionIndex],
                                           tower_bbox=None, line_w=RUNTIME_PRINT_WIDTH_MM, feed=15000,
                                           chain_max_travel_mm: float = DEFAULT_RASTER_CHAIN_MAX_TRAVEL_MM,
                                           gap_flow_max_mm: float = DEFAULT_RASTER_GAP_FLOW_MAX_MM,
                                           gap_flow_ratio: float = DEFAULT_RASTER_GAP_FLOW_RATIO,
                                           raster_gap_always_continue_mm: float = RASTER_GAP_ALWAYS_CONTINUE_MM,
                                           raster_gap_conditional_continue_mm: float = RASTER_GAP_CONDITIONAL_CONTINUE_MM,
                                           local_tile_mm: float = DEFAULT_LOCAL_TILE_MM,
                                           pure_grid_mode: bool = False,
                                           directional_block_mm: float = 0.0,
                                           directional_join_gap_mm: float = DEFAULT_DIRECTIONAL_JOIN_GAP_MM,
                                           directional_join_threshold: int = DEFAULT_DIRECTIONAL_JOIN_THRESHOLD,
                                           endpoint_trim_mm: float = 0.0,
                                           min_trimmed_segment_mm: float = MIN_TRIMMED_SEGMENT_MM,
                                           layer_orientation: str = "X",
                                           force_travel_hops: bool = False,
                                           hold_pressure_across_forced_hops: bool = False,
                                           hold_pressure_max_link_mm: float = 0.0,
                                           pressure_state: Optional[Dict[str, bool]] = None,
                                           same_material_chain_across_locations: bool = False,
                                           retract_at_end: bool = True,
                                           reference_wipe_between_scanlines: bool = False,
                                           reference_wipe_profile: Optional[Dict[str, object]] = None,
                                           forced_scanline_direction: str = "serpentine",
                                           planner_start_xy: Optional[Tuple[float, float]] = None,
                                           fixed_scanline_order: str = "ascending",
                                           z_decimals: int = 3, material=None):
    """Emit same-material roads in Studio-like local raster regions.

    PPV96 change: variable-dose same-material chain optimisation.

    PPV95 grouped scanlines by (axis, fixed coordinate, dose), which meant two
    adjacent same-material roads on the same emitted raster line were split into
    separate scanlines whenever their dose/extrusion multiplier differed.  PPV96
    groups by (axis, fixed coordinate) only and keeps dose per span.  The output
    remains normal M83 relative-E G-code: adjacent different-dose regions are
    emitted as consecutive G1 extrusion moves in one pressurised chain, preserving
    each segment's original E amount while avoiding unnecessary retract/reprime
    pressure breaks.

    Retained safety/QA rules:
      - no material/tool/layer crossing,
      - local tiles are still used for traversal locality,
      - no gap extrusion by default (gap_flow_max_mm = 0),
      - same-scanline gaps <= raster_gap_always_continue_mm live-cross without retract,
      - larger gaps up to raster_gap_conditional_continue_mm live-cross only if the span collision check is clear,
      - longer gaps retract/travel/reprime, hop only if collision check says needed,
      - scanline-to-scanline live chain default is 1.0 mm.

    v1.67's direct-card experiment may supply a shared ``pressure_state`` and
    ``same_material_chain_across_locations=True``. That narrowly scoped mode
    keeps the already-loaded material live across separate tiles/components and
    carrier-height groups. Every link is still a lifted no-E travel. The
    established v1.66 behaviour remains available for legacy diagnostics.

    v1.70/v1.71 may instead set ``reference_wipe_between_scanlines=True`` for the
    variable-height direct-card path.  Every emitted scanline then ends with the
    uploaded Bambu-reference sequence: move 1.00 mm backwards over the final
    printed segment while retracting E-0.38, retract the remaining E-0.02, then
    lift/travel while depressurised.  The next scanline restores E+0.40 before
    extrusion.  Reference-wipe mode and live pressure chaining are mutually
    exclusive.
    """
    scan_mode = dict(DEFAULT_DIRECT_SCANLINE_PRINT_MODE)
    if isinstance(reference_wipe_profile, dict):
        scan_mode.update(reference_wipe_profile)
    scan_mode_id = str(scan_mode.get("id", "normal_reference"))
    stationary_recovery_mm = float(scan_mode.get("stationary_recovery_mm", 0.40))
    stationary_recovery_feed_mm_min = float(scan_mode.get("stationary_recovery_feed_mm_min", DIRECT_REFERENCE_RETRACT_FEED_MM_MIN))
    stationary_recovery_dwell_ms = int(scan_mode.get("stationary_recovery_dwell_ms", 0))
    stationary_recovery_components = list(scan_mode.get("stationary_recovery_components", []))
    moving_recovery_mm = float(scan_mode.get("moving_recovery_mm", 0.0))
    moving_recovery_distance_mm = float(scan_mode.get("moving_recovery_distance_mm", 0.0))
    moving_recovery_steps = int(scan_mode.get("moving_recovery_steps", 0))
    end_coast_distance_mm = float(scan_mode.get("end_coast_distance_mm", 0.0))
    start_flow_ramp_distance_mm = float(scan_mode.get("start_flow_ramp_distance_mm", 0.0))
    end_flow_ramp_distance_mm = float(scan_mode.get("end_flow_ramp_distance_mm", 0.0))
    flow_ramp_steps = int(scan_mode.get("flow_ramp_steps", 4))
    physical_start_trim_mm = float(scan_mode.get("start_trim_mm", 0.0) or 0.0)
    physical_end_trim_mm = float(scan_mode.get("end_trim_mm", 0.0) or 0.0)
    start_underfeed_length_mm = float(scan_mode.get("start_underfeed_length_mm", 0.0) or 0.0)
    start_underfeed_factor = float(scan_mode.get("start_underfeed_factor", 1.0))
    end_underfeed_length_mm = float(scan_mode.get("end_underfeed_length_mm", 0.0) or 0.0)
    end_underfeed_factor = float(scan_mode.get("end_underfeed_factor", 1.0))
    end_flow_ramp_final_factor = float(scan_mode.get("end_flow_ramp_final_factor", 0.0))
    end_z_relief_distance_mm = float(scan_mode.get("end_z_relief_distance_mm", 0.0) or 0.0)
    end_z_relief_mm = float(scan_mode.get("end_z_relief_mm", 0.0) or 0.0)
    reference_wipe_distance_mm = float(scan_mode.get("wipe_distance_mm", DIRECT_REFERENCE_WIPE_DISTANCE_MM))
    reference_moving_retract_mm = float(scan_mode.get("moving_retract_mm", DIRECT_REFERENCE_WIPE_MOVING_RETRACT_MM))
    reference_final_retract_mm = float(scan_mode.get("final_retract_mm", DIRECT_REFERENCE_WIPE_FINAL_RETRACT_MM))
    retract_before_wipe = bool(scan_mode.get("retract_before_wipe", False))
    retract_before_end_coast = bool(scan_mode.get("retract_before_end_coast", False))
    total_recovery_mm = stationary_recovery_mm + moving_recovery_mm
    stationary_retract_components_mm = [float(v) for v in scan_mode.get("stationary_retract_components_mm", [])]
    total_retract_mm = sum(stationary_retract_components_mm) if stationary_retract_components_mm else (reference_moving_retract_mm + reference_final_retract_mm)
    cycle_balance_policy = str(scan_mode.get("cycle_balance_policy", "strict"))
    intentional_under_recovery_mm = float(scan_mode.get(
        "intentional_under_recovery_mm", max(0.0, total_retract_mm - total_recovery_mm)
    ))

    empty_stats = {
        "chains": 0,
        "scanlines": 0,
        "unretracted_links": 0,
        "gap_flow_moves": 0,
        "local_tiles": 0,
        "pure_grid_mode": int(bool(pure_grid_mode)),
        "pure_grid_segments": 0,
        "variable_dose_scanlines": 0,
        "variable_dose_span_transitions": 0,
        "same_dose_span_transitions": 0,
        "dose_grouping_mode": "axis_fixed_variable_dose",
        "raster_gap_always_continue_mm": float(raster_gap_always_continue_mm),
        "raster_gap_conditional_continue_mm": float(raster_gap_conditional_continue_mm),
        "same_scanline_live_gap_moves": 0,
        "same_scanline_long_gap_retracts": 0,
        "pressurised_noe_gap_moves": 0,
        "pressurised_noe_gap_total_mm": 0.0,
        "pressurised_noe_gap_max_mm": 0.0,
        "pressurised_noe_gap_hop_retracts": 0,
        "pressurised_noe_gap_rejected_too_long": 0,
        "pressurised_noe_gap_rejected_collision": 0,
        "pressurised_noe_gap_policy": "same-scanline-short-clear-no-E-no-retract",
        "force_travel_hops": int(bool(force_travel_hops)),
        "hold_pressure_across_forced_hops": int(bool(hold_pressure_across_forced_hops)),
        "hold_pressure_max_link_mm": float(max(0.0, hold_pressure_max_link_mm)),
        "pressurised_forced_hop_links": 0,
        "same_material_chain_across_locations": int(bool(same_material_chain_across_locations)),
        "same_material_location_links": 0,
        "initial_pressurised": int(bool((pressure_state or {}).get("pressurised", False))),
        "end_pressurised": int(bool((pressure_state or {}).get("pressurised", False))),
        "pressure_chain_final_retracts": 0,
        "reference_wipe_between_scanlines": int(bool(reference_wipe_between_scanlines)),
        "reference_wipe_scanlines": 0,
        "reference_wipe_total_distance_mm": 0.0,
        "reference_wipe_shortened_count": 0,
        "reference_wipe_moving_retract_total_mm": 0.0,
        "reference_wipe_final_retract_total_mm": 0.0,
        "reference_wipe_total_retract_mm": 0.0,
        "reference_retract_before_wipe_scanlines": 0,
        "reference_stationary_recovery_total_mm": 0.0,
        "reference_moving_recovery_total_mm": 0.0,
        "reference_total_recovery_mm": 0.0,
        "reference_moving_recovery_scanlines": 0,
        "reference_moving_recovery_distance_total_mm": 0.0,
        "reference_end_coast_scanlines": 0,
        "reference_end_coast_distance_total_mm": 0.0,
        "reference_start_flow_ramp_scanlines": 0,
        "reference_end_flow_ramp_scanlines": 0,
        "reference_start_flow_ramp_distance_total_mm": 0.0,
        "reference_end_flow_ramp_distance_total_mm": 0.0,
        "reference_flow_ramp_steps": int(flow_ramp_steps),
        "profile_start_trim_mm": float(physical_start_trim_mm),
        "profile_end_trim_mm": float(physical_end_trim_mm),
        "start_underfeed_length_mm": float(start_underfeed_length_mm),
        "start_underfeed_factor": float(start_underfeed_factor),
        "end_underfeed_length_mm": float(end_underfeed_length_mm),
        "end_underfeed_factor": float(end_underfeed_factor),
        "start_underfeed_scanlines": 0,
        "end_underfeed_scanlines": 0,
        "reference_cycle_balance_policy": cycle_balance_policy,
        "reference_intentional_under_recovery_total_mm": 0.0,
        "reference_print_mode_id": scan_mode_id,
        "reference_wipe_feed_mm_min": int(DIRECT_REFERENCE_WIPE_FEED_MM_MIN),
        "reference_retract_feed_mm_min": int(DIRECT_REFERENCE_RETRACT_FEED_MM_MIN),
        "planner_start_xy": (
            [float(planner_start_xy[0]), float(planner_start_xy[1])]
            if planner_start_xy is not None else None
        ),
        "fixed_scanline_order": str(fixed_scanline_order),
        "z_decimals": int(z_decimals),
    }
    if not segs:
        return current_xy, 0, empty_stats

    fixed_scanline_order = str(fixed_scanline_order or "ascending").strip().lower()
    if fixed_scanline_order not in {"ascending", "descending"}:
        raise RuntimeError(f"unsupported fixed_scanline_order {fixed_scanline_order!r}")

    hop_count = 0
    stats = dict(empty_stats)
    stats["fixed_scanline_order"] = fixed_scanline_order
    pressurised = bool((pressure_state or {}).get("pressurised", False))
    if bool(reference_wipe_between_scanlines) and (
        bool(hold_pressure_across_forced_hops)
        or bool(same_material_chain_across_locations)
        or pressurised
    ):
        raise RuntimeError(
            "reference-wipe scanline transitions are mutually exclusive with "
            "live pressure chaining or an inherited pressurised state"
        )
    if bool(reference_wipe_between_scanlines):
        actual_deficit = total_retract_mm - total_recovery_mm
        if cycle_balance_policy == "strict" and abs(actual_deficit) > 1e-9:
            raise RuntimeError(
                f"reference-wipe print mode {scan_mode_id!r} is not filament-balanced: "
                f"recovery={total_recovery_mm:.5f} retract={total_retract_mm:.5f}"
            )
        if cycle_balance_policy == "allow_under_recovery" and (
            actual_deficit < -1e-9 or abs(actual_deficit - intentional_under_recovery_mm) > 1e-9
        ):
            raise RuntimeError(
                f"reference-wipe print mode {scan_mode_id!r} under-recovery contract mismatch: "
                f"recovery={total_recovery_mm:.5f} retract={total_retract_mm:.5f} "
                f"deficit={actual_deficit:.5f}/{intentional_under_recovery_mm:.5f}"
            )
        if cycle_balance_policy == "allow_over_recovery" and (
            actual_deficit > 1e-9 or -actual_deficit > 0.10 + 1e-9
        ):
            raise RuntimeError(
                f"reference-wipe print mode {scan_mode_id!r} over-recovery contract mismatch: "
                f"recovery={total_recovery_mm:.5f} retract={total_retract_mm:.5f} deficit={actual_deficit:.5f}"
            )
        if moving_recovery_mm > 0.0 and (
            moving_recovery_distance_mm <= 0.02 or moving_recovery_steps < 1
        ):
            raise RuntimeError(
                f"reference-wipe print mode {scan_mode_id!r} has invalid moving recovery geometry"
            )

    # PPSPV14 hard locality cap.  Studio's internal live gaps are overwhelmingly
    # <= ~1.0 mm and practically capped around 1.2 mm.  Clamp all pressurised
    # continuation thresholds here so a command-line value such as 1.5 mm cannot
    # accidentally create long live gaps.
    hard_live_cap = max(0.0, float(globals().get("PSP_LIVE_GAP_HARD_CAP_MM", 1.20)))
    chain_max_travel_mm = min(float(chain_max_travel_mm), hard_live_cap)
    raster_gap_always_continue_mm = min(float(raster_gap_always_continue_mm), hard_live_cap)
    raster_gap_conditional_continue_mm = min(float(raster_gap_conditional_continue_mm), hard_live_cap)
    stats["pspv14_hard_live_gap_cap_mm"] = hard_live_cap
    stats["effective_chain_max_travel_mm"] = float(chain_max_travel_mm)
    stats["effective_raster_gap_always_continue_mm"] = float(raster_gap_always_continue_mm)
    stats["effective_raster_gap_conditional_continue_mm"] = float(raster_gap_conditional_continue_mm)

    def point(axis, fixed, v):
        return (v, fixed) if axis == "X" else (fixed, v)

    pressure_hold_link_limit = max(0.0, float(hold_pressure_max_link_mm))

    def can_hold_pressure_for_forced_hop(start_xy, end_xy) -> bool:
        """Authorise a lifted no-E link while the current material stays live.

        v1.66 authorises only the short step between adjacent experimental
        roads. v1.67 same-material mode deliberately removes the distance/tile
        restriction, but still refuses a link through the prime tower.
        """
        if not bool(hold_pressure_across_forced_hops) or start_xy is None:
            return False
        link = math.hypot(float(end_xy[0]) - float(start_xy[0]), float(end_xy[1]) - float(start_xy[1]))
        if link <= 0.02:
            return False
        if _segment_intersects_tower_bbox(start_xy, end_xy, tower_bbox, inflate=0.35):
            return False
        if bool(same_material_chain_across_locations):
            return True
        return bool(link <= pressure_hold_link_limit + 1e-9)

    effective_tile_mm = directional_block_mm if directional_block_mm > 0 else local_tile_mm
    directional_merge_enabled = directional_block_mm > 0

    def tile_index(v: float) -> int:
        return int(math.floor(v / max(effective_tile_mm, 0.001)))

    def split_axis_segment_to_tiles(axis: str, fixed: float, a: float, b: float):
        """Yield (tile_y,tile_x,axis,fixed,span_a,span_b) clipped to local windows."""
        lo, hi = sorted((a, b))
        if hi <= lo + 1e-9:
            return
        if axis == "X":
            ty = tile_index(fixed)
            tx0 = tile_index(lo)
            tx1 = tile_index(max(lo, hi - 1e-9))
            for tx in range(tx0, tx1 + 1):
                c0 = max(lo, tx * effective_tile_mm)
                c1 = min(hi, (tx + 1) * effective_tile_mm)
                if c1 > c0 + 0.02:
                    yield (ty, tx, axis, fixed, c0, c1)
        else:
            tx = tile_index(fixed)
            ty0 = tile_index(lo)
            ty1 = tile_index(max(lo, hi - 1e-9))
            for ty in range(ty0, ty1 + 1):
                c0 = max(lo, ty * effective_tile_mm)
                c1 = min(hi, (ty + 1) * effective_tile_mm)
                if c1 > c0 + 0.02:
                    yield (ty, tx, axis, fixed, c0, c1)

    # PPV96: group by tile + scanline only; keep dose on each span.
    local_groups = {}
    passthrough = []
    for s in segs:
        x0, y0, x1, y1 = seg_xy(s)
        dose = round(seg_dose(s), 6)
        if abs(y0 - y1) < 1e-6:
            fixed = round(y0, 5)
            a, b = sorted((x0, x1))
            for ty, tx, axis, fixed2, c0, c1 in split_axis_segment_to_tiles("X", fixed, a, b):
                local_groups.setdefault((ty, tx, axis, fixed2), []).append((c0, c1, float(dose)))
        elif abs(x0 - x1) < 1e-6:
            fixed = round(x0, 5)
            a, b = sorted((y0, y1))
            for ty, tx, axis, fixed2, c0, c1 in split_axis_segment_to_tiles("Y", fixed, a, b):
                local_groups.setdefault((ty, tx, axis, fixed2), []).append((c0, c1, float(dose)))
        else:
            passthrough.append(s)

    # Defensive fallback for unexpected non-axis-aligned segments.
    for s in passthrough:
        current_xy, did = append_segment(
            g, *seg_xy(s), z, h, current_xy, span_index, tower_bbox,
            line_w=line_w, feed=feed, e_multiplier=seg_dose(s),
            force_hop=bool(force_travel_hops), z_decimals=int(z_decimals),
        )
        hop_count += int(did)

    if pure_grid_mode:
        # Diagnostic path: local tile clipping only.
        #
        # Do not merge same-material spans, do not chain same-scanline gaps, do not
        # rejoin across tile boundaries, do not do variable-dose continuity
        # optimisation.  Emit each tile-clipped span as a normal independent
        # segment through append_segment, so the print isolates the effect of
        # local grid splitting and repeated segment starts/ends.
        pure_tile_map = {}
        for (ty, tx, axis, fixed), spans in local_groups.items():
            for c0, c1, dose in spans:
                if c1 > c0 + 0.02:
                    pure_tile_map.setdefault((ty, tx), []).append((axis, fixed, c0, c1, float(dose)))

        def _pure_tile_sort_key(k):
            ty, tx = k
            orient = (layer_orientation or "X").upper()
            if orient == "Y":
                return (tx, ty)
            return (ty, tx)

        g += [
            "; STUDIO_LOCAL_RASTER_MODE_START PURE_GRID_TILE_SPLIT_DIAGNOSTIC",
            f"; STUDIO_LOCAL_TILE_MM: {effective_tile_mm:.3f}",
            "; PURE_GRID_MODE: enabled=1",
            "; PURE_GRID_RULE: tile_clip_only_no_scanline_merge_no_gap_live_continue_no_directional_merge",
            f"M204 S{print_acceleration_for_layer_height(h)}",
            f"G1 F{feed}",
        ]

        for tile_key in sorted(pure_tile_map.keys(), key=_pure_tile_sort_key):
            ty, tx = tile_key
            stats["local_tiles"] += 1
            g.append(f"; PURE_GRID_TILE_START tx={tx} ty={ty}")
            tile_spans = pure_tile_map[tile_key]
            tile_spans.sort(key=lambda item: (0 if item[0] == "X" else 1, item[1], item[2], item[3], item[4]))
            for axis, fixed, c0, c1, dose in tile_spans:
                if axis == "X":
                    x0, y0, x1, y1 = c0, fixed, c1, fixed
                else:
                    x0, y0, x1, y1 = fixed, c0, fixed, c1
                current_xy, did = append_segment(
                    g, x0, y0, x1, y1, z, h, current_xy, span_index, tower_bbox,
                    line_w=line_w, feed=feed, e_multiplier=dose,
                    force_hop=bool(force_travel_hops), z_decimals=int(z_decimals),
                )
                hop_count += int(did)
                stats["pure_grid_segments"] += 1
            g.append(f"; PURE_GRID_TILE_END tx={tx} ty={ty}")
        g.append("; STUDIO_LOCAL_RASTER_MODE_END PURE_GRID_TILE_SPLIT_DIAGNOSTIC")
        merge_report = {
            "directional_merge_enabled": 0,
            "directional_merge_edges": 0,
            "directional_merge_groups": len(pure_tile_map),
            "directional_merge_note": "pure-grid diagnostic: no directional merge or scanline rejoin applied",
        }
        stats.update(merge_report)
        return current_xy, hop_count, stats

    def _merge_same_dose_spans(spans):
        """Merge only overlapping/touching spans with the same dose.

        Different-dose spans remain separate G1 extrusion moves, but because they
        are in one scanline group they can be emitted in one continuous chain.
        """
        if not spans:
            return []
        spans = sorted((min(a, b), max(a, b), float(d)) for a, b, d in spans)
        merged = []
        for a, b, d in spans:
            if merged and abs(d - merged[-1][2]) < 1e-9 and a <= merged[-1][1] + 1e-9:
                merged[-1] = (merged[-1][0], max(merged[-1][1], b), merged[-1][2])
            else:
                # If spans overlap but use different dose, clip conservatively by
                # preserving order.  This should be rare; exact same-material cells
                # normally occupy disjoint centreline intervals.
                if merged and a < merged[-1][1] - 1e-9 and abs(d - merged[-1][2]) >= 1e-9:
                    a = merged[-1][1]
                    if b <= a + 0.02:
                        continue
                merged.append((a, b, d))
        return merged

    tile_map = {}
    for (ty, tx, axis, fixed), spans in local_groups.items():
        merged = _merge_same_dose_spans(spans)
        if merged:
            tile_map.setdefault((ty, tx), []).append((axis, fixed, merged))

    # v1.125 stable serpentine parity: index each emitted road by its ordered
    # axis-local fixed coordinate, never by round(absolute_fixed / road_width).
    axis_fixed_values = {
        axis: sorted({
            round(float(fixed), 5)
            for scanlines in tile_map.values()
            for a, fixed, _spans in scanlines
            if a == axis
        })
        for axis in ("X", "Y")
    }
    axis_fixed_index = {
        axis: {fixed: idx for idx, fixed in enumerate(values)}
        for axis, values in axis_fixed_values.items()
    }

    # PPV96 keeps the caller-visible directional merge arguments, but the safe
    # variable-dose first pass deliberately does not union tiles.  The local-grid
    # behaviour remains intact.  Full directional union can be reintroduced later
    # on top of variable-dose spans once the basic optimisation is print-tested.
    merge_report = {
        "directional_merge_enabled": int(bool(directional_merge_enabled)),
        "directional_merge_edges": 0,
        "directional_merge_groups": len(tile_map),
        "directional_merge_note": "ppv96 variable-dose pass keeps local tiles; directional tile union intentionally not applied in this revision",
    }

    def tile_sort_key(k):
        ty, tx = k
        orient = (layer_orientation or "X").upper()
        if orient == "Y":
            return (tx, ty)
        return (ty, tx)

    ordered_tiles = sorted(tile_map.keys(), key=tile_sort_key)

    g += [
        "; STUDIO_LOCAL_RASTER_MODE_START local_region_scanline_chains_ppv96_variable_dose",
        f"; STUDIO_LOCAL_TILE_MM: {effective_tile_mm:.3f}",
        f"; STUDIO_RASTER_CHAIN_MAX_TRAVEL_MM: {chain_max_travel_mm:.3f}",
        f"; STUDIO_RASTER_GAP_FLOW_MAX_MM: {gap_flow_max_mm:.3f}",
        f"; STUDIO_RASTER_GAP_FLOW_RATIO: {gap_flow_ratio:.4f}",
        f"; STUDIO_RASTER_GAP_ALWAYS_CONTINUE_MM: {float(raster_gap_always_continue_mm):.3f}",
        f"; STUDIO_RASTER_GAP_CONDITIONAL_CONTINUE_MM: {float(raster_gap_conditional_continue_mm):.3f}",
        f"; VARIABLE_DOSE_CHAIN_OPTIMISE: enabled=1 grouping=axis_fixed span_dose_preserved",
        f"; DIRECTIONAL_MERGE: enabled={int(directional_merge_enabled)} block={effective_tile_mm:.3f} join_gap={float(directional_join_gap_mm):.3f} threshold={int(directional_join_threshold)} ppv96_local_tiles_preserved=1",
        f"M204 S{print_acceleration_for_layer_height(h)}",
        f"G1 F{feed}",
    ]

    def choose_scanline_direction(axis, fixed, spans, prefer_from=None):
        direction_mode = str(forced_scanline_direction or "serpentine").strip().lower()
        if direction_mode == "left_to_right":
            return False
        if direction_mode == "right_to_left":
            return True
        if direction_mode not in {"serpentine", "auto"}:
            raise RuntimeError(f"unsupported forced_scanline_direction {direction_mode!r}")
        fixed_key = round(float(fixed), 5)
        road_index = axis_fixed_index.get(axis, {}).get(fixed_key)
        if road_index is None:
            raise RuntimeError(
                f"v1.125 serpentine lattice audit failed for axis={axis} fixed={fixed_key:.5f}"
            )
        default_reverse = bool(int(road_index) % 2)
        if prefer_from is None or not spans:
            return default_reverse
        a0, b0, _d0 = spans[0]
        al, bl, _dl = spans[-1]
        start_forward = point(axis, fixed, a0)
        start_reverse = point(axis, fixed, bl)
        df = math.hypot(start_forward[0] - prefer_from[0], start_forward[1] - prefer_from[1])
        dr = math.hypot(start_reverse[0] - prefer_from[0], start_reverse[1] - prefer_from[1])
        if abs(df - dr) > 0.05:
            return dr < df
        return default_reverse

    def emit_scanline(axis, fixed, spans, reverse, pressurised):
        nonlocal current_xy, hop_count, stats
        spans_iter = list(reversed(spans)) if reverse else list(spans)
        if not spans_iter:
            return pressurised
        start_a, start_b, _start_dose = spans_iter[0]
        first_v = (start_b - physical_start_trim_mm) if reverse else (start_a + physical_start_trim_mm)
        first_xy = point(axis, fixed, first_v)
        if physical_start_trim_mm > 0.0 or physical_end_trim_mm > 0.0:
            g.append(
                f"; FC3D_PROFILE_ENDPOINT_TRIM start={physical_start_trim_mm:.3f} "
                f"end={physical_end_trim_mm:.3f} reverse={int(bool(reverse))}"
            )
        link_dist = (
            math.hypot(first_xy[0] - current_xy[0], first_xy[1] - current_xy[1])
            if current_xy is not None else float("inf")
        )
        keep_pressure_for_hop = bool(
            force_travel_hops
            and pressurised
            and (
                bool(same_material_chain_across_locations)
                or link_dist <= chain_max_travel_mm + 1e-9
            )
            and can_hold_pressure_for_forced_hop(current_xy, first_xy)
        )

        g.append(
            f"; FC3D_RASTER_SCANLINE_DIRECTION mode={str(forced_scanline_direction)} "
            f"reverse={int(bool(reverse))} fixed={float(fixed):.3f}"
        )
        unique_doses = {round(float(d), 6) for _a, _b, d in spans_iter}
        if len(unique_doses) > 1:
            stats["variable_dose_scanlines"] += 1

        need = bool(force_travel_hops and current_xy is not None)
        if not need and current_xy is not None:
            need = travel_needs_hop(current_xy, first_xy, span_index, z, tower_bbox)

        if need and current_xy is not None and pressurised and not keep_pressure_for_hop:
            g.append("G1 E-0.4 F1800 ; retract before checked local-raster travel")
            pressurised = False

        if current_xy is None or math.hypot(first_xy[0] - current_xy[0], first_xy[1] - current_xy[1]) > 0.02:
            current_xy, did_hop = append_checked_travel_xy(
                g, current_xy, first_xy, z, span_index, tower_bbox,
                feed=(feed if pressurised else 60000), reason="LOCAL_RASTER", restore_z=False,
                force_hop=bool(force_travel_hops), z_decimals=int(z_decimals),
            )
            hop_count += int(did_hop)
            if did_hop and keep_pressure_for_hop and pressurised:
                stats["pressurised_forced_hop_links"] += 1
                if bool(same_material_chain_across_locations):
                    stats["same_material_location_links"] += 1
            if pressurised and not did_hop:
                stats["unretracted_links"] += 1
            if did_hop:
                g.append(f"G1 F{feed}")

        pending_moving_recovery_mm = 0.0
        pending_moving_recovery_distance_mm = 0.0
        pending_moving_recovery_steps = 0
        if not pressurised:
            if bool(reference_wipe_between_scanlines):
                if stationary_recovery_components:
                    for _ri, _comp in enumerate(stationary_recovery_components, 1):
                        _mm = float(_comp["mm"]); _rf = int(round(float(_comp["feed_mm_min"])))
                        g.append(f"G1 E{_mm:.5f} F{_rf} ; FC3D_SCANLINE_STATIONARY_RECOVERY_COMPONENT mode={scan_mode_id} part={_ri}/{len(stationary_recovery_components)}")
                elif stationary_recovery_mm > 1e-9:
                    g.append(
                        f"G1 E{stationary_recovery_mm:.5f} F{int(round(stationary_recovery_feed_mm_min))} "
                        f"; FC3D_SCANLINE_STATIONARY_RECOVERY mode={scan_mode_id}"
                    )
                if stationary_recovery_dwell_ms > 0:
                    g.append(f"G4 P{stationary_recovery_dwell_ms} ; FC3D_SCANLINE_RECOVERY_DWELL mode={scan_mode_id}")
                pending_moving_recovery_mm = float(moving_recovery_mm)
                pending_moving_recovery_distance_mm = float(moving_recovery_distance_mm)
                pending_moving_recovery_steps = int(moving_recovery_steps)
                stats["reference_stationary_recovery_total_mm"] += float(stationary_recovery_mm)
                stats["reference_total_recovery_mm"] += float(total_recovery_mm)
                stats["reference_intentional_under_recovery_total_mm"] += float(intentional_under_recovery_mm)
                if moving_recovery_mm > 0.0:
                    stats["reference_moving_recovery_scanlines"] += 1
                    stats["reference_moving_recovery_total_mm"] += float(moving_recovery_mm)
                    stats["reference_moving_recovery_distance_total_mm"] += float(moving_recovery_distance_mm)
            else:
                g.append("G1 E0.4 F1800 ; prime local-raster chain")
            g.append(f"G1 F{feed}")
            pressurised = True
            stats["chains"] += 1

        cur_xy = first_xy
        prev_dose = None
        last_print_p0 = None
        last_print_p1 = None
        last_print_length = 0.0
        retracted_before_end_coast = False
        stats["scanlines"] += 1
        for span_i, (a, b, dose) in enumerate(spans_iter):
            s0, s1 = (b, a) if reverse else (a, b)
            if span_i == 0 and physical_start_trim_mm > 0.0:
                s0 = s0 - physical_start_trim_mm if reverse else s0 + physical_start_trim_mm
            if span_i == len(spans_iter) - 1 and physical_end_trim_mm > 0.0:
                s1 = s1 + physical_end_trim_mm if reverse else s1 - physical_end_trim_mm
            if abs(s1 - s0) <= 0.02:
                raise RuntimeError(
                    f"profile endpoint trims collapse scanline: start_trim={physical_start_trim_mm:.5f} "
                    f"end_trim={physical_end_trim_mm:.5f} span={abs(b-a):.5f}"
                )
            p0 = point(axis, fixed, s0)
            p1 = point(axis, fixed, s1)

            gap_len = math.hypot(p0[0] - cur_xy[0], p0[1] - cur_xy[1])
            if gap_len > 0.02:
                gap_clear = True
                if gap_len > float(raster_gap_always_continue_mm) and span_index is not None:
                    gap_clear = not span_index.swept_line_hits(cur_xy[0], cur_xy[1], p0[0], p0[1], z, TRAVEL_SWEEP_W_MM)
                same_material_live_cross = bool(
                    force_travel_hops
                    and pressurised
                    and bool(same_material_chain_across_locations)
                    and can_hold_pressure_for_forced_hop(cur_xy, p0)
                )
                can_live_cross = bool(
                    same_material_live_cross
                    or (
                        not force_travel_hops
                        and (
                            gap_len <= float(raster_gap_always_continue_mm)
                            or (gap_len <= float(raster_gap_conditional_continue_mm) and gap_clear)
                        )
                    )
                )
                if can_live_cross:
                    stats["same_scanline_live_gap_moves"] += 1
                    if same_material_live_cross:
                        stats["same_material_location_links"] += 1
                    # PPSPV19: preferred Studio-like safe-gap behaviour.
                    # Keep the nozzle pressurised, cross the short same-scanline
                    # gap with NO commanded E, then continue extruding the next
                    # span.  This avoids a retract/reprime pressure reset without
                    # intentionally filling the gap.  Optional gap-flow extrusion
                    # remains available only when explicitly requested.
                    if 0 < gap_flow_max_mm and gap_len <= gap_flow_max_mm and gap_flow_ratio > 0:
                        flow_dose = float(dose if prev_dose is None else min(prev_dose, dose))
                        g.append(f"G1 X{p0[0]:.3f} Y{p0[1]:.3f} E{e_for_len(gap_len,h,line_w,material=material)*flow_dose*gap_flow_ratio:.5f} F{feed}")
                        if span_index is not None:
                            span_index.add_segment(cur_xy[0], cur_xy[1], p0[0], p0[1], z, line_w)
                        stats["gap_flow_moves"] += 1
                    else:
                        need_live_hop = travel_needs_hop(cur_xy, p0, span_index, z, tower_bbox)
                        if need_live_hop and pressurised and not same_material_live_cross:
                            stats["pressurised_noe_gap_hop_retracts"] += 1
                            g.append("G1 E-0.4 F1800 ; retract before checked same-scanline travel")
                            pressurised = False
                        before_gap_pressurised = bool(pressurised)
                        cur_xy, did_hop = append_checked_travel_xy(
                            g, cur_xy, p0, z, span_index, tower_bbox,
                            feed=(feed if pressurised else 60000), reason="PRESSURISED_NOE_SCANLINE_GAP", restore_z=False,
                            force_hop=bool(force_travel_hops), z_decimals=int(z_decimals),
                        )
                        hop_count += int(did_hop)
                        if did_hop:
                            g.append(f"G1 F{feed}")
                        if before_gap_pressurised and not did_hop:
                            stats["pressurised_noe_gap_moves"] += 1
                            stats["pressurised_noe_gap_total_mm"] += float(gap_len)
                            stats["pressurised_noe_gap_max_mm"] = max(float(stats.get("pressurised_noe_gap_max_mm", 0.0)), float(gap_len))
                        if not pressurised:
                            g.append("G1 E0.4 F1800 ; reprime after checked same-scanline travel")
                            g.append(f"G1 F{feed}")
                            pressurised = True
                            stats["chains"] += 1
                else:
                    if gap_len > float(raster_gap_conditional_continue_mm):
                        stats["pressurised_noe_gap_rejected_too_long"] += 1
                    elif not gap_clear:
                        stats["pressurised_noe_gap_rejected_collision"] += 1
                    stats["same_scanline_long_gap_retracts"] += 1
                    if pressurised:
                        g.append("G1 E-0.4 F1800 ; retract before long same-scanline gap")
                        pressurised = False
                    need_gap_hop = travel_needs_hop(cur_xy, p0, span_index, z, tower_bbox)
                    cur_xy, did_hop = append_checked_travel_xy(
                        g, cur_xy, p0, z, span_index, tower_bbox,
                        feed=60000, reason="LONG_SCANLINE_GAP",
                        force_hop=bool(force_travel_hops or need_gap_hop), restore_z=False,
                        z_decimals=int(z_decimals),
                    )
                    hop_count += int(did_hop)
                    if did_hop:
                        g.append(f"G1 F{feed}")
                        g.append(f"G1 F{feed}")
                    g.append("G1 E0.4 F1800 ; reprime after long same-scanline gap")
                    g.append(f"G1 F{feed}")
                    pressurised = True
                    stats["chains"] += 1

            length = abs(s1 - s0)
            if length > 0.02:
                if prev_dose is not None:
                    if abs(float(dose) - float(prev_dose)) > 1e-6 and gap_len <= 0.02:
                        stats["variable_dose_span_transitions"] += 1
                    elif gap_len <= 0.02:
                        stats["same_dose_span_transitions"] += 1

                # v1.76 optional no-E coast on only the final span of the
                # scanline.  The head still reaches the same commanded endpoint;
                # normal dose simply stops slightly early so residual melt
                # pressure can finish the line while the nozzle remains moving.
                coast_distance = 0.0
                if (
                    bool(reference_wipe_between_scanlines)
                    and span_i == len(spans_iter) - 1
                    and end_coast_distance_mm > 0.0
                ):
                    coast_distance = min(float(end_coast_distance_mm), max(0.0, float(length) - 0.02))
                extrude_length = max(0.0, float(length) - coast_distance)
                ux_print = (float(p1[0]) - float(p0[0])) / float(length)
                uy_print = (float(p1[1]) - float(p0[1])) / float(length)
                extrude_end = (
                    float(p0[0]) + ux_print * extrude_length,
                    float(p0[1]) + uy_print * extrude_length,
                )

                emitted_start = p0
                if pending_moving_recovery_mm > 0.0:
                    recovery_distance = min(float(pending_moving_recovery_distance_mm), extrude_length)
                    if recovery_distance <= 0.02:
                        raise RuntimeError(
                            f"print mode {scan_mode_id!r} could not fit moving recovery into the first printed span"
                        )
                    steps = max(1, int(pending_moving_recovery_steps))
                    weight_sum = float(steps * (steps + 1) / 2)
                    previous = p0
                    for step_i in range(steps):
                        frac = float(step_i + 1) / float(steps)
                        q = (
                            float(p0[0]) + ux_print * recovery_distance * frac,
                            float(p0[1]) + uy_print * recovery_distance * frac,
                        )
                        step_len = math.hypot(float(q[0]) - float(previous[0]), float(q[1]) - float(previous[1]))
                        recovery_e = float(pending_moving_recovery_mm) * float(step_i + 1) / weight_sum
                        normal_e = e_for_len(step_len, h, line_w, material=material) * float(dose)
                        g.append(
                            f"G1 X{q[0]:.3f} Y{q[1]:.3f} E{normal_e + recovery_e:.5f} "
                            f"; FC3D_MOVING_RECOVERY mode={scan_mode_id} step={step_i+1}/{steps} "
                            f"recovery_E={recovery_e:.5f}"
                        )
                        previous = q
                    emitted_start = previous
                    pending_moving_recovery_mm = 0.0
                    pending_moving_recovery_distance_mm = 0.0
                    pending_moving_recovery_steps = 0

                is_first_span = span_i == 0
                is_final_span = span_i == len(spans_iter) - 1
                available_len = math.hypot(
                    float(extrude_end[0]) - float(emitted_start[0]),
                    float(extrude_end[1]) - float(emitted_start[1]),
                )
                start_ramp = min(float(start_flow_ramp_distance_mm), available_len) if is_first_span else 0.0
                end_ramp = min(float(end_flow_ramp_distance_mm), max(0.0, available_len - start_ramp)) if is_final_span else 0.0
                if start_ramp + end_ramp > available_len + 1e-9:
                    raise RuntimeError(f"print mode {scan_mode_id!r} flow ramps do not fit the printed span")

                previous = emitted_start
                if start_ramp > 1e-9:
                    steps = max(2, int(flow_ramp_steps))
                    for step_i in range(steps):
                        frac = float(step_i + 1) / float(steps)
                        q = (
                            float(emitted_start[0]) + ux_print * start_ramp * frac,
                            float(emitted_start[1]) + uy_print * start_ramp * frac,
                        )
                        step_len = math.hypot(float(q[0]) - float(previous[0]), float(q[1]) - float(previous[1]))
                        flow_fraction = float(step_i) / float(steps - 1)
                        normal_e = e_for_len(step_len, h, line_w, material=material) * float(dose) * flow_fraction
                        suffix = f" E{normal_e:.5f}" if normal_e > 0.0 else ""
                        g.append(
                            f"G1 X{q[0]:.3f} Y{q[1]:.3f}{suffix} "
                            f"; FC3D_START_FLOW_RAMP mode={scan_mode_id} step={step_i+1}/{steps} flow={flow_fraction:.6f}"
                        )
                        previous = q
                    stats["reference_start_flow_ramp_scanlines"] += 1
                    stats["reference_start_flow_ramp_distance_total_mm"] += float(start_ramp)

                # v1.99 constant-factor endpoint under-feed for stopped-tile seam
                # experiments.  This is deliberately distinct from the older
                # 0->1/1->0 ramps: the requested short interval is emitted at a
                # fixed fraction (e.g. 0.80) of normal dose.
                remaining_after_ramp = math.hypot(float(extrude_end[0])-float(previous[0]), float(extrude_end[1])-float(previous[1]))
                start_uf = min(start_underfeed_length_mm, remaining_after_ramp) if (is_first_span and start_ramp <= 1e-9) else 0.0
                end_uf = min(end_underfeed_length_mm, max(0.0, remaining_after_ramp - start_uf)) if (is_final_span and end_ramp <= 1e-9) else 0.0
                if start_uf > 1e-9:
                    q = (float(previous[0]) + ux_print*start_uf, float(previous[1]) + uy_print*start_uf)
                    g.append(
                        f"G1 X{q[0]:.3f} Y{q[1]:.3f} E{e_for_len(start_uf,h,line_w,material=material)*float(dose)*start_underfeed_factor:.5f} "
                        f"; FC3D_START_UNDERFEED distance={start_uf:.3f} factor={start_underfeed_factor:.3f}"
                    )
                    previous = q
                    stats["start_underfeed_scanlines"] += 1

                middle_end = (
                    float(extrude_end[0]) - ux_print * (end_ramp + end_uf),
                    float(extrude_end[1]) - uy_print * (end_ramp + end_uf),
                )
                middle_len = math.hypot(float(middle_end[0]) - float(previous[0]), float(middle_end[1]) - float(previous[1]))
                if middle_len > 0.02:
                    g.append(
                        f"G1 X{middle_end[0]:.3f} Y{middle_end[1]:.3f} "
                        f"E{e_for_len(middle_len,h,line_w,material=material)*float(dose):.5f}"
                    )
                    previous = middle_end

                if end_uf > 1e-9:
                    z_suffix = ""
                    if end_z_relief_distance_mm > 1e-9:
                        if abs(end_z_relief_distance_mm-end_uf) > 1e-6:
                            raise RuntimeError(f"print mode {scan_mode_id!r} end Z relief distance must match end underfeed distance")
                        z_suffix = f" Z{float(z)+end_z_relief_mm:.5f}"
                    g.append(
                        f"G1 X{extrude_end[0]:.3f} Y{extrude_end[1]:.3f}{z_suffix} E{e_for_len(end_uf,h,line_w,material=material)*float(dose)*end_underfeed_factor:.5f} "
                        f"; FC3D_END_UNDERFEED distance={end_uf:.3f} factor={end_underfeed_factor:.3f} z_relief={end_z_relief_mm:.5f}"
                    )
                    previous = extrude_end
                    stats["end_underfeed_scanlines"] += 1

                if end_ramp > 1e-9:
                    steps = max(2, int(flow_ramp_steps))
                    for step_i in range(steps):
                        frac = float(step_i + 1) / float(steps)
                        q = (
                            float(middle_end[0]) + ux_print * end_ramp * frac,
                            float(middle_end[1]) + uy_print * end_ramp * frac,
                        )
                        step_len = math.hypot(float(q[0]) - float(previous[0]), float(q[1]) - float(previous[1]))
                        flow_fraction = 1.0 - (1.0-end_flow_ramp_final_factor) * float(step_i) / float(steps - 1)
                        normal_e = e_for_len(step_len, h, line_w, material=material) * float(dose) * flow_fraction
                        suffix = f" E{normal_e:.5f}" if normal_e > 0.0 else ""
                        z_suffix = ""
                        if end_z_relief_distance_mm > 1e-9:
                            if abs(end_z_relief_distance_mm-end_ramp) > 1e-6:
                                raise RuntimeError(f"print mode {scan_mode_id!r} end Z relief distance must match end flow-ramp distance")
                            z_suffix = f" Z{float(z)+end_z_relief_mm*frac:.5f}"
                        g.append(
                            f"G1 X{q[0]:.3f} Y{q[1]:.3f}{z_suffix}{suffix} "
                            f"; FC3D_END_FLOW_RAMP mode={scan_mode_id} step={step_i+1}/{steps} flow={flow_fraction:.6f} final_factor={end_flow_ramp_final_factor:.3f} z_relief={end_z_relief_mm*frac:.5f}"
                        )
                        previous = q
                    stats["reference_end_flow_ramp_scanlines"] += 1
                    stats["reference_end_flow_ramp_distance_total_mm"] += float(end_ramp)
                if coast_distance > 0.0:
                    if retract_before_end_coast:
                        if not stationary_retract_components_mm:
                            raise RuntimeError(
                                f"print mode {scan_mode_id!r} retract_before_end_coast has no stationary retract components"
                            )
                        for component_index, component_mm in enumerate(stationary_retract_components_mm, 1):
                            if component_mm > 1e-9:
                                g.append(
                                    f"G1 E-{component_mm:.5f} F{int(DIRECT_REFERENCE_RETRACT_FEED_MM_MIN)} "
                                    f"; FC3D_END_EARLY_STATIONARY_RETRACT mode={scan_mode_id} "
                                    f"part={component_index}/{len(stationary_retract_components_mm)} "
                                    f"dry_tail={coast_distance:.3f}"
                                )
                        pressurised = False
                        retracted_before_end_coast = True
                    g.append(
                        f"G1 X{p1[0]:.3f} Y{p1[1]:.3f} F{int(NORMAL_LAYER_FEED)} "
                        f"; FC3D_END_COAST mode={scan_mode_id} distance={coast_distance:.3f} no_E"
                    )
                    stats["reference_end_coast_scanlines"] += 1
                    stats["reference_end_coast_distance_total_mm"] += float(coast_distance)
                if span_index is not None and extrude_length > 0.02:
                    span_index.add_segment(p0[0], p0[1], extrude_end[0], extrude_end[1], z, line_w)
                last_print_p0 = p0
                last_print_p1 = p1
                last_print_length = float(length)
            cur_xy = p1
            prev_dose = float(dose)
        current_xy = cur_xy
        if bool(reference_wipe_between_scanlines):
            if retracted_before_end_coast:
                if pressurised:
                    raise RuntimeError("early end-coast retract did not clear pressure state")
                current_xy = last_print_p1
                stats["reference_wipe_scanlines"] += 1
                stats["reference_wipe_final_retract_total_mm"] += float(total_retract_mm)
                stats["reference_wipe_total_retract_mm"] += float(total_retract_mm)
                return False
            if not pressurised:
                raise RuntimeError("reference-wipe scanline ended without a live extrusion state")
            if last_print_p0 is None or last_print_p1 is None or last_print_length <= 0.02:
                raise RuntimeError("reference-wipe scanline has no valid final printed segment")
            dx = float(last_print_p1[0]) - float(last_print_p0[0])
            dy = float(last_print_p1[1]) - float(last_print_p0[1])
            segment_length = math.hypot(dx, dy)
            if segment_length <= 0.02:
                raise RuntimeError("reference-wipe final printed segment is too short")
            if pending_moving_recovery_mm > 1e-9:
                raise RuntimeError(
                    f"print mode {scan_mode_id!r} scanline ended before its moving recovery was emitted"
                )
            if stationary_retract_components_mm:
                for component_index, component_mm in enumerate(stationary_retract_components_mm, 1):
                    if component_mm > 1e-9:
                        g.append(
                            f"G1 E-{component_mm:.5f} F{int(DIRECT_REFERENCE_RETRACT_FEED_MM_MIN)} "
                            f"; FC3D_REFERENCE_STATIONARY_RETRACT_COMPONENT mode={scan_mode_id} part={component_index}/{len(stationary_retract_components_mm)}"
                        )
                current_xy = last_print_p1
                pressurised = False
                stats["reference_wipe_scanlines"] += 1
                stats["reference_wipe_final_retract_total_mm"] += float(total_retract_mm)
                stats["reference_wipe_total_retract_mm"] += float(total_retract_mm)
                return pressurised
            wipe_distance = min(float(reference_wipe_distance_mm), float(segment_length))
            ux = dx / segment_length
            uy = dy / segment_length
            wipe_xy = (
                float(last_print_p1[0]) - ux * wipe_distance,
                float(last_print_p1[1]) - uy * wipe_distance,
            )
            if retract_before_wipe and reference_final_retract_mm > 1e-9:
                g.append(
                    f"G1 E-{reference_final_retract_mm:.5f} "
                    f"F{int(DIRECT_REFERENCE_RETRACT_FEED_MM_MIN)} "
                    f"; FC3D_REFERENCE_PRE_WIPE_RETRACT mode={scan_mode_id} total={total_retract_mm:.5f}"
                )
                stats["reference_retract_before_wipe_scanlines"] += 1
            g.append(f"; WIPE_START FC3D_DIRECT_REFERENCE_SCANLINE mode={scan_mode_id}")
            if wipe_distance > 1e-9:
                g.append(f"G1 F{int(DIRECT_REFERENCE_WIPE_FEED_MM_MIN)}")
                if reference_moving_retract_mm > 1e-9:
                    g.append(
                        f"G1 X{wipe_xy[0]:.3f} Y{wipe_xy[1]:.3f} "
                        f"E-{reference_moving_retract_mm:.5f} "
                        f"; FC3D_REFERENCE_MOVING_RETRACT mode={scan_mode_id} distance={wipe_distance:.3f}"
                    )
                else:
                    g.append(
                        f"G1 X{wipe_xy[0]:.3f} Y{wipe_xy[1]:.3f} "
                        f"; FC3D_REFERENCE_WIPE_ONLY mode={scan_mode_id} distance={wipe_distance:.3f}"
                    )
            else:
                if reference_moving_retract_mm > 1e-9:
                    raise RuntimeError(
                        f"print mode {scan_mode_id!r} requests moving retract without any wipe distance"
                    )
                g.append(f"; FC3D_REFERENCE_NO_WIPE mode={scan_mode_id}")
            g.append(f"; WIPE_END FC3D_DIRECT_REFERENCE_SCANLINE mode={scan_mode_id}")
            if (not retract_before_wipe) and reference_final_retract_mm > 1e-9:
                g.append(
                    f"G1 E-{reference_final_retract_mm:.5f} "
                    f"F{int(DIRECT_REFERENCE_RETRACT_FEED_MM_MIN)} "
                    f"; FC3D_REFERENCE_FINAL_RETRACT mode={scan_mode_id} total={total_retract_mm:.5f}"
                )
            current_xy = wipe_xy
            pressurised = False
            stats["reference_wipe_scanlines"] += 1
            stats["reference_wipe_total_distance_mm"] += float(wipe_distance)
            stats["reference_wipe_moving_retract_total_mm"] += float(reference_moving_retract_mm)
            stats["reference_wipe_final_retract_total_mm"] += float(reference_final_retract_mm)
            stats["reference_wipe_total_retract_mm"] += float(total_retract_mm)
            if wipe_distance < float(reference_wipe_distance_mm) - 1e-9:
                stats["reference_wipe_shortened_count"] += 1
        return pressurised

    planner_prev_end = (
        (float(planner_start_xy[0]), float(planner_start_xy[1]))
        if planner_start_xy is not None else current_xy
    )
    for tile_key in ordered_tiles:
        scanlines = tile_map[tile_key]
        if not scanlines:
            continue
        stats["local_tiles"] += 1
        ty, tx = tile_key
        g.append(f"; STUDIO_LOCAL_TILE_START tx={tx} ty={ty}")
        # The v1.66 rollback path resets pressure at every local tile. v1.67's
        # direct-card same-material path deliberately carries this state through
        # the tile marker because location alone is not a pressure boundary.
        if not bool(same_material_chain_across_locations):
            pressurised = False
        prev_end = planner_prev_end
        for axis in ("X", "Y"):
            axis_scanlines = [(a, f, s) for (a, f, s) in scanlines if a == axis]
            axis_scanlines.sort(
                key=lambda item: item[1],
                reverse=(fixed_scanline_order == "descending"),
            )
            fixed_sequence = [float(item[1]) for item in axis_scanlines]
            if fixed_sequence:
                if fixed_scanline_order == "ascending" and any(
                    b < a - 1e-9 for a, b in zip(fixed_sequence, fixed_sequence[1:])
                ):
                    raise RuntimeError("v1.125 fixed-axis monotonic ascending audit failed")
                if fixed_scanline_order == "descending" and any(
                    b > a + 1e-9 for a, b in zip(fixed_sequence, fixed_sequence[1:])
                ):
                    raise RuntimeError("v1.125 fixed-axis monotonic descending audit failed")
            for axis0, fixed, spans in axis_scanlines:
                reverse = choose_scanline_direction(axis0, fixed, spans, prev_end)
                if pressurised and current_xy is not None and spans:
                    spans_iter = list(reversed(spans)) if reverse else list(spans)
                    start_a, start_b, _start_dose = spans_iter[0]
                    first_v = start_b if reverse else start_a
                    first_xy = point(axis0, fixed, first_v)
                    link_dist = math.hypot(first_xy[0] - current_xy[0], first_xy[1] - current_xy[1])
                    pressure_hold_link = bool(
                        force_travel_hops
                        and (
                            bool(same_material_chain_across_locations)
                            or link_dist <= chain_max_travel_mm + 1e-9
                        )
                        and can_hold_pressure_for_forced_hop(current_xy, first_xy)
                    )
                    if (
                        (
                            not bool(same_material_chain_across_locations)
                            and link_dist > chain_max_travel_mm
                        )
                        or (force_travel_hops and not pressure_hold_link)
                        or (not force_travel_hops and travel_needs_hop(current_xy, first_xy, span_index, z, tower_bbox))
                    ):
                        g.append("G1 E-0.4 F1800 ; retract local-raster chain break")
                        pressurised = False
                pressurised = emit_scanline(axis0, fixed, spans, reverse, pressurised)
                prev_end = current_xy
                planner_prev_end = current_xy
        if pressurised and not bool(same_material_chain_across_locations):
            g.append("G1 E-0.4 F1800 ; retract end of local tile")
            pressurised = False
        g.append(f"; STUDIO_LOCAL_TILE_END tx={tx} ty={ty}")

    if pressurised and bool(same_material_chain_across_locations) and bool(retract_at_end):
        g.append("G1 E-0.4 F1800 ; retract end of same-material pressure chain")
        pressurised = False
        stats["pressure_chain_final_retracts"] += 1
    if pressure_state is not None:
        pressure_state["pressurised"] = bool(pressurised)
    stats["end_pressurised"] = int(bool(pressurised))
    g.append("; STUDIO_LOCAL_RASTER_MODE_END")
    stats.update(merge_report)
    return current_xy, hop_count, stats


def _psp_span_records_for_components(segs, line_w: float, join_gap_mm: float = 0.05):
    """Convert emitted segments to span records for PSP connected-component grouping."""
    records = []
    passthrough = []
    for i, s in enumerate(segs or []):
        x0, y0, x1, y1 = seg_xy(s)
        dose = seg_dose(s)
        if abs(y0 - y1) < 1e-6:
            a, b = sorted((x0, x1))
            if b - a > 0.02:
                records.append({"i": i, "axis": "X", "fixed": round(y0, 5), "a": a, "b": b, "dose": dose, "seg": s})
        elif abs(x0 - x1) < 1e-6:
            a, b = sorted((y0, y1))
            if b - a > 0.02:
                records.append({"i": i, "axis": "Y", "fixed": round(x0, 5), "a": a, "b": b, "dose": dose, "seg": s})
        else:
            passthrough.append(s)
    return records, passthrough


def _psp_axis_local_fixed_bins(recs):
    """Map distinct fixed coordinates to deterministic ordered local raster bins.

    v1.125 deliberately avoids absolute-coordinate ``round(fixed / pitch)``.
    Half-pitch coordinates such as 120.2/0.4 == 300.5 otherwise hit Python's
    ties-to-even rule and can alias one road then skip the next key.  Component
    grouping only needs a stable neighbour lookup; true adjacency is still
    verified by the physical fixed-coordinate distance test below.
    """
    fixed_values = sorted({round(float(r["fixed"]), 5) for r in (recs or [])})
    fixed_to_key = {fixed: index for index, fixed in enumerate(fixed_values)}
    if len(fixed_to_key) != len(fixed_values):
        raise RuntimeError("v1.125 axis-local raster bin audit produced duplicate keys")
    return fixed_to_key

def _psp_broad_raster_panel_info(component, line_w: float):
    """Return broad-panel traversal metadata for an already-formed component.

    This does not merge anything.  Existing PSP topology still decides which
    roads belong together.  The helper merely recognises a broad, contiguous,
    single-axis long-road component so v1.125 can prevent an interior entry seam.
    """
    if not component:
        return None
    axes = {str(r.get("axis", "")) for r in component}
    if len(axes) != 1:
        return None
    axis = next(iter(axes))
    if axis not in {"X", "Y"}:
        return None

    by_fixed = {}
    for r in component:
        fixed = round(float(r["fixed"]), 5)
        by_fixed.setdefault(fixed, []).append(r)
    fixed_values = sorted(by_fixed)
    if len(fixed_values) < 8:
        return None

    max_fixed_gap = max((b - a for a, b in zip(fixed_values, fixed_values[1:])), default=0.0)
    if max_fixed_gap > float(line_w) * 1.25 + 1e-9:
        return None

    road_extents = []
    for fixed in fixed_values:
        recs = by_fixed[fixed]
        lo = min(float(r["a"]) for r in recs)
        hi = max(float(r["b"]) for r in recs)
        road_extents.append((lo, hi, max(0.0, hi - lo)))
    lengths = sorted(ext[2] for ext in road_extents)
    median_length = lengths[len(lengths) // 2]
    if median_length < max(2.0, float(line_w) * 8.0):
        return None

    longitudinal_min = min(ext[0] for ext in road_extents)
    longitudinal_max = max(ext[1] for ext in road_extents)
    longitudinal_mid = 0.5 * (longitudinal_min + longitudinal_max)
    low_fixed = float(fixed_values[0])
    high_fixed = float(fixed_values[-1])
    if axis == "Y":
        low_edge_anchor = (low_fixed, longitudinal_mid)
        high_edge_anchor = (high_fixed, longitudinal_mid)
    else:
        low_edge_anchor = (longitudinal_mid, low_fixed)
        high_edge_anchor = (longitudinal_mid, high_fixed)
    return {
        "axis": axis,
        "road_count": int(len(fixed_values)),
        "low_fixed": low_fixed,
        "high_fixed": high_fixed,
        "median_road_length_mm": float(median_length),
        "low_edge_anchor": low_edge_anchor,
        "high_edge_anchor": high_edge_anchor,
    }

def _psp_connected_components_for_axis(records, line_w: float, join_gap_mm: float = 0.05,
                                       stable_half_pitch_bins: bool = False):
    """Return connected span-record components for one material/layer.

    ``stable_half_pitch_bins`` is retained for call compatibility only.  v1.125
    applies the stable axis-local rule to every PSP path so the old ambiguity
    cannot remain active outside the former direct-card experiment.
    """
    if not records:
        return []
    by_axis = {"X": [], "Y": []}
    for r in records:
        by_axis.setdefault(r["axis"], []).append(r)
    comps_all = []
    for axis, recs in by_axis.items():
        if not recs:
            continue
        n = len(recs)
        parent = list(range(n))
        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra

        fixed_to_key = _psp_axis_local_fixed_bins(recs)
        line_map = {}
        for j, r in enumerate(recs):
            fixed = round(float(r["fixed"]), 5)
            if fixed not in fixed_to_key:
                raise RuntimeError(f"v1.125 missing axis-local raster bin for fixed={fixed:.5f}")
            key = int(fixed_to_key[fixed])
            line_map.setdefault(key, []).append((j, r))

        # Every distinct physical road coordinate gets one and only one local
        # key. Multiple span records on the same road intentionally share it.
        if len(line_map) != len(fixed_to_key):
            raise RuntimeError(
                "v1.125 raster lattice audit failed: distinct fixed coordinates "
                "did not map one-to-one onto local bins"
            )

        for key, items in line_map.items():
            neighbours = []
            for nk in (key - 1, key, key + 1):
                neighbours.extend(line_map.get(nk, []))
            for j, r in items:
                for k, q in neighbours:
                    if k <= j:
                        continue
                    # Ordered bins are only a neighbour-search index. Physical
                    # spacing remains authoritative, so a genuinely missing road
                    # cannot be bridged merely because two surviving keys are adjacent.
                    if abs(r["fixed"] - q["fixed"]) > line_w * 1.25:
                        continue
                    if min(r["b"], q["b"]) + join_gap_mm >= max(r["a"], q["a"]):
                        union(j, k)
        comp_map = {}
        for j, r in enumerate(recs):
            comp_map.setdefault(find(j), []).append(r)
        comps_all.extend(comp_map.values())
    comps_all.sort(key=lambda comp: (-sum(abs(r["b"] - r["a"]) for r in comp), min(r["fixed"] for r in comp)))
    return comps_all


def _psp_component_bbox_and_anchor(component):
    xs = []
    ys = []
    for r in component:
        x0, y0, x1, y1 = seg_xy(r["seg"])
        xs += [x0, x1]
        ys += [y0, y1]
    if not xs:
        return (0, 0, 0, 0), (0, 0)
    bbox = (min(xs), min(ys), max(xs), max(ys))
    return bbox, ((bbox[0] + bbox[2]) * 0.5, (bbox[1] + bbox[3]) * 0.5)


def append_material_space_partition_segments(g, segs, z, h, current_xy, span_index: Optional[SpanCollisionIndex],
                                             tower_bbox=None, line_w=RUNTIME_PRINT_WIDTH_MM, feed=15000,
                                             chain_max_travel_mm: float = DEFAULT_RASTER_CHAIN_MAX_TRAVEL_MM,
                                             gap_flow_max_mm: float = DEFAULT_RASTER_GAP_FLOW_MAX_MM,
                                             gap_flow_ratio: float = DEFAULT_RASTER_GAP_FLOW_RATIO,
                                             raster_gap_always_continue_mm: float = RASTER_GAP_ALWAYS_CONTINUE_MM,
                                             raster_gap_conditional_continue_mm: float = RASTER_GAP_CONDITIONAL_CONTINUE_MM,
                                             directional_block_mm: float = 0.0,
                                             directional_join_gap_mm: float = DEFAULT_DIRECTIONAL_JOIN_GAP_MM,
                                             directional_join_threshold: int = DEFAULT_DIRECTIONAL_JOIN_THRESHOLD,
                                             endpoint_trim_mm: float = 0.0,
                                             min_trimmed_segment_mm: float = MIN_TRIMMED_SEGMENT_MM,
                                             layer_orientation: str = "X",
                                             force_travel_hops: bool = False,
                                             hold_pressure_across_forced_hops: bool = False,
                                             hold_pressure_max_link_mm: float = 0.0,
                                             pressure_state: Optional[Dict[str, bool]] = None,
                                             same_material_chain_across_locations: bool = False,
                                             retract_at_end: bool = True,
                                             reference_wipe_between_scanlines: bool = False,
                                             reference_wipe_profile: Optional[Dict[str, object]] = None,
                                             forced_scanline_direction: str = "serpentine",
                                             planner_start_xy: Optional[Tuple[float, float]] = None,
                                             z_decimals: int = 3,
                                             material: Optional[str] = None):
    """PPSPV14 space-partition pathing for one material/layer.

    This intentionally returns to the PPSPV3/PPSPV7 locality model.  The
    PPSPV8/PPSPV13 1.20 mm component pre-join experiment is disabled because it
    increased path count, retracts and Z-up moves.  Components are formed only
    from near-touching/overlapping spans using a very small tolerance, then the
    raster emitter applies the hard Studio-like live-gap cap.
    """
    stats = {
        "space_partition_mode": "connected-components-ppspv14-v7-locality-hard-gap-cap",
        "input_segments": int(len(segs or [])),
        "components": 0,
        "large_components": 0,
        "small_components": 0,
        "passthrough_segments": 0,
        "component_total_length_mm": 0.0,
        "largest_component_length_mm": 0.0,
        "component_emit_stats": [],
        "pressurised_noe_gap_moves": 0,
        "pressurised_noe_gap_total_mm": 0.0,
        "pressurised_noe_gap_max_mm": 0.0,
        "pressurised_noe_gap_hop_retracts": 0,
        "pressurised_noe_gap_rejected_too_long": 0,
        "pressurised_noe_gap_rejected_collision": 0,
        "gap_flow_moves": 0,
        "same_scanline_live_gap_moves": 0,
        "same_scanline_long_gap_retracts": 0,
        "local_tile_disabled_inside_components": True,
        "component_prejoin_enabled": False,
        "component_join_gap_mm": float(max(0.02, line_w * 0.10)),
        "live_gap_hard_cap_mm": float(globals().get("PSP_LIVE_GAP_HARD_CAP_MM", 1.20)),
        "force_travel_hops": int(bool(force_travel_hops)),
        "hold_pressure_across_forced_hops": int(bool(hold_pressure_across_forced_hops)),
        "hold_pressure_max_link_mm": float(max(0.0, hold_pressure_max_link_mm)),
        "pressurised_forced_hop_links": 0,
        "same_material_chain_across_locations": int(bool(same_material_chain_across_locations)),
        "same_material_location_links": 0,
        "initial_pressurised": int(bool((pressure_state or {}).get("pressurised", False))),
        "end_pressurised": int(bool((pressure_state or {}).get("pressurised", False))),
        "pressure_chain_final_retracts": 0,
        "chains": 0,
        "scanlines": 0,
        "reference_wipe_between_scanlines": int(bool(reference_wipe_between_scanlines)),
        "reference_wipe_scanlines": 0,
        "reference_wipe_total_distance_mm": 0.0,
        "reference_wipe_shortened_count": 0,
        "reference_wipe_moving_retract_total_mm": 0.0,
        "reference_wipe_final_retract_total_mm": 0.0,
        "reference_wipe_total_retract_mm": 0.0,
        "reference_retract_before_wipe_scanlines": 0,
        "reference_stationary_recovery_total_mm": 0.0,
        "reference_moving_recovery_total_mm": 0.0,
        "reference_total_recovery_mm": 0.0,
        "reference_moving_recovery_scanlines": 0,
        "reference_moving_recovery_distance_total_mm": 0.0,
        "reference_end_coast_scanlines": 0,
        "reference_end_coast_distance_total_mm": 0.0,
        "reference_intentional_under_recovery_total_mm": 0.0,
        "reference_print_mode_id": str((reference_wipe_profile or {}).get("id", "normal_reference")),
        "forced_scanline_direction": str(forced_scanline_direction),
        "planner_seed_xy": (
            [float(planner_start_xy[0]), float(planner_start_xy[1])]
            if planner_start_xy is not None else [0.0, 0.0]
        ),
        "planner_seed_mode": "virtual_material_pass_state_independent_of_physical_nozzle",
        "component_lattice_binning": "axis_local_ordered_fixed_coordinates_v1.125",
        "broad_raster_panels": 0,
        "broad_panel_low_edge_entries": 0,
        "broad_panel_high_edge_entries": 0,
        "z_decimals": int(z_decimals),
    }
    if not segs:
        return current_xy, 0, stats

    # PPSPV3/PPSPV7 grouping: only overlapping/touching/near-touching spans are
    # joined into a component.  Do not use the 1.20 mm Studio live-gap value for
    # component construction; that caused transitive component growth.
    psp_join_gap = max(0.02, line_w * 0.10)
    records, passthrough = _psp_span_records_for_components(segs, line_w=line_w, join_gap_mm=psp_join_gap)
    if (same_material_chain_across_locations or reference_wipe_between_scanlines) and passthrough:
        mode_name = (
            "same-material pressure chaining"
            if same_material_chain_across_locations
            else "reference-wipe scanline transitions"
        )
        raise RuntimeError(
            f"{mode_name} require axis-aligned direct-card roads; "
            f"found {len(passthrough)} passthrough segment(s)"
        )
    comps = _psp_connected_components_for_axis(
        records,
        line_w=line_w,
        join_gap_mm=psp_join_gap,
        # v1.125 is stable in every PSP path; argument retained for compatibility.
        stable_half_pitch_bins=True,
    )
    stats["components"] = int(len(comps) + len(passthrough))
    stats["passthrough_segments"] = int(len(passthrough))

    comp_items = []
    for comp in comps:
        length = float(sum(abs(r["b"] - r["a"]) for r in comp))
        bbox, anchor = _psp_component_bbox_and_anchor(comp)
        stats["component_total_length_mm"] += length
        stats["largest_component_length_mm"] = max(stats["largest_component_length_mm"], length)
        if length >= max(2.0, line_w * 8.0):
            stats["large_components"] += 1
        else:
            stats["small_components"] += 1
        panel_info = _psp_broad_raster_panel_info(comp, line_w=line_w)
        if panel_info is not None:
            stats["broad_raster_panels"] += 1
        comp_items.append({
            "records": comp,
            "length": length,
            "bbox": bbox,
            "anchor": anchor,
            "broad_panel": panel_info,
        })

    # v1.125 planner/physical separation.  Component order is planned from the
    # canonical virtual origin, never from actual post-tower current_xy. Small
    # components retain nearest-component locality. Broad already-rejoined panels
    # are costed only through their two outer fixed-axis edges; the opposite edge
    # becomes the planned exit for choosing the next component.
    ordered = []
    remaining = comp_items[:]
    planner_cur = (
        (float(planner_start_xy[0]), float(planner_start_xy[1]))
        if planner_start_xy is not None else (0.0, 0.0)
    )
    while remaining:
        candidates = []
        for i, candidate in enumerate(remaining):
            panel = candidate.get("broad_panel")
            if panel is not None:
                low = panel["low_edge_anchor"]
                high = panel["high_edge_anchor"]
                d_low = math.hypot(float(low[0]) - planner_cur[0], float(low[1]) - planner_cur[1])
                d_high = math.hypot(float(high[0]) - planner_cur[0], float(high[1]) - planner_cur[1])
                if d_low <= d_high:
                    cost = d_low
                    entry = "low"
                else:
                    cost = d_high
                    entry = "high"
            else:
                anchor = candidate["anchor"]
                cost = math.hypot(float(anchor[0]) - planner_cur[0], float(anchor[1]) - planner_cur[1])
                entry = None
            bbox = candidate["bbox"]
            candidates.append((float(cost), float(bbox[0]), float(bbox[1]), i, entry))

        _cost, _bx, _by, pick_i, entry = min(candidates)
        item = remaining.pop(pick_i)
        item["planner_start_xy"] = (float(planner_cur[0]), float(planner_cur[1]))
        item["planned_entry_edge"] = entry
        panel = item.get("broad_panel")
        if panel is not None:
            if entry == "high":
                item["fixed_scanline_order"] = "descending"
                planner_cur = tuple(panel["low_edge_anchor"])
                stats["broad_panel_high_edge_entries"] += 1
            else:
                item["fixed_scanline_order"] = "ascending"
                planner_cur = tuple(panel["high_edge_anchor"])
                stats["broad_panel_low_edge_entries"] += 1
        else:
            item["fixed_scanline_order"] = "ascending"
            planner_cur = tuple(item["anchor"])
        ordered.append(item)

    hop_count = 0
    physical_start_text = (
        f"{float(current_xy[0]):.3f},{float(current_xy[1]):.3f}"
        if current_xy is not None else "none"
    )
    planner_seed_effective = (
        (float(planner_start_xy[0]), float(planner_start_xy[1]))
        if planner_start_xy is not None else (0.0, 0.0)
    )
    stats["planner_end_xy"] = [float(planner_cur[0]), float(planner_cur[1])]
    g.append(
        f"; FC3D_PATH_PLANNER_SEED virtual_xy={planner_seed_effective[0]:.3f},{planner_seed_effective[1]:.3f} "
        f"physical_xy={physical_start_text} policy=v1.125_virtual_only_no_physical_move"
    )
    if PSP_EMIT_BODY_PATH_COMMENTS:
        g.append(f"; PPSPV14_SPACE_PARTITION_START components={len(ordered)} passthrough={len(passthrough)}")
    for ci, item in enumerate(ordered):
        comp_segs = [r["seg"] for r in item["records"]]
        bbox = item["bbox"]
        panel = item.get("broad_panel")
        if panel is not None:
            g.append(
                f"; FC3D_BROAD_PANEL_EDGE_ENTRY index={ci} axis={panel['axis']} "
                f"roads={panel['road_count']} entry={item.get('planned_entry_edge')} "
                f"fixed_order={item.get('fixed_scanline_order')} "
                f"low={panel['low_fixed']:.5f} high={panel['high_fixed']:.5f}"
            )
        if PSP_EMIT_BODY_PATH_COMMENTS:
            g.append(f"; PPSPV14_COMPONENT_START index={ci} spans={len(comp_segs)} length_mm={item['length']:.3f} bbox={bbox[0]:.3f},{bbox[1]:.3f},{bbox[2]:.3f},{bbox[3]:.3f}")
        current_xy, hops, substats = append_material_studio_raster_segments(
            g, comp_segs, z, h, current_xy, span_index, tower_bbox,
            line_w=line_w, feed=feed,
            chain_max_travel_mm=chain_max_travel_mm,
            gap_flow_max_mm=gap_flow_max_mm,
            gap_flow_ratio=gap_flow_ratio,
            raster_gap_always_continue_mm=raster_gap_always_continue_mm,
            raster_gap_conditional_continue_mm=raster_gap_conditional_continue_mm,
            local_tile_mm=1000000.0,
            pure_grid_mode=False,
            directional_block_mm=0.0,
            directional_join_gap_mm=directional_join_gap_mm,
            directional_join_threshold=directional_join_threshold,
            endpoint_trim_mm=endpoint_trim_mm,
            min_trimmed_segment_mm=min_trimmed_segment_mm,
            layer_orientation=layer_orientation,
            force_travel_hops=bool(force_travel_hops),
            hold_pressure_across_forced_hops=bool(hold_pressure_across_forced_hops),
            hold_pressure_max_link_mm=float(hold_pressure_max_link_mm),
            pressure_state=pressure_state,
            same_material_chain_across_locations=bool(same_material_chain_across_locations),
            retract_at_end=(False if same_material_chain_across_locations else True),
            reference_wipe_between_scanlines=bool(reference_wipe_between_scanlines),
            reference_wipe_profile=reference_wipe_profile,
            forced_scanline_direction=str(forced_scanline_direction),
            planner_start_xy=item.get("planner_start_xy"),
            fixed_scanline_order=str(item.get("fixed_scanline_order", "ascending")),
            z_decimals=int(z_decimals),
            material=material,
        )
        hop_count += int(hops)
        for _k in (
            "pressurised_noe_gap_moves",
            "pressurised_noe_gap_total_mm",
            "pressurised_noe_gap_hop_retracts",
            "pressurised_noe_gap_rejected_too_long",
            "pressurised_noe_gap_rejected_collision",
            "gap_flow_moves",
            "same_scanline_live_gap_moves",
            "same_scanline_long_gap_retracts",
            "pressurised_forced_hop_links",
            "same_material_location_links",
            "chains",
            "scanlines",
            "pressure_chain_final_retracts",
            "reference_wipe_scanlines",
            "reference_wipe_total_distance_mm",
            "reference_wipe_shortened_count",
            "reference_wipe_moving_retract_total_mm",
            "reference_wipe_final_retract_total_mm",
            "reference_wipe_total_retract_mm",
            "reference_retract_before_wipe_scanlines",
            "reference_stationary_recovery_total_mm",
            "reference_moving_recovery_total_mm",
            "reference_total_recovery_mm",
            "reference_moving_recovery_scanlines",
            "reference_moving_recovery_distance_total_mm",
            "reference_end_coast_scanlines",
            "reference_end_coast_distance_total_mm",
            "reference_intentional_under_recovery_total_mm",
        ):
            stats[_k] = stats.get(_k, 0) + substats.get(_k, 0)
        stats["pressurised_noe_gap_max_mm"] = max(float(stats.get("pressurised_noe_gap_max_mm", 0.0)), float(substats.get("pressurised_noe_gap_max_mm", 0.0)))
        if ci < 25:
            stats["component_emit_stats"].append({
                "index": int(ci),
                "spans": int(len(comp_segs)),
                "length_mm": float(item["length"]),
                "chains": int(substats.get("chains", 0)),
                "scanlines": int(substats.get("scanlines", 0)),
                "unretracted_links": int(substats.get("unretracted_links", 0)),
                "pressurised_noe_gap_moves": int(substats.get("pressurised_noe_gap_moves", 0)),
                "pressurised_noe_gap_total_mm": float(substats.get("pressurised_noe_gap_total_mm", 0.0)),
                "pressurised_noe_gap_max_mm": float(substats.get("pressurised_noe_gap_max_mm", 0.0)),
                "gap_flow_moves": int(substats.get("gap_flow_moves", 0)),
                "reference_wipe_scanlines": int(substats.get("reference_wipe_scanlines", 0)),
                "reference_wipe_total_distance_mm": float(substats.get("reference_wipe_total_distance_mm", 0.0)),
            })
        if PSP_EMIT_BODY_PATH_COMMENTS:
            g.append(f"; PPSPV14_COMPONENT_END index={ci}")

    for s in passthrough:
        current_xy, did = append_segment(
            g, *seg_xy(s), z, h, current_xy, span_index, tower_bbox,
            line_w=line_w, feed=feed, e_multiplier=seg_dose(s),
            force_hop=bool(force_travel_hops), z_decimals=int(z_decimals),
        )
        hop_count += int(did)
    if (
        bool(same_material_chain_across_locations)
        and bool(retract_at_end)
        and pressure_state is not None
        and bool(pressure_state.get("pressurised", False))
    ):
        g.append("G1 E-0.4 F1800 ; retract end of same-material component chain")
        pressure_state["pressurised"] = False
        stats["pressure_chain_final_retracts"] += 1
    stats["end_pressurised"] = int(bool((pressure_state or {}).get("pressurised", False)))
    # Once the deterministic virtual plan has selected the first path, every
    # emitted model endpoint is itself deterministic and independent of the
    # physical tower start.  Carry that exact endpoint into the next height
    # group rather than the component-centre approximation used while ordering.
    if current_xy is not None:
        stats["planner_end_xy"] = [float(current_xy[0]), float(current_xy[1])]
    if PSP_EMIT_BODY_PATH_COMMENTS:
        g.append("; PPSPV14_SPACE_PARTITION_END")
    return current_xy, hop_count, stats

def layer_header(layer_num,z,h,total_layers: int = TOTAL_LAYERS):
    print_accel = FIRST_LAYER_PRINT_ACCEL_MM_S2 if int(layer_num) == 1 else NORMAL_PRINT_ACCEL_MM_S2
    lines = ["; CHANGE_LAYER", f"; Z_HEIGHT: {z:.3f}", f"; LAYER_HEIGHT: {h:.3f}", f"; layer num/total_layer_count: {layer_num}/{total_layers}", f"M73 L{layer_num}", f"M991 S0 P{layer_num-1} ;notify layer change", "G90", "M83", f"M204 S{print_accel}", "G1 E-0.4 F1800"]
    if Z_HOP_MODE != "off":
        lines.append(f"G1 Z{z+HOP_Z_MM:.3f} F60000")
    lines.append(f"G1 Z{z:.3f} F6000")
    return lines

def material_switch(mat, current_tool, tool_map, blocks, purge_xy: Optional[Tuple[float, float]] = None,
                    safe_z: Optional[float] = None, cool_hotend: Optional[int] = None,
                    print_temp: int = 255, cool_temp: int = 50,
                    first_use_machine_prime: bool = False,
                    first_real_h2c_swap: bool = False,
                    machine_prime_xy: Optional[Tuple[float, float]] = None,
                    target_hotend: Optional[int] = None,
                    inactive_hotend: Optional[int] = None,
                    thermal_mode: str = "native",
                    precondition_temp: int = 215,
                    standby_temp: int = 215,
                    planner_guards: bool = True,
                    w_hotend_index: int = 0,
                    filament_type: str = "PETG",
                    tower_cooling_delta_c: int = 10):
    """Full H2C swap lifecycle using previous-tool M620.11 semantics.

    PPSPV43 correction:
    - PPSPV41 still failed at the first repeat return to W.
    - Deeper reference comparison showed the Bambu H2C filament-change block uses
      previous_extruder in M620.11 I..., not the target tool.
    - Repeat swaps need the same M620.10/M620.11/M628/M629/M983/G387 lifecycle as
      normal H2C changes, not the minimal repeat wrapper.

    The package metadata is active-job-only from W,F,R,Y,G,C,B.
    """
    tool = int(tool_map[mat])
    safe_z = 3.0 if safe_z is None else float(safe_z)
    if target_hotend is None:
        target_hotend = h2c_native_hotend_for_material(mat, tool, w_hotend_index)
    if inactive_hotend is None:
        inactive_hotend = 1 - int(target_hotend) if int(target_hotend) in (0, 1) else None

    if current_tool == tool:
        return [
            f"; --- FC3D tool {tool} already active for material {mat} ---",
            "G90",
            "M83",
        ], tool

    # H2C M620.11 I parameter follows the previous/raw current extruder in
    # Bambu/Orca generated filament-change code.  If unknown, W/raw4 is the safe
    # initial active tool for this project/template.
    previous_tool = int(current_tool) if current_tool is not None else int(tool_map.get("W", tool))
    # 3dprintv1.24: infer the physical hotend side we are leaving.  Studio only
    # sends the low/off-style inactive S25 command when crossing physical hotend
    # sides (T0 <-> T1), not on every material/nozzle swap.  If the previous raw
    # tool cannot be mapped, fall back to W/head0 because the FC3D template starts
    # from W and this is safer than cooling the wrong side on every swap.
    previous_mat_for_hotend = None
    for _m, _t in tool_map.items():
        if int(_t) == int(previous_tool):
            previous_mat_for_hotend = str(_m)
            break
    if previous_mat_for_hotend is None:
        previous_mat_for_hotend = "W"
    current_hotend = h2c_native_hotend_for_material(previous_mat_for_hotend, previous_tool, w_hotend_index) if thermal_mode == "native" else None
    hotend_side_change = bool(
        thermal_mode == "native"
        and current_hotend is not None
        and target_hotend is not None
        and int(current_hotend) != int(target_hotend)
    )
    if hotend_side_change:
        inactive_hotend = int(current_hotend)

    # 3dprintv1.25: Bambu Studio reference uses R0 for the first real H2C
    # change, then R2 for subsequent changes.  Keep the full firmware-managed
    # M620/M628/M629/M983/G387 lifecycle intact; only change this recovery R
    # value on the first real swap.
    h2c_recovery_r = 0 if first_real_h2c_swap else 2

    prime_xy = machine_prime_xy if machine_prime_xy is not None else purge_xy
    if prime_xy is None:
        prime_xy = (95.5, 336.0)

    px, py = float(prime_xy[0]), float(prime_xy[1])
    # Keep the old FC3D prime/wipe band dimensions for now. These are not the
    # reference template's exact model coordinates, but the command lifecycle is
    # now full and previous-tool-aware.
    y_hi = py + 7.5
    y_lo = py - 22.5

    swap = [
        f"; ===== FC3D_PPSPV43_FULL_H2C_SWAP_START material={mat} tool={tool} previous_tool={previous_tool} first_use={str(bool(first_use_machine_prime)).lower()} current_hotend={current_hotend} target_hotend={target_hotend} side_change={int(hotend_side_change)} first_real_h2c_swap={int(bool(first_real_h2c_swap))} recovery_r={int(h2c_recovery_r)} =====",
        "M400",
        "G90",
        "M83",
        "G1 E-1.2 F1800 ; FC3D_PPSPV43_PRE_SWAP_PRESSURE_RELIEF",
        f"; V4_ZHOP_START +{HOP_Z_MM:.2f} PRE_HEAD_SWAP",
        f"G1 Z{safe_z:.3f} F{H2C_TOOLCHANGE_PRE_LIFT_FEED_MM_MIN:.0f} ; FC3D_PPSPV43_PRE_HEAD_SWAP_LIFT",
        "; V4_ZHOP_END PRE_HEAD_SWAP",
        "M993 A2 B2 C2 ; FC3D_PPSPV43 nozzle cam detection allow status save",
        "M993 A0 B0 C0 ; FC3D_PPSPV43 nozzle cam detection not allowed",
        "M1015.4 S1 K0 ; FC3D_PPSPV43 disable E air printing detect",
        f"M620 S{tool}A H-1",
        "M1002 gcode_claim_action : 4",
        "M204 S9000",
        f"G1 Z{safe_z:.3f} F1200",
        "M400",
        "M106 P1 S0",
        "M106 P2 S0",
        # 3dprintv1.24: Bambu Studio reference-aligned H2C thermal planning.
        # Keep target-head preconditioning, use the Studio-like M620.15 P planner
        # temperature, and only emit inactive S25 when crossing physical hotend
        # sides (T0 <-> T1).  Do not enforce S50: the observed ~50 C inactive
        # temperature is passive coast-down/rest behaviour, not a target.
        *( [f"M632 S{tool} M N ; FC3D_PPSPV69_NATIVE_THERMAL_GUARD_BEGIN_TARGET_PRECONDITION"] if thermal_mode == "native" and planner_guards and target_hotend is not None else [] ),
        *( ["M400"] if thermal_mode == "native" and planner_guards and target_hotend is not None else [] ),
        *( [f"M104 T{int(target_hotend)} S{int(precondition_temp)} N0 ; FC3D_PPSPV69_NATIVE_TARGET_HOTEND_PRECONDITION"] if thermal_mode == "native" and target_hotend is not None else [] ),
        *( ["M633 ; FC3D_PPSPV69_NATIVE_THERMAL_GUARD_END_TARGET_PRECONDITION"] if thermal_mode == "native" and planner_guards and target_hotend is not None else [] ),
        *( [f"M104 T{int(inactive_hotend)} S{int(cool_temp)} N0 ; FC3D_V1_24_NATIVE_SIDE_CHANGE_INACTIVE_PRECOOL old_hotend={int(current_hotend)} new_hotend={int(target_hotend)}"] if thermal_mode == "native" and hotend_side_change and inactive_hotend is not None else [] ),
        f"M620.14 X{px:.3f} Y{py:.3f} ; FC3D_PPSPV43 machine prime location",
        f"M620.10 A0 F239.471 L0 H0.4 T270 P{int(print_temp)} S1",
        f"M620.10 A1 F239.471 L0 H0.4 T270 P{int(print_temp)} S1",
        f"M620.11 P1 I{previous_tool} B-1 E-14 F299.339",
        f"M620.15 P{int(standby_temp)} ; FC3D_PPSPV69_H2C_STANDBY_TEMP",
        f"M620.15 C{int(print_temp)-int(tower_cooling_delta_c)}",
        "M620.11 O1 T18",
        f"M620.11 K1 I{previous_tool} B-1 R10 F299.339",
        f"M620.15 C{int(print_temp)-int(tower_cooling_delta_c)}",
        "M628 S1",
        f"M620.11 S1 L0 I{previous_tool} B-1 R10 D8 E-14 F299.339",
        "M629",
        "M620.11 H0",
        f"T{tool} H-1",
        "M400",
        *( [f"; FC3D_V1_24_NATIVE_NO_POST_SWAP_INACTIVE_TEMP_SET inactive_hotend={int(inactive_hotend)} side_change={int(hotend_side_change)} staged_cool_temp={int(cool_temp)}"] if thermal_mode == "native" and inactive_hotend is not None else [] ),
        *( [f"M104 T{int(cool_hotend)} S{int(cool_temp)} N0 ; FC3D_PPSPV43_TEMPLATE_MATCHED_INACTIVE_COOLING"] if thermal_mode == "template" and cool_hotend is not None else [] ),
        *( [f"M104 T{1-int(cool_hotend)} S{int(print_temp)} N0 ; FC3D_PPSPV43_ACTIVE_HOTEND_PRINT_TEMP"] if thermal_mode == "template" and cool_hotend is not None and int(cool_hotend) in (0,1) else [] ),
        f"M1002 set_filament_type:{str(filament_type).upper()}",
        "M400",
        "M83",
        f"M620.10 R{int(h2c_recovery_r)} ; FC3D_V1_25_H2C_RECOVERY_R",
        "M628 S0",
        ";VM109 S255",
        "M629",
        "M400",
        *( [f"SYNC T{int(target_hotend)} ; FC3D_PPSPV69_REFERENCE_STYLE_THERMAL_SYNC", "; compensate for heating and cooling"] if thermal_mode == "native" and target_hotend is not None else [] ),
        f"M983.3 F5 A0.4 R{int(h2c_recovery_r)} ; FC3D_V1_25_H2C_RECOVERY_R",
        "M400",
        f"G387 Y{y_hi:.3f} J1 F30000",
        f"G387 Y{y_lo:.3f} J1 F18000",
        f"G1 Z{safe_z:.3f} F3000",
        "M204 S8000",
        f"M621 S{tool}A",
        "M622.1 S0 ;for prev version, default skip",
        "M1002 judge_flag powerloss_resume_flag",
        "M622 J1",
        f"M983.3 F5 A0.4 R{int(h2c_recovery_r)} ; FC3D_V1_25_H2C_RECOVERY_R",
        "M400",
        f"G387 Y{y_hi:.3f} J1 F30000",
        f"G387 Y{y_lo:.3f} J1 F18000",
        f"G1 Z{safe_z:.3f}",
        "M204 S8000",
        "M1002 set_flag powerloss_resume_flag=0",
        "M623",
        "M993 A3 B3 C3 ; nozzle cam detection allow status restore",
        "M1015.3 S0 ; disable tpu clog detect",
        "M1015.4 S1 K1 H0.4 ; enable E air printing detect",
        *( [f"M104 T{int(target_hotend)} S{int(print_temp)} N0 ; FC3D_V1_24_NATIVE_ACTIVE_HOTEND_PRINT_TEMP_REASSERT"] if thermal_mode == "native" and target_hotend is not None else [f"M104 S{int(print_temp)} ; FC3D_PPSPV43_REASSERT_ACTIVE_PRINT_TEMP"] ),
        *( [f";VM109 S{int(print_temp)} ; FC3D_V1_24_NATIVE_NO_GLOBAL_M109_KEEP_INACTIVE_COOL"] if thermal_mode == "native" else [f"M109 S{int(print_temp)} ; FC3D_PPSPV43_WAIT_FOR_ACTIVE_PRINT_TEMP_BEFORE_TOWER"] ),
        "G92 E0",
        "M83",
        "G90",
        f"; ===== FC3D_PPSPV43_FULL_H2C_SWAP_END material={mat} tool={tool} previous_tool={previous_tool} =====",
    ]
    return swap, tool


def extract_template_purge_xy(lines: Sequence[str]) -> Tuple[float, float]:
    """Extract machine purge/trash location from the template.

    Bambu/H2C templates declare the purge/waste location with M620.14.
    The current canonical template resolves this to X95.5 Y336.  We prefer the
    template value so future template changes carry through automatically.
    """
    found: List[Tuple[float, float]] = []
    for parsed in parse_gcode_lines(lines, strict=True):
        if parsed.command != "M620.14":
            continue
        found.append((parsed.require_numeric("X"), parsed.require_numeric("Y")))
    if len(found) != 1:
        raise RuntimeError(f"Expected exactly one parsed M620.14 X/Y template location; found {len(found)}")
    return found[0]


def remap_reference_gcode_tool_ids(
    lines: Sequence[str],
    reference_tool_map: Dict[str, int],
    runtime_tool_map: Dict[str, int],
    *,
    audit_name: str,
) -> Tuple[List[str], Dict[str, object]]:
    """Parser-based compatibility translator for all classified filament fields.

    Normal v1.57 generation renders typed embedded labels before this function.
    It uses this translator read-only to audit the short retained fragments and,
    under --audit, the complete final stream. It also remains available for
    differential checks against an explicitly supplied canonical reference.
    """
    reference_raw_to_material = {int(raw): str(mat) for mat, raw in reference_tool_map.items()}
    missing_runtime = sorted(mat for mat in reference_tool_map if mat not in runtime_tool_map)
    if missing_runtime:
        raise RuntimeError(
            f"{audit_name}: runtime tool map cannot translate reference materials: {missing_runtime}"
        )

    sentinel_ids = {-1, 255, 1000, 1001, 65535, 65279}
    family_counts = {
        "M620_SA": 0,
        "bare_T": 0,
        "M621_SA": 0,
        "M620.11_I": 0,
        "M620.6_I": 0,
        "M640.8_A": 0,
        "G383.3_L": 0,
        "G383_L": 0,
    }
    material_counts: Dict[str, int] = {}
    changed = 0
    identity = 0
    sentinels = 0
    unknown: List[Dict[str, object]] = []
    heater_target_lines = 0

    def translate(raw_value: int, family: str, line_number: int, original_line: str) -> int:
        nonlocal changed, identity, sentinels
        family_counts[family] += 1
        if raw_value in sentinel_ids:
            sentinels += 1
            return raw_value
        mat = reference_raw_to_material.get(int(raw_value))
        if mat is None:
            unknown.append({
                "line": int(line_number),
                "family": family,
                "raw_tool": int(raw_value),
                "gcode": original_line.strip(),
            })
            return raw_value
        mapped = int(runtime_tool_map[mat])
        material_counts[mat] = int(material_counts.get(mat, 0)) + 1
        if mapped == int(raw_value):
            identity += 1
        else:
            changed += 1
        return mapped

    field_registry: Dict[str, Tuple[str, str]] = {
        "M620": ("S", "M620_SA"),
        "M621": ("S", "M621_SA"),
        "M620.11": ("I", "M620.11_I"),
        "M620.6": ("I", "M620.6_I"),
        "M640.8": ("A", "M640.8_A"),
        "G383.3": ("L", "G383.3_L"),
        "G383": ("L", "G383_L"),
        "T": ("@TOOL", "bare_T"),
    }
    out: List[str] = []
    for parsed in parse_gcode_lines(lines, strict=True):
        if parsed.command in ("M104", "M109"):
            heater_target_lines += 1
        registered = field_registry.get(str(parsed.command))
        if registered is None:
            out.append(parsed.original)
            continue
        field, family = registered
        optional = parsed.optional_word(field)
        if optional is None:
            # M620 also has flag/configuration forms without a numeric S field.
            out.append(parsed.original)
            continue
        idx, word = optional
        if word.numeric is None:
            raise RuntimeError(
                f"{audit_name}: line {parsed.line_number} {parsed.command} {field} is not a resolved integer"
            )
        raw_float = float(word.numeric)
        if abs(raw_float - round(raw_float)) > 1e-9:
            raise RuntimeError(
                f"{audit_name}: line {parsed.line_number} {parsed.command} {field}{raw_float} is not an integer filament ID"
            )
        mapped = translate(int(round(raw_float)), family, parsed.line_number, parsed.original)
        out.append(parsed.render_word_values({idx: str(mapped)}))

    audit: Dict[str, object] = {
        "audit_name": audit_name,
        "line_count": int(len(lines)),
        "raw_tool_fields": int(sum(family_counts.values())),
        "changed_fields": int(changed),
        "identity_fields": int(identity),
        "sentinel_fields": int(sentinels),
        "family_counts": dict(family_counts),
        "material_counts": dict(sorted(material_counts.items())),
        "heater_target_lines_untouched": int(heater_target_lines),
        "unknown_raw_tool_fields": unknown,
    }
    if unknown:
        sample = "; ".join(
            f"line {v['line']} {v['family']} raw={v['raw_tool']} {v['gcode']}" for v in unknown[:8]
        )
        raise RuntimeError(
            f"{audit_name}: found {len(unknown)} raw-tool fields not covered by the reference material map; {sample}"
        )
    return out, audit


def audit_remapped_reference_startup(
    lines: Sequence[str],
    runtime_tool_map: Dict[str, int],
) -> Dict[str, object]:
    """Parser-state proof for all 13 startup filament fields and W extrusion."""
    w_raw = int(runtime_tool_map["W"])
    sentinel_ids = {-1, 255, 1000, 1001, 65535, 65279}
    active_raw: Optional[int] = None
    selector_events: List[Dict[str, object]] = []
    lifecycle_fields: List[Dict[str, object]] = []
    extrusion_events: List[Dict[str, object]] = []
    failures: List[str] = []

    field_registry: Dict[str, Tuple[str, str, int, bool]] = {
        "M620": ("S", "M620_SA", w_raw, True),
        "M621": ("S", "M621_SA", w_raw, True),
        "T": ("@TOOL", "bare_T", w_raw, True),
        "M620.11": ("I", "M620.11_I", w_raw, False),
        "M620.6": ("I", "M620.6_I", w_raw, False),
        "G383.3": ("L", "G383.3_L", w_raw, False),
        "G383": ("L", "G383_L", w_raw, False),
        "M640.8": ("A", "M640.8_A", w_raw, False),
    }
    associated_fields: List[Dict[str, object]] = []

    for parsed in parse_gcode_lines(lines, strict=True):
        command = str(parsed.command or "")
        raw_value: Optional[int] = None
        family: Optional[str] = None
        expected_raw: Optional[int] = None
        changes_active = False
        registered = field_registry.get(command)
        if registered is not None:
            field, family, expected_raw, changes_active = registered
            optional = parsed.optional_word(field)
            if optional is not None:
                _idx, word = optional
                if word.numeric is None or abs(float(word.numeric) - round(float(word.numeric))) > 1e-9:
                    failures.append(f"line {parsed.line_number} {command} {field} is not an integer")
                else:
                    raw_value = int(round(float(word.numeric)))

        if raw_value is not None and raw_value not in sentinel_ids:
            event = {
                "line": int(parsed.line_number), "family": str(family),
                "raw_tool": int(raw_value), "expected_raw_tool": int(expected_raw),
                "gcode": parsed.original.strip(),
            }
            associated_fields.append(dict(event))
            if changes_active:
                selector_events.append(dict(event))
            else:
                lifecycle_fields.append(dict(event))
            if raw_value != expected_raw:
                failures.append(
                    f"line {parsed.line_number} {family} identifies raw {raw_value}, expected {expected_raw}"
                )
            if family in ("bare_T", "M621_SA"):
                active_raw = int(raw_value)

        if command in ("G0", "G1", "G2", "G3"):
            e_word = parsed.optional_word("E")
            if e_word is not None and e_word[1].numeric is not None and float(e_word[1].numeric) > 0.0:
                extrusion_events.append({
                    "line": int(parsed.line_number), "active_raw_tool": active_raw,
                    "e": float(e_word[1].numeric), "gcode": parsed.original.strip(),
                })
                if active_raw != w_raw:
                    failures.append(
                        f"line {parsed.line_number} extrudes with active raw {active_raw}, expected startup W raw {w_raw}"
                    )

    family_counts: Dict[str, int] = {}
    for event in selector_events:
        key = str(event["family"])
        family_counts[key] = int(family_counts.get(key, 0)) + 1
    expected_selector_counts = {"M620_SA": 2, "bare_T": 2, "M621_SA": 2}
    if family_counts != expected_selector_counts:
        failures.append(
            f"startup selector topology changed: found {family_counts}, expected {expected_selector_counts}"
        )
    if not extrusion_events:
        failures.append("startup contains no positive-extrusion move to validate")
    if active_raw != w_raw:
        failures.append(f"startup handoff raw is {active_raw}, expected W raw {w_raw}")
    expected_all_counts = {
        "M620_SA": 2,
        "bare_T": 2,
        "M621_SA": 2,
        "M620.11_I": 3,
        "G383.3_L": 1,
        "G383_L": 1,
        "M620.6_I": 1,
        "M640.8_A": 1,
    }
    actual_all_counts: Dict[str, int] = {}
    for event in associated_fields:
        fam = str(event["family"])
        actual_all_counts[fam] = int(actual_all_counts.get(fam, 0)) + 1
    if actual_all_counts != expected_all_counts:
        failures.append(f"all startup filament-field topology changed: found {actual_all_counts}, expected {expected_all_counts}")
    if failures:
        raise RuntimeError("Reference startup semantic audit failed: " + "; ".join(failures))

    return {
        "line_count": int(len(lines)),
        "expected_material": "W",
        "expected_raw_tool": int(w_raw),
        "selector_event_count": int(len(selector_events)),
        "selector_family_counts": family_counts,
        "selector_events": selector_events,
        "lifecycle_field_count": int(len(lifecycle_fields)),
        "lifecycle_fields": lifecycle_fields,
        "all_filament_field_count": int(len(associated_fields)),
        "all_filament_field_counts": actual_all_counts,
        "all_filament_fields": associated_fields,
        "positive_extrusion_event_count": int(len(extrusion_events)),
        "positive_extrusion_events": extrusion_events,
        "final_active_raw_tool": int(active_raw),
        "result": "PASS",
    }


def extract_template_active_raw_tool(lines: Sequence[str]) -> Optional[int]:
    """Return the raw filament tool left active by the retained G-code prefix.

    M621 and bare T commands change filament selection. Heater targets such as
    M104 T0 are deliberately ignored. The last valid activation is the real
    handoff state and must not be replaced by an assumed default W tool.
    """
    active: Optional[int] = None
    for parsed in parse_gcode_lines(lines, strict=True):
        field: Optional[str] = None
        if parsed.command == "M621":
            field = "S"
        elif parsed.command == "T":
            field = "@TOOL"
        if field is None:
            continue
        optional = parsed.optional_word(field)
        if optional is None or optional[1].numeric is None:
            continue
        numeric = float(optional[1].numeric)
        if abs(numeric - round(numeric)) > 1e-9:
            raise RuntimeError(f"Non-integer active-tool field at line {parsed.line_number}: {parsed.original.strip()}")
        candidate = int(round(numeric))
        if candidate >= 0 and candidate not in _INVALID_H2C_TOOL_IDS:
            active = candidate
    return active

def extract_template_tool_cool_map(lines: Sequence[str]) -> Dict[int, int]:
    """Extract raw-tool -> hotend index used by reference M104 Tn S25 pre-cooling.

    The reference emits patterns like:
        T16 H-1
        M400
        M104 T1 S25 N0 ;Multi extruder pre cooling
    and:
        T4 H-1
        M400
        M104 T0 S25 N0 ;Multi extruder pre cooling

    This is safer than inventing a parity rule because the visible raw tool ID
    does not obviously encode the physical hotend index for every filament.
    """
    out: Dict[int, int] = {}
    parsed_lines = parse_gcode_lines(lines, strict=True)
    for i, parsed in enumerate(parsed_lines):
        if parsed.command != "T":
            continue
        tool_word = parsed.optional_word("@TOOL")
        hotend_word = parsed.optional_word("H")
        if tool_word is None or hotend_word is None or tool_word[1].numeric is None or hotend_word[1].numeric is None:
            continue
        if int(round(float(hotend_word[1].numeric))) != -1:
            continue
        raw_tool = int(round(float(tool_word[1].numeric)))
        for later in parsed_lines[i + 1:min(len(parsed_lines), i + 16)]:
            if later.command != "M104":
                continue
            t_word = later.optional_word("T")
            s_word = later.optional_word("S")
            if t_word is None or s_word is None or t_word[1].numeric is None or s_word[1].numeric is None:
                continue
            if abs(float(s_word[1].numeric) - 25.0) <= 1e-9:
                hotend = int(round(float(t_word[1].numeric)))
                if hotend not in (0, 1):
                    raise RuntimeError(f"Unexpected cooling hotend T{hotend} at line {later.line_number}")
                out[raw_tool] = hotend
                break
    return out


def h2c_native_hotend_for_material(mat: str, raw_tool: int, w_hotend_index: int = 0) -> int:
    """Return the physical H2C hotend index for FC3D's current material map.

    This is PPSP-native H2C behaviour rather than an extracted template rule:
      3dprintv1.28 physical-printer correction:
      W is assigned to the left hotend but Bambu M104 temperature target is T1.
      FC3D F(clear) and colour materials are assigned to the right hotend but Bambu M104 temperature target is T0.

    The raw_tool argument is retained for diagnostics/future expansion, but the
    current FC3D material model is intentionally material-driven.
    """
    w_hotend_index = 1 if int(w_hotend_index) == 1 else 0
    return w_hotend_index if str(mat).upper() == "W" else 1 - w_hotend_index


def append_extra_nozzle_clean(g: List[str], mat: str, tool: int, repeats: int = 2, command: str = "G150.1 F18000") -> None:
    """Append extra physical nozzle wipe/scrub commands without adding purge.

    This is intentionally NOT a flush/purge routine. It only repeats Bambu
    reference-template wipe primitives that are already present in the canonical
    eSUN/H2C template G-code:

      - G150.3 F18000  : move/prepare the nozzle wipe position
      - G150.1 F18000  : perform a nozzle/mouth wipe pass

    The older experimental clean-wipe build used ``G150 T255`` because that
    appears in the start-code resolved from nozzle temperature. That command is
    valid in the template, but it is a temperature-parameterised start wipe and
    is not the clearest reusable mid-print wipe primitive. This ref-wipe version
    therefore uses the explicit G150.1/G150.3 wipe commands validated from the
    reference G-code and adds no E moves / no extra purge volume.
    """
    repeats = max(0, int(repeats))
    if repeats <= 0:
        return
    wipe_cmd = str(command).strip() or "G150.1 F18000"
    g += [
        f"; FC3D_EXTRA_NOZZLE_CLEAN_START material={mat} tool={tool} repeats={repeats} primitive={wipe_cmd}",
        "; FC3D_EXTRA_NOZZLE_CLEAN_VALIDATED_IN_REFERENCE: G150.3 F18000 and G150.1 F18000",
        "M400",
        "G90",
        "M83",
        "G150.3 F18000 ; reference wipe position / prepare",
        "M400",
    ]
    for i in range(repeats):
        g += [
            f"; FC3D_EXTRA_NOZZLE_CLEAN_PASS {i+1}/{repeats}",
            wipe_cmd + " ; reference nozzle/mouth wipe pass",
            "M400",
        ]
    g += [
        "G150.3 F18000 ; reference wipe finish / safe wipe position",
        "M400",
        "G90",
        "M83",
        "; FC3D_EXTRA_NOZZLE_CLEAN_END",
    ]



def append_tower_travel_to(g, x, y, z, current_xy, span_index, tower_bbox):
    """Move into/within tower without extrusion with physical tower clearance.

    PPSPV53 rule:
    - Any non-print XY travel into or within the prime tower is treated as a
      tower-clearance move, not an ordinary model travel.
    - The head lifts vertically first, moves XY only at z + HOP_Z_MM, then
      lowers vertically at the destination before tower extrusion resumes.
    - The lift/lower are intentionally pure Z moves here.  The prior Studio
      layer-view problem came from huge numbers of model-area Z-only/XYZ restore
      moves; a small number of tower-local vertical moves is acceptable and is
      physically safer than an XY+Z downramp through the fresh tower top.

    This directly targets the observed H2C damage mode: the fresh prime tower is
    shredded 4-8 mm inside the right edge when the head leaves or repositions
    at/near tower-top height.
    """
    reason = "MANDATORY_TOWER_ENTRY" if (tower_bbox is not None and not point_in_tower(current_xy, tower_bbox)) else "TOWER_TRAVEL"
    x = float(x); y = float(y); z = float(z)
    zhop = z + max(HOP_Z_MM, TOWER_HOP_Z_MM)
    g.append("M204 S10000")
    g.append(f"; FC3D_PPSPV62_TOWER_VERTICAL_CLEARANCE_TRAVEL reason={reason} clearance={max(HOP_Z_MM, TOWER_HOP_Z_MM):.3f}")

    # Unknown start XY: lift first, position at lifted Z, then lower vertically.
    if current_xy is None:
        g.append(f"G1 Z{zhop:.3f} F60000 ; PPSPV53 lift before tower positioning")
        g.append(f"G1 X{x:.3f} Y{y:.3f} Z{zhop:.3f} F60000 ; PPSPV53 tower XY at lifted Z")
        g.append(f"G1 Z{z:.3f} F6000 ; PPSPV53 vertical lower at tower start")
        return (x, y), True

    x0, y0 = float(current_xy[0]), float(current_xy[1])
    if math.hypot(x - x0, y - y0) <= 0.02:
        # No XY motion needed.  Do not emit a low XY/XYZ restore; the caller is
        # already positioned at the tower start.
        return (x, y), False

    # True tower-clearance move: vertical lift, lifted XY, vertical lower.
    # Do not use the generic Studio-safe X/Y/Z restore here, because the tower
    # fresh-height audit correctly treats XY+Z lowering inside the tower as a
    # possible scrape/downramp.
    g.append(f"G1 Z{zhop:.3f} F60000 ; PPSPV53 lift before tower XY")
    g.append(f"G1 X{x:.3f} Y{y:.3f} Z{zhop:.3f} F60000 ; PPSPV53 tower XY at lifted Z")
    g.append(f"G1 Z{z:.3f} F6000 ; PPSPV53 vertical lower at tower destination")
    return (x, y), True


def append_tower_continuous_polyline(g, points, z, h, current_xy, span_index, tower_bbox,
                                     line_w=TOWER_LINE_W, feeds=None, e_multiplier: float = 1.0,
                                     prime_start: bool = True, retract_end: bool = False):
    """Emit connected tower geometry with one optional prime and optional final retract.

    Unlike append_segment(), this deliberately does not retract after every road.
    Studio's tower keeps pressure alive through tower/empty-grid lines, then
    does one final wipe/retract before model travel.
    """
    if not points or len(points) < 2:
        return current_xy, 0
    if feeds is None:
        feeds = [NORMAL_LAYER_FEED] * (len(points) - 1)
    else:
        feeds = list(feeds)
    if len(feeds) < len(points) - 1:
        feeds += [feeds[-1] if feeds else NORMAL_LAYER_FEED] * (len(points) - 1 - len(feeds))

    x0, y0 = points[0]
    current_xy, did_hop = append_tower_travel_to(g, x0, y0, z, current_xy, span_index, tower_bbox)
    if prime_start:
        g.append("G1 E0.4 F1800")
    g.append(f"M204 S{print_acceleration_for_layer_height(h)}")

    hop_count = int(did_hop)
    last_feed = None
    for i in range(1, len(points)):
        xa, ya = points[i-1]
        xb, yb = points[i]
        length = math.hypot(xb - xa, yb - ya)
        if length <= 0.02:
            continue
        feed = int(feeds[i-1])
        if feed != last_feed:
            g.append(f"G1 F{feed}")
            last_feed = feed
        line_e = e_for_len(length, h, line_w) * float(e_multiplier)
        g.append(f"G1 X{xb:.3f} Y{yb:.3f} E{line_e:.5f}")
        if span_index is not None:
            span_index.add_segment(xa, ya, xb, yb, z, line_w)
        current_xy = (xb, yb)

    if retract_end:
        g.append("G1 E-0.4 F1800")
    return current_xy, hop_count


def append_tower(g, mat, active, z, h, current_xy, span_index: Optional[SpanCollisionIndex], tower_bbox, layer_orientation: Optional[str] = None, first_use: bool = False, tower_slot_index: Optional[int] = None, tower_slot_count: Optional[int] = None, tower_slot_role: str = "prime", tower_road_count: Optional[int] = None, tower_slot_material: Optional[str] = None):
    active_input = list(active)
    active=[m for m in MATERIAL_ORDER if m in active_input]
    if mat not in active_input:
        return current_xy

    tx0,ty0,tx1,ty1 = tower_bbox
    if tower_slot_index is not None:
        n = max(1, int(tower_slot_count or len(active_input) or 1))
        idx = max(0, min(n - 1, int(tower_slot_index)))
    else:
        if mat not in active:
            return current_xy
        idx=active.index(mat); n=len(active)

    # PPV64: Studio-style tower direction only.
    # No alternating tower print direction.  Studio prints prime-tower pressure
    # and continuation as long X strokes with Y stepping, so pp does the same.
    tower_e_mult = TOWER_OPTICAL_E_MULT if h <= MIX_H_MM + 1e-6 else 1.0
    prime_feeds = [1782, 2025, 2473, 4725, 4775, 4775] if h <= MIX_H_MM + 1e-6 else [FIRST_LAYER_FEED] * 5
    if tower_road_count is not None:
        requested = int(tower_road_count)
        if requested < 1 or requested > len(prime_feeds):
            raise RuntimeError(
                f"tower_road_count must be in 1..{len(prime_feeds)}, got {requested}"
            )
        if requested != len(prime_feeds):
            # Preserve the beginning/stabilisation/end character of the proven
            # six-road feed ramp while fitting paired normal/filter sub-bands.
            pick = np.linspace(0, len(prime_feeds) - 1, requested).round().astype(int)
            prime_feeds = [prime_feeds[int(i)] for i in pick]

    band_h = (ty1 - ty0) / max(1, n)
    band_y0 = ty0 + idx * band_h
    band_y1 = ty0 + (idx + 1) * band_h
    x_left = tx0
    x_right = tx1

    pack_h = (len(prime_feeds) - 1) * TOWER_ROAD_SPACING
    y_start = (band_y0 + band_y1) / 2.0 + pack_h / 2.0

    g += [
        f"; WIPE_TOWER_START DIRECT_SOLID_V4 {mat}",
        f"; PRIME_TOWER_PPV64_CONTINUOUS_STUDIO_X material={mat} band={idx+1}/{n} role={tower_slot_role}",
        "; FEATURE: DIRECT_SOLID_PRIME_TOWER_V57",
        f"; FC3D_TOWER_SLOT material={mat} canonical_slot={tower_slot_material or mat} slot={idx+1}/{n} role={tower_slot_role}",
        f"; LINE_WIDTH: {TOWER_LINE_W:.3f}",
        f"; LAYER_HEIGHT: {h:.3f}",
        "; TOWER_DIRECTION: X_LONG_LINES_STUDIO_STYLE",
        f"; TOWER_E_MULT: {tower_e_mult:.3f}",
        f"; TOWER_LINE_FEEDS: {','.join(str(v) for v in prime_feeds)}",
    ]

    # Base layer: true solid 0.20 mm white tower foundation.
    # This is structural support, not purge behaviour.  Use the same base-layer
    # volumetric math as model roads: ROAD_W_MM line width, BASE_H_MM layer
    # height, FIRST_LAYER_FEED, and ROAD_W_MM spacing.  Optical tower layers
    # keep the wider purge-road spacing below.
    if h >= BASE_H_MM - 1e-6 and mat == "W" and n == 1:
        g.append("; FC3D_PPV64_SOLID_WHITE_TOWER_BASE_START")
        pts = []
        feeds = []
        y = ty0 + ROAD_W_MM / 2.0
        row = 0
        while y <= ty1 - ROAD_W_MM / 2.0 + 1e-9:
            xa, xb = (tx0, tx1) if row % 2 == 0 else (tx1, tx0)
            if not pts:
                pts.append((xa, y))
            else:
                pts.append((xa, y)); feeds.append(FIRST_LAYER_FEED)
            pts.append((xb, y)); feeds.append(FIRST_LAYER_FEED)
            y += ROAD_W_MM
            row += 1
        current_xy,_ = append_tower_continuous_polyline(
            g, pts, z, BASE_H_MM, current_xy, span_index, tower_bbox,
            line_w=ROAD_W_MM, feeds=feeds, e_multiplier=1.0,
            prime_start=True, retract_end=True
        )
        g.append("; FC3D_PPV64_SOLID_WHITE_TOWER_BASE_END")
        g.append("; WIPE_TOWER_END DIRECT_SOLID_V4")
        return current_xy

    # PPSPV69: disable the old first-use extra tower charge.
    #
    # The ppspv62 exact-segment audit reduced the file to 10 remaining fails, all
    # tower-only extrusion_current_layer_colinear_overlap events on physical layer 1.
    # The cause was this first-use charge printing full tower rows at the same Y as
    # the normal seed/main tower rows that immediately followed.  That is not a
    # travel collision, but it is a real same-layer reprint/overlap under the exact
    # segment model.  We therefore skip the duplicate charge and let the normal
    # seed + Studio-style tower road pack do the priming.
    if first_use:
        g.append("; FC3D_PPSPV69_FIRST_USE_TOWER_CHARGE_SKIPPED reason=avoid_same_layer_colinear_overlap")
        first_use = False

    # Bambu-style prime strokes: seed, small zigzag retract/deretract, then
    # long X strokes with increasing speed.  Only the intentional zigzag has a
    # retract/deretract; the road sequence itself stays continuously flowing.
    seed_y = max(band_y0 + TOWER_ROAD_SPACING/2, min(y_start, band_y1 - TOWER_ROAD_SPACING/2))
    seed_len = min(3.0, max(0.5, (x_right - x_left) * 0.08))
    # PPSPV52: start seed/prime on the left/safe side.  The observed tower
    # damage is 4-8 mm inside the right edge, probably from low post-tower
    # movement or inactive-head footprint sweep.  Starting and later finishing
    # non-print tower motions on the left avoids lowering/travelling through
    # that right-edge band after a fresh tower top has been printed.
    seed_x0 = x_left
    seed_x1 = x_left + seed_len
    # v1.164: the old short seed was an actual positive-E tower road at seed_y.
    # With six primary roads at 0.800-mm pitch in a 4.800-mm slot, that made
    # seven distinct requested Y centrelines compete for only six legal positions;
    # the clamping logic consequently placed the final two full-width roads on
    # the same centreline.  The main roads now perform all required priming, so
    # retain only safe/dry positioning to the former seed endpoint for prewipe
    # geometry and do not occupy a seventh tower centreline.
    current_xy, _ = append_tower_travel_to(
        g, seed_x1, seed_y, z, current_xy, span_index, tower_bbox
    )
    g.append("; FC3D_V162_TOWER_SEED_DRY_ONLY reason=six_unique_0.800mm_primary_centrelines")

    g += [
        "; FC3D_PPSPV47_TOWER_PREWIPE_ZIGZAG_START_SAFE_LIFTED",
        "G1 E-0.4000 F1800",
        f"G1 Z{z+max(HOP_Z_MM, TOWER_HOP_Z_MM):.3f} F60000 ; PPSPV62 lift before tower prewipe",
    ]
    zz1 = (max(x_left, seed_x1-2.0), seed_y)
    zz2 = (seed_x1, max(band_y0, seed_y-0.35))
    zz3 = (max(x_left, seed_x1-2.0), max(band_y0, seed_y-0.70))
    # PPSPV46: keep all tower pre-wipe XY safely above the freshly printed tower.
    g.append(f"G1 X{zz1[0]:.3f} Y{zz1[1]:.3f} F600")
    g.append(f"G1 X{zz2[0]:.3f} Y{zz2[1]:.3f} F240")
    g.append(f"G1 X{zz3[0]:.3f} Y{zz3[1]:.3f} F600")
    current_xy = zz3
    g += [
        f"G1 Z{z:.3f} F6000 ; PPSPV47 lower after lifted tower prewipe",
        "; FC3D_V150_TOWER_PRESSURE_STATE state=RETRACTED reason=prewipe_complete_reprime_deferred",
        "; FC3D_PPSPV47_TOWER_PREWIPE_ZIGZAG_END_SAFE_LIFTED",
    ]

    # v1.161: isolate every primary prime-tower road with one completely
    # symmetric pressure cycle.  Every road starts from retracted with +0.400,
    # draws, then ends with -0.400.  This includes the final road.  The legacy
    # post-tower safety retract remains in the source stream deliberately; the
    # global prime-state canonicaliser clips/suppresses that repeated retract at
    # logical state 0, so there is never a physical double-retract.
    y = seed_y
    left_to_right = True
    g.append("; FC3D_V161_TOWER_PRIMARY_ROADS_ISOLATED pressure_cycle=+0.400/draw/-0.400 final_state=RETRACTED")
    for i, feed in enumerate(prime_feeds):
        # Six unique centrelines exactly fill the 4.800-mm slot at 0.800-mm pitch:
        # y1-0.4, y1-1.2, ... , y0+0.4.  Do not clamp duplicate rows.
        y = band_y1 - TOWER_ROAD_SPACING/2 - i*TOWER_ROAD_SPACING
        xa, xb = (x_left, x_right) if left_to_right else (x_right, x_left)
        current_xy,_ = append_tower_continuous_polyline(
            g, [(xa, y), (xb, y)], z, h, current_xy, span_index, tower_bbox,
            line_w=TOWER_LINE_W, feeds=[feed], e_multiplier=tower_e_mult,
            prime_start=True, retract_end=True
        )
        left_to_right = not left_to_right
    g.append("; FC3D_V150_TOWER_PRESSURE_STATE state=RETRACTED reason=main_tower_extrusion_complete")

    # PPV64: dense tower continuation/empty-grid removed.
    # The tower/prime roads are intentionally over-extruded compared with model
    # roads, so they need Studio-like spacing rather than dense infill.
    g.append("; WIPE_TOWER_END DIRECT_SOLID_V4")
    return current_xy




def _tower_scheduler_band_geometry(tower_bbox, slot_index: int, slot_count: int):
    tx0,ty0,tx1,ty1=map(float,tower_bbox); n=max(1,int(slot_count)); idx=max(0,min(n-1,int(slot_index)))
    band_h=(ty1-ty0)/n; y0=ty0+idx*band_h; y1=ty0+(idx+1)*band_h
    feeds=[1782,2025,2473,4725,4775,4775]
    pack_h=(len(feeds)-1)*TOWER_ROAD_SPACING
    seed_y=(y0+y1)/2.0+pack_h/2.0
    main=[]
    for i in range(len(feeds)):
        yy=y1-TOWER_ROAD_SPACING/2-i*TOWER_ROAD_SPACING
        main.append(yy)
    gaps=[(main[i]+main[i+1])/2.0 for i in range(len(main)-1)]
    return tx0,tx1,y0,y1,main,gaps


def append_tower_secondary_gap_roads(g, mat, z, h, current_xy, span_index, tower_bbox, slot_index: int, slot_count: int, role: str, prime: bool):
    """Print interleaved secondary tower roads without extruding inter-row connectors.

    v1.155 emitted the five secondary roads as one serpentine polyline.  Its 0.75-mm
    vertical edge connectors overlapped the already-printed primary connectors by
    0.375 mm, creating genuine same-layer centreline reprints.  v1.156 keeps the
    exact same horizontal gap-road Y positions, line width, VE and feed; each endpoint
    is inset by one tower line width to clear the primary edge connector, and each
    horizontal road is an isolated stroke.  Between roads the nozzle
    is fully retracted and append_tower_travel_to performs the normal tower-safe lift.

    If ``prime`` is true, only the final road is left primed for the following model
    operation; otherwise every road ends fully retracted.
    """
    tx0,tx1,_y0,_y1,_main,gaps=_tower_scheduler_band_geometry(tower_bbox,slot_index,slot_count)
    if not gaps:
        raise RuntimeError("secondary tower-gap geometry has no available gaps")
    # Keep the secondary bead clear of the primary serpentine's vertical edge
    # connectors.  One full nominal tower line width gives bead-edge tangency
    # (0.25 + 0.25 mm) rather than overlap for the 0.50-mm tower line width.
    edge_inset = float(TOWER_LINE_W)
    sx0 = tx0 + edge_inset
    sx1 = tx1 - edge_inset
    if sx1 - sx0 <= 2.0 * TOWER_LINE_W:
        raise RuntimeError("tower too narrow for isolated secondary gap-road edge clearance")
    feed=NORMAL_LAYER_FEED
    g += [
        f"; WIPE_TOWER_START DIRECT_SOLID_V156_SECONDARY {mat}",
        f"; FC3D_TOWER_SECONDARY_GAPS_V156 material={mat} slot={slot_index+1}/{slot_count} role={role} prime={int(prime)} connector_policy=isolated_horizontal",
        f"; FC3D_TOWER_SLOT material={mat} canonical_slot={get_runtime_material_order()[slot_index]} slot={slot_index+1}/{slot_count} role={role}",
        f"; LINE_WIDTH: {TOWER_LINE_W:.3f}", f"; LAYER_HEIGHT: {h:.3f}",
    ]
    ltr=True
    for gi,yy in enumerate(gaps):
        xa,xb=(sx0,sx1) if ltr else (sx1,sx0)
        leave_primed = bool(prime and gi == len(gaps)-1)
        current_xy,_=append_tower_continuous_polyline(
            g,[(xa,yy),(xb,yy)],z,h,current_xy,span_index,tower_bbox,
            line_w=TOWER_LINE_W,feeds=[feed],
            e_multiplier=(TOWER_OPTICAL_E_MULT if h<=MIX_H_MM+1e-6 else 1.0),
            prime_start=True,retract_end=(not leave_primed)
        )
        ltr=not ltr
    g.append("; WIPE_TOWER_END DIRECT_SOLID_V156_SECONDARY")
    return current_xy


def append_tower_primary_fill_from_retracted(g, mat, z, h, current_xy, span_index, tower_bbox, slot_index: int, slot_count: int):
    """Structurally fill an unused primary slot from a known retracted state."""
    tx0,tx1,_y0,_y1,main,_gaps=_tower_scheduler_band_geometry(tower_bbox,slot_index,slot_count)
    pts=[]; feeds=[]; ltr=True
    for yy in main:
        xa,xb=(tx0,tx1) if ltr else (tx1,tx0)
        if not pts: pts.append((xa,yy))
        else: pts.append((xa,yy)); feeds.append(NORMAL_LAYER_FEED)
        pts.append((xb,yy)); feeds.append(NORMAL_LAYER_FEED); ltr=not ltr
    g.append(f"; FC3D_TOWER_PRIMARY_STRUCTURAL_FILL material={mat} slot={slot_index+1}/{slot_count}")
    g.append(
        f"; FC3D_TOWER_SLOT material={mat} "
        f"canonical_slot={get_runtime_material_order()[slot_index]} "
        f"slot={slot_index+1}/{slot_count} role=primary"
    )
    current_xy,_=append_tower_continuous_polyline(
        g,pts,z,h,current_xy,span_index,tower_bbox,line_w=TOWER_LINE_W,feeds=feeds,
        e_multiplier=(TOWER_OPTICAL_E_MULT if h<=MIX_H_MM+1e-6 else 1.0),prime_start=True,retract_end=True
    )
    return current_xy


def complete_same_layer_scheduler_tower(g, current_material, z, h, current_xy, span_index, tower_bbox, primary_used, secondary_used):
    active=list(get_runtime_material_order()); p=set(primary_used); s=set(secondary_used)
    if current_material not in active:
        raise RuntimeError(f"cannot complete scheduler tower with inactive material {current_material!r}")
    # Model action ends retracted. Fill any unused primary slots first.
    for idx,slotmat in enumerate(active):
        if slotmat not in p:
            current_xy=append_tower_primary_fill_from_retracted(g,current_material,z,h,current_xy,span_index,tower_bbox,idx,len(active))
    # Fill every secondary gap not already consumed by a genuine re-prime.
    for idx,slotmat in enumerate(active):
        if slotmat not in s:
            current_xy=append_tower_secondary_gap_roads(g,current_material,z,h,current_xy,span_index,tower_bbox,idx,len(active),"secondary_fill",prime=False)
    g.append(f"; FC3D_TOWER_LAYER_COMPLETE_V129 primary_used={','.join(primary_used) or 'none'} secondary_used={','.join(secondary_used) or 'none'} slots={','.join(active)}")
    return current_xy

def append_tower_filler_slot(g, mat, z, h, current_xy, span_index: Optional[SpanCollisionIndex], tower_bbox,
                             tower_slot_index: int, tower_slot_count: int,
                             layer_orientation: Optional[str] = None,
                             slot_material: Optional[str] = None):
    """Fill an unused canonical tower slot with the already-active material.

    v1.69 keeps the physical W,R,Y,G,C,B slot topology even when a colour is
    absent. The slot is structural filler printed by the material already active
    from the preceding slot. It emits no selector, tool change, purge or separate
    E-prime and therefore cannot reactivate a job-excluded colour.
    """
    tx0, ty0, tx1, ty1 = tower_bbox
    n = max(1, int(tower_slot_count))
    idx = max(0, min(n - 1, int(tower_slot_index)))
    band_h = (ty1 - ty0) / n
    band_y0 = ty0 + idx * band_h
    band_y1 = ty0 + (idx + 1) * band_h
    x_left = tx0
    x_right = tx1

    tower_e_mult = TOWER_OPTICAL_E_MULT if h <= MIX_H_MM + 1e-6 else 1.0
    road_count = 6 if h <= MIX_H_MM + 1e-6 else max(1, int(math.floor((band_y1 - band_y0) / max(TOWER_ROAD_SPACING, 0.01))))
    feed = NORMAL_LAYER_FEED if h <= MIX_H_MM + 1e-6 else FIRST_LAYER_FEED
    pack_h = max(0, road_count - 1) * TOWER_ROAD_SPACING
    y_start = (band_y0 + band_y1) / 2.0 + pack_h / 2.0

    g += [
        f"; WIPE_TOWER_START DIRECT_SOLID_V4_FILLER {mat}",
        f"; PRIME_TOWER_V169_CANONICAL_FILLER material={mat} canonical_slot={slot_material or 'unknown'} slot={idx+1}/{n}",
        "; FEATURE: DIRECT_SOLID_PRIME_TOWER_V169_FILLER",
        f"; FC3D_TOWER_SLOT material={mat} canonical_slot={slot_material or 'unknown'} slot={idx+1}/{n} role=filler_previous feed={feed}",
        f"; FC3D_TOWER_FILL_NO_SWAP active_material={mat} excluded_slot_material={slot_material or 'unknown'}",
        f"; LINE_WIDTH: {TOWER_LINE_W:.3f}",
        f"; LAYER_HEIGHT: {h:.3f}",
        "; TOWER_DIRECTION: X_LONG_LINES_STUDIO_STYLE",
        f"; TOWER_E_MULT: {tower_e_mult:.3f}",
        f"; TOWER_FILLER_FEED: {feed}",
    ]

    pts = []
    feeds = []
    left_to_right = True
    for i in range(road_count):
        y = max(band_y0 + TOWER_ROAD_SPACING/2, min(y_start - i*TOWER_ROAD_SPACING, band_y1 - TOWER_ROAD_SPACING/2))
        xa, xb = (x_left, x_right) if left_to_right else (x_right, x_left)
        if not pts:
            pts.append((xa, y))
        else:
            pts.append((xa, y)); feeds.append(feed)
        pts.append((xb, y)); feeds.append(feed)
        left_to_right = not left_to_right
    current_xy,_ = append_tower_continuous_polyline(
        g, pts, z, h, current_xy, span_index, tower_bbox,
        line_w=TOWER_LINE_W, feeds=feeds, e_multiplier=tower_e_mult,
        prime_start=False, retract_end=False
    )
    g.append("; WIPE_TOWER_END DIRECT_SOLID_V4_FILLER")
    return current_xy


def audit_v150_active_tower_pressure_contract(lines: Sequence[str]) -> Dict[str, int]:
    """Fail closed on the two active-layer tower pressure bugs fixed in v1.150.

    Contract A: after the prewipe retract completes, all positioning stays
    retracted.  The +0.40 recovery must occur only after the destination is
    reached and there may be no non-extruding XY/Z motion between that recovery
    and the first positive-E XY extrusion.

    Contract B: at a toolchange tower exit, the first pressure-changing action
    after WIPE_START is the complete stationary -0.40 retract, before any Z/XY
    movement.  The following lifted wipe contains no E.
    """
    src=[str(x).strip() for x in lines]
    pre=[i for i,x in enumerate(src) if 'FC3D_V150_TOWER_PRESSURE_STATE state=RETRACTED reason=prewipe_complete_reprime_deferred' in x]
    exits=[i for i,x in enumerate(src) if x.startswith('; WIPE_START FC3D_PPSPV47_POST_TOWER_SAFE_LIFTED')]
    if not pre:
        raise RuntimeError('v1.150 tower pressure audit found no deferred-prewipe markers')

    def words(line: str):
        code=line.split(';',1)[0].strip()
        return code.split() if code else []
    def g1_fields(line: str):
        w=words(line)
        if not w or w[0] not in ('G0','G1'):
            return {}
        d={}
        for tok in w[1:]:
            if len(tok)>1 and tok[0] in 'XYZEF':
                try: d[tok[0]]=float(tok[1:])
                except Exception: pass
        return d

    deferred_ok=0
    for i in pre:
        prime_i=None
        for j in range(i+1, min(len(src), i+80)):
            f=g1_fields(src[j])
            if 'E' in f and f['E']>0 and 'X' not in f and 'Y' not in f:
                prime_i=j; break
            if 'E' in f and f['E']>0 and ('X' in f or 'Y' in f):
                raise RuntimeError(f'v1.150 tower pressure audit: extrusion began before deferred reprime at line {j+1}')
        if prime_i is None:
            raise RuntimeError(f'v1.150 tower pressure audit: no deferred reprime after prewipe marker line {i+1}')
        first_print=None
        for j in range(prime_i+1, min(len(src), prime_i+40)):
            f=g1_fields(src[j])
            if ('X' in f or 'Y' in f or 'Z' in f) and 'E' not in f:
                raise RuntimeError(f'v1.150 tower pressure audit: non-extruding travel after reprime at line {j+1}: {src[j]}')
            if 'E' in f and f['E']>0 and ('X' in f or 'Y' in f):
                first_print=j; break
        if first_print is None:
            raise RuntimeError(f'v1.150 tower pressure audit: no tower extrusion immediately after reprime line {prime_i+1}')
        deferred_ok += 1

    exit_ok=0
    exit_retract_noops=0
    for i in exits:
        first_motion=None
        end=None
        saw_canonical_noop=False
        for j in range(i+1, min(len(src), i+40)):
            if src[j].startswith('; WIPE_END FC3D_PPSPV47_POST_TOWER_SAFE_LIFTED'):
                end=j; break
            if ('FC3D_V152_RETRACT_NOOP state=0' in src[j]
                    and 'FC3D_V150 immediate retract at tower print stop' in src[j]):
                saw_canonical_noop=True
                continue
            f=g1_fields(src[j])
            if f and any(k in f for k in ('X','Y','Z','E')) and first_motion is None:
                first_motion=(j,f,src[j])
        if first_motion is None:
            raise RuntimeError(f'v1.150 tower pressure audit: empty post-tower wipe block at line {i+1}')
        j,f,text=first_motion
        physical_exit_retract = ('E' in f and abs(f['E'] + 0.4) <= 1e-6 and 'X' not in f and 'Y' not in f and 'Z' not in f)
        if physical_exit_retract:
            check_from=j+1
        elif saw_canonical_noop:
            # v1.161 normal case: the final tower road already ended with -0.400,
            # so apply_global_prime_state_contract() canonicalises the retained
            # post-tower -0.400 request to an explicit state=0 no-op comment.
            # The first executable move may therefore be the safe lifted Z move.
            if 'E' in f:
                raise RuntimeError(f'v1.161 tower pressure audit: E move followed canonical exit retract no-op at line {j+1}: {text}')
            exit_retract_noops += 1
            check_from=j
        else:
            raise RuntimeError(f'v1.150 tower pressure audit: tower exit neither retracted stationary nor proved already retracted at line {j+1}: {text}')
        if end is None:
            raise RuntimeError(f'v1.150 tower pressure audit: missing post-tower WIPE_END after line {i+1}')
        for j2 in range(check_from,end):
            f2=g1_fields(src[j2])
            if 'E' in f2:
                raise RuntimeError(f'v1.150 tower pressure audit: E move during already-retracted lifted wipe at line {j2+1}: {src[j2]}')
        exit_ok += 1

    return {
        'deferred_prewipe_reprime_blocks': deferred_ok,
        'immediate_retract_exit_blocks': exit_ok,
        'canonical_exit_retract_noops': exit_retract_noops,
    }

def _fc3d_point_rect_distance(x: float, y: float, rect) -> float:
    x0, y0, x1, y1 = map(float, rect)
    dx = max(x0 - x, 0.0, x - x1)
    dy = max(y0 - y, 0.0, y - y1)
    return math.hypot(dx, dy)


def _fc3d_point_on_segment_interior(px, py, seg, eps: float = 1e-9) -> bool:
    x0, y0, x1, y1 = seg
    cross = (x1-x0)*(py-y0) - (y1-y0)*(px-x0)
    if abs(cross) > eps:
        return False
    if px < min(x0,x1)-eps or px > max(x0,x1)+eps or py < min(y0,y1)-eps or py > max(y0,y1)+eps:
        return False
    if math.hypot(px-x0, py-y0) <= eps or math.hypot(px-x1, py-y1) <= eps:
        return False
    return True


def _fc3d_segment_reentry_kind(a, b, eps: float = 1e-9) -> Optional[str]:
    """Classify centreline re-entry that means later tower extrusion enters occupied geometry.

    Ordinary endpoint-to-endpoint joins return None.  Positive-length collinear
    overlap, proper interior crossings, and one segment ending/starting in the
    strict interior of another are all considered occupied-centreline re-entry.
    """
    ax0, ay0, ax1, ay1 = a
    bx0, by0, bx1, by1 = b
    oa0 = (ax1-ax0)*(by0-ay0) - (ay1-ay0)*(bx0-ax0)
    oa1 = (ax1-ax0)*(by1-ay0) - (ay1-ay0)*(bx1-ax0)
    ob0 = (bx1-bx0)*(ay0-by0) - (by1-by0)*(ax0-bx0)
    ob1 = (bx1-bx0)*(ay1-by0) - (by1-by0)*(ax1-bx0)
    if abs(oa0) <= eps and abs(oa1) <= eps and abs(ob0) <= eps and abs(ob1) <= eps:
        if abs(ax1-ax0) >= abs(ay1-ay0):
            overlap = min(max(ax0,ax1), max(bx0,bx1)) - max(min(ax0,ax1), min(bx0,bx1))
        else:
            overlap = min(max(ay0,ay1), max(by0,by1)) - max(min(ay0,ay1), min(by0,by1))
        if overlap > 0.02:
            return "collinear_overlap"
        return None
    if ((oa0 > eps and oa1 < -eps) or (oa0 < -eps and oa1 > eps)) and \
       ((ob0 > eps and ob1 < -eps) or (ob0 < -eps and ob1 > eps)):
        return "proper_crossing"
    for px,py in ((ax0,ay0),(ax1,ay1)):
        if _fc3d_point_on_segment_interior(px,py,b,eps):
            return "endpoint_on_existing_interior"
    for px,py in ((bx0,by0),(bx1,by1)):
        if _fc3d_point_on_segment_interior(px,py,a,eps):
            return "existing_endpoint_in_new_interior"
    return None


def _fc3d_generated_body_motion(lines: Sequence[str]):
    """Yield explicit generated-body positive-E XY segments with resolved XYZ state."""
    src=[str(x) for x in lines]
    start=0
    for i,line in enumerate(src):
        if "FC3D STACK-LUT FAST STUDIO-RASTER IMAGE GCODE" in line:
            start=i
            break
    abs_xyz=True
    rel_e=True
    x=y=z=None
    e_abs=0.0
    for lineno,line in enumerate(src[start:], start=start+1):
        code=line.split(';',1)[0].strip()
        if not code:
            continue
        parts=code.split()
        cmd=parts[0]
        if cmd == 'G90':
            abs_xyz=True; continue
        if cmd == 'G91':
            abs_xyz=False; continue
        if cmd == 'M83':
            rel_e=True; continue
        if cmd == 'M82':
            rel_e=False; continue
        vals={}
        for tok in parts[1:]:
            if len(tok)>1 and tok[0] in 'XYZE':
                try: vals[tok[0]]=float(tok[1:])
                except Exception: pass
        if cmd == 'G92':
            if 'X' in vals: x=vals['X']
            if 'Y' in vals: y=vals['Y']
            if 'Z' in vals: z=vals['Z']
            if 'E' in vals: e_abs=vals['E']
            continue
        if cmd not in ('G0','G1'):
            continue
        ox,oy,oz=x,y,z
        nx=x; ny=y; nz=z
        if 'X' in vals: nx=vals['X'] if abs_xyz or x is None else x+vals['X']
        if 'Y' in vals: ny=vals['Y'] if abs_xyz or y is None else y+vals['Y']
        if 'Z' in vals: nz=vals['Z'] if abs_xyz or z is None else z+vals['Z']
        de=0.0
        if 'E' in vals:
            if rel_e:
                de=vals['E']
            else:
                de=vals['E']-e_abs
                e_abs=vals['E']
        x,y,z=nx,ny,nz
        if de <= 0.0 or ox is None or oy is None or nx is None or ny is None:
            continue
        if math.hypot(nx-ox, ny-oy) <= 0.02:
            continue
        yield {
            'line': int(lineno), 'z': None if nz is None else float(f"{nz:.3f}"),
            'segment': (float(f"{ox:.3f}"),float(f"{oy:.3f}"),float(f"{nx:.3f}"),float(f"{ny:.3f}")),
            'e': float(de), 'gcode': line.strip(),
        }


def audit_tower_same_layer_occupancy(lines: Sequence[str], tower_bbox) -> Dict[str, object]:
    """Fail closed if explicit tower extrusion re-enters an occupied same-layer centreline.

    This is deliberately a centreline/topology audit, not a bead-footprint packing
    audit.  The intended 0.50-mm tower beads at 0.375-mm horizontal pitch may overlap
    laterally; that dense fill remains legal.  What is forbidden is explicit later
    extrusion along/crossing an already printed centreline or terminating in its
    strict interior.
    """
    tx0,ty0,tx1,ty1=map(float,tower_bbox)
    eps=1e-6
    by_z: Dict[float,List[Tuple[Tuple[float,float,float,float],int]]] = {}
    failures=[]
    counts={}
    total=0
    for ev in _fc3d_generated_body_motion(lines):
        x0,y0,x1,y1=ev['segment']
        if not (tx0-eps <= x0 <= tx1+eps and ty0-eps <= y0 <= ty1+eps and
                tx0-eps <= x1 <= tx1+eps and ty0-eps <= y1 <= ty1+eps):
            continue
        z=ev['z']
        if z is None:
            raise RuntimeError(f"tower occupancy audit: positive-E tower segment has unknown Z at line {ev['line']}")
        prior=by_z.setdefault(z,[])
        for old,old_line in prior:
            kind=_fc3d_segment_reentry_kind(ev['segment'],old)
            if kind is not None:
                failures.append({
                    'kind':kind,'z':z,'line':ev['line'],'prior_line':old_line,
                    'segment':ev['segment'],'prior_segment':old,
                })
                if len(failures)>=20:
                    break
        if failures:
            break
        prior.append((ev['segment'],ev['line']))
        counts[z]=int(counts.get(z,0))+1
        total+=1
    if failures:
        raise RuntimeError(f"tower same-layer occupancy audit failed: explicit extrusion re-enters occupied centreline; examples={failures}")
    return {
        'result':'PASS',
        'tower_segments_checked':int(total),
        'segments_by_z':{f"{k:.3f}":int(v) for k,v in sorted(counts.items())},
        'collinear_reprints':0,
        'proper_crossings':0,
        'endpoint_interior_reentries':0,
        'bead_footprint_overlap_policy':'allowed_dense_pack_not_part_of_centreline_reentry_audit',
    }


def audit_m62014_staging_clearance(lines: Sequence[str], tower_bbox, printable_bbox, card_bbox,
                                   mode: str) -> Dict[str, object]:
    """Fail closed on FC3D-generated non-template M620.14 staging inside/near tower."""
    mode=str(mode).strip().lower()
    pts=[]
    for lineno,line in enumerate(lines, start=1):
        text=str(line)
        if 'M620.14 ' not in text or 'FC3D_PPSPV43 machine prime location' not in text:
            continue
        mx=re.search(r'\bX([-+]?\d+(?:\.\d+)?)',text)
        my=re.search(r'\bY([-+]?\d+(?:\.\d+)?)',text)
        if not mx or not my:
            raise RuntimeError(f"M620.14 staging audit could not parse line {lineno}: {text}")
        pts.append((lineno,float(mx.group(1)),float(my.group(1))))
    if not pts:
        raise RuntimeError('M620.14 staging audit found no FC3D toolchange staging commands')
    if mode == 'template':
        return {'result':'PASS_TEMPLATE_UNCHANGED','mode':mode,'points':len(pts),'strict_outside_tower_check':False}
    px0,py0,px1,py1=map(float,printable_bbox)
    min_tower=float('inf'); min_card=float('inf')
    expected_x={round(float(tower_bbox[0])-M62014_TOWER_STAGE_OFFSET_MM,3), round(float(tower_bbox[2])+M62014_TOWER_STAGE_OFFSET_MM,3)}
    rows=[]
    for lineno,x,y in pts:
        td=_fc3d_point_rect_distance(x,y,tower_bbox)
        cd=_fc3d_point_rect_distance(x,y,card_bbox)
        min_tower=min(min_tower,td); min_card=min(min_card,cd)
        if not (px0 <= x <= px1 and py0 <= y <= py1):
            raise RuntimeError(f"M620.14 staging audit: line {lineno} point X{x:.3f} Y{y:.3f} outside printable area")
        if td < M62014_RESERVED_CLEARANCE_MM-1e-6:
            raise RuntimeError(f"M620.14 staging audit: line {lineno} point X{x:.3f} Y{y:.3f} only {td:.3f} mm from tower; reserved={M62014_RESERVED_CLEARANCE_MM:.3f}")
        if round(x,3) not in expected_x:
            raise RuntimeError(f"M620.14 staging audit: line {lineno} X{x:.3f} is not the required {M62014_TOWER_STAGE_OFFSET_MM:.3f}-mm outside-tower staging X")
        rows.append({'line':lineno,'x':x,'y':y,'tower_clearance_mm':td,'card_clearance_mm':cd})
    return {
        'result':'PASS','mode':mode,'points':len(rows),
        'required_outside_offset_mm':float(M62014_TOWER_STAGE_OFFSET_MM),
        'reserved_clearance_mm':float(M62014_RESERVED_CLEARANCE_MM),
        'minimum_tower_clearance_mm':float(min_tower),
        'minimum_card_clearance_mm':float(min_card),
        'rows':rows,
    }


def append_post_tower_wipe_before_model(g: List[str], current_xy, z: float, tower_bbox, layer_orientation: Optional[str], span_index: Optional[SpanCollisionIndex] = None):
    """Tower wipe/retract before leaving tower, performed safely at lifted Z.

    PPSPV46: the old post-tower wipe used ramped/low XY through the tower right
    edge with E-.38.  Keep the retract/wipe concept, but lift vertically first,
    do the XY wipe at hop Z, and leave the nozzle lifted for the next checked
    travel.
    """
    if current_xy is None or tower_bbox is None:
        return current_xy
    tx0, ty0, tx1, ty1 = tower_bbox
    x, y = current_xy
    x = max(tx0 + 1.0, min(tx1 - 1.0, float(x)))
    y = max(ty0 + 1.0, min(ty1 - 1.0, float(y)))
    g += [
        "; WIPE_START FC3D_PPSPV47_POST_TOWER_SAFE_LIFTED",
        "G1 E-0.4000 F1800 ; FC3D_V150 immediate retract at tower print stop",
        "; FC3D_V150_TOWER_PRESSURE_STATE state=RETRACTED reason=tower_print_stop",
        "G1 F48000",
        f"G1 Z{z+max(HOP_Z_MM, TOWER_HOP_Z_MM):.3f} F60000 ; PPSPV62 lift after immediate tower retract",
    ]
    if layer_orientation == "Y":
        x2 = max(tx0 + 1.0, min(tx1 - 1.0, x + (6.0 if x < (tx0 + tx1) / 2.0 else -6.0)))
        y2 = y
    else:
        x2 = x
        y2 = max(ty0 + 1.0, min(ty1 - 1.0, y + (6.0 if y < (ty0 + ty1) / 2.0 else -6.0)))
    g.append(f"G1 X{x2:.3f} Y{y2:.3f} F48000 ; FC3D_V150 lifted post-tower wipe while already retracted")
    g += [
        "; FC3D_V150_TOWER_PRESSURE_STATE state=RETRACTED reason=post_tower_wipe_complete",
        "; WIPE_END FC3D_PPSPV47_POST_TOWER_SAFE_LIFTED",
        "; FC3D_PPSPV47_TOWER_EXIT_ALREADY_LIFTED_NEXT_TRAVEL_SAFE",
    ]
    return (x2, y2)


# PPSPV47: restored global image-array cache accidentally omitted in PPSPV46.
IMAGE_ARRAY_CACHE: Dict[int, np.ndarray] = {}


def _to_uint8_rgb(arr: np.ndarray) -> np.ndarray:
    """Output-boundary conversion only: float RGB -> display PNG uint8.

    PSPV12: avoid np.clip(np.rint(full_float_preview)) because that creates
    full-size temporary float arrays.  Process rows in chunks so large preview
    PNG saves do not fail on memory-constrained Windows/Python builds.
    """
    a = np.asarray(arr)
    if a.dtype == np.uint8:
        return a
    if a.ndim < 2:
        tmp = np.rint(a).astype(np.float32, copy=False)
        tmp = np.clip(tmp, 0, 255)
        return tmp.astype(np.uint8)
    out = np.empty(a.shape, dtype=np.uint8)
    rows = int(a.shape[0])
    # Keep temporary below roughly a few MB even for RGB images.
    chunk_rows = max(1, min(128, rows))
    for y0 in range(0, rows, chunk_rows):
        y1 = min(rows, y0 + chunk_rows)
        tmp = np.rint(a[y0:y1]).astype(np.float32, copy=False)
        np.clip(tmp, 0, 255, out=tmp)
        out[y0:y1] = tmp.astype(np.uint8)
    return out



def _preview_white_expand_rgb(arr: Optional[np.ndarray], lookup: Optional["RecipeLookup"] = None, mode: Optional[str] = None) -> Optional[np.ndarray]:
    """Return a display-only 255-white preview copy, leaving print maths untouched.

    v67/v66.1 LUT matching maps source white 255,255,255 down to measured
    printable white.  Raw predicted print previews are therefore physically
    correct but look dim/warm on a normal monitor.  This helper applies only the
    inverse display transform:
        display_rgb = print_rgb * 255 / printable_white_rgb
    It must never be fed back into recipe selection, stack replay, G-code
    extrusion, scheduler scoring, or exact stack-vs-LUT diagnostics.
    """
    if arr is None:
        return None
    use_mode = str(mode if mode is not None else globals().get("RUNTIME_PREVIEW_WHITE_EXPAND", "on")).lower()
    if use_mode in ("off", "false", "0", "no", "none"):
        return np.asarray(arr, dtype=np.float32)
    try:
        model = _demand_optical_model_from_lookup(lookup)
        white = np.asarray(
            model.get("printable_white_rgb")
            or model.get("recipe_prediction_substrate_rgb")
            or model.get("w_endpoint_rgb")
            or [255.0, 255.0, 255.0],
            dtype=np.float32,
        )
        if white.shape != (3,) or not np.all(np.isfinite(white)):
            return np.asarray(arr, dtype=np.float32)
        white = np.maximum(white, 1e-6)
        # If the model is already normal display white, this is a no-op.
        out = np.asarray(arr, dtype=np.float32) * (255.0 / white.reshape((1, 1, 3)))
        return np.clip(out, 0.0, 255.0).astype(np.float32)
    except Exception:
        return np.asarray(arr, dtype=np.float32)


def _preview_white_expand_report(lookup: Optional["RecipeLookup"] = None, mode: Optional[str] = None) -> Dict[str, object]:
    use_mode = str(mode if mode is not None else globals().get("RUNTIME_PREVIEW_WHITE_EXPAND", "on")).lower()
    rec: Dict[str, object] = {
        "enabled": use_mode not in ("off", "false", "0", "no", "none"),
        "formula": "display_rgb = print_preview_rgb * 255.0 / printable_white_rgb",
        "scope": "display PNGs and 3MF metadata thumbnails only; emitted G-code and exact stack previews stay in print space",
    }
    try:
        model = _demand_optical_model_from_lookup(lookup)
        white = np.asarray(
            model.get("printable_white_rgb")
            or model.get("recipe_prediction_substrate_rgb")
            or model.get("w_endpoint_rgb")
            or [255.0, 255.0, 255.0],
            dtype=np.float64,
        )
        rec["printable_white_rgb"] = [float(x) for x in white.tolist()]
        rec["optical_model_source"] = str(model.get("source", "unknown"))
    except Exception as exc:
        rec["error"] = str(exc)
    return rec


def _img_array(img: Image.Image) -> np.ndarray:
    key = id(img)
    arr = IMAGE_ARRAY_CACHE.get(key)
    if arr is None:
        # Internal source RGB is float32.  Integer conversion should only happen
        # at output/debug PNG boundaries or direct material-symbol decoding.
        arr = np.asarray(img.convert("RGB"), dtype=np.float32)
        IMAGE_ARRAY_CACHE[key] = arr
    return arr

def _append_runs(segs, mats: Sequence[str], fixed_coord: float, origin: float, band_reverse: bool, axis: str, step_mm: float,
                 boundary_positions: Optional[Sequence[float]] = None,
                 doses: Optional[Sequence[float]] = None,
                 height_fractions: Optional[Sequence[float]] = None,
                 height_profile_indices: Optional[Sequence[int]] = None,
                 partition_ids: Optional[Sequence[int]] = None):
    """Append material+dose(+optional carrier-height) runs.

    ppv78: direct-layer alpha can assign dose_multiplier per RP cell.  Runs are
    therefore split by both material and dose so different extrusion amounts do
    not get merged into one road. v1.57 additionally splits 4x4 direct runs by
    the underlying normal-carrier height fraction. Ordinary paths omit that
    sixth segment field and remain byte-for-byte compatible at this stage.
    """
    n = len(mats)
    if doses is None:
        doses = [1.0] * n
    if len(doses) != n:
        raise ValueError(f"doses length {len(doses)} != mats length {n}")
    if height_fractions is not None and len(height_fractions) != n:
        raise ValueError(f"height_fractions length {len(height_fractions)} != mats length {n}")
    if height_profile_indices is not None and len(height_profile_indices) != n:
        raise ValueError(f"height_profile_indices length {len(height_profile_indices)} != mats length {n}")
    if boundary_positions is None:
        pos = [origin + i * step_mm for i in range(n + 1)]
    else:
        pos = list(boundary_positions)
        if len(pos) != n + 1:
            raise ValueError(f"boundary_positions length {len(pos)} != {n+1}")

    runs = []
    cur_key = None
    start_i = 0
    for i in range(n + 1):
        if i < n:
            mat = mats[i]
            dose = 0.0 if mat == EMPTY_MAT else float(doses[i])
            height_fraction = 1.0 if height_fractions is None else float(height_fractions[i])
            height_profile_index = -1 if height_profile_indices is None else int(height_profile_indices[i])
            partition_id = 0 if partition_ids is None else int(partition_ids[i])
            key = (mat, round(dose, 8), round(height_fraction, 8), height_profile_index, partition_id)
        else:
            key = None
        if cur_key is None:
            cur_key = key
            start_i = i
        elif key != cur_key:
            mat0, dose0, height0, profile0, partition0 = cur_key
            runs.append((mat0, float(dose0), float(height0), int(profile0), int(partition0), start_i, i))
            cur_key = key
            start_i = i

    safe_pos = [origin + i * step_mm for i in range(n + 1)]
    if boundary_positions is not None:
        for ri in range(len(runs)-1):
            _mat_l, _dose_l, _height_l, _profile_l, _partition_l, a_l, b_l = runs[ri]
            _mat_r, _dose_r, _height_r, _profile_r, _partition_r, a_r, b_r = runs[ri+1]
            boundary = b_l
            if boundary != a_r or boundary <= 0 or boundary >= n:
                continue
            candidate = float(pos[boundary])
            if (b_l - a_l) <= 1 or (b_r - a_r) <= 1:
                continue
            left_len = abs(candidate - safe_pos[a_l])
            right_len = abs(safe_pos[b_r] - candidate)
            if left_len <= RUNTIME_PRINT_WIDTH_MM + 1e-9 or right_len <= RUNTIME_PRINT_WIDTH_MM + 1e-9:
                continue
            safe_pos[boundary] = candidate

    for mat, dose, height_fraction, height_profile_index, partition_id, a, b in runs:
        if mat == EMPTY_MAT or dose <= 0.0:
            continue
        a0 = safe_pos[a]
        a1 = safe_pos[b]
        if abs(a1 - a0) <= 0.02:
            continue
        if axis == "X":
            x0, x1 = a0, a1
            if band_reverse: x0, x1 = x1, x0
            seg = (x0, fixed_coord, x1, fixed_coord, dose)
        else:
            y0, y1 = a0, a1
            if band_reverse: y0, y1 = y1, y0
            seg = (fixed_coord, y0, fixed_coord, y1, dose)
        if height_fractions is not None:
            seg = seg + (float(height_fraction),)
        if height_profile_indices is not None:
            seg = seg + (int(height_profile_index),)
        segs[mat].append(seg)

def compile_layer(
    img,
    logical_layer,
    x_origin,
    y_origin,
    stack_grid: Optional[np.ndarray] = None,
    dose_grid: Optional[np.ndarray] = None,
    carrier_height_grid: Optional[np.ndarray] = None,
    zoffset_height_profile_grid: Optional[np.ndarray] = None,
    atomic_partition_grid: Optional[np.ndarray] = None,
    road_orientation: Optional[str] = None,
    perpendicular_phase_shift_mm: float = 0.0,
    material_road_geometry: Optional[Dict[str, Tuple[str, float]]] = None,
    bounded_valleys_only: bool = False,
):
    """Compile one logical/source layer from the authoritative RP-resolution stack.

    ppv41 note: logical_layer may differ from emitted physical Z layer.  This is
    used to reverse optical layer draw order while keeping the same generated
    stack and recipe selection.

    ppv26 geometry rules:
      - Input/RP pixel pitch is RP_PITCH_MM, normally 0.10 mm.
      - Printed road width is RUNTIME_PRINT_WIDTH_MM, normally print_width_mm = pixel_head_width RP pixels.
      - For X layers, step across Y by pixel_head_width RP rows and run along X at 1-RP precision.
      - For Y layers, step across X by pixel_head_width RP columns and run along Y at 1-RP precision.
    """
    arr = _img_array(img)
    h_img, w_img = arr.shape[:2]
    road_rp = int(RUNTIME_PIXEL_HEAD_WIDTH)
    active_orientation = str(road_orientation or orientation(logical_layer)).strip().upper()
    phase_shift = float(perpendicular_phase_shift_mm)
    if active_orientation not in ("X", "Y"):
        raise ValueError(f"road orientation must be X or Y, got {road_orientation!r}")
    if not math.isfinite(phase_shift) or phase_shift < 0.0:
        raise ValueError(
            f"perpendicular phase shift must be finite and non-negative, got {perpendicular_phase_shift_mm!r}"
        )

    active_stack = PRECOMPUTED_STACK_GRID if stack_grid is None else stack_grid
    active_dose = PRECOMPUTED_DOSE_GRID if dose_grid is None else dose_grid
    if active_stack is None:
        raise RuntimeError("Internal error: PRECOMPUTED_STACK_GRID is required for optical/base layer emission. Image mode must build a calibrated stack-LUT plan before G-code compilation; no procedural no-LUT fallback remains.")
    h_rp, w_rp = active_stack.shape[:2]

    card_w = w_rp * RUNTIME_RP_PITCH_MM
    card_h = h_rp * RUNTIME_RP_PITCH_MM
    segs = {m: [] for m in MATERIAL_ORDER}

    if logical_layer == 0:
        # PPV65: the 0.20 mm W base is always a solid full-card foundation.
        # Alpha/empty pixels affect only optical/direct layers above the base.
        for road_y in range(0, h_rp, road_rp):
            y = y_origin + (road_y + road_rp / 2.0) * RUNTIME_RP_PITCH_MM
            x0 = x_origin
            x1 = x_origin + card_w
            if (road_y // road_rp) % 2:
                x0, x1 = x1, x0
            segs["W"].append((x0, y, x1, y))
        return segs

    if material_road_geometry:
        # v1.64 needs two independent lattices within the normal pass: upper
        # RGBCY Z-offset roads follow/phase against the X foundation, while the
        # lower W carrier retains the ordinary Y lattice from v1.61. Compile
        # each unique lattice independently, then keep only its assigned
        # materials. Source sampling, dose and carrier-height data are unchanged.
        grouped_materials: Dict[Tuple[str, float], List[str]] = {}
        default_geometry = (active_orientation, phase_shift)
        for material in MATERIAL_ORDER:
            raw_geometry = material_road_geometry.get(material, default_geometry)
            geometry = (str(raw_geometry[0]).strip().upper(), float(raw_geometry[1]))
            if geometry[0] not in ("X", "Y"):
                raise ValueError(f"invalid road orientation {geometry[0]!r} for material {material}")
            if not math.isfinite(geometry[1]) or geometry[1] < 0.0:
                raise ValueError(f"invalid perpendicular phase {geometry[1]!r} for material {material}")
            grouped_materials.setdefault(geometry, []).append(material)

        combined = {m: [] for m in MATERIAL_ORDER}
        for (group_orientation, group_phase), materials in grouped_materials.items():
            partial = compile_layer(
                img,
                logical_layer,
                x_origin,
                y_origin,
                stack_grid=stack_grid,
                dose_grid=dose_grid,
                carrier_height_grid=carrier_height_grid,
                zoffset_height_profile_grid=zoffset_height_profile_grid,
                atomic_partition_grid=atomic_partition_grid,
                road_orientation=group_orientation,
                perpendicular_phase_shift_mm=group_phase,
                material_road_geometry=None,
                bounded_valleys_only=bounded_valleys_only,
            )
            for material in materials:
                combined[material].extend(partial[material])
        return combined

    stack_i = logical_layer - 1
    arr_bottom = arr[::-1, :, :]  # model Y=0 is source bottom row.

    def material_at_rp(yy: int, xx: int) -> str:
        if active_stack is not None:
            if 0 <= yy < h_rp and 0 <= xx < w_rp and 0 <= stack_i < active_stack.shape[2]:
                return str(active_stack[yy, xx, stack_i])
            return EMPTY_MAT
        return EMPTY_MAT

    def dose_at_rp(yy: int, xx: int) -> float:
        if active_dose is not None:
            if 0 <= yy < h_rp and 0 <= xx < w_rp and 0 <= stack_i < active_dose.shape[2]:
                return float(active_dose[yy, xx, stack_i])
            return 0.0
        return 1.0

    def height_at_rp(yy: int, xx: int) -> float:
        if carrier_height_grid is not None:
            if 0 <= yy < h_rp and 0 <= xx < w_rp and 0 <= stack_i < carrier_height_grid.shape[2]:
                return float(carrier_height_grid[yy, xx, stack_i])
            return 0.0
        return 1.0

    def height_profile_at_rp(yy: int, xx: int) -> int:
        if zoffset_height_profile_grid is not None:
            if 0 <= yy < h_rp and 0 <= xx < w_rp and 0 <= stack_i < zoffset_height_profile_grid.shape[2]:
                return int(zoffset_height_profile_grid[yy, xx, stack_i])
        return -1

    def partition_at_rp(yy: int, xx: int) -> int:
        if atomic_partition_grid is not None:
            if 0 <= yy < h_rp and 0 <= xx < w_rp and 0 <= stack_i < atomic_partition_grid.shape[2]:
                return int(atomic_partition_grid[yy, xx, stack_i])
        return 0

    if active_orientation == "X":
        # X roads: one 0.40 mm road per pixel_head_width RP rows; endpoints at 0.10 mm X precision.
        road_y_positions = list(range(0, h_rp, road_rp))
        if bounded_valleys_only and phase_shift > 1e-12:
            road_y_positions = road_y_positions[:-1]
        for road_y in road_y_positions:
            sample_y = road_y
            mats = [material_at_rp(sample_y, x) for x in range(w_rp)]
            doses = [dose_at_rp(sample_y, x) for x in range(w_rp)]
            heights = [height_at_rp(sample_y, x) for x in range(w_rp)] if carrier_height_grid is not None else None
            profiles = [height_profile_at_rp(sample_y, x) for x in range(w_rp)] if zoffset_height_profile_grid is not None else None
            partitions = [partition_at_rp(sample_y, x) for x in range(w_rp)] if atomic_partition_grid is not None else None
            y_model = (
                y_origin
                + (road_y + road_rp / 2.0) * RUNTIME_RP_PITCH_MM
                + phase_shift
            )
            band_reverse = bool((road_y // road_rp) % 2)
            _append_runs(segs, mats, y_model, x_origin, band_reverse, "X", RUNTIME_RP_PITCH_MM, boundary_positions=None, doses=doses, height_fractions=heights, height_profile_indices=profiles, partition_ids=partitions)
    else:
        # Y roads: one 0.40 mm road per pixel_head_width RP columns; endpoints at 0.10 mm Y precision.
        road_x_positions = list(range(0, w_rp, road_rp))
        if bounded_valleys_only and phase_shift > 1e-12:
            road_x_positions = road_x_positions[:-1]
        for road_x in road_x_positions:
            sample_x = road_x
            mats = [material_at_rp(y, sample_x) for y in range(h_rp)]
            doses = [dose_at_rp(y, sample_x) for y in range(h_rp)]
            heights = [height_at_rp(y, sample_x) for y in range(h_rp)] if carrier_height_grid is not None else None
            profiles = [height_profile_at_rp(y, sample_x) for y in range(h_rp)] if zoffset_height_profile_grid is not None else None
            partitions = [partition_at_rp(y, sample_x) for y in range(h_rp)] if atomic_partition_grid is not None else None
            x_model = (
                x_origin
                + (road_x + road_rp / 2.0) * RUNTIME_RP_PITCH_MM
                + phase_shift
            )
            band_reverse = bool((road_x // road_rp) % 2)
            _append_runs(segs, mats, x_model, y_origin, band_reverse, "Y", RUNTIME_RP_PITCH_MM, boundary_positions=None, doses=doses, height_fractions=heights, height_profile_indices=profiles, partition_ids=partitions)

    return segs



class CarrierValleySupportIndex:
    """Exact carrier-centreline coverage used by same-layer infill scheduling.

    It deliberately tracks only carrier model roads, not tower/travel geometry.
    An infill road is legal only when both neighbouring carrier centrelines
    cover the complete longitudinal extent of that infill road.
    """
    def __init__(self):
        self.x_lines: Dict[float, List[Tuple[float, float]]] = {}
        self.y_lines: Dict[float, List[Tuple[float, float]]] = {}

    @staticmethod
    def _q(v: float) -> float:
        return float(f"{float(v):.3f}")

    def add_segments(self, segments: Sequence[tuple]) -> None:
        for seg in segments:
            if len(seg) < 4:
                continue
            x0,y0,x1,y1 = map(self._q, seg[:4])
            if y0 == y1:
                a,b = sorted((x0,x1)); self.x_lines.setdefault(y0, []).append((a,b))
            elif x0 == x1:
                a,b = sorted((y0,y1)); self.y_lines.setdefault(x0, []).append((a,b))
            else:
                raise RuntimeError(f"same-layer carrier support requires axis-aligned roads: {seg[:4]}")

    @staticmethod
    def _covers(spans: Sequence[Tuple[float,float]], a: float, b: float, tol: float = 0.0015) -> bool:
        if not spans:
            return False
        lo,hi = sorted((float(a),float(b)))
        merged=[]
        for s0,s1 in sorted((min(x,y),max(x,y)) for x,y in spans):
            if not merged or s0 > merged[-1][1] + tol:
                merged.append([s0,s1])
            else:
                merged[-1][1]=max(merged[-1][1],s1)
        for s0,s1 in merged:
            if s0 <= lo + tol and s1 >= hi - tol:
                return True
            if s0 > lo + tol:
                return False
        return False

    def infill_segment_supported(self, seg: tuple, road_pitch_mm: float) -> bool:
        x0,y0,x1,y1 = map(self._q, seg[:4])
        half=float(road_pitch_mm)/2.0
        if y0 == y1:
            left=self._q(y0-half); right=self._q(y0+half)
            return self._covers(self.x_lines.get(left, []), x0,x1) and self._covers(self.x_lines.get(right, []), x0,x1)
        if x0 == x1:
            left=self._q(x0-half); right=self._q(x0+half)
            return self._covers(self.y_lines.get(left, []), y0,y1) and self._covers(self.y_lines.get(right, []), y0,y1)
        return False

    def all_infill_supported(self, segments: Sequence[tuple], road_pitch_mm: float) -> Tuple[bool, Dict[str,int]]:
        total=len(segments); good=sum(1 for seg in segments if self.infill_segment_supported(seg, road_pitch_mm))
        return good == total, {"segments": int(total), "supported": int(good), "unsupported": int(total-good)}


def audit_complete_carrier_compiled_geometry(segs: Dict[str, Sequence[tuple]], logical_layer: int, x_origin: float, y_origin: float, card_w: float, card_h: float) -> Dict[str, object]:
    """Prove one paired-infill carrier layer is complete and above carrier_dose_min."""
    orient=orientation(int(logical_layer))
    pitch=float(RUNTIME_PRINT_WIDTH_MM)
    support=CarrierValleySupportIndex()
    total_segments=0
    bad_dose=0
    observed_doses=[]
    _arch = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
    min_dose = float(_arch.get("carrier_dose_min", 1.0)) if isinstance(_arch, dict) else 1.0
    for mat,ss in segs.items():
        if direct_variable_height_operation("normal", mat, int(logical_layer)) != "carrier":
            if ss:
                raise RuntimeError(f"logical layer {logical_layer} normal material {mat} is not classified as carrier")
            continue
        support.add_segments(ss); total_segments += len(ss)
        for seg in ss:
            if len(seg) >= 5:
                d=float(seg[4]); observed_doses.append(d)
                if d < min_dose - 1e-7 or d > 1.0 + 1e-7:
                    bad_dose += 1
    if bad_dose:
        raise RuntimeError(
            f"logical layer {logical_layer} carrier has {bad_dose} compiled segments outside "
            f"required dose range {min_dose:.4f}..1.0000"
        )
    if orient == "X":
        fixed=[CarrierValleySupportIndex._q(y_origin+(i+0.5)*pitch) for i in range(int(round(card_h/pitch)))]
        missing=[y for y in fixed if not support._covers(support.x_lines.get(y,[]), x_origin, x_origin+card_w)]
    else:
        fixed=[CarrierValleySupportIndex._q(x_origin+(i+0.5)*pitch) for i in range(int(round(card_w/pitch)))]
        missing=[x for x in fixed if not support._covers(support.y_lines.get(x,[]), y_origin, y_origin+card_h)]
    if missing:
        raise RuntimeError(f"logical layer {logical_layer} carrier lattice incomplete: {len(missing)} missing/partial {orient} carrier roads; examples={missing[:8]}")
    return {
        "result":"PASS",
        "logical_layer":int(logical_layer),
        "orientation":orient,
        "carrier_lines":len(fixed),
        "segments":int(total_segments),
        "carrier_dose_min_required":float(min_dose),
        "carrier_dose_min_observed":float(min(observed_doses)) if observed_doses else None,
        "carrier_dose_max_observed":float(max(observed_doses)) if observed_doses else None,
    }


def audit_atomic_filter_ownership(logical: int) -> Dict[str, object]:
    """Validate canonical 0.40-mm ownership for same-layer offset infill.

    Ownership is determined exclusively by the logical source pixel sampled by
    compile_layer().  The physical +0.20-mm phase may place that extrusion in a
    valley between neighbouring carrier roads that have different owner IDs,
    materials or doses.  Those neighbour differences are expected at arbitrary
    recipe/family transitions and are diagnostic only.

    Fail-closed invariants when an atomic partition grid is present:
      - every active filter/infill source pixel has one positive owner ID;
      - every active filter/infill source pixel has an active logical carrier at
        the SAME source pixel (the carrier may be any valid material/dose);
      - the source owner is never replaced by either physical neighbour's owner.

    This audit deliberately does NOT require both physical valley neighbours to
    share an owner/material/dose.  Doing so would re-introduce the rejected
    half-road/shared-transition model.
    """
    if DIRECT_ATOMIC_PARTITION_GRID is None:
        return {"result": "SKIP", "reason": "no_atomic_partition_grid", "logical_layer": int(logical)}
    li = int(logical) - 1
    if li < 0 or DIRECT_FILTER_STACK_GRID is None or DIRECT_FILTER_DOSE_GRID is None:
        return {"result": "SKIP", "reason": "no_filter_grid", "logical_layer": int(logical)}
    if PRECOMPUTED_STACK_GRID is None or PRECOMPUTED_DOSE_GRID is None:
        raise RuntimeError(f"logical layer {logical} atomic ownership audit requires carrier stack+dose grids")
    if li >= DIRECT_ATOMIC_PARTITION_GRID.shape[2]:
        return {"result": "SKIP", "reason": "partition_layer_missing", "logical_layer": int(logical)}

    owner = DIRECT_ATOMIC_PARTITION_GRID[:, :, li]
    filt = DIRECT_FILTER_STACK_GRID[:, :, li]
    filt_dose = DIRECT_FILTER_DOSE_GRID[:, :, li]
    carrier = PRECOMPUTED_STACK_GRID[:, :, li]
    carrier_dose = PRECOMPUTED_DOSE_GRID[:, :, li]
    if owner.shape != filt.shape or owner.shape != filt_dose.shape or owner.shape != carrier.shape or owner.shape != carrier_dose.shape:
        raise RuntimeError(
            f"logical layer {logical} atomic ownership grid-shape mismatch: "
            f"owner={owner.shape} filter={filt.shape} dose={filt_dose.shape} "
            f"carrier={carrier.shape} carrier_dose={carrier_dose.shape}"
        )

    active = (filt != EMPTY_MAT) & (filt_dose > 0.0)
    active_count = int(np.count_nonzero(active))
    bad = []

    # Every active source pixel must be positively owned and must have its own
    # logical carrier.  This is the ownership contract; physical neighbours are
    # intentionally irrelevant to pass/fail.
    ys, xs = np.nonzero(active)
    for yy, xx in zip(ys, xs):
        oid = int(owner[yy, xx])
        cmat = str(carrier[yy, xx])
        cdose = float(carrier_dose[yy, xx])
        if oid <= 0:
            bad.append((int(xx), int(yy), "active_filter_without_positive_owner", oid))
        elif cmat == EMPTY_MAT or cdose <= 0.0:
            bad.append((int(xx), int(yy), "active_filter_without_logical_carrier", oid, cmat, round(cdose, 8)))
        if len(bad) >= 12:
            break
    if bad:
        raise RuntimeError(
            f"logical layer {logical} atomic filter-ownership audit failed: "
            f"active offset infill must retain one positive 0.40-mm source owner and its own logical carrier; "
            f"examples={bad}"
        )

    # Diagnostics at the exact source rows/columns compile_layer() samples.  A
    # filter belonging to the current logical pixel is physically shifted toward
    # the +perpendicular neighbour.  Count owner/material changes there, but do
    # NOT reinterpret them as ownership violations.
    road_rp = int(RUNTIME_PIXEL_HEAD_WIDTH)
    orient = orientation(int(logical))
    h, w = owner.shape
    sampled_active = 0
    owner_boundary_valleys = 0
    owner_to_unowned_valleys = 0
    mixed_carrier_owner_boundary_valleys = 0
    mixed_carrier_any_neighbour_valleys = 0

    def inspect_physical_neighbour(fy: int, fx: int, ny: int, nx: int) -> None:
        nonlocal sampled_active, owner_boundary_valleys, owner_to_unowned_valleys
        nonlocal mixed_carrier_owner_boundary_valleys, mixed_carrier_any_neighbour_valleys
        if str(filt[fy, fx]) == EMPTY_MAT or float(filt_dose[fy, fx]) <= 0.0:
            return
        sampled_active += 1
        a = int(owner[fy, fx])
        b = int(owner[ny, nx])
        ca = str(carrier[fy, fx]); cb = str(carrier[ny, nx])
        da = round(float(carrier_dose[fy, fx]), 8)
        db = round(float(carrier_dose[ny, nx]), 8)
        mixed_carrier = (ca != cb or da != db)
        if mixed_carrier:
            mixed_carrier_any_neighbour_valleys += 1
        if a > 0 and b > 0 and a != b:
            owner_boundary_valleys += 1
            if mixed_carrier:
                mixed_carrier_owner_boundary_valleys += 1
        elif a > 0 and b <= 0:
            owner_to_unowned_valleys += 1

    if orient == "X":
        for yy in range(0, max(0, h - road_rp), road_rp):
            yy2 = yy + road_rp
            for xx in range(w):
                inspect_physical_neighbour(yy, xx, yy2, xx)
    else:
        for xx in range(0, max(0, w - road_rp), road_rp):
            xx2 = xx + road_rp
            for yy in range(h):
                inspect_physical_neighbour(yy, xx, yy, xx2)

    return {
        "result": "PASS",
        "logical_layer": int(logical),
        "orientation": orient,
        "ownership_semantics": "logical_0.40mm_source_pixel_wholly_owns_offset_infill",
        "active_filter_source_pixels_checked": active_count,
        "active_filter_emission_samples_checked": int(sampled_active),
        "physical_owner_boundary_valleys": int(owner_boundary_valleys),
        "physical_owner_to_unowned_valleys": int(owner_to_unowned_valleys),
        "physical_mixed_carrier_owner_boundary_valleys": int(mixed_carrier_owner_boundary_valleys),
        "physical_mixed_carrier_any_neighbour_valleys": int(mixed_carrier_any_neighbour_valleys),
        "neighbour_carrier_purity_required": False,
        "shared_or_half_road_ownership_allowed": False,
    }


def audit_atomic_pure_filter_valleys(logical: int) -> Dict[str, object]:
    """Backward-compatible function alias; v1.155 ownership semantics are canonical."""
    return audit_atomic_filter_ownership(logical)


def audit_atomic_cross_layer_owner(logical: int) -> Dict[str, object]:
    """Validate logical cross-layer ownership at the same 0.40-mm source pixel.

    This is a logical raster check, not a physical-bead containment test.  The
    top offset filter may physically overlap neighbouring support geometry, but
    its source pixel must have one positive owner and that same owner ID at the
    corresponding logical support pixel.  Endpoint proximity is reported only
    as a diagnostic and never redefines ownership.
    """
    if DIRECT_ATOMIC_PARTITION_GRID is None:
        return {"result": "SKIP", "reason": "no_atomic_partition_grid", "logical_layer": int(logical)}
    li = int(logical) - 1
    under_li = li - 1
    if li < 0 or under_li < 0 or DIRECT_FILTER_STACK_GRID is None or DIRECT_FILTER_DOSE_GRID is None:
        return {"result": "SKIP", "reason": "no_support_layer", "logical_layer": int(logical)}
    if li >= DIRECT_ATOMIC_PARTITION_GRID.shape[2] or under_li >= DIRECT_ATOMIC_PARTITION_GRID.shape[2]:
        return {"result": "SKIP", "reason": "partition_layer_missing", "logical_layer": int(logical)}

    top_owner = DIRECT_ATOMIC_PARTITION_GRID[:, :, li]
    under_owner = DIRECT_ATOMIC_PARTITION_GRID[:, :, under_li]
    if not np.any(under_owner > 0):
        return {"result": "SKIP", "reason": "no_owned_support_partition", "logical_layer": int(logical), "support_logical_layer": int(logical)-1}
    filt = DIRECT_FILTER_STACK_GRID[:, :, li]
    filt_dose = DIRECT_FILTER_DOSE_GRID[:, :, li]
    active = (filt != EMPTY_MAT) & (filt_dose > 0.0)
    ys, xs = np.nonzero(active)
    checked = int(len(xs))
    bad = []
    for yy, xx in zip(ys, xs):
        a = int(top_owner[yy, xx]); b = int(under_owner[yy, xx])
        if a <= 0 or b <= 0 or a != b:
            bad.append((int(xx), int(yy), a, b))
            if len(bad) >= 12:
                break
    if bad:
        raise RuntimeError(
            f"logical layer {logical} atomic cross-layer owner audit failed: top active infill must retain one positive owner and the same logical owner ID on the support layer; examples={bad}"
        )

    # Endpoint proximity along the support layer's actual road direction.
    # Cache contiguous-run bounds for (axis-line, owner, coordinate) queries.
    support_orient = orientation(int(logical) - 1)
    pitch = float(RUNTIME_RP_PITCH_MM)
    distances = []
    run_cache = {}
    for yy, xx in zip(ys, xs):
        oid = int(top_owner[yy, xx])
        if support_orient == "Y":
            key = (int(xx), oid)
            runs = run_cache.get(key)
            if runs is None:
                col = under_owner[:, xx]
                runs = []
                start = None
                for q, val in enumerate(col):
                    if int(val) == oid and start is None:
                        start = q
                    if start is not None and (int(val) != oid or q == len(col)-1):
                        end = q if (q == len(col)-1 and int(val) == oid) else q-1
                        runs.append((start, end)); start = None
                run_cache[key] = runs
            coord = int(yy)
        else:
            key = (int(yy), oid)
            runs = run_cache.get(key)
            if runs is None:
                row = under_owner[yy, :]
                runs = []
                start = None
                for q, val in enumerate(row):
                    if int(val) == oid and start is None:
                        start = q
                    if start is not None and (int(val) != oid or q == len(row)-1):
                        end = q if (q == len(row)-1 and int(val) == oid) else q-1
                        runs.append((start, end)); start = None
                run_cache[key] = runs
            coord = int(xx)
        for lo, hi in runs:
            if lo <= coord <= hi:
                # sample-centre distance to nearest owned-run edge
                distances.append(min(coord - lo + 0.5, hi - coord + 0.5) * pitch)
                break
    if distances:
        arr = np.asarray(distances, dtype=np.float64)
        prox = {
            "min_mm": round(float(np.min(arr)), 4),
            "p10_mm": round(float(np.percentile(arr, 10)), 4),
            "median_mm": round(float(np.median(arr)), 4),
            "count_le_1mm": int(np.sum(arr <= 1.0)),
            "count_le_3mm": int(np.sum(arr <= 3.0)),
        }
    else:
        prox = {"min_mm": None, "p10_mm": None, "median_mm": None, "count_le_1mm": 0, "count_le_3mm": 0}
    return {
        "result": "PASS", "logical_layer": int(logical), "support_logical_layer": int(logical)-1,
        "active_filter_samples_checked": checked, "support_orientation": support_orient,
        "support_endpoint_proximity": prox,
    }


def audit_atomic_cross_layer_support(logical: int) -> Dict[str, object]:
    """Backward-compatible function alias; v1.155 logical owner semantics are canonical."""
    return audit_atomic_cross_layer_owner(logical)


def build_same_layer_infill_actions(img, physical: int, logical: int, x_origin: float, y_origin: float, card_w: float, card_h: float) -> Tuple[List[Dict[str, object]], Dict[str, object]]:
    """Plan carrier/infill actions using the binary all-now-or-defer rule."""
    if physical <= 0:
        raise ValueError("same-layer infill scheduler is optical-layer only")
    # v1.145: normal carrier topology remains independent of FILTER profile
    # metadata. Carrier dose may lie in carrier_dose_min..1.0 (for example
    # B80..B100). Its HEIGHT meaning is card-selectable:
    #   dose_scaled   -> later 4x4 behaviour, height=min(1,dose)
    #   fixed_nominal -> historical old-VE behaviour, E scales but carrier
    #                    remains at the ordinary 0.10 mm nominal layer plane.
    # Filter profile IDs remain forbidden on normal carriers.
    normal_segs=compile_layer(
        img, logical, x_origin,y_origin,
        stack_grid=PRECOMPUTED_STACK_GRID, dose_grid=PRECOMPUTED_DOSE_GRID,
        carrier_height_grid=DIRECT_CARRIER_HEIGHT_GRID,
        zoffset_height_profile_grid=None,
        atomic_partition_grid=DIRECT_ATOMIC_PARTITION_GRID,
        road_orientation=orientation(logical), perpendicular_phase_shift_mm=0.0,
        material_road_geometry=None, bounded_valleys_only=False,
    )
    _carrier_contract_failures = []
    _arch = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
    _carrier_dose_min = float(_arch.get("carrier_dose_min", 1.0)) if isinstance(_arch, dict) else 1.0
    _normal_carrier_height_mode = (
        str(_arch.get("normal_carrier_height_mode", "dose_scaled")).strip().lower()
        if isinstance(_arch, dict) else "dose_scaled"
    )
    for _mat, _ss in normal_segs.items():
        for _seg in _ss:
            # Expected shape is geometry+dose+carrier-height, with NO seventh
            # filter-profile field.
            if len(_seg) != 6:
                _carrier_contract_failures.append((_mat, "segment_field_count", _seg))
                continue
            _d = float(_seg[4])
            _h = float(seg_height_fraction(_seg))
            if _normal_carrier_height_mode == "fixed_nominal":
                _expected_h = 1.0
            elif _normal_carrier_height_mode == "dose_scaled":
                _expected_h = min(1.0, max(0.0, _d))
            else:
                _carrier_contract_failures.append(
                    (_mat, "invalid_normal_carrier_height_mode", _seg)
                )
                _expected_h = _h
            if _d < _carrier_dose_min - 1e-9 or _d > 1.0 + 1e-9:
                _carrier_contract_failures.append((_mat, "dose_outside_allowed_range", _seg))
            if abs(_h - _expected_h) > 1e-9:
                _carrier_contract_failures.append(
                    (_mat, f"carrier_height_wrong_for_{_normal_carrier_height_mode}", _seg)
                )
            if int(seg_height_profile_index(_seg)) != -1:
                _carrier_contract_failures.append((_mat, "filter_profile_leak", _seg))
    if _carrier_contract_failures:
        raise RuntimeError(
            "v1.145 same-layer high-VE carrier contract failed: "
            f"{len(_carrier_contract_failures)} failures; "
            f"examples={_carrier_contract_failures[:3]}"
        )

    filter_ownership_audit = audit_atomic_filter_ownership(logical)
    cross_layer_owner_audit = audit_atomic_cross_layer_owner(logical)

    filter_segs=compile_layer(
        img, logical, x_origin,y_origin,
        stack_grid=DIRECT_FILTER_STACK_GRID, dose_grid=DIRECT_FILTER_DOSE_GRID,
        carrier_height_grid=direct_dose_to_carrier_height_fraction(DIRECT_FILTER_DOSE_GRID),
        zoffset_height_profile_grid=DIRECT_ZOFFSET_HEIGHT_PROFILE_GRID,
        atomic_partition_grid=DIRECT_ATOMIC_PARTITION_GRID,
        road_orientation=orientation(logical), perpendicular_phase_shift_mm=direct_filter_phase_shift_mm(),
        material_road_geometry=None, bounded_valleys_only=True,
    )
    carrier_audit=audit_complete_carrier_compiled_geometry(normal_segs, logical, x_origin,y_origin,card_w,card_h)
    carrier_order=[m for m in get_runtime_material_order() if normal_segs.get(m)]
    infill_order=[m for m in get_runtime_material_order() if filter_segs.get(m)]
    support=CarrierValleySupportIndex()
    actions=[]; completed=set(); deferred=[]; decisions=[]
    for mat in carrier_order:
        actions.append({"pass_role":"normal","material":mat,"segs":{m:(list(normal_segs[m]) if m==mat else []) for m in MATERIAL_ORDER},"prime_kind":"primary","decision":"carrier"})
        support.add_segments(normal_segs[mat])
        if filter_segs.get(mat):
            ok,report=support.all_infill_supported(filter_segs[mat], float(RUNTIME_PRINT_WIDTH_MM))
            decisions.append({"material":mat,"after_carrier":True,"all_supported":bool(ok),**report})
            if ok:
                actions.append({"pass_role":"filter","material":mat,"segs":{m:(list(filter_segs[m]) if m==mat else []) for m in MATERIAL_ORDER},"prime_kind":"none","decision":"immediate"})
                completed.add(mat)
            else:
                deferred.append(mat)
    # Materials with infill but no carrier have no first-pass decision point; they
    # print once after all carriers exist, using their primary tower prime.
    for mat in infill_order:
        if mat in completed:
            continue
        ok,report=support.all_infill_supported(filter_segs[mat], float(RUNTIME_PRINT_WIDTH_MM))
        if not ok:
            raise RuntimeError(f"logical layer {logical} infill for {mat} remains unbounded after all carriers: {report}")
        has_carrier=bool(normal_segs.get(mat))
        actions.append({"pass_role":"filter","material":mat,"segs":{m:(list(filter_segs[m]) if m==mat else []) for m in MATERIAL_ORDER},"prime_kind":("secondary" if has_carrier else "primary"),"decision":("deferred" if has_carrier else "infill_only")})
        completed.add(mat)
    primary_used=sorted({a["material"] for a in actions if a["prime_kind"]=="primary"}, key=lambda m:get_runtime_material_order().index(m))
    secondary_used=sorted({a["material"] for a in actions if a["prime_kind"]=="secondary"}, key=lambda m:get_runtime_material_order().index(m))
    for i,a in enumerate(actions):
        a["same_layer_scheduler_action"]=True
        a["new_physical_layer"]=(i==0)
        a["scheduler_action_index"]=i+1
        a["scheduler_action_count"]=len(actions)
        a["complete_tower_layer"]=(i==len(actions)-1)
        a["primary_slots_used"]=primary_used
        a["secondary_slots_used"]=secondary_used
    report={"result":"PASS","logical_layer":int(logical),"carrier_order":carrier_order,"atomic_filter_ownership_audit":filter_ownership_audit,"atomic_cross_layer_owner_audit":cross_layer_owner_audit,"atomic_pure_valley_audit":filter_ownership_audit,"atomic_support_footprint_audit":cross_layer_owner_audit,"legacy_audit_key_aliases":{"atomic_pure_valley_audit":"atomic_filter_ownership_audit","atomic_support_footprint_audit":"atomic_cross_layer_owner_audit"},"infill_order":infill_order,"actions":[{"material":a["material"],"pass_role":a["pass_role"],"prime_kind":a["prime_kind"],"decision":a["decision"]} for a in actions],"decisions":decisions,"carrier_audit":carrier_audit,"primary_slots_used":primary_used,"secondary_slots_used":secondary_used}
    return actions,report

def audit_direct_test_compiled_geometry(
    segs: Dict[str, Sequence[tuple]],
    logical_layer: int,
    pass_role: str,
    x_origin: float,
    y_origin: float,
) -> Dict[str, object]:
    """Audit operation-derived geometry on compiled, pre-trim roads.

    Every normal-pass RGBCY road is a Z-offset operation and must use the
    underlayer direction plus half-road phase. Every normal-pass W road is a
    carrier operation on the ordinary lattice. Every paired-pass road is a
    filter operation parallel to that carrier with a half-road phase. The
    audit accepts any non-empty valid mixture instead of assuming both card
    sections are present.
    """
    logical = int(logical_layer)
    role = str(pass_role)
    ordinary_orientation = orientation(logical)
    upper_orientation = direct_zoffset_underlayer_orientation(logical)
    upper_phase = direct_zoffset_phase_shift_mm()
    lower_filter_phase = direct_filter_phase_shift_mm()
    road_pitch = float(RUNTIME_PRINT_WIDTH_MM)
    if role not in ("normal", "filter"):
        raise ValueError(f"direct test geometry audit requires normal/filter pass, got {pass_role!r}")

    rows: Dict[str, Dict[str, object]] = {}
    for material, material_segments in segs.items():
        if not material_segments:
            continue
        operation = direct_variable_height_operation(role, material, logical)
        if operation == "zoffset":
            expected_orientation = upper_orientation
            expected_phase = upper_phase
            section = "upper_zoffset"
        elif operation == "filter_zoffset":
            expected_orientation = ordinary_orientation
            expected_phase = lower_filter_phase
            section = "same_z_valley_zoffset"
        elif operation == "filter":
            expected_orientation = ordinary_orientation
            expected_phase = lower_filter_phase
            section = "lower_filter"
        elif operation == "carrier":
            expected_orientation = ordinary_orientation
            expected_phase = 0.0
            section = "lower_carrier"
        else:
            raise RuntimeError(
                f"v1.68 operation geometry audit cannot classify {role}/{material}"
            )

        fixed_origin = float(y_origin if expected_orientation == "X" else x_origin)
        lattice_origin = fixed_origin + road_pitch / 2.0 + expected_phase
        lattice_indices = set()
        for seg in material_segments:
            x0, y0, x1, y1 = map(float, seg_xy(seg))
            if expected_orientation == "X":
                if abs(y1 - y0) > 1e-8 or abs(x1 - x0) <= 1e-8:
                    raise RuntimeError(
                        f"v1.65 geometry audit failed: {role}/{material} is not an X road: {seg_xy(seg)}"
                    )
                fixed = y0
            else:
                if abs(x1 - x0) > 1e-8 or abs(y1 - y0) <= 1e-8:
                    raise RuntimeError(
                        f"v1.65 geometry audit failed: {role}/{material} is not a Y road: {seg_xy(seg)}"
                    )
                fixed = x0
            lattice_value = (fixed - lattice_origin) / road_pitch
            lattice_index = int(round(lattice_value))
            if lattice_index < 0 or abs(lattice_value - lattice_index) > 1e-6:
                raise RuntimeError(
                    f"v1.65 geometry audit failed: {role}/{material} fixed coordinate {fixed:.6f} "
                    f"is off its {expected_orientation} lattice origin {lattice_origin:.6f}"
                )
            lattice_indices.add(lattice_index)
        rows[material] = {
            "section": section,
            "orientation": expected_orientation,
            "phase_shift_mm": float(expected_phase),
            "segments": int(len(material_segments)),
            "active_scanlines": int(len(lattice_indices)),
        }

    if not rows:
        raise RuntimeError(f"v1.68 operation geometry audit failed: active {role} pass compiled no roads")

    return {
        "result": "PASS",
        "logical_layer": logical,
        "pass_role": role,
        "ordinary_orientation": ordinary_orientation,
        "upper_underlayer_orientation": upper_orientation,
        "upper_phase_shift_mm": float(upper_phase),
        "lower_filter_orientation": ordinary_orientation,
        "lower_filter_phase_shift_mm": float(lower_filter_phase),
        "materials": rows,
        "geometry_source": "operation_role",
        "zoffset_operation": "normal_chromatic",
        "carrier_operation": "normal_W",
        "filter_operation": "paired_filter_pass",
    }



def _lookup_optical_params(lookup: Optional["RecipeLookup"]) -> Dict:
    """Extract V8 optical parameters from LUT metadata for arbitrary-stack preview."""
    defaults = {
        "measured_weights": {"R": 0.62, "Y": 0.24, "G": 0.42, "C": 0.10, "B": 0.66, "W_T": 0.44, "W_S": 0.62, "F_T": 0.91, "F_S": 0.055},
        "chromatic_transmittance": None,
    }
    if lookup is None:
        return defaults
    try:
        meta = json.loads(getattr(lookup, "metadata_json", "{}") or "{}")
        if "measured_weights" in meta:
            defaults["measured_weights"].update({k: float(v) for k, v in meta["measured_weights"].items() if k in defaults["measured_weights"]})
        if "chromatic_transmittance" in meta:
            defaults["chromatic_transmittance"] = {k: np.asarray(v, dtype=np.float64) for k, v in meta["chromatic_transmittance"].items()}
    except Exception:
        pass
    return defaults


def _predict_stack_rgb_from_symbols(stack_bottom_to_top: Sequence[str], lookup: Optional["RecipeLookup"] = None) -> np.ndarray:
    """Predict RGB for an arbitrary physical bottom->top stack.

    PPSPV7.2:
      - if an exact stored LUT recipe RGB exists, use it;
      - otherwise replay the physical stack using the calibrated filter/blend
        model from LUT metadata / params.
    """
    physical = tuple("F" if str(ch) == "S" else str(ch) for ch in stack_bottom_to_top)
    if lookup is not None and getattr(lookup, "rgb", None) is not None:
        recipe = ''.join(reversed(physical))
        rgb = lookup.rgb_for_recipe_string(recipe) if hasattr(lookup, "rgb_for_recipe_string") else None
        if rgb is not None:
            return np.asarray(rgb, dtype=np.float32)

    params = _demand_optical_model_from_lookup(lookup)
    return _predict_demand_sequence_rgb_from_mats_doses(physical, [1.0] * len(physical), params)


def _weighted_rgb_error(pred: np.ndarray, target: np.ndarray, l_weight: float = 1.0, c_weight: float = 0.75) -> float:
    """Cubic absolute RGB/luma boundary-AA error.

    ppv20 used squared luma + squared RGB-channel error:
        l_weight * dl^2 + c_weight * dot(dc, dc)

    ppv22 deliberately penalises larger visible colour shifts much harder:
        l_weight * abs(dl)^3 + c_weight * sum(abs(dc)^3)

    This should reduce accepted boundary moves unless they are strong, local,
    genuinely useful improvements.
    """
    pred = np.asarray(pred, dtype=np.float32)
    target = np.asarray(target, dtype=np.float32)
    wp = float(0.2126*pred[0] + 0.7152*pred[1] + 0.0722*pred[2])
    wt = float(0.2126*target[0] + 0.7152*target[1] + 0.0722*target[2])
    dl = wp - wt
    dc = pred - target
    return float(float(l_weight) * (abs(dl) ** 3.0) + float(c_weight) * float(np.sum(np.abs(dc) ** 3.0)))


def _find_material_runs(mats: Sequence[str]) -> List[Tuple[str, int, int]]:
    runs = []
    if not mats:
        return runs
    cur = mats[0]
    start = 0
    for i in range(1, len(mats)+1):
        mat = mats[i] if i < len(mats) else None
        if mat != cur:
            runs.append((cur, start, i))
            cur = mat
            start = i
    return runs


def _score_boundary_candidate_1d(source_line: np.ndarray, left_rgb: np.ndarray, right_rgb: np.ndarray,
                                 lo_rp: int, hi_rp: int, boundary_rp: int,
                                 l_weight: float, c_weight: float) -> float:
    """Score one candidate boundary along a 1D RP strip [lo_rp, hi_rp)."""
    if hi_rp <= lo_rp:
        return 0.0
    src = source_line[lo_rp:hi_rp]
    score = 0.0
    for i in range(lo_rp, hi_rp):
        pred = left_rgb if i < boundary_rp else right_rgb
        score += _weighted_rgb_error(pred, source_line[i], l_weight=l_weight, c_weight=c_weight)
    return float(score / max(1, hi_rp - lo_rp))




def _build_initial_rp_material_map(stacks_model: np.ndarray, source_scale: int) -> np.ndarray:
    """Expand locked AP CR grid into bottom-origin RP-resolution W/F/R/G/B/C/Y stack."""
    scale = int(source_scale)
    return np.repeat(np.repeat(stacks_model, scale, axis=0), scale, axis=1).astype('<U1')


def _rgb_from_recipe_order_tuple_cached(recipe_tuple: Tuple[str, ...], lookup: Optional["RecipeLookup"], cache: Dict[str, np.ndarray]) -> np.ndarray:
    """Predict RGB for a LUT/recipe-order stack tuple.

    ppv41 hard rule:
      recipe-order tuple -> direct LUT RGB lookup.

    Do not pass recipe-order tuples through _predict_stack_rgb_from_symbols(),
    because that function is for physical bottom->top fallback reconstruction and
    reverses the stack.  ppv33 accidentally double-reversed in the cache path,
    so AA/diffusion/debug scoring fell back to the legacy optical model for many
    stacks.  That made simply enabling AA or diffusion change the apparent colour
    model/flow.
    """
    key = ''.join("F" if str(ch) == "S" else str(ch) for ch in recipe_tuple)
    rgb = cache.get(key)
    if rgb is None:
        rgb = lookup.rgb_for_recipe_string(key) if lookup is not None and hasattr(lookup, "rgb_for_recipe_string") else None
        if rgb is None:
            # Legacy fallback only when no exact LUT entry exists.
            rgb = _predict_stack_rgb_from_symbols(tuple(key), lookup)
        cache[key] = np.asarray(rgb, dtype=np.float32)
    return cache[key]


def _rgb_from_physical_stack_tuple_cached(physical_bottom_to_top: Tuple[str, ...], lookup: Optional["RecipeLookup"], cache: Dict[str, np.ndarray]) -> np.ndarray:
    """Predict RGB from a physical bottom->top RP stack.

    v1.9 convention: LUT recipe strings and physical stacks are both bottom->top,
    so this function no longer reverses the stack before lookup.
    """
    recipe_tuple = tuple("F" if str(ch) == "S" else str(ch) for ch in physical_bottom_to_top)
    return _rgb_from_recipe_order_tuple_cached(recipe_tuple, lookup, cache)


def _rgb_map_from_rp_materials(rp_mats: np.ndarray, lookup: Optional["RecipeLookup"]) -> np.ndarray:
    """Compute produced RGB from RP stack. RGB is derived, never primary editable state."""
    h, w, layers = rp_mats.shape
    out = np.empty((h, w, 3), dtype=np.float32)
    cache: Dict[str, np.ndarray] = {}
    flat = rp_mats.reshape((-1, layers))
    out_flat = out.reshape((-1, 3))
    for i, stack in enumerate(flat):
        syms = tuple(str(v) for v in stack)
        if all(v == EMPTY_MAT for v in syms):
            out_flat[i, :] = np.asarray([255.0, 255.0, 255.0], dtype=np.float32)
        else:
            # Empty layers are optically absent; remove them before RGB prediction.
            syms = tuple(v for v in syms if v != EMPTY_MAT)
            out_flat[i, :] = _rgb_from_physical_stack_tuple_cached(syms, lookup, cache)
    return out


MATERIAL_SYMBOL_ORDER = "WFTRGBCY."
MATERIAL_SYMBOL_TO_ID = {s: i for i, s in enumerate(MATERIAL_SYMBOL_ORDER)}
MATERIAL_ID_TO_SYMBOL = {i: s for s, i in MATERIAL_SYMBOL_TO_ID.items()}


def _rp_stack_symbols_to_ids(rp_stack_model_bottom: np.ndarray) -> np.ndarray:
    """Convert bottom-origin physical bottom->top RP symbol stack to compact uint8 IDs.

    The NPZ is the source-of-truth diagnostic export: axis order is
    [model_y_bottom_origin, x_left_to_right, physical_layer_bottom_to_top].
    """
    arr = np.asarray(rp_stack_model_bottom)
    out = np.full(arr.shape, 255, dtype=np.uint8)
    for sym, idx in MATERIAL_SYMBOL_TO_ID.items():
        out[arr == sym] = np.uint8(idx)
    bad = np.argwhere(out == 255)
    if bad.size:
        y, x, z = bad[0]
        raise RuntimeError(f"Unknown material symbol in RP stack at model-bottom y={y} x={x} layer={z}: {arr[y, x, z]!r}")
    return out


def _rp_stack_ids_to_symbols(stack_ids: np.ndarray) -> np.ndarray:
    ids = np.asarray(stack_ids, dtype=np.uint8)
    out = np.empty(ids.shape, dtype='<U1')
    for idx, sym in MATERIAL_ID_TO_SYMBOL.items():
        out[ids == idx] = sym
    bad = np.argwhere(ids >= len(MATERIAL_SYMBOL_ORDER))
    if bad.size:
        y, x, z = bad[0]
        raise RuntimeError(f"Unknown material ID in RP stack at model-bottom y={y} x={x} layer={z}: {ids[y, x, z]}")
    return out


def _preview_top_from_rp_stack(rp_stack_model_bottom: np.ndarray, lookup: Optional["RecipeLookup"]) -> np.ndarray:
    """Reconstruct top-oriented RGB preview from exact RP stack symbols as float32 RGB."""
    rgb_model = _rgb_map_from_rp_materials(rp_stack_model_bottom, lookup)
    return np.clip(rgb_model[::-1, :, :], 0, 255).astype(np.float32)


def _compare_preview_or_raise(name: str, reconstructed_top: np.ndarray, expected_top: Optional[np.ndarray]) -> Dict[str, float]:
    if expected_top is None:
        return {"checked": 0.0}
    a = _to_uint8_rgb(reconstructed_top)
    b = _to_uint8_rgb(expected_top)
    if a.shape != b.shape:
        raise RuntimeError(f"{name} preview self-check shape mismatch: reconstructed {a.shape}, expected {b.shape}")
    diff = a.astype(np.int16) - b.astype(np.int16)
    absdiff = np.abs(diff)
    changed = np.any(absdiff != 0, axis=2)
    report = {
        "checked": 1.0,
        "mean_abs_diff": float(absdiff.mean()),
        "max_abs_diff": float(absdiff.max()),
        "changed_pixels": float(changed.sum()),
        "total_pixels": float(changed.size),
    }
    if np.any(changed):
        yy, xx = np.argwhere(changed)[0]
        raise RuntimeError(
            f"{name} preview self-check FAILED at top-image x={int(xx)} y={int(yy)}: "
            f"reconstructed={a[yy, xx, :].tolist()} expected={b[yy, xx, :].tolist()} "
            f"diff={diff[yy, xx, :].tolist()} report={json.dumps(report, sort_keys=True)}"
        )
    print(f"{name.upper()} RGB SELF-CHECK: PASS changed_pixels={int(report['changed_pixels'])} max_abs_diff={int(report['max_abs_diff'])} mean_abs_diff={report['mean_abs_diff']:.6f}", flush=True)
    return report


def _compare_preview_report_only(name: str, reconstructed_top: np.ndarray, expected_top: Optional[np.ndarray], reason: str = "") -> Dict[str, float]:
    """Return a preview comparison report without failing the job.

    3dprintv1.1: lutmakerv1.0 hybrid previews are generated from the LUT's
    selected candidate_predicted_rgb.  The exact RP stack may then be locally
    scheduled/reordered for printing.  Reconstructing RGB from the scheduled
    stack by replaying recipe order is therefore no longer a valid strict
    invariant for hybrid LUTs, especially because RGBCY layer order is treated
    as optically commutative while W remains position-constrained.
    """
    if expected_top is None:
        return {"checked": 0.0, "strict": 0.0, "report_only": 1.0}
    a = _to_uint8_rgb(reconstructed_top)
    b = _to_uint8_rgb(expected_top)
    if a.shape != b.shape:
        return {
            "checked": 1.0,
            "strict": 0.0,
            "report_only": 1.0,
            "shape_mismatch": 1.0,
            "reconstructed_shape": list(a.shape),
            "expected_shape": list(b.shape),
            "reason": str(reason),
        }
    diff = a.astype(np.int16) - b.astype(np.int16)
    absdiff = np.abs(diff)
    changed = np.any(absdiff != 0, axis=2)
    report = {
        "checked": 1.0,
        "strict": 0.0,
        "report_only": 1.0,
        "mean_abs_diff": float(absdiff.mean()),
        "max_abs_diff": float(absdiff.max()),
        "changed_pixels": float(changed.sum()),
        "total_pixels": float(changed.size),
        "reason": str(reason),
    }
    if np.any(changed):
        yy, xx = np.argwhere(changed)[0]
        report.update({
            "first_changed_x": int(xx),
            "first_changed_y": int(yy),
            "first_reconstructed_rgb": a[yy, xx, :].tolist(),
            "first_expected_rgb": b[yy, xx, :].tolist(),
            "first_diff_rgb": diff[yy, xx, :].tolist(),
        })
    print(f"{name.upper()} RGB SELF-CHECK: report-only changed_pixels={int(report.get('changed_pixels', 0))} max_abs_diff={int(report.get('max_abs_diff', 0))} mean_abs_diff={float(report.get('mean_abs_diff', 0.0)):.6f}", flush=True)
    return report


def save_rp_stack_npz(preaa_stack_model: Optional[np.ndarray], postaa_stack_model: Optional[np.ndarray],
                      output_path: Optional[Path], lookup: Optional["RecipeLookup"],
                      preaa_preview_top: Optional[np.ndarray] = None,
                      postaa_preview_top: Optional[np.ndarray] = None) -> None:
    """Save exact symbolic RP stacks and verify RGB reconstruction.

    Unlike visual layer PNGs, this file is lossless. Stored stack ID arrays use:
      0=W, 1=F, 2=R, 3=G, 4=B, 5=C, 6=Y

    Array orientation is model/bottom-origin Y and physical bottom->top layer Z.
    RGB preview arrays, when included, are top-oriented normal image arrays.
    """
    if output_path is None:
        return
    if preaa_stack_model is None and postaa_stack_model is None and preaa_preview_top is None and postaa_preview_top is None:
        print("AA stack NPZ skipped: no RP stack/preview data avairgble", flush=True)
        return
    output_path = Path(output_path)
    output_path.parent.mkdir(parents=True, exist_ok=True)

    payload = {
        "material_order": np.array(list(MATERIAL_SYMBOL_ORDER), dtype='<U1'),
        "material_ids_json": np.array(json.dumps(MATERIAL_SYMBOL_TO_ID, sort_keys=True)),
        "orientation_json": np.array(json.dumps({
            "stack_arrays": "model/bottom-origin y, x left-to-right, physical layers bottom-to-top",
            "preview_arrays": "top-oriented image y, x, RGB",
            "rgb_reconstruction": "_preview_top_from_rp_stack -> _rgb_map_from_rp_materials -> reverse Y",
            "pp_version": PP_VERSION,
        }, sort_keys=True)),
    }
    report_only_hybrid = bool(lookup is not None and getattr(lookup, "is_lutmaker_lut", False))
    hybrid_report_reason = "lutmakerv1.0 hybrid preview is candidate_predicted_rgb; exact stack may be scheduler-reordered, so strict old recipe reconstruction is not a valid invariant"

    if preaa_stack_model is not None:
        pre_ids = _rp_stack_symbols_to_ids(preaa_stack_model)
        pre_recon = _preview_top_from_rp_stack(preaa_stack_model, lookup)
        payload["preaa_stack_ids"] = pre_ids
        payload["preaa_reconstructed_preview_rgb"] = pre_recon
        if report_only_hybrid:
            payload["preaa_selfcheck_json"] = np.array(json.dumps(_compare_preview_report_only("pre-AA", pre_recon, preaa_preview_top, hybrid_report_reason), sort_keys=True))
        else:
            payload["preaa_selfcheck_json"] = np.array(json.dumps(_compare_preview_or_raise("pre-AA", pre_recon, preaa_preview_top), sort_keys=True))
    elif preaa_preview_top is not None:
        # ppv24 intentionally does not retain a second pre-AA stack copy.
        # The pre-AA RGB preview is saved only as a derived diagnostic image.
        payload["preaa_preview_rgb_float"] = np.asarray(preaa_preview_top, dtype=np.float32)
        payload["preaa_note"] = np.array("ppv24 single-authoritative-stack mode: no frozen pre-AA stack copy retained")
    if postaa_stack_model is not None:
        post_ids = _rp_stack_symbols_to_ids(postaa_stack_model)
        post_recon = _preview_top_from_rp_stack(postaa_stack_model, lookup)
        payload["postaa_stack_ids"] = post_ids
        payload["postaa_reconstructed_preview_rgb"] = post_recon
        if report_only_hybrid:
            payload["postaa_selfcheck_json"] = np.array(json.dumps(_compare_preview_report_only("post-AA", post_recon, postaa_preview_top, hybrid_report_reason), sort_keys=True))
        else:
            payload["postaa_selfcheck_json"] = np.array(json.dumps(_compare_preview_or_raise("post-AA", post_recon, postaa_preview_top), sort_keys=True))
    np.savez_compressed(output_path, **payload)
    print(f"Wrote exact RP stack NPZ: {output_path}", flush=True)


def _weighted_rgb_error(pred: np.ndarray, target: np.ndarray, l_weight: float = 1.0, c_weight: float = 0.35) -> float:
    pred = np.asarray(pred, dtype=np.float32)
    target = np.asarray(target, dtype=np.float32)
    lp = float(0.2126*pred[0] + 0.7152*pred[1] + 0.0722*pred[2])
    lt = float(0.2126*target[0] + 0.7152*target[1] + 0.0722*target[2])
    dl = lp - lt
    dc = pred - target
    return float(l_weight * dl * dl + c_weight * float(np.dot(dc, dc)))


def _find_material_runs(mats: Sequence[str]) -> List[Tuple[str, int, int]]:
    runs = []
    if not mats:
        return runs
    cur = mats[0]
    start = 0
    for i in range(1, len(mats)+1):
        mat = mats[i] if i < len(mats) else None
        if mat != cur:
            runs.append((cur, start, i))
            cur = mat
            start = i
    return runs


def _score_points_from_stack(rp_stack: np.ndarray, source_rgb: np.ndarray,
                             points: Sequence[Tuple[int, int]], lookup: Optional["RecipeLookup"],
                             l_weight: float, c_weight: float) -> float:
    cache: Dict[str, np.ndarray] = {}
    score = 0.0
    for yy, xx in points:
        pred = _rgb_from_physical_stack_tuple_cached(tuple(str(v) for v in rp_stack[yy, xx, :]), lookup, cache)
        score += _weighted_rgb_error(pred, source_rgb[yy, xx, :], l_weight=l_weight, c_weight=c_weight)
    return float(score)


def _score_candidate_layer_change(rp_stack: np.ndarray, source_rgb: np.ndarray,
                                  points: Sequence[Tuple[int, int]], stack_i: int, new_mat: str,
                                  lookup: Optional["RecipeLookup"], l_weight: float, c_weight: float) -> float:
    cache: Dict[str, np.ndarray] = {}
    score = 0.0
    for yy, xx in points:
        stack = [str(v) for v in rp_stack[yy, xx, :]]
        stack[stack_i] = str(new_mat)
        pred = _rgb_from_physical_stack_tuple_cached(tuple(stack), lookup, cache)
        score += _weighted_rgb_error(pred, source_rgb[yy, xx, :], l_weight=l_weight, c_weight=c_weight)
    return float(score)


def _apply_layer_change_to_stack(rp_stack: np.ndarray, points: Sequence[Tuple[int, int]], stack_i: int, new_mat: str) -> None:
    for yy, xx in points:
        rp_stack[yy, xx, stack_i] = str(new_mat)


def _points_for_x_boundary_band(row0: int, row1: int, old_boundary: int, new_boundary: int) -> List[Tuple[int, int]]:
    if old_boundary == new_boundary:
        return []
    a, b = sorted((old_boundary, new_boundary))
    return [(yy, xx) for yy in range(row0, row1) for xx in range(a, b)]


def _points_for_y_boundary_band(col0: int, col1: int, old_boundary: int, new_boundary: int) -> List[Tuple[int, int]]:
    if old_boundary == new_boundary:
        return []
    a, b = sorted((old_boundary, new_boundary))
    return [(yy, xx) for yy in range(a, b) for xx in range(col0, col1)]



def _source_detail_map_rgb(source_rgb_model: np.ndarray) -> np.ndarray:
    """Bottom-origin local source-detail map in RGB units."""
    arr = np.asarray(source_rgb_model, dtype=np.float32)
    h, w = arr.shape[:2]
    detail = np.zeros((h, w), dtype=np.float32)
    if w > 1:
        d = np.sqrt(np.sum((arr[:, 1:, :] - arr[:, :-1, :]) ** 2, axis=2))
        detail[:, 1:] = np.maximum(detail[:, 1:], d)
        detail[:, :-1] = np.maximum(detail[:, :-1], d)
    if h > 1:
        d = np.sqrt(np.sum((arr[1:, :, :] - arr[:-1, :, :]) ** 2, axis=2))
        detail[1:, :] = np.maximum(detail[1:, :], d)
        detail[:-1, :] = np.maximum(detail[:-1, :], d)
    if h > 2 and w > 2:
        d2 = detail.copy()
        d2[1:, :] = np.maximum(d2[1:, :], detail[:-1, :])
        d2[:-1, :] = np.maximum(d2[:-1, :], detail[1:, :])
        d2[:, 1:] = np.maximum(d2[:, 1:], detail[:, :-1])
        d2[:, :-1] = np.maximum(d2[:, :-1], detail[:, 1:])
        detail = d2
    return detail


def _mean_detail_for_points(detail_map: Optional[np.ndarray], points: Sequence[Tuple[int, int]]) -> float:
    if detail_map is None or not points:
        return 0.0
    return float(sum(float(detail_map[yy, xx]) for yy, xx in points) / max(1, len(points)))


def _structure_weight_from_detail(detail: float, threshold: float, full: float, min_weight: float) -> float:
    if full <= threshold:
        full = threshold + 1.0
    t = (float(detail) - float(threshold)) / (float(full) - float(threshold))
    t = max(0.0, min(1.0, t))
    return float(min_weight + (1.0 - min_weight) * t)

def build_live_rp_boundary_aa(stacks_top: np.ndarray, lookup: Optional["RecipeLookup"],
                              source_rgb_top: np.ndarray, source_scale: int = None,
                              max_shift_mm: float = None,
                              min_run_mm: float = None,
                              improvement_threshold: float = 0.0,
                              l_weight: float = 1.0,
                              c_weight: float = 0.75,
                              structure_weight: str = "on",
                              detail_threshold: float = 8.0,
                              detail_full: float = 28.0,
                              min_structure_weight: float = 0.15,
                              boundary_cost: float = 250.0,
                              boundary_cost_per_rp: float = 0.0) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, Dict[str, float]]:
    """Boundary AA in RP space while respecting 0.40 mm physical road width.

    Definitions used by ppv26:
      RP = source/working pixel, 0.10 mm.
      AP = recipe assignment block, source_scale x source_scale RP pixels.
      road width = print_width_mm = pixel_head_width RP pixels.

    Recipe selection is done at AP resolution then expanded to the full RP stack.
    AA operates on that RP stack, but a boundary move is always applied across
    the whole 4-RP physical road width perpendicular to the print direction.
    Along the print direction the boundary can move in 1-RP / 0.10 mm steps.
    """
    ap_scale = int(source_scale if source_scale is not None else RUNTIME_PIXEL_HEAD_WIDTH)
    if ap_scale != int(RUNTIME_PIXEL_HEAD_WIDTH):
        raise ValueError("Internal scale mismatch: AP scale must equal derived pixel_head_width")

    ap_ny, ap_nx = stacks_top.shape[:2]
    stacks_model_ap = stacks_top[::-1, :, :]
    rp_stack = _build_initial_rp_material_map(stacks_model_ap, ap_scale)

    h_rp, w_rp = rp_stack.shape[:2]
    source_rgb_model = np.asarray(source_rgb_top[:h_rp, :w_rp, :], dtype=np.float32)[::-1, :, :]
    detail_map = _source_detail_map_rgb(source_rgb_model) if str(structure_weight).lower() == "on" else None

    if max_shift_mm is None:
        max_shift_mm = float(RUNTIME_PRINT_WIDTH_MM)
    if min_run_mm is None:
        min_run_mm = float(RUNTIME_PRINT_WIDTH_MM)

    road_rp = int(RUNTIME_PIXEL_HEAD_WIDTH)  # normally 4
    step_mm = float(RUNTIME_RP_PITCH_MM)                  # RP step, normally 0.10 mm
    max_shift_rp = int(round(float(max_shift_mm) / step_mm))
    min_run_rp = int(math.ceil(float(min_run_mm) / step_mm - 1e-9))
    max_shift_rp = max(0, min(max_shift_rp, max(1, ap_scale)))

    # Kept for compatibility/reporting; final G-code in ppv26 reads rp_stack directly.
    x_offsets = np.zeros((MIX_LAYERS, h_rp, w_rp + 1), dtype=np.float32)
    y_offsets = np.zeros((MIX_LAYERS, h_rp + 1, w_rp), dtype=np.float32)

    changed_mask = np.zeros(rp_stack.shape[:2], dtype=bool)

    initial_rgb = _rgb_map_from_rp_materials(rp_stack, lookup)
    preaa_mapped_preview_top = np.clip(initial_rgb[::-1, :, :], 0, 255).astype(np.float32)
    initial_error = 0.0
    for yy in range(source_rgb_model.shape[0]):
        for xx in range(source_rgb_model.shape[1]):
            initial_error += _weighted_rgb_error(initial_rgb[yy, xx, :], source_rgb_model[yy, xx, :], l_weight, c_weight)

    layer_stats = []
    for li in range(MIX_LAYERS):
        layer_stats.append({
            "layer": float(li + 1),
            "orientation": orientation(li + 1),
            "boundaries_seen": 0.0,
            "candidate_positions_tested": 0.0,
            "boundaries_moved": 0.0,
            "candidate_rejected_short_run": 0.0,
            "layer_change_events": 0.0,
            "unique_changed_rp": 0.0,
            "current_error_on_accepted_points": 0.0,
            "candidate_error_on_accepted_points": 0.0,
            "net_improvement_on_accepted_points": 0.0,
            "mean_improvement_per_move": 0.0,
            "mean_detail_accepted": 0.0,
            "mean_structure_weight_accepted": 0.0,
            "effective_gain_total": 0.0,
            "rejected_no_effective_gain": 0.0,
        })
    layer_masks = [np.zeros(rp_stack.shape[:2], dtype=bool) for _ in range(MIX_LAYERS)]

    boundaries_seen = tested_positions = moved = rejected_short = 0
    layer_change_events = 0
    improvement_sum = 0.0

    for stack_i in range(MIX_LAYERS - 1, -1, -1):
        orient = orientation(stack_i + 1)
        print(f"Boundary AA RP-stack layer {stack_i+1}/{MIX_LAYERS} ({orient})", flush=True)
        st = layer_stats[stack_i]

        if orient == "X":
            # X roads: step across Y in 4-RP road-width bands, optimise boundaries along X.
            for road_y in range(0, h_rp, road_rp):
                row0 = road_y
                row1 = min(road_y + road_rp, h_rp)
                sample_y = row0
                mats = [str(rp_stack[sample_y, x, stack_i]) for x in range(w_rp)]
                runs = _find_material_runs(mats)
                for ri in range(len(runs)-1):
                    left_mat, a_l, b_l = runs[ri]
                    right_mat, a_r, b_r = runs[ri+1]
                    if b_l != a_r or left_mat == right_mat:
                        continue
                    boundaries_seen += 1
                    st["boundaries_seen"] += 1.0
                    old_boundary = b_l
                    run_left_start = a_l
                    run_right_end = b_r
                    best_delta = 0; best_gain = 0.0; best_points = []
                    best_current = 0.0; best_candidate = 0.0; best_raw_gain = 0.0; best_detail = 0.0; best_sw = 1.0
                    for delta in range(-max_shift_rp, max_shift_rp+1):
                        if delta == 0:
                            continue
                        new_boundary = old_boundary + delta
                        tested_positions += 1
                        st["candidate_positions_tested"] += 1.0
                        if new_boundary <= 0 or new_boundary >= w_rp:
                            rejected_short += 1; st["candidate_rejected_short_run"] += 1.0; continue
                        if (new_boundary - run_left_start) < min_run_rp or (run_right_end - new_boundary) < min_run_rp:
                            rejected_short += 1; st["candidate_rejected_short_run"] += 1.0; continue
                        pts = _points_for_x_boundary_band(row0, row1, old_boundary, new_boundary)
                        current = _score_points_from_stack(rp_stack, source_rgb_model, pts, lookup, l_weight, c_weight)
                        fill = left_mat if new_boundary > old_boundary else right_mat
                        cand = _score_candidate_layer_change(rp_stack, source_rgb_model, pts, stack_i, fill, lookup, l_weight, c_weight)
                        gain = current - cand
                        mean_detail = _mean_detail_for_points(detail_map, pts)
                        sw = _structure_weight_from_detail(mean_detail, detail_threshold, detail_full, min_structure_weight) if detail_map is not None else 1.0
                        move_cost = float(boundary_cost) + float(boundary_cost_per_rp) * float(len(pts))
                        effective_gain = gain * sw - move_cost
                        if effective_gain <= float(improvement_threshold):
                            st["rejected_no_effective_gain"] += 1.0
                        if effective_gain > best_gain + float(improvement_threshold):
                            best_gain = effective_gain; best_delta = delta; best_points = pts
                            best_current = current; best_candidate = cand
                            best_raw_gain = gain; best_detail = mean_detail; best_sw = sw
                    if best_delta:
                        fill = left_mat if best_delta > 0 else right_mat
                        _apply_layer_change_to_stack(rp_stack, best_points, stack_i, fill)
                        for yy, xx in best_points:
                            changed_mask[yy, xx] = True
                            layer_masks[stack_i][yy, xx] = True
                        x_offsets[stack_i, road_y, old_boundary] = best_delta * step_mm
                        moved += 1; st["boundaries_moved"] += 1.0
                        layer_change_events += len(best_points); st["layer_change_events"] += float(len(best_points))
                        improvement_sum += best_raw_gain
                        st["current_error_on_accepted_points"] += float(best_current)
                        st["candidate_error_on_accepted_points"] += float(best_candidate)
                        st["net_improvement_on_accepted_points"] += float(best_raw_gain)
                        st["effective_gain_total"] += float(best_gain)
                        st["mean_detail_accepted"] += float(best_detail)
                        st["mean_structure_weight_accepted"] += float(best_sw)

        else:
            # Y roads: step across X in 4-RP road-width bands, optimise boundaries along Y.
            for road_x in range(0, w_rp, road_rp):
                col0 = road_x
                col1 = min(road_x + road_rp, w_rp)
                sample_x = col0
                mats = [str(rp_stack[y, sample_x, stack_i]) for y in range(h_rp)]
                runs = _find_material_runs(mats)
                for ri in range(len(runs)-1):
                    lower_mat, a_l, b_l = runs[ri]
                    upper_mat, a_r, b_r = runs[ri+1]
                    if b_l != a_r or lower_mat == upper_mat:
                        continue
                    boundaries_seen += 1
                    st["boundaries_seen"] += 1.0
                    old_boundary = b_l
                    run_lower_start = a_l
                    run_upper_end = b_r
                    best_delta = 0; best_gain = 0.0; best_points = []
                    best_current = 0.0; best_candidate = 0.0; best_raw_gain = 0.0; best_detail = 0.0; best_sw = 1.0
                    for delta in range(-max_shift_rp, max_shift_rp+1):
                        if delta == 0:
                            continue
                        new_boundary = old_boundary + delta
                        tested_positions += 1
                        st["candidate_positions_tested"] += 1.0
                        if new_boundary <= 0 or new_boundary >= h_rp:
                            rejected_short += 1; st["candidate_rejected_short_run"] += 1.0; continue
                        if (new_boundary - run_lower_start) < min_run_rp or (run_upper_end - new_boundary) < min_run_rp:
                            rejected_short += 1; st["candidate_rejected_short_run"] += 1.0; continue
                        pts = _points_for_y_boundary_band(col0, col1, old_boundary, new_boundary)
                        current = _score_points_from_stack(rp_stack, source_rgb_model, pts, lookup, l_weight, c_weight)
                        fill = lower_mat if new_boundary > old_boundary else upper_mat
                        cand = _score_candidate_layer_change(rp_stack, source_rgb_model, pts, stack_i, fill, lookup, l_weight, c_weight)
                        gain = current - cand
                        mean_detail = _mean_detail_for_points(detail_map, pts)
                        sw = _structure_weight_from_detail(mean_detail, detail_threshold, detail_full, min_structure_weight) if detail_map is not None else 1.0
                        move_cost = float(boundary_cost) + float(boundary_cost_per_rp) * float(len(pts))
                        effective_gain = gain * sw - move_cost
                        if effective_gain <= float(improvement_threshold):
                            st["rejected_no_effective_gain"] += 1.0
                        if effective_gain > best_gain + float(improvement_threshold):
                            best_gain = effective_gain; best_delta = delta; best_points = pts
                            best_current = current; best_candidate = cand
                            best_raw_gain = gain; best_detail = mean_detail; best_sw = sw
                    if best_delta:
                        fill = lower_mat if best_delta > 0 else upper_mat
                        _apply_layer_change_to_stack(rp_stack, best_points, stack_i, fill)
                        for yy, xx in best_points:
                            changed_mask[yy, xx] = True
                            layer_masks[stack_i][yy, xx] = True
                        y_offsets[stack_i, old_boundary, road_x] = best_delta * step_mm
                        moved += 1; st["boundaries_moved"] += 1.0
                        layer_change_events += len(best_points); st["layer_change_events"] += float(len(best_points))
                        improvement_sum += best_raw_gain
                        st["current_error_on_accepted_points"] += float(best_current)
                        st["candidate_error_on_accepted_points"] += float(best_candidate)
                        st["net_improvement_on_accepted_points"] += float(best_raw_gain)
                        st["effective_gain_total"] += float(best_gain)
                        st["mean_detail_accepted"] += float(best_detail)
                        st["mean_structure_weight_accepted"] += float(best_sw)

    for li, st in enumerate(layer_stats):
        st["unique_changed_rp"] = float(np.count_nonzero(layer_masks[li]))
        st["changed_rp_fraction"] = float(st["unique_changed_rp"] / max(1, changed_mask.size))
        st["mean_improvement_per_move"] = float(st["net_improvement_on_accepted_points"] / max(1.0, st["boundaries_moved"]))
        st["mean_detail_accepted"] = float(st["mean_detail_accepted"] / max(1.0, st["boundaries_moved"]))
        st["mean_structure_weight_accepted"] = float(st["mean_structure_weight_accepted"] / max(1.0, st["boundaries_moved"]))

    final_rgb_model = _rgb_map_from_rp_materials(rp_stack, lookup)
    final_error = 0.0
    for yy in range(source_rgb_model.shape[0]):
        for xx in range(source_rgb_model.shape[1]):
            final_error += _weighted_rgb_error(final_rgb_model[yy, xx, :], source_rgb_model[yy, xx, :], l_weight, c_weight)

    preview_top = np.clip(final_rgb_model[::-1, :, :], 0, 255).astype(np.float32)
    unique_changed = int(np.count_nonzero(changed_mask))
    report = {
        "mode": "rp-roadwidth-boundary-relocation",
        "source_scale": float(ap_scale),
        "ap_scale_rp": float(ap_scale),
        "road_width_rp": float(road_rp),
        "rp_pitch_mm": float(RUNTIME_RP_PITCH_MM),
        "print_width_mm": float(RUNTIME_PRINT_WIDTH_MM),
        "candidate_step_mm": float(step_mm),
        "max_shift_mm": float(max_shift_rp * step_mm),
        "min_run_mm": float(min_run_rp * step_mm),
        "boundaries_seen": float(boundaries_seen),
        "candidate_positions_tested": float(tested_positions),
        "boundaries_moved": float(moved),
        "candidate_rejected_short_run": float(rejected_short),
        "layer_change_events": float(layer_change_events),
        "unique_changed_rp": float(unique_changed),
        "changed_rp_fraction": float(unique_changed / max(1, changed_mask.size)),
        "initial_error": float(initial_error),
        "final_error": float(final_error),
        "net_error_improvement": float(initial_error - final_error),
        "mean_improvement_per_move": float(improvement_sum / max(1, moved)),
        "structure_weight": str(structure_weight),
        "detail_threshold": float(detail_threshold),
        "detail_full": float(detail_full),
        "min_structure_weight": float(min_structure_weight),
        "boundary_cost": float(boundary_cost),
        "boundary_cost_per_rp": float(boundary_cost_per_rp),
        "error_metric": "abs_luma_cubed_plus_abs_rgb_cubed",
        "l_weight": float(l_weight),
        "c_weight": float(c_weight),
        "per_layer": layer_stats,
    }
    return x_offsets, y_offsets, preaa_mapped_preview_top, preview_top, rp_stack, report

def reconstruct_preview_from_boundary_offsets(stacks_model: np.ndarray, x_offsets: Optional[np.ndarray], y_offsets: Optional[np.ndarray],
                                               lookup: Optional["RecipeLookup"], source_scale: int = 4) -> np.ndarray:
    rp = _build_initial_rp_material_map(stacks_model, source_scale)
    rgb = _rgb_map_from_rp_materials(rp, lookup)
    return np.clip(rgb[::-1, :, :], 0, 255).astype(np.float32)


def _edgeaa_hue_deg(rgb_arr: np.ndarray) -> np.ndarray:
    arr = np.asarray(rgb_arr, dtype=np.float32) / 255.0
    mx = arr.max(axis=-1); mn = arr.min(axis=-1)
    diff = mx - mn
    hue = np.zeros(mx.shape, dtype=np.float32)
    mask = diff > 1e-6
    r, g, b = arr[...,0], arr[...,1], arr[...,2]
    m = mask & (mx == r)
    hue[m] = (60 * ((g[m] - b[m]) / diff[m]) + 360) % 360
    m = mask & (mx == g)
    hue[m] = 60 * ((b[m] - r[m]) / diff[m]) + 120
    m = mask & (mx == b)
    hue[m] = 60 * ((r[m] - g[m]) / diff[m]) + 240
    return hue


def _edgeaa_internal_subcell_offset(v: int, scale: int = 4) -> int:
    """Return legal internal edge-AA boundary offset: 1, 2, or 3 subcells.

    4 subcells is the normal full-cell/no-adjust case; 0 means the transition
    belongs outside this cell and should not be emitted as an AA boundary.
    """
    return max(1, min(scale - 1, int(v)))

def _edgeaa_detect_blocks(arr: np.ndarray, scale: int = 4, luma_thresh: float = 28.0,
                          chroma_thresh: float = 34.0, hue_thresh: float = 25.0,
                          sat_thresh: float = 0.18) -> np.ndarray:
    """Return top-origin bool grid of coarse cells with strong 4x internal edge."""
    h, w = arr.shape[:2]
    ny = h // scale; nx = w // scale
    arr = arr[:ny*scale, :nx*scale, :].astype(np.float32)
    edge = np.zeros((ny, nx), dtype=bool)
    for y in range(ny):
        for x in range(nx):
            blk = arr[y*scale:(y+1)*scale, x*scale:(x+1)*scale, :]
            luma = 0.2126*blk[...,0] + 0.7152*blk[...,1] + 0.0722*blk[...,2]
            if float(luma.max() - luma.min()) >= luma_thresh:
                edge[y,x] = True; continue
            if float(np.max(blk.max(axis=(0,1)) - blk.min(axis=(0,1)))) >= chroma_thresh:
                edge[y,x] = True; continue
            mx = blk.max(axis=-1); mn = blk.min(axis=-1)
            sat = (mx - mn) / np.maximum(mx, 1.0)
            if float(sat.max()) >= sat_thresh:
                hue = _edgeaa_hue_deg(blk)
                hs = hue[sat >= sat_thresh]
                if hs.size >= 2:
                    # Circular hue range approximation.
                    hs = np.sort(hs)
                    gaps = np.diff(np.r_[hs, hs[0]+360])
                    circ_range = 360 - float(gaps.max())
                    if circ_range >= hue_thresh:
                        edge[y,x] = True
    return edge

def _edgeaa_build_offsets(arr: np.ndarray, coarse_rgb: np.ndarray, edge_blocks_top: np.ndarray,
                          scale: int = 4) -> Tuple[np.ndarray, np.ndarray, Dict[str, float]]:
    """Build top-origin subcell boundary offsets for 4x edge-AA.

    Offsets are 0/0.1/0.2/0.3/0.4 mm and are later converted to bottom-origin.
    Positive offset moves the boundary into the next/right or next/up coarse cell.
    """
    h, w = arr.shape[:2]
    ny, nx = coarse_rgb.shape[:2]
    arr = arr[:ny*scale, :nx*scale, :].astype(np.float32)

    xoff = np.zeros((ny, nx+1), dtype=np.float32)
    yoff = np.zeros((ny+1, nx), dtype=np.float32)
    triggered_x = 0
    triggered_y = 0

    def leading_like_left(left_rgb, right_cols):
        left = np.asarray(left_rgb, dtype=np.float32)
        right_mean = np.asarray(right_cols.mean(axis=(0,1)), dtype=np.float32)
        k = 0
        for c in range(scale):
            col = right_cols[:, c, :].mean(axis=0)
            if np.linalg.norm(col-left) <= np.linalg.norm(col-right_mean):
                k += 1
            else:
                break
        return k

    def leading_like_top(top_rgb, lower_rows):
        top = np.asarray(top_rgb, dtype=np.float32)
        lower_mean = np.asarray(lower_rows.mean(axis=(0,1)), dtype=np.float32)
        k = 0
        for r in range(scale):
            row = lower_rows[r, :, :].mean(axis=0)
            if np.linalg.norm(row-top) <= np.linalg.norm(row-lower_mean):
                k += 1
            else:
                break
        return k

    for y in range(ny):
        for b in range(1, nx):
            if not (edge_blocks_top[y, b-1] or edge_blocks_top[y, b]):
                continue
            left_rgb = coarse_rgb[y, b-1]
            right_blk = arr[y*scale:(y+1)*scale, b*scale:(b+1)*scale, :]
            k = leading_like_left(left_rgb, right_blk)
            if k:
                xoff[y, b] = min(scale, max(0, k)) * (RUNTIME_PRINT_WIDTH_MM / scale)
                triggered_x += 1

    for b in range(1, ny):
        for x in range(nx):
            if not (edge_blocks_top[b-1, x] or edge_blocks_top[b, x]):
                continue
            top_rgb = coarse_rgb[b-1, x]
            lower_blk = arr[b*scale:(b+1)*scale, x*scale:(x+1)*scale, :]
            k = leading_like_top(top_rgb, lower_blk)
            if k:
                yoff[b, x] = min(scale, max(0, k)) * (RUNTIME_PRINT_WIDTH_MM / scale)
                triggered_y += 1

    report = {
        "edgeaa_blocks": float(np.count_nonzero(edge_blocks_top)),
        "edgeaa_blocks_fraction": float(np.count_nonzero(edge_blocks_top) / max(1, edge_blocks_top.size)),
        "edgeaa_x_boundaries": float(triggered_x),
        "edgeaa_y_boundaries": float(triggered_y),
    }
    # FC3D_FIX43_INTERNAL_ONLY_EDGEAA: only emit internal AA shifts.
    try:
        if isinstance(x_offsets, np.ndarray):
            x_offsets[x_offsets <= 0] = 0
            x_offsets[x_offsets >= scale] = 0
            _mask = x_offsets > 0
            x_offsets[_mask] = np.clip(x_offsets[_mask], 1, scale - 1)
        if isinstance(y_offsets, np.ndarray):
            y_offsets[y_offsets <= 0] = 0
            y_offsets[y_offsets >= scale] = 0
            _mask = y_offsets > 0
            y_offsets[_mask] = np.clip(y_offsets[_mask], 1, scale - 1)
    except NameError:
        pass
    return xoff, yoff, report
def build_lut_cell_plan(img: Image.Image, lookup: RecipeLookup, error_diffusion: str = "none", noise_strength: float = 3.0, seed: int = 42,
                        candidate_count: int = 1, candidate_rgb_slack: float = 2.5, candidate_neighbour_weight: float = 0.25,
                        source_scale: int = None, edge_aa: str = "off", edge_luma_thresh: float = 28.0,
                        edge_chroma_thresh: float = 34.0, edge_hue_thresh: float = 25.0,
                        boundary_aa_structure_weight: str = "on",
                        boundary_aa_detail_threshold: float = 8.0,
                        boundary_aa_detail_full: float = 28.0,
                        boundary_aa_min_weight: float = 0.15,
                        boundary_aa_cost: float = 250.0,
                        boundary_aa_cost_per_rp: float = 0.0):
    """Build the current PPSP stack-LUT plan.

    PPSPV34 removed the obsolete legacy literal-LUT planner.  The active path is
    recipegenv64 stack LUT -> build_stack_lut_cell_plan().
    """
    if not getattr(lookup, "is_stack_lut", False):
        raise RuntimeError("PPSPV34 requires a recipegenv64 stack LUT; legacy literal/demand LUT planners were removed.")
    return build_stack_lut_cell_plan(
        img, lookup,
        source_scale=int(source_scale if source_scale is not None else RUNTIME_PIXEL_HEAD_WIDTH),
        max_physical_slots=int(globals().get("RUNTIME_MAX_PHYSICAL_SLOTS", MIX_LAYERS)),
    )






def _sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def _canonical_json_bytes(value: object) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode("utf-8")


def _provenance_path_record(path: Optional[Path], bundle_parent: Path) -> Optional[Dict[str, object]]:
    if path is None:
        return None
    p = Path(path)
    if not p.exists() or not p.is_file():
        raise RuntimeError(f"provenance artifact does not exist: {p}")
    try:
        stored_path = os.path.relpath(str(p.resolve()), str(bundle_parent.resolve()))
    except Exception:
        stored_path = str(p)
    return {
        "path": stored_path,
        "sha256": _sha256_file(p),
        "size_bytes": int(p.stat().st_size),
    }


def _prepare_print_provenance(args: argparse.Namespace) -> Dict[str, object]:
    """Validate bundle inputs and create an immutable deterministic print id."""
    if getattr(args, "print_bundle_out", None) is None:
        return {}
    card_mode = getattr(args, "card", None) is not None
    required = {
        "tile manifest": getattr(args, "tile_manifest_in", None),
        "card summary": getattr(args, "card_summary_in", None),
        "layer manifest output": getattr(args, "layer_manifest_out", None),
        "printed tile recipes output": getattr(args, "printed_tile_recipes_out", None),
        "resolved config output": getattr(args, "resolved_config_out", None),
        "G-code 3MF output": getattr(args, "output", None),
    }
    if card_mode:
        required.update({
            "card JSON": getattr(args, "_card_json_path", None),
            "card layer manifest": getattr(args, "_card_layer_manifest_path", None),
            "card layer sheet": getattr(args, "_card_layer_sheet_path", None),
            "card source manifest": getattr(args, "_card_source_manifest_path", None),
        })
    else:
        required.update({
            "source image": getattr(args, "image", None),
            "recipe LUT": getattr(args, "recipe_lut", None),
        })
    missing = [name for name, value in required.items() if value is None]
    if missing:
        raise RuntimeError("--print-bundle-out requires: " + ", ".join(missing))
    if bool(getattr(args, "preview_only", False)):
        raise RuntimeError("--print-bundle-out cannot be used with --preview-only")
    input_paths = {
        "script": Path(__file__),
        "tile_manifest": Path(args.tile_manifest_in),
        "card_summary": Path(args.card_summary_in),
    }
    if card_mode:
        input_paths.update({
            "card_json": Path(args._card_json_path),
            "card_layer_manifest": Path(args._card_layer_manifest_path),
            "card_layer_sheet": Path(args._card_layer_sheet_path),
            "card_source_manifest": Path(args._card_source_manifest_path),
        })
    else:
        input_paths.update({
            "source_image": Path(args.image),
            "recipe_lut": Path(args.recipe_lut),
        })
    if getattr(args, "calibration_holdout_printed_tile_recipes", None) is not None:
        input_paths["calibration_holdout_printed_tile_recipes"] = Path(args.calibration_holdout_printed_tile_recipes)
    if getattr(args, "calibration_continuity_extracted_tiles", None) is not None:
        input_paths["calibration_continuity_extracted_tiles"] = Path(args.calibration_continuity_extracted_tiles)
    for label, path in input_paths.items():
        if not path.exists() or not path.is_file():
            raise RuntimeError(f"provenance {label} does not exist: {path}")
    input_hashes = {key: _sha256_file(path) for key, path in input_paths.items()}
    identity_args = {
        key: (str(value) if isinstance(value, Path) else value)
        for key, value in sorted(vars(args).items())
        if key not in {"print_bundle_out"}
    }
    seed = {
        "schema": "fc3d_print_run_identity_v1",
        "script_version": SCRIPT_VERSION,
        "input_hashes": input_hashes,
        "resolved_arguments": identity_args,
    }
    identity_sha = hashlib.sha256(_canonical_json_bytes(seed)).hexdigest()
    return {
        "schema": "fc3d_print_provenance_context_v1",
        "print_run_id": f"fc3d-{identity_sha[:24]}",
        "identity_sha256": identity_sha,
        "input_hashes": input_hashes,
    }


def _printed_token(material: object, dose: float, *, model_policy: bool) -> str:
    mat = str(material).strip().upper()
    if mat in ("", EMPTY_MAT, ".", "NONE") or float(dose) <= 0.0:
        return "."
    pct = int(round(float(dose) * 100.0))
    # v1.57: raw and model identities both preserve the actual emitted dose.
    # Historical W100/60..100 relabelling made sub-60% roads appear to be a
    # different physical recipe and could silently defeat exact replay.
    return f"{mat}{pct}"


def write_printed_tile_recipes(
    path: Path,
    tile_manifest_path: Path,
    stack: np.ndarray,
    dose: Optional[np.ndarray],
    print_run_id: str,
) -> Dict[str, object]:
    """Write one compact row per physical card tile from the final emission grid."""
    path = Path(path)
    manifest_path = Path(tile_manifest_path)
    with manifest_path.open("r", newline="", encoding="utf-8-sig") as f:
        manifest_rows = list(csv.DictReader(f))
    if not manifest_rows:
        raise RuntimeError(f"tile manifest contains no rows: {manifest_path}")
    h, w, layers = stack.shape
    dose_arr = None if dose is None else np.asarray(dose, dtype=np.float32)
    if dose_arr is not None and dose_arr.shape != stack.shape:
        raise RuntimeError(f"dose grid shape {dose_arr.shape} does not match stack shape {stack.shape}")
    out_rows: List[Dict[str, object]] = []
    recipe_pairs: List[Tuple[str, str]] = []
    seen_recipe_keys = set()
    selected_exact_tiles = 0
    holdout_tiles = 0
    continuity_retained_tiles = 0
    continuity_applied_tiles = 0
    for mr in manifest_rows:
        role = str(mr.get("role", "")).strip()
        key = str(mr.get("print_key", "")).strip()
        gx0 = int(round(float(mr.get("x0_px", 0))))
        gy0 = int(round(float(mr.get("y0_px", 0))))
        gx1 = int(round(float(mr.get("x1_excl", int(float(mr.get("x1_px", gx0))) + 1))))
        gy1 = int(round(float(mr.get("y1_excl", int(float(mr.get("y1_px", gy0))) + 1))))
        cx = (gx0 + gx1 - 1) // 2
        cy_top = (gy0 + gy1 - 1) // 2
        cy_model = h - 1 - cy_top
        if not (0 <= cx < w and 0 <= cy_model < h):
            raise RuntimeError(f"tile manifest rectangle is outside final emission grid: key={key!r} centre=({cx},{cy_top}) grid={w}x{h}")
        raw_tokens: List[str] = []
        model_tokens: List[str] = []
        for li in range(layers):
            d = 1.0 if dose_arr is None else float(dose_arr[cy_model, cx, li])
            raw_tokens.append(_printed_token(stack[cy_model, cx, li], d, model_policy=False))
            model_tokens.append(_printed_token(stack[cy_model, cx, li], d, model_policy=True))
        raw_recipe = "|".join(raw_tokens)
        model_recipe = "|".join(model_tokens)
        source_scale = max(1, int(globals().get("RUNTIME_PIXEL_HEAD_WIDTH", 1)))
        ap_x, ap_y = cx // source_scale, cy_top // source_scale
        recipe_index = ""
        target_grid_index = ""
        pred_rgb: List[object] = ["", "", ""]
        pred_lab: List[object] = ["", "", ""]
        is_exact: object = ""
        parent_index: object = ""
        total_ve: object = ""
        is_holdout = False
        is_continuity_retained = False
        is_continuity_applied = False
        continuity_measured_de: object = ""
        lookup = globals().get("RECIPE_LOOKUP", None)
        recipe_grid = globals().get("PRECOMPUTED_CELL_RECIPE_INDEX", None)
        target_grid = globals().get("PRECOMPUTED_CELL_GRID_INDEX", None)
        holdout_grid = globals().get("PRECOMPUTED_CELL_HOLDOUT", None)
        continuity_grid = globals().get("PRECOMPUTED_CELL_CONTINUITY", None)
        continuity_applied_grid = globals().get("PRECOMPUTED_CELL_CONTINUITY_APPLIED", None)
        continuity_measured_grid = globals().get("PRECOMPUTED_CELL_CONTINUITY_MEASURED_DE", None)
        if lookup is not None and recipe_grid is not None and 0 <= ap_y < recipe_grid.shape[0] and 0 <= ap_x < recipe_grid.shape[1]:
            recipe_index = int(recipe_grid[ap_y, ap_x])
            target_grid_index = int(target_grid[ap_y, ap_x]) if target_grid is not None else ""
            pred_rgb = [float(x) for x in np.asarray(lookup.recipe_pred_rgb[recipe_index], dtype=np.float32)]
            pred_lab = [float(x) for x in np.asarray(lookup.recipe_pred_lab[recipe_index], dtype=np.float32)]
            is_exact = int(np.asarray(lookup.cloud_is_exact_measured, dtype=np.uint8)[recipe_index] > 0)
            if is_exact:
                parent_index = int(np.asarray(lookup.cloud_exact_measured_index, dtype=np.int64)[recipe_index])
                total_ve = 0.0
            elif target_grid_index != "" and getattr(lookup, "multi_recipe_index", None) is not None:
                bucket = np.asarray(lookup.multi_recipe_index[target_grid_index], dtype=np.int64)
                pos = np.flatnonzero(bucket == recipe_index)
                if len(pos) == 1:
                    k = int(pos[0])
                    if getattr(lookup, "multi_recipe_parent_history_index", None) is not None:
                        parent_index = int(lookup.multi_recipe_parent_history_index[target_grid_index, k])
                    if getattr(lookup, "multi_recipe_total_ve_movement", None) is not None:
                        total_ve = float(lookup.multi_recipe_total_ve_movement[target_grid_index, k])
            is_holdout = bool(holdout_grid is not None and holdout_grid[ap_y, ap_x])
            is_continuity_retained = bool(continuity_grid is not None and continuity_grid[ap_y, ap_x])
            is_continuity_applied = bool(continuity_applied_grid is not None and continuity_applied_grid[ap_y, ap_x])
            if continuity_measured_grid is not None and np.isfinite(continuity_measured_grid[ap_y, ap_x]):
                continuity_measured_de = float(continuity_measured_grid[ap_y, ap_x])
            expected_mats, expected_doses = lookup.recipe_stack_for_recipe_index(recipe_index)
            expected_recipe = "|".join(_printed_token(m, float(d), model_policy=True) for m, d in zip(expected_mats, expected_doses))
            if expected_recipe != model_recipe:
                raise RuntimeError(f"selected recipe index disagrees with final emitted recipe for tile {key!r}: selected={expected_recipe} emitted={model_recipe}")
        if role == "recipe":
            if not key:
                raise RuntimeError("recipe tile has a blank print_key")
            if key in seen_recipe_keys:
                raise RuntimeError(f"duplicate recipe tile print_key: {key}")
            seen_recipe_keys.add(key)
            recipe_pairs.append((key, model_recipe))
        out_rows.append({
            "schema_version": "fc3d_printed_tile_recipes_v3",
            "script_version": SCRIPT_VERSION,
            "print_run_id": print_run_id,
            "role": role,
            "section": str(mr.get("section", "")),
            "item_index": str(mr.get("item_index", "")),
            "grid_col": str(mr.get("grid_col", "")),
            "grid_row": str(mr.get("grid_row", "")),
            "print_key": key,
            "optical_key": str(mr.get("optical_key", "")),
            "x0_px": gx0,
            "y0_px": gy0,
            "x1_excl": gx1,
            "y1_excl": gy1,
            "centre_x_px": cx,
            "centre_y_px": cy_top,
            "actual_recipe_raw_bottom_to_top": raw_recipe,
            "actual_recipe_model_bottom_to_top": model_recipe,
            "selected_recipe_index": recipe_index,
            "selected_target_grid_index": target_grid_index,
            "selected_predicted_rgb_R": pred_rgb[0],
            "selected_predicted_rgb_G": pred_rgb[1],
            "selected_predicted_rgb_B": pred_rgb[2],
            "selected_predicted_lab_L": pred_lab[0],
            "selected_predicted_lab_a": pred_lab[1],
            "selected_predicted_lab_b": pred_lab[2],
            "selected_is_exact_history": is_exact,
            "selected_parent_history_index": parent_index,
            "selected_total_ve_movement": total_ve,
            "calibration_holdout": int(is_holdout),
            "calibration_continuity_retained_previous": int(is_continuity_retained),
            "calibration_continuity_applied": int(is_continuity_applied),
            "calibration_continuity_measured_delta_e76": continuity_measured_de,
        })
        if role == "recipe":
            selected_exact_tiles += int(is_exact == 1)
            holdout_tiles += int(is_holdout)
            continuity_retained_tiles += int(is_continuity_retained)
            continuity_applied_tiles += int(is_continuity_applied)
    if len(recipe_pairs) != 3427:
        raise RuntimeError(f"expected exactly 3427 recipe tiles, found {len(recipe_pairs)}")
    recipe_pairs.sort()
    recipe_map_sha = hashlib.sha256(
        "".join(f"{key}\t{recipe}\n" for key, recipe in recipe_pairs).encode("utf-8")
    ).hexdigest()
    fields = list(out_rows[0].keys())
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        writer.writerows(out_rows)
    print(
        f"Wrote printed tile recipe map: {path} recipe_tiles={len(recipe_pairs):,} "
        f"exact_history={selected_exact_tiles:,} continuity_retained={continuity_retained_tiles:,} "
        f"continuity_applied={continuity_applied_tiles:,} holdout={holdout_tiles:,}",
        flush=True,
    )
    return {
        "recipe_tile_count": len(recipe_pairs),
        "all_tile_count": len(out_rows),
        "tile_recipe_map_sha256": recipe_map_sha,
        "selected_exact_history_tiles": selected_exact_tiles,
        "selected_exact_history_pct": 100.0 * selected_exact_tiles / len(recipe_pairs),
        "holdout_tiles": holdout_tiles,
        "organic_exact_history_tiles": selected_exact_tiles - holdout_tiles,
        "continuity_retained_tiles": continuity_retained_tiles,
        "continuity_applied_tiles": continuity_applied_tiles,
    }


def write_print_bundle(args: argparse.Namespace, printed_map_info: Dict[str, object]) -> None:
    bundle_path = getattr(args, "print_bundle_out", None)
    if bundle_path is None:
        return
    bundle_path = Path(bundle_path)
    parent = bundle_path.parent
    provenance = dict(globals().get("PRINT_PROVENANCE_CONTEXT", {}) or {})
    layer_manifest = json.loads(Path(args.layer_manifest_out).read_text(encoding="utf-8"))
    sheet_path = Path(layer_manifest["layer_sheet_4x2"]["path"])
    card_mode = getattr(args, "card", None) is not None
    artifacts = {
        "script": _provenance_path_record(Path(__file__), parent),
        "tile_manifest": _provenance_path_record(Path(args.tile_manifest_in), parent),
        "card_summary": _provenance_path_record(Path(args.card_summary_in), parent),
        "resolved_config": _provenance_path_record(Path(args.resolved_config_out), parent),
        "layer_manifest": _provenance_path_record(Path(args.layer_manifest_out), parent),
        "layer_sheet": _provenance_path_record(sheet_path, parent),
        "printed_tile_recipes": _provenance_path_record(Path(args.printed_tile_recipes_out), parent),
        "calibration_manifest": _provenance_path_record(getattr(args, "calibration_manifest_out", None), parent),
        "preview_image": _provenance_path_record(getattr(args, "preview_image_out", None), parent),
        "gcode_3mf": _provenance_path_record(getattr(args, "output", None), parent),
        "embedded_gcode_parser_audit": _provenance_path_record(globals().get("REFERENCE_GCODE_REMAP_AUDIT_PATH"), parent),
        "calibration_holdout_source": _provenance_path_record(getattr(args, "calibration_holdout_printed_tile_recipes", None), parent),
        "calibration_continuity_source": _provenance_path_record(getattr(args, "calibration_continuity_extracted_tiles", None), parent),
    }
    if card_mode:
        artifacts.update({
            "card_json": _provenance_path_record(Path(args._card_json_path), parent),
            "card_source_manifest": _provenance_path_record(Path(args._card_source_manifest_path), parent),
            "source_layer_manifest": _provenance_path_record(Path(args._card_layer_manifest_path), parent),
            "source_layer_sheet": _provenance_path_record(Path(args._card_layer_sheet_path), parent),
        })
    else:
        artifacts.update({
            "source_image": _provenance_path_record(Path(args.image), parent),
            "recipe_lut": _provenance_path_record(Path(args.recipe_lut), parent),
        })
    payload = {
        "schema_version": "fc3d_print_bundle_v1",
        "script_version": SCRIPT_VERSION,
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "print_run_id": provenance.get("print_run_id"),
        "print_identity_sha256": provenance.get("identity_sha256"),
        "layer_order": "bottom_to_top",
        "layer_sheet_layout": [[1, 2, 3, 4], [5, 6, 7, 8]],
        "recipe_tile_count": int(printed_map_info.get("recipe_tile_count", 0)),
        "all_tile_count": int(printed_map_info.get("all_tile_count", 0)),
        "tile_recipe_map_sha256": printed_map_info.get("tile_recipe_map_sha256"),
        "selected_exact_history_tiles": int(printed_map_info.get("selected_exact_history_tiles", 0)),
        "organic_exact_history_tiles": int(printed_map_info.get("organic_exact_history_tiles", 0)),
        "holdout_tiles": int(printed_map_info.get("holdout_tiles", 0)),
        "continuity_retained_tiles": int(printed_map_info.get("continuity_retained_tiles", 0)),
        "continuity_applied_tiles": int(printed_map_info.get("continuity_applied_tiles", 0)),
        "artifacts": {k: v for k, v in artifacts.items() if v is not None},
        "command_line": list(sys.argv),
        "policy": {
            "authoritative_recipe_source": "printed_tile_recipes generated from final emitted stack/dose grid",
            "bundle_self_hash": "computed by consumers; the bundle cannot contain its own hash",
        },
    }
    bundle_path.parent.mkdir(parents=True, exist_ok=True)
    bundle_path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(f"Wrote print provenance bundle: {bundle_path}", flush=True)


def audit_direct_card_emission(source_manifest_path: Path, printed_tiles_path: Path) -> None:
    """Fail unless every immutable card recipe equals the final emitted stack."""
    def norm(recipe: str) -> Tuple[str, ...]:
        out: List[str] = []
        for raw in re.split(r"[|,\s]+", str(recipe).strip()):
            tok = raw.strip().upper()
            if not tok or tok in {".", "EMPTY", "NONE"}:
                continue
            m = re.fullmatch(r"([WRYGCBF])(\d+)", tok)
            if not m:
                raise RuntimeError(f"invalid card recipe token {raw!r}")
            out.append(f"{m.group(1)}{int(m.group(2))}")
        return tuple(out)

    with Path(source_manifest_path).open("r", newline="", encoding="utf-8-sig") as f:
        expected_rows = list(csv.DictReader(f))
    with Path(printed_tiles_path).open("r", newline="", encoding="utf-8-sig") as f:
        actual_rows = list(csv.DictReader(f))
    expected = {
        str(r.get("print_key", "")).strip(): norm(r.get("recipe_stack_bottom_to_top", ""))
        for r in expected_rows if str(r.get("print_key", "")).strip()
    }
    actual = {
        str(r.get("print_key", "")).strip(): norm(r.get("actual_recipe_model_bottom_to_top", ""))
        for r in actual_rows if str(r.get("role", "")).strip() == "recipe"
    }
    if len(expected) != 3427 or len(actual) != 3427:
        raise RuntimeError(
            f"direct-card emission audit requires 3427 immutable recipes; expected={len(expected)} actual={len(actual)}"
        )
    if expected.keys() != actual.keys():
        missing = sorted(expected.keys() - actual.keys())[:5]
        extra = sorted(actual.keys() - expected.keys())[:5]
        raise RuntimeError(f"direct-card print_key mismatch; missing={missing} extra={extra}")
    mismatches = [key for key in expected if expected[key] != actual[key]]
    if mismatches:
        key = mismatches[0]
        raise RuntimeError(
            f"direct-card emitted recipe mismatch ({len(mismatches)} tiles); first={key!r} "
            f"expected={expected[key]} actual={actual[key]}"
        )
    print("Direct-card emission audit: PASS recipes=3,427 exact_stack_match=100.000%", flush=True)






MATERIAL_DEBUG_RGB = {
    ".": (0, 0, 0),
    "W": (245, 245, 245),
    "F": (255, 160, 40),
    "R": (230, 40, 40),
    "Y": (235, 220, 40),
    "G": (50, 190, 70),
    "C": (40, 200, 220),
    "B": (50, 80, 230),
}


def save_rp_stack_layer_images(
    rp_stack_model: Optional[np.ndarray],
    output_prefix: Optional[Path],
    stage: str = "",
    dose_grid: Optional[np.ndarray] = None,
) -> None:
    """Save one combined 4x2 layer-sheet PNG from bottom-origin RP stack.

    v1.32 policy:
      - Do not emit eight separate layer PNGs.
      - Emit one high-resolution combined sheet laid out as:
            1, 2, 3, 4
            5, 6, 7, 8
        where layer 1 is the bottom optical layer and layer 8 is the top.
      - When dose_grid is supplied, save RGBA where RGB encodes material using
        MATERIAL_DEBUG_RGB and alpha encodes dose (alpha 128 = 100% dose).
      - Without dose_grid, write legacy RGB material-only content.

    This reduces file count while preserving an unambiguous canonical layer
    ordering for both human inspection and direct-layer reconstruction.
    """
    if output_prefix is None or rp_stack_model is None:
        return
    prefix = Path(output_prefix)
    prefix.parent.mkdir(parents=True, exist_ok=True)
    h, w, layers = rp_stack_model.shape
    stack_top = rp_stack_model[::-1, :, :]
    dose_top = None
    if dose_grid is not None:
        dose_arr = np.asarray(dose_grid, dtype=np.float32)
        if dose_arr.shape == rp_stack_model.shape:
            dose_top = dose_arr[::-1, :, :]
        else:
            print(
                f"WARNING: dose grid shape {dose_arr.shape} does not match stack shape {rp_stack_model.shape}; "
                "writing material-only RGB layer sheet",
                flush=True,
            )
    stage_part = f"_{stage}" if stage else ""
    use_rgba = (dose_top is not None)
    layer_arrays = []
    for li in range(layers):
        if use_rgba:
            out = np.zeros((h, w, 4), dtype=np.uint8)
        else:
            out = np.zeros((h, w, 3), dtype=np.uint8)
        layer = stack_top[:, :, li]
        for sym, rgb in MATERIAL_DEBUG_RGB.items():
            mask = (layer == sym)
            if np.any(mask):
                out[mask, :3] = rgb
        if use_rgba:
            active = (layer != EMPTY_MAT) & (dose_top[:, :, li] > 0)
            alpha = np.zeros((h, w), dtype=np.uint8)
            if np.any(active):
                alpha_vals = np.clip(np.rint(dose_top[:, :, li] * 128.0), 1, 255).astype(np.uint8)
                alpha[active] = alpha_vals[active]
            out[:, :, 3] = alpha
        layer_arrays.append(out)

    cols = 4
    rows = 2
    if use_rgba:
        sheet = np.zeros((rows * h, cols * w, 4), dtype=np.uint8)
    else:
        sheet = np.zeros((rows * h, cols * w, 3), dtype=np.uint8)
    for li, arr in enumerate(layer_arrays):
        r = li // cols
        c = li % cols
        y0 = r * h
        x0 = c * w
        sheet[y0:y0 + h, x0:x0 + w, ...] = arr

    sheet_name = prefix.with_name(f"{prefix.name}{stage_part}_layers_4x2_sheet.png")
    Image.fromarray(sheet, "RGBA" if use_rgba else "RGB").save(sheet_name)
    enc = "RGBA material+dose" if use_rgba else "RGB material-only"
    print(f"Wrote RP stack combined layer sheet ({enc}): {sheet_name}", flush=True)


def print_lut_stack_rgb_diagnostic(lookup: Optional["RecipeLookup"], sample_count: int = 12) -> None:
    """Print stored LUT RGB vs reconstructed stack RGB for representative recipes.

    This checks whether the live boundary-AA optical reconstruction is operating
    in the same colour space/model as the LUT selector.
    """
    if lookup is None:
        print("LUT_STACK_RGB_DIAGNOSTIC: skipped; no recipe lookup loaded", flush=True)
        return
    n = len(lookup.recipes)
    if n <= 0:
        print("LUT_STACK_RGB_DIAGNOSTIC: skipped; empty lookup", flush=True)
        return

    # Deterministic representative samples:
    # - first/middle/last
    # - near max/min/light/dark/chroma when rgb is avairgble
    idxs = []
    def add(i):
        i = int(max(0, min(n - 1, i)))
        if i not in idxs:
            idxs.append(i)

    add(0); add(n // 2); add(n - 1)

    try:
        rgb = np.asarray(lookup.rgb, dtype=np.float32)
        lum = 0.2126*rgb[:, 0] + 0.7152*rgb[:, 1] + 0.0722*rgb[:, 2]
        chroma = np.max(rgb, axis=1) - np.min(rgb, axis=1)
        add(int(np.argmax(lum)))
        add(int(np.argmin(lum)))
        add(int(np.argmax(chroma)))
        add(int(np.argmax(rgb[:, 0])))
        add(int(np.argmax(rgb[:, 1])))
        add(int(np.argmax(rgb[:, 2])))
        add(int(np.argmin(rgb[:, 0])))
        add(int(np.argmin(rgb[:, 1])))
        add(int(np.argmin(rgb[:, 2])))
    except Exception as e:
        print(f"LUT_STACK_RGB_DIAGNOSTIC: warning: could not choose RGB-derived samples: {e}", flush=True)

    # Fill remaining with evenly spaced indices.
    if len(idxs) < sample_count:
        for i in np.linspace(0, n - 1, sample_count, dtype=np.int64):
            add(int(i))
            if len(idxs) >= sample_count:
                break

    print("LUT_STACK_RGB_DIAGNOSTIC_BEGIN", flush=True)
    print(f"LUT_STACK_RGB_DIAGNOSTIC lookup={lookup.path} recipes={n} samples={len(idxs)}", flush=True)
    max_abs = 0.0
    mean_abs_acc = 0.0
    rows = 0
    for i in idxs[:sample_count]:
        recipe = str(lookup.recipes[i])
        stored = np.asarray(lookup.rgb[i], dtype=np.float32)
        recon = _predict_stack_rgb_from_symbols(tuple(recipe), lookup)
        diff = recon - stored
        absdiff = np.abs(diff)
        max_abs = max(max_abs, float(np.max(absdiff)))
        mean_abs_acc += float(np.mean(absdiff))
        rows += 1
        print(
            "LUT_STACK_RGB_DIAGNOSTIC "
            f"idx={i} recipe={recipe} "
            f"stored=[{stored[0]:.3f},{stored[1]:.3f},{stored[2]:.3f}] "
            f"recon=[{recon[0]:.3f},{recon[1]:.3f},{recon[2]:.3f}] "
            f"diff=[{diff[0]:+.3f},{diff[1]:+.3f},{diff[2]:+.3f}] "
            f"absmax={float(np.max(absdiff)):.3f}",
            flush=True,
        )
    print(
        f"LUT_STACK_RGB_DIAGNOSTIC_SUMMARY samples={rows} "
        f"mean_abs_channel_diff={mean_abs_acc/max(1, rows):.3f} "
        f"max_abs_channel_diff={max_abs:.3f}",
        flush=True,
    )
    print("LUT_STACK_RGB_DIAGNOSTIC_END", flush=True)



def _debug_base_path(args) -> Optional[Path]:
    """Choose a base path for --debug-package outputs."""
    base = None
    if getattr(args, "output", None) is not None:
        p = Path(args.output)
        name = p.name
        if name.endswith(".gcode.3mf"):
            name = name[:-len(".gcode.3mf")]
        else:
            name = p.stem
        base = p.with_name(name)
    elif getattr(args, "preview_image_out", None) is not None:
        p = Path(args.preview_image_out)
        name = p.stem
        for suf in ("_preview", "_postaa", "_final"):
            if name.endswith(suf):
                name = name[:-len(suf)]
        base = p.with_name(name)
    elif getattr(args, "image", None) is not None:
        p = Path(args.image)
        base = Path.cwd() / p.stem
    return base



def _compare_preview_report(name: str, reconstructed_top: Optional[np.ndarray], expected_top: Optional[np.ndarray]) -> Dict[str, float]:
    """Non-raising preview comparison for debug packages."""
    if reconstructed_top is None or expected_top is None:
        return {"checked": 0.0, "passed": 0.0}
    a = _to_uint8_rgb(reconstructed_top)
    b = _to_uint8_rgb(expected_top)
    if a.shape != b.shape:
        return {
            "checked": 1.0,
            "passed": 0.0,
            "shape_mismatch": 1.0,
            "reconstructed_shape": list(a.shape),
            "expected_shape": list(b.shape),
        }
    diff = a.astype(np.int16) - b.astype(np.int16)
    absdiff = np.abs(diff)
    changed = np.any(absdiff != 0, axis=2)
    report = {
        "checked": 1.0,
        "passed": float(not np.any(changed)),
        "mean_abs_diff": float(absdiff.mean()),
        "max_abs_diff": float(absdiff.max()),
        "changed_pixels": float(changed.sum()),
        "total_pixels": float(changed.size),
    }
    if np.any(changed):
        yy, xx = np.argwhere(changed)[0]
        report.update({
            "first_changed_x": int(xx),
            "first_changed_y": int(yy),
            "first_reconstructed_rgb": a[yy, xx, :].tolist(),
            "first_expected_rgb": b[yy, xx, :].tolist(),
            "first_diff_rgb": diff[yy, xx, :].tolist(),
        })
        print(
            f"{name.upper()} RGB SELF-CHECK: FAIL changed_pixels={int(report['changed_pixels'])} "
            f"max_abs_diff={int(report['max_abs_diff'])} mean_abs_diff={report['mean_abs_diff']:.6f}",
            flush=True,
        )
    else:
        print(
            f"{name.upper()} RGB SELF-CHECK: PASS changed_pixels=0 "
            f"max_abs_diff={int(report['max_abs_diff'])} mean_abs_diff={report['mean_abs_diff']:.6f}",
            flush=True,
        )
    return report


def save_rp_stack_npz_debug(preaa_stack_model: Optional[np.ndarray], postaa_stack_model: Optional[np.ndarray],
                            output_path: Path, lookup: Optional["RecipeLookup"],
                            preaa_preview_top: Optional[np.ndarray],
                            postaa_preview_top: Optional[np.ndarray],
                            checks: Dict[str, Dict[str, float]]) -> None:
    """Save debug NPZ without raising on RGB self-check mismatch."""
    output_path = Path(output_path)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "material_order": np.array(list(MATERIAL_SYMBOL_ORDER), dtype="<U1"),
        "material_ids_json": np.array(json.dumps(MATERIAL_SYMBOL_TO_ID, sort_keys=True)),
        "orientation_json": np.array(json.dumps({
            "stack_arrays": "model/bottom-origin y, x left-to-right, physical layers bottom-to-top",
            "preview_arrays": "top-oriented image y, x, RGB",
            "rgb_reconstruction": "_preview_top_from_rp_stack -> _rgb_map_from_rp_materials -> reverse Y",
            "pp_version": PP_VERSION,
            "debug_package": True,
        }, sort_keys=True)),
    }
    if preaa_preview_top is not None:
        payload["preaa_preview_rgb_float"] = np.asarray(preaa_preview_top, dtype=np.float32)
    if postaa_preview_top is not None:
        payload["postaa_preview_rgb_float"] = np.asarray(postaa_preview_top, dtype=np.float32)
    if preaa_stack_model is not None:
        payload["preaa_stack_ids"] = _rp_stack_symbols_to_ids(preaa_stack_model)
        payload["preaa_reconstructed_preview_rgb"] = _preview_top_from_rp_stack(preaa_stack_model, lookup)
        payload["preaa_selfcheck_json"] = np.array(json.dumps(checks.get("preaa", {"checked": 0.0}), sort_keys=True))
    if postaa_stack_model is not None:
        payload["postaa_stack_ids"] = _rp_stack_symbols_to_ids(postaa_stack_model)
        payload["postaa_reconstructed_preview_rgb"] = _preview_top_from_rp_stack(postaa_stack_model, lookup)
        payload["postaa_selfcheck_json"] = np.array(json.dumps(checks.get("postaa", {"checked": 0.0}), sort_keys=True))
    np.savez_compressed(output_path, **payload)
    print(f"Wrote debug exact RP stack NPZ: {output_path}", flush=True)



def save_full_debug_package(args, source_img: Image.Image, lookup: Optional["RecipeLookup"],
                            preaa_stack_model: Optional[np.ndarray],
                            postaa_stack_model: Optional[np.ndarray],
                            preaa_preview_top: Optional[np.ndarray],
                            postaa_preview_top: Optional[np.ndarray]) -> None:
    """Write the full pp debug package when --debug-package is set."""
    if not getattr(args, "debug_package", False):
        return
    base = _debug_base_path(args)
    if base is None:
        print("Debug package skipped: could not derive output base path", flush=True)
        return
    base = Path(base)
    base.parent.mkdir(parents=True, exist_ok=True)

    source_path = base.with_name(base.name + "_debug_source.png")
    source_img.save(source_path)
    print(f"Wrote debug source image: {source_path}", flush=True)

    if preaa_preview_top is not None:
        p = base.with_name(base.name + "_debug_preaa_mapped_preview.png")
        Image.fromarray(_to_uint8_rgb(preaa_preview_top), "RGB").save(p)
        print(f"Wrote debug pre-AA mapped preview: {p}", flush=True)

    if postaa_preview_top is not None:
        p = base.with_name(base.name + "_debug_postaa_preview.png")
        Image.fromarray(_to_uint8_rgb(postaa_preview_top), "RGB").save(p)
        print(f"Wrote debug post-AA/final preview: {p}", flush=True)

    checks = {}
    if preaa_stack_model is not None:
        pre_recon = _preview_top_from_rp_stack(preaa_stack_model, lookup)
        p = base.with_name(base.name + "_debug_preaa_reconstructed_rgb.png")
        Image.fromarray(_to_uint8_rgb(pre_recon), "RGB").save(p)
        print(f"Wrote debug pre-AA reconstructed RGB: {p}", flush=True)
        checks["preaa"] = _compare_preview_report("pre-AA", pre_recon, preaa_preview_top)
    if postaa_stack_model is not None:
        post_recon = _preview_top_from_rp_stack(postaa_stack_model, lookup)
        p = base.with_name(base.name + "_debug_postaa_reconstructed_rgb.png")
        Image.fromarray(_to_uint8_rgb(post_recon), "RGB").save(p)
        print(f"Wrote debug post-AA reconstructed RGB: {p}", flush=True)
        checks["postaa"] = _compare_preview_report("post-AA", post_recon, postaa_preview_top)

    layer_prefix = base.with_name(base.name + "_debug_layers")
    save_rp_stack_layer_images(preaa_stack_model, layer_prefix, stage="preaa")
    save_rp_stack_layer_images(postaa_stack_model, layer_prefix, stage="postaa")

    npz_path = base.with_name(base.name + "_debug_stack.npz")
    save_rp_stack_npz_debug(preaa_stack_model, postaa_stack_model, npz_path, lookup, preaa_preview_top, postaa_preview_top, checks)

    json_path = base.with_name(base.name + "_debug_selfcheck.json")
    with json_path.open("w", encoding="utf-8") as f:
        json.dump(checks, f, indent=2, sort_keys=True)
    print(f"Wrote debug self-check JSON: {json_path}", flush=True)





def render_lut_prediction_preview(img: Image.Image, lookup: RecipeLookup, output_path: Path, error_diffusion: str = "none", candidate_count: int = 1, candidate_rgb_slack: float = 2.5, candidate_neighbour_weight: float = 0.25, source_scale: int = 1, edge_aa: str = "off", edge_luma_thresh: float = 28.0, edge_chroma_thresh: float = 34.0, edge_hue_thresh: float = 25.0, boundary_aa_structure_weight: str = "on", boundary_aa_detail_threshold: float = 8.0, boundary_aa_detail_full: float = 28.0, boundary_aa_min_weight: float = 0.15, boundary_aa_cost: float = 250.0, boundary_aa_cost_per_rp: float = 0.0) -> None:
    """Render predicted printed appearance using the same LUT path as G-code."""
    _stacks, preview = build_lut_cell_plan(img, lookup, error_diffusion=error_diffusion, candidate_count=candidate_count, candidate_rgb_slack=candidate_rgb_slack, candidate_neighbour_weight=candidate_neighbour_weight, source_scale=source_scale, edge_aa=edge_aa, edge_luma_thresh=edge_luma_thresh, edge_chroma_thresh=edge_chroma_thresh, edge_hue_thresh=edge_hue_thresh)
    Image.fromarray(_to_uint8_rgb(preview), "RGB").save(output_path)



def add_corner_colour_tiles(img: Image.Image, tile_px: int = 56, margin_px: int = 32) -> Image.Image:
    """Return a copy of img with five pure colour 5 mm reference tiles in every corner.

    The source image file is not modified. Each corner receives the same compact
    3-by-2 colour reference block:

        R  G  B
        C  Y

    Each swatch defaults to 56 native pixels, which is 5.04 mm at 0.10 mm/pixel
    and is the nearest integer-pixel approximation to 5.0 mm. The third lower
    position is left untouched so the overlay remains five tiles, not six.
    """
    if tile_px <= 0:
        raise ValueError("corner colour tile size must be positive")
    if margin_px < 0:
        raise ValueError("corner colour tile margin must be non-negative")
    out = img.copy()
    w, h = out.size
    block_w = 3 * tile_px
    block_h = 2 * tile_px
    if block_w + 2 * margin_px > w or block_h + 2 * margin_px > h:
        raise ValueError(
            f"corner colour tile blocks do not fit image size {w}x{h}: "
            f"tile_px={tile_px}, margin_px={margin_px}, block={block_w}x{block_h}"
        )

    colours = [
        ("R", (255, 0, 0), 0, 0),
        ("G", (0, 255, 0), 1, 0),
        ("B", (0, 0, 255), 2, 0),
        ("C", (0, 255, 255), 0, 1),
        ("Y", (255, 255, 0), 1, 1),
    ]

    anchors = {
        "TL": (margin_px, margin_px),
        "TR": (w - margin_px - block_w, margin_px),
        "BL": (margin_px, h - margin_px - block_h),
        "BR": (w - margin_px - block_w, h - margin_px - block_h),
    }
    for ax, ay in anchors.values():
        for _name, rgb, col, row in colours:
            x0 = ax + col * tile_px
            y0 = ay + row * tile_px
            box = (x0, y0, x0 + tile_px, y0 + tile_px)
            patch = Image.new("RGB", (tile_px, tile_px), rgb)
            out.paste(patch, box)
    return out

FILAMENT_META_ORDER = ["W", "F", "R", "Y", "G", "C", "B"]
FILAMENT_COLOURS = {
    "W": "#FFFFFF",
    "R": "#F72323",
    "F": "#DDEEF2",
    "Y": "#FFF144",
    "G": "#0ACC38",
    "C": "#76D9F4",
    "B": "#2850E0",
}

# v1.119: metadata must describe the *physical assigned spool*, not merely the
# logical card channel.  Friendly assignments such as logical B -> PLA:C update
# this registry so Studio sees cyan PLA rather than blue PETG.
PHYSICAL_FILAMENT_COLOURS = {
    "W": "#FFFFFF",
    "R": "#F72323",
    "Y": "#FFF144",
    "G": "#0ACC38",
    "C": "#76D9F4",
    "B": "#2850E0",
    "M": "#F330F9",
    "F": "#DDEEF2",
}
RUNTIME_MATERIAL_COLOUR_HEX = dict(FILAMENT_COLOURS)
RUNTIME_MATERIAL_PHYSICAL_COLOUR = {m:m for m in FILAMENT_COLOURS}

def material_display_colour(material):
    m = str(material).upper()
    return str(RUNTIME_MATERIAL_COLOUR_HEX.get(m, FILAMENT_COLOURS.get(m, "#FFFFFF")))

def audit_job_material_and_tower_contract(
    gcode_lines: Sequence[str],
    expected_active_materials: Sequence[str],
    tool_map: Dict[str, int],
) -> Dict[str, object]:
    """Fail closed on excluded material lifecycle use and active tower topology."""
    full_canonical = list(RUNTIME_CANONICAL_TOWER_SLOT_ORDER)
    expected_active = [m for m in full_canonical if m in set(expected_active_materials)]
    expected_excluded = [m for m in full_canonical if m not in set(expected_active)]
    canonical = list(expected_active)
    expected_active_set = set(expected_active)
    raw_to_material = {int(raw): str(mat) for mat, raw in tool_map.items()}
    sentinel_ids = {-1, 255, 1000, 1001, 65535, 65279}
    registry = {
        "M620": ("S", "M620_SA"),
        "M621": ("S", "M621_SA"),
        "T": ("@TOOL", "bare_T"),
        "M620.11": ("I", "M620.11_I"),
        "M620.6": ("I", "M620.6_I"),
        "M640.8": ("A", "M640.8_A"),
        "G383.3": ("L", "G383.3_L"),
        "G383": ("L", "G383_L"),
    }
    failures: List[str] = []
    family_counts: Dict[str, int] = {}
    lifecycle_material_counts: Dict[str, int] = {}
    m621_materials: List[str] = []
    current_emission: Optional[Dict[str, object]] = None
    emission_slots: List[Dict[str, object]] = []
    optical_emission_audits: List[Dict[str, object]] = []

    def finish_emission() -> None:
        nonlocal current_emission, emission_slots
        if current_emission is None:
            return
        physical = int(current_emission["physical"])
        if physical > 0:
            pass_role = str(current_emission.get("pass", "normal"))
            denominators = []
            for row in emission_slots:
                try:
                    denominators.append(int(str(row.get("slot", "0/0")).split("/", 1)[1]))
                except Exception:
                    pass
            expected_total = max(denominators) if denominators else len(canonical)
            actual_numbers = [int(row["slot_number"]) for row in emission_slots]
            actual_canonical = [str(row["canonical_slot"]) for row in emission_slots]
            actual_roles = [str(row["role"]) for row in emission_slots]
            scheduler_roles = {"primary", "secondary", "secondary_fill"}
            scheduler_tower = any(role in scheduler_roles for role in actual_roles)
            if scheduler_tower:
                # v1.129 same-layer scheduler reuses each material band: one
                # primary road pack plus one interleaved secondary/gap pack.
                # The secondary pack may be a genuine re-prime or structural fill.
                for slot_i, canonical_mat in enumerate(canonical, start=1):
                    rows_for_slot = [r for r in emission_slots if str(r["canonical_slot"]) == canonical_mat]
                    primary = [r for r in rows_for_slot if str(r["role"]) == "primary"]
                    secondary = [r for r in rows_for_slot if str(r["role"]) in {"secondary", "secondary_fill"}]
                    if len(primary) != 1 or len(secondary) != 1:
                        failures.append(
                            f"physical={physical} scheduler tower {canonical_mat} requires one primary and one secondary/gap record; "
                            f"found roles={[r['role'] for r in rows_for_slot]}"
                        )
                    if any(int(r["slot_number"]) != slot_i for r in rows_for_slot):
                        failures.append(
                            f"physical={physical} scheduler tower {canonical_mat} slot numbers "
                            f"{[r['slot_number'] for r in rows_for_slot]} != {slot_i}"
                        )
                    if any(int(str(r.get("slot", "0/0")).split("/",1)[1]) != len(canonical) for r in rows_for_slot):
                        failures.append(
                            f"physical={physical} scheduler tower {canonical_mat} denominator mismatch"
                        )
            else:
                paired_total = 2 * len(canonical)
                expected_start = (len(canonical) + 1) if expected_total == paired_total and pass_role == "filter" else 1
                expected_numbers = list(range(expected_start, expected_start + len(canonical)))
                if actual_numbers != expected_numbers:
                    failures.append(
                        f"physical={physical} pass={pass_role} tower slots {actual_numbers} != {expected_numbers}"
                    )
                if actual_canonical != canonical:
                    failures.append(
                        f"physical={physical} pass={pass_role} canonical tower order {actual_canonical} != {canonical}"
                    )
            optical_emission_audits.append({
                "physical": physical,
                "pass": pass_role,
                "slot_numbers": actual_numbers,
                "canonical_slots": actual_canonical,
                "roles": [str(row["role"]) for row in emission_slots],
                "materials": [str(row["material"]) for row in emission_slots],
            })
        current_emission = None
        emission_slots = []

    for parsed in parse_gcode_lines(gcode_lines, strict=True):
        stripped = parsed.original.strip()
        if stripped.startswith("; DIRECT_LAYER V4 physical="):
            finish_emission()
            tokens = dict(
                token.split("=", 1) for token in stripped[2:].split()
                if "=" in token
            )
            current_emission = {
                "physical": int(tokens.get("physical", "0")),
                "pass": tokens.get("pass", "normal"),
            }
            continue
        if stripped.startswith("; FC3D_TOWER_SLOT "):
            tokens = dict(
                token.split("=", 1) for token in stripped[2:].split()
                if "=" in token
            )
            slot_text = str(tokens.get("slot", "0/0"))
            try:
                slot_number = int(slot_text.split("/", 1)[0])
            except Exception:
                failures.append(f"unparseable tower slot marker: {stripped}")
                slot_number = -1
            emission_slots.append({
                "slot": slot_text,
                "slot_number": slot_number,
                "canonical_slot": tokens.get("canonical_slot", ""),
                "material": tokens.get("material", ""),
                "role": tokens.get("role", ""),
            })
            continue
        if stripped.startswith("; FC3D_TIME_TOOL_ACTIVATION_BEGIN "):
            tokens = dict(
                token.split("=", 1) for token in stripped[2:].split()
                if "=" in token
            )
            material = str(tokens.get("material", ""))
            if material and material not in expected_active_set:
                failures.append(f"activation block names excluded material {material}: {stripped}")

        registered = registry.get(str(parsed.command))
        if registered is None:
            continue
        field, family = registered
        optional = parsed.optional_word(field)
        if optional is None:
            continue
        word = optional[1]
        if word.numeric is None or abs(float(word.numeric) - round(float(word.numeric))) > 1e-9:
            failures.append(f"line {parsed.line_number} {family} is not an integer raw tool")
            continue
        raw = int(round(float(word.numeric)))
        if raw in sentinel_ids:
            continue
        material = raw_to_material.get(raw)
        if material is None:
            failures.append(f"line {parsed.line_number} {family} uses unmapped raw tool {raw}")
            continue
        family_counts[family] = int(family_counts.get(family, 0)) + 1
        lifecycle_material_counts[material] = int(lifecycle_material_counts.get(material, 0)) + 1
        if material not in expected_active_set:
            failures.append(
                f"line {parsed.line_number} {family} uses excluded material {material}/raw{raw}: {stripped}"
            )
        if parsed.command == "M621":
            m621_materials.append(material)
    finish_emission()

    actual_m621_set = {m for m in m621_materials if m in canonical}
    if actual_m621_set != expected_active_set:
        failures.append(
            f"M621 active set {sorted(actual_m621_set)} != expected {expected_active}"
        )
    if failures:
        raise RuntimeError("v1.69 job material/tower contract failed: " + "; ".join(failures[:30]))
    return {
        "result": "PASS",
        "active_materials": expected_active,
        "excluded_materials": expected_excluded,
        "lifecycle_family_counts": dict(sorted(family_counts.items())),
        "lifecycle_material_counts": {
            material: int(lifecycle_material_counts.get(material, 0))
            for material in expected_active
        },
        "m621_activation_sequence": m621_materials,
        "optical_emission_count": len(optical_emission_audits),
        "optical_emissions": optical_emission_audits,
        "canonical_tower_slots_per_emission": canonical,
    }


def infer_used_materials_from_gcode(gcode: str, tool_map: Optional[Dict[str, int]] = None) -> List[str]:
    """Infer logical materials actually emitted by generated G-code.

    PPSPV17: make this tool-command based, not template/header based.  In
    current direct-output mode the canonical order is W,F,R,Y,G,C,B and F may be
    an emitted material unless its raw tool actually appears in legacy/off mode.
    This drives all compact metadata/header declarations so Studio does not keep
    stale F/slot-9 material metadata while the model is using the compact W-blocker material order.
    """
    if tool_map is None:
        tool_map = DEFAULT_TOOL_MAP
    active_order = get_runtime_material_order()
    raw_to_mat = {int(tool_map[m]): m for m in active_order if m in tool_map}
    used = set()
    field_by_command = {"M620": "S", "T": "@TOOL", "M621": "S"}
    for parsed in parse_gcode_lines(gcode.splitlines(), strict=True):
        field = field_by_command.get(str(parsed.command))
        if field is None:
            continue
        optional = parsed.optional_word(field)
        if optional is None or optional[1].numeric is None:
            continue
        value = float(optional[1].numeric)
        if abs(value - round(value)) > 1e-9:
            raise RuntimeError(f"Non-integer filament selector at line {parsed.line_number}: {parsed.original.strip()}")
        raw_tool = int(round(value))
        if raw_tool in _INVALID_H2C_TOOL_IDS:
            continue
        mat = raw_to_mat.get(raw_tool)
        if mat is None:
            raise RuntimeError(
                f"Unmapped raw filament selector {raw_tool} at line {parsed.line_number}: {parsed.original.strip()}"
            )
        used.add(mat)
    if not used:
        raise RuntimeError("Parsed final G-code contains no valid material-selection command")
    # Return compact list in runtime order; direct output uses W,F,R,Y,G,C,B.
    return [m for m in active_order if m in used]

def infer_tool_sequence_from_gcode(gcode: str, used_mats: Sequence[str], tool_map: Dict[str, int]) -> List[int]:
    """Return compact 1-based Bambu filament/tool IDs in first-use sequence.

    The G-code tool commands use zero-based tool numbers, while the Bambu header
    '; filament:' and filament_sequence.json sequence use tool+1 values.
    """
    seen: List[int] = []
    used_tools = {int(tool_map[m]) for m in used_mats}
    for tool in derive_raw_tool_sequence_from_m621(gcode, tool_map):
        if tool in used_tools and tool not in seen:
            seen.append(tool)
    missing = sorted(used_tools - set(seen))
    if missing:
        raise RuntimeError(f"Used materials have no parsed M621 activation sequence: raw tools {missing}")
    return [t + 1 for t in seen]

def estimate_filament_lengths_by_material(gcode: str, used_mats: Sequence[str], tool_map: Dict[str, int]) -> Dict[str, float]:
    """Best-effort relative-E estimate for header totals.

    This is metadata only; it is not used for actual extrusion. It is kept mainly
    so the header list length matches the compact used-filament list.
    """
    current_mat: Optional[str] = None
    by_mat = {m: 0.0 for m in used_mats}
    raw_to_mat = {int(v): str(k) for k, v in tool_map.items()}
    for parsed in parse_gcode_lines(gcode.splitlines(), strict=True):
        if parsed.command in ("M621", "T"):
            field = "S" if parsed.command == "M621" else "@TOOL"
            optional = parsed.optional_word(field)
            if optional is not None and optional[1].numeric is not None:
                raw_tool = int(round(float(optional[1].numeric)))
                if raw_tool not in _INVALID_H2C_TOOL_IDS:
                    current_mat = raw_to_mat.get(raw_tool)
        if current_mat not in by_mat or parsed.command not in ("G0", "G1"):
            continue
        e_word = parsed.optional_word("E")
        if e_word is not None and e_word[1].numeric is not None:
            e = float(e_word[1].numeric)
            if e > 0:
                by_mat[current_mat] += e
    return by_mat

def update_header_filament_metadata(gcode: str, used_mats: Sequence[str], tool_map: Dict[str, int]) -> str:
    ids_1based = [tool_map[m] + 1 for m in used_mats]
    lens = estimate_filament_lengths_by_material(gcode, used_mats, tool_map)
    lengths = [lens.get(m, 0.0) for m in used_mats]
    area = math.pi * (FILAMENT_DIAM_MM / 2) ** 2
    volumes = [v * area for v in lengths]
    # Use existing density assumptions where possible, otherwise harmless PLA-ish default.
    weights = [vol / 1000.0 * (1.24 if m in ("W","R","F","Y") else 1.27) for vol, m in zip(volumes, used_mats)]
    # These are structured Bambu header comment records.  Parse their exact
    # keys, require one of each, and rebuild only the value portion.  Regex does
    # not decide which comment has metadata meaning or where a replacement is
    # allowed.
    replacements = {
        "; total filament length [mm] :": ",".join(f"{v:.2f}" for v in lengths),
        "; total filament volume [cm^3] :": ",".join(f"{v:.2f}" for v in volumes),
        "; total filament weight [g] :": ",".join(f"{v:.2f}" for v in weights),
        "; filament:": ",".join(str(v) for v in ids_1based),
    }
    counts = {key: 0 for key in replacements}
    out: List[str] = []
    for line_number, line in enumerate(gcode.splitlines(), start=1):
        matched = [key for key in replacements if line.startswith(key)]
        if len(matched) > 1:
            raise RuntimeError(f"Ambiguous Bambu header metadata at line {line_number}: {line!r}")
        if not matched:
            out.append(line)
            continue
        key = matched[0]
        counts[key] += 1
        if counts[key] > 1:
            raise RuntimeError(f"Duplicate Bambu header metadata record {key!r} at line {line_number}")
        separator = " " if key.endswith(":") else ""
        out.append(f"{key}{separator}{replacements[key]}")
    missing = [key for key, count in counts.items() if count != 1]
    if missing:
        raise RuntimeError(f"Missing required Bambu header metadata records: {missing}")
    return "\n".join(out) + ("\n" if gcode.endswith("\n") else "")

def patch_xml_metadata(xml: str, used_mats: Sequence[str], tool_map: Dict[str, int]) -> str:
    """Patch XML metadata to avoid stale/auto compacting of filament slots."""
    try:
        root = ET.fromstring(xml)
    except Exception as exc:
        raise RuntimeError(f"Cannot safely patch malformed XML metadata: {exc}") from exc
    changed = False
    for element in root.iter():
        if element.get("key") == "filament_map_mode":
            element.set("value", "Manual")
            changed = True
    if not changed:
        raise RuntimeError("XML metadata has no filament_map_mode field to patch")
    return ET.tostring(root, encoding="unicode")

def patch_plate_json(data: bytes, used_mats: Sequence[str], tool_map: Dict[str, int], gcode: str, time_estimate: Optional[Dict[str, object]] = None, build_plate: str = DEFAULT_BUILD_PLATE) -> bytes:
    try:
        obj = json.loads(data.decode("utf-8"))
    except Exception as exc:
        raise RuntimeError(f"Metadata/plate_1.json is invalid and cannot be safely patched: {exc}") from exc
    if not isinstance(obj, dict):
        raise RuntimeError("Metadata/plate_1.json must contain a JSON object")

    obj["filament_ids"] = [tool_map[m] for m in used_mats]
    obj["filament_colors"] = [material_display_colour(m) for m in used_mats]
    obj["first_extruder"] = tool_map[used_mats[0]] if used_mats else tool_map["W"]
    plate_profile = get_build_plate_profile(build_plate)
    obj["bed_type"] = str(plate_profile["plate_json_value"])
    obj["fc3d_build_plate"] = str(build_plate)
    obj["fc3d_build_plate_display_name"] = str(plate_profile["display_name"])

    # This is a direct-G-code package. Do not preserve reference 3MF object or
    # wipe-tower bbox metadata, because Bambu Studio will show those stale
    # objects on the plate even when the generated G-code is correct.
    bbox = infer_xy_bbox_from_gcode(gcode)
    if bbox is not None:
        obj["bbox_all"] = [float(v) for v in bbox]
        obj["bbox_objects"] = [{
            "area": float(max(0.0, (bbox[2]-bbox[0]) * (bbox[3]-bbox[1]))),
            "bbox": [float(v) for v in bbox],
            "id": 1,
            "layer_height": float(BASE_H_MM),
            "name": "fc3d_direct_gcode"
        }]
    else:
        obj["bbox_all"] = [0, 0, 0, 0]
        obj["bbox_objects"] = []

    total_sec = _time_estimate_total_seconds(time_estimate)
    if total_sec is not None:
        obj["fc3d_time_estimate_total_seconds"] = int(round(float(total_sec)))
        obj["fc3d_time_estimate_total_hms"] = _format_seconds_hms(float(total_sec))
        obj["fc3d_time_estimate_bambu_comment_time"] = _format_bambu_comment_time(float(total_sec))
        obj["fc3d_time_estimate_source"] = "Metadata/fc3d_time_estimate.json"
        obj["fc3d_time_estimate_patched_by"] = PP_VERSION
        obj["fc3d_slice_info_prediction_seconds"] = int(round(float(total_sec)))

    return json.dumps(obj, separators=(",", ":")).encode("utf-8")


def _space_join(values: Sequence[object]) -> str:
    return " ".join(str(v) for v in values)


def _metadata_map_arrays_for_used_materials(used_mats: Sequence[str], tool_map: Dict[str, int]) -> Tuple[List[str], List[str], List[str]]:
    """Return Bambu metadata maps for active absolute filament IDs.

    PPSPV32: inactive slots are zero/unassigned.  PPSPV29 left inactive slots
    mapped to nozzle 1 in some metadata arrays, which could make Studio/printer
    expose stale inactive materials after the no-T cleanup.
    """
    n = max(17, max((int(tool_map[m]) + 1 for m in used_mats if m in tool_map), default=17))
    filament_maps = ["0"] * n
    filament_volume_maps = ["0"] * n
    filament_nozzle_maps = ["0"] * n
    for mat in used_mats:
        if mat not in tool_map:
            continue
        idx = int(tool_map[mat])
        if not (0 <= idx < n):
            continue
        if mat == "W":
            filament_maps[idx] = "1"
            filament_volume_maps[idx] = "0"
            filament_nozzle_maps[idx] = "0"
        else:
            filament_maps[idx] = "2"
            filament_volume_maps[idx] = "1"
            filament_nozzle_maps[idx] = "1"
    return filament_maps, filament_volume_maps, filament_nozzle_maps


def _xml_set_or_add_plate_metadata(root: ET.Element, key: str, value: str) -> bool:
    plate = root.find(".//plate")
    if plate is None:
        return False
    for el in plate.findall("metadata"):
        if el.get("key") == key:
            old = el.get("value")
            el.set("value", value)
            return old != value
    el = ET.SubElement(plate, "metadata")
    el.set("key", key)
    el.set("value", value)
    return True


def _xml_bytes(root: ET.Element) -> bytes:
    try:
        ET.indent(root, space="  ")
    except Exception:
        pass
    return ET.tostring(root, encoding="utf-8", xml_declaration=True)


def patch_model_settings_material_metadata(data: bytes, used_mats: Sequence[str], tool_map: Dict[str, int]) -> bytes:
    """Synchronise Metadata/model_settings.config with the active material registry.

    PPSPV17 still left model_settings.config with stale F/filament-9 maps.  Studio
    uses these maps as part of filament grouping, so PPSPV18 updates them inside
    the generator rather than relying on a post-process wrapper.
    """
    try:
        root = ET.fromstring(data)
    except Exception as exc:
        raise RuntimeError(f"Metadata/model_settings.config is invalid XML: {exc}") from exc
    if root.find(".//plate") is None:
        raise RuntimeError("Metadata/model_settings.config has no plate element")
    fmap, vmap, _nmap = _metadata_map_arrays_for_used_materials(used_mats, tool_map)
    _xml_set_or_add_plate_metadata(root, "filament_maps", _space_join(fmap))
    _xml_set_or_add_plate_metadata(root, "filament_volume_maps", _space_join(vmap))
    _xml_set_or_add_plate_metadata(root, "fc3d_model_settings_patched_by", PP_VERSION)
    _xml_set_or_add_plate_metadata(root, "fc3d_active_filament_one_based", ",".join(str(int(tool_map[m]) + 1) for m in used_mats if m in tool_map))
    return _xml_bytes(root)


def _find_plate_filament(plate: ET.Element, filament_id: int) -> Optional[ET.Element]:
    fid = str(int(filament_id))
    for el in plate.findall("filament"):
        if el.get("id") == fid:
            return el
    return None


def _insert_filament_sorted(plate: ET.Element, el: ET.Element) -> None:
    target_id = int(el.get("id", "999999"))
    for idx, child in enumerate(list(plate)):
        if child.tag == "filament":
            try:
                cid = int(child.get("id", "999999"))
            except Exception:
                cid = 999999
            if cid > target_id:
                plate.insert(idx, el)
                return
    plate.append(el)


def _sort_plate_filament_elements(plate: ET.Element) -> None:
    children = list(plate)
    filaments = [c for c in children if c.tag == "filament"]
    if not filaments:
        return
    first_idx = children.index(filaments[0])
    for f in filaments:
        plate.remove(f)
    filaments.sort(key=lambda e: int(e.get("id", "999999")))
    for off, f in enumerate(filaments):
        plate.insert(first_idx + off, f)


def audit_gcode_physical_layer_contract(
    gcode_lines: Sequence[str],
    expected_physical_layers: Optional[int] = None,
    require_state_reset_markers: bool = True,
) -> Dict[str, object]:
    """Validate the complete physical-layer boundary contract.

    Ordinary Z motion is deliberately ignored.  A physical layer exists only
    when the complete layer_header() record is present.  This keeps same-Z
    carrier/filter passes inside one physical layer while still allowing their
    model and travel moves to use arbitrary Z values.
    """
    # The late cumulative-time pass may insert executable M73 P/R records at
    # safe motion sites.  They are progress metadata, not physical-layer
    # boundaries, so ignore them while checking header contiguity.
    lines = [
        str(line).strip()
        for line in gcode_lines
        if not _m73_pr_line(str(line))
    ]
    change_positions = [i for i, line in enumerate(lines) if line == "; CHANGE_LAYER"]
    physical_layers = len(change_positions)
    if physical_layers < 1:
        raise RuntimeError("Physical-layer contract audit failed: no CHANGE_LAYER header found")
    if expected_physical_layers is not None and physical_layers != int(expected_physical_layers):
        raise RuntimeError(
            "Physical-layer contract audit failed: "
            f"found {physical_layers} headers, expected {int(expected_physical_layers)}"
        )

    boundary_families = {
        "Z_HEIGHT": [i for i, line in enumerate(lines) if line.startswith("; Z_HEIGHT:")],
        "layer_count": [i for i, line in enumerate(lines) if line.startswith("; layer num/total_layer_count:")],
        "M73_L": [i for i, line in enumerate(lines) if re.match(r"^M73 L\d+(?:\s.*)?$", line)],
        "M991_notify": [
            i for i, line in enumerate(lines)
            if re.match(r"^M991 S0 P-?\d+\s*;notify layer change$", line)
        ],
    }
    for family, positions in boundary_families.items():
        if len(positions) != physical_layers:
            raise RuntimeError(
                "Physical-layer contract audit failed: "
                f"{family} count {len(positions)} != CHANGE_LAYER count {physical_layers}"
            )

    header_rows: List[Dict[str, object]] = []
    reset_positions: List[int] = []
    reset_re = re.compile(r"^; FC3D_PHYSICAL_LAYER_STATE_RESET layer=(\d+)/(\d+)$")
    for ordinal, start in enumerate(change_positions, start=1):
        if start + 10 >= len(lines):
            raise RuntimeError(f"Physical-layer contract audit failed: truncated header {ordinal}")
        z_match = re.match(r"^; Z_HEIGHT: ([-+0-9.]+)$", lines[start + 1])
        h_match = re.match(r"^; LAYER_HEIGHT: ([-+0-9.]+)$", lines[start + 2])
        count_match = re.match(r"^; layer num/total_layer_count: (\d+)/(\d+)$", lines[start + 3])
        if z_match is None or h_match is None or count_match is None:
            raise RuntimeError(
                f"Physical-layer contract audit failed: malformed Z/height/count fields in header {ordinal}"
            )
        z = float(z_match.group(1))
        h = float(h_match.group(1))
        layer_num = int(count_match.group(1))
        declared_total = int(count_match.group(2))
        if layer_num != ordinal or declared_total != physical_layers:
            raise RuntimeError(
                "Physical-layer contract audit failed: "
                f"header {ordinal} declares {layer_num}/{declared_total}, expected {ordinal}/{physical_layers}"
            )
        expected_header = [str(line).strip() for line in layer_header(layer_num, z, h, physical_layers)]
        actual_header = lines[start:start + len(expected_header)]
        def _header_equivalent(actual: str, expected: str) -> bool:
            if actual == expected:
                return True
            # v1.151+ global pressure-state contract makes repeated layer-boundary
            # retracts idempotent.  If the nozzle is already fully retracted, the
            # canonical E-0.4 header operation is represented by an explicit no-op
            # marker rather than physically retracting below prime_state zero.
            if expected == "G1 E-0.4 F1800" and (
                actual.startswith("; FC3D_V151_RETRACT_NOOP state=0 original=G1 E-0.4 F1800")
                or actual.startswith("; FC3D_V152_RETRACT_NOOP state=0 original=G1 E-0.4 F1800")
            ):
                return True
            return False
        if not all(_header_equivalent(actual, expected) for actual, expected in zip(actual_header, expected_header)):
            mismatch = next(
                (
                    idx for idx, (actual, expected) in enumerate(zip(actual_header, expected_header))
                    if not _header_equivalent(actual, expected)
                ),
                min(len(actual_header), len(expected_header)),
            )
            actual = actual_header[mismatch] if mismatch < len(actual_header) else "<missing>"
            expected = expected_header[mismatch] if mismatch < len(expected_header) else "<none>"
            raise RuntimeError(
                "Physical-layer contract audit failed: "
                f"header {ordinal} record {mismatch + 1} is {actual!r}, expected {expected!r}"
            )
        reset_index = start + len(expected_header)
        if require_state_reset_markers:
            expected_reset = f"; FC3D_PHYSICAL_LAYER_STATE_RESET layer={layer_num}/{physical_layers}"
            actual_reset = lines[reset_index] if reset_index < len(lines) else "<missing>"
            if actual_reset != expected_reset:
                raise RuntimeError(
                    "Physical-layer contract audit failed: "
                    f"header {ordinal} is not followed by its collision-state reset marker; "
                    f"found {actual_reset!r}, expected {expected_reset!r}"
                )
            reset_positions.append(reset_index)
        header_rows.append({
            "layer_num": layer_num,
            "declared_total": declared_total,
            "z": z,
            "layer_height": h,
            "line_index": start,
        })

    if require_state_reset_markers:
        all_resets = [i for i, line in enumerate(lines) if reset_re.match(line)]
        if all_resets != reset_positions:
            raise RuntimeError(
                "Physical-layer contract audit failed: collision-state reset markers do not map one-to-one "
                f"to layer headers (found {all_resets}, expected {reset_positions})"
            )

    total_fields = []
    max_z_fields = []
    for line in lines:
        total_match = re.match(r"^; total layer number:\s*(\d+)$", line)
        if total_match is not None:
            total_fields.append(int(total_match.group(1)))
        max_z_match = re.match(r"^; max_z_height:\s*([-+0-9.]+)$", line)
        if max_z_match is not None:
            max_z_fields.append(float(max_z_match.group(1)))
    if total_fields != [physical_layers]:
        raise RuntimeError(
            "Physical-layer contract audit failed: "
            f"G-code total-layer metadata {total_fields} != [{physical_layers}]"
        )
    nominal_max_z = max(float(row["z"]) for row in header_rows)
    if len(max_z_fields) != 1 or abs(max_z_fields[0] - nominal_max_z) > 5e-6:
        raise RuntimeError(
            "Physical-layer contract audit failed: "
            f"G-code max_z_height {max_z_fields} != nominal layer maximum {nominal_max_z:.5f}"
        )
    return {
        "physical_layers": int(physical_layers),
        "nominal_max_z": float(nominal_max_z),
        "header_rows": header_rows,
        "change_layer_positions": change_positions,
        "state_reset_positions": reset_positions,
        "result": "PASS",
    }


def _expected_slice_layer_rows(
    physical_layers: int,
    base_raw: int,
    full_raw: Sequence[int],
) -> List[Tuple[int, int, str]]:
    """Return the minimal inherited-compatible slice-info range structure."""
    count = int(physical_layers)
    if count < 1:
        raise RuntimeError(f"Invalid physical layer count for slice metadata: {count}")
    rows: List[Tuple[int, int, str]] = [(0, 0, str(int(base_raw)))]
    full_text = _space_join(full_raw)
    if count >= 2:
        rows.append((1, 1, full_text))
    if count >= 3:
        rows.append((2, count - 1, full_text))
    return rows


def _replace_slice_layer_ranges(
    plate: ET.Element,
    physical_layers: int,
    base_raw: int,
    full_raw: Sequence[int],
) -> None:
    """Replace, rather than merely relabel, inherited template layer ranges."""
    lists = plate.find("layer_filament_lists")
    if lists is None:
        lists = ET.SubElement(plate, "layer_filament_lists")
    for child in list(lists):
        if child.tag == "layer_filament_list":
            lists.remove(child)
    for start, end, filament_list in _expected_slice_layer_rows(physical_layers, base_raw, full_raw):
        child = ET.SubElement(lists, "layer_filament_list")
        child.set("filament_list", filament_list)
        child.set("layer_ranges", f"{start} {end}")


def _read_slice_layer_rows(plate: ET.Element) -> List[Tuple[int, int, str]]:
    lists = plate.find("layer_filament_lists")
    if lists is None:
        raise RuntimeError("slice_info.config has no layer_filament_lists element")
    rows: List[Tuple[int, int, str]] = []
    for child in lists.findall("layer_filament_list"):
        ranges = [int(value) for value in re.findall(r"-?\d+", child.get("layer_ranges", ""))]
        if len(ranges) != 2 or ranges[0] < 0 or ranges[1] < ranges[0]:
            raise RuntimeError(
                f"slice_info.config has invalid layer_ranges={child.get('layer_ranges')!r}"
            )
        rows.append((ranges[0], ranges[1], " ".join(child.get("filament_list", "").split())))
    return rows


def patch_slice_info_material_metadata(
    data: bytes,
    used_mats: Sequence[str],
    tool_map: Dict[str, int],
    layer_contract: Dict[str, object],
    time_estimate: Optional[Dict[str, object]] = None,
) -> bytes:
    """Synchronise Metadata/slice_info.config with actual emitted tools/materials.

    PPSPV32 removes stale unused filament/nozzle entries and rebuilds compact
    nozzle rows for only the active materials.  This is targeted at the invalid
    3MF error seen after PPSPV29.
    """
    try:
        root = ET.fromstring(data)
    except Exception as exc:
        raise RuntimeError(f"Metadata/slice_info.config is invalid XML: {exc}") from exc
    plate = root.find(".//plate")
    if plate is None:
        raise RuntimeError("Metadata/slice_info.config has no plate element")

    active_raw = [int(tool_map[m]) for m in used_mats if m in tool_map]
    active_one = [v + 1 for v in active_raw]
    active_one_set = set(active_one)

    fmap, _vmap, _nmap = _metadata_map_arrays_for_used_materials(used_mats, tool_map)
    _xml_set_or_add_plate_metadata(root, "filament_maps", _space_join(fmap))
    total_sec = _time_estimate_total_seconds(time_estimate)
    if total_sec is not None:
        total_i = int(round(float(total_sec)))
        # Bambu/printer display appears to use this built-in total-time field.
        # The inherited reference package had prediction=22347, matching 6h12m27s.
        _xml_set_or_add_plate_metadata(root, "prediction", str(total_i))
        _xml_set_or_add_plate_metadata(root, "fc3d_prediction_seconds", str(total_i))
        _xml_set_or_add_plate_metadata(root, "fc3d_prediction_hms", _format_seconds_hms(float(total_sec)))
        _xml_set_or_add_plate_metadata(root, "fc3d_prediction_source", "Metadata/fc3d_time_estimate.json")
    _xml_set_or_add_plate_metadata(root, "fc3d_slice_info_patched_by", PP_VERSION)
    _xml_set_or_add_plate_metadata(root, "fc3d_active_raw_tools", ",".join(str(v) for v in active_raw))
    _xml_set_or_add_plate_metadata(root, "fc3d_active_filament_one_based", ",".join(str(v) for v in active_one))
    physical_layers = int(layer_contract["physical_layers"])
    nominal_max_z = float(layer_contract["nominal_max_z"])
    _xml_set_or_add_plate_metadata(root, "fc3d_physical_layer_count", str(physical_layers))
    _xml_set_or_add_plate_metadata(root, "fc3d_nominal_max_z_mm", f"{nominal_max_z:.5f}")

    # Remove any stale filament entries whose one-based id is not active.
    for fil in list(plate.findall("filament")):
        try:
            fid = int(fil.get("id", "-1"))
        except Exception:
            fid = -1
        if fid not in active_one_set:
            plate.remove(fil)

    def find_filament(fid: int) -> Optional[ET.Element]:
        for el in plate.findall("filament"):
            try:
                if int(el.get("id", "-1")) == int(fid):
                    return el
            except Exception:
                pass
        return None

    for compact_idx, mat in enumerate(used_mats):
        if mat not in tool_map:
            continue
        fid = int(tool_map[mat]) + 1
        el = find_filament(fid)
        if el is None:
            el = ET.Element("filament")
            el.set("id", str(fid))
            _insert_filament_sorted(plate, el)
        el.set("tray_info_idx", el.get("tray_info_idx") or "GFG99")
        el.set("type", str(polymer_profile_for_material(mat)["filament_type"]).upper())
        el.set("color", material_display_colour(mat))
        el.set("group_id", str(compact_idx))
        el.set("nozzle_diameter", "0.40")
        el.set("volume_type", "Standard" if mat == "W" else "High Flow")
        el.set("used_for_object", "true")
        el.set("used_for_support", "false")
        if el.get("used_m") is None:
            el.set("used_m", "0.00")
        if el.get("used_g") is None:
            el.set("used_g", "0.00")

    # Rebuild compact nozzle rows only for active compact materials.
    for noz in list(plate.findall("nozzle")):
        plate.remove(noz)
    insert_at = len(list(plate))
    for idx, child in enumerate(list(plate)):
        if child.tag == "layer_filament_lists":
            insert_at = idx
            break
    for compact_idx, mat in enumerate(used_mats):
        noz = ET.Element("nozzle")
        noz.set("id", str(compact_idx))
        noz.set("extruder_id", "1" if mat == "W" else "2")
        noz.set("nozzle_diameter", "0.4")
        noz.set("volume_type", "Standard" if mat == "W" else "High Flow")
        plate.insert(insert_at + compact_idx, noz)

    if active_raw:
        base_raw = str(int(tool_map.get("W", active_raw[0])))
        _replace_slice_layer_ranges(
            plate,
            physical_layers,
            int(base_raw),
            active_raw,
        )

    _sort_plate_filament_elements(plate)
    return _xml_bytes(root)


def positive_extrusion_by_raw_tool(gcode: str) -> Dict[int, Tuple[int, float]]:
    """Return positive model/tower extrusion counts and E sum keyed by raw T-number."""
    current_tool = None
    counts: Dict[int, int] = {}
    e_sum: Dict[int, float] = {}
    for parsed in parse_gcode_lines(gcode.splitlines(), strict=True):
        if parsed.command in ("T", "M621"):
            field = "@TOOL" if parsed.command == "T" else "S"
            optional = parsed.optional_word(field)
            if optional is not None and optional[1].numeric is not None:
                candidate = int(round(float(optional[1].numeric)))
                if candidate not in _INVALID_H2C_TOOL_IDS:
                    current_tool = candidate
            continue
        if current_tool is None or parsed.command not in ("G1", "G0"):
            continue
        e_word = parsed.optional_word("E")
        if e_word is None or e_word[1].numeric is None:
            continue
        e = float(e_word[1].numeric)
        if e > 0:
            counts[current_tool] = counts.get(current_tool, 0) + 1
            e_sum[current_tool] = e_sum.get(current_tool, 0.0) + e
    return {k: (counts.get(k, 0), e_sum.get(k, 0.0)) for k in sorted(set(counts) | set(e_sum))}


def patch_filament_sequence(data: bytes, used_mats: Sequence[str], tool_map: Dict[str, int], gcode: str) -> bytes:
    seq = [tool_map[m] + 1 for m in used_mats]
    # Keep a compact sequence in the same order as plate_1.json/header.
    # This avoids stale Y/G/C entries and avoids a mismatch where B is the
    # 3rd sequence item but 4th compact filament. For W/R/F/B-only files,
    # the sequence is therefore 5,8,9,17.
    obj = {"plate_1": {"sequence": seq, "nozzle_sequence": [0 for _ in seq], "optimal_assignment": []}}
    return json.dumps(obj, separators=(",", ":")).encode("utf-8")


# ---------------------------------------------------------------------------
# Diagnostic geometry .3mf export
# ---------------------------------------------------------------------------

def _cuboid_mesh_append(vertices: List[Tuple[float,float,float]], triangles: List[Tuple[int,int,int]],
                        x0: float, y0: float, z0: float, x1: float, y1: float, z1: float) -> None:
    """Append one closed axis-aligned cuboid to a mesh."""
    if x1 <= x0 or y1 <= y0 or z1 <= z0:
        return
    base = len(vertices)
    vertices.extend([
        (x0,y0,z0), (x1,y0,z0), (x1,y1,z0), (x0,y1,z0),
        (x0,y0,z1), (x1,y0,z1), (x1,y1,z1), (x0,y1,z1),
    ])
    # 12 triangles, outward-ish winding.  Bambu/3MF readers are generally tolerant,
    # but keep a closed manifold cuboid per merged rectangle.
    triangles.extend([
        (0,2,1), (0,3,2),       # bottom
        (4,5,6), (4,6,7),       # top
        (0,1,5), (0,5,4),       # front
        (1,2,6), (1,6,5),       # right
        (2,3,7), (2,7,6),       # back
        (3,0,4), (3,4,7),       # left
    ])
    for i in range(len(triangles)-12, len(triangles)):
        a,b,c = triangles[i]
        triangles[i] = (base+a, base+b, base+c)


def _rectangles_for_material_grid(grid: np.ndarray, mat: str) -> List[Tuple[int,int,int,int]]:
    """Greedily merge same-material cells into axis-aligned integer rectangles.

    grid is bottom-origin [rows_y, cols_x].  Returned rectangles are
    (x0_cell, y0_cell, x1_cell_exclusive, y1_cell_exclusive).
    """
    h, w = grid.shape
    visited = np.zeros((h, w), dtype=bool)
    rects: List[Tuple[int,int,int,int]] = []
    for y in range(h):
        x = 0
        while x < w:
            if visited[y, x] or grid[y, x] != mat:
                x += 1
                continue
            x1 = x + 1
            while x1 < w and (not visited[y, x1]) and grid[y, x1] == mat:
                x1 += 1
            y1 = y + 1
            while y1 < h:
                row_ok = True
                for xx in range(x, x1):
                    if visited[y1, xx] or grid[y1, xx] != mat:
                        row_ok = False
                        break
                if not row_ok:
                    break
                y1 += 1
            visited[y:y1, x:x1] = True
            rects.append((x, y, x1, y1))
            x = x1
    return rects



def downsample_stack_grid_to_ap_for_geometry(stack_grid: np.ndarray, ap_scale: int) -> np.ndarray:
    """
    Convert RP-resolution direct/image stack into AP-resolution diagnostic geometry.

    RP pixels exist for AA/recipe lookup and pp's internal line construction.
    Slicer-input 3MF geometry should NOT create one cuboid per RP pixel.  It should
    represent the coarser actual-print/AP decision grid.  For rp_pitch=0.05 and
    print_width=0.40, ap_scale=8, so every 8x8 RP block becomes one AP cell.
    We sample the centre RP pixel of each AP block, preserving recipe/layer order
    while producing normal 0.40 mm geometry for Bambu Studio to slice.
    """
    ap_scale = int(max(1, round(ap_scale)))
    if ap_scale <= 1:
        return stack_grid

    ny, nx, layers = stack_grid.shape
    ap_nx = int(math.ceil(nx / ap_scale))
    ap_ny = int(math.ceil(ny / ap_scale))
    out = np.empty((ap_ny, ap_nx, layers), dtype=stack_grid.dtype)

    for ay in range(ap_ny):
        sy = min(ny - 1, ay * ap_scale + ap_scale // 2)
        for ax in range(ap_nx):
            sx = min(nx - 1, ax * ap_scale + ap_scale // 2)
            out[ay, ax, :] = stack_grid[sy, sx, :]
    return out


def write_diagnostic_geometry_3mf(output: Path, stack_grid: np.ndarray, x_origin: float, y_origin: float,
                                  include_base: bool = True, ap_scale: int = 1) -> Dict[str, int]:
    """Write a simple slicer-readable 3MF model with seven global material objects.

    This is intentionally a diagnostic slicer input, not a Bambu project/gcode.  It
    creates one object named W/F/R/Y/G/C/B and merges neighbouring same-material
    AP cells into cuboids within that object. RP input is centre-sampled to AP first.  Bambu Studio should then be able to
    slice/assign the six objects so we can inspect its path planning, flow,
    line lengths, hops, and purge strategy.
    """
    output = Path(output)
    source_ny, source_nx, source_layers = stack_grid.shape
    if source_layers != MIX_LAYERS:
        raise RuntimeError(f"Expected stack_grid third dimension {MIX_LAYERS}, got {source_layers}")

    ap_scale = int(max(1, round(ap_scale)))
    stack_grid = downsample_stack_grid_to_ap_for_geometry(stack_grid, ap_scale)
    ny, nx, layers = stack_grid.shape

    meshes: Dict[str, Tuple[List[Tuple[float,float,float]], List[Tuple[int,int,int]]]] = {
        m: ([], []) for m in MATERIAL_ORDER
    }

    # 0.20 mm opaque W foundation as one solid base cuboid.
    if include_base:
        verts, tris = meshes['W']
        _cuboid_mesh_append(verts, tris, x_origin, y_origin, 0.0,
                            x_origin + nx * ROAD_W_MM, y_origin + ny * ROAD_W_MM, BASE_H_MM)

    # Optical layers: stack_grid is physical bottom->top and bottom-origin in Y.
    for li in range(MIX_LAYERS):
        z0 = BASE_H_MM + li * MIX_H_MM
        z1 = z0 + MIX_H_MM
        layer_grid = stack_grid[:, :, li]
        for mat in MATERIAL_ORDER:
            if not np.any(layer_grid == mat):
                continue
            rects = _rectangles_for_material_grid(layer_grid, mat)
            verts, tris = meshes[mat]
            for x0c, y0c, x1c, y1c in rects:
                _cuboid_mesh_append(
                    verts, tris,
                    x_origin + x0c * ROAD_W_MM,
                    y_origin + y0c * ROAD_W_MM,
                    z0,
                    x_origin + x1c * ROAD_W_MM,
                    y_origin + y1c * ROAD_W_MM,
                    z1,
                )

    def esc(v):
        return f"{v:.5f}".rstrip('0').rstrip('.') if isinstance(v, float) else str(v)

    resources = []
    build_items = []
    object_id = 1
    stats = {}
    for mat in MATERIAL_ORDER:
        verts, tris = meshes[mat]
        stats[f'{mat}_vertices'] = len(verts)
        stats[f'{mat}_triangles'] = len(tris)
        stats[f'{mat}_objects'] = 1 if tris else 0
        vert_xml = ''.join(f'<vertex x="{esc(x)}" y="{esc(y)}" z="{esc(z)}" />' for x,y,z in verts)
        tri_xml = ''.join(f'<triangle v1="{a}" v2="{b}" v3="{c}" />' for a,b,c in tris)
        resources.append(
            f'<object id="{object_id}" type="model" name="{mat}" partnumber="{mat}"><metadata name="Title">{mat}</metadata><metadata name="Description">FC3D material object {mat}</metadata><mesh><vertices>{vert_xml}</vertices><triangles>{tri_xml}</triangles></mesh></object>'
        )
        build_items.append(f'<item objectid="{object_id}" />')
        object_id += 1

    model_xml = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<model unit="millimeter" xml:lang="en-US" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02">'
        '<metadata name="Application">FC3D V5 diagnostic geometry export</metadata>'
        '<resources>' + ''.join(resources) + '</resources>'
        '<build>' + ''.join(build_items) + '</build>'
        '</model>'
    )
    content_types = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        '<Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/>'
        '</Types>'
    )
    rels = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/>'
        '</Relationships>'
    )
    with zipfile.ZipFile(output, 'w', zipfile.ZIP_DEFLATED) as z:
        z.writestr('[Content_Types].xml', content_types)
        z.writestr('_rels/.rels', rels)
        z.writestr('3D/3dmodel.model', model_xml)
    stats['source_rp_cells_x'] = int(source_nx)
    stats['source_rp_cells_y'] = int(source_ny)
    stats['ap_scale_rp_per_ap'] = int(ap_scale)
    stats['cells_x'] = nx
    stats['cells_y'] = ny
    stats['cell_mm'] = ROAD_W_MM
    stats['base_h_mm'] = BASE_H_MM
    stats['mix_h_mm'] = MIX_H_MM
    stats['mix_layers'] = MIX_LAYERS
    stats['total_height_mm'] = BASE_H_MM + MIX_LAYERS * MIX_H_MM
    stats['total_triangles'] = sum(stats.get(f'{m}_triangles', 0) for m in MATERIAL_ORDER)
    stats['total_vertices'] = sum(stats.get(f'{m}_vertices', 0) for m in MATERIAL_ORDER)
    return stats



def trim_axis_aligned_segment(seg: Tuple[float, float, float, float], trim_mm: float,
                              min_len_mm: float = MIN_TRIMMED_SEGMENT_MM) -> Optional[Tuple[float, float, float, float]]:
    """Shorten a generated model extrusion segment by a TOTAL endpoint trim.

    ``trim_mm`` is the total requested shortening of the physical road, not a
    per-end inset.  It is divided equally between the two true endpoints so the
    centre of the requested feature is preserved regardless of serpentine
    direction.  For example, ``trim_mm=0.075`` removes 0.0375 mm at the start
    and 0.0375 mm at the end.

    Tower, wipe, toolchange, and purge paths are unchanged because their
    geometry serves a different mechanical purpose.
    """
    trim_mm = max(0.0, float(trim_mm))
    x0, y0, x1, y1 = seg
    length = math.hypot(x1 - x0, y1 - y0)
    if trim_mm <= 0.0:
        return seg if length > min_len_mm else None

    each_end_mm = 0.5 * trim_mm
    new_len = length - trim_mm
    if new_len < min_len_mm:
        return None
    ux = (x1 - x0) / length
    uy = (y1 - y0) / length
    return (x0 + ux * each_end_mm, y0 + uy * each_end_mm,
            x1 - ux * each_end_mm, y1 - uy * each_end_mm)

def trim_model_segments(segs: Dict[str, List[Tuple[float, float, float, float]]], trim_mm: float,
                        min_len_mm: float = MIN_TRIMMED_SEGMENT_MM) -> Tuple[Dict[str, List[Tuple[float, float, float, float]]], Dict[str, int]]:
    """Apply symmetric endpoint-cap compensation to all model road segments.

    ``trim_mm`` is total road shortening and is split 50/50 between the two
    true endpoints by ``trim_axis_aligned_segment``.  Returns the trimmed
    segment dictionary plus per-material counts of skipped segments.  This
    deliberately runs after gap-closing so the trim is applied to the final
    model-road centreline geometry that will actually be emitted.
    """
    if trim_mm <= 0.0:
        return segs, {m: 0 for m in segs}
    out: Dict[str, List[Tuple[float, float, float, float]]] = {}
    skipped: Dict[str, int] = {}
    for mat, mat_segs in segs.items():
        kept = []
        skip = 0
        for seg in mat_segs:
            trimmed_xy = trim_axis_aligned_segment(seg_xy(seg), trim_mm, min_len_mm)
            trimmed = None if trimmed_xy is None else seg_with_xy(seg, trimmed_xy)
            if trimmed is None:
                skip += 1
            else:
                kept.append(trimmed)
        out[mat] = kept
        skipped[mat] = skip
    return out, skipped

def segment_length(seg):
    x0,y0,x1,y1 = seg_xy(seg)
    return math.hypot(x1-x0, y1-y0)

def material_layer_score(segments, short_threshold=1.0, total_weight=1.0, avg_weight=2.0, short_penalty=5.0):
    """Score a material's geometry on one physical layer for print-order selection.

    Higher score means this material is a better early-print candidate: lots of
    total length, generally longer/steadier segments, and fewer tiny fragile
    segments. This does not change recipes or geometry, only material order.
    """
    if not segments:
        return -1e30
    lengths = [segment_length(s) for s in segments]
    total = float(sum(lengths))
    avg = total / max(1, len(lengths))
    short_count = sum(1 for L in lengths if L < short_threshold)
    return total_weight * total + avg_weight * avg - short_penalty * short_count

def fc3d_on_off_enabled(value) -> bool:
    """Parse simple on/off command-line switches stored as strings."""
    return str(value).strip().lower() in ("1", "true", "yes", "on", "enable", "enabled")


def choose_material_print_order(segs, mode='fixed', base_order=None, previous_final=None, skip_absent: bool = False):
    """Return material order for one physical layer.

    fixed/canonical:
      keep the runtime active material order.

    stability-score:
      sort by broad/stable geometry score, with base-order tie-breaker.

    carryover:
      start this layer with the previous layer's final material when that
      material is present on this layer.  This avoids an H2C activation at the
      layer boundary whenever the material naturally carries over.

    skip_absent controls whether materials with no model roads on this layer are
    removed from the draw order.  The recipe/LUT/stack is not changed; only same-Z
    material emission order and sparse-layer material omission are affected.
    """
    if base_order is None:
        base_order = get_runtime_material_order()
    base_order = [m for m in list(base_order) if m in segs]
    present = [m for m in base_order if len(segs.get(m, [])) > 0]
    order = list(present if skip_absent else base_order)
    if not order:
        return []

    mode = 'fixed' if mode in (None, 'canonical') else str(mode)
    if mode == 'fixed':
        return order

    if mode == 'stability-score':
        canonical_idx = {m:i for i,m in enumerate(base_order)}
        return sorted(order, key=lambda m: (-material_layer_score(segs.get(m, [])), canonical_idx.get(m, 999)))

    if mode == 'carryover':
        # Only a genuinely present material can give the intended carryover win.
        if previous_final is not None and previous_final in order and previous_final in present:
            order = [previous_final] + [m for m in order if m != previous_final]
        return order

    raise ValueError(f"Unknown material draw-order mode {mode!r}")


def infer_xy_bbox_from_gcode(gcode: str) -> Optional[Tuple[float, float, float, float]]:
    xs: List[float] = []
    ys: List[float] = []
    for parsed in parse_gcode_lines(gcode.splitlines(), strict=True):
        if parsed.command not in ("G0", "G1"):
            continue
        # Ignore obvious parking/maintenance moves far above print. We only need
        # a plate bbox for Studio UI, not motion validation.
        x_word = parsed.optional_word("X")
        y_word = parsed.optional_word("Y")
        if x_word is not None and y_word is not None and x_word[1].numeric is not None and y_word[1].numeric is not None:
            xs.append(float(x_word[1].numeric))
            ys.append(float(y_word[1].numeric))
    if not xs or not ys:
        return None
    return (min(xs), min(ys), max(xs), max(ys))

def empty_direct_gcode_model_xml() -> bytes:
    """Minimal empty 3MF model so Studio cannot display reference geometry."""
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<model unit="millimeter" xml:lang="en-US" '
        'xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02">'
        '<metadata name="Application">FC3D direct G-code package</metadata>'
        '<resources></resources><build></build></model>'
    ).encode("utf-8")



_INVALID_H2C_TOOL_IDS = {1000, 1001, 65535, 65279}


def derive_raw_tool_sequence_from_m621(gcode: str, tool_map: Optional[Dict[str, int]] = None) -> List[int]:
    """Derive raw machine tool activation sequence from final emitted M621 only.

    PPSPV39 correction:
    The authoritative Bambu/H2C activation event in the final G-code is M621.
    Do not mix M620, T, and M621 records here, and do not compress repeated
    adjacent activations. The failed PPSPV38 file needed an initial repeated W
    activation represented as 5,5 in filament_sequence.sequence.
    """
    if tool_map is None:
        tool_map = DEFAULT_TOOL_MAP

    valid_raw_tools = {int(v) for v in tool_map.values()}
    seq: List[int] = []
    for parsed in parse_gcode_lines(gcode.splitlines(), strict=True):
        if parsed.command != "M621":
            continue
        optional = parsed.optional_word("S")
        if optional is None or optional[1].numeric is None:
            continue
        value = float(optional[1].numeric)
        if abs(value - round(value)) > 1e-9:
            raise RuntimeError(f"M621 at line {parsed.line_number} has non-integer S field")
        raw_tool = int(round(value))
        if raw_tool in _INVALID_H2C_TOOL_IDS:
            continue
        if raw_tool not in valid_raw_tools:
            raise RuntimeError(
                f"M621 at line {parsed.line_number} activates raw tool {raw_tool}, absent from the runtime material map"
            )
        seq.append(raw_tool)
    return seq


def derive_raw_tool_sequence_from_gcode(gcode: str, tool_map: Optional[Dict[str, int]] = None) -> List[int]:
    """Compatibility wrapper: PPSPV39 uses final emitted M621 events only."""
    return derive_raw_tool_sequence_from_m621(gcode, tool_map)


def derive_nozzle_sequence_from_gcode(gcode: str, tool_map: Optional[Dict[str, int]] = None) -> List[int]:
    """Derive compact emitted material/nozzle sequence from M621 raw activations.

    sequence        = raw machine tool id + 1
    nozzle_sequence = compact emitted material index, using current runtime order
                      W,F,R,Y,G,C,B when those materials are active.
    """
    if tool_map is None:
        tool_map = DEFAULT_TOOL_MAP

    raw_seq = derive_raw_tool_sequence_from_m621(gcode, tool_map)
    raw_set = {int(v) for v in raw_seq}
    # Build the compact sequence from the active emitted materials only. This keeps
    # Build compact logical indices from the actual active emitted material set.
    # With F active, F receives its own logical index rather than aliasing R/B.
    material_order = [m for m in get_runtime_material_order() if m in tool_map and int(tool_map[m]) in raw_set]
    raw_tool_to_logical = {int(tool_map[m]): i for i, m in enumerate(material_order) if m in tool_map}
    return [int(raw_tool_to_logical[v]) for v in raw_seq if int(v) in raw_tool_to_logical]


def _find_reference_optimal_assignment(obj: object) -> List[int]:
    """Return the first plausible full-slot optimal_assignment from copied metadata."""
    found: List[int] = []

    def walk(v: object) -> None:
        nonlocal found
        if found:
            return
        if isinstance(v, dict):
            oa = v.get("optimal_assignment")
            if isinstance(oa, list) and len(oa) >= 8 and all(isinstance(x, (int, float, str)) for x in oa):
                try:
                    found = [int(x) for x in oa]
                    return
                except Exception:
                    found = []
            for vv in v.values():
                walk(vv)
        elif isinstance(v, list):
            for item in v:
                walk(item)

    walk(obj)
    return found


def _default_h2c_optimal_assignment(tool_map: Dict[str, int]) -> List[int]:
    """Fallback inactive-slot-safe raw-tool-index -> physical head assignment.

    PPSPV41 active-only metadata keeps inactive/pseudo slots on head 0/unassigned
    unless a raw tool is actually present in the emitted M621 sequence. This avoids
    the PPSPV39 stale inactive raw8/F=head1 ambiguity while avoiding PPSPV40's full
    registry rewrite that the printer rejected.
    """
    max_raw = max([16] + [int(v) for v in tool_map.values()])
    return [0] * (max_raw + 1)


def _repair_optimal_assignment_for_used_raw_tools(ref_assignment: List[int], raw_seq: Sequence[int], tool_map: Dict[str, int]) -> List[int]:
    """Build a full-slot head map from active emitted M621 tools only."""
    max_raw = max([16] + [int(v) for v in tool_map.values()] + [int(v) for v in raw_seq])
    arr = [0] * (max_raw + 1)
    raw_to_mat = {int(v): str(k) for k, v in tool_map.items()}
    for raw in raw_seq:
        mat = raw_to_mat.get(int(raw), "")
        if mat:
            arr[int(raw)] = 0 if mat == "W" else 1
    return arr


def patch_filament_sequence_json_preserve_heads(data: bytes, gcode: str, tool_map: Optional[Dict[str, int]] = None) -> bytes:
    """Write clean H2C filament_sequence.json from final emitted M621 events.

    PPSPV39 correction:
    - sequence is derived from every final emitted M621 S<raw_tool> activation,
      preserving adjacent repeats, then stored as raw_tool + 1.
    - nozzle_sequence is derived from the same M621 raw sequence in compact
      emitted material order.
    - optimal_assignment is a full raw-filament-slot -> physical head map, not a
      per-activation list.
    - output is a clean reference-style {"plate_1": {...}} payload only.
    """
    if tool_map is None:
        tool_map = DEFAULT_TOOL_MAP

    raw_seq = derive_raw_tool_sequence_from_m621(gcode, tool_map)
    logical_seq = derive_nozzle_sequence_from_gcode(gcode, tool_map)
    if not raw_seq or not logical_seq:
        raise RuntimeError("Final parsed G-code produced an empty M621 filament/nozzle sequence")
    if len(raw_seq) != len(logical_seq):
        raise RuntimeError(
            f"Parsed M621 raw/nozzle sequence lengths disagree: raw={len(raw_seq)} logical={len(logical_seq)}"
        )

    raw_plus_one_seq = [int(v) + 1 for v in raw_seq]
    full_slot_assignment = _repair_optimal_assignment_for_used_raw_tools([], raw_seq, tool_map)
    plate_1 = {
        "sequence": list(raw_plus_one_seq),
        "nozzle_sequence": list(logical_seq),
        "optimal_assignment": list(full_slot_assignment),
        "fc3d_sequence_source": "derived_from_final_emitted_M621_events",
        "fc3d_sequence_rule": "sequence = every valid M621 S<raw_tool> event + 1; adjacent repeats preserved",
        "fc3d_nozzle_sequence_rule": "nozzle_sequence = compact emitted material/nozzle order mapped from the same M621 sequence",
        "fc3d_optimal_assignment_rule": "full slot-indexed H2C head map; raw tool slots unchanged; temperature M104 mapping is W/left=T1 and colours/right=T0",
        "fc3d_filtered_pseudo_tools": sorted(int(v) for v in _INVALID_H2C_TOOL_IDS),
        "fc3d_sequence_patched_by": PP_VERSION,
        "fc3d_sequence_patched_utc": datetime.now(timezone.utc).isoformat(),
    }
    return json.dumps({"plate_1": plate_1}, separators=(",", ":")).encode("utf-8")


