def audit_reference_head_metadata(template_path: Optional[Path] = None) -> None:
    """Parse and report head metadata from an explicit or embedded package."""
    source: object = Path(template_path) if template_path is not None else io.BytesIO(embedded_h2c_package_bytes())
    try:
        with zipfile.ZipFile(source, "r") as z:
            names = [name for name in z.namelist() if name.lower().endswith("filament_sequence.json")]
            if len(names) != 1:
                raise RuntimeError(f"expected one filament_sequence.json, found {len(names)}")
            name = names[0]
            obj = json.loads(z.read(name).decode("utf-8"))
    except Exception as exc:
        raise RuntimeError(f"Could not parse H2C head metadata: {exc}") from exc
    if not isinstance(obj, dict):
        raise RuntimeError("filament_sequence.json must contain a JSON object")
    plate = obj.get("plate_1", obj)
    if not isinstance(plate, dict):
        raise RuntimeError("filament_sequence.json plate_1 must be an object")
    print(f"Reference head metadata source: {'embedded package skeleton' if template_path is None else str(template_path)}::{name}")
    for key in ("nozzle_sequence", "optimal_assignment", "filament_map_mode"):
        if key in plate:
            print(f"Reference {key}: {json.dumps(plate[key], separators=(',', ':'))[:300]}")


def patch_project_settings_disable_reference_prime_tower(data: bytes, used_mats: Optional[Sequence[str]] = None, tool_map: Optional[Dict[str, int]] = None, build_plate: str = DEFAULT_BUILD_PLATE) -> bytes:
    """Disable stale reference tower metadata and declare active FC3D materials.

    The generated print uses the compact active subset of W,F,R,Y,G,C,B.
    The copied Bambu template can still carry old W,R,F,Y,G,C,B material metadata,
    so patch project_settings.config to record the active raw/one-based tool ids
    and disable stale reference tower/material assumptions.
    """
    try:
        txt = data.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise RuntimeError(f"Metadata/project_settings.config is not valid UTF-8: {exc}") from exc

    # project_settings.config is structured JSON.  v1.54 fails closed rather
    # than applying a text/regex fallback to malformed structured metadata.
    try:
        obj = json.loads(txt)
    except Exception as exc:
        raise RuntimeError(f"Metadata/project_settings.config is invalid JSON: {exc}") from exc
    if not isinstance(obj, dict):
        raise RuntimeError("Metadata/project_settings.config must contain a JSON object")

    if tool_map is None:
        tool_map = DEFAULT_TOOL_MAP
    if used_mats is None:
        used_mats = []
    used_mats = [str(m) for m in used_mats]
    plate_profile = get_build_plate_profile(build_plate)
    obj["curr_bed_type"] = str(plate_profile["display_name"])
    obj["fc3d_build_plate"] = str(build_plate)
    obj["fc3d_build_plate_plate_json_value"] = str(plate_profile["plate_json_value"])

    # Disable the reference tower/settings but keep dimensional values valid.
    for key, val in {
        "enable_prime_tower": "0",
        "enable_tower_interface_features": "0",
        "prime_tower_enable_framework": "0",
        "prime_tower_flat_ironing": "0",
        "prime_tower_fillet_wall": "0",
        "prime_tower_skip_points": "0",
        "wipe_tower_no_sparse_layers": "1",
        "filament_map_mode": "Manual",
        "enable_filament_dynamic_map": "0",
    }.items():
        if key in obj:
            obj[key] = val
    if str(obj.get("prime_tower_width", "2")).strip() in ("0", "0.0", "0.00"):
        obj["prime_tower_width"] = "2"

    active_raw = [int(tool_map[m]) for m in used_mats if m in tool_map]
    active_one = [v + 1 for v in active_raw]

    # Patch visible colour/material identity for active physical slots.  Project
    # settings arrays are generally indexed by raw zero-based tool id.
    per_slot_updates = {
        "filament_colour": FILAMENT_COLOURS,
        "filament_multi_colour": FILAMENT_COLOURS,
        "default_filament_colour": FILAMENT_COLOURS,
    }
    for key, colour_map in per_slot_updates.items():
        arr = obj.get(key)
        if isinstance(arr, list):
            for mat in used_mats:
                idx = int(tool_map.get(mat, -1))
                if 0 <= idx < len(arr):
                    arr[idx] = material_display_colour(mat)

    # pretending that logical F is active.
    for mat in used_mats:
        idx = int(tool_map.get(mat, -1))
        if idx < 0:
            continue
        _pp = polymer_profile_for_material(mat)
        _ptype = str(_pp["filament_type"]).upper()
        scalar_updates = {
            "filament_type": _ptype,
            "filament_settings_id": f"Generic {_ptype} @BBL H2C 0.4 nozzle",
            "filament_vendor": "Generic",
            "filament_ids": "GFG99",
            "filament_is_support": "0",
            "filament_soluble": "0",
            "filament_colour_type": "2",
            "nozzle_temperature": str(int(_pp["nozzle_temp_c"])),
            "nozzle_temperature_initial_layer": str(int(_pp["nozzle_temp_c"])),
            "textured_plate_temp": str(int(_pp["textured_bed_temp_c"])),
            "textured_plate_temp_initial_layer": str(int(_pp["textured_bed_temp_c"])),
            "filament_flow_ratio": f"{float(_pp['flow_ratio']):.2f}",
            "filament_pre_cooling_temperature_nc": str(int(_pp["standby_temp_c"])),
            "filament_cooling_before_tower": str(int(_pp["tower_cooling_delta_c"])),
            "additional_cooling_fan_speed": str(int(round((int(_pp["aux_fan_pwm"]) / 255.0) * 100.0))) if _pp.get("aux_fan_pwm") is not None else "0",
        }
        for key, val in scalar_updates.items():
            arr = obj.get(key)
            if not isinstance(arr, list):
                arr = [val] * max(17, idx + 1)
                obj[key] = arr
            elif idx >= len(arr):
                arr.extend([val] * (idx + 1 - len(arr)))
            arr[idx] = val

    # Keep project-level map arrays aligned too.  The proven Studio grouping fix
    # was slice_info/model_settings, but project_settings should no longer carry
    # stale F/tool-9 assumptions either.
    fmap, vmap, nmap = _metadata_map_arrays_for_used_materials(used_mats, tool_map)
    obj["filament_map"] = fmap
    obj["filament_volume_map"] = vmap
    obj["filament_nozzle_map"] = nmap
    obj["fc3d_active_logical_materials"] = list(used_mats)
    obj["fc3d_active_raw_tools"] = active_raw
    obj["fc3d_active_filament_one_based"] = active_one
    obj["fc3d_runtime_material_order"] = list(get_runtime_material_order())
    obj["fc3d_project_settings_patched_by"] = PP_VERSION
    obj["fc3d_project_settings_patched_utc"] = datetime.now(timezone.utc).isoformat()

    return json.dumps(obj, separators=(",", ":")).encode("utf-8")

def _metadata_preview_sample_uint8(preview_rgb: np.ndarray, out_size: int) -> np.ndarray:
    """Return a small uint8 RGB sample for embedded 3MF metadata thumbnails.

    PPSPV10: do not convert the full float32 preview image for metadata previews.
    On large 4x/near-native previews, np.clip(np.rint(full_float_rgb)) can require
    an extra full-size float allocation and fail on memory-limited Windows runs.
    Metadata thumbnails are at most 512 px, so first decimate to a small sample
    and only then convert to uint8.  This is intentionally for metadata previews
    only; full preview-image output still uses the normal output-boundary path.
    """
    a = np.asarray(preview_rgb)
    if a.ndim != 3 or a.shape[2] < 3:
        raise ValueError(f"preview_rgb must be HxWx3-ish, got shape {a.shape}")
    h, w = int(a.shape[0]), int(a.shape[1])
    if h <= 0 or w <= 0:
        return np.zeros((1, 1, 3), dtype=np.uint8)
    # Keep enough pixels for clean thumbnails after rotation, but avoid full-size
    # float temporary arrays.  For 512 metadata previews this caps the sample at
    # roughly 1024 px on the long side; for 128 previews roughly 256 px.
    sample_long_side = max(64, int(out_size) * 2)
    step = max(1, int(math.ceil(max(h, w) / float(sample_long_side))))
    sample = a[::step, ::step, :3]
    if sample.dtype == np.uint8:
        return np.ascontiguousarray(sample)
    # Convert only the small sample.  Avoid chained np.rint/np.clip temporaries.
    work = np.array(sample, dtype=np.float32, copy=True)
    np.nan_to_num(work, copy=False, nan=0.0, posinf=255.0, neginf=0.0)
    np.rint(work, out=work)
    np.clip(work, 0.0, 255.0, out=work)
    return work.astype(np.uint8, copy=False)


def make_isometric_metadata_preview(preview_rgb: np.ndarray, out_size: int = 512) -> bytes:
    """Create Bambu-style embedded RGBA preview PNG from the actual RP preview.

    Uses the reconstructed/expected printed RGB image, not per-layer colours and
    not the prime tower.  The image is rotated 45 degrees and vertically
    compressed to give an oblique/isometric-style view similar to Studio's plate
    thumbnail.  Output is PNG bytes at the requested metadata size.

    PPSPV10: downsample before uint8 conversion so repack cannot fail on a
    full-size preview_rgb allocation while only producing 512/128 px metadata.
    """
    arr = _metadata_preview_sample_uint8(preview_rgb, out_size)
    src = Image.fromarray(arr, "RGB").convert("RGBA")

    # Fit the square/rectangular print image so that after 45 degree rotation it
    # fills most of the metadata canvas without clipping.
    max_side = max(src.size)
    if max_side <= 0:
        src = Image.new("RGBA", (64, 64), (255, 255, 255, 0))
        max_side = 64
    pre_side = max(16, int(out_size * 0.62))
    scale = pre_side / float(max_side)
    new_size = (max(1, int(round(src.size[0] * scale))), max(1, int(round(src.size[1] * scale))))
    src = src.resize(new_size, Image.Resampling.LANCZOS)

    rot = src.rotate(45, expand=True, resample=Image.Resampling.BICUBIC)
    iso_h = max(1, int(round(rot.size[1] * 0.58)))
    top = rot.resize((rot.size[0], iso_h), Image.Resampling.LANCZOS)

    canvas = Image.new("RGBA", (out_size, out_size), (255, 255, 255, 0))

    # Add a subtle printed-card thickness/shadow under the top surface.
    shadow_alpha = top.getchannel("A").point(lambda a: int(a * 0.20))
    shadow = Image.new("RGBA", top.size, (0, 0, 0, 0))
    shadow.putalpha(shadow_alpha)

    x = (out_size - top.size[0]) // 2
    y = int(out_size * 0.18)
    canvas.alpha_composite(shadow, (x + max(1, out_size // 80), y + max(2, out_size // 45)))
    canvas.alpha_composite(top, (x, y))

    bio = io.BytesIO()
    canvas.save(bio, format="PNG")
    return bio.getvalue()



def _format_seconds_hms(seconds: float) -> str:
    seconds = max(0, int(round(float(seconds))))
    h = seconds // 3600
    m = (seconds % 3600) // 60
    s = seconds % 60
    if h:
        return f"{h}h{m:02d}m{s:02d}s"
    if m:
        return f"{m}m{s:02d}s"
    return f"{s}s"


def estimate_gcode_ballpark_time(
    gcode: str,
    tool_map: Dict[str, int],
    first_use_tool_overhead_sec: float = DEFAULT_TIME_ESTIMATE_FIRST_USE_TOOL_SEC,
    tool_activation_overhead_sec: float = DEFAULT_TIME_ESTIMATE_TOOL_ACTIVATION_SEC,
    fixed_overhead_sec: float = DEFAULT_TIME_ESTIMATE_FIXED_OVERHEAD_SEC,
    swap_model: str = "transition",
    repeat_right_to_left_sec: float = DEFAULT_TIME_ESTIMATE_REPEAT_RIGHT_TO_LEFT_SEC,
    repeat_left_to_right_sec: float = DEFAULT_TIME_ESTIMATE_REPEAT_LEFT_TO_RIGHT_SEC,
    repeat_right_to_right_sec: float = DEFAULT_TIME_ESTIMATE_REPEAT_RIGHT_TO_RIGHT_SEC,
    repeat_left_to_left_sec: float = DEFAULT_TIME_ESTIMATE_REPEAT_LEFT_TO_LEFT_SEC,
    motion_model: str = "accel",
    default_print_accel_mm_s2: float = DEFAULT_TIME_ESTIMATE_DEFAULT_PRINT_ACCEL_MM_S2,
    default_travel_accel_mm_s2: float = DEFAULT_TIME_ESTIMATE_DEFAULT_TRAVEL_ACCEL_MM_S2,
    default_retract_accel_mm_s2: float = DEFAULT_TIME_ESTIMATE_DEFAULT_RETRACT_ACCEL_MM_S2,
    default_junction_speed_mm_s: float = DEFAULT_TIME_ESTIMATE_DEFAULT_JUNCTION_SPEED_MM_S,
) -> Dict[str, object]:
    """Estimate emitted G-code time with activation phases and motion planning.

    PPSPV45 timing model:
    - Movement inside FC3D_TIME_TOOL_ACTIVATION_BEGIN/END blocks is excluded;
      measured activation timings cover that whole phase up to prime-tower print.
    - H2C repeat activation time can be transition-aware by physical head.
    - Normal movement outside activation blocks can be timed either naively
      (distance/feedrate) or by a practical acceleration-aware triangle/trapezoid
      estimate using parsed M204/M201/M203/M205 state and simple junction carry.

    This is still ball-park only: it is not a full Bambu Studio planner clone.
    """
    active_raw_tools = {int(v) for v in tool_map.values()}
    raw_to_mat = {int(v): str(k) for k, v in tool_map.items()}

    def head_for_raw(raw: Optional[int]) -> Optional[str]:
        if raw is None:
            return None
        mat = raw_to_mat.get(int(raw), "")
        if not mat:
            return None
        return "left" if mat == "W" else "right"

    absolute_xyz = True
    absolute_e = False
    x = y = z = e = None
    feed_mm_min = None
    current_tool: Optional[int] = None

    # Defaults are deliberately conservative/tunable.  They are updated when the
    # emitted G-code contains M201/M203/M204/M205 commands.
    max_feed = {"X": 1000.0, "Y": 1000.0, "Z": 30.0, "E": 50.0}  # mm/s
    max_accel = {"X": 20000.0, "Y": 20000.0, "Z": 500.0, "E": 5000.0}  # mm/s^2
    print_accel = float(default_print_accel_mm_s2)
    travel_accel = float(default_travel_accel_mm_s2)
    retract_accel = float(default_retract_accel_mm_s2)
    junction_xy = float(default_junction_speed_mm_s)
    junction_e = 2.5

    naive_move_seconds = 0.0
    accel_move_seconds = 0.0
    skipped_activation_move_seconds = 0.0
    skipped_activation_move_seconds_accel = 0.0
    xy_distance_mm = 0.0
    z_distance_mm = 0.0
    xyz_distance_mm = 0.0
    e_abs_mm = 0.0
    extrusion_xy_distance_mm = 0.0
    travel_xy_distance_mm = 0.0
    g0g1_moves = 0
    skipped_activation_moves = 0
    extrusion_moves = 0
    travel_moves = 0
    e_only_moves = 0
    feed_missing_moves = 0
    feed_zero_moves = 0
    feed_time_by_rounded: Dict[str, float] = {}
    accel_time_by_class: Dict[str, float] = {}
    naive_time_by_class: Dict[str, float] = {}
    length_buckets = [0.05, 0.10, 0.20, 0.50, 1.00, 2.00, 5.00, 10.00, 25.00]
    bucket_stats: Dict[str, Dict[str, float]] = {}

    begin_re = re.compile(r'^\s*;\s*FC3D_TIME_TOOL_ACTIVATION_BEGIN\b(.*)$')
    end_re = re.compile(r'^\s*;\s*FC3D_TIME_TOOL_ACTIVATION_END\b(.*)$')
    attr_re = re.compile(r'([A-Za-z_]+)=([^ ]+)')

    activation_open: Optional[Dict[str, object]] = None
    activations: List[Dict[str, object]] = []
    move_records: List[Dict[str, object]] = []
    skipped_records: List[Dict[str, object]] = []

    def parse_attrs(txt: str) -> Dict[str, str]:
        return {m.group(1): m.group(2) for m in attr_re.finditer(txt or "")}

    def update_machine_state(parsed: ParsedGCodeLine) -> None:
        nonlocal print_accel, travel_accel, retract_accel, junction_xy, junction_e
        vals = parsed.numeric_parameters()
        if not vals:
            return
        cmd = str(parsed.command or "")
        if cmd == "M201":
            for ax in ("X", "Y", "Z", "E"):
                if ax in vals and vals[ax] > 0:
                    max_accel[ax] = float(vals[ax])
        elif cmd == "M203":
            for ax in ("X", "Y", "Z", "E"):
                if ax in vals and vals[ax] > 0:
                    max_feed[ax] = float(vals[ax])
        elif cmd == "M204":
            # Bambu/Marlin variants: S is generic/default, P print, T travel,
            # R retract.  PPSP emits M204 S8000 frequently; treat S as current
            # XY print/travel acceleration unless explicit P/T override follows.
            if "S" in vals and vals["S"] > 0:
                print_accel = float(vals["S"])
                travel_accel = float(vals["S"])
            if "P" in vals and vals["P"] > 0:
                print_accel = float(vals["P"])
            if "T" in vals and vals["T"] > 0:
                travel_accel = float(vals["T"])
            if "R" in vals and vals["R"] > 0:
                retract_accel = float(vals["R"])
        elif cmd == "M205":
            xy_vals = [vals[k] for k in ("X", "Y") if k in vals and vals[k] > 0]
            if xy_vals:
                junction_xy = float(min(xy_vals))
            if "E" in vals and vals["E"] > 0:
                junction_e = float(vals["E"])

    def capped_feed_mm_s(feed: Optional[float], dx: float, dy: float, dz: float, de: float, dist: float, e_only: bool) -> Optional[float]:
        if feed is None or feed <= 0.0 or dist <= 0.0:
            return None
        v = float(feed) / 60.0
        if e_only:
            return min(v, max_feed.get("E", v))
        # Limit vector velocity so no individual axis exceeds its max feed.
        for ax, d in (("X", dx), ("Y", dy), ("Z", dz)):
            ad = abs(float(d))
            if ad > 1e-12:
                v = min(v, max_feed.get(ax, v) * dist / ad)
        return max(1e-9, v)

    def classify_move(xy: float, dz: float, de: float, e_only: bool) -> str:
        if e_only:
            return "e_retract" if de < 0 else ("e_prime" if de > 0 else "e_only")
        if xy > 0.0 and de > 0.0:
            return "extrusion_xy"
        if xy > 0.0:
            return "travel_xy"
        if abs(dz) > 0.0:
            return "z_only"
        return "other"

    def accel_for_move(cls: str) -> float:
        if cls == "extrusion_xy":
            return max(1.0, float(print_accel))
        if cls in ("e_retract", "e_prime", "e_only"):
            return max(1.0, float(retract_accel))
        if cls == "z_only":
            return max(1.0, float(max_accel.get("Z", 500.0)))
        return max(1.0, float(travel_accel))

    def time_one_motion(parsed: ParsedGCodeLine, lineno: int) -> Tuple[float, Dict[str, object]]:
        nonlocal absolute_xyz, absolute_e, x, y, z, e, feed_mm_min, current_tool
        cmd = str(parsed.command or "")
        if cmd == "G90":
            absolute_xyz = True
            return 0.0, {}
        if cmd == "G91":
            absolute_xyz = False
            return 0.0, {}
        if cmd == "M82":
            absolute_e = True
            return 0.0, {}
        if cmd == "M83":
            absolute_e = False
            return 0.0, {}
        if cmd == "G92":
            vals = parsed.numeric_parameters()
            if "X" in vals: x = vals["X"]
            if "Y" in vals: y = vals["Y"]
            if "Z" in vals: z = vals["Z"]
            if "E" in vals: e = vals["E"]
            return 0.0, {}
        if cmd == "T":
            optional = parsed.optional_word("@TOOL")
            if optional is not None and optional[1].numeric is not None:
                current_tool = int(round(float(optional[1].numeric)))
            return 0.0, {}
        if cmd in ("M201", "M203", "M204", "M205"):
            update_machine_state(parsed)
            return 0.0, {}
        if cmd not in ("G0", "G00", "G1", "G01"):
            return 0.0, {}

        vals = parsed.numeric_parameters()
        if "F" in vals:
            feed_mm_min = float(vals["F"])
        if not any(k in vals for k in ("X", "Y", "Z", "E")):
            return 0.0, {}

        old_x, old_y, old_z, old_e = x, y, z, e
        nx, ny, nz, ne = x, y, z, e
        if "X" in vals:
            nx = vals["X"] if absolute_xyz or x is None else x + vals["X"]
        if "Y" in vals:
            ny = vals["Y"] if absolute_xyz or y is None else y + vals["Y"]
        if "Z" in vals:
            nz = vals["Z"] if absolute_xyz or z is None else z + vals["Z"]
        if "E" in vals:
            ne = vals["E"] if absolute_e or e is None else (0.0 if e is None else e) + vals["E"]

        dx = 0.0 if old_x is None or nx is None else float(nx - old_x)
        dy = 0.0 if old_y is None or ny is None else float(ny - old_y)
        dz = 0.0 if old_z is None or nz is None else float(nz - old_z)
        de = 0.0
        if "E" in vals:
            if absolute_e:
                de = 0.0 if old_e is None or ne is None else float(ne - old_e)
            else:
                de = float(vals["E"])

        xy = math.hypot(dx, dy)
        xyz = math.sqrt(dx * dx + dy * dy + dz * dz)
        dist = xyz
        e_only = False
        if dist <= 0.0 and "E" in vals:
            dist = abs(de)
            e_only = True

        x, y, z, e = nx, ny, nz, ne

        feed_missing = False
        feed_zero = False
        v = capped_feed_mm_s(feed_mm_min, dx, dy, dz, de, dist, e_only)
        dt_naive = 0.0
        if dist > 0.0:
            if feed_mm_min is None:
                feed_missing = True
            elif feed_mm_min <= 0.0 or v is None:
                feed_zero = True
            else:
                dt_naive = dist / float(v)

        cls = classify_move(xy, dz, de, e_only)
        return dt_naive, {
            "line": int(lineno),
            "dist": float(dist),
            "xy": float(xy),
            "xyz": float(xyz),
            "dx": float(dx),
            "dy": float(dy),
            "dz": float(dz),
            "dz_abs": float(abs(dz)),
            "de_abs": float(abs(de)),
            "de": float(de),
            "e_only": bool(e_only),
            "feed": None if feed_mm_min is None else float(feed_mm_min),
            "v_mm_s": None if v is None else float(v),
            "feed_missing": bool(feed_missing),
            "feed_zero": bool(feed_zero),
            "class": cls,
            "accel_mm_s2": float(accel_for_move(cls)),
            "junction_xy_mm_s": float(junction_xy),
            "junction_e_mm_s": float(junction_e),
            "current_tool": None if current_tool is None else int(current_tool),
            "naive_sec": float(dt_naive),
        }

    def bucket_key(length: float) -> str:
        last = 0.0
        for b in length_buckets:
            if length < b:
                return f"{last:.2f}-{b:.2f}mm"
            last = b
        return f">={length_buckets[-1]:.2f}mm"

    def can_blend(a: Dict[str, object], b: Dict[str, object]) -> bool:
        if float(a.get("xy", 0.0)) <= 1e-9 or float(b.get("xy", 0.0)) <= 1e-9:
            return False
        if abs(float(a.get("dz", 0.0))) > 1e-9 or abs(float(b.get("dz", 0.0))) > 1e-9:
            return False
        if a.get("class") != b.get("class"):
            return False
        if a.get("class") not in ("extrusion_xy", "travel_xy"):
            return False
        if a.get("current_tool") != b.get("current_tool"):
            return False
        if a.get("v_mm_s") is None or b.get("v_mm_s") is None:
            return False
        return True

    def junction_speed(a: Dict[str, object], b: Dict[str, object]) -> float:
        if not can_blend(a, b):
            return 0.0
        ax, ay = float(a["dx"]), float(a["dy"])
        bx, by = float(b["dx"]), float(b["dy"])
        la, lb = float(a["xy"]), float(b["xy"])
        if la <= 0 or lb <= 0:
            return 0.0
        dot = max(-1.0, min(1.0, (ax * bx + ay * by) / (la * lb)))
        vmin = min(float(a.get("v_mm_s") or 0.0), float(b.get("v_mm_s") or 0.0))
        jerk = min(float(a.get("junction_xy_mm_s", default_junction_speed_mm_s)), float(b.get("junction_xy_mm_s", default_junction_speed_mm_s)))
        if dot > 0.9995:
            return vmin
        # Classic-jerk style approximation: for equal speeds, velocity change at
        # a corner is v*sqrt(2*(1-dot)). Keep that below the parsed M205 X/Y jerk.
        denom = math.sqrt(max(1e-9, 2.0 * (1.0 - dot)))
        return max(0.0, min(vmin, jerk / denom))

    def trapezoid_time(length: float, v_target: float, accel: float, v_in: float, v_out: float) -> float:
        L = max(0.0, float(length))
        v = max(1e-9, float(v_target))
        a = max(1.0, float(accel))
        vin = max(0.0, min(float(v_in), v))
        vout = max(0.0, min(float(v_out), v))
        if L <= 0.0:
            return 0.0
        d_acc = max(0.0, (v * v - vin * vin) / (2.0 * a))
        d_dec = max(0.0, (v * v - vout * vout) / (2.0 * a))
        if d_acc + d_dec <= L:
            return (v - vin) / a + (v - vout) / a + (L - d_acc - d_dec) / v
        vp2 = max(vin * vin, vout * vout, 0.5 * (2.0 * a * L + vin * vin + vout * vout))
        vp = math.sqrt(max(0.0, vp2))
        return max(0.0, (vp - vin) / a) + max(0.0, (vp - vout) / a)

    def estimate_accel_time(records: Sequence[Dict[str, object]]) -> Tuple[float, List[float]]:
        if not records:
            return 0.0, []
        exits = [0.0] * len(records)
        for i in range(len(records) - 1):
            exits[i] = junction_speed(records[i], records[i + 1])
        per = []
        total = 0.0
        for i, rec in enumerate(records):
            L = float(rec.get("dist", 0.0))
            v = rec.get("v_mm_s")
            if L <= 0.0 or v is None:
                per.append(0.0)
                continue
            vin = exits[i - 1] if i > 0 and can_blend(records[i - 1], rec) else 0.0
            vout = exits[i]
            dt = trapezoid_time(L, float(v), float(rec.get("accel_mm_s2", default_print_accel_mm_s2)), vin, vout)
            per.append(float(dt))
            total += float(dt)
        return float(total), per

    # First pass: parse movement, machine-limit state and activation blocks.
    for lineno, raw_line in enumerate(gcode.splitlines(), 1):
        stripped = raw_line.strip()
        mb = begin_re.match(stripped)
        if mb:
            attrs = parse_attrs(mb.group(1))
            activation_open = {
                "raw_tool": int(attrs.get("raw_tool", "-1")),
                "one_based_filament": int(attrs.get("one_based_filament", "0")),
                "material": str(attrs.get("material", "")),
                "first_use": str(attrs.get("first_use", "false")).lower() in ("1", "true", "yes", "on"),
                "skipped_move_seconds": 0.0,
                "skipped_move_seconds_accel": 0.0,
                "skipped_g0g1_moves": 0,
            }
            continue
        me = end_re.match(stripped)
        if me and activation_open is not None:
            activations.append(dict(activation_open))
            activation_open = None
            continue

        parsed = parse_gcode_line(raw_line, lineno, strict=True)
        if parsed.command is None:
            continue

        dt_naive, metrics = time_one_motion(parsed, lineno)
        if not metrics:
            continue
        if metrics.get("dist", 0.0) <= 0.0:
            continue

        if activation_open is not None:
            activation_open["skipped_move_seconds"] = float(activation_open.get("skipped_move_seconds", 0.0)) + dt_naive
            activation_open["skipped_g0g1_moves"] = int(activation_open.get("skipped_g0g1_moves", 0)) + 1
            skipped_activation_move_seconds += dt_naive
            skipped_activation_moves += 1
            skipped_records.append(metrics)
            continue

        move_records.append(metrics)
        g0g1_moves += 1
        xy = float(metrics.get("xy", 0.0))
        xy_distance_mm += xy
        z_distance_mm += float(metrics.get("dz_abs", 0.0))
        xyz_distance_mm += float(metrics.get("xyz", 0.0))
        e_abs_mm += float(metrics.get("de_abs", 0.0))
        if metrics.get("e_only"):
            e_only_moves += 1

        de = float(metrics.get("de", 0.0))
        if de > 0.0 and xy > 0.0:
            extrusion_moves += 1
            extrusion_xy_distance_mm += xy
        elif xy > 0.0:
            travel_moves += 1
            travel_xy_distance_mm += xy

        if metrics.get("feed_missing"):
            feed_missing_moves += 1
        elif metrics.get("feed_zero"):
            feed_zero_moves += 1
        else:
            naive_move_seconds += dt_naive
            cls = str(metrics.get("class", "other"))
            naive_time_by_class[cls] = float(naive_time_by_class.get(cls, 0.0) + dt_naive)
            feed = metrics.get("feed")
            if feed is not None:
                fkey = str(int(round(float(feed))))
                feed_time_by_rounded[fkey] = float(feed_time_by_rounded.get(fkey, 0.0) + dt_naive)

    accel_move_seconds, accel_per_move = estimate_accel_time(move_records)
    skipped_activation_move_seconds_accel, _skipped_accel_per = estimate_accel_time(skipped_records)

    for rec, acc_dt in zip(move_records, accel_per_move):
        cls = str(rec.get("class", "other"))
        accel_time_by_class[cls] = float(accel_time_by_class.get(cls, 0.0) + acc_dt)
        key = bucket_key(float(rec.get("dist", 0.0)))
        b = bucket_stats.setdefault(key, {"moves": 0, "distance_mm": 0.0, "naive_sec": 0.0, "accel_sec": 0.0})
        b["moves"] += 1
        b["distance_mm"] += float(rec.get("dist", 0.0))
        b["naive_sec"] += float(rec.get("naive_sec", 0.0))
        b["accel_sec"] += float(acc_dt)

    # Backfill approximate skipped accel timing into open-block records for diagnostics.
    skipped_iter = iter(_skipped_accel_per)
    for a in activations:
        # Per-block exact skipped accel is diagnostic only; keeping the old naive
        # per-block value avoids extra bookkeeping inside activation blocks.
        a["skipped_move_seconds_accel_note"] = "overall skipped_activation_move_time_accel_sec is reported globally"

    if str(motion_model).lower() == "naive":
        move_seconds = float(naive_move_seconds)
        chosen_motion_model = "naive_feedrate"
    else:
        move_seconds = float(accel_move_seconds)
        chosen_motion_model = "accel_trapezoid_junction"

    first_use_activations = [a for a in activations if bool(a.get("first_use"))]
    repeat_activations = [a for a in activations if not bool(a.get("first_use"))]
    first_use_overhead_sec = float(len(first_use_activations)) * float(first_use_tool_overhead_sec)

    transition_counts: Dict[str, int] = {"right_to_left": 0, "left_to_right": 0, "right_to_right": 0, "left_to_left": 0, "unknown": 0}
    transition_seconds: Dict[str, float] = {k: 0.0 for k in transition_counts}
    activation_events_enriched: List[Dict[str, object]] = []
    prev_raw: Optional[int] = None
    for idx, a in enumerate(activations):
        raw = int(a.get("raw_tool", -1))
        first = bool(a.get("first_use"))
        prev_head = head_for_raw(prev_raw)
        target_head = head_for_raw(raw)
        applied = 0.0
        trans = "first_use" if first else "unknown"
        if first:
            applied = float(first_use_tool_overhead_sec)
        elif str(swap_model).lower() == "flat":
            trans = "flat_repeat"
            applied = float(tool_activation_overhead_sec)
        else:
            if prev_head == "right" and target_head == "left":
                trans = "right_to_left"; applied = float(repeat_right_to_left_sec)
            elif prev_head == "left" and target_head == "right":
                trans = "left_to_right"; applied = float(repeat_left_to_right_sec)
            elif prev_head == "right" and target_head == "right":
                trans = "right_to_right"; applied = float(repeat_right_to_right_sec)
            elif prev_head == "left" and target_head == "left":
                trans = "left_to_left"; applied = float(repeat_left_to_left_sec)
            else:
                trans = "unknown"; applied = float(tool_activation_overhead_sec)
            transition_counts[trans] = int(transition_counts.get(trans, 0) + 1)
            transition_seconds[trans] = float(transition_seconds.get(trans, 0.0) + applied)
        ev = dict(a)
        ev.update({
            "activation_index": int(idx),
            "previous_raw_tool": None if prev_raw is None else int(prev_raw),
            "previous_head": prev_head,
            "target_head": target_head,
            "timing_transition": trans,
            "applied_time_sec": float(applied),
        })
        activation_events_enriched.append(ev)
        prev_raw = raw

    if str(swap_model).lower() == "flat":
        repeat_activation_overhead_sec = float(len(repeat_activations)) * float(tool_activation_overhead_sec)
        transition_counts["flat_repeat"] = int(len(repeat_activations))
        transition_seconds["flat_repeat"] = float(repeat_activation_overhead_sec)
    else:
        repeat_activation_overhead_sec = float(sum(float(ev.get("applied_time_sec", 0.0)) for ev in activation_events_enriched if not bool(ev.get("first_use"))))

    total_sec = float(move_seconds) + first_use_overhead_sec + repeat_activation_overhead_sec + float(fixed_overhead_sec)

    active_raw_tools_seen = sorted({int(a.get("raw_tool", -1)) for a in activations if int(a.get("raw_tool", -1)) in active_raw_tools})
    return {
        "schema": "fc3d_ballpark_gcode_time_estimate_v3_transition_accel",
        "script_version": SCRIPT_VERSION,
        "revision_intent": REVISION_INTENT,
        "important_note": "Ball-park estimate. Movement inside FC3D_TIME_TOOL_ACTIVATION_BEGIN/END blocks is deliberately excluded because first-use/repeat activation settings are defined to include head fetch/load/purge/wipe/travel up to prime-tower extrusion. Motion model is acceleration-aware but not a full Bambu Studio planner clone.",
        "settings": {
            "first_use_tool_sec": float(first_use_tool_overhead_sec),
            "tool_activation_sec_flat_fallback": float(tool_activation_overhead_sec),
            "swap_model": str(swap_model),
            "repeat_right_to_left_sec": float(repeat_right_to_left_sec),
            "repeat_left_to_right_sec": float(repeat_left_to_right_sec),
            "repeat_right_to_right_sec": float(repeat_right_to_right_sec),
            "repeat_left_to_left_sec": float(repeat_left_to_left_sec),
            "motion_model": str(motion_model),
            "chosen_motion_model": chosen_motion_model,
            "default_print_accel_mm_s2": float(default_print_accel_mm_s2),
            "default_travel_accel_mm_s2": float(default_travel_accel_mm_s2),
            "default_retract_accel_mm_s2": float(default_retract_accel_mm_s2),
            "default_junction_speed_mm_s": float(default_junction_speed_mm_s),
            "fixed_overhead_sec": float(fixed_overhead_sec),
        },
        "counts": {
            "total_tool_activations": int(len(activations)),
            "first_use_tool_activations": int(len(first_use_activations)),
            "repeat_tool_activations": int(len(repeat_activations)),
            "active_raw_tools_seen": active_raw_tools_seen,
            "unique_active_raw_tools_seen": int(len(active_raw_tools_seen)),
            "transition_counts": {k: int(v) for k, v in sorted(transition_counts.items())},
        },
        "seconds": {
            "printing_move_time_excluding_activation_blocks_sec": float(move_seconds),
            "printing_move_time_naive_feedrate_sec": float(naive_move_seconds),
            "printing_move_time_accel_sec": float(accel_move_seconds),
            "short_move_accel_added_sec": float(accel_move_seconds - naive_move_seconds),
            "skipped_activation_move_time_sec": float(skipped_activation_move_seconds),
            "skipped_activation_move_time_accel_sec": float(skipped_activation_move_seconds_accel),
            "first_use_overhead_sec": float(first_use_overhead_sec),
            "repeat_activation_overhead_sec": float(repeat_activation_overhead_sec),
            "fixed_overhead_sec": float(fixed_overhead_sec),
            "total_ballpark_sec": float(total_sec),
            "transition_seconds": {k: float(v) for k, v in sorted(transition_seconds.items())},
        },
        "formatted": {
            "printing_move_time_excluding_activation_blocks": _format_seconds_hms(move_seconds),
            "printing_move_time_naive_feedrate": _format_seconds_hms(naive_move_seconds),
            "printing_move_time_accel": _format_seconds_hms(accel_move_seconds),
            "short_move_accel_added": _format_seconds_hms(accel_move_seconds - naive_move_seconds),
            "skipped_activation_move_time": _format_seconds_hms(skipped_activation_move_seconds),
            "skipped_activation_move_time_accel": _format_seconds_hms(skipped_activation_move_seconds_accel),
            "first_use_overhead": _format_seconds_hms(first_use_overhead_sec),
            "repeat_activation_overhead": _format_seconds_hms(repeat_activation_overhead_sec),
            "fixed_overhead": _format_seconds_hms(fixed_overhead_sec),
            "total_ballpark": _format_seconds_hms(total_sec),
        },
        "motion": {
            "g0g1_timed_moves_outside_activation_blocks": int(g0g1_moves),
            "skipped_g0g1_moves_inside_activation_blocks": int(skipped_activation_moves),
            "extrusion_xy_moves": int(extrusion_moves),
            "travel_xy_moves": int(travel_moves),
            "e_only_moves": int(e_only_moves),
            "xy_distance_mm": float(xy_distance_mm),
            "xyz_distance_mm": float(xyz_distance_mm),
            "z_abs_distance_mm": float(z_distance_mm),
            "extrusion_xy_distance_mm": float(extrusion_xy_distance_mm),
            "travel_xy_distance_mm": float(travel_xy_distance_mm),
            "e_abs_mm": float(e_abs_mm),
            "feed_missing_moves": int(feed_missing_moves),
            "feed_zero_moves": int(feed_zero_moves),
            "final_parsed_limits": {
                "max_feed_mm_s": {k: float(v) for k, v in sorted(max_feed.items())},
                "max_accel_mm_s2": {k: float(v) for k, v in sorted(max_accel.items())},
                "print_accel_mm_s2": float(print_accel),
                "travel_accel_mm_s2": float(travel_accel),
                "retract_accel_mm_s2": float(retract_accel),
                "junction_xy_mm_s": float(junction_xy),
                "junction_e_mm_s": float(junction_e),
            },
        },
        "motion_time_seconds_by_class": {k: float(v) for k, v in sorted(accel_time_by_class.items())},
        "motion_naive_time_seconds_by_class": {k: float(v) for k, v in sorted(naive_time_by_class.items())},
        "motion_length_buckets": {k: {kk: float(vv) if kk != "moves" else int(vv) for kk, vv in v.items()} for k, v in sorted(bucket_stats.items())},
        "activation_events": activation_events_enriched[:250],
        "feed_time_seconds_by_rounded_mm_min": {k: float(v) for k, v in sorted(feed_time_by_rounded.items(), key=lambda kv: int(kv[0]))},
    }

def build_metadata_preview_replacements(preview_rgb: Optional[np.ndarray]) -> Dict[str, bytes]:
    if preview_rgb is None:
        return {}
    # PPSPV10: generate each thumbnail size once and reuse the bytes for multiple
    # metadata names.  This avoids repeated sample/convert/rotate work and keeps
    # peak memory low during repack.
    preview_512 = make_isometric_metadata_preview(preview_rgb, 512)
    preview_128 = make_isometric_metadata_preview(preview_rgb, 128)
    return {
        "metadata/plate_1.png": preview_512,
        "metadata/plate_no_light_1.png": preview_512,
        "metadata/top_1.png": preview_512,
        "metadata/pick_1.png": preview_512,
        "metadata/plate_1_small.png": preview_128,
    }


def _time_estimate_total_seconds(time_estimate: Optional[Dict[str, object]]) -> Optional[float]:
    if not isinstance(time_estimate, dict):
        return None
    seconds = time_estimate.get("seconds")
    if isinstance(seconds, dict):
        for key in ("total_ballpark_sec", "total_sec", "total_seconds"):
            if key in seconds:
                try:
                    return float(seconds[key])
                except Exception:
                    pass
    for key in ("total_ballpark_sec", "total_sec", "total_seconds"):
        if key in time_estimate:
            try:
                return float(time_estimate[key])
            except Exception:
                pass
    return None


def _format_bambu_comment_time(seconds: float) -> str:
    seconds_i = max(0, int(round(float(seconds))))
    h = seconds_i // 3600
    m = (seconds_i % 3600) // 60
    s = seconds_i % 60
    if h:
        return f"{h}h {m}m {s}s"
    if m:
        return f"{m}m {s}s"
    return f"{s}s"


def _m73_remaining_minutes_for_percent(total_seconds: float, percent: float) -> int:
    """Return Bambu/Marlin M73 R minutes from total estimate and percent complete."""
    total_minutes = max(0.0, float(total_seconds) / 60.0)
    remaining = total_minutes * max(0.0, min(100.0, 100.0 - float(percent))) / 100.0
    # Bambu's inherited reference used integer minutes. Use floor to mirror
    # 6h12m27s -> R372 rather than R373.
    return max(0, int(math.floor(remaining + 1e-9)))


def _m73_pr_line(line: str) -> bool:
    """True for executable M73 P... R... progress-time lines, not M73.2/L/E."""
    parsed = parse_gcode_line(str(line), 0, strict=True)
    if parsed.command != "M73":
        return False
    return parsed.optional_word("P") is not None and parsed.optional_word("R") is not None


def _fc3d_trace_safe_m73_sites(lines: Sequence[str], total_seconds: float) -> Tuple[List[Tuple[int, float]], Dict[str, object]]:
    """Second-pass cumulative-time walk for M73 progress insertion.

    Returns safe insertion sites as (line_index, scaled_elapsed_seconds).  The
    line_index is an index before which it is safe to insert M73 P/R.  The
    elapsed time is based on a real pass through the final G-code:
      - outside activation blocks: G0/G1 motion time from parsed positions/feed
      - activation blocks: add FC3D first-use / transition overhead at block end
      - unsafe blocks: no M73 emitted inside the block; accumulated elapsed time
        is reported at the next safe normal G0/G1 line.

    The raw cumulative trace is scaled to the already-computed PPSP total time
    so the progress stream agrees with the published ball-park estimate even
    though this trace uses a lighter planner than estimate_gcode_ballpark_time.
    """
    total = max(1.0, float(total_seconds))

    abs_xyz = True
    abs_e = False
    x = y = z = e = None
    feed_mm_min = None

    activation_open = False
    activation_attrs: Dict[str, str] = {}
    prev_head: Optional[str] = None

    begin_re = re.compile(r"^\s*;\s*FC3D_TIME_TOOL_ACTIVATION_BEGIN\b(.*)$")
    end_re = re.compile(r"^\s*;\s*FC3D_TIME_TOOL_ACTIVATION_END\b")
    attr_re = re.compile(r"([A-Za-z_]+)=([^ ]+)")

    safe_elapsed_raw: List[Tuple[int, float]] = []
    raw_elapsed = 0.0
    motion_seconds = 0.0
    activation_seconds = 0.0
    safe_sites = 0
    activation_count = 0

    def parse_attrs(txt: str) -> Dict[str, str]:
        return {m.group(1): m.group(2) for m in attr_re.finditer(txt or "")}

    def head_for_material(material: str) -> Optional[str]:
        mat = str(material or "").upper()
        if not mat:
            return None
        return "left" if mat == "W" else "right"

    def activation_overhead(attrs: Dict[str, str]) -> float:
        nonlocal prev_head, activation_count
        activation_count += 1
        first = str(attrs.get("first_use", "false")).lower() in ("1", "true", "yes", "on")
        target_head = head_for_material(str(attrs.get("material", "")))
        if first:
            applied = float(DEFAULT_TIME_ESTIMATE_FIRST_USE_TOOL_SEC)
        else:
            if prev_head == "right" and target_head == "left":
                applied = float(DEFAULT_TIME_ESTIMATE_REPEAT_RIGHT_TO_LEFT_SEC)
            elif prev_head == "left" and target_head == "right":
                applied = float(DEFAULT_TIME_ESTIMATE_REPEAT_LEFT_TO_RIGHT_SEC)
            elif prev_head == "right" and target_head == "right":
                applied = float(DEFAULT_TIME_ESTIMATE_REPEAT_RIGHT_TO_RIGHT_SEC)
            elif prev_head == "left" and target_head == "left":
                applied = float(DEFAULT_TIME_ESTIMATE_REPEAT_LEFT_TO_LEFT_SEC)
            else:
                applied = float(DEFAULT_TIME_ESTIMATE_TOOL_ACTIVATION_SEC)
        if target_head is not None:
            prev_head = target_head
        return max(0.0, float(applied))

    def update_elapsed_for_line(parsed: ParsedGCodeLine) -> float:
        nonlocal abs_xyz, abs_e, x, y, z, e, feed_mm_min
        cmd = str(parsed.command or "")
        if not cmd:
            return 0.0
        if cmd == "G90":
            abs_xyz = True; return 0.0
        if cmd == "G91":
            abs_xyz = False; return 0.0
        if cmd == "M82":
            abs_e = True; return 0.0
        if cmd == "M83":
            abs_e = False; return 0.0
        vals = parsed.numeric_parameters()
        if cmd == "G92":
            if "X" in vals: x = vals["X"]
            if "Y" in vals: y = vals["Y"]
            if "Z" in vals: z = vals["Z"]
            if "E" in vals: e = vals["E"]
            return 0.0
        if cmd not in ("G0", "G00", "G1", "G01"):
            return 0.0
        if "F" in vals:
            feed_mm_min = float(vals["F"])
        if feed_mm_min is None or feed_mm_min <= 0:
            return 0.0
        if not any(k in vals for k in ("X", "Y", "Z", "E")):
            return 0.0

        old_x, old_y, old_z, old_e = x, y, z, e
        nx, ny, nz, ne = x, y, z, e
        if "X" in vals:
            nx = vals["X"] if abs_xyz or x is None else x + vals["X"]
        if "Y" in vals:
            ny = vals["Y"] if abs_xyz or y is None else y + vals["Y"]
        if "Z" in vals:
            nz = vals["Z"] if abs_xyz or z is None else z + vals["Z"]
        if "E" in vals:
            ne = vals["E"] if abs_e or e is None else (0.0 if e is None else e) + vals["E"]

        dx = 0.0 if old_x is None or nx is None else float(nx - old_x)
        dy = 0.0 if old_y is None or ny is None else float(ny - old_y)
        dz = 0.0 if old_z is None or nz is None else float(nz - old_z)
        de = 0.0
        if "E" in vals:
            de = (0.0 if old_e is None or ne is None else float(ne - old_e)) if abs_e else float(vals["E"])

        x, y, z, e = nx, ny, nz, ne
        xyz = math.sqrt(dx * dx + dy * dy + dz * dz)
        dist = xyz if xyz > 0 else (abs(de) if "E" in vals else 0.0)
        if dist <= 0:
            return 0.0
        return max(0.0, dist / (float(feed_mm_min) / 60.0))

    for i, raw in enumerate(lines):
        mb = begin_re.match(raw)
        if mb:
            activation_open = True
            activation_attrs = parse_attrs(mb.group(1))
            continue
        if end_re.match(raw):
            if activation_open:
                dt = activation_overhead(activation_attrs)
                raw_elapsed += dt
                activation_seconds += dt
            activation_open = False
            activation_attrs = {}
            continue

        parsed = parse_gcode_line(raw, i + 1, strict=True)
        if parsed.command is None:
            continue

        if (not activation_open) and parsed.command in ("G0", "G00", "G1", "G01"):
            safe_elapsed_raw.append((i, raw_elapsed))
            safe_sites += 1

        dt = update_elapsed_for_line(parsed)
        if dt > 0:
            if activation_open:
                # Activation block motion is already covered by the activation
                # overhead added at block end, matching the main time estimator.
                continue
            raw_elapsed += dt
            motion_seconds += dt

    raw_total = max(1e-9, float(raw_elapsed))
    scale = total / raw_total
    scaled = [(idx, max(0.0, min(total, elapsed * scale))) for idx, elapsed in safe_elapsed_raw]
    return scaled, {
        "raw_trace_total_seconds": float(raw_total),
        "scale_to_total": float(scale),
        "motion_trace_seconds": float(motion_seconds),
        "activation_trace_seconds": float(activation_seconds),
        "activation_count": int(activation_count),
        "safe_insertion_sites": int(safe_sites),
    }


def _m73_values_from_elapsed(elapsed_seconds: float, total_seconds: float) -> Tuple[int, int]:
    total = max(1.0, float(total_seconds))
    elapsed = max(0.0, min(float(elapsed_seconds), total))
    p = int(math.floor((100.0 * elapsed / total) + 1e-9))
    p = min(99, max(0, p))
    r = max(0, int(math.floor((total - elapsed) / 60.0 + 1e-9)))
    return p, r


def patch_m73_remaining_time_commands(gcode: str, total_seconds: float) -> Tuple[str, Dict[str, object]]:
    """Replace sparse M73 P/R with a true cumulative-time second-pass stream.

    v1.35 policy:
      - remove old executable M73 P... R... lines.
      - keep M73.2 reset, M73 L layer updates, and any M73 E Bambu-specific
        event counters untouched.
      - walk the final G-code in order, estimating cumulative elapsed time from
        motion plus FC3D activation overhead.
      - insert M73 P/R at the next safe normal G0/G1 point outside activation
        blocks whenever displayed P changes by 1% or R changes by 1 minute.
      - force final M73 P100 R0 at the end.
    """
    original_lines = gcode.splitlines()
    original_pr = sum(1 for l in original_lines if _m73_pr_line(l))
    lines = [l for l in original_lines if not _m73_pr_line(l)]

    total = max(1.0, float(total_seconds))
    safe_trace, trace_info = _fc3d_trace_safe_m73_sites(lines, total)
    if not safe_trace:
        safe_trace = [(min(len(lines), 1), 0.0)]
        trace_info["fallback_no_safe_trace"] = True

    reset_idxs = [
        i for i, line in enumerate(lines)
        if parse_gcode_line(line, i + 1, strict=True).command == "M73.2"
    ]
    first_reset = reset_idxs[0] if reset_idxs else -1
    # Prefer updates after the first reset, matching Bambu Studio's pattern.
    usable_trace = [(idx, elapsed) for idx, elapsed in safe_trace if idx > first_reset]
    if not usable_trace:
        usable_trace = safe_trace

    inject: Dict[int, List[str]] = {}
    last_key: Optional[Tuple[int, int]] = None
    for idx, elapsed in usable_trace:
        p, r = _m73_values_from_elapsed(elapsed, total)
        key = (p, r)
        if key == last_key:
            continue
        inject.setdefault(idx, []).append(f"M73 P{p} R{r} ; FC3D cumulative progress")
        last_key = key

    # Guarantee an initial visible value after reset if the trace started just
    # after non-motion setup lines and did not emit P0/Rtotal naturally.
    initial_r = max(0, int(math.floor(total / 60.0 + 1e-9)))
    if first_reset >= 0:
        first_after_reset = next((idx for idx, _ in usable_trace if idx > first_reset), first_reset + 1)
        first_lines = inject.get(first_after_reset, [])
        def is_initial_m73(text: str) -> bool:
            parsed = parse_gcode_line(text, 0, strict=True)
            if parsed.command != "M73":
                return False
            p_word = parsed.optional_word("P")
            r_word = parsed.optional_word("R")
            return bool(p_word is not None and r_word is not None and p_word[1].numeric == 0.0)
        if not any(is_initial_m73(s) for s in first_lines):
            inject.setdefault(first_after_reset, []).insert(0, f"M73 P0 R{initial_r} ; FC3D cumulative progress start")

    out: List[str] = []
    inserted_count = 0
    emitted_at: set = set()
    for i, line in enumerate(lines):
        if i in inject:
            for m73 in inject[i]:
                key = (i, m73)
                if key not in emitted_at:
                    out.append(m73)
                    inserted_count += 1
                    emitted_at.add(key)
        out.append(line)
    out.append("M73 P100 R0 ; FC3D cumulative progress done")
    inserted_count += 1

    marker = (
        f"; FC3D_M73_CUMULATIVE_PROGRESS: inserted={inserted_count} removed_old_pr={original_pr} "
        f"total_seconds={int(round(total))} policy=true_second_pass_P_or_R_change "
        f"safe=normal_G0_G1_outside_activation_blocks raw_trace_seconds={trace_info.get('raw_trace_total_seconds', 0):.3f} "
        f"scale={trace_info.get('scale_to_total', 0):.6f}"
    )
    if not any("FC3D_M73_CUMULATIVE_PROGRESS" in l for l in out[:150]):
        out.insert(min(len(out), 5), marker)

    return "\n".join(out) + ("\n" if gcode.endswith("\n") else ""), {
        "patched_m73_commands": inserted_count,
        "removed_old_m73_pr_commands": original_pr,
        "safe_insertion_sites": int(trace_info.get("safe_insertion_sites", 0)),
        "raw_trace_total_seconds": float(trace_info.get("raw_trace_total_seconds", 0.0)),
        "scale_to_total": float(trace_info.get("scale_to_total", 0.0)),
        "motion_trace_seconds": float(trace_info.get("motion_trace_seconds", 0.0)),
        "activation_trace_seconds": float(trace_info.get("activation_trace_seconds", 0.0)),
        "activation_count": int(trace_info.get("activation_count", 0)),
        "policy": "true cumulative-time second pass; insert when P changes by 1 percent or R changes by 1 minute; outside activation blocks",
    }

def embed_fc3d_time_comments_in_gcode(
    gcode: str,
    time_estimate: Optional[Dict[str, object]],
    run_parser_audits: bool = False,
) -> str:
    """Patch stale Bambu-facing time comments and add FC3D time comments.

    This is intentionally metadata/comment-only. It does not change motion.
    """
    total = _time_estimate_total_seconds(time_estimate)
    if total is None:
        if run_parser_audits:
            globals()["LAST_PACKAGED_GCODE_PARSER_AUDIT"] = audit_final_parsed_gcode(gcode.splitlines())
        else:
            globals().pop("LAST_PACKAGED_GCODE_PARSER_AUDIT", None)
        return gcode

    compact = _format_seconds_hms(total)
    bambu = _format_bambu_comment_time(total)
    move = ""
    if isinstance(time_estimate, dict):
        fmt = time_estimate.get("formatted")
        if isinstance(fmt, dict):
            move = str(fmt.get("printing_move_time_excluding_activation_blocks", ""))

    gcode, m73_patch_info = patch_m73_remaining_time_commands(gcode, total)
    comments = [
        f"; FC3D_PPSP_BALLPARK_TIME: {compact}",
        f"; FC3D_PPSP_BALLPARK_SECONDS: {int(round(total))}",
        f"; FC3D_PPSP_TIME_SOURCE: Metadata/fc3d_time_estimate.json",
        f"; FC3D_M73_PATCHED_COMMANDS: {int(m73_patch_info.get('patched_m73_commands', 0))}",
    ]
    if move:
        comments.append(f"; FC3D_PPSP_MOVE_FEED_OUTSIDE_ACTIVATION: {move}")

    out: List[str] = []
    inserted = False
    patched_any_time_line = False

    for line in gcode.splitlines():
        st = line.strip()
        lower = st.lower()
        if not inserted and (st.startswith("; total layer number:") or st.startswith("; max_z_height:") or st.startswith("; filament used")):
            out.extend(comments)
            inserted = True

        if lower.startswith("; model printing time:"):
            out.append(f"; model printing time: {bambu}; total estimated time: {bambu}")
            patched_any_time_line = True
            continue
        if lower.startswith("; total estimated time:"):
            out.append(f"; total estimated time: {bambu}")
            patched_any_time_line = True
            continue
        out.append(line)

    if not inserted:
        out = comments + out
    if not patched_any_time_line:
        insert_at = 0
        while insert_at < len(out) and out[insert_at].startswith("; FC3D_PPSP_"):
            insert_at += 1
        out.insert(insert_at, f"; model printing time: {bambu}; total estimated time: {bambu}")

    final_gcode = "\n".join(out) + ("\n" if gcode.endswith("\n") else "")
    # This is the last function allowed to alter executable G-code before the
    # package is written.  Under --audit, re-parse that exact final text so an
    # M73 construction or comment/header edit cannot bypass the shared parser.
    if run_parser_audits:
        globals()["LAST_PACKAGED_GCODE_PARSER_AUDIT"] = audit_final_parsed_gcode(final_gcode.splitlines())
    else:
        globals().pop("LAST_PACKAGED_GCODE_PARSER_AUDIT", None)
    return final_gcode



def audit_repacked_build_plate(out_path: Path, build_plate: str) -> None:
    """Verify executable startup and both Bambu metadata records agree on one plate."""
    profile = get_build_plate_profile(build_plate)
    failures: List[str] = []
    with zipfile.ZipFile(out_path, "r") as zf:
        names = {name.lower(): name for name in zf.namelist()}
        project_name = next((real for low, real in names.items() if low.endswith("metadata/project_settings.config")), None)
        plate_name = next((real for low, real in names.items() if low.endswith("metadata/plate_1.json")), None)
        gcode_name = next((real for low, real in names.items() if low.endswith("metadata/plate_1.gcode")), None)

        if project_name is None:
            failures.append("missing Metadata/project_settings.config")
        else:
            try:
                project = json.loads(zf.read(project_name).decode("utf-8"))
            except Exception as exc:
                failures.append(f"invalid project_settings.config: {exc}")
            else:
                if project.get("curr_bed_type") != profile["display_name"]:
                    failures.append(
                        f"project curr_bed_type={project.get('curr_bed_type')!r}, expected {profile['display_name']!r}"
                    )
                if project.get("fc3d_build_plate") != build_plate:
                    failures.append(
                        f"project fc3d_build_plate={project.get('fc3d_build_plate')!r}, expected {build_plate!r}"
                    )

        if plate_name is None:
            failures.append("missing Metadata/plate_1.json")
        else:
            try:
                plate = json.loads(zf.read(plate_name).decode("utf-8"))
            except Exception as exc:
                failures.append(f"invalid plate_1.json: {exc}")
            else:
                if plate.get("bed_type") != profile["plate_json_value"]:
                    failures.append(
                        f"plate_1.json bed_type={plate.get('bed_type')!r}, expected {profile['plate_json_value']!r}"
                    )
                if plate.get("fc3d_build_plate") != build_plate:
                    failures.append(
                        f"plate_1.json fc3d_build_plate={plate.get('fc3d_build_plate')!r}, expected {build_plate!r}"
                    )

        if gcode_name is None:
            failures.append("missing Metadata/plate_1.gcode")
        else:
            try:
                gcode = zf.read(gcode_name).decode("utf-8")
                marker = "; FC3D_PPV22_CUBIC_ABS_RGB_AA_ERROR"
                if marker not in gcode:
                    raise RuntimeError("missing FC3D startup/model boundary marker")
                startup = gcode.split(marker, 1)[0].splitlines()
                audit_build_plate_startup(startup, build_plate)
            except Exception as exc:
                failures.append(f"packaged build-plate startup audit failed: {exc}")

    if failures:
        raise RuntimeError("Repacked build-plate audit failed: " + "; ".join(failures))
    print(
        "Repacked build-plate audit: PASS "
        f"cli={build_plate} display={profile['display_name']} "
        f"plate_json={profile['plate_json_value']} m972={profile['startup_m972']} "
        f"baseline_G29.1={float(profile['startup_z_trim']):.5f}",
        flush=True,
    )


def repack(
    template_path: Optional[Path],
    out_path: Path,
    gcode: str,
    tool_map: Dict[str, int],
    preview_rgb: Optional[np.ndarray] = None,
    time_estimate: Optional[Dict[str, object]] = None,
    run_parser_audits: bool = False,
    build_plate: str = DEFAULT_BUILD_PLATE,
) -> None:
    """Repack preserving reference package metadata, with derived head sequence.

    Critical for H2D/Vortek multi-head use:
    - Preserve current-head Bambu Studio metadata/package structure.
    - Replace Metadata/plate_1.gcode and md5.
    - Patch Metadata/filament_sequence.json from final emitted M621 events:
        sequence            = every valid emitted M621 raw tool + 1
        nozzle_sequence     = compact emitted material/nozzle sequence
        optimal_assignment  = full raw-filament-slot -> physical head map
      written as a clean reference-style plate_1 payload.
    """
    # PPSPV17: derive the compact active material set from the emitted G-code and
    # patch the copied Bambu header before inserting it into the package.  This is
    # where the active compact material order is derived from emitted G-code.
    used_mats = infer_used_materials_from_gcode(gcode, tool_map)
    expected_job_active = list(globals().get("RUNTIME_JOB_ACTIVE_MATERIALS", []))
    if expected_job_active and used_mats != expected_job_active:
        raise RuntimeError(
            f"Final emitted material set {used_mats} does not match discovered job-active set {expected_job_active}"
        )
    audit_job_material_and_tower_contract(
        gcode.splitlines(),
        expected_job_active or used_mats,
        tool_map,
    )
    gcode = update_header_filament_metadata(gcode, used_mats, tool_map)
    layer_contract = audit_gcode_physical_layer_contract(
        gcode.splitlines(),
        require_state_reset_markers=True,
    )
    pre_time_trim_contract: Optional[Dict[str, object]] = None
    if "; FC3D_DIRECT_CARRIER_HEIGHT " in gcode:
        pre_time_trim_contract = audit_variable_direct_carrier_heights(gcode.splitlines())
    gcode = embed_fc3d_time_comments_in_gcode(
        gcode,
        time_estimate,
        run_parser_audits=run_parser_audits,
    )
    packaged_layer_contract = audit_gcode_physical_layer_contract(
        gcode.splitlines(),
        expected_physical_layers=int(layer_contract["physical_layers"]),
        require_state_reset_markers=True,
    )
    if abs(float(packaged_layer_contract["nominal_max_z"]) - float(layer_contract["nominal_max_z"])) > 5e-6:
        raise RuntimeError(
            "Physical-layer contract changed while adding package time metadata: "
            f"{packaged_layer_contract['nominal_max_z']} != {layer_contract['nominal_max_z']}"
        )
    layer_contract = packaged_layer_contract
    if pre_time_trim_contract is not None:
        packaged_trim_contract = audit_variable_direct_carrier_heights(gcode.splitlines())
        for key in (
            "height_group_markers",
            "lowered_height_groups",
            "g29_target_sets",
            "g29_baseline_restores",
            "model_g29_commands",
            "positive_xy_extrusions_at_nominal_z",
        ):
            if packaged_trim_contract.get(key) != pre_time_trim_contract.get(key):
                raise RuntimeError(
                    "Direct Z-trim contract changed while adding package time metadata: "
                    f"{key}={packaged_trim_contract.get(key)!r} != {pre_time_trim_contract.get(key)!r}"
                )
    if run_parser_audits:
        packaged_parser_audit = globals().get("LAST_PACKAGED_GCODE_PARSER_AUDIT")
        if not isinstance(packaged_parser_audit, dict) or packaged_parser_audit.get("result") != "PASS":
            raise RuntimeError("Final packaged G-code did not pass the post-M73 strict parser audit")
        print(
            "Final packaged G-code parser audit: PASS "
            f"lines={packaged_parser_audit['line_count']} "
            f"executable={packaged_parser_audit['executable_record_count']} "
            f"commands={packaged_parser_audit['unique_commands']} "
            "unparsed=0 unresolved_labels=0",
            flush=True,
        )
    gbytes = gcode.encode("utf-8")
    md5 = hashlib.md5(gbytes).hexdigest().encode("ascii")
    preview_replacements = build_metadata_preview_replacements(preview_rgb)
    time_estimate_bytes = json.dumps(time_estimate or {}, indent=2, sort_keys=True).encode("utf-8") if time_estimate is not None else None

    template_source: object = Path(template_path) if template_path is not None else io.BytesIO(embedded_h2c_package_bytes())
    with zipfile.ZipFile(template_source, "r") as zin, zipfile.ZipFile(out_path, "w", zipfile.ZIP_DEFLATED) as zout:
        wrote_gcode = False
        wrote_md5 = False
        wrote_filseq = False
        wrote_time_estimate = False

        for item in zin.infolist():
            name = item.filename
            lname = name.lower()
            data = zin.read(name)

            if lname in preview_replacements:
                zout.writestr(item, preview_replacements[lname])
            elif lname == "metadata/plate_1.gcode" or lname.endswith("/plate_1.gcode"):
                zout.writestr(item, gbytes)
                wrote_gcode = True
            elif lname == "metadata/plate_1.gcode.md5" or lname.endswith("/plate_1.gcode.md5"):
                zout.writestr(item, md5)
                wrote_md5 = True
            elif lname == "metadata/fc3d_time_estimate.json" or lname.endswith("/fc3d_time_estimate.json"):
                if time_estimate_bytes is not None:
                    zout.writestr(item, time_estimate_bytes)
                    wrote_time_estimate = True
                else:
                    zout.writestr(item, data)
            elif lname == "metadata/filament_sequence.json" or lname.endswith("/filament_sequence.json"):
                zout.writestr(item, patch_filament_sequence_json_preserve_heads(data, gcode, tool_map))
                wrote_filseq = True
            elif lname == "metadata/model_settings.config" or lname.endswith("/model_settings.config"):
                zout.writestr(item, patch_model_settings_material_metadata(data, used_mats, tool_map))
            elif lname == "metadata/slice_info.config" or lname.endswith("/slice_info.config"):
                zout.writestr(
                    item,
                    patch_slice_info_material_metadata(
                        data,
                        used_mats,
                        tool_map,
                        layer_contract,
                        time_estimate=time_estimate,
                    ),
                )
            elif lname == "metadata/project_settings.config" or lname.endswith("/project_settings.config"):
                zout.writestr(item, patch_project_settings_disable_reference_prime_tower(data, used_mats, tool_map, build_plate=build_plate))
            elif lname == "metadata/plate_1.json" or lname.endswith("/plate_1.json"):
                zout.writestr(item, patch_plate_json(data, used_mats, tool_map, gcode, time_estimate=time_estimate, build_plate=build_plate))
            else:
                zout.writestr(item, data)

        if not wrote_gcode:
            zout.writestr("Metadata/plate_1.gcode", gbytes)
        if not wrote_md5:
            zout.writestr("Metadata/plate_1.gcode.md5", md5)
        if not wrote_filseq:
            zout.writestr("Metadata/filament_sequence.json", patch_filament_sequence_json_preserve_heads(b"{}", gcode, tool_map))
        if time_estimate_bytes is not None and not wrote_time_estimate:
            zout.writestr("Metadata/fc3d_time_estimate.json", time_estimate_bytes)

    audit_repacked_material_metadata(out_path, used_mats, tool_map, layer_contract)
    audit_repacked_build_plate(out_path, build_plate)


def audit_repacked_material_metadata(
    out_path: Path,
    used_mats: Sequence[str],
    tool_map: Dict[str, int],
    expected_layer_contract: Dict[str, object],
) -> None:
    """Fail if the final 3MF advertises stale material or physical-layer metadata."""
    active = [m for m in used_mats if m in tool_map]
    failures: List[str] = []
    with zipfile.ZipFile(out_path, "r") as zf:
        names = {name.lower(): name for name in zf.namelist()}
        project_name = next((real for low, real in names.items() if low.endswith("metadata/project_settings.config")), None)
        slice_name = next((real for low, real in names.items() if low.endswith("metadata/slice_info.config")), None)
        gcode_name = next((real for low, real in names.items() if low.endswith("metadata/plate_1.gcode")), None)
        filament_sequence_name = next((real for low, real in names.items() if low.endswith("metadata/filament_sequence.json")), None)

        expected_physical_layers = int(expected_layer_contract["physical_layers"])
        expected_nominal_max_z = float(expected_layer_contract["nominal_max_z"])
        if gcode_name is None:
            failures.append("missing Metadata/plate_1.gcode")
        else:
            try:
                packaged_gcode = zf.read(gcode_name).decode("utf-8")
                packaged_contract = audit_gcode_physical_layer_contract(
                    packaged_gcode.splitlines(),
                    expected_physical_layers=expected_physical_layers,
                    require_state_reset_markers=True,
                )
            except Exception as exc:
                failures.append(f"packaged G-code physical-layer contract failed: {exc}")
            else:
                if abs(float(packaged_contract["nominal_max_z"]) - expected_nominal_max_z) > 5e-6:
                    failures.append(
                        "packaged G-code nominal max Z "
                        f"{packaged_contract['nominal_max_z']} != expected {expected_nominal_max_z}"
                    )
                if "; FC3D_DIRECT_CARRIER_HEIGHT " in packaged_gcode:
                    try:
                        audit_variable_direct_carrier_heights(packaged_gcode.splitlines())
                    except Exception as exc:
                        failures.append(f"packaged G-code direct Z-trim contract failed: {exc}")

        if project_name is None:
            failures.append("missing Metadata/project_settings.config")
        else:
            try:
                project = json.loads(zf.read(project_name).decode("utf-8"))
            except Exception as exc:
                failures.append(f"invalid project_settings.config: {exc}")
            else:
                if project.get("fc3d_active_logical_materials") != active:
                    failures.append(
                        f"project active materials {project.get('fc3d_active_logical_materials')!r} != {active!r}"
                    )
                if project.get("fc3d_runtime_material_order") != active:
                    failures.append(
                        f"project runtime material order {project.get('fc3d_runtime_material_order')!r} != {active!r}"
                    )
                expected_raw_tools = [int(tool_map[m]) for m in active]
                if project.get("fc3d_active_raw_tools") != expected_raw_tools:
                    failures.append(
                        f"project active raw tools {project.get('fc3d_active_raw_tools')!r} != {expected_raw_tools!r}"
                    )
                for mat in active:
                    raw = int(tool_map[mat])
                    expected_colour = material_display_colour(mat).upper()
                    for key, expected in (("filament_type", str(polymer_profile_for_material(mat)["filament_type"])), ("filament_colour", expected_colour)):
                        arr = project.get(key)
                        actual = arr[raw] if isinstance(arr, list) and raw < len(arr) else None
                        if str(actual).upper() != str(expected).upper():
                            failures.append(f"project {mat}/raw{raw} {key}={actual!r}, expected {expected!r}")

        if filament_sequence_name is None:
            failures.append("missing Metadata/filament_sequence.json")
        else:
            try:
                filament_sequence_obj = json.loads(zf.read(filament_sequence_name).decode("utf-8"))
                filament_plate = filament_sequence_obj.get("plate_1", filament_sequence_obj)
            except Exception as exc:
                failures.append(f"invalid filament_sequence.json: {exc}")
            else:
                expected_one_based = [int(tool_map[m]) + 1 for m in active]
                sequence = filament_plate.get("sequence") if isinstance(filament_plate, dict) else None
                if not isinstance(sequence, list):
                    failures.append("filament_sequence.json has no sequence list")
                else:
                    compact_first_use: List[int] = []
                    for value in sequence:
                        ivalue = int(value)
                        if ivalue not in compact_first_use:
                            compact_first_use.append(ivalue)
                    if compact_first_use != expected_one_based:
                        failures.append(
                            f"filament sequence compact first-use {compact_first_use!r} != {expected_one_based!r}"
                        )
                nozzle_sequence = filament_plate.get("nozzle_sequence") if isinstance(filament_plate, dict) else None
                if not isinstance(nozzle_sequence, list) or len(nozzle_sequence) != len(sequence or []):
                    failures.append("filament_sequence nozzle_sequence length does not match sequence")

        if slice_name is None:
            failures.append("missing Metadata/slice_info.config")
        else:
            try:
                root = ET.fromstring(zf.read(slice_name))
            except Exception as exc:
                failures.append(f"invalid slice_info.config: {exc}")
            else:
                plate = root.find(".//plate")
                if plate is None:
                    failures.append("slice_info.config has no plate")
                else:
                    metadata = {
                        str(el.get("key")): str(el.get("value"))
                        for el in plate.findall("metadata")
                    }
                    if metadata.get("fc3d_physical_layer_count") != str(expected_physical_layers):
                        failures.append(
                            "slice physical-layer count metadata "
                            f"{metadata.get('fc3d_physical_layer_count')!r} != {expected_physical_layers!r}"
                        )
                    try:
                        slice_nominal_max_z = float(metadata.get("fc3d_nominal_max_z_mm", "nan"))
                    except Exception:
                        slice_nominal_max_z = float("nan")
                    if not math.isfinite(slice_nominal_max_z) or abs(slice_nominal_max_z - expected_nominal_max_z) > 5e-6:
                        failures.append(
                            "slice nominal max Z metadata "
                            f"{metadata.get('fc3d_nominal_max_z_mm')!r} != {expected_nominal_max_z:.5f}"
                        )
                    active_raw = [int(tool_map[mat]) for mat in active]
                    base_raw = int(tool_map.get("W", active_raw[0] if active_raw else 0))
                    expected_rows = _expected_slice_layer_rows(
                        expected_physical_layers,
                        base_raw,
                        active_raw,
                    )
                    try:
                        actual_rows = _read_slice_layer_rows(plate)
                    except Exception as exc:
                        failures.append(f"slice layer ranges invalid: {exc}")
                    else:
                        if actual_rows != expected_rows:
                            failures.append(
                                f"slice layer ranges {actual_rows!r} != expected {expected_rows!r}"
                            )
                        covered_layers = [
                            layer
                            for start, end, _filaments in actual_rows
                            for layer in range(start, end + 1)
                        ]
                        if covered_layers != list(range(expected_physical_layers)):
                            failures.append(
                                "slice layer ranges do not cover each physical layer exactly once: "
                                f"{covered_layers!r}"
                            )
                    by_id = {el.get("id"): el for el in plate.findall("filament")}
                    for mat in active:
                        fid = str(int(tool_map[mat]) + 1)
                        el = by_id.get(fid)
                        if el is None:
                            failures.append(f"slice missing {mat}/filament{fid}")
                            continue
                        expected_type = str(polymer_profile_for_material(mat)["filament_type"]).upper()
                        if str(el.get("type", "")).upper() != expected_type:
                            failures.append(f"slice {mat}/filament{fid} type={el.get('type')!r}, expected {expected_type!r}")
                        if str(el.get("color", "")).upper() != material_display_colour(mat).upper():
                            failures.append(f"slice {mat}/filament{fid} color={el.get('color')!r}, expected {material_display_colour(mat)!r}")

    if failures:
        raise ValueError("Repacked material metadata audit failed: " + "; ".join(failures))

    mapping = " ".join(
        f"{m}=position{int(tool_map[m]) + 1}/{str(polymer_profile_for_material(m)['filament_type']).upper()}/{material_display_colour(m)}" for m in active
    )
    print(
        "Repacked material/layer metadata audit: PASS "
        f"layers={expected_physical_layers} nominal_max_z={expected_nominal_max_z:.5f} "
        f"{mapping}",
        flush=True,
    )

def close_small_gaps_in_segments(segs, close_gaps_mm: float):
    """Merge same-scanline same-material spans separated by small gaps.

    This is a mechanical print-quality optimisation: tiny gaps below roughly one
    bead width are unlikely to be reliably preserved by the extrusion system,
    and closing them reduces pressure cycling and stop/start artefacts.

    Supports axis-aligned segments represented as (x0, y0, x1, y1).
    """
    if close_gaps_mm <= 0:
        return segs

    out = {}
    for mat, mat_segs in segs.items():
        if not mat_segs:
            out[mat] = mat_segs
            continue

        groups = {}
        passthrough = []
        for s in mat_segs:
            x0, y0, x1, y1 = seg_xy(s)
            dose = round(seg_dose(s), 6)
            height_fraction = round(seg_height_fraction(s), 8)
            has_height_fraction = bool(seg_has_height_fraction(s))
            if abs(y0 - y1) < 1e-6:
                fixed = round(y0, 5)
                a, b = sorted((x0, x1))
                direction = 1 if x1 >= x0 else -1
                groups.setdefault(("X", fixed, dose, height_fraction, has_height_fraction), []).append((a, b, direction))
            elif abs(x0 - x1) < 1e-6:
                fixed = round(x0, 5)
                a, b = sorted((y0, y1))
                direction = 1 if y1 >= y0 else -1
                groups.setdefault(("Y", fixed, dose, height_fraction, has_height_fraction), []).append((a, b, direction))
            else:
                passthrough.append(s)

        merged = list(passthrough)
        for (axis, fixed, dose, height_fraction, has_height_fraction), spans in groups.items():
            spans.sort(key=lambda v: (v[0], v[1]))
            cur_a, cur_b, cur_dir = spans[0]

            def merged_segment(a: float, b: float, direction: int):
                if axis == "X":
                    xy = (a, fixed, b, fixed) if direction >= 0 else (b, fixed, a, fixed)
                else:
                    xy = (fixed, a, fixed, b) if direction >= 0 else (fixed, b, fixed, a)
                base = xy + (float(dose),)
                return base + ((float(height_fraction),) if has_height_fraction else ())

            for a, b, direction in spans[1:]:
                if a - cur_b <= close_gaps_mm + 1e-9:
                    cur_b = max(cur_b, b)
                else:
                    merged.append(merged_segment(cur_a, cur_b, cur_dir))
                    cur_a, cur_b, cur_dir = a, b, direction

            merged.append(merged_segment(cur_a, cur_b, cur_dir))

        out[mat] = merged

    return out





def apply_global_prime_state_contract(g: List[str]) -> Tuple[List[str], Dict[str, object]]:
    """Canonicalise and audit FC3D print-pressure state over the generated model body.

    Numeric ``prime_state`` is the logical print-pressure state:
        0.00 = fully retracted
        0.38 = pre-primed
        0.40 = fully primed

    Physical E is normally equal to the logical transition, except for the
    calibrated full reprime: physical +CALIBRATED_REPRIME_MM (currently 0.395)
    explicitly declares logical 0.00 -> FULL_PRIME_STATE_MM (0.400).  This keeps
    the deliberate 0.005 mm per-road pressure reduction while preventing logical
    state drift or clipping of the final retract.

    Retraction is deliberately forgiving: a request can only remove what is
    currently primed, so repeated/oversized retract requests are clipped at zero.
    Priming is deliberately strict: staged +0.38 and final +0.02 transitions must
    begin from their expected states, generic full/profile recoveries must begin
    fully retracted, and no recovery may exceed 0.40 mm total state.

    Any non-extruding XYZ move encountered while live is pressure-isolated by an
    exact retract of the current state.  When this pass itself has split a legacy
    pressure chain, it supplies the canonical +0.38/+0.02 recovery immediately
    before the next positive-E drawing move.  This is the only automatic prime;
    malformed explicit prime sequences still hard-fail.

    The H2C ``FC3D_PPSPV43_PRE_SWAP_PRESSURE_RELIEF`` E-1.2 move is filament-swap
    handling rather than the 0..0.40 print-pressure state and is therefore left
    intact, but is only legal when print-pressure state is already zero.
    """
    import re as _re

    FULL = float(FC3D_PRESSURE_FULL_PRIME_STATE_MM)
    CAL_REPRIME = float(FC3D_PRESSURE_CALIBRATED_REPRIME_MM)
    PREPRIME = float(FC3D_PRESSURE_PREPRIME_MM)
    FINAL_PRIME = float(FC3D_PRESSURE_FINAL_PRIME_MM)

    if not isinstance(g, list):
        raise RuntimeError("global prime-state contract expects a list of G-code lines")
    try:
        start = next(i for i, line in enumerate(g) if str(line).strip() == "; CHANGE_LAYER")
        end = next(i for i, line in enumerate(g[start:], start) if str(line).strip() == "; V4_MODEL_END")
    except StopIteration as exc:
        raise RuntimeError("global prime-state contract could not locate FC3D model body") from exc

    # The retained Bambu prefix leaves the active nozzle in the normal recovered
    # print state; every FC3D physical layer begins with a 0.40 retract.  Starting
    # at 0.40 therefore lets the first layer reset itself to the authoritative 0.
    prime_state = FULL
    auto_chain_retracted = False
    tol = 1e-6
    field_re = _re.compile(r"(?:^|\s)([XYZEF])([+-]?(?:\d+(?:\.\d*)?|\.\d+))")
    e_re = _re.compile(r"(\sE)([+-]?(?:\d+(?:\.\d*)?|\.\d+))")

    stats: Dict[str, object] = {
        "scope_start_line": int(start + 1),
        "scope_end_line": int(end + 1),
        "initial_prime_state_mm": FULL,
        "final_prime_state_mm": None,
        "dry_travel_auto_retracts": 0,
        "dry_travel_auto_retract_total_mm": 0.0,
        "auto_reprime_sequences": 0,
        "auto_reprime_total_mm": 0.0,
        "explicit_prime_moves": 0,
        "drawing_moves_checked": 0,
        "retract_moves_checked": 0,
        "retracts_clipped": 0,
        "retract_clipped_total_mm": 0.0,
        "retract_noops": 0,
        "toolchange_unload_retracts_exempt": 0,
        "strict_prime_errors": 0,
        "calibrated_full_reprimes": 0,
        "calibrated_full_reprime_physical_total_mm": 0.0,
        "calibrated_pressure_bias_total_mm": 0.0,
        "max_observed_prime_state_mm": FULL,
        "min_drawing_prime_state_mm": None,
    }

    def _motion_fields(line: str):
        code = str(line).split(";", 1)[0].strip()
        if not (code.startswith("G0 ") or code == "G0" or code.startswith("G00 ") or
                code.startswith("G1 ") or code == "G1" or code.startswith("G01 ")):
            return None
        return {m.group(1): float(m.group(2)) for m in field_re.finditer(code)}

    def _replace_e(line: str, new_e: float) -> str:
        parts = str(line).split(";", 1)
        code = e_re.sub(lambda m: f"{m.group(1)}{new_e:.5f}", parts[0], count=1).rstrip()
        return code + ((" ;" + parts[1]) if len(parts) > 1 else "")

    def _remove_e(line: str) -> str:
        parts = str(line).split(";", 1)
        code = e_re.sub("", parts[0], count=1).rstrip()
        return code + ((" ;" + parts[1]) if len(parts) > 1 else "")

    out: List[str] = []
    for idx, raw_line in enumerate(g):
        line = str(raw_line)
        if idx < start or idx > end:
            out.append(line)
            continue

        # Separate H2C filament-unload operation.  It is deliberately not allowed
        # to hide a live print-pressure state before head swap.
        if "FC3D_PPSPV43_PRE_SWAP_PRESSURE_RELIEF" in line:
            if prime_state > 1e-5:
                raise RuntimeError(
                    f"v1.152 prime-state error at source line {idx+1}: H2C pre-swap relief "
                    f"requested while print prime_state={prime_state:.5f}, expected 0.00000"
                )
            out.append(line)
            stats["toolchange_unload_retracts_exempt"] = int(stats["toolchange_unload_retracts_exempt"]) + 1
            auto_chain_retracted = False
            continue

        fields = _motion_fields(line)
        if fields is None:
            out.append(line)
            continue
        e = fields.get("E")
        has_xyz = any(k in fields for k in ("X", "Y", "Z"))
        has_xy = any(k in fields for k in ("X", "Y"))

        # Any actual non-extruding position change must be fully retracted.  Feed-
        # only G1 commands do not count as travel.
        if has_xyz and (e is None or abs(float(e)) <= tol):
            if prime_state > tol:
                out.append(
                    f"G1 E-{prime_state:.5f} F1800 ; FC3D_V152_GLOBAL_AUTO_RETRACT "
                    f"before dry travel source_line={idx+1}"
                )
                stats["dry_travel_auto_retracts"] = int(stats["dry_travel_auto_retracts"]) + 1
                stats["dry_travel_auto_retract_total_mm"] = float(stats["dry_travel_auto_retract_total_mm"]) + prime_state
                prime_state = 0.0
                auto_chain_retracted = True
            out.append(line)
            continue

        # Retraction is intentionally permissive and saturating.  This is the
        # defensive half of the contract: repeat attempts can never double-retract.
        if e is not None and float(e) < -tol:
            requested = -float(e)
            before = prime_state
            actual = min(requested, max(0.0, prime_state))
            prime_state = max(0.0, prime_state - actual)
            stats["retract_moves_checked"] = int(stats["retract_moves_checked"]) + 1
            if actual <= tol:
                stats["retract_noops"] = int(stats["retract_noops"]) + 1
                if has_xyz:
                    out.append(_remove_e(line) + " ; FC3D_V152_RETRACT_NOOP state=0")
                else:
                    out.append(f"; FC3D_V152_RETRACT_NOOP state=0 original={line.strip()}")
            else:
                if actual < requested - tol:
                    rewritten = _replace_e(line, -actual)
                    stats["retracts_clipped"] = int(stats["retracts_clipped"]) + 1
                    stats["retract_clipped_total_mm"] = float(stats["retract_clipped_total_mm"]) + (requested - actual)
                    rewritten += (
                        f" ; FC3D_V152_RETRACT_CLIPPED requested={requested:.5f} "
                        f"state_before={before:.5f}"
                    )
                    out.append(rewritten)
                else:
                    # Preserve exact source spelling/comments when no saturation
                    # was required; several legacy audits intentionally match the
                    # canonical physical-layer reset line byte-for-byte.
                    out.append(line)
            # A repeated retract after an automatically inserted isolation does not
            # erase the fact that the next formerly chained drawing road needs the
            # corresponding automatic recovery.
            continue

        # Positive E without spatial movement is a prime/recovery operation.
        if e is not None and float(e) > tol and not has_xyz:
            amount = float(e)
            comment = line.split(";", 1)[1] if ";" in line else ""
            staged_component = (
                "RECOVERY_COMPONENT" in comment
                or "PROFILE_RESET_RECOVERY" in comment
            )
            if staged_component:
                if prime_state + amount > FULL + 1e-5:
                    raise RuntimeError(
                        f"v1.152 prime-state error at source line {idx+1}: staged recovery +{amount:.5f} "
                        f"from {prime_state:.5f} would exceed {FULL:.5f}"
                    )
            elif abs(amount - FINAL_PRIME) <= 1e-5:
                if abs(prime_state - PREPRIME) > 1e-4:
                    raise RuntimeError(
                        f"v1.152 prime-state error at source line {idx+1}: final +{FINAL_PRIME:.5f} prime "
                        f"requires state {PREPRIME:.5f}, observed {prime_state:.5f}"
                    )
            elif abs(amount - PREPRIME) <= 1e-5:
                if abs(prime_state) > 1e-4:
                    raise RuntimeError(
                        f"v1.152 prime-state error at source line {idx+1}: +{PREPRIME:.5f} pre-prime "
                        f"requires state 0.00000, observed {prime_state:.5f}"
                    )
            elif abs(amount - CAL_REPRIME) <= 1e-5:
                # Calibrated physical reprime: +0.395 mm (default) is the empirically
                # tuned physical action that reaches logical FULL=0.400.  Do NOT add
                # 0.395 arithmetically to logical state: that would create false drift
                # and clip the intended -0.380/-0.020 full retract.
                if abs(prime_state) > 1e-4:
                    raise RuntimeError(
                        f"v1.152 prime-state error at source line {idx+1}: calibrated full reprime "
                        f"+{amount:.5f} requires state 0.00000, observed {prime_state:.5f}"
                    )
                prime_state = FULL
                stats["calibrated_full_reprimes"] = int(stats["calibrated_full_reprimes"]) + 1
                stats["calibrated_full_reprime_physical_total_mm"] = (
                    float(stats["calibrated_full_reprime_physical_total_mm"]) + amount
                )
                stats["calibrated_pressure_bias_total_mm"] = (
                    float(stats["calibrated_pressure_bias_total_mm"]) + (FULL - amount)
                )
                stats["explicit_prime_moves"] = int(stats["explicit_prime_moves"]) + 1
                stats["max_observed_prime_state_mm"] = max(float(stats["max_observed_prime_state_mm"]), prime_state)
                auto_chain_retracted = False
                out.append(line)
                continue
            elif 0.39000 - 1e-6 <= amount <= FULL + 1e-5:
                # Other full/profile recoveries remain literal physical/logical
                # transitions and must start fully retracted.
                if abs(prime_state) > 1e-4:
                    raise RuntimeError(
                        f"v1.152 prime-state error at source line {idx+1}: profile/full recovery "
                        f"+{amount:.5f} requires state 0.00000, observed {prime_state:.5f}"
                    )
            else:
                raise RuntimeError(
                    f"v1.152 prime-state error at source line {idx+1}: unrecognised standalone "
                    f"prime/recovery +{amount:.5f}; explicit state contract required"
                )
            prime_state += amount
            if prime_state > FULL + 1e-5:
                raise RuntimeError(
                    f"v1.152 prime-state error at source line {idx+1}: prime_state exceeded {FULL:.5f} "
                    f"after +{amount:.5f}: {prime_state:.5f}"
                )
            stats["explicit_prime_moves"] = int(stats["explicit_prime_moves"]) + 1
            stats["max_observed_prime_state_mm"] = max(float(stats["max_observed_prime_state_mm"]), prime_state)
            auto_chain_retracted = False
            out.append(line)
            continue

        # Positive E with XY/Z is drawing/extrusion.  If this pass itself inserted
        # a retract to split a legacy live-pressure link, supply the canonical
        # two-stage recovery.  Otherwise a low state is a genuine source bug.
        if e is not None and float(e) > tol and has_xyz:
            if prime_state < 0.39000 - 1e-6:
                if auto_chain_retracted and prime_state <= tol:
                    out.append(
                        f"G1 E{PREPRIME:.5f} F1800 ; FC3D_V152_GLOBAL_AUTO_PREPRIME "
                        "after enforced dry-travel retract"
                    )
                    out.append(
                        f"G1 E{FINAL_PRIME:.5f} F1800 ; FC3D_V152_GLOBAL_AUTO_FINAL_PRIME "
                        "after enforced dry-travel retract"
                    )
                    prime_state = FULL
                    auto_chain_retracted = False
                    stats["auto_reprime_sequences"] = int(stats["auto_reprime_sequences"]) + 1
                    stats["auto_reprime_total_mm"] = float(stats["auto_reprime_total_mm"]) + FULL
                else:
                    raise RuntimeError(
                        f"v1.152 prime-state error at source line {idx+1}: drawing move begins at "
                        f"prime_state={prime_state:.5f}; expected >=0.39000"
                    )
            if prime_state > FULL + 1e-5:
                raise RuntimeError(
                    f"v1.152 prime-state error at source line {idx+1}: drawing move begins above "
                    f"full prime state {FULL:.5f}: {prime_state:.5f}"
                )
            stats["drawing_moves_checked"] = int(stats["drawing_moves_checked"]) + 1
            prev_min = stats["min_drawing_prime_state_mm"]
            stats["min_drawing_prime_state_mm"] = (
                prime_state if prev_min is None else min(float(prev_min), prime_state)
            )
            out.append(line)
            continue

        out.append(line)

    # The generated model body is required to end safely retracted before the
    # independent reference finish tail takes over.
    if prime_state > 1e-5:
        raise RuntimeError(
            f"v1.152 prime-state error at V4_MODEL_END: prime_state={prime_state:.5f}, expected 0.00000"
        )
    stats["final_prime_state_mm"] = float(prime_state)
    stats["result"] = "PASS"
    return out, stats



def enforce_explicit_model_draw_feedrates(g: List[str]) -> Tuple[List[str], Dict[str, object]]:
    """v1.159: make model/card positive-E XY extrusion feedrate explicit.

    G-code feedrate is modal.  An E-only prime such as ``G1 E0.395 F1800``
    therefore changes the active feedrate to 30 mm/s.  Historically, several
    model raster paths then emitted their positive-E XY draw without an F word,
    so a nominal 250 mm/s optical road could execute at 30 mm/s.

    This pass is deliberately scoped ONLY to FC3D model/card raster feature
    blocks (``FEATURE: DIRECT_DETERMINISTIC_ROADS_*``).  Prime tower, purge,
    wipe/toolchange and finish-tail mechanics are untouched.

    Contract:
      * physical/base layer 0 model draws: FIRST_LAYER_FEED (v1.159 = 105 mm/s)
      * every optical model/card draw: NORMAL_LAYER_FEED (250 mm/s)
      * every positive-E XY draw gets an explicit F word, so E-only prime/retract
        commands can never silently change its printing speed.
    """
    import re as _re
    field_re = _re.compile(r"(?:^|\s)([XYZEF])([+-]?(?:\d+(?:\.\d*)?|\.\d+))")
    out: List[str] = []
    physical_index = -1
    in_model_feature = False
    changed = 0
    checked = 0
    base_checked = 0
    optical_checked = 0
    wrong_before = 0

    for line in g:
        stripped = str(line).strip()
        if stripped == "; CHANGE_LAYER":
            physical_index += 1
            in_model_feature = False
        if stripped.startswith("; FEATURE: DIRECT_DETERMINISTIC_ROADS_"):
            in_model_feature = True
            out.append(line)
            continue
        if stripped.startswith("; PSP_SPACE_PARTITION_STATS ") or stripped.startswith("; BASE_RASTER_STATS "):
            in_model_feature = False
            out.append(line)
            continue
        if stripped == "; V4_MODEL_END":
            in_model_feature = False

        if in_model_feature:
            code, sep, comment = str(line).partition(";")
            code_s = code.strip()
            if code_s.startswith(("G1 ", "G01 ", "G0 ", "G00 ")):
                fields = {m.group(1): float(m.group(2)) for m in field_re.finditer(code_s)}
                has_xy = "X" in fields or "Y" in fields
                e = fields.get("E")
                if has_xy and e is not None and e > 1e-9:
                    checked += 1
                    target = int(FIRST_LAYER_FEED if physical_index == 0 else NORMAL_LAYER_FEED)
                    if physical_index == 0:
                        base_checked += 1
                    else:
                        optical_checked += 1
                    old_f = fields.get("F")
                    if old_f is None or abs(old_f - target) > 1e-6:
                        wrong_before += 1
                        # Remove any existing F word and append the authoritative
                        # explicit model draw feed.  Preserve comments verbatim.
                        new_code = _re.sub(r"(?:(?<=\s)|^)F[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?=\s|$)", "", code_s)
                        new_code = " ".join(new_code.split()) + f" F{target}"
                        line = new_code + ((" ;" + comment) if sep else "")
                        changed += 1
        out.append(line)

    # Fail closed: reparse the result and prove every scoped positive-E XY draw
    # carries the correct explicit feedrate.
    physical_index = -1
    in_model_feature = False
    audited = 0
    for i, line in enumerate(out, start=1):
        stripped = str(line).strip()
        if stripped == "; CHANGE_LAYER":
            physical_index += 1
            in_model_feature = False
        if stripped.startswith("; FEATURE: DIRECT_DETERMINISTIC_ROADS_"):
            in_model_feature = True
            continue
        if stripped.startswith("; PSP_SPACE_PARTITION_STATS ") or stripped.startswith("; BASE_RASTER_STATS ") or stripped == "; V4_MODEL_END":
            in_model_feature = False
            continue
        if not in_model_feature:
            continue
        code = str(line).split(";", 1)[0].strip()
        if not code.startswith(("G1 ", "G01 ", "G0 ", "G00 ")):
            continue
        fields = {m.group(1): float(m.group(2)) for m in field_re.finditer(code)}
        if ("X" in fields or "Y" in fields) and fields.get("E", 0.0) > 1e-9:
            audited += 1
            target = float(FIRST_LAYER_FEED if physical_index == 0 else NORMAL_LAYER_FEED)
            if "F" not in fields or abs(fields["F"] - target) > 1e-6:
                raise RuntimeError(
                    f"v1.159 model draw feed audit failed at line {i}: physical={physical_index} "
                    f"expected F{target:.0f}, got {stripped!r}"
                )

    report = {
        "result": "PASS",
        "draws_checked": int(checked),
        "draws_audited": int(audited),
        "base_draws": int(base_checked),
        "optical_draws": int(optical_checked),
        "wrong_or_implicit_before": int(wrong_before),
        "rewritten": int(changed),
        "base_feed_mm_min": int(FIRST_LAYER_FEED),
        "base_speed_mm_s": float(FIRST_LAYER_FEED) / 60.0,
        "optical_feed_mm_min": int(NORMAL_LAYER_FEED),
        "optical_speed_mm_s": float(NORMAL_LAYER_FEED) / 60.0,
    }
    return out, report


def audit_global_prime_state_contract(g: List[str]) -> Dict[str, object]:
    """Non-mutating second-pass audit of the v1.152 pressure invariants."""
    import re as _re
    FULL = float(FC3D_PRESSURE_FULL_PRIME_STATE_MM)
    CAL_REPRIME = float(FC3D_PRESSURE_CALIBRATED_REPRIME_MM)
    PREPRIME = float(FC3D_PRESSURE_PREPRIME_MM)
    FINAL_PRIME = float(FC3D_PRESSURE_FINAL_PRIME_MM)
    try:
        start = next(i for i, line in enumerate(g) if str(line).strip() == "; CHANGE_LAYER")
        end = next(i for i, line in enumerate(g[start:], start) if str(line).strip() == "; V4_MODEL_END")
    except StopIteration as exc:
        raise RuntimeError("v1.152 audit could not locate FC3D model body") from exc
    field_re = _re.compile(r"(?:^|\s)([XYZEF])([+-]?(?:\d+(?:\.\d*)?|\.\d+))")
    state = FULL
    tol = 1e-6
    dry_travels = drawing = primes = retracts = exempt = 0
    min_draw = None
    for idx in range(start, end + 1):
        line = str(g[idx])
        if "FC3D_PPSPV43_PRE_SWAP_PRESSURE_RELIEF" in line:
            if state > 1e-5:
                raise RuntimeError(f"v1.152 audit: live state {state:.5f} before H2C swap at line {idx+1}")
            exempt += 1
            continue
        code = line.split(";", 1)[0].strip()
        if not (code.startswith("G0 ") or code == "G0" or code.startswith("G00 ") or
                code.startswith("G1 ") or code == "G1" or code.startswith("G01 ")):
            continue
        fields = {m.group(1): float(m.group(2)) for m in field_re.finditer(code)}
        e = fields.get("E")
        has_xyz = any(k in fields for k in ("X", "Y", "Z"))
        if has_xyz and (e is None or abs(float(e)) <= tol):
            if state > 1e-5:
                raise RuntimeError(
                    f"v1.152 audit: dry XYZ travel while prime_state={state:.5f} at line {idx+1}: {line}"
                )
            dry_travels += 1
            continue
        if e is not None and float(e) < -tol:
            req = -float(e)
            if req > state + 1e-5:
                raise RuntimeError(
                    f"v1.152 audit: retract {req:.5f} exceeds state {state:.5f} at line {idx+1}: {line}"
                )
            state = max(0.0, state - req)
            retracts += 1
            continue
        if e is not None and float(e) > tol and not has_xyz:
            amount = float(e)
            comment = line.split(";", 1)[1] if ";" in line else ""
            if abs(amount - FINAL_PRIME) <= 1e-5 and "GLOBAL_AUTO_FINAL_PRIME" not in comment and "RECOVERY_COMPONENT" not in comment:
                if abs(state - PREPRIME) > 1e-4:
                    raise RuntimeError(
                        f"v1.152 audit: +{FINAL_PRIME:.5f} final prime from state {state:.5f} at line {idx+1}"
                    )
            if abs(amount - PREPRIME) <= 1e-5 and "RECOVERY_COMPONENT" not in comment:
                if abs(state) > 1e-4:
                    raise RuntimeError(
                        f"v1.152 audit: +{PREPRIME:.5f} pre-prime from state {state:.5f} at line {idx+1}"
                    )
            if abs(amount - CAL_REPRIME) <= 1e-5:
                if abs(state) > 1e-4:
                    raise RuntimeError(
                        f"v1.152 audit: calibrated full reprime +{amount:.5f} from state {state:.5f} at line {idx+1}"
                    )
                state = FULL
                primes += 1
                continue
            if state + amount > FULL + 1e-5:
                raise RuntimeError(
                    f"v1.152 audit: prime +{amount:.5f} exceeds state ceiling from {state:.5f} at line {idx+1}"
                )
            state += amount
            primes += 1
            continue
        if e is not None and float(e) > tol and has_xyz:
            if state < 0.39000 - 1e-6 or state > FULL + 1e-5:
                raise RuntimeError(
                    f"v1.152 audit: drawing at invalid prime_state={state:.5f} line {idx+1}: {line}"
                )
            drawing += 1
            min_draw = state if min_draw is None else min(min_draw, state)
    if state > 1e-5:
        raise RuntimeError(f"v1.152 audit: model ends live at prime_state={state:.5f}")
    return {
        "result": "PASS",
        "dry_travels_checked": int(dry_travels),
        "drawing_moves_checked": int(drawing),
        "prime_moves_checked": int(primes),
        "retract_moves_checked": int(retracts),
        "toolchange_unload_retracts_exempt": int(exempt),
        "min_drawing_prime_state_mm": float(min_draw if min_draw is not None else 0.0),
        "final_prime_state_mm": float(state),
    }

def sanitise_redundant_z_moves(g: List[str], z_hop_mode: str = "off") -> List[str]:
    """Remove redundant same-layer pure-Z moves when Z-hop is disabled.

    pp emits many `G1 Z<current layer>` restore commands before tower/model
    starts. They are machine-no-ops once already at that Z, but Bambu Studio's
    direct-G-code viewer treats them as visual layer/height events. This keeps
    one pure Z move per declared layer and drops repeated current-layer Z moves
    plus generated +0.40 hop lifts when z-hop is off.
    """
    if z_hop_mode != "off":
        return g

    out: List[str] = []
    current_layer_z: Optional[float] = None
    seen_layer_z_move = False

    for line_number, line in enumerate(g, start=1):
        s = line.strip()

        if s.startswith("; Z_HEIGHT:"):
            try:
                current_layer_z = float(s.split(":", 1)[1].strip())
            except Exception:
                current_layer_z = None
            seen_layer_z_move = False
            out.append(line)
            continue

        parsed = parse_gcode_line(line, line_number, strict=True)
        is_pure_z = (
            parsed.command == "G1"
            and len(parsed.words) == 2
            and [word.letter for word in parsed.words] == ["Z", "F"]
            and all(word.numeric is not None for word in parsed.words)
        )
        if is_pure_z and current_layer_z is not None:
            z = parsed.require_numeric("Z")
            if abs(z - (current_layer_z + HOP_Z_MM)) < 1e-6:
                continue
            if abs(z - current_layer_z) < 1e-6:
                if seen_layer_z_move:
                    continue
                seen_layer_z_move = True
                out.append(line)
                continue

        out.append(line)

    return out



def strip_psp_runtime_marker_comments(g: List[str]) -> List[str]:
    """Remove optional PSP model-body debug marker comments while preserving motion.

    Functional moves, including actual ramped/vertical Z-hop lift/drop commands,
    are never removed here.  This only strips selected semicolon comments that
    are useful for debugging but too noisy for normal print files and audits.
    """
    out: List[str] = []
    for line in g:
        st = line.strip()
        if not PSP_EMIT_ZHOP_COMMENTS and (st.startswith("; V4_ZHOP_START") or st.startswith("; V4_ZHOP_END")):
            continue
        if not PSP_EMIT_BODY_PATH_COMMENTS and (
            st.startswith("; PSPV") or
            st.startswith("; PSP_") or
            st.startswith("; STUDIO_LOCAL_RASTER_MODE_START") or
            st.startswith("; STUDIO_LOCAL_RASTER_MODE_END") or
            st.startswith("; STUDIO_LOCAL_TILE_START") or
            st.startswith("; STUDIO_LOCAL_TILE_END")
        ):
            continue
        out.append(line)
    return out

def strip_reference_geometry_remnants(g: List[str]) -> List[str]:
    """Carbon-copy mode: do not strip template setup or generated layer body.

    Kept as a hook for future audits, but intentionally returns g unchanged.
    Previous aggressive stripping broke Bambu's sliced-package expectations.
    """
    return g





def _parse_direct_layer_image_list(s: str) -> List[Path]:
    paths = [Path(v.strip().strip('"')) for v in str(s).split(",") if v.strip()]
    if not (1 <= len(paths) <= MIX_LAYERS):
        raise RuntimeError(f"--direct-layer-images requires 1..{MIX_LAYERS} comma-separated images, got {len(paths)}")
    return paths


DIRECT_LAYER_RGB_TO_MAT = {
    (245,245,245): "W",
    (255,255,255): "W",
    (255,160,40): "F",
    (230,40,40): "R",
    (235,220,40): "Y",
    (50,190,70): "G",
    (40,200,220): "C",
    (50,80,230): "B",
    (0,0,0): EMPTY_MAT,  # black debug pixels are empty in direct calibration mode
}


DIRECT_LAYER_MAT_TO_PREVIEW_RGB = {
    "W": (245, 245, 245),
    "F": (255, 160, 40),
    "R": (230, 40, 40),
    "Y": (235, 220, 40),
    "G": (50, 190, 70),
    "C": (40, 200, 220),
    "B": (50, 80, 230),
}


def _direct_alpha_dose_preview_top_from_stack(rp_stack_model_bottom: np.ndarray, dose_model_bottom: np.ndarray) -> np.ndarray:
    """Render a direct-layer preview that makes physical layer order visible.

    This preview is intentionally diagnostic rather than a colour-calibrated
    optical prediction.  The old ppv83 preview blended every layer with a weak
    alpha/stack-depth factor.  That made a stack with W below colour look almost
    the same as a stack with W above colour, so it was poor at catching direct
    layer-order mistakes.

    The model below is order-aware:
      * W underneath coloured material acts as support/backing and does not
        wash out that colour.
      * W above coloured material acts as a top cover/scatter layer and visibly
        whitens the preview.
      * coloured layers are accumulated from their own doses, so dose ramps are
        easy to see.
      * the emitted G-code/extrusion is unchanged; this affects preview only.

    Input stack is physical bottom->top in model/bottom-origin Y.
    Returned preview is top-origin RGB for saved PNGs.
    """
    mats = np.asarray(rp_stack_model_bottom)
    dose = np.asarray(dose_model_bottom, dtype=np.float32)
    if mats.shape != dose.shape:
        raise RuntimeError(f"Direct preview stack/dose shape mismatch: {mats.shape} vs {dose.shape}")

    h, w, n_layers = mats.shape
    out = np.full((h, w, 3), 255.0, dtype=np.float32)

    coloured_materials = [
        m for m in DIRECT_LAYER_MAT_TO_PREVIEW_RGB.keys()
        if m not in ("W", "F", EMPTY_MAT)
    ]
    colour_weight = np.zeros((h, w), dtype=np.float32)
    colour_sum = np.zeros((h, w, 3), dtype=np.float32)

    for mat in coloured_materials:
        rgb = np.asarray(DIRECT_LAYER_MAT_TO_PREVIEW_RGB[mat], dtype=np.float32)
        m = (mats == mat) & (dose > 0)
        if not np.any(m):
            continue
        weights = np.where(m, np.clip(dose, 0.0, 2.0), 0.0).astype(np.float32)
        ww = np.sum(weights, axis=2)
        if np.any(ww > 0):
            colour_weight += ww
            colour_sum += ww[:, :, None] * rgb[None, None, :]

    has_colour = colour_weight > 1e-6
    if np.any(has_colour):
        avg_colour = np.zeros_like(out)
        avg_colour[has_colour] = colour_sum[has_colour] / colour_weight[has_colour, None]

        # Saturation/density cue: one active colour layer is clearly visible;
        # more layers become more chromatic/dense without clipping immediately.
        density = np.clip(colour_weight / 4.0, 0.0, 1.0)
        blend = 0.35 + 0.55 * density
        out[has_colour] = out[has_colour] * (1.0 - blend[has_colour, None]) + avg_colour[has_colour] * blend[has_colour, None]

        # Find highest coloured layer per pixel, then count only W physically
        # above it. W below this layer is support/backing and must not whiten the
        # preview. This is the key direct-layer order diagnostic.
        colour_present = np.isin(mats, coloured_materials) & (dose > 0)
        highest_colour = np.full((h, w), -1, dtype=np.int16)
        for li in range(n_layers):
            highest_colour[colour_present[:, :, li]] = li

        w_above_dose = np.zeros((h, w), dtype=np.float32)
        for li in range(n_layers):
            above = highest_colour >= 0
            above &= li > highest_colour
            wm = above & (mats[:, :, li] == "W") & (dose[:, :, li] > 0)
            if np.any(wm):
                w_above_dose[wm] += np.clip(dose[:, :, li][wm], 0.0, 2.0)

        # Top W cover is visually strong because physically it hides/whitens
        # what is below.  One W layer gives an obvious cue; several approach
        # white.  W below colour has no effect here by construction.
        cover = 1.0 - np.exp(-0.55 * np.clip(w_above_dose, 0.0, 8.0))
        if np.any(cover > 0):
            out[has_colour] = out[has_colour] * (1.0 - cover[has_colour, None]) + 255.0 * cover[has_colour, None]

    # W/F-only pixels: show as optically neutral. F is the clear carrier and
    # must not appear as its internal orange identity colour in this preview.
    any_active = np.any((mats != EMPTY_MAT) & (dose > 0), axis=2)
    w_only = any_active & (~has_colour)
    if np.any(w_only):
        w_depth = np.sum(np.where((mats == "W") & (dose > 0), np.clip(dose, 0.0, 2.0), 0.0), axis=2)
        shade = 255.0 - np.clip(w_depth * 1.8, 0.0, 12.0)
        out[w_only] = shade[w_only, None]

    return np.clip(out[::-1, :, :], 0, 255).astype(np.float32)




def _canonicalise_w_bounded_recipe_for_reverse_preview(recipe: str) -> str:
    """Canonicalise chroma order inside W-bounded segments using BRGYC.

    This matches the FC3D current optical-equivalence rule used by the candidate
    bank and measured-master dedupe. W positions remain barriers.
    """
    chroma_order = "BRGYC"
    rank = {ch: i for i, ch in enumerate(chroma_order)}
    r = "".join(ch for ch in str(recipe).upper() if ch in "RGBCYWF")
    if len(r) > MIX_LAYERS:
        r = r[:MIX_LAYERS]
    if len(r) < MIX_LAYERS:
        r = "W" * (MIX_LAYERS - len(r)) + r
    out = []
    seg = []
    def flush():
        if seg:
            out.extend(sorted(seg, key=lambda ch: rank.get(ch, 999)))
            seg.clear()
    for ch in r:
        if ch == "W":
            flush()
            out.append("W")
        else:
            seg.append(ch)
    flush()
    return "".join(out)


def _reverse_preview_token(mat: str, dose_mult: float) -> str:
    m = str(mat).upper()
    if m in (EMPTY_MAT, "F", "T", "S", ""):
        m = "W"
    if m == "W":
        return "W100"
    pct = int(round(float(dose_mult) * 100.0))
    pct = max(0, min(255, pct))
    return f"{m}{pct}"


def _canonicalise_w_bounded_tokens_for_reverse_preview(tokens: Sequence[str]) -> List[str]:
    rank = {ch: i for i, ch in enumerate("BRGYC")}
    toks: List[str] = []
    for t in tokens:
        m = re.search(r"([RGBCYWF])\s*(\d{1,3})?", str(t).upper())
        if not m:
            toks.append("W100")
        else:
            mat = m.group(1)
            dose = int(m.group(2)) if m.group(2) else 100
            if mat in ("W", "F"):
                toks.append("W100")
            else:
                toks.append(f"{mat}{dose}")
    if len(toks) > MIX_LAYERS:
        toks = toks[:MIX_LAYERS]
    if len(toks) < MIX_LAYERS:
        toks = ["W100"] * (MIX_LAYERS - len(toks)) + toks
    out: List[str] = []
    seg: List[str] = []
    def dose(t: str) -> int:
        mm = re.search(r"(\d{1,3})", t)
        return int(mm.group(1)) if mm else 100
    def flush() -> None:
        if seg:
            out.extend(sorted(seg, key=lambda t: (rank.get(t[0], 999), dose(t), t)))
            seg.clear()
    for t in toks:
        if t[0] == "W":
            flush(); out.append("W100")
        else:
            seg.append(t)
    flush()
    return out


def _print_key_from_tokens_for_reverse_preview(tokens: Sequence[str]) -> str:
    toks = _canonicalise_w_bounded_tokens_for_reverse_preview(tokens)
    def dose(t: str) -> int:
        mm = re.search(r"(\d{1,3})", t)
        return int(mm.group(1)) if mm else 100
    return "optve:" + "-".join(f"{t[0]}{dose(t):03d}" for t in toks)


def _print_key_from_text_for_reverse_preview(text: str) -> str:
    s0 = str(text or "").strip()
    if not s0:
        return ""
    s = s0.upper()
    if s.startswith("OPTVE:"):
        s = s[6:]
    elif s.startswith("PRINT:"):
        s = s[6:]
    elif s.startswith("OPT:"):
        # material-only legacy key: full-dose tokens
        letters = [ch for ch in s[4:] if ch in "RGBCYWF"]
        return _print_key_from_tokens_for_reverse_preview([ch + "100" for ch in letters])
    found = list(re.finditer(r"([RGBCYWF])\s*(\d{1,3})?", s))
    if not found:
        return ""
    has_dose = any(m.group(2) for m in found)
    if has_dose:
        toks = [m.group(1).upper() + (m.group(2) or "100") for m in found]
    else:
        toks = [m.group(1).upper() + "100" for m in found]
    return _print_key_from_tokens_for_reverse_preview(toks)


def _load_direct_layer_reverse_rgb_lookup(path: str) -> Tuple[Dict[str, Tuple[float, float, float]], Dict[str, object]]:
    import csv as _csv
    p = Path(path)
    if not p.exists():
        raise RuntimeError(f"--direct-layer-reverse-rgb-csv does not exist: {path}")
    out: Dict[str, Tuple[float, float, float]] = {}
    rows = 0
    skipped = 0
    duplicates = 0

    def _pick(row, names):
        lower = {str(k).lower(): k for k in row.keys()}
        for name in names:
            k = lower.get(name.lower())
            if k is not None and str(row.get(k, '')).strip() != '':
                return str(row.get(k, '')).strip()
        return ''

    def _rgb(row):
        for names in [
            ("expected_r", "expected_g", "expected_b"),
            ("candidate_r", "candidate_g", "candidate_b"),
            ("corrected_R_mean", "corrected_G_mean", "corrected_B_mean"),
            ("model_pred_R", "model_pred_G", "model_pred_B"),
            ("r", "g", "b"),
        ]:
            vals = [_pick(row, names=[n]) for n in names]
            if all(v != '' for v in vals):
                try:
                    return tuple(float(v) for v in vals)
                except Exception:
                    pass
        return None

    with p.open('r', newline='', encoding='utf-8-sig') as f:
        rr = _csv.DictReader(f)
        for row in rr:
            rows += 1
            key = _pick(row, ["fc3d_print_key", "print_key", "dose_key", "ve_key"])
            if not key:
                key = _pick(row, ["recipe_stack_bottom_to_top", "recipe", "candidate_recipe", "canonical_recipe", "stack", "active_stack", "print_recipe", "fc3d_optical_key", "optical_key"])
            opt_key = _print_key_from_text_for_reverse_preview(key)
            if not opt_key:
                skipped += 1
                continue
            rgb = _rgb(row)
            if rgb is None:
                skipped += 1
                continue
            if opt_key in out:
                duplicates += 1
            out[opt_key] = tuple(max(0.0, min(255.0, float(v))) for v in rgb)  # type: ignore[assignment]
    return out, {"path": str(p), "rows": rows, "loaded_keys": len(out), "skipped": skipped, "duplicate_keys_last_wins": duplicates}


def _load_card_manifest_expected_rgb(manifest_csv: str) -> Tuple[Dict[str, Tuple[float, float, float]], Dict[str, object]]:
    """Load card manifest recipe -> expected RGB for reverse-LUT integrity audit."""
    path = Path(manifest_csv)
    rows = 0
    skipped = 0
    duplicates = 0
    out: Dict[str, Tuple[float, float, float]] = {}
    examples: List[Dict[str, object]] = []
    if not manifest_csv:
        return out, {"enabled": False}
    if not path.exists():
        raise RuntimeError(f"--direct-layer-card-manifest-csv not found: {manifest_csv}")

    def pick(row: Dict[str, str], names: Sequence[str]) -> str:
        for n in names:
            if n in row and str(row.get(n, "")).strip() != "":
                return str(row.get(n, "")).strip()
        return ""

    with path.open("r", newline="", encoding="utf-8-sig") as f:
        rdr = csv.DictReader(f)
        for row in rdr:
            rows += 1
            recipe = pick(row, ["print_key", "fc3d_print_key", "recipe_stack", "recipe_stack_bottom_to_top", "optical_key", "fc3d_optical_key", "recipe", "candidate_recipe", "canonical_recipe"])
            opt = _print_key_from_text_for_reverse_preview(recipe)
            if not opt:
                skipped += 1
                continue
            try:
                rgb = (
                    float(pick(row, ["expected_r", "r", "pred_r", "candidate_r"])),
                    float(pick(row, ["expected_g", "g", "pred_g", "candidate_g"])),
                    float(pick(row, ["expected_b", "b", "pred_b", "candidate_b"])),
                )
            except Exception:
                skipped += 1
                continue
            if opt in out:
                duplicates += 1
            out[opt] = rgb
            if len(examples) < 5:
                examples.append({"optical_key": opt, "expected_rgb": list(rgb)})
    return out, {
        "enabled": True,
        "path": str(path),
        "rows": rows,
        "loaded_unique_keys": len(out),
        "skipped": skipped,
        "duplicate_keys_last_wins": duplicates,
        "examples": examples,
    }


def _audit_reverse_lookup_against_card_manifest(
    lookup: Dict[str, Tuple[float, float, float]],
    manifest_csv: str,
    tolerance_rgb: float = 1.0,
    policy_rejected_keys: Optional[set] = None,
) -> Dict[str, object]:
    expected, load_report = _load_card_manifest_expected_rgb(manifest_csv)
    policy_rejected_keys = policy_rejected_keys or set()
    if not manifest_csv:
        return {"enabled": False}
    missing: List[str] = []
    policy_rejected_missing: List[str] = []
    unexpected_missing: List[str] = []
    mismatches: List[Dict[str, object]] = []
    max_abs_delta = 0.0
    max_de76 = 0.0
    compared = 0
    for opt, exp_rgb in expected.items():
        got = lookup.get(opt)
        if got is None:
            missing.append(opt)
            if opt in policy_rejected_keys:
                policy_rejected_missing.append(opt)
            else:
                unexpected_missing.append(opt)
            continue
        compared += 1
        exp = np.asarray(exp_rgb, dtype=np.float32)
        got_arr = np.asarray(got, dtype=np.float32)
        delta = got_arr - exp
        abs_delta = float(np.max(np.abs(delta)))
        max_abs_delta = max(max_abs_delta, abs_delta)
        de76 = float(np.linalg.norm(_srgb_to_lab_array(got_arr.reshape(1, 3))[0] - _srgb_to_lab_array(exp.reshape(1, 3))[0]))
        max_de76 = max(max_de76, de76)
        if abs_delta > tolerance_rgb:
            mismatches.append({
                "optical_key": opt,
                "expected_rgb": [float(x) for x in exp.tolist()],
                "reverse_rgb": [float(x) for x in got_arr.tolist()],
                "delta_rgb": [float(x) for x in delta.tolist()],
                "max_abs_delta_rgb": abs_delta,
                "de76": de76,
            })
    return {
        "enabled": True,
        "manifest": load_report,
        "tolerance_rgb": float(tolerance_rgb),
        "manifest_unique_keys": int(len(expected)),
        "compared_unique_keys": int(compared),
        "missing_unique_keys": int(len(missing)),
        "policy_rejected_missing_unique_keys": int(len(policy_rejected_missing)),
        "unexpected_missing_unique_keys": int(len(unexpected_missing)),
        "mismatch_unique_keys": int(len(mismatches)),
        "max_abs_delta_rgb": float(max_abs_delta),
        "max_de76": float(max_de76),
        "missing_examples": missing[:30],
        "policy_rejected_missing_examples": policy_rejected_missing[:30],
        "unexpected_missing_examples": unexpected_missing[:30],
        "mismatch_examples": mismatches[:30],
    }


def _reverse_lookup_preview_top_from_direct_stack(
    rp_stack_model_bottom: np.ndarray,
    dose_model_bottom: np.ndarray,
    reverse_csv: str,
    missing_policy: str = "fail",
    card_manifest_csv: str = "",
    audit_tolerance_rgb: float = 1.0,
    audit_fail: bool = True,
    policy_rejected_keys: Optional[set] = None,
) -> Tuple[np.ndarray, Dict[str, object]]:
    """Render direct-layer preview by exact stack -> canonical recipe -> RGB CSV.

    This mode is deliberately strict: it validates reverse-LUT integrity. A missing
    recipe is a fault by default, not something to hide with nearest-neighbour colour.
    """
    lookup, load_report = _load_direct_layer_reverse_rgb_lookup(reverse_csv)
    policy_rejected_keys = policy_rejected_keys or set()
    manifest_expected: Dict[str, Tuple[float, float, float]] = {}
    if card_manifest_csv:
        try:
            manifest_expected, _manifest_expected_report = _load_card_manifest_expected_rgb(card_manifest_csv)
        except Exception:
            manifest_expected = {}
    manifest_audit = _audit_reverse_lookup_against_card_manifest(lookup, card_manifest_csv, audit_tolerance_rgb, policy_rejected_keys) if card_manifest_csv else {"enabled": False}
    mats = np.asarray(rp_stack_model_bottom)
    dose = np.asarray(dose_model_bottom, dtype=np.float32)
    if mats.shape != dose.shape:
        raise RuntimeError(f"reverse direct preview stack/dose shape mismatch: {mats.shape} vs {dose.shape}")
    h, w, n_layers = mats.shape
    if n_layers != MIX_LAYERS:
        raise RuntimeError(f"reverse direct preview expects {MIX_LAYERS} optical layers, got {n_layers}")

    flat_m = mats.reshape(-1, n_layers)
    flat_d = dose.reshape(-1, n_layers)
    active = np.any((flat_m != EMPTY_MAT) & (flat_d > 0), axis=1)
    out_flat = np.full((flat_m.shape[0], 3), 255.0, dtype=np.float32)
    if not np.any(active):
        report = {"mode": "reverse-lookup", "active_cells": 0, "lookup": load_report, "manifest_audit": manifest_audit}
        return out_flat.reshape(h, w, 3)[::-1, :, :], report

    # Convert active stack rows into canonical dose-aware print keys. Empty/unsupported tokens are W100.
    active_m = flat_m[active]
    active_d = flat_d[active]
    recipes = np.asarray([_print_key_from_tokens_for_reverse_preview([_reverse_preview_token(ch, dd) for ch, dd in zip(row_m, row_d)]) for row_m, row_d in zip(active_m, active_d)], dtype=object)
    unique_recipes, inv = np.unique(recipes, return_inverse=True)
    pred_unique = np.empty((len(unique_recipes), 3), dtype=np.float32)
    missing = []
    policy_rejected_missing = []
    unexpected_missing = []
    exact_matches = 0
    policy = str(missing_policy or "fail").lower().strip()
    for i, rec in enumerate(unique_recipes):
        opt = str(rec)
        rgb = lookup.get(opt)
        if rgb is not None:
            exact_matches += 1
            pred_unique[i] = rgb
            continue
        missing.append(opt)
        if opt in policy_rejected_keys:
            policy_rejected_missing.append(opt)
            # For preview only, use the card/source manifest expected RGB if available.
            # This keeps deliberately-rejected source tiles readable without adding them to the reverse LUT.
            rgb2 = manifest_expected.get(opt)
            pred_unique[i] = rgb2 if rgb2 is not None else (160.0, 160.0, 160.0)
        else:
            unexpected_missing.append(opt)
            # Diagnostic colour for true missing keys; default policy raises after report is built.
            pred_unique[i] = (255.0, 0.0, 255.0)
    out_flat[active] = pred_unique[inv]
    report = {
        "mode": "reverse-lookup",
        "lookup": load_report,
        "manifest_audit": manifest_audit,
        "cells_total": int(flat_m.shape[0]),
        "active_cells": int(np.count_nonzero(active)),
        "unique_stacks_seen": int(len(unique_recipes)),
        "unique_reverse_keys_loaded": int(len(lookup)),
        "exact_match_unique_stacks": int(exact_matches),
        "missing_unique_stacks": int(len(missing)),
        "policy_rejected_missing_unique_stacks": int(len(policy_rejected_missing)),
        "unexpected_missing_unique_stacks": int(len(unexpected_missing)),
        "missing_examples": missing[:50],
        "policy_rejected_missing_examples": policy_rejected_missing[:50],
        "unexpected_missing_examples": unexpected_missing[:50],
        "missing_policy": policy,
        "source_rejected_keys_loaded_from_lut": int(len(policy_rejected_keys)),
        "canonical_policy": "dose-aware optve print key; W-bounded BRGYC token canonicalisation; W positions preserved; VE dose carried by token",
        "rgb_source": "--direct-layer-reverse-rgb-csv",
    }
    hard_fail_reasons = []
    if len(unexpected_missing) and policy == "fail":
        hard_fail_reasons.append(f"{len(unexpected_missing)} unexpected direct-layer unique stack(s) missing from reverse lookup")
    if audit_fail and manifest_audit.get("enabled"):
        if int(manifest_audit.get("unexpected_missing_unique_keys", manifest_audit.get("missing_unique_keys", 0))) > 0:
            hard_fail_reasons.append(f"{manifest_audit.get('unexpected_missing_unique_keys', manifest_audit.get('missing_unique_keys'))} unexpected manifest key(s) missing from reverse lookup")
        if int(manifest_audit.get("mismatch_unique_keys", 0)) > 0:
            hard_fail_reasons.append(f"{manifest_audit.get('mismatch_unique_keys')} manifest key(s) reverse-lookup RGB differs from expected RGB")
    if hard_fail_reasons:
        print(f"Direct-layer reverse-lookup validation report: {json.dumps(report, sort_keys=True)}", flush=True)
        raise RuntimeError("Reverse-LUT integrity validation failed: " + "; ".join(hard_fail_reasons))
    return np.clip(out_flat.reshape(h, w, 3)[::-1, :, :], 0, 255).astype(np.float32), report

def _calibrated_model_preview_top_from_direct_stack(
    rp_stack_model_bottom: np.ndarray,
    dose_model_bottom: np.ndarray,
    lookup: Optional["RecipeLookup"],
) -> Tuple[np.ndarray, Dict[str, object]]:
    """Render direct-layer preview via the shared lutmaker forward predictor.

    This is for phase-2 reference generation:
      exact printed direct stack -> calibrated maths predictor -> print-space RGB

    The direct stack is model/bottom-origin Y and physical bottom->top. Output
    is top-origin RGB for saved PNGs. Empty all-layer pixels stay paper white.
    Partial empty layers are filled as W100 for the predictor and counted in
    the report because the current lutmaker maths model has no explicit air/T.
    """
    if lookup is None:
        raise RuntimeError("--direct-layer-preview-mode calibrated-model requires --recipe-lut with a lutmakerv2.6+ predictor bundle")
    if getattr(lookup, "forward_predictor", None) is None:
        rep = getattr(lookup, "forward_predictor_report", {})
        raise RuntimeError(f"--direct-layer-preview-mode calibrated-model requires a forward predictor in --recipe-lut; report={rep}")
    mats = np.asarray(rp_stack_model_bottom)
    dose = np.asarray(dose_model_bottom, dtype=np.float32)
    if mats.shape != dose.shape:
        raise RuntimeError(f"calibrated direct preview stack/dose shape mismatch: {mats.shape} vs {dose.shape}")
    h, w, n_layers = mats.shape
    if n_layers != MIX_LAYERS:
        raise RuntimeError(f"calibrated direct preview expects {MIX_LAYERS} optical layers, got {n_layers}")

    flat_m = mats.reshape(-1, n_layers)
    flat_d = dose.reshape(-1, n_layers)
    active = np.any((flat_m != EMPTY_MAT) & (flat_d > 0), axis=1)
    out_flat = np.full((flat_m.shape[0], 3), 255.0, dtype=np.float32)
    if not np.any(active):
        return out_flat.reshape(h, w, 3)[::-1, :, :], {"mode": "calibrated-model", "active_cells": 0}

    mat_to_code = {"R": 0, "G": 1, "B": 2, "C": 3, "Y": 4, "W": 5}
    active_m = flat_m[active]
    active_d = (flat_d[active] * 100.0).astype(np.float32)
    fill_as_w100 = (active_m == EMPTY_MAT) | np.isin(active_m, ["F", "T", "S"])
    partial_empty_cells = np.any(active_m == EMPTY_MAT, axis=1)
    unsupported_cells = np.any(np.isin(active_m, ["F", "T", "S"]), axis=1)

    # Fill empty/unsupported tokens as W100 for the predictor. Fully empty cells
    # have already been excluded and remain RGB 255. F/T/S are not in the current
    # RGBCYW predictor; treating them as W is a conservative visible warning path.
    active_m2 = active_m.copy()
    active_m2[(active_m2 == EMPTY_MAT) | (active_m2 == "F") | (active_m2 == "T") | (active_m2 == "S")] = "W"
    material_codes = np.empty(active_m2.shape, dtype=np.uint8)
    for k, v in mat_to_code.items():
        material_codes[active_m2 == k] = int(v)
    # v1.57 preserves every real material's exact alpha/128 dose, including W
    # and chromatic values below 60%. Only explicit empty/unsupported predictor
    # placeholders are filled as W100 because the model has no air/F/T/S code.
    active_d[fill_as_w100] = 100.0
    active_d = active_d.astype(np.float32, copy=False)

    # Predict only unique stacks for speed and stable diagnostics.
    key = np.concatenate([material_codes.astype(np.int16), np.rint(active_d).astype(np.int16)], axis=1)
    unique_key, inv = np.unique(key, axis=0, return_inverse=True)
    uniq_m = unique_key[:, :n_layers].astype(np.uint8)
    uniq_d = unique_key[:, n_layers:].astype(np.float32)
    pred_unique = lookup.calibrated_predict_rgb_for_material_dose(uniq_m, uniq_d)
    out_flat[active] = pred_unique[inv]
    report = {
        "mode": "calibrated-model",
        "predictor": getattr(lookup, "forward_predictor_report", {}),
        "cells_total": int(flat_m.shape[0]),
        "active_cells": int(np.count_nonzero(active)),
        "unique_stacks_predicted": int(unique_key.shape[0]),
        "partial_empty_active_cells_filled_as_W100": int(np.count_nonzero(partial_empty_cells)),
        "unsupported_FTS_cells_filled_as_W100": int(np.count_nonzero(unsupported_cells)),
        "dose_policy": "all real materials use exact alpha/128*100 with no low-dose clamp or doubling; predictor-only empty/F/T/S placeholders use W100",
        "rgb_space": "print-space sRGB 0..255; no preview white expansion inside predictor",
    }
    return np.clip(out_flat.reshape(h, w, 3)[::-1, :, :], 0, 255).astype(np.float32), report


def _load_direct_layer_image(path: Path) -> np.ndarray:
    """Load one direct-layer image without losing floating-point alpha.

    Supported direct-image encodings:
      * legacy PNG/etc via Pillow -> uint8 RGBA, alpha 128 == 100% VE
      * float TIFF (.tif/.tiff)   -> float32 RGBA, alpha 1.0 == 100% VE

    Float TIFF is intentionally strict: normalized finite RGBA in 0..1.
    This keeps material identity and dose in one image and avoids a sidecar
    numerical dose channel.
    """
    p = Path(path)
    if p.suffix.lower() in (".tif", ".tiff"):
        arr = np.asarray(tifffile.imread(p))
        if arr.ndim != 3 or arr.shape[2] != 4:
            raise RuntimeError(
                f"float direct TIFF must be HxWx4 RGBA, got shape {arr.shape} for {p}"
            )
        if not np.issubdtype(arr.dtype, np.floating):
            raise RuntimeError(
                f"direct TIFF must use floating-point RGBA, got dtype {arr.dtype} for {p}"
            )
        arr = arr.astype(np.float32, copy=False)
        if not np.all(np.isfinite(arr)):
            raise RuntimeError(f"float direct TIFF contains non-finite values: {p}")
        lo = float(np.min(arr))
        hi = float(np.max(arr))
        if lo < -1e-7 or hi > 1.0 + 1e-7:
            raise RuntimeError(
                f"float direct TIFF RGBA must be normalized to 0..1, got range {lo:.8f}..{hi:.8f}: {p}"
            )
        return np.clip(arr, 0.0, 1.0).astype(np.float32, copy=False)

    return np.asarray(Image.open(p).convert("RGBA"), dtype=np.uint8)


def _direct_layer_image_size(path: Path) -> Tuple[int, int]:
    """Return (width,height) for either legacy raster input or float TIFF."""
    p = Path(path)
    if p.suffix.lower() in (".tif", ".tiff"):
        with tifffile.TiffFile(p) as tf:
            shape = tuple(int(v) for v in tf.pages[0].shape)
        if len(shape) < 2:
            raise RuntimeError(f"invalid direct TIFF shape {shape}: {p}")
        return int(shape[1]), int(shape[0])
    with Image.open(p) as im:
        return int(im.size[0]), int(im.size[1])


def _classify_direct_layer_rgba(arr: np.ndarray) -> Tuple[np.ndarray, np.ndarray]:
    """Convert a uint8 or normalized-float RGBA direct image to material symbols.

    Presence:
      alpha == 0 -> EMPTY_MAT
      alpha > 0  -> material present

    RGB:
      uint8 legacy image -> direct 0..255 palette comparison
      float TIFF         -> normalized 0..1, converted only for material lookup

    Numerical dose is handled separately by direct_alpha_to_dose() and is never
    quantised when the source image is float TIFF.
    """
    arr = np.asarray(arr)
    if arr.ndim != 3 or arr.shape[2] < 4:
        raise RuntimeError(f"direct layer image must be HxWx4 RGBA, got {arr.shape}")

    if np.issubdtype(arr.dtype, np.floating):
        if not np.all(np.isfinite(arr)):
            raise RuntimeError("floating direct layer image contains non-finite values")
        rgb_f = np.asarray(arr[:, :, :3], dtype=np.float32)
        alpha = np.asarray(arr[:, :, 3], dtype=np.float32)
        if np.any(rgb_f < -1e-7) or np.any(rgb_f > 1.0 + 1e-7):
            raise RuntimeError("floating direct layer RGB must be normalized to 0..1")
        if np.any(alpha < -1e-7) or np.any(alpha > 1.0 + 1e-7):
            raise RuntimeError("floating direct layer alpha/dose must be in 0..1")
        rgb = np.rint(np.clip(rgb_f, 0.0, 1.0) * 255.0).astype(np.int32)
        solid = alpha > np.float32(0.0)
    else:
        rgb = np.asarray(arr[:, :, :3], dtype=np.int32)
        alpha = np.asarray(arr[:, :, 3], dtype=np.uint8)
        solid = alpha > 0

    h, w = rgb.shape[:2]
    out = np.full((h, w), EMPTY_MAT, dtype='<U1')
    if not np.any(solid):
        return out, solid

    palette_items = [(colour, mat) for colour, mat in DIRECT_LAYER_RGB_TO_MAT.items() if mat != EMPTY_MAT]
    palette = np.asarray([c for c, _m in palette_items], dtype=np.int32)
    mats = [m for _c, m in palette_items]
    flat = rgb.reshape(-1, 3)
    out_flat = out.reshape(-1)
    solid_flat = solid.reshape(-1)
    unresolved = solid_flat.copy()

    for colour, mat in palette_items:
        c = np.asarray(colour, dtype=np.int32)
        m = solid_flat & np.all(flat == c, axis=1)
        if np.any(m):
            out_flat[m] = mat
            unresolved[m] = False

    if np.any(unresolved):
        vals = flat[unresolved].astype(np.int32, copy=False)
        d = vals[:, None, :] - palette[None, :, :]
        d2 = np.sum(d * d, axis=2)
        nearest = np.argmin(d2, axis=1)
        out_flat[unresolved] = np.asarray([mats[int(i)] for i in nearest], dtype='<U1')
    return out, solid


def direct_alpha_to_dose(alpha: np.ndarray) -> np.ndarray:
    """Map direct-image alpha to extrusion dose without unnecessary quantisation.

    Float TIFF:
        normalized floating alpha is already the exact VE fraction:
            A=0.005 -> 0.5%
            A=1.000 -> 100%

    Legacy integer RGBA:
        preserve established behaviour:
            alpha 1   -> 1/128 VE
            alpha 64  -> 1/2 VE
            alpha 128 -> 1.0 VE
            alpha 255 -> ~1.992 VE (established 4x2 path)
    """
    a = np.asarray(alpha)
    if np.issubdtype(a.dtype, np.floating):
        out = np.asarray(a, dtype=np.float32)
        if not np.all(np.isfinite(out)):
            raise RuntimeError("floating direct alpha/dose contains non-finite values")
        return out
    return np.asarray(a, dtype=np.float32) / np.float32(128.0)


def direct_dose_to_carrier_height_fraction(dose: np.ndarray) -> np.ndarray:
    """Map 4x4 normal dose to clearance fraction; only over-100% is capped."""
    return np.minimum(
        np.maximum(np.asarray(dose, dtype=np.float32), np.float32(0.0)),
        np.float32(1.0),
    ).astype(np.float32)


def audit_direct_low_dose_linearity() -> Dict[str, object]:
    """Audit both established uint8-alpha and exact float-TIFF direct-dose paths.

    The returned dictionary deliberately retains the historical v1.139 fields
    consumed by existing CLI/report code, and adds explicit float-TIFF fields.
    This prevents diagnostics from becoming a separate incompatible API.
    """
    # Legacy PNG / uint8 path: preserve alpha/128 exactly.
    legacy_alpha = np.arange(0, 256, dtype=np.uint8)
    legacy_dose = direct_alpha_to_dose(legacy_alpha)
    legacy_expected = legacy_alpha.astype(np.float32) / np.float32(128.0)
    legacy_height = direct_dose_to_carrier_height_fraction(legacy_dose)

    if not np.array_equal(legacy_dose, legacy_expected):
        raise RuntimeError("legacy direct alpha audit failed: dose is not exactly alpha/128")
    if not np.array_equal(legacy_height[:129], legacy_expected[:129]):
        raise RuntimeError("legacy direct alpha audit failed: sub-100% height is not exactly alpha/128")
    if np.any(np.diff(legacy_dose[:129]) <= 0.0):
        raise RuntimeError("legacy direct alpha audit failed: 0..100% dose is not strictly increasing")
    if np.any(np.diff(legacy_height[:129]) <= 0.0):
        raise RuntimeError("legacy direct alpha audit failed: 0..100% height fraction is not strictly increasing")

    # Float-TIFF path: exact 0.5 percentage-point ladder for the current card.
    float_alpha = (
        np.arange(0, 201, dtype=np.float32) * np.float32(0.005)
    ).astype(np.float32)
    float_dose = direct_alpha_to_dose(float_alpha)
    float_height = direct_dose_to_carrier_height_fraction(float_dose)

    if not np.array_equal(float_dose, float_alpha):
        raise RuntimeError("float direct alpha audit failed: floating dose was altered")
    if abs(float(float_dose[1]) - 0.005) > 1e-8:
        raise RuntimeError("float direct alpha audit failed at 0.5% VE")
    if abs(float(float_dose[-1]) - 1.0) > 1e-7:
        raise RuntimeError("float direct alpha audit failed at 100% VE")
    if np.any(np.diff(float_dose) <= 0.0):
        raise RuntimeError("float direct alpha audit failed: 0.5% VE ladder is not strictly increasing")
    if not np.array_equal(float_height, float_dose):
        raise RuntimeError("float direct alpha audit failed: 0..100% carrier height fraction changed")

    # Historical keys retained for all existing consumers.
    result = {
        "result": "PASS",
        "alpha_range_checked": [0, 255],
        "sub_100_alpha_range_checked": [0, 128],
        "dose_formula": "legacy_uint8=alpha/128; float_tiff=alpha_exact_fraction",
        "height_formula": "min(1,dose_fraction)",
        "low_dose_floor": None,
        "low_dose_multiplier": None,
        "low_dose_halftone_conversion": None,
        "alpha_step_dose": float(legacy_dose[1] - legacy_dose[0]),
        "alpha_step_height_mm_for_0_10mm_layer": float(
            (legacy_height[1] - legacy_height[0]) * MIX_H_MM
        ),

        # New explicit float-image audit fields.
        "legacy_uint8_formula": "alpha/128",
        "float_tiff_formula": "alpha_is_exact_dose_fraction",
        "float_tiff_range": [0.0, 1.0],
        "float_tiff_test_step": 0.005,
        "float_tiff_quantisation": None,
        "float_tiff_first_positive_dose": float(float_dose[1]),
        "float_tiff_last_dose": float(float_dose[-1]),
    }
    return result




def _natural_layer_number_from_name(path: Path) -> Optional[int]:
    """Return numeric layer suffix from names like layer_01/layer08 if present."""
    m = re.search(r"(?:^|[_\-])layer[_\-]?(\d{1,2})(?:\D|$)", Path(path).stem, flags=re.IGNORECASE)
    if not m:
        return None
    return int(m.group(1))


def _warn_if_direct_layer_filenames_not_ascending(layer_paths: Sequence[Path]) -> None:
    nums = [_natural_layer_number_from_name(p) for p in layer_paths]
    if all(n is not None for n in nums) and nums != sorted(nums):
        raise RuntimeError(
            "--direct-layer-images filenames appear not to be ascending layer order. "
            "v1.9 expects bottom-to-top order: layer_01,layer_02,...,layer_08. "
            f"Detected order: {nums}"
        )

def _load_direct_layer_rgba_inputs(
    layer_paths: Sequence[Path],
    direct_layout: str = "4x2",
) -> Tuple[List[np.ndarray], Optional[List[np.ndarray]]]:
    """Load ordinary direct layers or one 4x4 normal/filter-pair sheet.

    ``4x2`` is the established path and remains row-major layers 1..8.
    ``4x4`` is deliberately explicit because an arbitrary image's dimensions
    alone cannot safely distinguish the two layouts. Its row-major panels are:

        L1 normal, L1 filter, L2 normal, L2 filter,
        ...,
        L7 normal, L7 filter, L8 normal, L8 filter.

    The returned first list is always the ordinary bottom-to-top optical stack.
    The optional second list contains its one-to-one same-Z filter partners.
    """
    layout = str(direct_layout or "4x2").strip().lower()
    if layout not in ("4x2", "4x4"):
        raise RuntimeError(f"Unsupported direct-layer layout {direct_layout!r}; expected 4x2 or 4x4")
    if not (1 <= len(layer_paths) <= MIX_LAYERS):
        raise RuntimeError(f"Expected 1..{MIX_LAYERS} direct-layer inputs, got {len(layer_paths)}")
    if layout == "4x4" and len(layer_paths) != 1:
        raise RuntimeError("--direct-layout 4x4 requires exactly one combined 4x4 image sheet")
    if len(layer_paths) == 1:
        p = Path(layer_paths[0])
        rgba = _load_direct_layer_image(p)
        h, w = rgba.shape[:2]
        rows = 4 if layout == "4x4" else 2
        if (w % 4) != 0 or (h % rows) != 0:
            raise RuntimeError(
                f"Combined {layout} layer sheet must have width divisible by 4 and height divisible by {rows}: "
                f"{p} is {w}x{h}"
            )
        pw = w // 4
        ph = h // rows
        panels: List[np.ndarray] = []
        for row in range(rows):
            for col in range(4):
                y0 = row * ph
                x0 = col * pw
                panels.append(rgba[y0:y0 + ph, x0:x0 + pw, :].copy())
        if layout == "4x4":
            if len(panels) != 2 * MIX_LAYERS:
                raise RuntimeError(f"Internal 4x4 split error: expected {2 * MIX_LAYERS} panels, got {len(panels)}")
            return panels[0::2], panels[1::2]
        return panels, None
    _warn_if_direct_layer_filenames_not_ascending(layer_paths)
    return [_load_direct_layer_image(p) for p in layer_paths], None


def build_direct_layer_stack(
    layer_paths: Sequence[Path],
    lookup: Optional["RecipeLookup"] = None,
    direct_layout: str = "4x2",
) -> Tuple[np.ndarray, np.ndarray, Image.Image]:
    """Read direct material images into the normal and optional filter grids.

    v1.9 layer-order convention:
      - layer_01 is always the lowest/bottom optical layer above the solid W base.
      - layer_08 is always the highest/top optical layer.
      - --direct-layer-images must be supplied in physical bottom-to-top order:
        layer_01, layer_02, ..., layer_08.
      - PP no longer reverses the supplied image list. The supplied order is copied
        directly to the canonical internal physical bottom-to-top stack axis.

    Alpha-dose convention:
      - alpha == 0   -> empty/no road
      - legacy uint8: alpha 128 -> nominal 100%, dose = alpha/128
      - float TIFF: alpha 1.0 -> nominal 100%, dose = alpha exactly

    Additional 4x4-only convention:
      - the first empty normal panel terminates the stack (1..8 layers)
      - normal alpha below 128 also sets clearance fraction alpha/128 within
        the nominal 0.10 mm layer, continuously and without a low-dose floor
      - filter extrusion keeps its own alpha but inherits carrier clearance

    The base layer is not controlled by these alpha masks; the compiler always
    emits a solid 0.20 mm W base over the full card footprint.

    Returned stack is model/bottom-origin Y and physical bottom-to-top layer
    axis, exactly what compile_layer() expects. PRECOMPUTED_DOSE_GRID carries
    the matching per-pixel extrusion multiplier for optical roads.
    """
    global PRINTABLE_RP_MASK, DIRECT_OPTICAL_LAYER_COUNT, PRECOMPUTED_DOSE_GRID
    global DIRECT_FILTER_STACK_GRID, DIRECT_FILTER_DOSE_GRID, DIRECT_CARRIER_HEIGHT_GRID, DIRECT_ZOFFSET_HEIGHT_PROFILE_GRID, DIRECT_ATOMIC_PARTITION_GRID
    layout = str(direct_layout or "4x2").strip().lower()
    imgs, filter_imgs = _load_direct_layer_rgba_inputs(layer_paths, layout)
    h, w = imgs[0].shape[:2]
    for idx, arr in enumerate(imgs):
        if arr.shape[:2] != (h, w):
            raise RuntimeError(f"Direct layer image size mismatch at layer {idx+1}: got {arr.shape[1]}x{arr.shape[0]}, expected {w}x{h}")
    if filter_imgs is not None:
        if len(filter_imgs) != len(imgs):
            raise RuntimeError(f"4x4 normal/filter pair-count mismatch: {len(imgs)} normal vs {len(filter_imgs)} filter")
        for idx, arr in enumerate(filter_imgs):
            if arr.shape[:2] != (h, w):
                raise RuntimeError(
                    f"Direct filter image size mismatch at layer {idx+1}: "
                    f"got {arr.shape[1]}x{arr.shape[0]}, expected {w}x{h}"
                )
    normal_decoded: List[Tuple[np.ndarray, np.ndarray, np.ndarray]] = []
    for rgba in imgs:
        top_mat, top_solid = _classify_direct_layer_rgba(rgba)
        alpha = np.asarray(rgba[:, :, 3])
        active_normal = top_solid & (top_mat != EMPTY_MAT)
        normal_decoded.append((top_mat, alpha, active_normal))

    filter_decoded: Optional[List[Tuple[np.ndarray, np.ndarray, np.ndarray]]] = None
    if filter_imgs is not None:
        filter_decoded = []
        for rgba in filter_imgs:
            top_mat, top_solid = _classify_direct_layer_rgba(rgba)
            alpha = np.asarray(rgba[:, :, 3])
            active_filter = top_solid & (top_mat != EMPTY_MAT)
            filter_decoded.append((top_mat, alpha, active_filter))

        # v1.57 variable-length 4x4 contract. The first completely empty normal
        # panel is an explicit end-of-stack marker, not a printable empty layer.
        first_empty = next((li for li, (_m, _a, active) in enumerate(normal_decoded) if not np.any(active)), len(normal_decoded))
        if first_empty == 0:
            raise RuntimeError("4x4 layer 1 normal panel is empty; the first optical layer must contain active extrusion")
        if first_empty < len(normal_decoded):
            misplaced: List[str] = []
            for li in range(first_empty, len(normal_decoded)):
                if np.any(normal_decoded[li][2]):
                    misplaced.append(f"layer {li+1} normal")
                if filter_decoded is not None and np.any(filter_decoded[li][2]):
                    misplaced.append(f"layer {li+1} filter")
            if misplaced:
                raise RuntimeError(
                    f"4x4 layer {first_empty+1} normal panel terminates the stack, but active content exists after termination: "
                    + ", ".join(misplaced)
                )
            normal_decoded = normal_decoded[:first_empty]
            filter_decoded = filter_decoded[:first_empty]
            imgs = imgs[:first_empty]
            filter_imgs = filter_imgs[:first_empty]

    n_layers = len(normal_decoded)
    _arch = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
    if isinstance(_arch, dict) and bool(_arch.get("require_complete_carrier_layer", False)):
        _min_dose = float(_arch.get("carrier_dose_min", 1.0))
        _allow_sparse_normal_only = bool(
            _arch.get("allow_sparse_normal_layers_without_filter", False)
        )
        for li, (_top_mat, _alpha, _active_normal) in enumerate(normal_decoded, start=1):
            _has_active_filter = bool(
                filter_decoded is not None
                and (li - 1) < len(filter_decoded)
                and np.any(filter_decoded[li - 1][2])
            )
            if not np.all(_active_normal):
                if not (_allow_sparse_normal_only and not _has_active_filter):
                    missing = int(np.count_nonzero(~_active_normal))
                    raise RuntimeError(
                        f"logical layer {li} carrier is incomplete: {missing} RP pixels have no carrier; "
                        "paired same-layer infill layers must be complete"
                    )
            _normal_dose = direct_alpha_to_dose(_alpha)
            bad = _active_normal & (_normal_dose < _min_dose - 1e-7)
            if np.any(bad):
                raise RuntimeError(
                    f"logical layer {li} carrier dose below required minimum {_min_dose:.4f}: "
                    f"{int(np.count_nonzero(bad))} RP pixels"
                )
    DIRECT_OPTICAL_LAYER_COUNT = n_layers
    stack = np.full((h, w, n_layers), EMPTY_MAT, dtype='<U1')
    dose = np.zeros((h, w, n_layers), dtype=np.float32)
    union_mask_top = np.zeros((h, w), dtype=bool)
    # v1.9: consume the supplied image list exactly as physical bottom->top.
    # layer_paths[0] is the lowest optical layer (layer_01); layer_paths[-1]
    # is the highest/top optical layer. Only the PNG row origin is flipped into
    # PP's model/bottom-origin Y coordinates.
    for li, (top_mat, alpha, active_normal) in enumerate(normal_decoded):
        top_dose = np.where(active_normal, direct_alpha_to_dose(alpha), 0.0).astype(np.float32)
        stack[:, :, li] = top_mat[::-1, :]  # PNG top-origin rows -> model/bottom-origin rows
        dose[:, :, li] = top_dose[::-1, :]
        union_mask_top |= active_normal
    PRECOMPUTED_DOSE_GRID = dose
    DIRECT_FILTER_STACK_GRID = None
    DIRECT_FILTER_DOSE_GRID = None
    DIRECT_CARRIER_HEIGHT_GRID = None
    DIRECT_ZOFFSET_HEIGHT_PROFILE_GRID = None
    DIRECT_ATOMIC_PARTITION_GRID = None

    preview_stack = stack
    preview_dose = dose
    if filter_decoded is not None:
        filter_stack = np.full((h, w, n_layers), EMPTY_MAT, dtype='<U1')
        filter_dose = np.zeros((h, w, n_layers), dtype=np.float32)

        # v1.145: distinguish historical "old VE" (E-only at nominal carrier
        # plane) from the later 4x4 dose-scaled carrier-clearance experiment.
        adjustment = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
        normal_carrier_height_mode = (
            str(adjustment.get("normal_carrier_height_mode", "dose_scaled")).strip().lower()
            if isinstance(adjustment, dict) else "dose_scaled"
        )
        if normal_carrier_height_mode == "fixed_nominal":
            carrier_height = np.where(dose > 0.0, 1.0, 0.0).astype(np.float32)
        elif normal_carrier_height_mode == "dose_scaled":
            carrier_height = direct_dose_to_carrier_height_fraction(dose)
        else:
            raise RuntimeError(
                f"unsupported normal_carrier_height_mode={normal_carrier_height_mode!r}"
            )

        for li, (top_mat, alpha, active_filter) in enumerate(filter_decoded):
            _filter_dose_top = direct_alpha_to_dose(alpha)
            if np.any(active_filter & (_filter_dose_top > 1.0 + 1e-7)):
                max_dose = float(np.max(_filter_dose_top[active_filter]))
                bad_count = int(np.count_nonzero(active_filter & (_filter_dose_top > 1.0 + 1e-7)))
                raise RuntimeError(
                    f"4x4 filter panel for layer {li+1} exceeds the current 100% dose ceiling: "
                    f"{bad_count} active pixels have dose>1.0; maximum dose={max_dose:.8f}"
                )
            active_normal_top = normal_decoded[li][2]
            unsupported_filter = active_filter & (~active_normal_top)
            if np.any(unsupported_filter):
                raise RuntimeError(
                    f"4x4 filter panel for layer {li+1} has {int(np.count_nonzero(unsupported_filter))} active pixels "
                    "without an active normal carrier underneath"
                )
            top_dose = np.where(active_filter, direct_alpha_to_dose(alpha), 0.0).astype(np.float32)
            filter_stack[:, :, li] = top_mat[::-1, :]
            filter_dose[:, :, li] = top_dose[::-1, :]
            union_mask_top |= active_filter
        DIRECT_FILTER_STACK_GRID = filter_stack
        DIRECT_FILTER_DOSE_GRID = filter_dose
        DIRECT_CARRIER_HEIGHT_GRID = carrier_height
        if isinstance(adjustment, dict):
            row_indices = list(adjustment.get("row_profile_indices_top_to_bottom", []))
            profile_index_grid = adjustment.get("profile_index_grid_top_to_bottom")
            tile_size_px = int(adjustment.get("tile_size_px", 0))
            logical_layers = [
                int(v) for v in adjustment.get(
                    "logical_layers",
                    [adjustment.get("logical_layer", 1)]
                )
            ]
            if any(v < 1 or v > n_layers for v in logical_layers):
                raise RuntimeError(
                    f"card Z-offset profile logical layers {logical_layers} are outside active stack 1..{n_layers}"
                )
            top_off = int(adjustment.get("profile_grid_top_offset_px", 0) or 0)
            left_off = int(adjustment.get("profile_grid_left_offset_px", 0) or 0)
            # Border/base-only pixels are optically empty. Give them profile 0 so
            # the profile map remains total while the active grid can start after
            # an exact non-tile-sized white margin (e.g. 5.0 mm = 25 RP pixels).
            profile_top = np.zeros((h, w), dtype=np.int16)
            if isinstance(profile_index_grid, list):
                for row_index, grid_row in enumerate(profile_index_grid):
                    for col_index, profile_index in enumerate(grid_row):
                        y0 = top_off + row_index * tile_size_px
                        y1 = min(h, y0 + tile_size_px)
                        x0 = left_off + col_index * tile_size_px
                        x1 = min(w, x0 + tile_size_px)
                        profile_top[y0:y1, x0:x1] = int(profile_index)
            else:
                for row_index, profile_index in enumerate(row_indices):
                    y0 = top_off + row_index * tile_size_px
                    y1 = min(h, y0 + tile_size_px)
                    profile_top[y0:y1, :] = int(profile_index)
            if np.any(profile_top < 0):
                raise RuntimeError("card Z-offset profile map did not cover the complete panel")
            profile_grid = np.full((h, w, n_layers), -1, dtype=np.int16)
            for logical_layer in logical_layers:
                profile_grid[:, :, logical_layer - 1] = profile_top[::-1, :]
            DIRECT_ZOFFSET_HEIGHT_PROFILE_GRID = profile_grid

            owner_specs = adjustment.get("atomic_partition_id_grids_top_to_bottom", {})
            if isinstance(owner_specs, dict) and owner_specs:
                partition_grid = np.zeros((h, w, n_layers), dtype=np.int32)
                for layer_key, owner_rows in owner_specs.items():
                    li = int(layer_key)
                    owner_top = np.zeros((h, w), dtype=np.int32)
                    for row_index, owner_row in enumerate(owner_rows):
                        for col_index, owner_id in enumerate(owner_row):
                            y0 = top_off + row_index * tile_size_px
                            y1 = min(h, y0 + tile_size_px)
                            x0 = left_off + col_index * tile_size_px
                            x1 = min(w, x0 + tile_size_px)
                            owner_top[y0:y1, x0:x1] = int(owner_id)
                    partition_grid[:, :, li - 1] = owner_top[::-1, :]
                DIRECT_ATOMIC_PARTITION_GRID = partition_grid
                print(
                    "Card-encoded atomic partitions: "
                    + json.dumps({
                        "logical_layers": sorted(int(k) for k in owner_specs.keys()),
                        "nonzero_cells": int(np.count_nonzero(partition_grid)),
                    }, sort_keys=True),
                    flush=True,
                )
            print(
                "Card-encoded Z-offset height profiles: "
                + json.dumps({
                    "profiles": adjustment.get("profiles", []),
                    "row_profile_ids_top_to_bottom": adjustment.get("row_profile_ids_top_to_bottom", []),
                    "profile_id_grid_top_to_bottom": adjustment.get("profile_id_grid_top_to_bottom"),
                }, sort_keys=True),
                flush=True,
            )

        # Diagnostic preview follows actual deposition order within each Z:
        # normal first, then its filter, before advancing to the next layer.
        preview_stack = np.empty((h, w, 2 * n_layers), dtype='<U1')
        preview_dose = np.zeros((h, w, 2 * n_layers), dtype=np.float32)
        preview_stack[:, :, 0::2] = stack
        preview_stack[:, :, 1::2] = filter_stack
        preview_dose[:, :, 0::2] = dose
        preview_dose[:, :, 1::2] = filter_dose
    PRINTABLE_RP_MASK = None
    # ppv82: direct-layer preview must respect alpha-as-dose, matching the
    # print path where PRECOMPUTED_DOSE_GRID scales model-road extrusion.
    preview_mode = str(globals().get("RUNTIME_DIRECT_LAYER_PREVIEW_MODE", "diagnostic")).lower().strip()
    if filter_imgs is not None and preview_mode not in ("diagnostic", "diag"):
        raise RuntimeError(
            "--direct-layout 4x4 currently requires --direct-layer-preview-mode diagnostic; "
            "the existing calibrated/reverse models describe eight independent Z layers, not same-Z filter passes"
        )
    if preview_mode in ("reverse-lookup", "reverse_lookup", "reverse", "lookup"):
        reverse_csv = str(globals().get("RUNTIME_DIRECT_LAYER_REVERSE_RGB_CSV", "") or "")
        if not reverse_csv:
            raise RuntimeError("--direct-layer-preview-mode reverse-lookup requires --direct-layer-reverse-rgb-csv")
        preview, direct_preview_report = _reverse_lookup_preview_top_from_direct_stack(
            stack,
            dose,
            reverse_csv,
            str(globals().get("RUNTIME_DIRECT_LAYER_REVERSE_LOOKUP_MISSING_POLICY", "fail") or "fail"),
            str(globals().get("RUNTIME_DIRECT_LAYER_CARD_MANIFEST_CSV", "") or ""),
            float(globals().get("RUNTIME_DIRECT_LAYER_REVERSE_AUDIT_TOLERANCE_RGB", 1.0) or 1.0),
            str(globals().get("RUNTIME_DIRECT_LAYER_REVERSE_AUDIT_FAIL", "on") or "on").lower() not in ("0", "false", "no", "off"),
            getattr(lookup, "source_rejected_print_keys", set()) if lookup is not None else set(),
        )
        print(f"Direct-layer reverse-lookup validation/preview: {json.dumps(direct_preview_report, sort_keys=True)}", flush=True)
    elif preview_mode in ("calibrated-model", "calibrated_model", "model", "forward-model", "forward_model"):
        preview, direct_preview_report = _calibrated_model_preview_top_from_direct_stack(stack, dose, lookup)
        print(f"Direct-layer calibrated-model preview: {json.dumps(direct_preview_report, sort_keys=True)}", flush=True)
    else:
        preview = _direct_alpha_dose_preview_top_from_stack(preview_stack, preview_dose)
    preview[~union_mask_top, :] = 255
    source_img = Image.fromarray(_to_uint8_rgb(preview), "RGB")
    return stack, preview, source_img


def audit_paired_direct_filter_structure(
    gcode_lines: Sequence[str],
    active_filter_layers: Sequence[int],
    physical_layers_total: int,
) -> Dict[str, object]:
    """Fail closed if a 4x4 normal/filter emission loses its same-Z contract."""
    active = {int(v) for v in active_filter_layers}
    marker_re = re.compile(
        r"^; DIRECT_LAYER V4 physical=(\d+) logical=(\d+) z=([-+0-9.]+) "
        r"pass=(base|normal|filter) same_z_pair=([01])$"
    )
    marker_rows: List[Dict[str, object]] = []
    marker_positions: List[int] = []
    for line_index, line in enumerate(gcode_lines):
        match = marker_re.match(str(line).strip())
        if match is None:
            continue
        marker_positions.append(line_index)
        marker_rows.append({
            "physical": int(match.group(1)),
            "logical": int(match.group(2)),
            "z": float(match.group(3)),
            "pass_role": match.group(4),
            "same_z_pair": int(match.group(5)),
        })

    expected_rows: List[Tuple[int, int, float, str, int]] = [(0, 0, BASE_H_MM, "base", 0)]
    for physical in range(1, int(physical_layers_total)):
        z = BASE_H_MM + physical * MIX_H_MM
        expected_rows.append((physical, physical, z, "normal", 0))
        if physical in active:
            expected_rows.append((physical, physical, z, "filter", 1))
    actual_rows = [
        (
            int(row["physical"]),
            int(row["logical"]),
            float(row["z"]),
            str(row["pass_role"]),
            int(row["same_z_pair"]),
        )
        for row in marker_rows
    ]
    if len(actual_rows) != len(expected_rows):
        raise RuntimeError(
            f"4x4 paired-pass audit failed: expected {len(expected_rows)} emission markers, got {len(actual_rows)}"
        )
    for index, (actual, expected) in enumerate(zip(actual_rows, expected_rows), start=1):
        if actual[:2] != expected[:2] or actual[3:] != expected[3:] or abs(actual[2] - expected[2]) > 1e-9:
            raise RuntimeError(
                f"4x4 paired-pass audit failed at emission {index}: found {actual}, expected {expected}"
            )

    change_count = sum(1 for line in gcode_lines if str(line).strip() == "; CHANGE_LAYER")
    if change_count != int(physical_layers_total):
        raise RuntimeError(
            f"4x4 paired-pass audit failed: CHANGE_LAYER count {change_count} != physical layer count {physical_layers_total}"
        )
    expected_z_markers = [
        BASE_H_MM if physical == 0 else BASE_H_MM + physical * MIX_H_MM
        for physical in range(int(physical_layers_total))
    ]
    actual_z_markers: List[float] = []
    for line in gcode_lines:
        text = str(line).strip()
        if text.startswith("; Z_HEIGHT:"):
            actual_z_markers.append(float(text.split(":", 1)[1].strip()))
    if len(actual_z_markers) != len(expected_z_markers) or any(
        abs(a - e) > 1e-9 for a, e in zip(actual_z_markers, expected_z_markers)
    ):
        raise RuntimeError(
            f"4x4 paired-pass audit failed: Z markers {actual_z_markers} != expected {expected_z_markers}"
        )

    tower_re = re.compile(
        r"^; FC3D_TOWER_SLOT material=([WFRYGCB]) canonical_slot=([WFRYGCB]) "
        r"slot=(\d+)/(\d+) role=(normal|filter|carry|actual|filler_previous)(?:\s.*)?$"
    )
    # v1.128: v1.92 tower scheduling is active-job-demand.  The paired-pass
    # audit must therefore prove the exact active runtime slot topology, not the
    # historic six-material canonical superset.  Ordering is still canonical
    # because get_runtime_material_order() is the canonical subset selected by
    # job demand (e.g. W,B for this capacity card).
    expected_materials = list(get_runtime_material_order())
    canonical_superset = list(RUNTIME_CANONICAL_TOWER_SLOT_ORDER)
    if not expected_materials:
        raise RuntimeError("4x4 paired-pass audit has no runtime-active tower materials")
    if any(material not in canonical_superset for material in expected_materials):
        raise RuntimeError(
            "4x4 paired-pass audit runtime tower order contains non-canonical material(s): "
            f"{expected_materials}"
        )
    expected_active_from_job = [
        material for material in canonical_superset
        if material in set(globals().get("RUNTIME_JOB_ACTIVE_MATERIALS", expected_materials))
    ]
    if expected_materials != expected_active_from_job:
        raise RuntimeError(
            "4x4 paired-pass audit runtime tower order disagrees with active-job demand: "
            f"runtime={expected_materials} job_active={expected_active_from_job}"
        )
    paired_tower_records = 0
    for row_index, row in enumerate(marker_rows):
        physical = int(row["physical"])
        pass_role = str(row["pass_role"])
        if physical not in active or pass_role not in ("normal", "filter"):
            continue
        start = marker_positions[row_index]
        end = marker_positions[row_index + 1] if row_index + 1 < len(marker_positions) else len(gcode_lines)
        region = [str(line).strip() for line in gcode_lines[start:end]]
        if pass_role == "normal":
            forbidden_boundary_records = [
                line for line in region[1:]
                if line == "; CHANGE_LAYER"
                or line.startswith("; Z_HEIGHT:")
                or line.startswith("; layer num/total_layer_count:")
                or re.match(r"^M73 L\d+(?:\s.*)?$", line)
                or re.match(r"^M991 S0 P-?\d+\s*;notify layer change$", line)
                or line.startswith("; FC3D_PHYSICAL_LAYER_STATE_RESET layer=")
            ]
            if forbidden_boundary_records:
                raise RuntimeError(
                    "4x4 paired-pass audit failed: "
                    f"layer {physical} contains physical-layer boundary records between normal and filter: "
                    f"{forbidden_boundary_records[:8]}"
                )
        found = []
        for line in region:
            match = tower_re.match(line)
            if match is not None:
                found.append({
                    "material": match.group(1),
                    "canonical_slot": match.group(2),
                    "slot": int(match.group(3)),
                    "slot_count": int(match.group(4)),
                    "role": match.group(5),
                })
        offset = 0 if pass_role == "normal" else len(expected_materials)
        expected_slots = [offset + index + 1 for index in range(len(expected_materials))]
        if [row["canonical_slot"] for row in found] != expected_materials:
            raise RuntimeError(
                f"4x4 paired-pass tower canonical order failed for layer {physical} pass {pass_role}: "
                f"found {[row['canonical_slot'] for row in found]}, expected active-job order {expected_materials}"
            )
        if [row["slot"] for row in found] != expected_slots or any(
            row["slot_count"] != 2 * len(expected_materials) for row in found
        ):
            raise RuntimeError(
                f"4x4 paired-pass tower slot numbering failed for layer {physical} pass {pass_role}: "
                f"found {[(row['slot'], row['slot_count']) for row in found]}, "
                f"expected {[(slot, 2 * len(expected_materials)) for slot in expected_slots]}"
            )
        if any(row["material"] not in get_runtime_material_order() for row in found):
            raise RuntimeError(
                f"4x4 paired-pass tower used a job-excluded filler/actual material on layer {physical} pass {pass_role}: {found}"
            )
        paired_tower_records += len(found)

    return {
        "physical_layers": int(physical_layers_total),
        "emission_passes": int(len(marker_rows)),
        "active_filter_layers": sorted(active),
        "same_z_filter_pairs": int(len(active)),
        "change_layer_count": int(change_count),
        "tower_slot_records": int(paired_tower_records),
        "result": "PASS",
    }


def audit_variable_direct_carrier_heights(gcode_lines: Sequence[str]) -> Dict[str, object]:
    """Prove the nominal-Z/absolute-G29.1 contract for every 4x4 group.

    This audit deliberately follows the final executable stream rather than
    trusting construction-time data.  It requires every XY extrusion inside a
    carrier/filter height group to occur at the logical layer's nominal model Z
    while the exact absolute trim for that carrier is active.  Lowered groups
    must restore the inherited baseline before their end marker.
    """
    marker_re = re.compile(
        r"^; FC3D_DIRECT_CARRIER_HEIGHT physical=(\d+) pass=(normal|filter) material=([WFRYGCB]) "
        r"group=(\d+)/(\d+) carrier_alpha=(\d+) height_fraction=([-+0-9.]+) "
        r"height_profile=([A-Za-z0-9_.-]+) "
        r"(?:print_speed_mm_s=[-+0-9.]+ optical_e_multiplier=[-+0-9.]+ )?"
        r"print_mode=([A-Za-z0-9_.-]+) total_depth_mm=([-+0-9.]+) "
        r"lower_nominal_z=([-+0-9.]+) nominal_print_z=([-+0-9.]+) "
        r"literal_z_equivalent=([-+0-9.]+) trim_baseline=([-+0-9.]+) "
        r"z_trim=([-+0-9.]+) effective_machine_z=([-+0-9.]+) "
        r"segments=(\d+) forced_safe_travel=([01])$"
    )
    begin_re = re.compile(
        r"^; FC3D_DIRECT_Z_TRIM_BEGIN physical=(\d+) pass=(normal|filter) material=([WFRYGCB]) "
        r"group=(\d+)/(\d+) target=([-+0-9.]+) baseline=([-+0-9.]+) safe_command_z=([-+0-9.]+)$"
    )
    restore_re = re.compile(
        r"^; FC3D_DIRECT_Z_TRIM_RESTORE physical=(\d+) pass=(normal|filter) material=([WFRYGCB]) "
        r"group=(\d+)/(\d+) active=([-+0-9.]+) baseline=([-+0-9.]+) safe_command_z=([-+0-9.]+)$"
    )
    end_re = re.compile(
        r"^; FC3D_DIRECT_CARRIER_HEIGHT_END physical=(\d+) pass=(normal|filter) material=([WFRYGCB]) "
        r"group=(\d+)/(\d+)$"
    )

    lines = [str(line) for line in gcode_lines]

    def group_key_from_match(match: re.Match) -> Tuple[int, str, str, int, int]:
        return (
            int(match.group(1)),
            str(match.group(2)),
            str(match.group(3)),
            int(match.group(4)),
            int(match.group(5)),
        )

    def nearest_executable_command(start: int, direction: int) -> Optional[str]:
        i = int(start) + int(direction)
        while 0 <= i < len(lines):
            parsed = parse_gcode_line(lines[i], i + 1, strict=True)
            if parsed.command is not None:
                return str(parsed.command)
            i += int(direction)
        return None

    absolute_xyz = True
    commanded_z: Optional[float] = None
    current_trim: Optional[float] = None
    active: Optional[Dict[str, object]] = None
    seen_group = False
    rows: List[Dict[str, object]] = []
    lowered = 0
    trim_sets = 0
    trim_restores = 0
    positive_xy_extrusions = 0
    model_g29_commands = 0

    for index, line in enumerate(lines):
        stripped = line.strip()
        marker = marker_re.match(stripped)
        begin = begin_re.match(stripped)
        restore = restore_re.match(stripped)
        end = end_re.match(stripped)

        if marker is not None:
            if active is not None:
                raise RuntimeError(f"4x4 Z-trim audit failed: nested height group at line {index + 1}")
            seen_group = True
            row: Dict[str, object] = {
                "physical": int(marker.group(1)),
                "pass_role": marker.group(2),
                "material": marker.group(3),
                "group_index": int(marker.group(4)),
                "group_count": int(marker.group(5)),
                "carrier_alpha": int(marker.group(6)),
                "height_fraction": float(marker.group(7)),
                "height_profile_id": str(marker.group(8)),
                "print_mode_id": str(marker.group(9)),
                "total_depth_mm": float(marker.group(10)),
                "lower_nominal_z": float(marker.group(11)),
                "nominal_print_z": float(marker.group(12)),
                "literal_z_equivalent": float(marker.group(13)),
                "trim_baseline": float(marker.group(14)),
                "z_trim": float(marker.group(15)),
                "effective_machine_z": float(marker.group(16)),
                "segments": int(marker.group(17)),
                "forced_safe_travel": int(marker.group(18)),
                "line_index": int(index),
                "begin_seen": False,
                "restore_seen": False,
                "target_set_count": 0,
                "baseline_restore_count": 0,
                "positive_xy_extrusions": 0,
            }
            physical = int(row["physical"])
            fraction = float(row["height_fraction"])
            baseline = float(row["trim_baseline"])
            is_zoffset = bool(globals().get("RUNTIME_DIRECT_OPERATION_GEOMETRY", False)) and direct_variable_height_operation(
                str(row["pass_role"]), str(row["material"]), int(row["physical"])
            ) in {"zoffset", "filter_zoffset"}
            if is_zoffset:
                spec = globals().get("RUNTIME_DIRECT_ZOFFSET_HEIGHT_ADJUSTMENT")
                profile_index = -1
                if isinstance(spec, dict):
                    for idx, profile in enumerate(spec.get("profiles", [])):
                        if isinstance(profile, dict) and str(profile.get("id")) == str(row["height_profile_id"]):
                            profile_index = idx
                            break
                    if profile_index < 0:
                        raise RuntimeError(f"4x4 Z-trim audit failed: unknown marker height profile in {row}")
                expected_total_depth = direct_zoffset_total_depth_mm(fraction, profile_index)
            else:
                expected_total_depth = (1.0 - min(1.0, max(0.0, fraction))) * MIX_H_MM
            row["expected_total_depth_mm"] = float(expected_total_depth)
            if abs(float(row["total_depth_mm"]) - float(f"{expected_total_depth:.8f}")) > 5e-10:
                raise RuntimeError(f"4x4 Z-trim audit failed: total depth mismatch in {row}")
            expected_lower = BASE_H_MM + (physical - 1) * MIX_H_MM
            layer_nominal = BASE_H_MM + physical * MIX_H_MM
            _audit_operation = (
                direct_variable_height_operation(
                    str(row["pass_role"]), str(row["material"]), int(row["physical"])
                )
                if is_zoffset else "ordinary"
            )
            _audit_same_layer_shift = direct_same_layer_filter_representation_shift_mm(_audit_operation)
            expected_literal = direct_total_depth_print_z(
                physical + (1 if _audit_operation == "filter_zoffset" else 0),
                expected_total_depth,
            )
            _audit_profile = direct_zoffset_height_profile(profile_index) if is_zoffset else {}
            _audit_rep = str(_audit_profile.get("static_height_representation", "g29")).strip().lower()
            if _audit_operation == "filter_zoffset" and _audit_rep != "g29":
                raise RuntimeError(
                    "4x4 Z-trim audit failed: same-layer filter_zoffset must remain nominal-G1Z/G29"
                )
            if is_zoffset and _audit_rep == "direct_g1z":
                expected_nominal = expected_literal
                expected_trim = baseline
                expected_effective = expected_literal + baseline
            else:
                expected_nominal = layer_nominal
                expected_trim = (
                    direct_total_depth_z_trim(expected_total_depth, baseline)
                    + _audit_same_layer_shift
                )
                expected_effective = layer_nominal + expected_trim
            expected_alpha = int(round(fraction * 128.0))
            # These audit values are written into the marker at exactly five
            # decimal places.  Compare against expectations quantised through the
            # same formatter rather than against unrounded binary floats.  Values
            # such as 0.211875 legitimately emit as 0.21188; comparing that text
            # back to 0.211875 with a nominal 5e-6 threshold can exceed the limit
            # by a few binary floating-point ulps and fail despite identical G-code.
            def marker_5dp(value: float) -> float:
                return quantize_direct_g29_trim_5dp(value)

            expected_trim_5dp = marker_5dp(expected_trim)
            baseline_5dp = marker_5dp(baseline)
            checks = (
                ("lower nominal Z", float(row["lower_nominal_z"]), marker_5dp(expected_lower)),
                ("nominal print Z", float(row["nominal_print_z"]), marker_5dp(expected_nominal)),
                ("literal-Z equivalent", float(row["literal_z_equivalent"]), marker_5dp(expected_literal)),
                ("absolute Z trim", float(row["z_trim"]), expected_trim_5dp),
                ("effective machine Z", float(row["effective_machine_z"]), marker_5dp(expected_effective)),
            )
            for label, actual, expected in checks:
                if abs(actual - expected) > 5e-10:
                    raise RuntimeError(
                        f"4x4 Z-trim audit failed: {label} {actual:.5f} != {expected:.5f} in {row}"
                    )
            if int(row["carrier_alpha"]) != expected_alpha:
                raise RuntimeError(f"4x4 Z-trim audit failed: carrier alpha/fraction mismatch in {row}")
            if current_trim is None or abs(float(current_trim) - baseline) > 5e-6:
                raise RuntimeError(
                    "4x4 Z-trim audit failed: group did not begin at its inherited baseline; "
                    f"current={current_trim}, expected={baseline:.5f}, row={row}"
                )
            if expected_trim_5dp < baseline_5dp:
                lowered += 1
            if expected_trim_5dp != baseline_5dp:
                if int(row["forced_safe_travel"]) != 1:
                    raise RuntimeError(f"4x4 Z-trim audit failed: adjusted group lacks forced safe travel in {row}")
            active = row
            continue

        if begin is not None:
            if active is None or group_key_from_match(begin) != (
                int(active["physical"]), str(active["pass_role"]), str(active["material"]),
                int(active["group_index"]), int(active["group_count"]),
            ):
                raise RuntimeError(f"4x4 Z-trim audit failed: unmatched trim-begin marker at line {index + 1}")
            if abs(float(active["z_trim"]) - float(active["trim_baseline"])) <= 1e-9 or bool(active["begin_seen"]):
                raise RuntimeError(f"4x4 Z-trim audit failed: unexpected duplicate/unchanged trim begin in {active}")
            if abs(float(begin.group(6)) - float(active["z_trim"])) > 5e-6:
                raise RuntimeError(f"4x4 Z-trim audit failed: trim-begin target mismatch in {active}")
            if abs(float(begin.group(7)) - float(active["trim_baseline"])) > 5e-6:
                raise RuntimeError(f"4x4 Z-trim audit failed: trim-begin baseline mismatch in {active}")
            expected_safe = float(active["nominal_print_z"]) + HOP_Z_MM
            if abs(float(begin.group(8)) - expected_safe) > 5e-6:
                raise RuntimeError(f"4x4 Z-trim audit failed: trim-begin safe Z mismatch in {active}")
            active["begin_seen"] = True
            continue

        if restore is not None:
            if active is None or group_key_from_match(restore) != (
                int(active["physical"]), str(active["pass_role"]), str(active["material"]),
                int(active["group_index"]), int(active["group_count"]),
            ):
                raise RuntimeError(f"4x4 Z-trim audit failed: unmatched restore marker at line {index + 1}")
            if not bool(active["begin_seen"]) or bool(active["restore_seen"]):
                raise RuntimeError(f"4x4 Z-trim audit failed: restore order mismatch in {active}")
            if current_trim is None or abs(float(current_trim) - float(active["z_trim"])) > 5e-6:
                raise RuntimeError(f"4x4 Z-trim audit failed: restore began without target trim active in {active}")
            if abs(float(restore.group(6)) - float(active["z_trim"])) > 5e-6:
                raise RuntimeError(f"4x4 Z-trim audit failed: restore active trim mismatch in {active}")
            if abs(float(restore.group(7)) - float(active["trim_baseline"])) > 5e-6:
                raise RuntimeError(f"4x4 Z-trim audit failed: restore baseline mismatch in {active}")
            expected_safe = float(active["nominal_print_z"]) + HOP_Z_MM
            if abs(float(restore.group(8)) - expected_safe) > 5e-6:
                raise RuntimeError(f"4x4 Z-trim audit failed: restore safe Z mismatch in {active}")
            active["restore_seen"] = True
            continue

        if end is not None:
            if active is None or group_key_from_match(end) != (
                int(active["physical"]), str(active["pass_role"]), str(active["material"]),
                int(active["group_index"]), int(active["group_count"]),
            ):
                raise RuntimeError(f"4x4 Z-trim audit failed: unmatched height-end marker at line {index + 1}")
            trim_changed = abs(float(active["z_trim"]) - float(active["trim_baseline"])) > 1e-9
            if trim_changed:
                if not bool(active["begin_seen"]) or not bool(active["restore_seen"]):
                    raise RuntimeError(f"4x4 Z-trim audit failed: adjusted group lacks begin/restore pair in {active}")
                if int(active["target_set_count"]) != 1 or int(active["baseline_restore_count"]) != 1:
                    raise RuntimeError(f"4x4 Z-trim audit failed: adjusted group G29.1 count mismatch in {active}")
            elif bool(active["begin_seen"]) or bool(active["restore_seen"]) or int(active["target_set_count"]) or int(active["baseline_restore_count"]):
                raise RuntimeError(f"4x4 Z-trim audit failed: unchanged group changed Z trim in {active}")
            if int(active["positive_xy_extrusions"]) < 1:
                raise RuntimeError(f"4x4 Z-trim audit failed: height group contains no positive XY extrusion in {active}")
            baseline = float(active["trim_baseline"])
            if current_trim is None or abs(float(current_trim) - baseline) > 5e-6:
                raise RuntimeError(f"4x4 Z-trim audit failed: group ended without baseline restored in {active}")
            rows.append(dict(active))
            active = None
            continue

        parsed = parse_gcode_line(line, index + 1, strict=True)
        command = str(parsed.command or "")
        params = parsed.numeric_parameters() if parsed.command is not None else {}

        if command == "G90":
            absolute_xyz = True
        elif command == "G91":
            absolute_xyz = False
        elif command == "G92" and "Z" in params:
            commanded_z = float(params["Z"])
        elif command in ("G0", "G00", "G1", "G01") and "Z" in params:
            z_value = float(params["Z"])
            commanded_z = z_value if absolute_xyz or commanded_z is None else float(commanded_z + z_value)

        if command == "G29.1":
            z_word = parsed.optional_word("Z")
            if z_word is None or z_word[1].numeric is None:
                raise RuntimeError(f"4x4 Z-trim audit failed: non-numeric G29.1 Z at line {index + 1}")
            next_trim = float(z_word[1].numeric)
            if active is None:
                if seen_group:
                    raise RuntimeError(
                        f"4x4 Z-trim audit failed: G29.1 outside a closed height group at line {index + 1}"
                    )
                current_trim = next_trim
                continue
            model_g29_commands += 1
            if nearest_executable_command(index, -1) != "M400" or nearest_executable_command(index, 1) != "M400":
                raise RuntimeError(f"4x4 Z-trim audit failed: G29.1 is not bracketed by M400 at line {index + 1}")
            target = float(active["z_trim"])
            baseline = float(active["trim_baseline"])
            if not bool(active["restore_seen"]):
                if not bool(active["begin_seen"]) or int(active["target_set_count"]) != 0:
                    raise RuntimeError(f"4x4 Z-trim audit failed: target trim set out of order in {active}")
                if abs(next_trim - target) > 5e-6:
                    raise RuntimeError(f"4x4 Z-trim audit failed: target G29.1 {next_trim:.5f} != {target:.5f} in {active}")
                active["target_set_count"] = 1
                trim_sets += 1
            else:
                if int(active["target_set_count"]) != 1 or int(active["baseline_restore_count"]) != 0:
                    raise RuntimeError(f"4x4 Z-trim audit failed: baseline restore set out of order in {active}")
                if abs(next_trim - baseline) > 5e-6:
                    raise RuntimeError(f"4x4 Z-trim audit failed: restore G29.1 {next_trim:.5f} != {baseline:.5f} in {active}")
                active["baseline_restore_count"] = 1
                trim_restores += 1
            current_trim = next_trim
            continue

        if active is not None and command in ("G0", "G00", "G1", "G01"):
            e_value = float(params.get("E", 0.0))
            if e_value > 0.0 and ("X" in params or "Y" in params):
                target = float(active["z_trim"])
                nominal = float(active["nominal_print_z"])
                if current_trim is None or abs(float(current_trim) - target) > 5e-6:
                    raise RuntimeError(f"4x4 Z-trim audit failed: XY extrusion without target trim active in {active}")
                if commanded_z is None or abs(float(commanded_z) - nominal) > 5e-6:
                    # v1.103 permits an explicitly tagged progressive Z relief only
                    # during the final <=0.20 mm printed endpoint segment.  The
                    # G29.1 depth trim remains unchanged; only model Z rises by
                    # the literal relief amount encoded in the marker.
                    m_relief = re.search(r"\bz_relief=([0-9]+(?:\.[0-9]+)?)", line)
                    allowed_relief = None if m_relief is None else float(m_relief.group(1))
                    if (
                        allowed_relief is None
                        or allowed_relief < -1e-9
                        or allowed_relief > 0.050 + 1e-9
                        or "FC3D_END_" not in line
                        or abs(float(commanded_z) - (nominal + allowed_relief)) > 6e-6
                    ):
                        raise RuntimeError(
                            "4x4 Z-trim audit failed: XY extrusion is not at nominal model Z or valid tagged end-Z relief; "
                            f"commanded={commanded_z}, expected={nominal:.5f}, line={line!r}, row={active}"
                        )
                active["positive_xy_extrusions"] = int(active["positive_xy_extrusions"]) + 1
                positive_xy_extrusions += 1

    if active is not None:
        raise RuntimeError(f"4x4 Z-trim audit failed: unterminated height group {active}")
    if not rows:
        raise RuntimeError("4x4 Z-trim audit failed: no direct carrier-height groups found")
    baselines = sorted({round(float(row["trim_baseline"]), 8) for row in rows})
    if len(baselines) != 1:
        raise RuntimeError(f"4x4 Z-trim audit failed: inconsistent inherited baselines {baselines}")
    if current_trim is None or abs(float(current_trim) - float(baselines[0])) > 5e-6:
        raise RuntimeError(
            f"4x4 Z-trim audit failed: final trim {current_trim} != inherited baseline {baselines[0]:.5f}"
        )
    return {
        "result": "PASS",
        "height_group_markers": int(len(rows)),
        "lowered_height_groups": int(lowered),
        "g29_target_sets": int(trim_sets),
        "g29_baseline_restores": int(trim_restores),
        "model_g29_commands": int(model_g29_commands),
        "positive_xy_extrusions_at_nominal_z": int(positive_xy_extrusions),
        "inherited_baseline_trim_mm": float(baselines[0]),
        "lower_carrier_filter_formula": "carrier: nominal_model_z + baseline_trim; same-layer filter_zoffset: nominal_model_z + baseline_trim + MIX_H_MM - calibrated_total_depth",
        "upper_zoffset_formula": "nominal_model_z + baseline_trim - (alpha/128) * 0.02mm - (1 - alpha/128) * 0.10mm",
        "upper_zoffset_extra_depth_mode": "dose_scaled_alpha_fraction",
        "upper_zoffset_extra_depth_full_dose_mm": float(DIRECT_ZOFFSET_EXTRA_DEPTH_MM),
        "upper_zoffset_extra_depth_mm": float(DIRECT_ZOFFSET_EXTRA_DEPTH_MM),
        "lower_filter_phase_shift_mm": float(direct_filter_phase_shift_mm()),
        "lower_filter_extra_depth_mm": 0.0,
        "model_extrusion_z": "nominal logical-layer Z only",
    }


def _road_direction_for_direct_optical_slot(slot_index_zero_based: int) -> str:
    """Return emitted road direction for a direct optical slot.

    The solid base is emitted as physical layer 0 with X roads in this PP path.
    The first optical slot above it is physical layer 1 and emits Y roads; the
    direction then alternates. This was verified on the v8 red halftone audit.
    """
    physical_layer = int(slot_index_zero_based) + 1
    return "Y" if (physical_layer % 2) == 1 else "X"



def _normalise_demand_optical_state(doc: Dict[str, object]) -> Dict[str, object]:
    """Normalise recipegen calibration params / calibration_state into PP optical model fields.

    PPSPV7.2 adds the corrected filter/blend model used by recipegenv66:
      - start from measured/printable white
      - ignore leading W before first colour
      - RGBCY multiply current RGB by material_filter_rgb multipliers
      - active W blends current RGB back toward printable white
      - preserve bottom-to-top order

    Legacy filter_rgb endpoint models are still accepted as fallback.
    """
    source_detail = "top_level"
    if isinstance(doc, dict) and isinstance(doc.get("calibration_bundle"), dict):
        bundle = doc.get("calibration_bundle") or {}
        if isinstance(bundle.get("modified_calibration_state"), dict):
            doc = dict(bundle["modified_calibration_state"])
            source_detail = "calibration_bundle.modified_calibration_state"
    if isinstance(doc, dict) and source_detail == "top_level" and isinstance(doc.get("modified_calibration_state"), dict):
        doc = dict(doc["modified_calibration_state"])
        source_detail = "modified_calibration_state"
    if isinstance(doc, dict) and source_detail == "top_level" and isinstance(doc.get("effective_calibration_state"), dict):
        doc = dict(doc["effective_calibration_state"])
        source_detail = "effective_calibration_state"
    if isinstance(doc, dict) and source_detail == "top_level" and isinstance(doc.get("calibration_state"), dict):
        doc = dict(doc["calibration_state"])
        source_detail = "calibration_state"
    if not isinstance(doc, dict):
        doc = {}

    def _rgb3(value, default):
        try:
            arr = np.asarray(value if value is not None else default, dtype=np.float64)
            if arr.shape == (3,) and np.all(np.isfinite(arr)):
                return [float(x) for x in np.clip(arr, 0.0, 255.0).tolist()]
        except Exception:
            pass
        return [float(x) for x in default]

    remap = doc.get("target_rgb_remap_for_lut", {}) if isinstance(doc.get("target_rgb_remap_for_lut", {}), dict) else {}
    mw = doc.get("measured_white_substrate", {}) if isinstance(doc.get("measured_white_substrate", {}), dict) else {}
    printable_white = (
        doc.get("recipe_prediction_substrate_rgb")
        or doc.get("printable_white_rgb")
        or remap.get("target_remap_white_rgb")
        or remap.get("printable_white_rgb")
        or remap.get("rgb_255_255_255_maps_to")
        or mw.get("rgb")
        or doc.get("w_endpoint_rgb")
        or [255.0, 255.0, 255.0]
    )
    printable_white_rgb = _rgb3(printable_white, [255.0, 255.0, 255.0])

    model_name = str(doc.get("model", ""))
    cal_type = str(doc.get("calibration_model_type", ""))
    material_filter_src = doc.get("material_filter_rgb", {})
    material_filter: Dict[str, List[float]] = {}
    is_filter_blend = (
        cal_type == "rgb_filter_multiply_ordered_w_blend"
        or model_name == "fc3d_rgb_filter_multiply_ordered_w_blend_v1"
        or isinstance(material_filter_src, dict) and bool(material_filter_src)
    )
    if isinstance(material_filter_src, dict):
        for k, v in material_filter_src.items():
            try:
                arr = np.asarray(v, dtype=np.float64)
                if arr.shape == (3,) and np.all(np.isfinite(arr)):
                    material_filter[str(k).upper()] = [float(x) for x in np.clip(arr, 0.0, 2.0).tolist()]
            except Exception:
                pass

    filt = doc.get("filter_rgb", {}) if isinstance(doc.get("filter_rgb", {}), dict) else {}
    filter_rgb: Dict[str, List[float]] = {}
    if isinstance(filt, dict):
        for k, v in filt.items():
            try:
                arr = np.asarray(v, dtype=np.float64)
                if arr.shape == (3,) and np.all(np.isfinite(arr)):
                    filter_rgb[str(k).upper()] = [float(x) for x in np.clip(arr, 0.0, 255.0).tolist()]
            except Exception:
                pass

    # If v66-style material_filter_rgb is present, derive endpoint-form filter_rgb
    # for legacy reporting only.  Prediction uses material_filter_rgb directly.
    if material_filter:
        white = np.asarray(printable_white_rgb, dtype=np.float64)
        for m, f in material_filter.items():
            filter_rgb[m] = [float(x) for x in np.clip(white * np.asarray(f, dtype=np.float64), 0.0, 255.0).tolist()]
    elif is_filter_blend and filter_rgb:
        white = np.maximum(np.asarray(printable_white_rgb, dtype=np.float64), 1e-6)
        for m, endpoint in filter_rgb.items():
            material_filter[m] = [float(x) for x in np.clip(np.asarray(endpoint, dtype=np.float64) / white, 0.0, 2.0).tolist()]

    model = {
        "source": "calibration_params_json",
        "model_type": "rgb_filter_multiply_ordered_w_blend" if is_filter_blend else "legacy_filter_endpoint",
        "filter_rgb": filter_rgb,
        "material_filter_rgb": material_filter,
        "w_blend_strength": float(doc.get("w_blend_strength", doc.get("w_whiten", 0.38))),
        "w_whiten": float(doc.get("w_blend_strength", doc.get("w_whiten", 0.38))),
        "f_whiten": float(doc.get("f_whiten", 0.15)),
        "w_endpoint_rgb": printable_white_rgb if is_filter_blend else _rgb3(doc.get("w_endpoint_rgb"), [255.0, 255.0, 255.0]),
        "f_endpoint_rgb": _rgb3(doc.get("f_endpoint_rgb"), printable_white_rgb if is_filter_blend else [255.0, 255.0, 255.0]),
        "recipe_prediction_substrate_rgb": printable_white_rgb,
        "printable_white_rgb": printable_white_rgb,
        "model_name": model_name,
        "calibration_model_type": cal_type,
        "schema_version": doc.get("schema_version"),
        "state_source_detail": source_detail,
        "effective_state_name": "modified_calibration_state" if "modified" in str(source_detail) or "effective" in str(source_detail) else source_detail,
        "recipe_prediction_formula": "filter_blend" if is_filter_blend else "legacy_endpoint",
    }

    # Ensure all colour keys exist if old/default params are sparse.
    defaults_endpoint = {
        "R": [248.0, 110.0, 110.0],
        "Y": [248.0, 248.0, 110.0],
        "G": [140.0, 248.0, 140.0],
        "C": [180.0, 248.0, 248.0],
        "B": [110.0, 110.0, 248.0],
    }
    for m, v in defaults_endpoint.items():
        model["filter_rgb"].setdefault(m, [float(x) for x in v])
        if is_filter_blend:
            white = np.maximum(np.asarray(model["w_endpoint_rgb"], dtype=np.float64), 1e-6)
            model["material_filter_rgb"].setdefault(m, [float(x) for x in np.clip(np.asarray(model["filter_rgb"][m], dtype=np.float64) / white, 0.0, 2.0).tolist()])
    return model


def _demand_optical_model_from_params_file(path: Path) -> Dict[str, object]:
    path = Path(path)
    if not path.exists():
        raise FileNotFoundError(f"Calibration params file not found: {path}")
    doc = json.loads(path.read_text(encoding="utf-8"))
    model = _normalise_demand_optical_state(doc)
    model["source"] = "calibration_params_file"
    model["source_path"] = str(path)
    try:
        model["source_sha256"] = hashlib.sha256(path.read_bytes()).hexdigest()
    except Exception:
        pass
    return model


def _demand_optical_model_from_lookup(lookup: Optional["RecipeLookup"]) -> Dict[str, object]:
    """Return the optical calibration used to recompute demand-stack RGB.

    PPV114 preference order:
      1. LUT metadata modified_calibration_state / calibration_bundle.modified_calibration_state.
      2. --calibration-params-file, which itself may contain modified_calibration_state.
      3. Legacy LUT metadata calibration_state.
      4. Hard-coded fallback defaults.

    This ensures recipegenv61+ LUTs carry their effective modified colour model
    downstream even when the user also passes the original unmodified params file.
    """
    if lookup is not None:
        try:
            meta = json.loads(getattr(lookup, "metadata_json", "{}") or "{}")
        except Exception:
            meta = getattr(lookup, "metadata", {}) or {}
        if isinstance(meta, dict):
            bundle = meta.get("calibration_bundle", {})
            if isinstance(bundle, dict) and isinstance(bundle.get("modified_calibration_state"), dict):
                model = _normalise_demand_optical_state({"calibration_bundle": bundle})
                model["source"] = "lut_metadata.calibration_bundle.modified_calibration_state"
                return model
            if isinstance(meta.get("modified_calibration_state"), dict):
                model = _normalise_demand_optical_state({"modified_calibration_state": meta.get("modified_calibration_state")})
                model["source"] = "lut_metadata.modified_calibration_state"
                return model
            if isinstance(meta.get("effective_calibration_state"), dict):
                model = _normalise_demand_optical_state({"effective_calibration_state": meta.get("effective_calibration_state")})
                model["source"] = "lut_metadata.effective_calibration_state"
                return model

    params_path = globals().get("RUNTIME_CALIBRATION_PARAMS_FILE", None)
    if params_path:
        return _demand_optical_model_from_params_file(Path(params_path))

    default_filter = {
        "R": [241.5, 134.5, 96.5],
        "Y": [226.3, 226.6, 86.9],
        "G": [175.8, 228.1, 129.3],
        "C": [177.4, 219.3, 206.1],
        "B": [79.1, 161.7, 226.7],
    }
    model = {
        "source": "fallback_defaults_not_lut_calibration_state",
        "filter_rgb": {k: [float(x) for x in v] for k, v in default_filter.items()},
        "w_whiten": 0.62,
        "f_whiten": 0.055,
        "w_endpoint_rgb": [255.0, 255.0, 255.0],
        "f_endpoint_rgb": [255.0, 255.0, 255.0],
    }
    if lookup is None:
        return model
    try:
        meta = json.loads(getattr(lookup, "metadata_json", "{}") or "{}")
    except Exception:
        meta = getattr(lookup, "metadata", {}) or {}
    state = meta.get("calibration_state", {}) if isinstance(meta, dict) else {}
    if isinstance(state, dict) and isinstance(state.get("filter_rgb"), dict):
        model = _normalise_demand_optical_state(state)
        model["source"] = "lut_metadata.calibration_state"
    return model


def _apply_demand_optical_layer_rgb(rgb: np.ndarray, mat: str, dose: float, model: Dict[str, object]) -> np.ndarray:
    """Apply one optical layer for legacy callers.

    For v66/v67 filter-blend params this applies the colour multiplier and W blend,
    but it does not know whether W is leading.  New sequence-aware callers use
    _predict_demand_sequence_rgb_from_mats_doses() so leading W is ignored.
    """
    rgb = np.asarray(rgb, dtype=np.float64)
    mat = str(mat).upper()
    dose = float(dose)
    if dose <= 0.0 or mat in (".", "0", "", "NONE"):
        return rgb.copy()

    material_filter = model.get("material_filter_rgb", {})
    if isinstance(material_filter, dict) and mat in material_filter:
        full_t = np.asarray(material_filter[mat], dtype=np.float64)
        t = 1.0 - np.clip(dose, 0.0, 1.0) * (1.0 - full_t)
        return rgb * np.clip(t, 0.0, 2.0)

    filter_rgb = model.get("filter_rgb", {})
    if isinstance(filter_rgb, dict) and mat in filter_rgb:
        full_t = np.asarray(filter_rgb[mat], dtype=np.float64) / 255.0
        t = 1.0 - np.clip(dose, 0.0, 1.0) * (1.0 - full_t)
        return rgb * np.clip(t, 0.0, 2.0)

    if mat == "W":
        ep = np.asarray(model.get("w_endpoint_rgb", model.get("recipe_prediction_substrate_rgb", [255.0, 255.0, 255.0])), dtype=np.float64)
        return rgb + (ep - rgb) * np.clip(float(model.get("w_blend_strength", model.get("w_whiten", 0.0))) * dose, 0.0, 1.0)
    if mat == "F":
        ep = np.asarray(model.get("f_endpoint_rgb", [255.0, 255.0, 255.0]), dtype=np.float64)
        return rgb + (ep - rgb) * np.clip(float(model.get("f_whiten", 0.0)) * dose, 0.0, 1.0)
    return rgb.copy()


def _predict_demand_sequence_rgb_from_mats_doses(mats: Sequence[str], doses: Sequence[float], model: Dict[str, object]) -> np.ndarray:
    """Predict RGB from physical bottom->top material/dose sequence.

    PPSPV7.2 corrected v66/v67 maths:
      - start at measured printable white
      - leading W before first RGBCY colour is structural only
      - RGBCY multiply current RGB by material_filter_rgb[M]
      - active W after colour blends current RGB toward measured printable white
      - ordering is preserved; e.g. WWWRRWBW replays as RRWBW
    """
    model_type = str(model.get("model_type", ""))
    has_filter_blend = model_type == "rgb_filter_multiply_ordered_w_blend" or bool(model.get("material_filter_rgb", {}))
    if not has_filter_blend:
        rgb = np.asarray(model.get("w_endpoint_rgb", [255.0, 255.0, 255.0]), dtype=np.float64)
        for mat, dose0 in zip(mats, doses):
            mat = str(mat).upper()
            if mat == EMPTY_MAT or mat in (".", "", "NONE"):
                continue
            d = float(dose0)
            if d <= 0.0:
                continue
            rgb = _apply_demand_optical_layer_rgb(rgb, mat, d, model)
        return np.clip(rgb, 0.0, 255.0).astype(np.float32)

    white = np.asarray(model.get("recipe_prediction_substrate_rgb", model.get("w_endpoint_rgb", [255.0, 255.0, 255.0])), dtype=np.float64)
    rgb = white.copy()
    filters = model.get("material_filter_rgb", {})
    if not isinstance(filters, dict):
        filters = {}
    w_strength = float(model.get("w_blend_strength", model.get("w_whiten", 0.0)))
    seen_colour = False
    for mat, dose0 in zip(mats, doses):
        mat = str(mat).upper()
        if mat == EMPTY_MAT or mat in (".", "", "NONE"):
            continue
        d = float(dose0)
        if d <= 0.0:
            continue
        if mat in filters:
            f = np.asarray(filters[mat], dtype=np.float64)
            f_eff = 1.0 - np.clip(d, 0.0, 1.0) * (1.0 - f)
            rgb = rgb * np.clip(f_eff, 0.0, 2.0)
            seen_colour = True
        elif mat == "W":
            if seen_colour:
                s = np.clip(w_strength * d, 0.0, 1.0)
                rgb = rgb + (white - rgb) * s
            # else leading W is structural substrate: no optical action
        elif mat == "F":
            # Current no-F LUTs should not use F; legacy F remains neutral here
            # for the filter-blend model.
            pass
        rgb = np.clip(rgb, 0.0, 255.0)
    return np.clip(rgb, 0.0, 255.0).astype(np.float32)



def _structural_w_slot_dict() -> Dict[str, object]:
    """Return a synthetic solid-W slot used only for PP structural normalisation.

    This is not a colour re-fit. It is the old allocator behaviour restored for
    locked exact candidate emission: if a physical optical slot/phase would
    otherwise be air in a normal picture print, fill it with structural W.
    """
    return {
        "mode": "solid",
        "a": {
            "material": DEFAULT_STRUCTURAL_FILL_MATERIAL,
            "mode": "solid",
            "effective_units": 0,
            "printed_dose": float(DEFAULT_STRUCTURAL_FILL_DOSE),
            "ppv107_structural_fill": True,
        },
    }


def _normalised_locked_fit_dict_slots(fit_dict: Dict[str, object], n_slots: int) -> List[Dict[str, object]]:
    """Return exactly n_slots physical slots with accidental EMPTY converted to structural W.

    Policy for normal demand-LUT picture prints:
      - preserve every non-empty material/dose from candidate_packed_stack_json;
      - short candidate stacks are top-aligned, with missing lower slots filled with W,
        matching the old _apply_fit_to_stack_cell/fitted-stack behaviour;
      - explicit empty slots are structural W, not air;
      - half_single inactive phase is a genuine half-tone air gap and is handled by the caller.

    This is deliberately not a demand solve and does not change any non-empty selected
    material or printed_dose value.
    """
    raw_slots = [slot for slot in (fit_dict.get("slots", []) if isinstance(fit_dict, dict) else []) if isinstance(slot, dict)]
    n = int(n_slots)
    out = [_structural_w_slot_dict() for _ in range(n)]
    used = min(len(raw_slots), n)
    offset = max(0, n - used)
    for local_i, slot in enumerate(raw_slots[:used]):
        si = offset + local_i
        mode = str(slot.get("mode", "empty"))
        if mode == "empty":
            out[si] = _structural_w_slot_dict()
        else:
            out[si] = slot
    return out


def _apply_slot_dict_to_phases(phase_a: np.ndarray, phase_b: np.ndarray, slot: Dict[str, object], optical_model: Dict[str, object]) -> Tuple[np.ndarray, np.ndarray]:
    """Apply one FitResult.to_dict slot using recipegenv32 half/dose semantics."""
    mode = str(slot.get("mode", "empty"))
    a = slot.get("a") if isinstance(slot.get("a"), dict) else None
    b = slot.get("b") if isinstance(slot.get("b"), dict) else None
    if mode == "solid" and a is not None:
        mat = str(a.get("material")); dose = float(a.get("printed_dose", 0.0))
        phase_a = _apply_demand_optical_layer_rgb(phase_a, mat, dose, optical_model)
        phase_b = _apply_demand_optical_layer_rgb(phase_b, mat, dose, optical_model)
    elif mode == "half_single" and a is not None:
        mat = str(a.get("material")); dose = float(a.get("printed_dose", 0.0))
        phase_a = _apply_demand_optical_layer_rgb(phase_a, mat, dose, optical_model)
    elif mode == "half_dual":
        if a is not None:
            phase_a = _apply_demand_optical_layer_rgb(phase_a, str(a.get("material")), float(a.get("printed_dose", 0.0)), optical_model)
        if b is not None:
            phase_b = _apply_demand_optical_layer_rgb(phase_b, str(b.get("material")), float(b.get("printed_dose", 0.0)), optical_model)
    elif mode == "empty":
        pass
    else:
        raise ValueError(f"Unsupported stack slot mode in LUT candidate JSON: {mode!r}")
    return phase_a, phase_b

def _apply_slot_dict_to_phases_ppv107_structural(phase_a: np.ndarray, phase_b: np.ndarray, slot: Dict[str, object], optical_model: Dict[str, object]) -> Tuple[np.ndarray, np.ndarray]:
    """Apply one locked slot with PPV107 structural fill semantics.

    Difference from _apply_slot_dict_to_phases:
      half_single inactive phase remains air; full empty slots are structural W.
    """
    mode = str(slot.get("mode", "empty"))
    a = slot.get("a") if isinstance(slot.get("a"), dict) else None
    b = slot.get("b") if isinstance(slot.get("b"), dict) else None
    fill_mat = str(DEFAULT_STRUCTURAL_FILL_MATERIAL)
    fill_dose = float(DEFAULT_STRUCTURAL_FILL_DOSE)
    if mode == "solid" and a is not None:
        mat = str(a.get("material")); dose = float(a.get("printed_dose", 0.0))
        phase_a = _apply_demand_optical_layer_rgb(phase_a, mat, dose, optical_model)
        phase_b = _apply_demand_optical_layer_rgb(phase_b, mat, dose, optical_model)
    elif mode == "half_single" and a is not None:
        # Genuine half-tone air gap: active phase prints selected material/dose;
        # inactive phase is intentionally not printed.  A future explicit
        # half-tone-with-W mode should use a distinct recipe representation.
        mat = str(a.get("material")); dose = float(a.get("printed_dose", 0.0))
        phase_a = _apply_demand_optical_layer_rgb(phase_a, mat, dose, optical_model)
    elif mode == "half_dual":
        if a is not None:
            phase_a = _apply_demand_optical_layer_rgb(phase_a, str(a.get("material")), float(a.get("printed_dose", 0.0)), optical_model)
        else:
            phase_a = _apply_demand_optical_layer_rgb(phase_a, fill_mat, fill_dose, optical_model)
        if b is not None:
            phase_b = _apply_demand_optical_layer_rgb(phase_b, str(b.get("material")), float(b.get("printed_dose", 0.0)), optical_model)
        else:
            phase_b = _apply_demand_optical_layer_rgb(phase_b, fill_mat, fill_dose, optical_model)
    elif mode == "empty":
        phase_a = _apply_demand_optical_layer_rgb(phase_a, fill_mat, fill_dose, optical_model)
        phase_b = _apply_demand_optical_layer_rgb(phase_b, fill_mat, fill_dose, optical_model)
    else:
        raise ValueError(f"Unsupported stack slot mode in PPV107 locked candidate JSON: {mode!r}")
    return phase_a, phase_b



def _slot_modes_from_fit_dict_for_debug(fit_dict: Dict[str, object]) -> List[Dict[str, object]]:
    rows = []
    for li, slot in enumerate(fit_dict.get("slots", []) if isinstance(fit_dict, dict) else []):
        if not isinstance(slot, dict):
            continue
        row = {"layer": int(li + 1), "mode": str(slot.get("mode", "empty"))}
        for key in ("a", "b"):
            seg = slot.get(key)
            if isinstance(seg, dict):
                row[key] = {
                    "material": str(seg.get("material", "")),
                    "mode": str(seg.get("mode", "")),
                    "effective_units": int(seg.get("effective_units", 0)),
                    "printed_dose": float(seg.get("printed_dose", 0.0)),
                }
        rows.append(row)
    return rows

def _fit_result_slot_modes_for_debug(fit) -> List[Dict[str, object]]:
    rows = []
    for li, slot in enumerate(getattr(fit, "slots", [])):
        row = {"layer": int(li + 1), "mode": str(slot.mode)}
        for key, seg in (("a", slot.a), ("b", slot.b)):
            if seg is not None:
                row[key] = {
                    "material": str(seg.material),
                    "mode": str(seg.mode),
                    "effective_units": int(seg.effective_units),
                    "printed_dose": float(seg.printed_dose),
                }
        rows.append(row)
    return rows

def _phase_for_direct_slot_cell(slot_index_zero_based: int, x_idx: int, y_idx: int, head_width_px: int) -> int:
    """Return 0/1 complementary half-tone phase for this cell/slot.

    Phase changes perpendicular to the emitted road direction so one G-code road
    does not contain a material change. head_width_px allows 0.10 mm demand maps
    to group four pixels into one 0.40 mm road phase.
    """
    hw = max(1, int(head_width_px))
    direction = _road_direction_for_direct_optical_slot(slot_index_zero_based)
    if direction == "Y":
        return (int(x_idx) // hw) & 1
    return (int(y_idx) // hw) & 1



STRUCTURAL_W_ONLY_SENTINEL = "__FC3D_STRUCTURAL_W_ONLY__"


def _structurally_fill_empty_stack_slots(mats: np.ndarray, rdose: np.ndarray) -> Tuple[np.ndarray, np.ndarray, int]:
    """Bottom-lift short recipe stacks with mandatory structural W.

    Physical slot convention in PP is bottom-to-top.  The W used only to lift /
    support a short selected recipe must therefore live in the LOWER physical
    slots, with the selected non-empty recipe tokens shifted upward and kept in
    their original bottom-to-top order.

    The older PPSPV3/PPSPV10 repair filled every empty slot in-place.  If the
    v64 stack LUT stored a compact recipe followed by empty top slots, that
    put structural W above the colour recipe.  The final exact-stack preview
    then interpreted that top W optically, creating bright white sky speckles.

    This function now converts, for example:
        [B, C, EMPTY, EMPTY, EMPTY, EMPTY, EMPTY, EMPTY]
    into:
        [W, W, W, W, W, W, B, C]
    not:
        [B, C, W, W, W, W, W, W]

    This does not change the selected recipe token sequence; it only places the
    structural lift/support W below that sequence.
    """
    mats_in = np.asarray(mats, dtype='<U1')
    dose_in = np.asarray(rdose, dtype=np.float32)
    n = int(len(dose_in))
    fill_mat = str(DEFAULT_STRUCTURAL_FILL_MATERIAL)
    fill_dose = float(DEFAULT_STRUCTURAL_FILL_DOSE)

    keep_mats = []
    keep_dose = []
    repaired = 0
    for si in range(n):
        m = str(mats_in[si])
        d = float(dose_in[si])
        if d > 0.0 and m != EMPTY_MAT:
            keep_mats.append(m)
            keep_dose.append(d)
        else:
            repaired += 1

    out_mats = np.full((n,), fill_mat, dtype='<U1')
    out_dose = np.full((n,), fill_dose, dtype=np.float32)
    k = min(len(keep_mats), n)
    if k > 0:
        start = n - k
        out_mats[start:] = np.asarray(keep_mats[-k:], dtype='<U1')
        out_dose[start:] = np.asarray(keep_dose[-k:], dtype=np.float32)
    return out_mats, out_dose, repaired



def _stack_scheduler_parse_layer_order(order_text: str) -> List[str]:
    movable = set(STACK_SCHEDULER_MOVABLE_MATERIALS)
    out: List[str] = []
    for part in str(order_text or "").replace(";", ",").split(","):
        m = part.strip().upper()
        if m and m in movable and m not in out:
            out.append(m)
    for m in STACK_SCHEDULER_LAYER_ORDER:
        if m in movable and m not in out:
            out.append(m)
    return out


def _normalise_stack_arrays(mats: Sequence[str], rdose: Sequence[float], n_slots: int) -> Tuple[np.ndarray, np.ndarray]:
    mats_list = [str(m) for m in list(mats)[:n_slots]]
    dose_list = [float(d) for d in list(rdose)[:n_slots]]
    if len(mats_list) < n_slots:
        mats_list += [EMPTY_MAT] * (n_slots - len(mats_list))
        dose_list += [0.0] * (n_slots - len(dose_list))
    return np.asarray(mats_list, dtype='<U1'), np.asarray(dose_list, dtype=np.float32)


def _stack_scheduler_recipe_token_counts(mats: Sequence[str], rdose: Sequence[float]) -> Dict[str, int]:
    counts = {m: 0 for m in STACK_SCHEDULER_MOVABLE_MATERIALS}
    for m0, d0 in zip(mats, rdose):
        m = str(m0).upper()
        if float(d0) > 0.0 and m in counts:
            counts[m] += 1
    return counts


def _choose_even_slots(n_slots: int, seat_total: int) -> List[int]:
    if seat_total <= 0:
        return []
    if seat_total >= n_slots:
        return list(range(n_slots))
    raw = np.linspace(0, n_slots - 1, seat_total)
    used: set[int] = set()
    out: List[int] = []
    for val in raw:
        base = int(round(float(val)))
        candidates = sorted(range(n_slots), key=lambda s: (abs(s - val), abs(s - base), s))
        for c in candidates:
            if c not in used:
                used.add(c); out.append(c); break
    return out


def _build_global_stack_scheduler_plan(recipe_idx_flat: np.ndarray, lookup: RecipeLookup, n_slots: int) -> Dict[str, object]:
    """Build one whole-image layer preference map for movable RGBCY tokens.

    This is intentionally simple for PPSPV15: it uses area-weighted selected recipe
    usage, allocates repeated layer seats to materials with deep-token demand, then
    maps those seats onto evenly spaced physical slots in a fixed bottom-to-top
    colour order.  W/F are not part of this plan; they remain per-recipe blockers.
    """
    n_slots = int(n_slots)
    material_order = _stack_scheduler_parse_layer_order(globals().get("RUNTIME_STACK_SCHEDULER_LAYER_ORDER", "B,C,R,Y,G"))
    movable = list(STACK_SCHEDULER_MOVABLE_MATERIALS)
    unique, counts = np.unique(np.asarray(recipe_idx_flat, dtype=np.int64), return_counts=True)
    area_ge: Dict[str, List[int]] = {m: [0] * (n_slots + 1) for m in movable}
    exact_count: Dict[str, List[int]] = {m: [0] * (n_slots + 1) for m in movable}
    total_tokens = {m: 0 for m in movable}
    for ridx, cell_count in zip(unique.tolist(), counts.tolist()):
        mats, rdose = lookup.recipe_stack_for_recipe_index(int(ridx))
        mats, rdose = _normalise_stack_arrays(mats, rdose, n_slots)
        cc = _stack_scheduler_recipe_token_counts(mats, rdose)
        for m, c in cc.items():
            c = min(int(c), n_slots)
            if c > 0:
                exact_count[m][c] += int(cell_count)
                total_tokens[m] += int(cell_count) * int(c)
                for k in range(1, c + 1):
                    area_ge[m][k] += int(cell_count)

    active = [m for m in material_order if area_ge[m][1] > 0]
    # Keep any active colour not present in the explicit layer order.
    for m in movable:
        if area_ge[m][1] > 0 and m not in active:
            active.append(m)

    seat_counts = {m: 0 for m in movable}
    for m in active[:n_slots]:
        seat_counts[m] = 1
    remaining = max(0, n_slots - sum(seat_counts.values()))
    extra_candidates = []
    for m in active:
        for k in range(2, n_slots + 1):
            if area_ge[m][k] <= 0:
                continue
            depth_weight = 1.0 + 0.15 * float(k - 1)
            score = float(area_ge[m][k]) * depth_weight
            extra_candidates.append((score, m, k))
    extra_candidates.sort(key=lambda t: (-t[0], material_order.index(t[1]) if t[1] in material_order else 99, t[2]))
    for _score, m, _k in extra_candidates:
        if remaining <= 0:
            break
        seat_counts[m] += 1
        remaining -= 1

    seat_sequence: List[str] = []
    for m in material_order:
        seat_sequence.extend([m] * int(seat_counts.get(m, 0)))
    # If explicit order omitted an active material, append it deterministically.
    for m in active:
        if m not in material_order:
            seat_sequence.extend([m] * int(seat_counts.get(m, 0)))
    seat_sequence = seat_sequence[:n_slots]
    slots = _choose_even_slots(n_slots, len(seat_sequence))
    preferred_slots: Dict[str, List[int]] = {m: [] for m in movable}
    for m, slot in zip(seat_sequence, slots):
        preferred_slots[m].append(int(slot))

    report = {
        "enabled": True,
        "mode": "global-preference",
        "algorithm": "ppspv33_wblocker_rgbyc_token_layer_scheduler_v1",
        "movable_materials": list(movable),
        "fixed_blockers": list(STACK_SCHEDULER_FIXED_BLOCKERS),
        "layer_order_bottom_to_top": list(material_order),
        "seat_counts": {m: int(seat_counts.get(m, 0)) for m in movable},
        "preferred_slots_zero_based": {m: [int(v) for v in preferred_slots.get(m, [])] for m in movable},
        "preferred_slots_one_based": {m: [int(v) + 1 for v in preferred_slots.get(m, [])] for m in movable},
        "area_ge_token_count_cells": {m: {str(k): int(area_ge[m][k]) for k in range(1, n_slots + 1) if area_ge[m][k] > 0} for m in movable},
        "exact_token_count_cells": {m: {str(k): int(exact_count[m][k]) for k in range(1, n_slots + 1) if exact_count[m][k] > 0} for m in movable},
        "total_token_area_cells": {m: int(total_tokens[m]) for m in movable},
        "unique_recipes_seen": int(len(unique)),
        "cells_seen": int(len(recipe_idx_flat)),
    }
    return {"enabled": True, "preferred_slots": preferred_slots, "report": report}



def _build_local_stack_scheduler_plans(recipe_idx_flat: np.ndarray, lookup: RecipeLookup, nx: int, ny: int, n_slots: int, tile_mm: float) -> Dict[str, object]:
    """Build per-local-tile layer preference maps for RGBCY token scheduling.

    This is deliberately conservative: each AP cell uses the preference plan for
    its local tile, but there is no geometric hard boundary in the emitted roads;
    it only changes token placement before normal PSP pathing.  Tile size is in
    millimetres and converted to AP cells using the current print width.
    """
    nx = int(nx); ny = int(ny); n_slots = int(n_slots)
    ap_pitch = max(1e-6, float(globals().get("RUNTIME_PRINT_WIDTH_MM", ROAD_W_MM)))
    tile_cells = max(1, int(round(float(tile_mm) / ap_pitch)))
    tiles_x = int(math.ceil(nx / float(tile_cells)))
    tiles_y = int(math.ceil(ny / float(tile_cells)))
    recipe_grid = np.asarray(recipe_idx_flat, dtype=np.int64).reshape(ny, nx)
    plans: Dict[Tuple[int, int], Dict[str, object]] = {}
    preferred_sample: Dict[str, object] = {}
    mode = str(globals().get("RUNTIME_STACK_SCHEDULER", "local-preference"))
    for ty in range(tiles_y):
        y0 = ty * tile_cells; y1 = min(ny, (ty + 1) * tile_cells)
        for tx in range(tiles_x):
            x0 = tx * tile_cells; x1 = min(nx, (tx + 1) * tile_cells)
            subset = recipe_grid[y0:y1, x0:x1].reshape(-1)
            plan = _build_global_stack_scheduler_plan(subset, lookup, n_slots)
            # Mark tile identity and mode, while retaining the exact global-plan schema.
            report = dict(plan.get("report", {}))
            report.update({
                "mode": mode,
                "algorithm": "ppspv41_active_metadata_reference_repeat_v1",
                "tile_x": int(tx), "tile_y": int(ty),
                "tile_cells": int(tile_cells),
                "x0_cell": int(x0), "x1_cell": int(x1),
                "y0_cell": int(y0), "y1_cell": int(y1),
            })
            plan["report"] = report
            plan["tile_id"] = (int(ty), int(tx))
            plans[(ty, tx)] = plan
            if len(preferred_sample) < 16:
                preferred_sample[f"{ty},{tx}"] = report.get("preferred_slots_one_based", {})
    report = {
        "enabled": True,
        "mode": mode,
        "algorithm": "ppspv41_active_metadata_reference_repeat_v1",
        "tile_mm": float(tile_mm),
        "tile_cells": int(tile_cells),
        "tiles_x": int(tiles_x),
        "tiles_y": int(tiles_y),
        "tile_count": int(len(plans)),
        "preferred_slots_sample_one_based": preferred_sample,
        "note": "Each AP cell uses its tile preference plan; no hard geometry partition is introduced by this scheduler stage.",
    }
    return {"enabled": True, "mode": mode, "tile_cells": tile_cells, "tiles_x": tiles_x, "tiles_y": tiles_y, "plans": plans, "report": report}


def _scheduler_plan_for_cell(scheduler_plan: Dict[str, object], xb: int, yb: int) -> Dict[str, object]:
    if not isinstance(scheduler_plan, dict):
        return {"enabled": False, "preferred_slots": {}, "report": {"enabled": False}}
    if "plans" not in scheduler_plan:
        return scheduler_plan
    tile_cells = max(1, int(scheduler_plan.get("tile_cells", 1)))
    tx = int(xb) // tile_cells
    ty = int(yb) // tile_cells
    return scheduler_plan.get("plans", {}).get((ty, tx), {"enabled": False, "preferred_slots": {}, "report": {"enabled": False}})


def _slot_preference_cost(mat: str, slot: int, preferred_slots: Dict[str, List[int]], n_slots: int) -> float:
    prefs = preferred_slots.get(str(mat), [])
    if not prefs:
        # Fallback keeps active but unassigned colours near the middle.
        return 20.0 + abs(float(slot) - (float(n_slots - 1) * 0.5))
    best = 999.0
    for rank, p in enumerate(prefs):
        # rank lightly favours the primary slot, distance keeps bands coherent.
        best = min(best, abs(int(slot) - int(p)) * 2.0 + float(rank) * 0.25)
    return best


def _schedule_stack_w_blocker(
    mats: Sequence[str],
    rdose: Sequence[float],
    plan: Dict[str, object],
    n_slots: int,
    neighbour_stacks: Optional[Sequence[Sequence[str]]] = None,
    neighbour_contexts: Optional[Sequence[Dict[str, object]]] = None,
) -> Tuple[np.ndarray, np.ndarray, Dict[str, int]]:
    """PPSPV29 no-T scheduler: reorder RGBCY inside W/F-bounded regions only.

    Caller must first apply structural W lift/fill.  Therefore short recipes have
    W below them, and that W is treated as a real printed blocker.  No spacer material is emitted; any unexpected leftover free slot is filled with W.
    """
    n_slots = int(n_slots)
    mats_in, dose_in = _normalise_stack_arrays(mats, rdose, n_slots)
    movable = set(STACK_SCHEDULER_MOVABLE_MATERIALS)
    blockers = set(STACK_SCHEDULER_FIXED_BLOCKERS)
    fill_mat = str(DEFAULT_STRUCTURAL_FILL_MATERIAL)
    fill_dose = float(DEFAULT_STRUCTURAL_FILL_DOSE)
    preferred_slots = plan.get("preferred_slots", {}) if isinstance(plan, dict) else {}
    neighbour_weight = float(globals().get("RUNTIME_STACK_SCHEDULER_NEIGHBOUR_WEIGHT", STACK_SCHEDULER_NEIGHBOUR_WEIGHT))
    component_weight = float(globals().get("RUNTIME_STACK_SCHEDULER_COMPONENT_WEIGHT", STACK_SCHEDULER_COMPONENT_WEIGHT))
    island_penalty = float(globals().get("RUNTIME_STACK_SCHEDULER_ISLAND_PENALTY", STACK_SCHEDULER_ISLAND_PENALTY))
    scheduler_mode = str(globals().get("RUNTIME_STACK_SCHEDULER", "off"))
    neighbour_mode = scheduler_mode in ("local-neighbour", "local-component")
    component_mode = scheduler_mode == "local-component"

    neighbours = []
    if neighbour_mode and neighbour_stacks is not None:
        for ns in neighbour_stacks:
            if ns is not None:
                arr_ns = [str(v).upper() for v in list(ns)[:n_slots]]
                if len(arr_ns) < n_slots:
                    arr_ns += [EMPTY_MAT] * (n_slots - len(arr_ns))
                neighbours.append(arr_ns)

    contexts: List[Dict[str, object]] = []
    if component_mode and neighbour_contexts is not None:
        for ctx in neighbour_contexts:
            if not isinstance(ctx, dict):
                continue
            stack0 = ctx.get("stack")
            if stack0 is None:
                continue
            arr_stack = [str(v).upper() for v in list(stack0)[:n_slots]]
            if len(arr_stack) < n_slots:
                arr_stack += [EMPTY_MAT] * (n_slots - len(arr_stack))
            run0 = ctx.get("run")
            if run0 is None:
                arr_run = [1] * n_slots
            else:
                arr_run = [int(v) for v in list(run0)[:n_slots]]
                if len(arr_run) < n_slots:
                    arr_run += [1] * (n_slots - len(arr_run))
            contexts.append({"stack": arr_stack, "run": arr_run, "direction": str(ctx.get("direction", ""))})

    out_mats = np.full((n_slots,), EMPTY_MAT, dtype='<U1')
    out_dose = np.zeros((n_slots,), dtype=np.float32)
    fixed_slots = set()
    tokens_by_region: Dict[int, List[Tuple[str, float]]] = {}
    removed_empty = 0
    fixed_blockers = 0

    # First mark all W/F/non-movable active slots as fixed blockers. Structural W
    # was already inserted by caller, so shallow stacks naturally have less room.
    slot_fixed = [False] * n_slots
    for si in range(n_slots):
        m = str(mats_in[si]).upper()
        d = float(dose_in[si])
        if d <= 0.0 or m == EMPTY_MAT:
            continue
        if m in blockers or m not in movable:
            slot_fixed[si] = True

    # Contiguous non-fixed runs are the only sortable regions.
    slot_region = [-1] * n_slots
    region_slots: List[List[int]] = []
    current_region = -1
    in_region = False
    for si in range(n_slots):
        if slot_fixed[si]:
            in_region = False
            continue
        if not in_region:
            current_region += 1
            region_slots.append([])
            in_region = True
        slot_region[si] = current_region
        region_slots[current_region].append(si)

    region_free_slots: Dict[int, List[int]] = {ri: list(slots) for ri, slots in enumerate(region_slots)}

    for si in range(n_slots):
        m = str(mats_in[si]).upper()
        d = float(dose_in[si])
        if d <= 0.0 or m == EMPTY_MAT:
            removed_empty += 1
            continue
        if slot_fixed[si]:
            out_mats[si] = m
            out_dose[si] = d
            fixed_slots.add(si)
            fixed_blockers += 1
        elif m in movable:
            ri = slot_region[si]
            tokens_by_region.setdefault(ri, []).append((m, d))
        else:
            out_mats[si] = fill_mat
            out_dose[si] = fill_dose
            fixed_slots.add(si)
            fixed_blockers += 1

    seat_counts = plan.get("report", {}).get("seat_counts", {}) if isinstance(plan, dict) else {}
    order_index = {m: i for i, m in enumerate(_stack_scheduler_parse_layer_order(globals().get("RUNTIME_STACK_SCHEDULER_LAYER_ORDER", "B,C,R,Y,G")))}

    placed = 0
    displaced = 0
    component_contexts_used = 0
    component_reward_applications = 0
    component_reward_total = 0.0
    isolated_token_penalties = 0
    component_run_seed_total = 0
    regions_with_tokens = 0

    for ri, tokens in tokens_by_region.items():
        if not tokens:
            continue
        regions_with_tokens += 1
        free_slots = list(region_free_slots.get(ri, []))
        tokens.sort(key=lambda md: (-int(seat_counts.get(md[0], 0)), order_index.get(md[0], 99), -float(md[1])))

        for m, d in tokens:
            if not free_slots:
                break

            def _placement_cost(si: int) -> Tuple[float, int]:
                cost = float(_slot_preference_cost(m, si, preferred_slots, n_slots))
                if neighbours and neighbour_weight > 0.0:
                    matches = sum(1 for ns in neighbours if si < len(ns) and str(ns[si]).upper() == m)
                    cost -= neighbour_weight * float(matches)
                if component_mode:
                    ctx_matches = 0
                    ctx_run = 0
                    for ctx in contexts:
                        st = ctx.get("stack", [])
                        rn = ctx.get("run", [])
                        if si < len(st) and str(st[si]).upper() == m:
                            ctx_matches += 1
                            try:
                                ctx_run += max(1, int(rn[si]))
                            except Exception:
                                ctx_run += 1
                    if ctx_matches > 0:
                        run_strength = min(16, int(ctx_run))
                        cost -= component_weight * math.sqrt(float(run_strength))
                    elif island_penalty > 0.0:
                        cost += float(island_penalty)
                return (cost, si)

            best_slot = min(free_slots, key=_placement_cost)
            if component_mode:
                best_matches = 0
                best_run = 0
                for ctx in contexts:
                    st = ctx.get("stack", [])
                    rn = ctx.get("run", [])
                    if best_slot < len(st) and str(st[best_slot]).upper() == m:
                        best_matches += 1
                        try:
                            best_run += max(1, int(rn[best_slot]))
                        except Exception:
                            best_run += 1
                if best_matches > 0:
                    component_contexts_used += int(best_matches)
                    component_reward_applications += 1
                    component_run_seed_total += min(16, int(best_run))
                    component_reward_total += float(component_weight) * math.sqrt(float(min(16, int(best_run))))
                elif island_penalty > 0.0:
                    isolated_token_penalties += 1

            if _slot_preference_cost(m, best_slot, preferred_slots, n_slots) > 0.0:
                displaced += 1
            out_mats[best_slot] = m
            out_dose[best_slot] = float(d)
            free_slots.remove(best_slot)
            placed += 1
        region_free_slots[ri] = free_slots

    # No T in this test.  Structural fill should normally leave no free slots
    # after all tokens are placed; if any remain, fill them with W so output is
    # still W/R/Y/G/C/B only.
    w_filled = 0
    regions_with_w_fill = 0
    for ri, free_slots in region_free_slots.items():
        if free_slots:
            regions_with_w_fill += 1
        for si in free_slots:
            out_mats[si] = fill_mat
            out_dose[si] = fill_dose
            w_filled += 1

    total_tokens = int(sum(len(v) for v in tokens_by_region.values()))
    return out_mats, out_dose, {
        "tokens_seen": int(total_tokens),
        "tokens_placed": int(placed),
        "tokens_unplaced": int(max(0, total_tokens - placed)),
        "tokens_displaced_from_primary": int(displaced),
        "fixed_blockers": int(fixed_blockers),
        "free_slots_filled_with_w": 0,
        "unexpected_free_slots_filled_with_w": int(w_filled),
        "empty_or_zero_slots_removed_before_scheduling": int(removed_empty),
        "neighbour_candidates_used": int(len(neighbours)),
        "component_contexts_used": int(component_contexts_used),
        "component_reward_applications": int(component_reward_applications),
        "component_reward_total_x1000": int(round(component_reward_total * 1000.0)),
        "component_run_seed_total": int(component_run_seed_total),
        "isolated_token_penalties": int(isolated_token_penalties),
        "sortable_regions_total": int(len(region_slots)),
        "sortable_regions_with_tokens": int(regions_with_tokens),
        "sortable_regions_with_unused_fill": 0,
        "sortable_regions_with_w_fill": int(regions_with_w_fill),
    }

def _apply_full_structural_w_stack_cell(stack: np.ndarray, dose: np.ndarray, x: int, y_model: int) -> None:
    """Fill every optical slot for one cell with mandatory full structural W.

    This is used for true zero-demand / white cells.  They are not outside the
    card and must not remain EMPTY_MAT in upper layers; in the FC3D card model
    the least/neutral recipe is full W support through the stack.
    """
    n_slots = int(stack.shape[2])
    for si in range(n_slots):
        stack[y_model, x, si] = DEFAULT_STRUCTURAL_FILL_MATERIAL
        dose[y_model, x, si] = DEFAULT_STRUCTURAL_FILL_DOSE

def _apply_fit_to_stack_cell(fit, stack: np.ndarray, dose: np.ndarray, x: int, y_model: int, head_width_px: int) -> None:
    """Apply a shared allocator FitResult to one model-bottom RP cell.

    ppv92 change: StackPlans are top-aligned inside the available optical slots.
    If a cell uses fewer slots than max_physical_slots, the unused LOWER slots are
    filled with full structural W so the actual colour/demand recipe is
    lifted to the card surface and Studio never sees unsupported/empty upper
    optical layers. This is mandatory core behaviour, not an optional mode.

    Values below the solid threshold are not weak solid roads. They are emitted
    as half occupancy. Dual-half slots use complementary phases in one physical
    layer. Phase is computed from the emitted road direction so one road never
    contains a half-tone material change.
    """
    n_slots = int(stack.shape[2])
    used_slots = min(len(getattr(fit, "slots", [])), n_slots)
    offset = max(0, n_slots - used_slots)

    fill_mat = DEFAULT_STRUCTURAL_FILL_MATERIAL
    fill_dose = DEFAULT_STRUCTURAL_FILL_DOSE
    if offset > 0:
        for si in range(offset):
            stack[y_model, x, si] = fill_mat
            dose[y_model, x, si] = fill_dose

    for local_si, slot in enumerate(getattr(fit, "slots", [])):
        si = offset + local_si
        if si >= n_slots:
            break
        if slot.mode == "solid" and slot.a is not None:
            stack[y_model, x, si] = slot.a.material
            dose[y_model, x, si] = float(slot.a.printed_dose)
        elif slot.mode == "half_single" and slot.a is not None:
            if _phase_for_direct_slot_cell(si, x, y_model, head_width_px) == 0:
                stack[y_model, x, si] = slot.a.material
                dose[y_model, x, si] = float(slot.a.printed_dose)
        elif slot.mode == "half_dual" and slot.a is not None and slot.b is not None:
            if _phase_for_direct_slot_cell(si, x, y_model, head_width_px) == 0:
                stack[y_model, x, si] = slot.a.material
                dose[y_model, x, si] = float(slot.a.printed_dose)
            else:
                stack[y_model, x, si] = slot.b.material
                dose[y_model, x, si] = float(slot.b.printed_dose)


def _apply_fit_dict_to_locked_stack_cell(fit_dict: Dict[str, object], stack: np.ndarray, dose: np.ndarray, x: int, y_model: int, head_width_px: int) -> None:
    """Apply exact recipegen candidate_packed_stack_json directly to one cell.

    PPV107 correctness rule:
      - candidate_packed_stack_json is still authoritative for every non-empty
        material+dose decision;
      - but normal picture prints must not leave accidental air in full physical
        layers.  Empty/short full slots are structural W.  Genuine half_single
        inactive phases remain air, because half-tone holes are intentionally allowed.
      - This restores the critical full-slot structural-fill function that the old
        allocator supplied before PPV104 bypassed demand refit.

    This is not colour/demand re-solving.
    """
    n_slots = int(stack.shape[2])
    slots = _normalised_locked_fit_dict_slots(fit_dict, n_slots)
    for si, slot in enumerate(slots):
        if si >= n_slots or not isinstance(slot, dict):
            break
        mode = str(slot.get("mode", "empty"))
        a = slot.get("a") if isinstance(slot.get("a"), dict) else None
        b = slot.get("b") if isinstance(slot.get("b"), dict) else None
        fill_mat = str(DEFAULT_STRUCTURAL_FILL_MATERIAL)
        fill_dose = float(DEFAULT_STRUCTURAL_FILL_DOSE)
        if mode == "solid" and a is not None:
            stack[y_model, x, si] = str(a.get("material"))
            dose[y_model, x, si] = float(a.get("printed_dose", 0.0))
        elif mode == "half_single" and a is not None:
            if _phase_for_direct_slot_cell(si, x, y_model, head_width_px) == 0:
                stack[y_model, x, si] = str(a.get("material"))
                dose[y_model, x, si] = float(a.get("printed_dose", 0.0))
            else:
                # Genuine half-tone air gap. Do not structurally fill with W unless
                # a future explicit half-tone-with-W mode requests it.
                pass
        elif mode == "half_dual":
            if _phase_for_direct_slot_cell(si, x, y_model, head_width_px) == 0:
                seg = a
            else:
                seg = b
            if isinstance(seg, dict):
                stack[y_model, x, si] = str(seg.get("material"))
                dose[y_model, x, si] = float(seg.get("printed_dose", 0.0))
            else:
                stack[y_model, x, si] = fill_mat
                dose[y_model, x, si] = fill_dose
        elif mode == "empty":
            stack[y_model, x, si] = fill_mat
            dose[y_model, x, si] = fill_dose
        else:
            raise ValueError(f"Unsupported exact candidate slot mode for locked emission: {mode!r}")


def _locked_fit_dict_slot_mode_counts(fit_dict: Dict[str, object]) -> Dict[str, int]:
    out: Dict[str, int] = {}
    slots = fit_dict.get("slots", []) if isinstance(fit_dict, dict) else []
    for slot in slots:
        if isinstance(slot, dict):
            mode = str(slot.get("mode", "empty"))
            out[mode] = out.get(mode, 0) + 1
    return out



def _unique_permutations_limited(items: Sequence[Tuple[str, float]], max_count: int = 720) -> List[Tuple[Tuple[str, float], ...]]:
    """Return unique permutations of material/dose items, capped for safety.

    Items are material+dose pairs, not just symbols, so dose/count preservation is exact.
    Sortable regions are normally small; if a region is too large, fall back to a few
    deterministic grouped/alternating candidates rather than factorial explosion.
    """
    items = tuple((str(m), float(d)) for m, d in items)
    if len(items) <= 1:
        return [items]
    # exact unique permutations for small regions
    import itertools as _it
    out = []
    seen = set()
    limit = max(1, int(max_count))
    if math.factorial(len(items)) <= limit * 4:
        for perm in _it.permutations(items):
            if perm in seen:
                continue
            seen.add(perm)
            out.append(perm)
            if len(out) >= limit:
                break
        return out or [items]
    # Large-region fallback: original, reverse, grouped ascending/descending, and round-robin by material.
    def _grouped(reverse=False):
        return tuple(sorted(items, key=lambda x: (x[0], x[1]), reverse=reverse))
    cands = [items, tuple(reversed(items)), _grouped(False), _grouped(True)]
    # Round-robin interleaving by material as a diversity candidate.
    buckets: Dict[str, List[Tuple[str,float]]] = {}
    for it in items:
        buckets.setdefault(it[0], []).append(it)
    keys = sorted(buckets.keys())
    rr=[]
    while any(buckets.values()):
        for k in keys:
            if buckets[k]:
                rr.append(buckets[k].pop(0))
    cands.append(tuple(rr))
    out=[]; seen=set()
    for c in cands:
        if c not in seen:
            seen.add(c); out.append(c)
    return out or [items]


def _split_w_bounded_sortable_regions(mats: Sequence[str], doses: Sequence[float]) -> List[Tuple[str, int, int]]:
    """Split physical bottom->top stack into fixed W and sortable colour regions.

    Current user-approved rule for PPV101:
      - leading/lower W run is fixed structural/foundation/fill region.
      - any W encountered after colour starts is a fixed W boundary/separator.
      - non-W runs between fixed W boundaries are independently sortable.
      - material/dose counts are preserved inside each sortable region.

    Example: WWWBRWRG => fixed WWW, sortable BR, fixed W, sortable RG.
    """
    n = len(mats)
    regions=[]
    i=0
    # fixed leading W region
    while i<n and str(mats[i]) == 'W':
        regions.append(('fixed', i, i+1)); i+=1
    while i<n:
        if str(mats[i]) == 'W':
            regions.append(('fixed', i, i+1)); i+=1
            continue
        j=i
        while j<n and str(mats[j]) != 'W':
            j+=1
        if j-i > 1:
            regions.append(('sortable', i, j))
        else:
            regions.append(('fixed_colour_single', i, j))
        i=j
    return regions



def _sortable_region_containing_layer(mats: Sequence[str], doses: Sequence[float], layer_i: int) -> Optional[Tuple[int, int]]:
    """Return the W-bounded sortable colour region containing layer_i, or None.

    Current FC3D sorting rule:
      - leading W run is fixed structural/foundation/fill.
      - W encountered after colour starts is a fixed boundary/separator.
      - non-W regions between fixed W boundaries are sortable independently.
      - colour/material is never moved across a fixed W boundary.
    """
    for kind, a, b in _split_w_bounded_sortable_regions(mats, doses):
        if kind == 'sortable' and a <= int(layer_i) < b and (b - a) > 1:
            return int(a), int(b)
    return None


def _scan_prev_coord_for_layer(layer_i: int, cy: int, cx: int, ny: int, nx: int) -> Optional[Tuple[int, int]]:
    """Previous AP cell in the actual emitted scanline direction for optical slot layer_i.

    layer_i is 0-based stack slot; orientation() takes 1-based optical/mix layer.
    X-road layers run along rows and alternate left->right / right->left by row.
    Y-road layers run along columns and alternate bottom->top / top->bottom by column.
    """
    orient = orientation(int(layer_i) + 1)
    if orient == 'X':
        if (int(cy) % 2) == 0:
            return (cy, cx - 1) if cx > 0 else None
        return (cy, cx + 1) if cx < nx - 1 else None
    # Y roads
    if (int(cx) % 2) == 0:
        return (cy - 1, cx) if cy > 0 else None
    return (cy + 1, cx) if cy < ny - 1 else None


def _scanline_layer_order(layer_i: int, ny: int, nx: int) -> Iterable[Tuple[int, int]]:
    """Yield AP cells in actual print-head scan order for this optical slot."""
    orient = orientation(int(layer_i) + 1)
    if orient == 'X':
        for cy in range(ny):
            if (cy % 2) == 0:
                for cx in range(nx):
                    yield cy, cx
            else:
                for cx in range(nx - 1, -1, -1):
                    yield cy, cx
    else:
        for cx in range(nx):
            if (cx % 2) == 0:
                for cy in range(ny):
                    yield cy, cx
            else:
                for cy in range(ny - 1, -1, -1):
                    yield cy, cx


def _local_prev_matches(cell_mats: np.ndarray, cy: int, cx: int) -> List[bool]:
    """For current AP cell, return which stack slots currently continue their own scanline."""
    ny, nx, layers = cell_mats.shape
    out=[]
    for li in range(layers):
        prev = _scan_prev_coord_for_layer(li, cy, cx, ny, nx)
        if prev is None:
            out.append(False)
        else:
            py, px = prev
            out.append(str(cell_mats[cy, cx, li]) == str(cell_mats[py, px, li]))
    return out


def _global_scanline_continuity_count(cell_mats: np.ndarray) -> int:
    """Count same-material adjacencies in actual scanline directions across all optical slots."""
    ny, nx, layers = cell_mats.shape
    total = 0
    for li in range(layers):
        for cy in range(ny):
            for cx in range(nx):
                prev = _scan_prev_coord_for_layer(li, cy, cx, ny, nx)
                if prev is None:
                    continue
                py, px = prev
                if str(cell_mats[cy, cx, li]) == str(cell_mats[py, px, li]):
                    total += 1
    return int(total)



def _stack_vector_from_fit_for_cell(fit, x: int, y_model: int, n_slots: int, head_width_px: int) -> Tuple[List[str], List[float]]:
    """Representative material/dose vector for one AP/RP cell from a FitResult.

    This mirrors _apply_fit_to_stack_cell for a single coordinate, including top alignment,
    structural W fill, and half-tone phase choice. It is used only for candidate-choice
    scoring before the full AP block is expanded.
    """
    mats = [EMPTY_MAT for _ in range(int(n_slots))]
    doses = [0.0 for _ in range(int(n_slots))]
    if fit is None:
        return mats, doses
    if fit == STRUCTURAL_W_ONLY_SENTINEL:
        return [DEFAULT_STRUCTURAL_FILL_MATERIAL for _ in range(int(n_slots))], [float(DEFAULT_STRUCTURAL_FILL_DOSE) for _ in range(int(n_slots))]
    used_slots = min(len(getattr(fit, "slots", [])), int(n_slots))
    offset = max(0, int(n_slots) - used_slots)
    for si in range(offset):
        mats[si] = DEFAULT_STRUCTURAL_FILL_MATERIAL
        doses[si] = float(DEFAULT_STRUCTURAL_FILL_DOSE)
    for local_si, slot in enumerate(getattr(fit, "slots", [])):
        si = offset + local_si
        if si >= int(n_slots):
            break
        if slot.mode == "solid" and slot.a is not None:
            mats[si] = slot.a.material
            doses[si] = float(slot.a.printed_dose)
        elif slot.mode == "half_single" and slot.a is not None:
            if _phase_for_direct_slot_cell(si, int(x), int(y_model), int(head_width_px)) == 0:
                mats[si] = slot.a.material
                doses[si] = float(slot.a.printed_dose)
        elif slot.mode == "half_dual" and slot.a is not None and slot.b is not None:
            if _phase_for_direct_slot_cell(si, int(x), int(y_model), int(head_width_px)) == 0:
                mats[si] = slot.a.material
                doses[si] = float(slot.a.printed_dose)
            else:
                mats[si] = slot.b.material
                doses[si] = float(slot.b.printed_dose)
    return mats, doses


def _stack_vector_from_fit_dict_for_cell(fit_dict: Dict[str, object], x: int, y_model: int, n_slots: int, head_width_px: int) -> Tuple[List[str], List[float]]:
    """Representative material/dose vector directly from exact candidate_packed_stack_json.

    PPV108 structural-fill policy:
      - short/empty full physical slots become structural W;
      - genuine half_single inactive phases remain EMPTY/air;
      - candidate choice may therefore see real half-tone air gaps, but no accidental
        full-slot empties from short/empty stack definitions.
    """
    n = int(n_slots)
    mats = [str(DEFAULT_STRUCTURAL_FILL_MATERIAL) for _ in range(n)]
    doses = [float(DEFAULT_STRUCTURAL_FILL_DOSE) for _ in range(n)]
    slots = _normalised_locked_fit_dict_slots(fit_dict, n)
    for si, slot in enumerate(slots):
        if si >= n or not isinstance(slot, dict):
            break
        mode = str(slot.get("mode", "empty"))
        a = slot.get("a") if isinstance(slot.get("a"), dict) else None
        b = slot.get("b") if isinstance(slot.get("b"), dict) else None
        if mode == "solid" and a is not None:
            mats[si] = str(a.get("material"))
            doses[si] = float(a.get("printed_dose", 0.0))
        elif mode == "half_single" and a is not None:
            if _phase_for_direct_slot_cell(si, int(x), int(y_model), int(head_width_px)) == 0:
                mats[si] = str(a.get("material"))
                doses[si] = float(a.get("printed_dose", 0.0))
            else:
                mats[si] = EMPTY_MAT
                doses[si] = 0.0
        elif mode == "half_dual":
            seg = a if _phase_for_direct_slot_cell(si, int(x), int(y_model), int(head_width_px)) == 0 else b
            if isinstance(seg, dict):
                mats[si] = str(seg.get("material"))
                doses[si] = float(seg.get("printed_dose", 0.0))
            else:
                # missing half_dual side is not an intended half-tone-air mode, so keep structural W
                pass
        elif mode == "empty":
            pass
        else:
            raise ValueError(f"Unsupported exact candidate slot mode for candidate-choice scoring: {mode!r}")
    return mats, doses



def _select_multicandidate_routes_scanline(
    lookup: RecipeLookup,
    idx_grid_model: np.ndarray,
    rules,
    n_slots: int,
    head_width_px: int,
    mode: str = "off",
    max_extra_lab: float = 2.0,
    continuity_weight: float = 1.0,
    score_weight: float = 0.10,
    candidate_limit: int = 8,
    half_tone_policy: str = "allow",
    half_tone_solid_max_extra_lab: float = 2.0,
) -> Tuple[np.ndarray, Dict[str, object]]:
    """PPSPV13: staged multi-candidate routing has been removed.

    The active runtime path is dense RGB stack LUT lookup only.  Return the
    selected LUT row/index grid unchanged so old CLI flags cannot accidentally
    trigger loading/using giant multi_candidate_* tables.
    """
    report = {
        "enabled": False,
        "mode": str(mode),
        "algorithm": "removed-in-ppspv13-dense-stack-lut-only",
        "disabled_reason": "PPSPV13 removes staged multi-candidate tables; dense RGB stack LUT is used directly",
    }
    return idx_grid_model.astype(np.int64), report

def apply_stack_resort_w_regions(stack: np.ndarray, dose: np.ndarray, ap_scale: int, mode: str = "off", max_permutations: int = 720) -> Dict[str, object]:
    """Apply PPV102 scanline-continuity stack resorting to an RP stack grid.

    This replaces PPV101's static left/up neighbour score. It operates on AP cells and walks
    each physical optical slot in the same scanline order used by emission. At a current cell,
    it looks at the previous cell in the actual print-head direction. If the previous cell has
    material M on this slot and the current cell has M elsewhere inside the same legal W-bounded
    sortable region, it swaps M into this slot only when that continues the current road without
    breaking any other already-continuing road in this AP cell.

    Counts and doses are preserved by swapping material+dose pairs, and fixed W boundaries are
    never crossed. The resorted representative stack is expanded back over the full AP block.
    """
    report={"enabled": False, "mode": str(mode), "ap_scale": int(ap_scale), "algorithm": "scanline-continuity"}
    mode_l=str(mode).lower()
    if mode_l in ("off", "false", "0", "none"):
        return report
    if mode_l not in ("scanline-continuity", "scanline", "w-region-neighbour"):
        # Accept legacy w-region-neighbour as an alias to keep old command lines from failing,
        # but record that the actual PPV102 algorithm is scanline-continuity.
        return report
    h,w,layers=stack.shape
    ap=max(1,int(ap_scale))
    ny=h//ap; nx=w//ap
    changed_cells_mask=np.zeros((ny,nx), dtype=bool)
    sortable_cells=0; sortable_regions=0
    swap_attempts=0; swaps_accepted=0; rejected_break_other=0; rejected_no_gain=0; rejected_no_region=0; wanted_available=0
    per_layer=[{"layer": int(li+1), "orientation": orientation(li+1), "attempts":0, "accepted":0, "rejected_break_other":0, "rejected_no_gain":0, "wanted_available":0} for li in range(layers)]
    cell_mats=np.empty((ny,nx,layers), dtype='<U1')
    cell_dose=np.zeros((ny,nx,layers), dtype=np.float32)
    for cy in range(ny):
        yy=cy*ap
        for cx in range(nx):
            xx=cx*ap
            cell_mats[cy,cx,:]=stack[yy,xx,:]
            cell_dose[cy,cx,:]=dose[yy,xx,:]
    before_cont=_global_scanline_continuity_count(cell_mats)

    # Pre-count sortable regions from original selected recipes for reporting.
    for cy in range(ny):
        for cx in range(nx):
            mats=list(cell_mats[cy,cx,:]); doses=[float(v) for v in cell_dose[cy,cx,:]]
            regs=_split_w_bounded_sortable_regions(mats,doses)
            sr=sum(1 for k,a,b in regs if k=='sortable' and (b-a)>1)
            if sr:
                sortable_cells += 1; sortable_regions += sr

    # Greedy physical-slot scanline pass. Later slots see earlier accepted swaps.
    for li in range(layers):
        st=per_layer[li]
        for cy,cx in _scanline_layer_order(li, ny, nx):
            prev=_scan_prev_coord_for_layer(li, cy, cx, ny, nx)
            if prev is None:
                continue
            py,px=prev
            wanted=str(cell_mats[py,px,li])
            cur=str(cell_mats[cy,cx,li])
            if cur == wanted:
                continue
            mats=list(cell_mats[cy,cx,:]); doses=[float(v) for v in cell_dose[cy,cx,:]]
            region=_sortable_region_containing_layer(mats,doses,li)
            if region is None:
                rejected_no_region += 1
                continue
            a,b=region
            candidate_js=[jj for jj in range(a,b) if jj != li and str(cell_mats[cy,cx,jj]) == wanted]
            if not candidate_js:
                continue
            wanted_available += 1; st["wanted_available"] += 1
            before_vec=_local_prev_matches(cell_mats, cy, cx)
            before_count=sum(1 for v in before_vec if v)
            best_j=None; best_after_count=-1; best_breaks=999
            for jj in candidate_js:
                swap_attempts += 1; st["attempts"] += 1
                # Test swap on a tiny copy of this cell's stack.
                new_mats=list(cell_mats[cy,cx,:]); new_doses=[float(v) for v in cell_dose[cy,cx,:]]
                new_mats[li],new_mats[jj]=new_mats[jj],new_mats[li]
                new_doses[li],new_doses[jj]=new_doses[jj],new_doses[li]
                after_vec=[]
                for kk in range(layers):
                    p2=_scan_prev_coord_for_layer(kk, cy, cx, ny, nx)
                    if p2 is None:
                        after_vec.append(False)
                    else:
                        qy,qx=p2
                        after_vec.append(str(new_mats[kk]) == str(cell_mats[qy,qx,kk]))
                breaks=sum(1 for before,after in zip(before_vec,after_vec) if before and not after)
                after_count=sum(1 for v in after_vec if v)
                if breaks > 0:
                    continue
                if after_count <= before_count:
                    continue
                if after_count > best_after_count or (after_count == best_after_count and breaks < best_breaks):
                    best_j=jj; best_after_count=after_count; best_breaks=breaks
            if best_j is None:
                # Categorise rejection based on whether every candidate broke another line or simply gave no gain.
                any_no_break=False
                for jj in candidate_js:
                    new_mats=list(cell_mats[cy,cx,:])
                    new_mats[li],new_mats[jj]=new_mats[jj],new_mats[li]
                    after_vec=[]
                    for kk in range(layers):
                        p2=_scan_prev_coord_for_layer(kk, cy, cx, ny, nx)
                        if p2 is None:
                            after_vec.append(False)
                        else:
                            qy,qx=p2
                            after_vec.append(str(new_mats[kk]) == str(cell_mats[qy,qx,kk]))
                    if not any(before and not after for before,after in zip(before_vec,after_vec)):
                        any_no_break=True
                if any_no_break:
                    rejected_no_gain += 1; st["rejected_no_gain"] += 1
                else:
                    rejected_break_other += 1; st["rejected_break_other"] += 1
                continue
            jj=best_j
            old_m_li=str(cell_mats[cy,cx,li]); old_d_li=float(cell_dose[cy,cx,li])
            cell_mats[cy,cx,li]=cell_mats[cy,cx,jj]
            cell_dose[cy,cx,li]=cell_dose[cy,cx,jj]
            cell_mats[cy,cx,jj]=old_m_li
            cell_dose[cy,cx,jj]=old_d_li
            swaps_accepted += 1; st["accepted"] += 1
            changed_cells_mask[cy,cx]=True
    after_cont=_global_scanline_continuity_count(cell_mats)
    # expand back to RP grid
    for cy in range(ny):
        for cx in range(nx):
            y0=cy*ap; y1=min((cy+1)*ap,h); x0=cx*ap; x1=min((cx+1)*ap,w)
            stack[y0:y1,x0:x1,:]=cell_mats[cy,cx,:]
            dose[y0:y1,x0:x1,:]=cell_dose[cy,cx,:]
    changed=int(np.count_nonzero(changed_cells_mask))
    report.update({
        "enabled": True,
        "ppv106_reportfix": "stack_resort_report_no_longer_references_candidate_choice_fit_cache",
        "mode": "scanline-continuity",
        "requested_mode": str(mode),
        "ap_cells": int(nx*ny),
        "sortable_cells": int(sortable_cells),
        "changed_cells": int(changed),
        "changed_cell_fraction": float(changed/max(1,nx*ny)),
        "sortable_regions": int(sortable_regions),
        "swap_attempts": int(swap_attempts),
        "wanted_available_events": int(wanted_available),
        "swaps_accepted": int(swaps_accepted),
        "rejected_break_other": int(rejected_break_other),
        "rejected_no_gain": int(rejected_no_gain),
        "rejected_no_region": int(rejected_no_region),
        "scanline_continuity_before": int(before_cont),
        "scanline_continuity_after": int(after_cont),
        "scanline_continuity_delta": int(after_cont-before_cont),
        "per_layer": per_layer,
        "rule": "fixed leading W and internal fixed W boundaries split independent sortable non-W colour regions; scan each optical slot in actual emitted X/Y direction; swap material+dose pairs only inside the same region when it continues the previous scanline material without breaking any other already-continuing slot",
    })

    return report

RUN_COMPACT_REPORT: Dict[str, object] = {"enabled": False, "mode": "off"}


def _run_compact_rgb_from_cell(mats: Sequence[str], doses: Sequence[float], optical_model: Dict[str, object]) -> np.ndarray:
    """Predict final RGB from one already phase-resolved physical bottom->top cell stack."""
    return _predict_demand_sequence_rgb_from_mats_doses(mats, doses, optical_model)


def _run_compact_de_for_cell(mats: Sequence[str], doses: Sequence[float], target_lab: np.ndarray, optical_model: Dict[str, object]) -> Tuple[float, np.ndarray]:
    rgb = _run_compact_rgb_from_cell(mats, doses, optical_model)
    lab = _srgb_to_lab_array(rgb.reshape(1, 3))[0]
    de = float(np.linalg.norm(lab.astype(np.float32) - np.asarray(target_lab, dtype=np.float32)))
    return de, rgb


def _run_compact_sequence_score(seq: Sequence[str], allowed: set[str]) -> int:
    """Local run score for directional adjacent-token swaps. Higher is better."""
    vals = [str(v) for v in seq]
    same_edges = 0
    runs: List[Tuple[str, int]] = []
    cur = None
    cur_len = 0
    for v in vals:
        active = v in allowed
        if active and cur == v:
            cur_len += 1
        else:
            if cur is not None:
                runs.append((cur, cur_len))
            cur = v if active else None
            cur_len = 1 if active else 0
    if cur is not None:
        runs.append((cur, cur_len))
    for a, b in zip(vals, vals[1:]):
        if a == b and a in allowed:
            same_edges += 1
    max_run = max((ln for _m, ln in runs), default=0)
    one_cell_runs = sum(1 for _m, ln in runs if ln == 1)
    return int(same_edges * 10 + max_run * 3 - len(runs) * 2 - one_cell_runs)


def apply_directional_run_compaction(
    stack: np.ndarray,
    dose: np.ndarray,
    targets_top: np.ndarray,
    optical_model: Dict[str, object],
    ap_scale: int,
    max_extra_de: float = 0.0,
    materials: str = "R,Y,G,C,B",
) -> Dict[str, object]:
    """Optional PPV109 directional adjacent-token run compaction.

    Works on AP cells. Each accepted swap exchanges one physical layer token
    (material+dose) between two adjacent AP cells in that layer's true print
    direction. It then expands the AP cell back over the full RP block.

    A swap is accepted only if local run score improves and both affected cells'
    final target-vs-predicted Lab error after the swap is no more than their
    pre-run-compact Lab error + max_extra_de. No absolute DeltaE ceiling is used.
    """
    max_extra_de = float(max_extra_de)
    allowed = {m.strip().upper() for m in str(materials).split(',') if m.strip()}
    allowed.discard(EMPTY_MAT)
    allowed.discard('W')
    report: Dict[str, object] = {
        "enabled": False,
        "algorithm": "ppv109_directional_adjacent_token_run_compaction",
        "max_extra_de": float(max_extra_de),
        "materials": sorted(allowed),
        "ap_scale": int(ap_scale),
    }
    if max_extra_de <= 0.0:
        report["disabled_reason"] = "max_extra_de <= 0"
        return report
    if not allowed:
        report["disabled_reason"] = "no allowed materials"
        return report

    h, w, layers = stack.shape
    ap = max(1, int(ap_scale))
    ny = h // ap
    nx = w // ap
    if ny <= 0 or nx <= 0:
        report["disabled_reason"] = "empty AP grid"
        return report

    cell_mats = np.empty((ny, nx, layers), dtype='<U1')
    cell_dose = np.zeros((ny, nx, layers), dtype=np.float32)
    for cy in range(ny):
        yy = cy * ap
        for cx in range(nx):
            xx = cx * ap
            cell_mats[cy, cx, :] = stack[yy, xx, :]
            cell_dose[cy, cx, :] = dose[yy, xx, :]

    target_rgb_model = np.asarray(targets_top[::-1, :, :], dtype=np.float32)
    target_lab_model = _srgb_to_lab_array(np.clip(target_rgb_model, 0, 255))

    base_de = np.zeros((ny, nx), dtype=np.float32)
    current_de = np.zeros((ny, nx), dtype=np.float32)
    for cy in range(ny):
        for cx in range(nx):
            de, _rgb = _run_compact_de_for_cell(cell_mats[cy, cx, :], cell_dose[cy, cx, :], target_lab_model[cy, cx], optical_model)
            base_de[cy, cx] = float(de)
            current_de[cy, cx] = float(de)

    before_cont = _global_scanline_continuity_count(cell_mats)
    attempts = accepted = 0
    rejected_material = rejected_same = rejected_no_gain = rejected_de_a = rejected_de_b = 0
    touched = np.zeros((ny, nx), dtype=bool)
    extra_de_values: List[float] = []
    per_layer = [{"layer": int(li + 1), "orientation": orientation(li + 1), "attempts": 0, "accepted": 0} for li in range(layers)]
    per_pair: Dict[str, int] = {}
    score_gain_total = 0

    def line_cells_for_layer(li: int) -> Iterable[List[Tuple[int, int]]]:
        orient = orientation(li + 1)
        if orient == 'X':
            for cy0 in range(ny):
                yield [(cy0, cx0) for cx0 in (range(nx) if (cy0 % 2) == 0 else range(nx - 1, -1, -1))]
        else:
            for cx0 in range(nx):
                yield [(cy0, cx0) for cy0 in (range(ny) if (cx0 % 2) == 0 else range(ny - 1, -1, -1))]

    for li in range(layers):
        st = per_layer[li]
        for line in line_cells_for_layer(li):
            i = 0
            while i < len(line) - 1:
                cy_a, cx_a = line[i]
                cy_b, cx_b = line[i + 1]
                mat_a = str(cell_mats[cy_a, cx_a, li])
                mat_b = str(cell_mats[cy_b, cx_b, li])
                if mat_a == mat_b:
                    rejected_same += 1; i += 1; continue
                if mat_a not in allowed or mat_b not in allowed:
                    rejected_material += 1; i += 1; continue
                dose_a = float(cell_dose[cy_a, cx_a, li])
                dose_b = float(cell_dose[cy_b, cx_b, li])
                if dose_a <= 0.0 or dose_b <= 0.0:
                    rejected_material += 1; i += 1; continue

                lo = max(0, i - 1)
                hi = min(len(line), i + 4)
                before_seq = [str(cell_mats[cy0, cx0, li]) for cy0, cx0 in line[lo:hi]]
                rel_a = i - lo
                rel_b = i + 1 - lo
                after_seq = list(before_seq)
                after_seq[rel_a], after_seq[rel_b] = after_seq[rel_b], after_seq[rel_a]
                before_score = _run_compact_sequence_score(before_seq, allowed)
                after_score = _run_compact_sequence_score(after_seq, allowed)
                attempts += 1; st["attempts"] += 1
                if after_score <= before_score:
                    rejected_no_gain += 1; i += 1; continue

                new_mats_a = list(cell_mats[cy_a, cx_a, :])
                new_dose_a = [float(v) for v in cell_dose[cy_a, cx_a, :]]
                new_mats_b = list(cell_mats[cy_b, cx_b, :])
                new_dose_b = [float(v) for v in cell_dose[cy_b, cx_b, :]]
                new_mats_a[li], new_mats_b[li] = new_mats_b[li], new_mats_a[li]
                new_dose_a[li], new_dose_b[li] = new_dose_b[li], new_dose_a[li]
                new_de_a, _ = _run_compact_de_for_cell(new_mats_a, new_dose_a, target_lab_model[cy_a, cx_a], optical_model)
                new_de_b, _ = _run_compact_de_for_cell(new_mats_b, new_dose_b, target_lab_model[cy_b, cx_b], optical_model)
                extra_a = float(new_de_a - float(base_de[cy_a, cx_a]))
                extra_b = float(new_de_b - float(base_de[cy_b, cx_b]))
                if extra_a > max_extra_de + 1e-6:
                    rejected_de_a += 1; i += 1; continue
                if extra_b > max_extra_de + 1e-6:
                    rejected_de_b += 1; i += 1; continue

                old_a_m, old_b_m = mat_a, mat_b
                cell_mats[cy_a, cx_a, li], cell_mats[cy_b, cx_b, li] = cell_mats[cy_b, cx_b, li], cell_mats[cy_a, cx_a, li]
                cell_dose[cy_a, cx_a, li], cell_dose[cy_b, cx_b, li] = cell_dose[cy_b, cx_b, li], cell_dose[cy_a, cx_a, li]
                current_de[cy_a, cx_a] = float(new_de_a)
                current_de[cy_b, cx_b] = float(new_de_b)
                touched[cy_a, cx_a] = True; touched[cy_b, cx_b] = True
                accepted += 1; st["accepted"] += 1
                score_gain_total += int(after_score - before_score)
                key = f"{old_a_m}<->{old_b_m}"
                per_pair[key] = per_pair.get(key, 0) + 1
                extra_de_values.extend([max(0.0, extra_a), max(0.0, extra_b)])
                i += 2

    after_cont = _global_scanline_continuity_count(cell_mats)
    for cy in range(ny):
        for cx in range(nx):
            y0 = cy * ap; y1 = min((cy + 1) * ap, h)
            x0 = cx * ap; x1 = min((cx + 1) * ap, w)
            stack[y0:y1, x0:x1, :] = cell_mats[cy, cx, :]
            dose[y0:y1, x0:x1, :] = cell_dose[cy, cx, :]

    extra = np.asarray(extra_de_values, dtype=np.float32) if extra_de_values else np.asarray([], dtype=np.float32)
    report.update({
        "enabled": True,
        "ap_cells": int(nx * ny),
        "layers": int(layers),
        "attempts": int(attempts),
        "accepted_swaps": int(accepted),
        "unique_cells_touched": int(np.count_nonzero(touched)),
        "rejected_same_material": int(rejected_same),
        "rejected_material_not_allowed": int(rejected_material),
        "rejected_no_run_score_gain": int(rejected_no_gain),
        "rejected_delta_e_cell_a": int(rejected_de_a),
        "rejected_delta_e_cell_b": int(rejected_de_b),
        "scanline_continuity_before": int(before_cont),
        "scanline_continuity_after": int(after_cont),
        "scanline_continuity_delta": int(after_cont - before_cont),
        "local_score_gain_total": int(score_gain_total),
        "per_layer": per_layer,
        "per_material_pair": dict(sorted(per_pair.items(), key=lambda kv: (-kv[1], kv[0]))),
        "extra_de_mean": float(extra.mean()) if extra.size else 0.0,
        "extra_de_p95": float(np.percentile(extra, 95)) if extra.size else 0.0,
        "extra_de_max": float(extra.max()) if extra.size else 0.0,
        "rule": "adjacent AP-cell tokens are swapped bottom-up in true layer print direction only when local run score improves and both affected cells stay within pre-run-compact DeltaE + max_extra_de; accepted swaps skip the next cell to prevent token floating",
    })
    return report





def _normalise_printed_recipe(value: object) -> str:
    """Canonical bottom-to-top printed recipe tokens joined with pipes."""
    tokens = [tok.strip() for tok in re.split(r"[|\s]+", str(value or "").strip()) if tok.strip()]
    return "|".join(tokens)


def _printed_recipe_cloud_key(recipe: str, material_to_code: Dict[str, int]) -> bytes:
    """Return the LUT cloud's exact 8-material/8-dose byte identity."""
    tokens = [tok for tok in _normalise_printed_recipe(recipe).split("|") if tok]
    if len(tokens) != MIX_LAYERS:
        raise RuntimeError(f"printed recipe must have exactly {MIX_LAYERS} layers: {recipe!r}")
    mats = np.zeros((MIX_LAYERS,), dtype=np.uint8)
    doses = np.zeros((MIX_LAYERS,), dtype=np.uint8)
    for li, token in enumerate(tokens):
        if token == ".":
            continue
        match = re.fullmatch(r"([A-Za-z]+)(\d+)", token)
        if match is None:
            raise RuntimeError(f"invalid printed recipe token {token!r} in {recipe!r}")
        material = match.group(1).upper()
        if material not in material_to_code:
            raise RuntimeError(f"printed recipe material {material!r} is absent from the LUT material order")
        pct = int(match.group(2))
        pct = max(0, min(255, pct))
        mats[li] = int(material_to_code[material])
        doses[li] = int(pct)
    return mats.tobytes() + doses.tobytes()


def _resolve_previous_recipes_in_cloud(
    lookup: RecipeLookup,
    recipes: Iterable[str],
) -> Tuple[Dict[str, int], Dict[str, object]]:
    """Resolve exact physical recipe stacks, preferring accepted-history rows.

    Lutmaker's cloud is deduplicated by the exact material+dose stack, but the
    cloud_is_exact_measured flag deliberately covers only accepted history.
    Previous printed stacks that failed that narrower acceptance filter can
    still be replayed safely when their exact physical stack is present in the
    deployable cloud. This targeted scan does not build a four-million-entry
    Python dictionary.
    """
    wanted = sorted({_normalise_printed_recipe(recipe) for recipe in recipes})
    wanted_set = set(wanted)
    material_to_code = {str(material).upper(): i for i, material in enumerate(lookup.recipe_materials)}
    key_to_recipe = {_printed_recipe_cloud_key(recipe, material_to_code): recipe for recipe in wanted}
    resolved: Dict[str, int] = {}

    # First prefer accepted-history entries. This set is small enough to decode
    # conventionally and preserves the authoritative history label where one exists.
    exact_flags = np.asarray(lookup.cloud_is_exact_measured, dtype=np.uint8)
    for ridx in np.flatnonzero(exact_flags > 0).tolist():
        mats, doses = lookup.recipe_stack_for_recipe_index(int(ridx))
        candidate = "|".join(_printed_token(m, float(d), model_policy=True) for m, d in zip(mats, doses))
        if candidate in wanted_set:
            resolved.setdefault(candidate, int(ridx))

    unresolved_recipes = [recipe for recipe in wanted if recipe not in resolved]
    if unresolved_recipes:
        unresolved_keys = {
            _printed_recipe_cloud_key(recipe, material_to_code): recipe
            for recipe in unresolved_recipes
        }
        target_void = np.asarray(list(unresolved_keys.keys()), dtype=f"V{2 * MIX_LAYERS}")
        cloud_mats = np.asarray(lookup.recipe_stack_material_id, dtype=np.uint8)
        cloud_dose_source = np.asarray(lookup.recipe_stack_dose, dtype=np.float32)
        if cloud_mats.shape != cloud_dose_source.shape or cloud_mats.ndim != 2 or cloud_mats.shape[1] != MIX_LAYERS:
            raise RuntimeError("LUT cloud material/dose arrays cannot be used for exact previous-recipe replay")
        chunk = 262144
        for start in range(0, cloud_mats.shape[0], chunk):
            end = min(cloud_mats.shape[0], start + chunk)
            block_doses = np.rint(cloud_dose_source[start:end] * 100.0).clip(0, 255).astype(np.uint8)
            packed = np.ascontiguousarray(np.concatenate((cloud_mats[start:end], block_doses), axis=1))
            packed_void = packed.view(f"V{2 * MIX_LAYERS}").reshape(-1)
            matches = np.flatnonzero(np.isin(packed_void, target_void))
            for local_index in matches.tolist():
                key = bytes(packed[local_index])
                recipe = unresolved_keys.get(key)
                if recipe is not None:
                    resolved.setdefault(recipe, start + int(local_index))
            if len(resolved) == len(wanted):
                break

    exact_resolved = sum(int(exact_flags[index] > 0) for index in resolved.values())
    report = {
        "unique_previous_recipes": len(wanted),
        "unique_resolved_recipes": len(resolved),
        "unique_resolved_as_accepted_history": int(exact_resolved),
        "unique_resolved_as_other_cloud_recipe": int(len(resolved) - exact_resolved),
        "unique_unresolved_recipes": int(len(wanted) - len(resolved)),
    }
    return resolved, report


def _apply_calibration_recipe_continuity(
    lookup: RecipeLookup,
    recipe_idx_flat: np.ndarray,
    pred_flat: np.ndarray,
    targets_flat: np.ndarray,
    *,
    nx: int,
    ny: int,
    source_scale: int,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, Dict[str, object]]:
    """Softly retain the exact previous printed recipe where measurement supports it.

    This is deliberately different from a fixed holdout. Every recipe tile is
    evaluated independently. The previous recipe receives a colour-score bonus
    that fades as exp(-(measured_de / scale_de)^2). It is retained only when its
    current LUT-predicted DeltaE minus that bonus is no worse than the normally
    selected candidate's current predicted DeltaE. If a previous recipe is no
    longer printable under the current LUT rules, continuity is unavailable for
    that tile and the normally selected best valid LUT candidate is retained.
    Optionally, a measured-error threshold can hard-retain the previous recipe;
    the recipe must still resolve in the current safe LUT cloud.
    """
    previous_path = globals().get("RUNTIME_CALIBRATION_CONTINUITY_EXTRACTED_TILES", None)
    tile_manifest_path = globals().get("RUNTIME_TILE_MANIFEST_IN", None)
    bonus_de = float(globals().get("RUNTIME_CALIBRATION_CONTINUITY_BONUS_DE", 1.0) or 0.0)
    scale_de = float(globals().get("RUNTIME_CALIBRATION_CONTINUITY_SCALE_DE", 3.0) or 0.0)
    hard_hold_below_de = float(globals().get("RUNTIME_CALIBRATION_CONTINUITY_HOLD_BELOW_DE", 0.0) or 0.0)
    retained = np.zeros((ny, nx), dtype=bool)
    applied = np.zeros((ny, nx), dtype=bool)
    measured_grid = np.full((ny, nx), np.nan, dtype=np.float32)
    if previous_path is None:
        return recipe_idx_flat, pred_flat, retained, applied, measured_grid, {
            "enabled": False,
            "retained_previous_tiles": 0,
            "applied_tiles": 0,
        }
    if tile_manifest_path is None:
        raise RuntimeError("calibration continuity requires --tile-manifest-in")
    if bonus_de <= 0.0:
        raise RuntimeError("--calibration-continuity-bonus-de must be positive")
    if scale_de <= 0.0:
        raise RuntimeError("--calibration-continuity-scale-de must be positive")
    if hard_hold_below_de < 0.0:
        raise RuntimeError("--calibration-continuity-hold-below-de must be non-negative")

    with Path(previous_path).open("r", newline="", encoding="utf-8-sig") as f:
        extracted_rows = [
            row for row in csv.DictReader(f)
            if str(row.get("tile_manifest_role", row.get("role", ""))).strip().lower() == "recipe"
        ]
    with Path(tile_manifest_path).open("r", newline="", encoding="utf-8-sig") as f:
        card_rows = [row for row in csv.DictReader(f) if str(row.get("role", "")).strip().lower() == "recipe"]
    if len(card_rows) != 3427 or len(extracted_rows) != 3427:
        raise RuntimeError(
            "calibration continuity requires exactly 3427 recipe rows in both files; "
            f"current={len(card_rows)} previous_extraction={len(extracted_rows)}"
        )

    previous_by_key: Dict[str, Dict[str, str]] = {}
    for row in extracted_rows:
        key = str(row.get("tile_manifest_print_key", row.get("print_key", ""))).strip()
        if not key or key in previous_by_key:
            raise RuntimeError(f"calibration continuity extraction has a blank or duplicate print_key: {key!r}")
        previous_by_key[key] = row

    previous_recipes = {
        _normalise_printed_recipe(
            row.get("recipe_model_bottom_to_top", row.get("actual_recipe_model_bottom_to_top", ""))
        )
        for row in extracted_rows
    }
    previous_lookup, resolver_report = _resolve_previous_recipes_in_cloud(lookup, previous_recipes)
    exact_flags = np.asarray(lookup.cloud_is_exact_measured, dtype=np.uint8)

    recipe_idx = np.asarray(recipe_idx_flat, dtype=np.int64).copy()
    predictions = np.asarray(pred_flat, dtype=np.float32).copy()
    target_lab_all = _srgb_to_lab_array(np.asarray(targets_flat, dtype=np.float32))
    predicted_costs: List[float] = []
    bonus_values: List[float] = []
    already_previous = 0
    applied_tiles = 0
    retained_tiles = 0
    hard_held_tiles = 0
    accepted_history_tiles = 0
    other_cloud_tiles = 0
    unresolved: List[Tuple[str, str]] = []
    band_edges = [(-math.inf, 3.0, "le_3"), (3.0, 5.0, "gt_3_le_5"), (5.0, 10.0, "gt_5_le_10"), (10.0, math.inf, "gt_10")]
    bands: Dict[str, Dict[str, int]] = {
        name: {"tiles": 0, "already_previous": 0, "applied": 0, "hard_held": 0, "retained_previous": 0, "changed_after": 0}
        for _lo, _hi, name in band_edges
    }

    for row in card_rows:
        key = str(row.get("print_key", "")).strip()
        old = previous_by_key.get(key)
        if old is None:
            raise RuntimeError(f"calibration continuity extraction has no row for current print_key {key!r}")
        previous_recipe = _normalise_printed_recipe(
            old.get("recipe_model_bottom_to_top", old.get("actual_recipe_model_bottom_to_top", ""))
        )
        previous_idx = previous_lookup.get(previous_recipe)
        if previous_idx is None:
            unresolved.append((key, previous_recipe))
            continue
        if exact_flags[previous_idx] > 0:
            accepted_history_tiles += 1
        else:
            other_cloud_tiles += 1
        try:
            np_rgb = np.asarray([float(old[f"np_photo_rgb_{c}"]) for c in "RGB"], dtype=np.float32)
            dp_rgb = np.asarray([float(old[f"dp_photo_rgb_{c}"]) for c in "RGB"], dtype=np.float32)
        except Exception as exc:
            raise RuntimeError(f"calibration continuity row {key!r} lacks complete NP/3DP measured RGB") from exc
        measured_de = float(np.linalg.norm(
            _srgb_to_lab_array(np_rgb.reshape(1, 3))[0]
            - _srgb_to_lab_array(dp_rgb.reshape(1, 3))[0]
        ))
        bonus = float(bonus_de * math.exp(-((measured_de / scale_de) ** 2)))

        gx0 = int(float(row["x0_px"])); gy0 = int(float(row["y0_px"]))
        gx1 = int(float(row.get("x1_excl", int(float(row.get("x1_px", gx0))) + 1)))
        gy1 = int(float(row.get("y1_excl", int(float(row.get("y1_px", gy0))) + 1)))
        cx = (gx0 + gx1 - 1) // 2; cy = (gy0 + gy1 - 1) // 2
        ax, ay = cx // source_scale, cy // source_scale
        if not (0 <= ax < nx and 0 <= ay < ny):
            raise RuntimeError(f"calibration continuity tile {key!r} centre is outside the AP grid")
        current_idx = int(recipe_idx[ay * nx + ax])
        target_lab = target_lab_all[ay * nx + ax]
        current_de = float(np.linalg.norm(np.asarray(lookup.recipe_pred_lab[current_idx], dtype=np.float32) - target_lab))
        previous_de = float(np.linalg.norm(np.asarray(lookup.recipe_pred_lab[previous_idx], dtype=np.float32) - target_lab))
        hard_hold = bool(hard_hold_below_de > 0.0 and measured_de < hard_hold_below_de)
        use_previous = current_idx == previous_idx or hard_hold or (previous_de - bonus <= current_de + 1e-7)

        band_name = next(name for lo, hi, name in band_edges if measured_de > lo and measured_de <= hi)
        bands[band_name]["tiles"] += 1
        if current_idx == previous_idx:
            already_previous += 1
            bands[band_name]["already_previous"] += 1
        elif use_previous:
            applied_tiles += 1
            bands[band_name]["applied"] += 1
            predicted_costs.append(previous_de - current_de)
            bonus_values.append(bonus)
        if hard_hold:
            hard_held_tiles += 1
            bands[band_name]["hard_held"] += 1
        if use_previous:
            retained_tiles += 1
            bands[band_name]["retained_previous"] += 1
        else:
            bands[band_name]["changed_after"] += 1

        x0 = max(0, gx0 // source_scale); y0 = max(0, gy0 // source_scale)
        x1 = min(nx, (gx1 + source_scale - 1) // source_scale)
        y1 = min(ny, (gy1 + source_scale - 1) // source_scale)
        if x0 >= x1 or y0 >= y1:
            raise RuntimeError(f"calibration continuity tile {key!r} has an empty AP-cell rectangle")
        measured_grid[y0:y1, x0:x1] = measured_de
        if use_previous:
            retained[y0:y1, x0:x1] = True
        if current_idx != previous_idx and use_previous:
            for yy in range(y0, y1):
                start, end = yy * nx + x0, yy * nx + x1
                recipe_idx[start:end] = previous_idx
                predictions[start:end] = lookup.recipe_pred_rgb[previous_idx]
            applied[y0:y1, x0:x1] = True

    cost = np.asarray(predicted_costs, dtype=np.float32)
    bonuses = np.asarray(bonus_values, dtype=np.float32)
    unresolved_examples = [
        {"print_key": key, "previous_recipe": recipe}
        for key, recipe in unresolved[:10]
    ]
    report: Dict[str, object] = {
        "enabled": True,
        "mode": ("measured_error_hard_hold_plus_soft_bonus" if hard_hold_below_de > 0.0 else "soft_previous_printed_recipe_measured_error"),
        "source_file": str(previous_path),
        "source_sha256": _sha256_file(Path(previous_path)),
        "bonus_de": float(bonus_de),
        "scale_de": float(scale_de),
        "hard_hold_below_delta_e76": float(hard_hold_below_de),
        "card_tiles": len(card_rows),
        "previous_recipe_resolution": resolver_report,
        "previous_tiles_resolved": int(len(card_rows) - len(unresolved)),
        "previous_tiles_unresolved": int(len(unresolved)),
        "previous_tile_resolution_fraction": float(
            (len(card_rows) - len(unresolved)) / max(len(card_rows), 1)
        ),
        "unresolved_fallback": "best_valid_lut_candidate",
        "unresolved_previous_recipe_examples": unresolved_examples,
        "previous_tiles_resolved_as_accepted_history": int(accepted_history_tiles),
        "previous_tiles_resolved_as_other_cloud_recipe": int(other_cloud_tiles),
        "already_previous_tiles": int(already_previous),
        "applied_tiles": int(applied_tiles),
        "retained_previous_tiles": int(retained_tiles),
        "hard_held_tiles": int(hard_held_tiles),
        "changed_after_tiles": int(len(card_rows) - retained_tiles),
        "predicted_delta_e_cost_mean_applied": float(cost.mean()) if cost.size else 0.0,
        "predicted_delta_e_cost_p95_applied": float(np.percentile(cost, 95)) if cost.size else 0.0,
        "predicted_delta_e_cost_max_applied": float(cost.max()) if cost.size else 0.0,
        "effective_bonus_mean_applied": float(bonuses.mean()) if bonuses.size else 0.0,
        "measured_error_bands": bands,
    }
    return recipe_idx, predictions, retained, applied, measured_grid, report


def _apply_calibration_recipe_holdout(
    lookup: RecipeLookup,
    recipe_idx_flat: np.ndarray,
    pred_flat: np.ndarray,
    *,
    nx: int,
    ny: int,
    source_scale: int,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray, Dict[str, object]]:
    previous_path = globals().get("RUNTIME_CALIBRATION_HOLDOUT_PRINTED_TILE_RECIPES", None)
    fraction = float(globals().get("RUNTIME_CALIBRATION_HOLDOUT_FRACTION", 0.0) or 0.0)
    tile_manifest_path = globals().get("RUNTIME_TILE_MANIFEST_IN", None)
    holdout = np.zeros((ny, nx), dtype=bool)
    if previous_path is None or fraction <= 0.0:
        return recipe_idx_flat, pred_flat, holdout, {"enabled": False, "selected_tiles": 0}
    if tile_manifest_path is None:
        raise RuntimeError("calibration holdout requires --tile-manifest-in")
    if not (0.0 < fraction < 1.0):
        raise RuntimeError("--calibration-holdout-fraction must be greater than 0 and less than 1")

    with Path(previous_path).open("r", newline="", encoding="utf-8-sig") as f:
        old_rows = {
            str(row.get("print_key", "")).strip(): row
            for row in csv.DictReader(f)
            if str(row.get("role", "")).strip().lower() == "recipe"
        }
    with Path(tile_manifest_path).open("r", newline="", encoding="utf-8-sig") as f:
        card_rows = [row for row in csv.DictReader(f) if str(row.get("role", "")).strip().lower() == "recipe"]
    if len(card_rows) != 3427 or len(old_rows) != 3427:
        raise RuntimeError(f"holdout requires 3427 recipe rows in both maps; current={len(card_rows)} previous={len(old_rows)}")

    exact_lookup: Dict[str, int] = {}
    exact_indices = np.flatnonzero(np.asarray(lookup.cloud_is_exact_measured, dtype=np.uint8) > 0)
    for ridx in exact_indices.tolist():
        mats, doses = lookup.recipe_stack_for_recipe_index(int(ridx))
        recipe = "|".join(_printed_token(m, float(d), model_policy=True) for m, d in zip(mats, doses))
        exact_lookup.setdefault(recipe, int(ridx))

    seed = str(globals().get("RUNTIME_CALIBRATION_HOLDOUT_SEED", "fc3d-fixed-holdout-v1"))
    ranked_rows: List[Tuple[str, Dict[str, str], str]] = []
    for row in card_rows:
        key = str(row.get("print_key", "")).strip()
        old = old_rows.get(key)
        recipe = "" if old is None else str(old.get("actual_recipe_model_bottom_to_top", "")).strip()
        if not key or old is None or not recipe:
            raise RuntimeError(
                f"holdout previous tile map has no recipe for current print_key {key!r}"
            )
        ranked_rows.append((key, row, recipe))

    requested = int(round(fraction * len(ranked_rows)))
    all_resolvable = sum(
        1 for _key, _row, recipe in ranked_rows if recipe in exact_lookup
    )

    # Bootstrap the first holdout from positions whose previous recipes are
    # accepted exact-history recipes.  From the next print onward, the v2 map
    # carries calibration_holdout=1 and those exact same print keys are reused.
    previous_holdout_keys = {
        key for key, old in old_rows.items()
        if str(old.get("calibration_holdout", "")).strip().lower()
        in {"1", "true", "yes", "on"}
    }
    if previous_holdout_keys:
        if len(previous_holdout_keys) != requested:
            raise RuntimeError(
                "previous printed-tile map contains "
                f"{len(previous_holdout_keys)} holdout tiles but the requested "
                f"fraction requires {requested}; keep the original fraction"
            )
        selection_mode = "continue_previous_holdout"
        selected_rows = [
            item for item in ranked_rows if item[0] in previous_holdout_keys
        ]
        if len(selected_rows) != requested:
            raise RuntimeError(
                "previous holdout print keys do not match the current card map"
            )
    else:
        selection_mode = "bootstrap_exact_history_holdout"
        eligible_rows = [
            item for item in ranked_rows if item[2] in exact_lookup
        ]
        if len(eligible_rows) < requested:
            raise RuntimeError(
                "holdout needs "
                f"{requested} exact-history tiles but only {len(eligible_rows)} "
                "previous tile recipes are available in the LUT; rebuild the "
                "LUT with exact-history retention enabled"
            )
        eligible_rows.sort(
            key=lambda item: hashlib.sha256(
                f"{seed}|{item[0]}".encode("utf-8")
            ).digest()
        )
        selected_rows = eligible_rows[:requested]

    selected: List[Tuple[str, Dict[str, str], int]] = []
    missing_selected: List[Tuple[str, str]] = []
    for key, row, recipe in selected_rows:
        ridx = exact_lookup.get(recipe)
        if ridx is None:
            missing_selected.append((key, recipe))
        else:
            selected.append((key, row, ridx))
    if missing_selected:
        examples = "; ".join(
            f"{key}={recipe}" for key, recipe in missing_selected[:3]
        )
        raise RuntimeError(
            "holdout could resolve only "
            f"{len(selected)}/{requested} deterministically selected previous "
            "recipes as exact history recipes; rebuild the LUT with exact-history "
            f"retention enabled; examples: {examples}"
        )

    recipe_idx = np.asarray(recipe_idx_flat, dtype=np.int64).copy()
    predictions = np.asarray(pred_flat, dtype=np.float32).copy()
    for key, row, ridx in selected:
        x0 = int(float(row["x0_px"])) // source_scale
        y0 = int(float(row["y0_px"])) // source_scale
        x1 = (int(float(row.get("x1_excl", row.get("x1_px", 0)))) + source_scale - 1) // source_scale
        y1 = (int(float(row.get("y1_excl", row.get("y1_px", 0)))) + source_scale - 1) // source_scale
        x0, y0 = max(0, x0), max(0, y0)
        x1, y1 = min(nx, x1), min(ny, y1)
        if x0 >= x1 or y0 >= y1:
            raise RuntimeError(f"holdout tile {key!r} has an empty AP-cell rectangle")
        for yy in range(y0, y1):
            start, end = yy * nx + x0, yy * nx + x1
            recipe_idx[start:end] = ridx
            predictions[start:end] = lookup.recipe_pred_rgb[ridx]
        holdout[y0:y1, x0:x1] = True
    report = {
        "enabled": True,
        "fraction_requested": fraction,
        "selection_mode": selection_mode,
        "card_tiles": len(ranked_rows),
        "previous_recipes_resolvable_as_exact_history": int(all_resolvable),
        "selected_tiles": len(selected),
        "selected_pct": 100.0 * len(selected) / len(ranked_rows),
        "seed": seed,
        "source_file": str(previous_path),
        "source_sha256": hashlib.sha256(Path(previous_path).read_bytes()).hexdigest(),
        "selected_print_keys_sha256": hashlib.sha256("\n".join(sorted(key for key, _row, _idx in selected)).encode("utf-8")).hexdigest(),
    }
    return recipe_idx, predictions, holdout, report


def build_stack_lut_cell_plan(img: Image.Image, lookup: RecipeLookup, source_scale: int = 1, max_physical_slots: int = 8) -> Tuple[np.ndarray, np.ndarray]:
    """Build an RP emission grid directly from a recipegenv64 recipe-stack LUT.

    This is the clean PSPV1 path:
      averaged source RGB -> nearest stack-LUT grid row -> selected_recipe_index
      -> recipe_stack_values/material_id/dose -> final emission grid.

    It deliberately does not use selected_demand_units, fit_demand_to_stack, or
    candidate_packed_stack_json.
    """
    if not getattr(lookup, "is_stack_lut", False):
        raise RuntimeError("build_stack_lut_cell_plan requires recipegenv64 stack LUT arrays")
    global PRECOMPUTED_DOSE_GRID, DIRECT_OPTICAL_LAYER_COUNT, CANDIDATE_SELECTION_REPORT, DEMAND_STACK_PREVIEW_RGB, DEMAND_LUT_STACK_DIFF_RGB, DEMAND_PP_REFIT_STACK_PREVIEW_RGB, DEMAND_LUT_STACK_DEBUG_REPORT, PRECOMPUTED_CELL_TARGET_RGB_TOP, PRECOMPUTED_CELL_GRID_INDEX, PRECOMPUTED_CELL_RECIPE_INDEX, PRECOMPUTED_CELL_PRED_RGB_TOP, PRECOMPUTED_CELL_SELECTED_DELTAE, PRECOMPUTED_CELL_SELECTED_SCORE, PRECOMPUTED_CELL_HOLDOUT, PRECOMPUTED_CELL_CONTINUITY, PRECOMPUTED_CELL_CONTINUITY_APPLIED, PRECOMPUTED_CELL_CONTINUITY_MEASURED_DE

    n_slots = int(max_physical_slots)
    DIRECT_OPTICAL_LAYER_COUNT = n_slots
    optical_model = _demand_optical_model_from_lookup(lookup)

    arr = np.asarray(img.convert("RGB"), dtype=np.float32)
    h, w = arr.shape[:2]
    source_scale = max(1, int(source_scale))
    if h < source_scale or w < source_scale:
        raise ValueError(f"pixel_head_width/source_scale={source_scale} requires image at least {source_scale}x{source_scale}")
    ny = h // source_scale
    nx = w // source_scale
    if ny * source_scale != h or nx * source_scale != w:
        print(f"Warning: input image {w}x{h} is not divisible by pixel_head_width={source_scale}; cropping to {nx*source_scale}x{ny*source_scale}")
    arr_work = arr[:ny*source_scale, :nx*source_scale, :]

    total_cells = int(nx * ny)
    prog = _ProgressReporter("stack LUT: average RGB cells", total_cells)
    targets_top = np.zeros((ny, nx, 3), dtype=np.float32)
    done_cells = 0
    for yb in range(ny):
        for xb in range(nx):
            y0 = yb * source_scale; y1 = (yb + 1) * source_scale
            x0 = xb * source_scale; x1 = (xb + 1) * source_scale
            targets_top[yb, xb] = arr_work[y0:y1, x0:x1, :].mean(axis=(0,1))
            done_cells += 1
        prog.update(done_cells)
    prog.done(done_cells)

    flat_targets = targets_top.reshape(-1, 3)
    print(f"[stack LUT] looking up {len(flat_targets):,} averaged RGB cells in {getattr(lookup, 'lut_kind', 'stack LUT')}...", file=sys.stderr, flush=True)
    t_lookup = time.time()
    grid_idx_flat = lookup.nearest_stack_indices_batch(flat_targets)
    bucket_choice_mode = str(globals().get("RUNTIME_LUT_BUCKET_CHOICE", "prime"))
    bucket_choice_count = int(globals().get("RUNTIME_LUT_BUCKET_CHOICE_COUNT", 32))
    recipe_idx_flat, pred_flat, bucket_choice_report = lookup.select_recipe_indices_for_grid_targets(
        grid_idx_flat, flat_targets, mode=bucket_choice_mode, candidate_count=bucket_choice_count
    )
    baseline_recipe_idx_flat = np.asarray(recipe_idx_flat, dtype=np.int64).copy()
    organic_exact_cells = int(np.count_nonzero(np.asarray(lookup.cloud_is_exact_measured, dtype=np.uint8)[np.asarray(recipe_idx_flat, dtype=np.int64)]))
    recipe_idx_flat, pred_flat, PRECOMPUTED_CELL_CONTINUITY, PRECOMPUTED_CELL_CONTINUITY_APPLIED, PRECOMPUTED_CELL_CONTINUITY_MEASURED_DE, continuity_report = _apply_calibration_recipe_continuity(
        lookup, recipe_idx_flat, pred_flat, flat_targets, nx=nx, ny=ny, source_scale=source_scale,
    )
    recipe_idx_flat, pred_flat, PRECOMPUTED_CELL_HOLDOUT, holdout_report = _apply_calibration_recipe_holdout(
        lookup, recipe_idx_flat, pred_flat, nx=nx, ny=ny, source_scale=source_scale,
    )
    bucket_choice_report["organic_selected_exact_history_cells"] = organic_exact_cells
    bucket_choice_report["organic_selected_exact_history_pct"] = 100.0 * organic_exact_cells / max(1, len(recipe_idx_flat))
    bucket_choice_report["calibration_continuity"] = continuity_report
    bucket_choice_report["calibration_holdout"] = holdout_report
    bucket_choice_report["final_selected_exact_history_cells"] = int(np.count_nonzero(np.asarray(lookup.cloud_is_exact_measured, dtype=np.uint8)[np.asarray(recipe_idx_flat, dtype=np.int64)]))
    tile_manifest_for_audit = globals().get("RUNTIME_TILE_MANIFEST_IN", None)
    if tile_manifest_for_audit is not None:
        with Path(tile_manifest_for_audit).open("r", newline="", encoding="utf-8-sig") as f:
            audit_rows = [row for row in csv.DictReader(f) if str(row.get("role", "")).strip().lower() == "recipe"]
        if len(audit_rows) == 3427:
            exact_flags = np.asarray(lookup.cloud_is_exact_measured, dtype=np.uint8)
            tile_exact = 0
            tile_baseline_exact = 0
            tile_holdout = 0
            tile_continuity = 0
            tile_continuity_applied = 0
            tile_small_ve = 0
            tile_wide_ve = 0
            tile_ve_unresolved = 0
            for row in audit_rows:
                cx = (int(float(row["x0_px"])) + int(float(row.get("x1_excl", row.get("x1_px", 0)))) - 1) // 2
                cy = (int(float(row["y0_px"])) + int(float(row.get("y1_excl", row.get("y1_px", 0)))) - 1) // 2
                ax, ay = cx // source_scale, cy // source_scale
                ridx = int(recipe_idx_flat[ay * nx + ax])
                baseline_ridx = int(baseline_recipe_idx_flat[ay * nx + ax])
                tile_exact += int(exact_flags[ridx] > 0)
                tile_baseline_exact += int(exact_flags[baseline_ridx] > 0)
                tile_holdout += int(PRECOMPUTED_CELL_HOLDOUT[ay, ax])
                tile_continuity += int(PRECOMPUTED_CELL_CONTINUITY[ay, ax])
                tile_continuity_applied += int(PRECOMPUTED_CELL_CONTINUITY_APPLIED[ay, ax])
                if exact_flags[ridx] == 0:
                    grid_index = int(grid_idx_flat[ay * nx + ax])
                    bucket = np.asarray(lookup.multi_recipe_index[grid_index], dtype=np.int64)
                    pos = np.flatnonzero(bucket == ridx)
                    if len(pos) == 1 and getattr(lookup, "multi_recipe_total_ve_movement", None) is not None:
                        movement = float(lookup.multi_recipe_total_ve_movement[grid_index, int(pos[0])])
                        tile_small_ve += int(movement <= 30.0)
                        tile_wide_ve += int(movement > 30.0)
                    else:
                        tile_ve_unresolved += 1
            bucket_choice_report["selected_exact_history_tiles"] = tile_exact
            bucket_choice_report["selected_exact_history_tile_pct"] = 100.0 * tile_exact / len(audit_rows)
            bucket_choice_report["baseline_exact_history_tiles"] = tile_baseline_exact
            bucket_choice_report["holdout_tiles"] = tile_holdout
            bucket_choice_report["continuity_retained_tiles"] = tile_continuity
            bucket_choice_report["continuity_applied_tiles"] = tile_continuity_applied
            bucket_choice_report["organic_exact_history_tiles"] = tile_baseline_exact
            bucket_choice_report["selected_small_ve_variant_tiles_le30"] = tile_small_ve
            bucket_choice_report["selected_wide_ve_variant_tiles_gt30"] = tile_wide_ve
            bucket_choice_report["selected_ve_unresolved_tiles"] = tile_ve_unresolved

    # v1.15 calibration manifest metadata: top-origin AP/cell arrays before RP expansion.
    PRECOMPUTED_CELL_TARGET_RGB_TOP = targets_top.astype(np.float32, copy=True)
    PRECOMPUTED_CELL_GRID_INDEX = np.asarray(grid_idx_flat, dtype=np.int64).reshape(ny, nx).copy()
    PRECOMPUTED_CELL_RECIPE_INDEX = np.asarray(recipe_idx_flat, dtype=np.int64).reshape(ny, nx).copy()
    PRECOMPUTED_CELL_PRED_RGB_TOP = np.asarray(pred_flat, dtype=np.float32).reshape(ny, nx, 3).copy()
    PRECOMPUTED_CELL_SELECTED_DELTAE = None
    PRECOMPUTED_CELL_SELECTED_SCORE = None
    try:
        if getattr(lookup, "multi_recipe_index", None) is not None:
            _top = np.asarray(lookup.multi_recipe_index[np.asarray(grid_idx_flat, dtype=np.int64)], dtype=np.int64)
            if _top.ndim == 1:
                _top = _top[:, None]
            _sel = np.asarray(recipe_idx_flat, dtype=np.int64).reshape(-1)
            _pos = np.zeros((_sel.shape[0],), dtype=np.int64)
            _found = np.zeros((_sel.shape[0],), dtype=bool)
            for _k in range(_top.shape[1]):
                _m = (~_found) & (_top[:, _k] == _sel)
                _pos[_m] = _k
                _found[_m] = True
            _rows = np.arange(_sel.shape[0], dtype=np.int64)
            if getattr(lookup, "multi_recipe_error_lab", None) is not None:
                _err_all = np.asarray(lookup.multi_recipe_error_lab[np.asarray(grid_idx_flat, dtype=np.int64)], dtype=np.float32)
                _target_lab = _srgb_to_lab_array(np.asarray(flat_targets, dtype=np.float32))
                _vals = np.linalg.norm(np.asarray(lookup.recipe_pred_lab[_sel], dtype=np.float32) - _target_lab, axis=1).astype(np.float32)
                _vals[_found] = _err_all[_rows[_found], _pos[_found]]
                PRECOMPUTED_CELL_SELECTED_DELTAE = _vals.reshape(ny, nx).copy()
            if getattr(lookup, "multi_recipe_score", None) is not None:
                _score_all = np.asarray(lookup.multi_recipe_score[np.asarray(grid_idx_flat, dtype=np.int64)], dtype=np.float32)
                _vals = np.full((_sel.shape[0],), np.nan, dtype=np.float32)
                _vals[_found] = _score_all[_rows[_found], _pos[_found]]
                PRECOMPUTED_CELL_SELECTED_SCORE = _vals.reshape(ny, nx).copy()
    except Exception as _e:
        print(f"Warning: could not populate selected candidate metric arrays for calibration manifest: {_e}", file=sys.stderr, flush=True)
    if bucket_choice_report.get("enabled"):
        print(
            "[stack LUT] bucket candidate choice: "
            + json.dumps({k: bucket_choice_report.get(k) for k in ("mode", "metric", "active_colour_distance_mode", "candidate_count_used", "changed_from_prime_cells", "changed_from_prime_pct", "selected_exact_history_without_preference_cells", "selected_exact_history_cells", "changed_by_history_preference_cells", "history_preference_raw_colour_cost_mean", "organic_selected_exact_history_cells", "final_selected_exact_history_cells", "selected_exact_history_tiles", "baseline_exact_history_tiles", "organic_exact_history_tiles", "selected_small_ve_variant_tiles_le30", "selected_wide_ve_variant_tiles_gt30", "selected_ve_unresolved_tiles", "continuity_retained_tiles", "continuity_applied_tiles", "calibration_continuity", "holdout_tiles", "calibration_holdout", "mean_prime_colour_error", "mean_selected_colour_error", "mean_colour_error_improvement", "support2_source")}, sort_keys=True),
            file=sys.stderr, flush=True,
        )
    print(f"[stack LUT] LUT lookup complete in {time.time() - t_lookup:,.1f}s", file=sys.stderr, flush=True)

    h_rp = ny * source_scale
    w_rp = nx * source_scale
    stack = np.full((h_rp, w_rp, n_slots), EMPTY_MAT, dtype='<U1')
    dose = np.zeros((h_rp, w_rp, n_slots), dtype=np.float32)

    stats = {
        "mode": "recipe_stack_lut",
        "lut_kind": getattr(lookup, "lut_kind", "unknown"),
        "lut_script_version": str(getattr(lookup, "metadata", {}).get("script_version", "unknown")),
        "lut_model_name": str(getattr(lookup, "metadata", {}).get("model_name", "unknown")),
        "lut_grid_size": int(getattr(lookup, "metadata", {}).get("grid_size", getattr(lookup, "stack_lut_levels", 0) or 0)),
        "lut_top_k": int(getattr(lookup, "metadata", {}).get("top_k", getattr(lookup, "multi_recipe_count", 0) or 0)),
        "lut_hierarchical_parent_grid": int(getattr(lookup, "metadata", {}).get("hierarchical_parent_grid", 0) or 0),
        "lut_hierarchical_parent_top_k": int(getattr(lookup, "metadata", {}).get("hierarchical_parent_top_k", 0) or 0),
        "cells": int(nx * ny),
        "rp_pixels": int(h_rp * w_rp),
        "source_scale": int(source_scale),
        "max_physical_slots": int(n_slots),
        "recipe_policy_filter": getattr(lookup, "recipe_policy_filter", {}),
        "bucket_candidate_choice_report": bucket_choice_report,
        "active_cells": 0,
        "unique_grid_rows": int(len(set(int(i) for i in np.asarray(grid_idx_flat, dtype=np.int64).tolist()))),
        "unique_recipe_indices": int(len(set(int(i) for i in np.asarray(recipe_idx_flat, dtype=np.int64).tolist()))),
        "slot_mode_counts": {},
        "structural_w_underfill_slots_repaired": 0,
        "w_blocker_scheduler_free_slots_filled_with_w": 0,
        "w_blocker_scheduler_tokens_placed": 0,
        "w_blocker_scheduler_tokens_unplaced": 0,
        "w_blocker_scheduler_fixed_blockers": 0,
        "w_blocker_scheduler_tokens_displaced_from_primary": 0,
        "w_blocker_scheduler_component_contexts_used": 0,
        "w_blocker_scheduler_component_reward_applications": 0,
        "w_blocker_scheduler_component_reward_total_x1000": 0,
        "w_blocker_scheduler_component_run_seed_total": 0,
        "w_blocker_scheduler_isolated_token_penalties": 0,
        "warnings_sample": [],
        "pp_contract": "RGB -> grid row -> selected_recipe_index/cloud recipe -> material+dose stack; no demand refit, no low-dose halftone conversion",
        "dose_mode": str(getattr(lookup, "metadata", {}).get("dose_mode", "recipe_stack_dose")),
        "low_dose_halftone": "disabled",
        "hybrid_speed_ve": "disabled",
    }

    scheduler_mode = str(globals().get("RUNTIME_STACK_SCHEDULER", "off"))
    scheduler_plan = {"enabled": False, "preferred_slots": {}, "report": {"enabled": False, "mode": scheduler_mode}}
    if scheduler_mode == "global-preference":
        scheduler_plan = _build_global_stack_scheduler_plan(recipe_idx_flat, lookup, n_slots)
        stats["stack_scheduler_report"] = scheduler_plan.get("report", {})
        globals()["STACK_SCHEDULER_REPORT"] = scheduler_plan.get("report", {})
        print("[stack scheduler] global-preference enabled: " + json.dumps(scheduler_plan.get("report", {}).get("preferred_slots_one_based", {}), sort_keys=True), file=sys.stderr, flush=True)
    elif scheduler_mode in ("local-preference", "local-neighbour", "local-component"):
        scheduler_plan = _build_local_stack_scheduler_plans(recipe_idx_flat, lookup, nx, ny, n_slots, float(globals().get("RUNTIME_STACK_SCHEDULER_LOCAL_TILE_MM", STACK_SCHEDULER_LOCAL_TILE_MM)))
        stats["stack_scheduler_report"] = scheduler_plan.get("report", {})
        globals()["STACK_SCHEDULER_REPORT"] = scheduler_plan.get("report", {})
        print("[stack scheduler] " + scheduler_mode + " enabled: " + json.dumps(scheduler_plan.get("report", {}), sort_keys=True), file=sys.stderr, flush=True)
    elif scheduler_mode not in ("off", "", "None", "none"):
        raise RuntimeError(f"Unsupported --stack-scheduler mode {scheduler_mode!r}")
    else:
        stats["stack_scheduler_report"] = {"enabled": False, "mode": "off"}
        globals()["STACK_SCHEDULER_REPORT"] = stats["stack_scheduler_report"]

    print(f"[stack LUT] building exact emission grid for {int(nx * ny):,} cells from {stats['unique_recipe_indices']:,} unique selected recipe stacks; decode cache removed...", file=sys.stderr, flush=True)
    scheduled_ap_mats = np.full((ny, nx, n_slots), EMPTY_MAT, dtype='<U1')
    scheduled_run_h = np.zeros((ny, nx, n_slots), dtype=np.uint16)
    scheduled_run_v = np.zeros((ny, nx, n_slots), dtype=np.uint16)
    prog = _ProgressReporter("stack LUT: build exact emission grid", total_cells)
    fitted_cells = 0
    for yb in range(ny):
        for xb in range(nx):
            flat = yb * nx + xb
            ridx = int(recipe_idx_flat[flat])
            cell_plan = _scheduler_plan_for_cell(scheduler_plan, xb, yb) if scheduler_plan.get("enabled") else scheduler_plan
            mats, rdose = lookup.recipe_stack_for_recipe_index(ridx)
            mats, rdose = _normalise_stack_arrays(mats, rdose, n_slots)
            if scheduler_plan.get("enabled"):
                mats, rdose, repaired_slots = _structurally_fill_empty_stack_slots(mats, rdose)
                stats["structural_w_underfill_slots_repaired"] = int(stats.get("structural_w_underfill_slots_repaired", 0)) + int(repaired_slots)
                neighbour_stacks = None
                neighbour_contexts = None
                if scheduler_mode in ("local-neighbour", "local-component"):
                    neighbour_stacks = []
                    if xb > 0:
                        neighbour_stacks.append(scheduled_ap_mats[yb, xb - 1, :])
                    if yb > 0:
                        neighbour_stacks.append(scheduled_ap_mats[yb - 1, xb, :])
                if scheduler_mode == "local-component":
                    neighbour_contexts = []
                    if xb > 0:
                        neighbour_contexts.append({"stack": scheduled_ap_mats[yb, xb - 1, :], "run": scheduled_run_h[yb, xb - 1, :], "direction": "left"})
                    if yb > 0:
                        neighbour_contexts.append({"stack": scheduled_ap_mats[yb - 1, xb, :], "run": scheduled_run_v[yb - 1, xb, :], "direction": "up"})
                mats, rdose, sched_stats = _schedule_stack_w_blocker(mats, rdose, cell_plan, n_slots, neighbour_stacks=neighbour_stacks, neighbour_contexts=neighbour_contexts)
                stats["w_blocker_scheduler_free_slots_filled_with_w"] = int(stats.get("w_blocker_scheduler_free_slots_filled_with_w", 0)) + int(sched_stats.get("free_slots_filled_with_w", 0))
                stats["w_blocker_scheduler_tokens_placed"] = int(stats.get("w_blocker_scheduler_tokens_placed", 0)) + int(sched_stats.get("tokens_placed", 0))
                stats["w_blocker_scheduler_tokens_unplaced"] = int(stats.get("w_blocker_scheduler_tokens_unplaced", 0)) + int(sched_stats.get("tokens_unplaced", 0))
                stats["w_blocker_scheduler_fixed_blockers"] = int(stats.get("w_blocker_scheduler_fixed_blockers", 0)) + int(sched_stats.get("fixed_blockers", 0))
                stats["w_blocker_scheduler_tokens_displaced_from_primary"] = int(stats.get("w_blocker_scheduler_tokens_displaced_from_primary", 0)) + int(sched_stats.get("tokens_displaced_from_primary", 0))
                stats["w_blocker_scheduler_component_contexts_used"] = int(stats.get("w_blocker_scheduler_component_contexts_used", 0)) + int(sched_stats.get("component_contexts_used", 0))
                stats["w_blocker_scheduler_component_reward_applications"] = int(stats.get("w_blocker_scheduler_component_reward_applications", 0)) + int(sched_stats.get("component_reward_applications", 0))
                stats["w_blocker_scheduler_component_reward_total_x1000"] = int(stats.get("w_blocker_scheduler_component_reward_total_x1000", 0)) + int(sched_stats.get("component_reward_total_x1000", 0))
                stats["w_blocker_scheduler_component_run_seed_total"] = int(stats.get("w_blocker_scheduler_component_run_seed_total", 0)) + int(sched_stats.get("component_run_seed_total", 0))
                stats["w_blocker_scheduler_isolated_token_penalties"] = int(stats.get("w_blocker_scheduler_isolated_token_penalties", 0)) + int(sched_stats.get("isolated_token_penalties", 0))
            else:
                mats, rdose, repaired_slots = _structurally_fill_empty_stack_slots(mats, rdose)
                stats["structural_w_underfill_slots_repaired"] = int(stats.get("structural_w_underfill_slots_repaired", 0)) + int(repaired_slots)
            scheduled_ap_mats[yb, xb, :] = mats
            # PPSPV33 local-component run context: causal left/up same-material same-slot run lengths.
            for _si in range(n_slots):
                _m = str(mats[_si]).upper()
                if _m == EMPTY_MAT or float(rdose[_si]) <= 0.0:
                    scheduled_run_h[yb, xb, _si] = 0
                    scheduled_run_v[yb, xb, _si] = 0
                else:
                    _lh = int(scheduled_run_h[yb, xb - 1, _si]) if xb > 0 and str(scheduled_ap_mats[yb, xb - 1, _si]).upper() == _m else 0
                    _uv = int(scheduled_run_v[yb - 1, xb, _si]) if yb > 0 and str(scheduled_ap_mats[yb - 1, xb, _si]).upper() == _m else 0
                    scheduled_run_h[yb, xb, _si] = min(65535, _lh + 1)
                    scheduled_run_v[yb, xb, _si] = min(65535, _uv + 1)
            fitted_cells += 1
            if np.any(rdose > 0):
                stats["active_cells"] += 1
            for li in range(n_slots):
                m = str(mats[li])
                d = float(rdose[li])
                if d <= 0.0 or m == EMPTY_MAT:
                    continue
                stats["slot_mode_counts"][f"stack_lut_{m}"] = stats["slot_mode_counts"].get(f"stack_lut_{m}", 0) + 1
            for yy_top in range(yb * source_scale, (yb + 1) * source_scale):
                y_model = h_rp - 1 - yy_top
                for xx in range(xb * source_scale, (xb + 1) * source_scale):
                    stack[y_model, xx, :] = mats
                    dose[y_model, xx, :] = rdose
        prog.update(fitted_cells)
    prog.done(fitted_cells)
    stats["decoded_recipe_stack_cells"] = int(fitted_cells)
    stats["decoded_recipe_stack_cache"] = "removed"
    print(f"[stack LUT] decoded exact selected recipe for every cell ({fitted_cells:,} cells); legacy refit removed; stack_scheduler={scheduler_mode}", file=sys.stderr, flush=True)

    global STACK_RESORT_REPORT
    STACK_RESORT_REPORT = apply_stack_resort_w_regions(
        stack, dose,
        ap_scale=int(source_scale),
        mode=str(globals().get("RUNTIME_STACK_RESORT", "off")),
        max_permutations=int(globals().get("RUNTIME_STACK_RESORT_MAX_PERMUTATIONS", 720)),
    )
    stats["stack_resort_report"] = STACK_RESORT_REPORT
    if STACK_RESORT_REPORT.get("enabled"):
        print(f"[stack LUT] stack resort: changed {STACK_RESORT_REPORT.get('changed_cells',0):,}/{STACK_RESORT_REPORT.get('ap_cells',0):,} AP cells; swaps {STACK_RESORT_REPORT.get('swaps_accepted',0):,}; scanline-continuity delta {STACK_RESORT_REPORT.get('scanline_continuity_delta',0):,}", file=sys.stderr, flush=True)

    global RUN_COMPACT_REPORT
    RUN_COMPACT_REPORT = apply_directional_run_compaction(
        stack, dose, targets_top, optical_model,
        ap_scale=int(source_scale),
        max_extra_de=float(globals().get("RUNTIME_RUN_COMPACT_MAX_EXTRA_DE", 0.0)),
        materials=str(globals().get("RUNTIME_RUN_COMPACT_MATERIALS", "R,Y,G,C,B")),
    )
    stats["run_compact_report"] = RUN_COMPACT_REPORT
    if RUN_COMPACT_REPORT.get("enabled"):
        print(f"[stack LUT] run compact: accepted {RUN_COMPACT_REPORT.get('accepted_swaps',0):,}/{RUN_COMPACT_REPORT.get('attempts',0):,} swaps; touched {RUN_COMPACT_REPORT.get('unique_cells_touched',0):,} AP cells; continuity delta {RUN_COMPACT_REPORT.get('scanline_continuity_delta',0):,}", file=sys.stderr, flush=True)

    PRECOMPUTED_DOSE_GRID = dose
    CANDIDATE_SELECTION_REPORT = stats
    selected_preview = pred_flat.reshape(ny, nx, 3).astype(np.float32, copy=False)

    display_stack_preview_out = globals().get("RUNTIME_DISPLAY_STACK_PREVIEW_OUT", None)
    if RUNTIME_STACK_PREVIEW_OUT is not None or display_stack_preview_out is not None or RUNTIME_LUT_STACK_DIFF_OUT is not None:
        raise RuntimeError(
            "3dprintv1.8 removed the stage-3 final-emission-stack preview/diff recomputation from the RGB-to-print path. "
            "Remove --stack-preview-out, --display-stack-preview-out, and --lut-stack-diff-out for this clean path."
        )

    # 3dprintv1.8 clean path: do not recompute a separate final-emission-stack
    # preview.  The main preview is the LUT-selected predicted RGB, expanded to
    # the RP grid only for display/metadata.  The emitted print stack above is
    # already final and is what the G-code compiler consumes.
    preview = np.repeat(np.repeat(selected_preview, source_scale, axis=0), source_scale, axis=1).astype(np.float32, copy=False)
    np.clip(preview, 0, 255, out=preview)

    DEMAND_STACK_PREVIEW_RGB = None
    DEMAND_PP_REFIT_STACK_PREVIEW_RGB = None
    DEMAND_LUT_STACK_DIFF_RGB = None
    DEMAND_LUT_STACK_DEBUG_REPORT = {
        "format": "fc3d_stack_lut_stage3_removed_v1",
        "cells": int(nx * ny),
        "source_scale": int(source_scale),
        "lut_kind": str(getattr(lookup, "lut_kind", "unknown")),
        "lut_script_version": str(getattr(lookup, "metadata", {}).get("script_version", "unknown")),
        "lut_model_name": str(getattr(lookup, "metadata", {}).get("model_name", "unknown")),
        "recipe_lut": str(getattr(lookup, "path", "")),
        "stage3_final_emission_stack_preview": "removed",
        "main_preview_uses": "selected LUT/cloud predicted RGB only",
        "print_stack_uses": "decoded selected recipe material+dose grid",
        "stack_resort_report": globals().get("STACK_RESORT_REPORT", {}),
        "run_compact_report": globals().get("RUN_COMPACT_REPORT", {}),
        "stack_scheduler_report": globals().get("STACK_SCHEDULER_REPORT", {}),
        "preview_white_expand": _preview_white_expand_report(lookup, globals().get("RUNTIME_PREVIEW_WHITE_EXPAND", "on")),
    }
    if RUNTIME_LUT_STACK_DEBUG_JSON is not None:
        Path(RUNTIME_LUT_STACK_DEBUG_JSON).write_text(json.dumps(DEMAND_LUT_STACK_DEBUG_REPORT, indent=2, sort_keys=True), encoding="utf-8")
        print(f"Wrote stack-LUT clean-path debug JSON: {RUNTIME_LUT_STACK_DEBUG_JSON}", flush=True)

    stats["preview_model"] = "stack_lut_selected_pred_rgb_or_lutmaker_cloud_predicted_rgb"
    stats["stack_preview_model"] = "removed_stage3_final_emission_stack_preview"
    stats["lut_stack_rms_rgb_error"] = None
    stats["lut_stack_max_abs_channel_error"] = None
    stats["preview_note"] = "3dprintv1.8 clean path: main preview is selected LUT/cloud predicted RGB; stage-3 final-emission-stack preview/diff recomputation is removed. Low-dose halftone conversion is disabled for dose-aware LUT paths."
    return stack, preview




def save_direct_mode_debug_preview(args, preview_top: Optional[np.ndarray]) -> None:
    """Direct-layer mode debug output is intentionally only the final preview."""
    if not getattr(args, "debug_package", False) or preview_top is None:
        return
    base = _debug_base_path(args)
    if base is None:
        return
    p = Path(base).with_name(Path(base).name + "_debug_direct_preview.png")
    Image.fromarray(_to_uint8_rgb(preview_top), "RGB").save(p)
    print(f"Wrote direct-layer debug preview: {p}", flush=True)



# ============================
# FC3D v1.15 config/manifests
# ============================

def _fc3d_config_flatten(d: Dict[str, object]) -> Dict[str, object]:
    """Flatten categorised FC3D JSON config to argparse dest names.

    Convention:
      config = instructions for a run
      manifest = record of what was produced / actually printed
    """
    if not isinstance(d, dict):
        raise RuntimeError("--config must be a JSON object")
    out: Dict[str, object] = {}
    alias = {
        # inputs
        "source_image": "image",
        "image": "image",
        "direct_layer_images": "direct_layer_images",
        "recipe_lut": "recipe_lut",
        "template_gcode_3mf": "template_gcode_3mf",
        "template_gcode": "template_gcode_3mf",
        # layers
        "aa_layer_image_prefix": "aa_layer_image_prefix",
        "aa_stack_npz_out": "aa_stack_npz_out",
        "layer_manifest_out": "layer_manifest_out",
        "layer_manifest_in": "layer_manifest_in",
        # calibration recipes
        "calibration_manifest_out": "calibration_manifest_out",
        "calibration_manifest_in": "calibration_manifest_in",
        # outputs
        "gcode_3mf": "output",
        "output": "output",
        "geometry_3mf": "geometry_3mf_out",
        "geometry_3mf_out": "geometry_3mf_out",
        "preview_image": "preview_image_out",
        "preview_image_out": "preview_image_out",
        "resolved_config": "resolved_config_out",
        "resolved_config_out": "resolved_config_out",
        "plain_gcode_out": "plain_gcode_out",
        "debug_package": "debug_package",
        # run/config
        "name": "run_name",
    }
    for section, val in d.items():
        if section in ("run", "inputs", "layers", "calibration_recipes", "print_options", "machine_options", "outputs", "extract_options", "npiter_options") and isinstance(val, dict):
            for k, v in val.items():
                if v == "":
                    v = None
                dest = alias.get(k, k).replace("-", "_")
                out[dest] = v
        else:
            # also allow simple flat config files
            if val == "":
                val = None
            dest = alias.get(section, section).replace("-", "_")
            out[dest] = val
    return out


def _fc3d_load_config_defaults(ap: argparse.ArgumentParser, config_path: Optional[Path]) -> Dict[str, object]:
    if config_path is None:
        return {}
    cfg_path = Path(config_path)
    cfg = json.loads(cfg_path.read_text(encoding="utf-8"))
    flat = _fc3d_config_flatten(cfg)
    actions = {a.dest: a for a in ap._actions if getattr(a, "dest", None)}
    defaults: Dict[str, object] = {}
    ignored: Dict[str, object] = {}
    for dest, val in flat.items():
        if dest not in actions:
            ignored[dest] = val
            continue
        action = actions[dest]
        if val is not None:
            try:
                if isinstance(action, argparse._StoreTrueAction):
                    val = bool(val)
                elif isinstance(action, argparse._StoreFalseAction):
                    val = not bool(val)
                elif getattr(action, "type", None) is not None and not isinstance(val, action.type):
                    val = action.type(val)
            except Exception:
                # Keep original; argparse/runtime validation will give a useful error if needed.
                pass
        defaults[dest] = val
    if defaults:
        ap.set_defaults(**defaults)
    if ignored:
        print("FC3D config ignored keys: " + json.dumps(ignored, sort_keys=True), flush=True)
    return {"config_path": str(cfg_path), "loaded_defaults": {k: str(v) if isinstance(v, Path) else v for k, v in defaults.items()}, "ignored": ignored}


def _fc3d_resolved_config_dict(args: argparse.Namespace, ap: argparse.ArgumentParser, config_report: Optional[Dict[str, object]] = None) -> Dict[str, object]:
    def val(name: str):
        v = getattr(args, name, None)
        if isinstance(v, Path):
            return str(v)
        return v
    return {
        "run": {
            "name": val("run_name") or (Path(str(val("output") or val("geometry_3mf_out") or val("preview_image_out") or "fc3d_run")).stem),
            "script": SCRIPT_VERSION,
            "print_run_id": (globals().get("PRINT_PROVENANCE_CONTEXT", {}) or {}).get("print_run_id"),
            "mode": "direct_layer" if val("direct_layer_images") else "image_to_gcode",
            "config_report": config_report or {},
        },
        "inputs": {
            "source_image": val("image"),
            "direct_layer_images": val("direct_layer_images"),
            "recipe_lut": val("recipe_lut"),
            "template_gcode_3mf": val("template_gcode_3mf"),
            "tile_manifest": val("tile_manifest_in"),
            "card_summary": val("card_summary_in"),
            "calibration_holdout_printed_tile_recipes": val("calibration_holdout_printed_tile_recipes"),
            "calibration_continuity_extracted_tiles": val("calibration_continuity_extracted_tiles"),
        },
        "layers": {
            "layer_order": "bottom_to_top",
            "aa_layer_image_prefix": val("aa_layer_image_prefix"),
            "aa_stack_npz_out": val("aa_stack_npz_out"),
            "layer_manifest_out": val("layer_manifest_out"),
        },
        "calibration_recipes": {
            "calibration_manifest_out": val("calibration_manifest_out"),
            "write_target_rgb": bool(val("calibration_manifest_out")),
            "write_selected_recipe": bool(val("calibration_manifest_out")),
            "write_predicted_rgb": bool(val("calibration_manifest_out")),
        },
        "print_options": {
            "rp_pitch_mm": val("rp_pitch_mm"),
            "print_width_mm": val("print_width_mm"),
            "preview_white_expand": val("preview_white_expand"),
            "error_diffusion": val("error_diffusion"),
            "edge_aa": val("edge_aa"),
            "lut_bucket_choice": val("lut_bucket_choice"),
            "lut_candidate_rank": val("lut_candidate_rank"),
            "lut_bucket_choice_count": val("lut_bucket_choice_count"),
            "lut_existing_history_bonus_de": val("lut_existing_history_bonus_de"),
            "lut_existing_history_bonus_scale_de": val("lut_existing_history_bonus_scale_de"),
            "lut_generated_ve_penalty_de": val("lut_generated_ve_penalty_de"),
            "lut_generated_ve_penalty_scale": val("lut_generated_ve_penalty_scale"),
            "calibration_holdout_fraction": val("calibration_holdout_fraction"),
            "calibration_holdout_seed": val("calibration_holdout_seed"),
            "calibration_continuity_bonus_de": val("calibration_continuity_bonus_de"),
            "calibration_continuity_scale_de": val("calibration_continuity_scale_de"),
            "calibration_continuity_hold_below_de": val("calibration_continuity_hold_below_de"),
            "stack_scheduler": val("stack_scheduler"),
            "stack_resort": val("stack_resort"),
            "run_compact_max_extra_de": val("run_compact_max_extra_de"),
            "endpoint_trim_mm": val("endpoint_trim_mm"),
            "direct_test_scanline_transition": val("direct_test_scanline_transition"),
            "direct_test_pressure_chain_scope": val("direct_test_pressure_chain_scope"),
            "material_draw_order_mode": val("material_draw_order_mode"),
            "skip_absent_layer_materials": val("skip_absent_layer_materials"),
            "directional_join_gap_mm": val("directional_join_gap_mm"),
        },
        "machine_options": {
            "tower_slot_mode": val("tower_slot_mode"),
            "tower_fill_unused_slots": val("tower_fill_unused_slots"),
            "h2c_toolchange_lift_mm": val("h2c_toolchange_lift_mm"),
            "h2c_machine_prime_xy_mode": val("h2c_machine_prime_xy_mode"),
            "h2c_standby_temp": val("h2c_standby_temp"),
        },
        "outputs": {
            "gcode_3mf": val("output"),
            "geometry_3mf": val("geometry_3mf_out"),
            "preview_image": val("preview_image_out"),
            "plain_gcode_out": val("plain_gcode_out"),
            "resolved_config": val("resolved_config_out"),
            "debug_package": bool(val("debug_package")),
            "printed_tile_recipes": val("printed_tile_recipes_out"),
            "print_bundle": val("print_bundle_out"),
        },
        "provenance": globals().get("PRINT_PROVENANCE_CONTEXT", {}) or {},
    }


def _write_resolved_config(args: argparse.Namespace, ap: argparse.ArgumentParser, config_report: Optional[Dict[str, object]]) -> None:
    p = getattr(args, "resolved_config_out", None)
    if p is None:
        return
    p = Path(p)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(_fc3d_resolved_config_dict(args, ap, config_report), indent=2, sort_keys=True), encoding="utf-8")
    print(f"Wrote resolved config: {p}", flush=True)


def _layer_manifest_sheet_path_from_prefix(prefix: Path, stage: str) -> str:
    stage_part = f"_{stage}" if stage else ""
    return str(prefix.with_name(f"{prefix.name}{stage_part}_layers_4x2_sheet.png"))


def write_layer_manifest(
    path: Path,
    prefix: Path,
    stage: str,
    stack: Optional[np.ndarray],
    args: argparse.Namespace,
    dose_grid: Optional[np.ndarray] = None,
) -> None:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    h = int(stack.shape[0]) if stack is not None else 0
    w = int(stack.shape[1]) if stack is not None else 0
    layers = int(stack.shape[2]) if stack is not None and stack.ndim == 3 else MIX_LAYERS
    dose_available = bool(dose_grid is not None and stack is not None and np.asarray(dose_grid).shape == stack.shape)
    data = {
        "manifest_version": "fc3d_layer_manifest_v4",
        "script_version": PP_VERSION,
        "layer_order": "bottom_to_top",
        "stage": stage,
        "grid_size_rp_px": [w, h],
        "rp_pitch_mm": float(getattr(args, "rp_pitch_mm", RUNTIME_RP_PITCH_MM)),
        "print_width_mm": float(getattr(args, "print_width_mm", RUNTIME_PRINT_WIDTH_MM)),
        "source_scale": int(globals().get("RUNTIME_PIXEL_HEAD_WIDTH", 1)),
        "layer_image_encoding": "rgba_material_rgb_alpha_128_equals_100pct_dose" if dose_available else "rgb_material_only_no_dose",
        "alpha_dose_policy": {
            "enabled": dose_available,
            "alpha_0": "empty/no optical material",
            "alpha_128": "100 percent extrusion dose",
            "alpha_formula": "round(dose_multiplier * 128), clipped 1..255 for active pixels",
        },
        "layer_sheet_4x2": {
            "path": _layer_manifest_sheet_path_from_prefix(Path(prefix), stage),
            "layout": [[1, 2, 3, 4], [5, 6, 7, 8]],
            "preserves_individual_layer_resolution": True,
            "panel_count": int(layers),
            "panel_grid": [4, 2],
            "panel_order": "bottom_to_top_left_to_right_then_top_to_bottom_rows",
        },
        "notes": [
            "layer_01_bottom is the lowest optical layer above the solid W base.",
            "layer_08_top is the highest/top optical layer.",
            "v4 manifests use a single dose-preserving RGBA layer sheet suitable for extractphase direct-layer recipe reconstruction.",
            "layer_sheet_4x2 is the canonical output, laid out 1,2,3,4 / 5,6,7,8.",
        ],
    }
    path.write_text(json.dumps(data, indent=2, sort_keys=True), encoding="utf-8")
    print(f"Wrote layer manifest: {path}", flush=True)


def _manifest_token(mat: object, dose: float) -> str:
    m = str(mat).upper()
    if m in ("", EMPTY_MAT, ".", "NONE") or float(dose) <= 0.0:
        return "."
    pct = int(round(float(dose) * 100.0))
    return f"{m}{pct}"


def write_calibration_manifest(path: Path, stack: np.ndarray, dose: Optional[np.ndarray], args: argparse.Namespace, lookup: Optional[RecipeLookup]) -> None:
    """Write one row per AP/source cell using the actual final selected stack.

    This is the recipe truth for closed-loop calibration cards generated through 3dprint.
    It deliberately samples the final emitted stack/dose grid, so scheduler/resort/compaction
    effects are reflected if enabled.
    """
    if stack is None:
        return
    import csv as _csv
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    h_rp, w_rp, layers = stack.shape
    source_scale = max(1, int(globals().get("RUNTIME_PIXEL_HEAD_WIDTH", 1)))
    ny = h_rp // source_scale
    nx = w_rp // source_scale
    target = globals().get("PRECOMPUTED_CELL_TARGET_RGB_TOP", None)
    grid_idx = globals().get("PRECOMPUTED_CELL_GRID_INDEX", None)
    recipe_idx = globals().get("PRECOMPUTED_CELL_RECIPE_INDEX", None)
    pred = globals().get("PRECOMPUTED_CELL_PRED_RGB_TOP", None)
    de = globals().get("PRECOMPUTED_CELL_SELECTED_DELTAE", None)
    score = globals().get("PRECOMPUTED_CELL_SELECTED_SCORE", None)
    continuity = globals().get("PRECOMPUTED_CELL_CONTINUITY", None)
    continuity_applied = globals().get("PRECOMPUTED_CELL_CONTINUITY_APPLIED", None)
    continuity_measured_de = globals().get("PRECOMPUTED_CELL_CONTINUITY_MEASURED_DE", None)
    fields = [
        "script_version", "row_type", "cell_x", "cell_y", "grid_w", "grid_h", "source_scale", "rp_pitch_mm", "print_width_mm",
        "target_R", "target_G", "target_B", "predicted_R", "predicted_G", "predicted_B",
        "target_grid_index", "selected_recipe_index", "candidate_delta_e76", "candidate_score",
        "continuity_retained_previous", "continuity_applied", "continuity_measured_delta_e76",
    ]
    for li in range(layers):
        fields.append("layer_01_bottom" if li == 0 else "layer_08_top" if li == layers - 1 else f"layer_{li+1:02d}")
    fields += ["recipe_stack_bottom_to_top", "recipe_stack_top_to_bottom"]
    with path.open("w", newline="", encoding="utf-8") as f:
        wr = _csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")
        wr.writeheader()
        for cy in range(ny):
            y_model = h_rp - 1 - (cy * source_scale)
            for cx in range(nx):
                x_model = cx * source_scale
                toks = []
                row: Dict[str, object] = {
                    "script_version": SCRIPT_VERSION,
                    "row_type": "cell",
                    "cell_x": int(cx),
                    "cell_y": int(cy),
                    "grid_w": int(nx),
                    "grid_h": int(ny),
                    "source_scale": int(source_scale),
                    "rp_pitch_mm": float(getattr(args, "rp_pitch_mm", RUNTIME_RP_PITCH_MM)),
                    "print_width_mm": float(getattr(args, "print_width_mm", RUNTIME_PRINT_WIDTH_MM)),
                    "target_grid_index": int(grid_idx[cy, cx]) if grid_idx is not None and cy < grid_idx.shape[0] and cx < grid_idx.shape[1] else "",
                    "selected_recipe_index": int(recipe_idx[cy, cx]) if recipe_idx is not None and cy < recipe_idx.shape[0] and cx < recipe_idx.shape[1] else "",
                    "candidate_delta_e76": float(de[cy, cx]) if de is not None and cy < de.shape[0] and cx < de.shape[1] and np.isfinite(de[cy, cx]) else "",
                    "candidate_score": float(score[cy, cx]) if score is not None and cy < score.shape[0] and cx < score.shape[1] and np.isfinite(score[cy, cx]) else "",
                    "continuity_retained_previous": int(bool(continuity[cy, cx])) if continuity is not None else 0,
                    "continuity_applied": int(bool(continuity_applied[cy, cx])) if continuity_applied is not None else 0,
                    "continuity_measured_delta_e76": float(continuity_measured_de[cy, cx]) if continuity_measured_de is not None and np.isfinite(continuity_measured_de[cy, cx]) else "",
                }
                if target is not None and cy < target.shape[0] and cx < target.shape[1]:
                    row.update({"target_R": float(target[cy, cx, 0]), "target_G": float(target[cy, cx, 1]), "target_B": float(target[cy, cx, 2])})
                else:
                    row.update({"target_R": "", "target_G": "", "target_B": ""})
                if pred is not None and cy < pred.shape[0] and cx < pred.shape[1]:
                    row.update({"predicted_R": float(pred[cy, cx, 0]), "predicted_G": float(pred[cy, cx, 1]), "predicted_B": float(pred[cy, cx, 2])})
                else:
                    row.update({"predicted_R": "", "predicted_G": "", "predicted_B": ""})
                for li in range(layers):
                    tok = _manifest_token(stack[y_model, x_model, li], 0.0 if dose is None else float(dose[y_model, x_model, li]))
                    toks.append(tok)
                    key = "layer_01_bottom" if li == 0 else "layer_08_top" if li == layers - 1 else f"layer_{li+1:02d}"
                    row[key] = tok
                row["recipe_stack_bottom_to_top"] = " ".join(toks)
                row["recipe_stack_top_to_bottom"] = " ".join(reversed(toks))
                wr.writerow(row)
    print(f"Wrote calibration recipe manifest: {path} cells={nx*ny:,}", flush=True)


def _resolve_card_direct_layer_input(args: argparse.Namespace) -> None:
    """Map a hashed card package onto the existing direct-layer input.

    ``fc3d_card_v1`` remains the immutable 4x2 / 3427-recipe calibration-card
    contract. ``fc3d_direct_testcard_v1`` is the deliberately smaller 4x4
    normal/filter experiment contract. Both schemas use the same --card entry
    point, but only the former enables the legacy extraction provenance bundle.
    """
    card_arg = getattr(args, "card", None)
    if card_arg is None:
        return
    if args.image is not None or args.direct_layer_images is not None:
        raise RuntimeError("--card cannot be combined with --image or --direct-layer-images")

    card_path = Path(card_arg).resolve()
    if not card_path.is_file():
        raise RuntimeError(f"card JSON does not exist: {card_path}")
    try:
        card = json.loads(card_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError(f"could not read card JSON {card_path}: {exc}") from exc
    schema = str(card.get("schema_version", "")).strip()
    if schema not in {"fc3d_card_v1", "fc3d_direct_testcard_v1"}:
        raise RuntimeError(
            f"unsupported card schema in {card_path}: {schema!r}; expected "
            "'fc3d_card_v1' or 'fc3d_direct_testcard_v1'"
        )
    files = card.get("files")
    if not isinstance(files, dict):
        raise RuntimeError(f"card JSON has no files object: {card_path}")

    def resolve_record(key: str) -> Path:
        rec = files.get(key)
        if not isinstance(rec, dict) or not rec.get("path"):
            raise RuntimeError(f"card JSON is missing files.{key}.path: {card_path}")
        path = (card_path.parent / str(rec["path"])).resolve()
        if not path.is_file():
            raise RuntimeError(f"card files.{key} does not exist: {path}")
        expected_hash = str(rec.get("sha256", "")).strip().lower()
        if expected_hash:
            actual_hash = _sha256_file(path)
            if actual_hash.lower() != expected_hash:
                raise RuntimeError(
                    f"card files.{key} SHA-256 mismatch: {path}; "
                    f"expected {expected_hash}, got {actual_hash}"
                )
        return path

    layer_manifest_path = resolve_record("layer_manifest")
    layer_sheet_path = resolve_record("layer_sheet")
    tile_manifest_path = resolve_record("tile_manifest")
    card_summary_path = resolve_record("card_summary")
    try:
        layer_manifest = json.loads(layer_manifest_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError(f"could not read card layer manifest {layer_manifest_path}: {exc}") from exc
    if layer_manifest.get("layer_order") != "bottom_to_top":
        raise RuntimeError(f"card layer manifest must declare bottom_to_top order: {layer_manifest_path}")
    stem = card_path.stem
    parent = card_path.parent
    if schema == "fc3d_card_v1":
        if str(getattr(args, "direct_layout", "4x2")) != "4x2":
            raise RuntimeError("fc3d_card_v1 manifests are fixed 4x2 direct-layer cards")
        source_manifest_path = resolve_record("source_manifest")
        if int(layer_manifest.get("layer_count", 0)) != MIX_LAYERS:
            raise RuntimeError(f"card layer manifest must contain {MIX_LAYERS} optical layers: {layer_manifest_path}")
        sheet = layer_manifest.get("layer_sheet_4x2")
        if not isinstance(sheet, dict) or not sheet.get("path"):
            raise RuntimeError(f"card layer manifest has no layer_sheet_4x2.path: {layer_manifest_path}")
        manifest_sheet_path = (layer_manifest_path.parent / str(sheet["path"])).resolve()
        if manifest_sheet_path != layer_sheet_path:
            raise RuntimeError(
                "card JSON and layer manifest reference different layer sheets: "
                f"{layer_sheet_path} != {manifest_sheet_path}"
            )
        expected_layout = [[1, 2, 3, 4], [5, 6, 7, 8]]
        if sheet.get("layout") != expected_layout:
            raise RuntimeError(f"card layer sheet layout must be {expected_layout}: {layer_manifest_path}")

        # The established permanent-card provenance path remains unchanged.
        args.direct_layer_images = str(layer_sheet_path)
        args.direct_layout = "4x2"
        args.tile_manifest_in = tile_manifest_path
        args.card_summary_in = card_summary_path
        args.resolved_config_out = args.resolved_config_out or (parent / f"{stem}{EMITTER_FILE_SUFFIX}_print_config.json")
        args.layer_manifest_out = args.layer_manifest_out or (parent / f"{stem}{EMITTER_FILE_SUFFIX}_printed_layers.json")
        args.printed_tile_recipes_out = args.printed_tile_recipes_out or (parent / f"{stem}{EMITTER_FILE_SUFFIX}_printed_tiles.csv")
        args.preview_image_out = args.preview_image_out or (parent / f"{stem}{EMITTER_FILE_SUFFIX}_printed_preview.png")
        args.print_bundle_out = args.print_bundle_out or (parent / f"{stem}{EMITTER_FILE_SUFFIX}_print_bundle.json")
        args.rp_pitch_mm = 0.20
        args.print_width_mm = 0.40
        args._card_source_manifest_path = source_manifest_path
        card_mode_label = "calibration 4x2"
    else:
        if "layout_preview" in files:
            resolve_record("layout_preview")
        direct_print = card.get("direct_print")
        if not isinstance(direct_print, dict):
            raise RuntimeError(f"direct test-card JSON has no direct_print object: {card_path}")
        if str(direct_print.get("layout", "")).strip().lower() != "4x4":
            raise RuntimeError(f"fc3d_direct_testcard_v1 requires direct_print.layout='4x4': {card_path}")
        rp_pitch_mm = float(direct_print.get("rp_pitch_mm", 0.0))
        print_width_mm = float(direct_print.get("print_width_mm", 0.0))
        if rp_pitch_mm <= 0.0 or print_width_mm <= 0.0:
            raise RuntimeError(f"direct test-card RP pitch and print width must be positive: {card_path}")
        if layer_manifest.get("manifest_version") != "fc3d_direct_layer_manifest_v1":
            raise RuntimeError(
                f"unsupported direct test-card layer manifest {layer_manifest.get('manifest_version')!r}: "
                f"{layer_manifest_path}"
            )
        if int(layer_manifest.get("logical_layer_capacity", 0)) != MIX_LAYERS:
            raise RuntimeError(
                f"direct test-card layer manifest must declare logical_layer_capacity={MIX_LAYERS}: "
                f"{layer_manifest_path}"
            )
        active_layers = int(layer_manifest.get("active_logical_layers", 0))
        if not (1 <= active_layers <= MIX_LAYERS):
            raise RuntimeError(
                f"direct test-card active_logical_layers must be 1..{MIX_LAYERS}: {layer_manifest_path}"
            )
        if int(direct_print.get("active_logical_layers", 0)) != active_layers:
            raise RuntimeError(
                "direct test-card JSON and layer manifest disagree on active_logical_layers: "
                f"{direct_print.get('active_logical_layers')!r} != {active_layers}"
            )
        sheet = layer_manifest.get("layer_sheet_4x4")
        if not isinstance(sheet, dict) or not sheet.get("path"):
            raise RuntimeError(f"direct test-card layer manifest has no layer_sheet_4x4.path: {layer_manifest_path}")
        manifest_sheet_path = (layer_manifest_path.parent / str(sheet["path"])).resolve()
        if manifest_sheet_path != layer_sheet_path:
            raise RuntimeError(
                "card JSON and layer manifest reference different layer sheets: "
                f"{layer_sheet_path} != {manifest_sheet_path}"
            )
        expected_layout = [
            [f"L{2 * row + (col // 2) + 1}_{'normal' if col % 2 == 0 else 'filter'}" for col in range(4)]
            for row in range(4)
        ]
        if sheet.get("layout") != expected_layout:
            raise RuntimeError(f"direct test-card layer sheet layout must be {expected_layout}: {layer_manifest_path}")
        manifest_hash = str(sheet.get("sha256", "")).strip().lower()
        if manifest_hash and _sha256_file(layer_sheet_path).lower() != manifest_hash:
            raise RuntimeError(f"direct test-card layer manifest sheet SHA-256 mismatch: {layer_sheet_path}")
        _sheet_w, _sheet_h = _direct_layer_image_size(layer_sheet_path)
        if (_sheet_w % 4) != 0 or (_sheet_h % 4) != 0:
            raise RuntimeError(f"direct test-card 4x4 sheet dimensions are invalid: {_sheet_w}x{_sheet_h}")
        _raw_zoffset_profiles = direct_print.get("zoffset_print_profiles")
        if _raw_zoffset_profiles is None:
            _raw_zoffset_profiles = direct_print.get("zoffset_height_adjustment")
        args._direct_zoffset_height_adjustment = _normalise_direct_zoffset_height_adjustment(
            _raw_zoffset_profiles,
            _sheet_h // 4,
            _sheet_w // 4,
        )

        # 4x4 card mode is an ergonomic, hashed wrapper around the validated
        # paired direct-sheet implementation. It deliberately does not enable
        # the old 3427-tile extraction/provenance outputs, whose data model has
        # no representation for same-Z filters or per-pixel carrier height.
        args.direct_layer_images = str(layer_sheet_path)
        args.direct_layout = "4x4"
        args.tile_manifest_in = tile_manifest_path
        args.card_summary_in = card_summary_path
        args.resolved_config_out = args.resolved_config_out or (parent / f"{stem}{EMITTER_FILE_SUFFIX}_print_config.json")
        args.preview_image_out = args.preview_image_out or (parent / f"{stem}{EMITTER_FILE_SUFFIX}_printed_preview.png")
        args.rp_pitch_mm = rp_pitch_mm
        args.print_width_mm = print_width_mm
        args._card_source_manifest_path = tile_manifest_path
        card_mode_label = f"direct test 4x4, active logical layers={active_layers}"

    # Both schemas are complete direct-print instructions. Keep all front-end
    # recipe selection, AA, diffusion, reordering, gap closing and ironing off.
    if args.output is None and args.geometry_3mf_out is None and not bool(args.preview_only):
        args.output = parent / f"{stem}{EMITTER_FILE_SUFFIX}.gcode.3mf"
    if args.run_name is None:
        args.run_name = stem
    args.directional_join_gap_mm = 0.0
    # Keep endpoint compensation explicitly user-controlled.  Earlier card mode
    # silently replaced every parsed CLI value with 0.025 mm, which made an
    # explicit --endpoint-trim-mm override ineffective.  The parser default is
    # already the established 0.025 mm, so no card-specific assignment is needed.
    args.error_diffusion = "none"
    args.edge_aa = "off"
    args.candidate_choice = "off"
    args.stack_resort = "off"
    args.stack_scheduler = "off"
    args.run_compact_max_extra_de = 0.0
    args.close_gaps_mm = 0.0
    args.ironing_layers = ""
    args.add_corner_colour_tiles = False

    # Retain these resolved source paths for direct-card provenance.  They are
    # deliberately private attributes and are not additional CLI options.
    args._card_json_path = card_path
    args._card_layer_manifest_path = layer_manifest_path
    args._card_layer_sheet_path = layer_sheet_path
    args._card_schema_version = schema
    print(
        f"Card mode ({card_mode_label}): {card_path.name} -> {layer_sheet_path.name} -> "
        f"{args.output if args.output is not None else 'non-G-code output'}",
        flush=True,
    )


def main():
    pre_ap = argparse.ArgumentParser(add_help=False)
    pre_ap.add_argument("--config", type=Path, default=None, help="JSON run config/options manifest. Command-line values override config defaults.")
    pre_args, _pre_remaining = pre_ap.parse_known_args()
    ap=argparse.ArgumentParser(parents=[pre_ap])
    ap.add_argument("--card", required=False, type=Path,
                    help="Card JSON whose hashed layer sheet is printed through the direct-layer path. Supports established fc3d_card_v1 4x2 calibration cards and fc3d_direct_testcard_v1 4x4 normal/filter cards.")
    ap.add_argument("--image", required=False, type=Path,
                    help="Source RGB image for normal LUT/picture mode. Not required with --direct-layer-images.")
    ap.add_argument("--direct-layer-images", default=None,
                    help="Comma-separated 1..8 direct-layer images in physical bottom-to-top order. Legacy PNG uses uint8 RGBA with alpha 128=100%% VE. Float TIFF uses normalized float32 RGBA with alpha equal to the exact VE fraction (A=1.0 is 100%%). RGB encodes W/F/R/Y/G/C/B. Base is always solid W. Bypasses RGB->recipe lookup, candidate selection, AA, and error diffusion.")
    ap.add_argument("--direct-layout", "--dl", dest="direct_layout", choices=["4x2", "4x4"], default="4x2",
                    help="Combined direct-sheet layout. 4x2 preserves layers 1..8. 4x4 reads row-major normal/filter pairs and emits each filter at the same Z as its normal layer. Default 4x2.")
    ap.add_argument("--max-physical-slots", type=int, default=8,
                    help="Maximum optical/material slots for shared demand-map packing. Default 8. Lower values are supported for tests; >8 is experimental and template/metadata dependent.")
    ap.add_argument("--progress", choices=["auto", "on", "off"], default="auto",
                    help="Print periodic progress for long demand-LUT/direct-demand stages. auto prints on interactive stderr; on always prints; off disables. Default auto.")
    ap.add_argument("--progress-interval-sec", type=float, default=2.0,
                    help="Minimum seconds between progress updates. Default 2.0.")
    ap.add_argument("--audit", action="store_true",
                    help="Run the four slow final full-G-code parser audits. Default off.")
    ap.add_argument("--time-estimate-first-use-tool-sec", type=float, default=DEFAULT_TIME_ESTIMATE_FIRST_USE_TOOL_SEC,
                    help="First-use H2C head/tool activation phase time in seconds. Measured default 135.")
    ap.add_argument("--time-estimate-tool-activation-sec", type=float, default=DEFAULT_TIME_ESTIMATE_TOOL_ACTIVATION_SEC,
                    help="Legacy flat repeat activation time/fallback in seconds. Used when --time-estimate-swap-model flat or transition is unknown. Default 57.")
    ap.add_argument("--time-estimate-swap-model", choices=["flat", "transition"], default="transition",
                    help="H2C repeat activation timing model. transition uses previous/target physical head; flat uses --time-estimate-tool-activation-sec for all repeats. Default transition.")
    ap.add_argument("--time-estimate-repeat-right-to-left-sec", type=float, default=DEFAULT_TIME_ESTIMATE_REPEAT_RIGHT_TO_LEFT_SEC,
                    help="Measured repeat activation time for right-head material/tool to left-head W. Default 20.")
    ap.add_argument("--time-estimate-repeat-left-to-right-sec", type=float, default=DEFAULT_TIME_ESTIMATE_REPEAT_LEFT_TO_RIGHT_SEC,
                    help="Measured repeat activation time for left-head W to right-head material/tool. Default 53.")
    ap.add_argument("--time-estimate-repeat-right-to-right-sec", type=float, default=DEFAULT_TIME_ESTIMATE_REPEAT_RIGHT_TO_RIGHT_SEC,
                    help="Measured repeat activation time for one right-head material/tool to another right-head material/tool. Default 39.")
    ap.add_argument("--time-estimate-repeat-left-to-left-sec", type=float, default=DEFAULT_TIME_ESTIMATE_REPEAT_LEFT_TO_LEFT_SEC,
                    help="Fallback repeat activation time for left-head to left-head. Rare for current W-only-left jobs. Default 20.")
    ap.add_argument("--time-estimate-motion-model", choices=["naive", "accel"], default="accel",
                    help="Motion time model outside activation blocks. naive=distance/feedrate; accel=triangle/trapezoid acceleration model with simple junction carry. Default accel.")
    ap.add_argument("--time-estimate-default-print-accel-mm-s2", type=float, default=DEFAULT_TIME_ESTIMATE_DEFAULT_PRINT_ACCEL_MM_S2,
                    help="Default print acceleration for estimator until M204 overrides it. Default 8000.")
    ap.add_argument("--time-estimate-default-travel-accel-mm-s2", type=float, default=DEFAULT_TIME_ESTIMATE_DEFAULT_TRAVEL_ACCEL_MM_S2,
                    help="Default travel acceleration for estimator until M204 overrides it. Default 9000.")
    ap.add_argument("--time-estimate-default-retract-accel-mm-s2", type=float, default=DEFAULT_TIME_ESTIMATE_DEFAULT_RETRACT_ACCEL_MM_S2,
                    help="Default retract/E acceleration for estimator until M204/M201 overrides it. Default 5000.")
    ap.add_argument("--time-estimate-default-junction-speed-mm-s", type=float, default=DEFAULT_TIME_ESTIMATE_DEFAULT_JUNCTION_SPEED_MM_S,
                    help="Default XY junction/jerk speed for estimator until M205 X/Y overrides it. Default 9.")
    ap.add_argument("--time-estimate-fixed-overhead-sec", type=float, default=DEFAULT_TIME_ESTIMATE_FIXED_OVERHEAD_SEC,
                    help="Extra fixed overhead added to the PPSP ball-park time estimate. Default 0 seconds until calibrated.")
    ap.add_argument("--template-gcode-3mf", type=Path, default=None, help="Optional explicit H2C package override used only for package metadata/repacking. Normal v1.57 generation uses the embedded validated package skeleton and never reads reference model G-code.")
    ap.add_argument("--output", type=Path, default=None)
    ap.add_argument("--run-name", default=None, help="Optional human-readable run name used in resolved config metadata.")
    ap.add_argument("--resolved-config-out", type=Path, default=None, help="Write final resolved categorised config JSON after config+CLI overrides.")
    ap.add_argument("--layer-manifest-out", type=Path, default=None, help="Write JSON manifest listing produced bottom-to-top layer debug PNGs.")
    ap.add_argument("--calibration-manifest-out", type=Path, default=None, help="Write CSV manifest of actual selected bottom-to-top recipe stack per AP/source cell.")
    ap.add_argument("--tile-manifest-in", type=Path, default=None, help="Card tile manifest used to generate the compact authoritative printed-tile recipe map.")
    ap.add_argument("--card-summary-in", type=Path, default=None, help="Card-generator summary JSON to bind into the print provenance bundle.")
    ap.add_argument("--printed-tile-recipes-out", type=Path, default=None, help="Write the compact per-tile actual recipe map from the final emitted stack/dose grid.")
    ap.add_argument("--print-bundle-out", type=Path, default=None, help="Write the immutable hashed print provenance bundle consumed by ExtractPhase2.")
    ap.add_argument("--calibration-holdout-printed-tile-recipes", type=Path, default=None, help="Previous authoritative printed-tile map whose exact recipes may be repeated as a fixed calibration holdout.")
    ap.add_argument("--calibration-holdout-fraction", type=float, default=0.0, help="Deterministic fraction of recipe tiles to repeat exactly from the previous map. Use 0.25 for the convergence holdout; default 0 disables it.")
    ap.add_argument("--calibration-holdout-seed", default="fc3d-fixed-holdout-v1", help="Stable seed used to choose holdout print keys. Keep unchanged across rounds.")
    ap.add_argument("--calibration-continuity-extracted-tiles", type=Path, default=None, help="Previous round's validated combined Phase2 tiles CSV. Softly favours that exact previous tile recipe only where measured NP-to-3DP error was already low; this is not a fixed holdout.")
    ap.add_argument("--calibration-continuity-bonus-de", type=float, default=1.0, help="Maximum soft DeltaE score bonus for retaining the exact previous tile recipe at zero measured error. Default 1.0.")
    ap.add_argument("--calibration-continuity-scale-de", type=float, default=3.0, help="Measured NP-to-3DP DeltaE decay scale for the previous-tile continuity bonus. Bonus uses exp(-(error/scale)^2); default 3.0.")
    ap.add_argument("--calibration-continuity-hold-below-de", type=float, default=0.0, help="Hard-retain the previous printed recipe when its measured NP-to-3DP DeltaE is below this threshold and the exact recipe remains in the current safe LUT cloud. Zero disables. Use 10 for a low-error convergence hold while continuing to update the high-error tail.")
    ap.add_argument("--lut-existing-history-bonus-de", type=float, default=None, help="Optional runtime override for the LUT-embedded global exact-history score bonus. Default uses the value stored in the LUT.")
    ap.add_argument("--lut-existing-history-bonus-scale-de", type=float, default=None, help="Optional runtime override for the exact-history bonus decay scale.")
    ap.add_argument("--lut-generated-ve-penalty-de", type=float, default=None, help="Optional runtime override for the calm-region generated-VE score penalty.")
    ap.add_argument("--lut-generated-ve-penalty-scale", type=float, default=None, help="Optional runtime override for generated-VE movement scaling.")
    ap.add_argument("--geometry-3mf-out", type=Path, default=None, help="Write a diagnostic slicer-input .3mf with six labelled material objects W/F/R/Y/G/C/B using the same LUT recipe plan. This is a normal geometry 3MF, not a .gcode.3mf.")
    ap.add_argument("--center-x", type=float, default=DEFAULT_CENTER_X)
    ap.add_argument("--center-y", type=float, default=DEFAULT_CENTER_Y)
    ap.add_argument("--tool-map-json", default=None)
    ap.add_argument("--filament-assignment-json", default=None, help="Friendly logical-material to installed-filament mapping, e.g. {\"W\":\"PLA:W\",\"B\":\"PLA:C\"}. Automatically sets both polymer profile and physical H2C slot. Unspecified logical colours use the current PETG defaults. --tool-map-json, if supplied, remains the final explicit tool-map override.")
    ap.add_argument("--plain-gcode-out", type=Path)
    ap.add_argument("--recipe-lut", type=Path, default=None, help="Required recipe LUT .npz. Supports recipegenv64 stack LUTs and lutmakerv1.0 hybrid LUTs.")
    ap.add_argument("--calibration-params-file", type=Path, default=None, help="Stack-LUT exact previews: load the calibration params JSON so PP uses the same RGBCYWF optical constants as recipegen. If omitted, PP falls back to LUT metadata calibration_state, then internal defaults.")
    ap.add_argument("--lookup-space", choices=["rgb"], default="rgb", help="RGB-only in ppv32; kept for command compatibility.")



    ap.add_argument("--preview-image-out", type=Path, default=None, help="Write a predicted-print preview image using the same 0.40 mm image-native LUT lookup path as printing.")
    ap.add_argument("--pre-aa-mapped-preview-out", type=Path, default=None, help="Write RP-stack mapped preview before boundary AA, using the same stack-to-RGB path as final preview.")
    ap.add_argument("--stack-preview-out", type=Path, default=None, help="Removed in 3dprintv1.8 clean path: exact final-emission-stack preview recomputation is no longer available.")
    ap.add_argument("--display-stack-preview-out", type=Path, default=None, help="Removed in 3dprintv1.8 clean path: display stack preview is no longer available because stage-3 stack preview was removed.")
    ap.add_argument("--preview-white-expand", choices=["on", "off"], default="on", help="Display-only preview correction: output/metadata previews are expanded from measured printable white to normal 255 display white. Stage-3 exact stack preview was removed in 3dprintv1.8. Default on.")
    ap.add_argument("--direct-layer-preview-mode", choices=["diagnostic", "calibrated-model", "reverse-lookup"], default="diagnostic", help="Direct-layer preview source. diagnostic keeps the old order/dose visualiser. calibrated-model uses the shared lutmaker forward predictor from --recipe-lut. reverse-lookup validates exact canonical recipe -> RGB entries from --direct-layer-reverse-rgb-csv.")
    ap.add_argument("--direct-layer-reverse-rgb-csv", default=None, help="CSV mapping canonical recipe/optical key to expected RGB for --direct-layer-preview-mode reverse-lookup.")
    ap.add_argument("--direct-layer-card-manifest-csv", default=None, help="Optional card tile manifest CSV. In reverse-lookup mode, validate every manifest recipe has an exact reverse-LUT entry and matching expected RGB.")
    ap.add_argument("--direct-layer-reverse-lookup-missing-policy", choices=["fail", "magenta"], default="fail", help="What to do if a direct-layer stack is missing from the reverse lookup. Default fail because this mode is intended to validate LUT integrity.")
    ap.add_argument("--direct-layer-reverse-audit-tolerance-rgb", type=float, default=1.0, help="Maximum per-channel RGB delta allowed when comparing reverse lookup RGB to card manifest expected RGB.")
    ap.add_argument("--direct-layer-reverse-audit-fail", choices=["on", "off"], default="on", help="Fail the run if reverse lookup is missing manifest keys or differs from manifest expected RGB beyond tolerance.")
    ap.add_argument("--lut-stack-diff-out", type=Path, default=None, help="Removed in 3dprintv1.8 clean path: LUT-vs-final-stack diff preview is no longer available because stage-3 stack preview was removed.")
    ap.add_argument("--pp-refit-stack-preview-out", type=Path, default=None, help="Removed. Passing this option raises an error; exact final-emission stack preview was also removed from the clean path in 3dprintv1.8.")
    ap.add_argument("--lut-stack-debug-json", type=Path, default=None, help="Stack-LUT only: write JSON comparing LUT selected_pred_rgb to the exact emitted stack preview, including worst cells and slot modes.")
    ap.add_argument("--aa-layer-image-prefix", type=Path, default=None, help="Optional prefix for 8 RP-stack material layer debug PNGs after boundary AA.")
    ap.add_argument("--aa-stack-npz-out", type=Path, default=None, help="Write exact pre/post-AA RP stack symbols as uint8 material IDs plus reconstructed RGB previews and self-check metadata.")
    ap.add_argument("--debug-package", action="store_true", help="Write full debug package: source image, pre/post-AA reconstructed previews, pre/post-AA layer PNGs, stack NPZ, and self-check JSONs. Default off.")
    ap.add_argument("--preview-only", action="store_true", help="Only write --preview-image-out; do not generate a .gcode.3mf.")
    ap.add_argument("--error-diffusion", choices=["none", "blue-noise", "recipe-aware"], default="none", help="Optional LUT-space residual diffusion. 'blue-noise' is the older RGB-space diffusion. 'recipe-aware' is PPV2 RGB/LUT-space diffusion with strong chroma damping to avoid hue speckling.")
    ap.add_argument("--print-width-mm", type=float, default=0.40, help="Physical printed road/head width in mm. Default 0.40 for the current 0.4 mm nozzle path.")
    ap.add_argument("--rp-pitch-mm", type=float, default=0.10, help="Physical size of one input/RP image pixel in mm. Default 0.10. Use 0.05 for a 2048 px image to print about 102.4 mm wide.")
    ap.add_argument("--edge-aa", choices=["off","on"], default="off", help="Enable 4x source edge-only subcell endpoint AA. Requires --print-width-mm/--rp-pitch-mm 4.")
    ap.add_argument("--edge-luma-thresh", type=float, default=28.0, help="4x edge-AA luma range threshold inside a 4x4 source block.")
    ap.add_argument("--edge-chroma-thresh", type=float, default=34.0, help="4x edge-AA RGB/chroma range threshold inside a 4x4 source block.")
    ap.add_argument("--edge-hue-thresh", type=float, default=25.0, help="4x edge-AA saturated hue range threshold inside a 4x4 source block.")
    ap.add_argument("--boundary-aa-structure-weight", choices=["on", "off"], default="on", help="Use local source detail to suppress boundary AA in smooth regions.")
    ap.add_argument("--boundary-aa-detail-threshold", type=float, default=8.0, help="RGB-detail value below which boundary AA gets minimum structure weight.")
    ap.add_argument("--boundary-aa-detail-full", type=float, default=28.0, help="RGB-detail value at/above which boundary AA gets full structure weight.")
    ap.add_argument("--boundary-aa-min-weight", type=float, default=0.15, help="Minimum gain multiplier for smooth areas when structure weighting is on.")
    ap.add_argument("--boundary-aa-cost", type=float, default=250.0, help="Fixed cost subtracted from each candidate boundary move after structure weighting.")
    ap.add_argument("--boundary-aa-cost-per-rp", type=float, default=0.0, help="Additional cost per affected RP pixel for candidate boundary moves.")
    ap.add_argument("--candidate-count", type=int, default=8, help="Candidate-aware recipe selection: query the nearest N LUT recipes per colour cell and prefer close candidates sharing layer/material symbols with left/up neighbours. Default 8 enables the adopted candidate-aware neighbour-sharing selection. Use 1 for strict nearest-colour selection.")
    ap.add_argument("--candidate-rgb-slack", type=float, default=2.5, help="Maximum extra RGB distance above nearest candidate allowed for neighbour-aware selection. Default 2.5.")
    ap.add_argument("--candidate-lab-slack", dest="candidate_rgb_slack", type=float, help=argparse.SUPPRESS)
    ap.add_argument("--candidate-neighbour-weight", type=float, default=0.25, help="RGB-distance credit per matching physical layer symbol against left/up neighbours. Default 0.25.")
    ap.add_argument("--candidate-choice", choices=["off", "scanline-neighbour"], default="off", help="PPV103: for old multi-candidate LUTs, choose one whole AP-cell candidate recipe before stack resorting using scanline predecessor continuity. Default off.")
    ap.add_argument("--candidate-choice-count", type=int, default=8, help="Maximum v59 stored candidates per RGB target to consider for --candidate-choice scanline-neighbour. Default 8.")
    ap.add_argument("--candidate-choice-max-extra-lab", type=float, default=2.0, help="Colour guard for multi-candidate choice: candidate Lab error may exceed the first/winner candidate by at most this amount. Default 2.0.")
    ap.add_argument("--candidate-choice-continuity-weight", type=float, default=1.0, help="Weight for scanline continuity matches during whole-cell candidate selection. Default 1.0.")
    ap.add_argument("--candidate-choice-score-weight", type=float, default=0.10, help="Penalty weight for extra v59 candidate score above the first/winner candidate during candidate selection. Default 0.10.")
    ap.add_argument("--lut-bucket-choice", choices=["prime", "rgb-best", "lab-best", "rgb-best-ve", "lab-best-ve", "direct-cloud-rgb", "direct-cloud-lab"], default="prime", help="3dprintv1.38: for lutmaker cloud-grid LUTs, choose candidate 0 (prime), nearest predicted RGB/RGB2 inside bucket (rgb-best), nearest CIE Lab/DeltaE76 inside bucket (lab-best), active-metric+VE tiebreak inside bucket (rgb-best-ve auto-follows Lab LUTs, or lab-best-ve explicitly), brute-force nearest RGB over full cloud, or brute-force nearest CIE Lab/DeltaE76 over full cloud.")
    ap.add_argument("--lut-bucket-choice-count", type=int, default=32, help="3dprintv1.4: number of stored bucket candidates to check for --lut-bucket-choice rgb-best/rgb-best-ve. Default 32.")
    ap.add_argument("--lut-bucket-colour-distance-mode", choices=["auto", "rgb2", "rgb", "lab"], default="auto", help="3dprintv1.38: active print-time bucket colour metric. auto follows explicit lab-* choices and lutmakerv4.7 colour_distance_mode=lab for *-best-ve; rgb/rgb2 uses RGB squared; lab uses CIE Lab DeltaE76.")
    ap.add_argument("--lut-bucket-rgb-best-ve-max-extra-rgb", type=float, default=4.0, help="For RGB-mode --lut-bucket-choice rgb-best-ve, allow VE/chromatic-depth preference only among candidates within this linear RGB distance of the bucket's best RGB match. In auto Lab mode this value is reused as the DeltaE76 guard unless --lut-bucket-best-ve-max-extra-colour-error is set. Default 4.0.")
    ap.add_argument("--lut-bucket-best-ve-max-extra-colour-error", type=float, default=None, help="Optional explicit active-colour guard for *-best-ve. In Lab mode this is DeltaE76; in RGB mode it is linear RGB distance. Default: use --lut-bucket-rgb-best-ve-max-extra-rgb.")
    ap.add_argument("--lut-bucket-rgb-best-ve-w-weight", type=float, default=0.35, help="For rgb-best-ve, penalty per W layer inside the RGB guard. Default 0.35.")
    ap.add_argument("--lut-bucket-rgb-best-ve-chroma-bonus", type=float, default=0.45, help="For rgb-best-ve, bonus per chromatic layer inside the RGB guard. Default 0.45.")
    ap.add_argument("--lut-bucket-rgb-best-ve-ve-bonus", type=float, default=0.35, help="For rgb-best-ve, bonus per sub-100%% chromatic layer inside the RGB guard. Default 0.35.")
    ap.add_argument("--lut-bucket-support2-weight", type=float, default=1.0, help="3dprintv1.38: multiplier for LUT support-distance2 penalty during rgb-best-ve/lab-best-ve bucket choice. With lutmakerv4.7, 1.0 uses the stored recipe-space support penalty as written; 0 disables.")
    ap.add_argument("--lut-candidate-rank", type=int, default=0, help="3dprintv1.3: prime/rank candidate slot used from the bucket when --lut-bucket-choice prime. Default 0.")
    ap.add_argument("--half-tone-policy", choices=["allow", "prefer-solid", "forbid"], default="allow", help="PPV111 diagnostic: leave LUT unchanged but alter PP-side v59 candidate selection. allow=current behaviour; prefer-solid=choose no-half candidate if within --half-tone-solid-max-extra-lab; forbid=use no-half candidate when present in stored candidates, reporting fallbacks. Default allow.")
    ap.add_argument("--half-tone-solid-max-extra-lab", type=float, default=2.0, help="For --half-tone-policy prefer-solid, maximum extra Lab above the first/winner candidate to switch to a no-half candidate. Default 2.0.")
    ap.add_argument("--stack-resort", choices=["off", "scanline-continuity"], default="off", help="PPV102: after stack-LUT AP recipe selection, reorder materials inside W-bounded sortable colour regions by walking each optical layer in the actual emitted scanline direction and swapping material+dose pairs only when a road continues without breaking another already-continuing road. Default off.")
    ap.add_argument("--stack-resort-max-permutations", type=int, default=720, help="Deprecated compatibility option; PPV102 scanline-continuity resorting does not enumerate whole-region permutations.")
    ap.add_argument("--stack-scheduler", choices=["off", "global-preference", "local-preference", "local-neighbour", "local-component"], default="off", help="Transparent stack scheduler. off preserves PPSPV14. global-preference uses one whole-image material layer preference. local-preference builds per-tile preferences. local-neighbour rewards left/up same-material slot continuity; local-component additionally rewards longer same-slot runs and penalises isolated token placement.")
    ap.add_argument("--stack-scheduler-local-tile-mm", type=float, default=STACK_SCHEDULER_LOCAL_TILE_MM, help="Tile size for --stack-scheduler local-preference/local-neighbour/local-component. Default 12 mm.")
    ap.add_argument("--stack-scheduler-local-blend-mm", type=float, default=STACK_SCHEDULER_LOCAL_BLEND_MM, help="Reserved soft-blend margin for local scheduler diagnostics/future smoothing. Default 4 mm; PPSPV33 does not use it to create geometry hard boundaries.")
    ap.add_argument("--stack-scheduler-neighbour-weight", type=float, default=STACK_SCHEDULER_NEIGHBOUR_WEIGHT, help="Slot-continuity reward for --stack-scheduler local-neighbour/local-component against left/up scheduled AP cells. Default 0.75.")
    ap.add_argument("--stack-scheduler-component-weight", type=float, default=STACK_SCHEDULER_COMPONENT_WEIGHT, help="PPSPV33 local-component extra reward for joining into longer left/up same-material same-slot runs. Default 1.25.")
    ap.add_argument("--stack-scheduler-island-penalty", type=float, default=STACK_SCHEDULER_ISLAND_PENALTY, help="PPSPV21 local-component penalty when a movable colour token has no left/up same-slot same-material neighbour. Default 0.50.")
    ap.add_argument("--scheduler-diagnostics-out", type=Path, default=None, help="Optional JSON sidecar with stack scheduler and pathing diagnostics.")
    ap.add_argument("--stack-scheduler-layer-order", default="B,C,R,Y,G", help="Comma-separated bottom-to-top material order used to lay out whole-image preferred colour zones for --stack-scheduler global-preference. Default B,C,R,Y,G.")
    ap.add_argument("--run-compact-max-extra-de", type=float, default=0.0, help="PPV109 optional bottom-up directional adjacent-token run compaction. 0 disables. If >0, a swap is accepted only when both affected cells remain within pre-run-compact DeltaE + this value and local run score improves. Default 0.")
    ap.add_argument("--run-compact-materials", default="R,Y,G,C,B", help="Comma-separated materials allowed to participate in --run-compact-max-extra-de swaps. Default R,Y,G,C,B. EMPTY and W are excluded by the implementation in this first version.")
    ap.add_argument("--close-gaps-mm", type=float, default=DEFAULT_CLOSE_GAPS_MM,
                    help="Merge same-material scanline spans separated by gaps up to this many mm before direct G-code emission. Default 0.0; use 0 to disable.")
    ap.add_argument("--z-hop-mode", choices=["off","on"], default="on",
                    help="PPSPV61: exact current-layer collision-safe travel. Default on. Use off only for diagnostics.")
    ap.add_argument("--ironing-layers", default=DEFAULT_IRONING_LAYERS,
                    help="PPSPV69 optional no-flow thermal ironing after selected optical layers. Off by default. Use comma list such as 2,4,6,8, or all/even/odd. Layer numbers are optical/direct logical layers 1..8.")
    ap.add_argument("--ironing-speed-mm-s", type=float, default=DEFAULT_IRONING_SPEED_MM_S,
                    help="No-flow ironing feed speed in mm/s. Default 40 mm/s.")
    ap.add_argument("--ironing-line-spacing-mm", type=float, default=DEFAULT_IRONING_LINE_SPACING_MM,
                    help="No-flow ironing line spacing in mm. Default 0.40 mm.")
    ap.add_argument("--ironing-pattern", choices=["layer", "x", "y", "xy"], default=DEFAULT_IRONING_PATTERN,
                    help="Ironing scan direction. layer=use normal layer orientation; x/y force one direction; xy does two crossed passes. Default layer.")
    ap.add_argument("--ironing-margin-mm", type=float, default=DEFAULT_IRONING_MARGIN_MM,
                    help="Inset ironing rectangle from image bbox by this many mm. Default 0.0.")
    ap.add_argument("--ironing-z-offset-mm", type=float, default=DEFAULT_IRONING_Z_OFFSET_MM,
                    help="Z offset for no-flow ironing relative to current layer Z. Default 0.0. This is mechanical only and has no recipe/LUT impact.")
    ap.add_argument("--endpoint-trim-mm", type=float, default=DEFAULT_ENDPOINT_TRIM_MM,
                    help="Endpoint-cap compensation for optical/model roads expressed as TOTAL road shortening. The value is split equally between the two true endpoints. Example: --endpoint-trim-mm 0.075 removes 0.0375 mm at each end. Default 0.025 mm total; use 0 to disable.")
    ap.add_argument("--min-trimmed-segment-mm", type=float, default=MIN_TRIMMED_SEGMENT_MM,
                    help="Minimum model-road extrusion length allowed after endpoint trimming. Shorter segments are skipped. Default 0.05 mm.")
    ap.add_argument("--direct-test-scanline-transition", choices=["reference-wipe", "legacy-chain"], default=DEFAULT_DIRECT_TEST_SCANLINE_TRANSITION,
                    help="Variable-height direct-card road transition path. reference-wipe is the historical compatibility name for the current direct per-road emitter; its v1.179 canonical default is +0.395 reprime, no backward wipe, stationary -0.400 retract 0.16 mm before the already-trimmed endpoint, then dry completion to the endpoint at 250 mm/s. Card print profiles may override this. legacy-chain retains the v1.67/v1.66 live-pressure experiments.")
    ap.add_argument("--direct-test-pressure-chain-scope", choices=["same-material", "v1.66-tile"], default=DEFAULT_DIRECT_TEST_PRESSURE_CHAIN_SCOPE,
                    help="Used only with --direct-test-scanline-transition legacy-chain. same-material uses one live pressure chain across all tiles/components/height groups of a material pass; v1.66-tile restores per-component/tile resets.")
    ap.add_argument("--raster-chain-max-travel-mm", type=float, default=DEFAULT_RASTER_CHAIN_MAX_TRAVEL_MM,
                    help="Maximum non-retracted travel distance allowed between chained raster scanlines in the PSP/base raster emitter. Default 3.0 mm.")
    ap.add_argument("--raster-gap-flow-max-mm", type=float, default=DEFAULT_RASTER_GAP_FLOW_MAX_MM,
                    help="Optional pressure-preserving low-flow extrusion through tiny gaps within a scanline. 0 disables. Default 0.0 mm; try 0.8 only for aggressive tests.")
    ap.add_argument("--raster-gap-flow-ratio", type=float, default=DEFAULT_RASTER_GAP_FLOW_RATIO,
                    help="Extrusion ratio for --raster-gap-flow-max-mm controlled gap-flow moves. Default 0.06.")
    ap.add_argument("--raster-gap-always-continue-mm", type=float, default=RASTER_GAP_ALWAYS_CONTINUE_MM,
                    help="Same-scanline non-extruding gap length that stays live/unretracted without collision-clear checking. Default 0.0 mm in PPSPV19; keep at 0 for quality-safe conditional-only continuation.")
    ap.add_argument("--raster-gap-conditional-continue-mm", type=float, default=RASTER_GAP_CONDITIONAL_CONTINUE_MM,
                    help="Same-scanline non-extruding gap length that may stay live/unretracted if the swept path is collision-clear. Default 1.5 mm. Use 10000 for the full-line experiment.")
    ap.add_argument("--directional-block-mm", type=float, default=0.0,
                    help="Enable experimental directional occupancy merging using this block size in mm. Use 3.2 for 8 x 0.40 mm roads. Default 0 disables this legacy directional merge helper.")
    ap.add_argument("--directional-join-gap-mm", type=float, default=DEFAULT_DIRECTIONAL_JOIN_GAP_MM,
                    help="Pre-trim same-line boundary gap allowed when deciding whether neighbouring directional blocks should merge. Default 0.10 mm.")
    ap.add_argument("--directional-join-threshold", type=int, default=DEFAULT_DIRECTIONAL_JOIN_THRESHOLD,
                    help="Number of raster lines across an 8-road block boundary that must join before neighbouring blocks merge. Default 3.")
    ap.add_argument("--extra-nozzle-cleaning", choices=["off", "toolchange"], default="off",
                    help="Add extra physical nozzle wipe/scrub after real material/tool changes without increasing purge volume. Uses Bambu G150.3/G150.1 wipe primitives validated in the reference template. Default off.")
    ap.add_argument("--extra-clean-repeats", type=int, default=0,
                    help="Number of extra nozzle wipe/scrub passes after each real toolchange when --extra-nozzle-cleaning=toolchange. Default 0. Use 0 to disable passes.")
    ap.add_argument("--extra-clean-command", default="G150.1 F18000",
                    help="Single G-code command used for each extra clean pass. Default G150.1 F18000, validated in the Bambu template nozzle-wipe section. Does not add purge/extrusion.")
    ap.add_argument("--swap-temperature-management", choices=["off", "template", "native"], default="native",
                    help="During H2C swaps, manage head temperatures. native uses Bambu Studio reference-aligned H2C thermal planning: target precondition, inactive S25 only on physical T0/T1 side changes, M620.15 P planner temp, and active hotend print-temp reassert; template preserves older template-extracted handling; off disables added M104 Tn temperature commands. Default native.")
    ap.add_argument("--material-polymer-map-json", default=None,
                    help="v1.117 per-logical-material polymer map, e.g. {\"B\":\"pla\"}. Unspecified materials remain PETG. Supported: petg, pla. Changes target temperature, cooling and optical E scaling; VE-to-gap height law remains v1.116.")
    ap.add_argument("--swap-cool-temp", type=int, default=25,
                    help="Low/off-style inactive hotend command used only when native mode crosses physical hotend sides T0<->T1. Default 25. Do not use 50: observed ~50 C is passive rest/coast-down, not a target.")
    ap.add_argument("--swap-print-temp", type=int, default=255,
                    help="Active hotend print temperature to reassert after M621 during swap. Default 255.")
    ap.add_argument("--build-plate", choices=["tex_plate", "eng_plate"], default=DEFAULT_BUILD_PLATE,
                    help="H2C build-plate profile. tex_plate (default) emits Textured PEI metadata, M972 S26, and G29.1 Z-0.02 for the fixed 0.4 mm nozzle. eng_plate preserves the former Engineering Plate metadata, M972 S36 ... X1, and 0.00 startup trim.")
    ap.add_argument("--bed-temperature", type=int, default=70,
                    help="Typed H2C startup first-layer bed temperature in C. Default 70, matching the proven PETG reference.")
    ap.add_argument("--swap-precondition-temp", type=int, default=215,
                    help="PPSPV7.0 native mode: staged target-hotend precondition temperature before the H2C M620.10/M620.15 swap block. Default 215.")
    ap.add_argument("--h2c-standby-temp", type=int, default=215,
                    help="Native mode: H2C M620.15 P planner/pre-cooling temperature used during swaps. Default 215, matching the Bambu Studio H2C reference for this PETG workflow.")
    ap.add_argument("--h2c-thermal-planner-guards", choices=["off", "on"], default="on",
                    help="PPSPV7.0 native mode: wrap target-hotend preconditioning in Bambu-style M632/M633 planner guards. Default on.")
    ap.add_argument("--h2c-w-hotend-index", type=int, choices=[0, 1], default=1,
                    help="3dprintv1.29 native mode: M104/SYNC temperature target index used for W/left hotend. Default 1 because physical H2C testing showed M104 T1 heats the left/W head and M104 T0 heats the right/RGBYC head. Raw T-tool selection is unchanged.")
    ap.add_argument("--h2c-toolchange-lift-mm", type=float, default=3.0,
                    help="PPSPV58+: explicit Z lift added before the H2C M620.14/M620.10/M620.11 toolchange macro block. This is independent of normal travel z-hop. Default 3.0 mm above current layer.")
    ap.add_argument("--h2c-machine-prime-xy-mode", choices=["material-row", "tower-slot", "tower-center", "template"], default="material-row",
                    help="v1.156: choose XY passed to Bambu M620.14 staging command. material-row keeps the stable material-band Y while placing X 2 mm outside the tower entry edge; tower-slot follows the scheduled slot Y with the same outside X; tower-center uses tower-centre Y with outside X; template preserves the embedded template location. Default material-row.")

    ap.add_argument("--material-order", choices=["canonical", "stability-score"], default="canonical", help="Legacy per-layer material print order switch. canonical keeps runtime active order. stability-score is preserved for compatibility but --material-draw-order-mode is preferred in PPSPV57.")
    ap.add_argument("--material-draw-order-mode", choices=["fixed", "stability-score", "carryover"], default="fixed", help="PPSPV57 per-layer material draw-order scheduler. fixed preserves PPSPV56 order; stability-score sorts broad/stable roads first; carryover starts a layer with the previous layer's final material when present. Default fixed.")
    ap.add_argument("--skip-absent-layer-materials", choices=["off", "on"], default="off", help="PPSPV57: when on, omit materials that have no model roads on the current optical layer. Use with --tower-slot-mode dynamic and --tower-fill-unused-slots on to keep tower shape. Default off for PPSPV56 compatibility.")
    ap.add_argument("--tower-slot-mode", choices=["fixed", "dynamic"], default="fixed", help="PPSPV57 prime tower slot assignment. fixed keeps material-derived tower bands; dynamic treats the tower as physical slots filled by this layer's actual draw order. Default fixed.")
    ap.add_argument("--tower-fill-unused-slots", choices=["off", "on"], default="off", help="PPSPV57 dynamic tower option: fill unused tower slots with the final active material at full-speed filler feed, avoiding extra swaps while preserving tower topography. Default off.")
    ap.add_argument("--tower-fill-material", choices=["last"], default="last", help="PPSPV57 dynamic tower filler material policy. Only 'last' is currently supported: use the final active material on that layer.")
    ap.add_argument("--add-corner-colour-tiles", action="store_true", help="Add five pure colour reference tiles in every image corner before compiling: top row R/G/B and bottom row C/Y. The source image file is not modified.")
    ap.add_argument("--corner-tile-size-px", type=int, default=56, help="Corner colour tile size in native image/print pixels. Default: 56 px = 5.04 mm, nearest integer-pixel approximation to 5 mm.")
    ap.add_argument("--corner-tile-margin-px", type=int, default=32, help="Inset margin for corner colour tiles in native pixels. Default: 32 px = 2.88 mm.")
    _config_report = _fc3d_load_config_defaults(ap, pre_args.config)
    args=ap.parse_args()

    global RUNTIME_MATERIAL_POLYMER, RUNTIME_MATERIAL_COLOUR_HEX, RUNTIME_MATERIAL_PHYSICAL_COLOUR
    RUNTIME_MATERIAL_POLYMER = {m:"petg" for m in ("W","F","R","Y","G","C","B")}
    RUNTIME_MATERIAL_COLOUR_HEX = dict(FILAMENT_COLOURS)
    RUNTIME_MATERIAL_PHYSICAL_COLOUR = {m:m for m in FILAMENT_COLOURS}
    if args.material_polymer_map_json:
        try:
            _poly_raw = dict(json.loads(args.material_polymer_map_json))
        except Exception as exc:
            raise SystemExit(f"Invalid --material-polymer-map-json: {exc}") from exc
        for _mat,_poly in _poly_raw.items():
            _m = str(_mat).upper(); _p = str(_poly).lower()
            if _m not in RUNTIME_MATERIAL_POLYMER:
                raise SystemExit(f"Unknown FC3D logical material in --material-polymer-map-json: {_m}")
            if _p not in POLYMER_PROFILES:
                raise SystemExit(f"Unsupported polymer profile {_p!r}; choose petg or pla")
            RUNTIME_MATERIAL_POLYMER[_m] = _p

    # v1.118 friendly installed-filament assignment. This is evaluated after
    # --material-polymer-map-json so an explicit assignment is authoritative
    # for both polymer profile and physical spool position.
    _friendly_tool_overrides = {}
    if args.filament_assignment_json:
        try:
            _fa_raw = dict(json.loads(args.filament_assignment_json))
        except Exception as exc:
            raise SystemExit(f"Invalid --filament-assignment-json: {exc}") from exc
        for _mat, _assignment in _fa_raw.items():
            _m = str(_mat).upper()
            if _m not in RUNTIME_MATERIAL_POLYMER:
                raise SystemExit(f"Unknown FC3D logical material in --filament-assignment-json: {_m}")
            try:
                _p, _physical_colour, _raw_tool = parse_filament_assignment(_assignment)
            except Exception as exc:
                raise SystemExit(f"Invalid filament assignment for {_m}: {exc}") from exc
            RUNTIME_MATERIAL_POLYMER[_m] = _p
            RUNTIME_MATERIAL_PHYSICAL_COLOUR[_m] = _physical_colour
            RUNTIME_MATERIAL_COLOUR_HEX[_m] = PHYSICAL_FILAMENT_COLOURS[_physical_colour]
            _friendly_tool_overrides[_m] = int(_raw_tool)
            print(f"FC3D filament assignment: logical {_m} -> {_p.upper()} {_physical_colour} at position {_raw_tool+1} colour={RUNTIME_MATERIAL_COLOUR_HEX[_m]}", flush=True)
    _resolve_card_direct_layer_input(args)
    if getattr(args, "layer_manifest_out", None) is not None and getattr(args, "aa_layer_image_prefix", None) is None:
        args.aa_layer_image_prefix = Path(args.layer_manifest_out).with_suffix("")
    globals()["PRINT_PROVENANCE_CONTEXT"] = _prepare_print_provenance(args)
    _write_resolved_config(args, ap, _config_report)

    if getattr(args, "pure_grid_mode", "off") == "on":
        # Diagnostic isolation: keep local tiling, disable every optional
        # path/recipe continuity modification that could mask or create the
        # tile-boundary defect.  The emitted model paths are simply tile-clipped
        # and independently emitted.
        args.candidate_choice = "off"
        args.candidate_choice_count = 1
        args.candidate_choice_max_extra_lab = 0.0
        args.candidate_choice_continuity_weight = 0.0
        args.candidate_choice_score_weight = 0.0
        args.lut_bucket_choice = "prime"
        args.lut_bucket_choice_count = 1
        args.lut_candidate_rank = 0
        args.stack_resort = "off"
        args.run_compact_max_extra_de = 0.0
        args.close_gaps_mm = 0.0
        args.endpoint_trim_mm = 0.0
        args.raster_gap_always_continue_mm = 0.0
        args.raster_gap_conditional_continue_mm = 0.0
        args.raster_gap_flow_max_mm = 0.0
        args.directional_block_mm = 0.0
        args.directional_join_gap_mm = 0.0
        args.half_tone_policy = "allow"

    global RUNTIME_PROGRESS, RUNTIME_PROGRESS_INTERVAL_SEC, RUNTIME_CALIBRATION_PARAMS_FILE
    RUNTIME_PROGRESS = str(getattr(args, "progress", "auto"))
    RUNTIME_PROGRESS_INTERVAL_SEC = float(getattr(args, "progress_interval_sec", 2.0))
    RUNTIME_CALIBRATION_PARAMS_FILE = str(args.calibration_params_file) if getattr(args, "calibration_params_file", None) is not None else None
    if getattr(args, "pp_refit_stack_preview_out", None) is not None:
        raise RuntimeError("3dprintv1.8 clean path removed --pp-refit-stack-preview-out and the stage-3 final-emission stack preview.")
    globals()["RUNTIME_PREVIEW_WHITE_EXPAND"] = str(getattr(args, "preview_white_expand", "on"))
    globals()["RUNTIME_DIRECT_LAYER_PREVIEW_MODE"] = str(getattr(args, "direct_layer_preview_mode", "diagnostic"))
    globals()["RUNTIME_DIRECT_LAYER_REVERSE_RGB_CSV"] = str(getattr(args, "direct_layer_reverse_rgb_csv", "") or "")
    globals()["RUNTIME_DIRECT_LAYER_CARD_MANIFEST_CSV"] = str(getattr(args, "direct_layer_card_manifest_csv", "") or "")
    globals()["RUNTIME_DIRECT_LAYER_REVERSE_LOOKUP_MISSING_POLICY"] = str(getattr(args, "direct_layer_reverse_lookup_missing_policy", "fail") or "fail")
    globals()["RUNTIME_DIRECT_LAYER_REVERSE_AUDIT_TOLERANCE_RGB"] = float(getattr(args, "direct_layer_reverse_audit_tolerance_rgb", 1.0) or 1.0)
    globals()["RUNTIME_DIRECT_LAYER_REVERSE_AUDIT_FAIL"] = str(getattr(args, "direct_layer_reverse_audit_fail", "on") or "on")
    globals()["RUNTIME_DIRECT_LAYER_LAYOUT"] = str(getattr(args, "direct_layout", "4x2") or "4x2")
    globals()["RUNTIME_STACK_PREVIEW_OUT"] = getattr(args, "stack_preview_out", None)
    globals()["RUNTIME_DISPLAY_STACK_PREVIEW_OUT"] = getattr(args, "display_stack_preview_out", None)
    globals()["RUNTIME_LUT_STACK_DIFF_OUT"] = getattr(args, "lut_stack_diff_out", None)
    globals()["RUNTIME_PP_REFIT_STACK_PREVIEW_OUT"] = None
    globals()["RUNTIME_LUT_STACK_DEBUG_JSON"] = getattr(args, "lut_stack_debug_json", None)

    direct_layer_mode = (args.direct_layer_images is not None)
    paired_filter_mode = bool(direct_layer_mode and str(getattr(args, "direct_layout", "4x2")) == "4x4")
    # In a 4x4 variable-height direct job the pass/material role is the mode:
    # normal chromatic = Z offset, normal W = carrier, paired pass = filter.
    # No card name, id or global card-wide geometry switch participates.
    direct_operation_geometry = bool(paired_filter_mode)
    globals()["RUNTIME_DIRECT_OPERATION_GEOMETRY"] = direct_operation_geometry
    if args.image is None and not direct_layer_mode:
        raise RuntimeError("--image is required unless --direct-layer-images is supplied")
    if direct_layer_mode:
        # Direct stacks already define material per layer. Disable all front-end
        # image-to-recipe systems so only the shared pp backend remains active.
        args.error_diffusion = "none"
        args.edge_aa = "off"
        args.candidate_count = 1
        args.candidate_neighbour_weight = 0.0
        args.add_corner_colour_tiles = False
    if paired_filter_mode:
        unsupported_outputs = [
            name for name in (
                "layer_manifest_out",
                "calibration_manifest_out",
                "printed_tile_recipes_out",
                "aa_layer_image_prefix",
                "aa_stack_npz_out",
                "geometry_3mf_out",
            )
            if getattr(args, name, None) is not None
        ]
        if unsupported_outputs:
            raise RuntimeError(
                "--dl 4x4 cannot write legacy eight-slot stack/provenance outputs yet: "
                + ", ".join("--" + name.replace("_", "-") for name in unsupported_outputs)
            )
        if bool(getattr(args, "debug_package", False)):
            raise RuntimeError("--dl 4x4 cannot use the legacy eight-slot --debug-package yet")
        if str(getattr(args, "direct_layer_preview_mode", "diagnostic")) != "diagnostic":
            raise RuntimeError("--dl 4x4 currently supports only --direct-layer-preview-mode diagnostic")
        if (
            str(getattr(args, "material_draw_order_mode", "fixed")) != "fixed"
            or str(getattr(args, "skip_absent_layer_materials", "off")) != "off"
            or str(getattr(args, "tower_slot_mode", "fixed")) != "fixed"
            or str(getattr(args, "tower_fill_unused_slots", "off")) != "off"
        ):
            raise RuntimeError(
                "--dl 4x4 currently requires the stable paired-pass tower settings: "
                "--material-draw-order-mode fixed --skip-absent-layer-materials off "
                "--tower-slot-mode fixed --tower-fill-unused-slots off"
            )
    audit_reference_head_metadata(args.template_gcode_3mf)
    global Z_HOP_MODE
    Z_HOP_MODE = args.z_hop_mode
    if float(args.rp_pitch_mm) <= 0:
        raise RuntimeError("--rp-pitch-mm must be greater than zero")
    if float(args.print_width_mm) <= 0:
        raise RuntimeError("--print-width-mm must be greater than zero")
    globals()["RUNTIME_RP_PITCH_MM"] = float(args.rp_pitch_mm)
    globals()["RUNTIME_PRINT_WIDTH_MM"] = float(args.print_width_mm)
    try:
        globals()["RUNTIME_PIXEL_HEAD_WIDTH"] = derive_pixel_head_width(
            globals()["RUNTIME_RP_PITCH_MM"], globals()["RUNTIME_PRINT_WIDTH_MM"]
        )
    except ValueError as exc:
        raise RuntimeError(str(exc)) from exc
    print(
        f"RP pitch: {globals()['RUNTIME_RP_PITCH_MM']:.4f} mm/source pixel; "
        f"print width: {globals()['RUNTIME_PRINT_WIDTH_MM']:.4f} mm; "
        f"pixel_head_width: {globals()['RUNTIME_PIXEL_HEAD_WIDTH']} RP",
        flush=True,
    )
    globals()["RUNTIME_DEBUG_PACKAGE"] = bool(args.debug_package)
    globals()["RUNTIME_LOOKUP_SPACE"] = "rgb"
    globals()["RUNTIME_MAX_PHYSICAL_SLOTS"] = int(args.max_physical_slots)
    globals()["RUNTIME_STRUCTURAL_FILL_MODE"] = DEFAULT_STRUCTURAL_FILL_MODE
    globals()["RUNTIME_STRUCTURAL_FILL_DOSE"] = DEFAULT_STRUCTURAL_FILL_DOSE
    globals()["RUNTIME_STRUCTURAL_FILL_MATERIAL"] = DEFAULT_STRUCTURAL_FILL_MATERIAL
    globals()["RUNTIME_CANDIDATE_CHOICE"] = str(getattr(args, "candidate_choice", "off"))
